// ---- left4sol raw-build resolver ------------------------------------------
// itch's raw playable URL (html-classic.itch.zone/html/<upload>-<build>/...)
// changes id on every game push. Resolve the current one from the embed page
// server-side and cache briefly; phones must land on the raw page because the
// embed wrapper has no mobile viewport.
// R2 fast lane: latest.txt holds the live build folder (e.g. "v2.4.35"),
// written atomically AFTER all build files upload. 60s cache keeps origin
// load nil while updates still appear within a minute of deploy.
// play.left4sol.com attached to the bucket 2026-08-16 — first-party asset
// domain (AV reputation + no r2.dev rate limits). r2.dev remains valid.
const LEFT4SOL_R2_BASE = "https://play.left4sol.com";
let left4solR2Cache = { url: null, fetchedAt: 0 };
async function resolveLeft4SolR2Url() {
  const now = Date.now();
  if (left4solR2Cache.fetchedAt && now - left4solR2Cache.fetchedAt < 60 * 1000)
    return left4solR2Cache.url;
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 4000);
    const res = await fetch(`${LEFT4SOL_R2_BASE}/latest.txt?t=${now}`, { signal: controller.signal });
    clearTimeout(timeout);
    if (res.ok) {
      const version = (await res.text()).trim();
      left4solR2Cache = {
        url: /^v[\w.\-]+$/.test(version) ? `${LEFT4SOL_R2_BASE}/${version}/index.html` : null,
        fetchedAt: now,
      };
      return left4solR2Cache.url;
    }
  } catch (error) {
    console.error("left4sol r2 resolve failed:", error?.message || error);
  }
  left4solR2Cache.fetchedAt = now; // negative-cache failures too
  return left4solR2Cache.url;
}

// First-party page serve (2026-08-16): ESET and friends began blanket-
// flagging *.r2.dev with fake-captcha URL heuristics (the shared free
// domain is heavily abused by actual scammers) and BLOCKED the redirect
// target for players. Serving the index.html from THIS origin keeps the
// address bar on slimewire while a <base> tag resolves every relative
// asset URL (loader/data/wasm/StreamingAssets) against the R2 folder, so
// the multi-hundred-MB payload still rides Cloudflare, not this dyno.
// Cache is per-version: a build's page is immutable once published.
let left4solPageCache = { sourceUrl: null, html: null };
async function fetchLeft4SolPageHtml(indexUrl) {
  if (left4solPageCache.sourceUrl === indexUrl && left4solPageCache.html)
    return left4solPageCache.html;
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6000);
    const res = await fetch(indexUrl, { signal: controller.signal });
    clearTimeout(timeout);
    if (!res.ok) return null;
    let html = await res.text();
    const baseDir = indexUrl.replace(/index\.html.*$/, "");
    // OG/Twitter tags make pasted links unfurl with real key art instead of a
    // bare URL — bare links read as scams. Canonical is the short domain.
    const ogTags =
      `<meta property="og:title" content="LEFT4SOL — Zombie Survival">`
      + `<meta property="og:description" content="Survive the horde. Ten-chapter campaign, endless survival, bank heists and Death Karts — free in your browser, Windows download available.">`
      + `<meta property="og:image" content="${LEFT4SOL_R2_BASE}/site/left4sol-og.jpg">`
      + `<meta property="og:url" content="https://left4sol.com/">`
      + `<meta property="og:type" content="website">`
      + `<meta name="twitter:card" content="summary_large_image">`
      + `<meta name="description" content="LEFT4SOL — free browser zombie survival with a ten-chapter campaign, co-op, heists and kart racing.">`;
    html = html.replace(/<head([^>]*)>/i, `<head$1><base href="${baseDir}">${ogTags}`);
    // Unity's loader resolves streamingAssetsUrl against document.URL and
    // IGNORES the <base> tag - so on this origin the runtime fetched
    // left4sol.com/StreamingAssets/UnityServicesProjectConfiguration.json,
    // got this portal's HTML back, and Unity Services (auth/relay/co-op)
    // never initialized for any web player ("co-op doesn't seem to be
    // online for users to join", owner 2026-08-24). Absolute URL fixes it.
    html = html.replace(
      /streamingAssetsUrl:\s*"StreamingAssets"/,
      `streamingAssetsUrl: "${baseDir}StreamingAssets"`);
    left4solPageCache = { sourceUrl: indexUrl, html };
    return html;
  } catch (error) {
    console.error("left4sol page fetch failed:", error?.message || error);
    return null;
  }
}

// Windows tester-build pointer: downloads/windows-latest.txt holds the zip
// filename, written AFTER the zip finishes uploading (same atomic-pointer
// pattern as latest.txt). 5-min cache — downloads are not latency-critical.
let left4solDownloadCache = { name: null, fetchedAt: 0 };
async function resolveLeft4SolDownloadZip() {
  const now = Date.now();
  if (left4solDownloadCache.fetchedAt && now - left4solDownloadCache.fetchedAt < 5 * 60 * 1000)
    return left4solDownloadCache.name;
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 4000);
    const res = await fetch(`${LEFT4SOL_R2_BASE}/downloads/windows-latest.txt?t=${now}`,
      { signal: controller.signal });
    clearTimeout(timeout);
    if (res.ok) {
      const name = (await res.text()).trim();
      left4solDownloadCache = {
        name: /^[\w.\-]+\.zip$/.test(name) ? name : null,
        fetchedAt: now,
      };
      return left4solDownloadCache.name;
    }
  } catch (error) {
    console.error("left4sol download resolve failed:", error?.message || error);
  }
  left4solDownloadCache.fetchedAt = now; // negative-cache failures too
  return left4solDownloadCache.name;
}

let left4solRawUrlCache = { url: null, fetchedAt: 0 };
async function resolveLeft4SolRawUrl() {
  const CACHE_MS = 5 * 60 * 1000;
  const now = Date.now();
  if (left4solRawUrlCache.url && now - left4solRawUrlCache.fetchedAt < CACHE_MS)
    return left4solRawUrlCache.url;
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6000);
    const headers = { "User-Agent": "Mozilla/5.0 (compatible; SlimeWire game portal)" };
    const page = await fetch("https://itch.io/embed-upload/18456748", {
      signal: controller.signal, headers,
    });
    let body = await page.text();
    // The URL appears both escaped (\/) inside JSON and plain in the iframe.
    const rawPattern =
      /html-classic\.itch\.zone(?:\\\/|\/)html(?:\\\/|\/)(18456748-\d+)(?:\\\/|\/)index\.html\?v=(\d+)/;
    let match = body.match(rawPattern);
    if (!match) {
      // 2026-08: itch stopped inlining the raw URL on the first page; it now
      // links a signed variant (18456748?sig=...) whose page still carries it.
      const signed = body.match(/18456748\?sig=[^"'&\s\\]+/);
      if (signed) {
        const second = await fetch(
          `https://itch.io/embed-upload/${signed[0]}`, { signal: controller.signal, headers });
        body = await second.text();
        match = body.match(rawPattern);
      }
    }
    clearTimeout(timeout);
    if (match) {
      left4solRawUrlCache = {
        url: `https://html-classic.itch.zone/html/${match[1]}/index.html?v=${match[2]}`,
        fetchedAt: now,
      };
      return left4solRawUrlCache.url;
    }
  } catch (error) {
    console.error("left4sol raw url resolve failed:", error?.message || error);
  }
  // Serve the last known-good raw URL over the desktop-shell fallback.
  return left4solRawUrlCache.url;
}
const DEFAULT_MANUAL_LAUNCH_SCAN_INTERVAL_MS = 1500;
const OGRE_AI_SCAN_BATCH_SIZE = 16;
const OGRE_AI_SCAN_BATCH_DELAY_MS = 120;
const OGRE_AI_MAX_SCAN_ROWS = 140;
