// --- Subscription access (pay SOL to receive wallet -> 30 days) ----------------
async function readAutopilotSubs() {
  try {
    const j = await readJson(AUTOPILOT_SUBS_FILE).catch(() => null);
    return (j && j.subs && typeof j.subs === "object") ? j : { subs: {} };
  } catch { return { subs: {} }; }
}
async function autopilotSubActive(userId) {
  if (!userId) return false;
  const store = await readAutopilotSubs();
  const exp = Date.parse(store.subs[userId]?.expiresAt || "");
  return Number.isFinite(exp) && exp > Date.now();
}
async function grantAutopilotSub(userId, days = CONFIG.subDays) {
  // Lock the subs-file read-modify-write so a concurrent grant/trial write can't clobber it.
  const granted = await withFileLock(AUTOPILOT_SUBS_FILE, async () => {
    const store = await readAutopilotSubs();
    const cur = Date.parse(store.subs[userId]?.expiresAt || "");
    const base = Number.isFinite(cur) && cur > Date.now() ? cur : Date.now();
    const expiresAt = new Date(base + days * 24 * 60 * 60 * 1000).toISOString();
    store.subs[userId] = { ...(store.subs[userId] || {}), expiresAt, grantedAt: new Date().toISOString() };
    await writeJsonFile(AUTOPILOT_SUBS_FILE, store);
    return store.subs[userId];
  });
  // Make sure a savable access key exists the moment they're paid up.
  try { await autopilotAccessKeyFor(userId); } catch {}
  return granted;
}
// Each subscriber gets a unique deposit address (a managed wallet) so payments
// attribute cleanly. Paying the monthly price there auto-unlocks 30 days and the
// SOL is swept to the owner's receive wallet.
const SUB_DEPOSIT_OWNER = "__sub_deposits__";
async function getSubDepositWallet(userId) {
  const label = `subdep:${userId}`;
  const existing = (await readWalletStore()).wallets.find((x) => String(x.ownerId) === SUB_DEPOSIT_OWNER && x.label === label);
  if (existing) return existing;
  // Create under the wallet-store lock with a re-check, so two concurrent first-time callers can't each
  // push a deposit wallet (one of which would then be dropped by the lost-update race).
  return mutateWalletStore((store) => {
    let w = store.wallets.find((x) => String(x.ownerId) === SUB_DEPOSIT_OWNER && x.label === label);
    if (!w) {
      const kp = Keypair.generate();
      w = walletRecord(label, kp, SUB_DEPOSIT_OWNER);
      store.wallets.push(w);
    }
    return w;
  });
}
let subWatcherRunning = false;
// deposit pubkey -> lamports we've already GRANTED access for. A failed/lagging sweep leaves the balance
// sitting above threshold; without this it re-triggered a grant every tick and stacked free 30-day
// extensions. Cleared once a sweep clears the wallet, so a genuine NEW deposit can grant again.
const subDepositGrantLedger = new Map();
async function checkSubscriptionPayments() {
  if (!CONFIG.subEnabled || !(CONFIG.subPriceSol > 0)) return;
  if (subWatcherRunning) return;   // re-entrancy guard: a slow tick must not overlap the next 60s tick
  subWatcherRunning = true;
  try {
    let receive;
    try { receive = new PublicKey(CONFIG.subReceiveWallet); } catch { return; }
    const store = await readWalletStore();
    const deposits = store.wallets.filter((x) => String(x.ownerId) === SUB_DEPOSIT_OWNER);
    const thresholdLamports = Math.round(CONFIG.subPriceSol * 0.98 * 1_000_000_000);
    for (const w of deposits) {
      try {
        const balLamports = Number(await getSolBalanceCached(new PublicKey(w.publicKey), { force: true }));
        if (balLamports >= thresholdLamports) {
          const userId = w.label.replace(/^subdep:/, "");
          // Grant once per payment: only when the balance is at least one FULL price above what we've
          // already credited (a stuck/dust balance can't re-trigger; a real second deposit still does).
          const grantedFor = subDepositGrantLedger.get(w.publicKey) || 0;
          if (balLamports - grantedFor >= thresholdLamports) {
            await grantAutopilotSub(userId, CONFIG.subDays);
            subDepositGrantLedger.set(w.publicKey, balLamports);
            console.log(`[subs] payment ${(balLamports / 1e9).toFixed(4)} SOL -> unlocked ${userId} for ${CONFIG.subDays}d`);
          }
          try {
            const kp = decryptWallet(w);
            await drainSolFromWallet(kp, receive);
            invalidateWalletReadCache(w.publicKey);
            subDepositGrantLedger.delete(w.publicKey);   // swept clean → a fresh deposit can grant again
          } catch (e) { console.warn(`[subs] sweep failed for ${userId}: ${e && e.message}`); }
        }
      } catch {}
    }
  } finally {
    subWatcherRunning = false;
  }
}
function startSubscriptionWatcher() {
  if (!CONFIG.subEnabled) return;
  setInterval(() => { void checkSubscriptionPayments(); }, 60_000);
}

// --- Temporary access (owner-minted 1-hour trial codes) -----------------------
// The owner mints a code from their panel and hands it to a person. The person
// redeems it (while logged in) and gets a budget of *active running time* (default
// 60 min). Usage only ticks while THEIR autopilot session is actually running.
// When the budget is exhausted the engine auto-stops (flattening every position
// back to SOL) and the /pro app offers them: withdraw their SOL to any wallet, or
// pay to unlock a full subscription. One engine runs at a time, so the running
// controller's clock is unambiguous.
function newTrialCode() {
  return crypto.randomBytes(4).toString("hex").toUpperCase(); // e.g. "9F3A2C71"
}
async function autopilotTrialState(userId) {
  if (!userId) return null;
  const store = await readAutopilotSubs();
  return (store.trials && store.trials[userId]) || null;
}
function trialIsActive(t) {
  return Boolean(t) && !t.expiredAt && Number(t.secondsUsed || 0) < Number(t.capSeconds || 0);
}
async function autopilotTrialActive(userId) {
  return trialIsActive(await autopilotTrialState(userId));
}
async function createTrialCode(capMinutes = CONFIG.subTrialMinutes) {
  const store = await readAutopilotSubs();
  if (!store.trialCodes) store.trialCodes = {};
  const cap = Math.max(1, Math.min(Number(capMinutes) || CONFIG.subTrialMinutes, 1440));
  let code = newTrialCode();
  while (store.trialCodes[code]) code = newTrialCode();
  store.trialCodes[code] = { capSeconds: cap * 60, createdAt: new Date().toISOString(), redeemedBy: null, redeemedAt: null };
  await writeJsonFile(AUTOPILOT_SUBS_FILE, store);
  return { code, capSeconds: cap * 60, capMinutes: cap };
}
async function redeemTrialCode(userId, codeRaw) {
  const code = String(codeRaw || "").trim().toUpperCase();
  if (!code) throw new Error("Enter an access code.");
  const store = await readAutopilotSubs();
  if (!store.trials) store.trials = {};
  if (!store.trialCodes) store.trialCodes = {};
  const c = store.trialCodes[code];
  if (!c) throw new Error("That code isn't valid.");
  if (c.redeemedBy && c.redeemedBy !== userId) throw new Error("That code has already been used.");
  const existing = store.trials[userId];
  if (trialIsActive(existing)) return existing; // already on a live trial; no double-spend
  c.redeemedBy = userId; c.redeemedAt = new Date().toISOString();
  store.trials[userId] = { capSeconds: c.capSeconds, secondsUsed: 0, grantedAt: new Date().toISOString(), code, expiredAt: null };
  await writeJsonFile(AUTOPILOT_SUBS_FILE, store);
  return store.trials[userId];
}
async function accrueTrialUsage(userId, seconds) {
  if (!userId || !(seconds > 0)) return autopilotTrialState(userId);
  const store = await readAutopilotSubs();
  const t = store.trials && store.trials[userId];
  if (!t || t.expiredAt) return t || null;
  t.secondsUsed = Math.min(Number(t.capSeconds || 0), Number(t.secondsUsed || 0) + seconds);
  if (t.secondsUsed >= Number(t.capSeconds || 0)) t.expiredAt = t.expiredAt || new Date().toISOString();
  await writeJsonFile(AUTOPILOT_SUBS_FILE, store);
  return t;
}

// Which logged-in user owns the currently running engine, and whether their clock
// is a metered trial. Set when a session starts; consumed by the trial watcher.
let autopilotRunController = null; // { userId, isTrial, lastAccrueAt }
async function tickTrialUsage() {
  const c = autopilotRunController;
  if (!c || !c.isTrial) return;
  const now = Date.now();
  const delta = Math.max(0, (now - c.lastAccrueAt) / 1000);
  c.lastAccrueAt = now;
  let running = false;
  try { running = Boolean(autopilotEngine.status()?.running); } catch {}
  if (delta > 0) {
    const t = await accrueTrialUsage(c.userId, delta);
    if (t && (t.expiredAt || Number(t.secondsUsed) >= Number(t.capSeconds))) {
      try { await autopilotEngine.stop("trial_expired"); } catch {}
      console.log(`[trial] ${c.userId} used full ${Math.round((t.capSeconds || 0) / 60)}m budget -> auto-stopped & flattened to SOL`);
      autopilotRunController = null;
      return;
    }
  }
  if (!running) autopilotRunController = null; // they stopped; final delta already counted
}
function startTrialUsageWatcher() {
  setInterval(() => { void tickTrialUsage().catch(() => {}); }, 10_000);
}

// --- KEY-BASED ACCESS (decoupled from site logins) ---------------------------
// The autopilot is almost a standalone product: people come here just for this.
// So access is by KEY, not by remembering a site login. The OWNER key is the
// owner's login and always maps to one stable identity (so wallets persist on any
// device). Paying users get a savable/downloadable access key bound to their
// account — losing a site login never loses paid access; the key restores it.
const AUTOPILOT_OWNER_USERID = "__owner__";
async function autopilotResolveKey(keyRaw) {
  const k = String(keyRaw || "").trim();
  if (!k) return null;
  if (CONFIG.autopilotOwnerKey && k === CONFIG.autopilotOwnerKey) return { userId: AUTOPILOT_OWNER_USERID, owner: true };
  if (CONFIG.autopilotControlKey && k === CONFIG.autopilotControlKey) return { userId: AUTOPILOT_OWNER_USERID, owner: true };
  const store = await readAutopilotSubs();
  const uid = store.accessKeys && store.accessKeys[k];
  return uid ? { userId: uid, owner: false } : null;
}
async function autopilotAccessKeyFor(userId) {
  if (!userId) return null;
  const store = await readAutopilotSubs();
  if (!store.accessKeys) store.accessKeys = {};
  if (!store.userKeys) store.userKeys = {};
  const existing = store.userKeys[userId];
  if (existing && store.accessKeys[existing] === userId) return existing;
  const key = "swa_" + crypto.randomBytes(20).toString("hex");
  store.accessKeys[key] = userId; store.userKeys[userId] = key;
  await writeJsonFile(AUTOPILOT_SUBS_FILE, store);
  return key;
}

// Owner = holds the owner key (provided directly, OR is signed in as the stable
// owner identity via key-login). Before any owner key is set, any session is owner.
function autopilotIsOwner(providedKey, webAuth) {
  // Owner ONLY = signed in as the stable owner identity (key-login) OR presenting the
  // exact owner/control key. FAIL CLOSED: if no owner key is configured we trust NOBODY
  // (previously any logged-in session was treated as owner — that leaked paper mode,
  // logs, and strategy to ordinary users). The owner key is required to be set in prod.
  if (webAuth && webAuth.userId === AUTOPILOT_OWNER_USERID) return true;
  if (CONFIG.autopilotOwnerKey && providedKey === CONFIG.autopilotOwnerKey) return true;
  if (CONFIG.autopilotControlKey && providedKey === CONFIG.autopilotControlKey) return true;
  return false;
}
// Strip the owner-only intel (decision log, strategy internals, stats) from a
// status payload so paying users see ONLY their P&L — never how it works.
function liteAutopilotStatus(s) {
  if (!s) return s;
  return {
    running: s.running, live: s.live, wallet: s.wallet,
    start: s.start, bank: s.bank, walletSol: s.walletSol, secured: s.secured,
    equity: s.equity, peak: s.peak, pnlPct: s.pnlPct,
    wins: s.wins, losses: s.losses, scratches: s.scratches, blocked: s.blocked,
    open: (s.open || []).map((p) => ({ sym: p.sym, movePct: p.movePct, heldS: p.heldS })),
    endsInS: s.endsInS, stopped: s.stopped, stopReason: s.stopReason,
    bigWins: s.bigWins, // their own win cards are fine to keep
    tape: s.tape // mood only (HOT/COLD/NORMAL) — drives the reactor color, not strategy internals
  };
}

// Lock the autopilot onto a specific managed wallet record. Always refuses the
// fee wallet and any wallet without a signable secret - the only two hard "no"s.
function lockAutopilotWallet(match, context = "") {
  if (!match) throw new Error(`No wallet to run the autopilot on${context ? ` (${context})` : ""}.`);
  if (match.publicKey === CONFIG.feeWallet) throw new Error("Refusing to run the autopilot on the FEE wallet.");
  if (!match.secret) throw new Error("Selected wallet has no signable secret.");
  autopilotWalletRecord = match;
  return match;
}

// Resolve which wallet a START request should use. Two paths:
//  - logged-in terminal session: pick from YOUR loaded wallets by index, label,
//    or pubkey (the "select a wallet loaded in terminal" flow - no env needed).
//  - headless control key: fall back to AUTOPILOT_WALLET_PUBKEY if configured.
async function resolveAutopilotWalletFor({ selector, userId }) {
  const store = await readWalletStore();
  if (userId && selector != null && String(selector).trim() !== "") {
    const mine = walletsForOwner(store, userId);
    const sel = String(selector).trim();
    const idx = Number(sel);
    let match = null;
    if (Number.isInteger(idx) && idx >= 1 && idx <= mine.length) match = mine[idx - 1];
    else match = mine.find((w) => w.label === sel || w.publicKey === sel);
    if (!match) throw new Error(`Wallet "${sel}" not found in your loaded wallets. Run the wallets command to list them.`);
    return lockAutopilotWallet(match, "selected in terminal");
  }
  if (CONFIG.autopilotWalletPubkey) {
    const match = store.wallets.find((w) => w.publicKey === CONFIG.autopilotWalletPubkey);
    if (!match) throw new Error(`AUTOPILOT_WALLET_PUBKEY ${CONFIG.autopilotWalletPubkey} is not a managed wallet in this store.`);
    return lockAutopilotWallet(match, "AUTOPILOT_WALLET_PUBKEY");
  }
  throw new Error("No wallet selected. Log in and pass a wallet index, or set AUTOPILOT_WALLET_PUBKEY.");
}

// Re-lock the wallet a persisted session was using (boot resume after redeploy).
async function relockAutopilotWalletByPubkey(pubkey) {
  const store = await readWalletStore();
  const match = store.wallets.find((w) => w.publicKey === pubkey);
  if (!match) throw new Error(`Persisted autopilot wallet ${pubkey} is no longer in the store.`);
  return lockAutopilotWallet(match, "resume");
}

// --- Autopilot learning flywheel: trade-outcome log + dev-wallet reputation ----
// Every trade records its features + outcome so we can find what predicts runners,
// and we skip wallets that have repeatedly rugged us (the one real anti-rug edge:
// you can't read a rug off the coin, but you can off the dev's track record).
const AUTOPILOT_TRADES_FILE = path.join(CONFIG.dataDir, "autopilot-trades.json");
const autopilotDevRep = new Map(); // devWallet -> { trades, rugs, runners, pnl }
// CROSS-SESSION repeat-loser memory by coin NAME. Clone-name serial ruggers (e.g.
// "LONGDOG" relaunched again and again, different mints) slip past the per-mint guard
// and the per-session name guard resets on restart. This tally persists via the trade
// history so a name that's lost us money repeatedly gets skipped permanently.
const autopilotSymLosses = new Map(); // normSym -> loss count (all-time)
function autopilotNormSym(s) { return String(s || "").toLowerCase().replace(/[^a-z0-9]/g, ""); }
function autopilotSymLossBump(rec) {
  if (!rec || rec.win) return;
  const ns = autopilotNormSym(rec.sym);
  if (!ns) return;
  autopilotSymLosses.set(ns, (autopilotSymLosses.get(ns) || 0) + 1);
}
function autopilotSymbolLoserCount(symbol) { return autopilotSymLosses.get(autopilotNormSym(symbol)) || 0; }
let autopilotTradesCache = null;

function autopilotDevRepBump(dev, rec) {
  if (!dev) return;
  const r = autopilotDevRep.get(dev) || { trades: 0, rugs: 0, runners: 0, pnl: 0, peakSum: 0, avgPeak: 0 };
  r.trades += 1;
  if (rec.rugged) r.rugs += 1;
  if ((rec.peakPct || 0) >= 100) r.runners += 1;
  r.pnl += Number(rec.pnl) || 0;
  r.peakSum += Number(rec.peakPct) || 0;
  r.avgPeak = Math.round(r.peakSum / r.trades); // this dev's coins typically top around here
  autopilotDevRep.set(dev, r);
}
async function loadAutopilotTrades() {
  if (autopilotTradesCache) return autopilotTradesCache;
  let trades = [];
  try {
    const j = await readJson(AUTOPILOT_TRADES_FILE).catch(() => null);
    trades = (j && Array.isArray(j.trades)) ? j.trades : [];
  } catch { trades = []; }
  autopilotDevRep.clear();
  autopilotSymLosses.clear();
  for (const t of trades) { autopilotDevRepBump(t.dev, t); autopilotSymLossBump(t); }
  autopilotTradesCache = trades;
  return trades;
}
async function recordAutopilotTrade(rec) {
  try {
    if (!autopilotTradesCache) await loadAutopilotTrades();
    autopilotTradesCache.push(rec);
    if (autopilotTradesCache.length > 4000) autopilotTradesCache = autopilotTradesCache.slice(-4000);
    autopilotDevRepBump(rec.dev, rec);
    autopilotSymLossBump(rec);
    await writeJsonFile(AUTOPILOT_TRADES_FILE, { trades: autopilotTradesCache });
  } catch {}
}

// SELF-CALIBRATION: derive a bounded, never-looser entry/size bias from the accumulated
// trade history (lib/selfCalibration.js) and cache it to disk. Recomputed periodically on
// the web tick and read at session start so the bot's selectivity tracks what has paid.
const AUTOPILOT_CALIBRATION_FILE = path.join(CONFIG.dataDir, "autopilot-calibration.json");
let autopilotCalibrationCache = null;      // global bias
let autopilotCalibrationByMode = null;     // { [mode]: bias }
let autopilotLiveCalibrationCache = null;  // live-money bias only
let autopilotLiveCalibrationByMode = null; // { [mode]: live-money bias }
let autopilotCalibrationAt = 0;
async function recomputeAutopilotCalibration() {
  try {
    const trades = await loadAutopilotTrades();
    const cal = computeAutopilotCalibration(trades);
    const liveCal = computeAutopilotCalibration(trades, { liveOnly: true });
    autopilotCalibrationCache = cal;
    autopilotLiveCalibrationCache = liveCal;
    autopilotCalibrationByMode = computeCalibrationByMode(trades);
    autopilotLiveCalibrationByMode = computeCalibrationByMode(trades, { liveOnly: true });
    autopilotCalibrationAt = Date.now();
    await writeJsonFile(AUTOPILOT_CALIBRATION_FILE, {
      ...cal,
      byMode: autopilotCalibrationByMode,
      live: liveCal,
      liveByMode: autopilotLiveCalibrationByMode,
      savedAt: autopilotCalibrationAt
    });
    return cal;
  } catch { return autopilotCalibrationCache; }
}
// Returns the bias for a session: the MODE-specific one when that mode has a real sample,
// otherwise the global bias (then defaults). This is what makes every mode self-correct
// toward green on its OWN record rather than being dragged by the others.
function activeCalibration(c) {
  return Boolean(c && (c.minScoreBonus > 0 || (c.sizeFracCapMult != null && c.sizeFracCapMult < 1) || (c.signalWeights && Object.keys(c.signalWeights).length > 0)));
}

async function getAutopilotCalibration(mode, options = {}) {
  const liveOnly = Boolean(options.live || options.liveOnly);
  if (!autopilotCalibrationCache) {
    try {
      const j = await readJson(AUTOPILOT_CALIBRATION_FILE).catch(() => null);
      if (j && (j.minScoreBonus != null || j.sizeFracCapMult != null)) {
        autopilotCalibrationCache = j;
        if (j.byMode) autopilotCalibrationByMode = j.byMode;
        if (j.live) autopilotLiveCalibrationCache = j.live;
        if (j.liveByMode) autopilotLiveCalibrationByMode = j.liveByMode;
      } else {
        await recomputeAutopilotCalibration();
      }
    } catch { await recomputeAutopilotCalibration().catch(() => {}); }
  }
  if (liveOnly && !autopilotLiveCalibrationCache) {
    await recomputeAutopilotCalibration().catch(() => {});
  }
  const byMode = liveOnly ? autopilotLiveCalibrationByMode : autopilotCalibrationByMode;
  const base = liveOnly ? autopilotLiveCalibrationCache : autopilotCalibrationCache;
  const m = mode && byMode && byMode[mode];
  // Use the mode bias only once it has enough sample to be non-neutral; else fall back global.
  if (activeCalibration(m)) return m;
  return base || { minScoreBonus: 0, sizeFracCapMult: 1 };
}

// --- OFF-BOX BACKUP to Cloudflare R2 (10GB free, zero egress) -------------------------------
// A persistent disk survives deploys but is NOT a backup (a deleted/corrupt disk loses it all).
// This daily job gzips the /var/data JSON state — the irreplaceable autopilot brain: trades,
// dev/wallet observatories, caller-intel, calibration, market-tape — and uploads it to R2.
// SECURITY: app-secret.json (the key that decrypts wallets) is NEVER backed up, so the off-box
// copy holds the ENCRYPTED wallets but not the secret to open them — an R2 leak alone can't
// drain funds. Gated on R2_* env: when unset this is a no-op (zero behavior change).
function r2Config() {
  return {
    accountId: process.env.R2_ACCOUNT_ID || "",
    accessKeyId: process.env.R2_ACCESS_KEY_ID || "",
    secretAccessKey: process.env.R2_SECRET_ACCESS_KEY || "",
    bucket: process.env.R2_BUCKET || ""
  };
}
let lastBackupAt = 0;
let lastBackupInfo = null;
async function buildBackupBundle() {
  const bundle = { at: Date.now(), service: CONFIG.serviceRole || "web", files: {}, pg: null, notes: [] };
  // NEVER back up the decryption secret next to the encrypted wallets.
  const EXCLUDE = new Set(["app-secret.json", ...String(process.env.R2_BACKUP_EXCLUDE || "").split(",").map((s) => s.trim()).filter(Boolean)]);
  try {
    const names = (await fs.readdir(CONFIG.dataDir)).filter((n) => n.endsWith(".json") && !EXCLUDE.has(n));
    for (const n of names) {
      try { bundle.files[n] = await fs.readFile(path.join(CONFIG.dataDir, n), "utf8"); } catch {}
    }
  } catch (e) { bundle.notes.push(`dataDir read: ${e && e.message}`); }
  // OPTIONAL bounded Postgres export (off unless R2_BACKUP_PG=true). Dumps the newest rows per
  // public table up to a cap so a huge table can't OOM the box; caps are logged (no silent
  // truncation). Render's managed PG backups remain the heavier, point-in-time tool.
  if (String(process.env.R2_BACKUP_PG || "").toLowerCase() === "true") {
    try {
      const pool = await postgresPool();
      if (pool) {
        const cap = Math.max(1000, Math.min(200000, Number(process.env.R2_BACKUP_PG_ROW_CAP) || 50000));
        const t = await pool.query("select table_name from information_schema.tables where table_schema='public' and table_type='BASE TABLE'");
        bundle.pg = {};
        for (const row of t.rows) {
          const tbl = String(row.table_name);
          try {
            const r = await pool.query(`select * from "${tbl}" limit ${cap + 1}`);
            const capped = r.rows.length > cap;
            bundle.pg[tbl] = r.rows.slice(0, cap);
            if (capped) bundle.notes.push(`pg ${tbl}: capped at ${cap} rows (more exist)`);
          } catch (e) { bundle.notes.push(`pg ${tbl}: ${e && e.message}`); }
        }
      }
    } catch (e) { bundle.notes.push(`pg export: ${e && e.message}`); }
  }
  return bundle;
}
async function backupDataToR2(reason = "scheduled") {
  const cfg = r2Config();
  if (!r2Configured(cfg)) { lastBackupInfo = { ok: false, skipped: true, reason: "R2 not configured" }; return lastBackupInfo; }
  try {
    const bundle = await buildBackupBundle();
    const gz = zlib.gzipSync(Buffer.from(JSON.stringify(bundle)));
    const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, "");
    const fileCount = Object.keys(bundle.files).length;
    const datedKey = `backups/slimewire-${stamp}.json.gz`;
    const a = await r2PutObject(cfg, datedKey, gz, "application/gzip");          // dated snapshot
    const b = await r2PutObject(cfg, "backups/latest.json.gz", gz, "application/gzip"); // easy restore
    lastBackupAt = Date.now();
    lastBackupInfo = { ok: Boolean(a.ok && b.ok), at: lastBackupAt, reason, bytes: gz.length, files: fileCount, pg: Boolean(bundle.pg), key: datedKey, notes: bundle.notes.slice(0, 8) };
    console.log(`[backup] R2 ${lastBackupInfo.ok ? "OK" : `FAIL ${a.status}/${b.status}`} ${(gz.length / 1024).toFixed(0)}KB · ${fileCount} files${bundle.pg ? " +pg" : ""} -> ${datedKey} (${reason})`);
    return lastBackupInfo;
  } catch (e) {
    lastBackupInfo = { ok: false, at: Date.now(), reason, error: e && e.message };
    console.warn(`[backup] R2 failed: ${e && e.message}`);
    return lastBackupInfo;
  }
}

// RUNNING LOG: a rolling, PERSISTENT play-by-play of the autopilot's narration so the log
// survives session/server restarts and accumulates a reviewable history (for tuning + user
// trust). The high-frequency "scanning…" heartbeats are dropped so the log stays signal
// (apes, closes, locks, banks, skips, starts/stops). Capped + debounce-written.
const AUTOPILOT_EVENTS_FILE = path.join(CONFIG.dataDir, "autopilot-events.json");
let autopilotEvents = [];
let autopilotEventsLoaded = false;
let autopilotEventsDirty = false;
async function loadAutopilotEvents() {
  if (autopilotEventsLoaded) return;
  autopilotEventsLoaded = true;
  try {
    const j = await readJson(AUTOPILOT_EVENTS_FILE).catch(() => null);
    autopilotEvents = (j && Array.isArray(j.events)) ? j.events : [];
  } catch { autopilotEvents = []; }
}
const AUTOPILOT_ALERT_CHAT = String(process.env.AUTOPILOT_ALERT_CHAT || "").trim();
function pushAutopilotEvent(level, msg) {
  try {
    const text = String(msg || "");
    if (/^🔍 scanning/.test(text)) return; // skip the noisy heartbeats — keep the log meaningful
    autopilotEvents.push({ at: Date.now(), level, msg: text.slice(0, 300) });
    if (autopilotEvents.length > 4000) autopilotEvents.splice(0, autopilotEvents.length - 4000);
    autopilotEventsDirty = true;
    // OWNER copy-trade watch (private, never public — the autopilot edge stays secret): forward the
    // key live events — copy-trade entries (🐳), fills (🟢 APED), and banked exits/wins — to the chat
    // set in AUTOPILOT_ALERT_CHAT, so the owner can watch it work in real time from Telegram.
    if (AUTOPILOT_ALERT_CHAT && (/^🐳|^🟢 APED|banked|🏆|🎉|stopped out|took profit|smart-exit/i.test(text))) {
      void telegram("sendMessage", { chat_id: AUTOPILOT_ALERT_CHAT, text: "🤖 " + text, disable_web_page_preview: true }).catch(() => {});
    }
  } catch {}
}
setInterval(() => {
  if (!autopilotEventsDirty) return;
  autopilotEventsDirty = false;
  writeJsonFile(AUTOPILOT_EVENTS_FILE, { events: autopilotEvents }).catch(() => {});
}, 8_000);

// --- DEV OBSERVATORY: passively watch EVERY pump.fun launch (creator + outcome)
// market-wide via the live stream, so dev reputation is rich from thousands of
// coins, not just the few we traded. Runs 24/7 regardless of whether autopilot
// is on. Best-effort; never affects trading.
const DEV_OBS_FILE = path.join(CONFIG.dataDir, "dev-observatory.json");
const WALLET_OBS_FILE = path.join(CONFIG.dataDir, "wallet-observatory.json");
const BRAIN_SEED_FLAG_FILE = path.join(CONFIG.dataDir, "brain-seed.json"); // one-time seed-attempt marker (loop-proof)
// OFFLINE MASS GRAB: a brain file produced by scripts/mass-grab.js (run OFF the box, so it can't
// crash the instance) and committed to the REPO. Merged into walletObs once per grab on boot — a
// light JSON read + Map merge, NO network/ST calls, so it's crash-safe. The import marker lives on
// the PERSISTENT disk so a redeploy of the same grab doesn't re-merge.
const BRAIN_GRAB_FILE = path.join(__dirname, "..", "seed", "brain-grab.json");
const BRAIN_GRAB_MARKER = path.join(CONFIG.dataDir, "brain-grab-imported.json");
// DEPLOYER WAREHOUSE — the offline deployer/dev-history grab (scripts/mass-grab.js phase 3). Boot-
// merged ONCE into deployerWarehouse (+ devObs) so Dev Info shows a dev's real launch/rug history
// even for operators the bot never personally watched, and it survives an ST downgrade.
const DEPLOYER_GRAB_FILE = path.join(__dirname, "..", "seed", "deployer-grab.json");
const DEPLOYER_GRAB_MARKER = path.join(CONFIG.dataDir, "deployer-grab-imported.json");
const deployerWarehouse = new Map(); // deployer -> { launchesTracked, runners, rugs, avgMc, bestMc, recentLaunches[], lastSeenMs }
const MARKET_TAPE_FILE = path.join(CONFIG.dataDir, "market-tape.json");
const KOL_LEARNING_FILE = path.join(CONFIG.dataDir, "kol-learning.json");
const devObs = new Map();    // dev -> { coins, ran, rugged, peakSum }  (peakSum = sum of max/first multiples)
const obsCoins = new Map();  // mint -> { dev, firstMc, maxMc, lastMc, at, seen, buyers:[] }
// SMART-MONEY OBSERVATORY: same idea as devObs but for the EARLY BUYER wallets of
// every observed coin — score wallets by how their buys turned out (ran vs rugged).
// Lets the bot lean harder when proven winners / tracked KOLs are aping a coin.
const walletObs = new Map(); // wallet -> { coins, ran, rugged, peakSum }
const KOL_WALLETS = new Set(String(process.env.KOL_WALLETS || "").split(",").map((s) => s.trim()).filter(Boolean));
// AUTO-KOL ROSTER: trusted KOL wallets HARVESTED from our own KOL tracker leaderboard (Solana
// Tracker "top"), so the bot copy-trades any proven KOL with a real win-rate — no manual list.
// The moment one of these wallets shows up in a fresh coin's early buyers, the smart-money entry
// path follows them. Refreshed on a timer (refreshAutoKolWallets) + persisted across restarts.
const autoKolWallets = new Map(); // wallet -> { name, winRate, roi, trades, at }
const trackedKolWallets = new Map(); // wallet -> { name, winRate, roi, trades, source, at } — every KOL our APIs expose
const kolSignalStats = new Map(); // wallet -> { signals, ran, rugged, peakSum, exitSum, exitN, lastAt }
const kolSignalMints = new Map(); // mint -> { wallets:{wallet:meta}, firstMc, maxMc, lastMc, at, seen }
const KOL_COPY_MIN_WINRATE = Number(process.env.KOL_COPY_MIN_WINRATE || 50); // only copy KOLs at/above this win%
const KOL_COPY_MIN_TRADES = Number(process.env.KOL_COPY_MIN_TRADES || 30);   // ignore tiny-sample flukes
function isKolWallet(w) { return KOL_WALLETS.has(w) || autoKolWallets.has(w); }
function isTrackedKolWallet(w) { return isKolWallet(w) || trackedKolWallets.has(w); }

// MARKET-WIDE TAPE: rolling record of FINALIZED market outcomes across every coin the
// observatory watches (not just ours). The autopilot reads this to know if the WHOLE
// market is hot (press) or cold (slow down) — like an AI watching the room, not just
// its own hand. Each entry: { ranMult, rugged, at }.
const marketRecent = [];
function marketTape() {
  const now = Date.now();
  const cutoff = now - 30 * 60 * 1000;
  const r = marketRecent.filter((x) => x.at >= cutoff);
  if (r.length < 12) return null; // not enough fresh market data to call it yet
  const runRate = r.filter((x) => x.ranMult >= 2).length / r.length;
  const rugRate = r.filter((x) => x.rugged).length / r.length;
  // CALIBRATED to pump.fun's grim baseline: MOST coins rug/die normally, so a high
  // rug rate is NOT "cold" — it's Tuesday. COLD must be genuinely dead (almost nothing
  // running AND rugs even worse than baseline), or the gauge reads COLD ~always and
  // freezes the bot every session. HOT = clearly more runners than usual.
  let heat = "NORMAL";
  if (runRate >= 0.16) heat = "HOT";                              // notably more coins running than usual
  else if (runRate < 0.04 && rugRate > 0.85) heat = "COLD";      // truly dead: nothing runs + extreme rugs
  return { heat, runRate: Math.round(runRate * 100) / 100, rugRate: Math.round(rugRate * 100) / 100, sample: r.length };
}

// COIN BANNERS: pump.fun's banner is website/DB-only (can't be set via any create
// API), so SlimeWire keeps its own mint -> banner map and renders the banner like a
// pump.fun coin page (wide banner + overlapping pfp) on our own coin pages.
const COIN_BANNER_FILE = path.join(CONFIG.dataDir, "coin-banners.json");
const COIN_COMMUNITY_FILE = path.join(CONFIG.dataDir, "coin-communities.json");
const COIN_COMMUNITY_BANNER_MAX_BYTES = 4 * 1024 * 1024;
const COIN_COMMUNITY_POST_MEDIA_MAX_BYTES = 5 * 1024 * 1024;
const PUFCAT_MINT = "8G1Z1Mde7AFEUon6iiGpGJzVbUiZCBnsy3Xn495cpump";
const PUFCAT_COMMUNITY_OWNER_ID = "system:pufcat";
const coinBanners = new Map(); // mint -> { bannerUri, symbol, name, at }
async function loadCoinBanners() {
  try {
    const j = await readJson(COIN_BANNER_FILE).catch(() => null);
    if (j && j.banners) for (const [m, r] of Object.entries(j.banners)) coinBanners.set(m, r);
  } catch {}
}
async function saveCoinBanners() {
  try { await writeJsonFile(COIN_BANNER_FILE, { banners: Object.fromEntries(coinBanners), savedAt: Date.now() }); } catch {}
}
function recordCoinBanner(mint, rec = {}) {
  const m = String(mint || "").trim();
  if (!m || !rec.bannerUri) return;
  coinBanners.set(m, { bannerUri: String(rec.bannerUri), symbol: rec.symbol || "", name: rec.name || "", at: Date.now() });
  if (coinBanners.size > 20000) {
    for (const [k] of [...coinBanners.entries()].sort((a, b) => (a[1].at || 0) - (b[1].at || 0)).slice(0, 4000)) coinBanners.delete(k);
  }
  void saveCoinBanners();
}

function coinCommunityBannerDir() {
  return path.join(CONFIG.dataDir, "coin-community-banners");
}

function coinCommunityMediaDir() {
  return path.join(CONFIG.dataDir, "coin-community-media");
}

function normalizeCoinCommunityAddress(value) {
  const raw = String(value || "").trim();
  if (/^0x[0-9a-fA-F]{40}$/.test(raw)) return raw.toLowerCase();
  try { return parsePublicKey(raw).toBase58(); }
  catch {
    const error = new Error("Enter a valid Solana or Robinhood Chain contract address.");
    error.statusCode = 400;
    throw error;
  }
}

function coinCommunityKey(address) {
  return crypto.createHash("sha256").update(normalizeCoinCommunityAddress(address)).digest("hex").slice(0, 32);
}

function coinCommunityBannerPath(address) {
  return path.join(coinCommunityBannerDir(), `${coinCommunityKey(address)}.jpg`);
}

function coinCommunityMediaPath(address, postId, mediaType = "image/webp") {
  const cleanPostId = String(postId || "").replace(/[^a-z0-9_-]/gi, "").slice(0, 40);
  if (!cleanPostId) throw new Error("Invalid community post media key.");
  return path.join(coinCommunityMediaDir(), `${coinCommunityKey(address)}-${cleanPostId}.${mediaType === "image/gif" ? "gif" : "webp"}`);
}

async function readCoinCommunities() {
  const store = await readJson(COIN_COMMUNITY_FILE).catch(() => ({ communities: {} }));
  if (!store.communities || typeof store.communities !== "object" || Array.isArray(store.communities)) store.communities = {};
  if (!store.communities[PUFCAT_MINT]) store.communities[PUFCAT_MINT] = pufcatCommunityDefaults();
  return store;
}

