  const madeOnSolCacheTtlMs = Number.parseInt(process.env.MADE_ON_SOL_CACHE_TTL_MS || "900000", 10);
  const kolUseSolanaTrackerFallback = parseBoolean(process.env.KOL_USE_SOLANA_TRACKER_FALLBACK || "false");
  // OFF by default: the display feed must NOT block on per-coin RPC safety. It RPC-checked up to 120
  // FRESH (uncached) coins via Alchemy getMintSafetyInfo (~3.5s each) every build, so the live/newest
  // bucket timed out and fresh pairs never showed. Real protection is at BUY time (assertTokenBuyBaseSafety
  // checks freeze/mint authority + Token-2022 pool). Set LIVE_PAIRS_RPC_SAFETY=true to re-enable.
  const livePairsRpcSafety = parseBoolean(process.env.LIVE_PAIRS_RPC_SAFETY || "false");
  const livePairsRefreshSeconds = Number.parseInt(process.env.LIVE_PAIRS_REFRESH_SECONDS || "8", 10);
  const livePairsSharedCacheMs = Number.parseInt(process.env.LIVE_PAIRS_SHARED_CACHE_MS || "4000", 10);
  const livePairsImageEnrich = parseBoolean(process.env.LIVE_PAIRS_IMAGE_ENRICH || "true");
  const tokenAvatarFixEnabled = parseOptionalBoolean(process.env.VITE_TOKEN_AVATAR_FIX_ENABLED || process.env.TOKEN_AVATAR_FIX_ENABLED, true);
  const pumpPortalSellFallbackEnabled = parseBoolean(process.env.PUMPPORTAL_SELL_FALLBACK_ENABLED || "true");
  const pumpPortalTradeLocalUrl = (process.env.PUMPPORTAL_TRADE_LOCAL_URL || "https://pumpportal.fun/api/trade-local").trim();
  const minExitMarketCapUsd = Number.parseInt(process.env.MIN_EXIT_MARKET_CAP_USD || "2000", 10);
  const minExitLiquidityUsd = Number.parseInt(process.env.MIN_EXIT_LIQUIDITY_USD || "250", 10);
  const stopLossCheckIntervalMs = Number.parseInt(process.env.STOP_LOSS_CHECK_INTERVAL_MS || "2000", 10);
  const stopLossTriggerBufferPct = Number.parseFloat(process.env.STOP_LOSS_TRIGGER_BUFFER_PCT || "1.5");
  const stopLossExitSlippageBps = Number.parseInt(process.env.STOP_LOSS_EXIT_SLIPPAGE_BPS || "1500", 10);
  const stopLossMonitorSlippageBps = Number.parseInt(process.env.STOP_LOSS_MONITOR_SLIPPAGE_BPS || "2500", 10);
  const stopLossPriceFailureSellAfter = Number.parseInt(process.env.STOP_LOSS_PRICE_FAILURE_SELL_AFTER || "2", 10);
  const stopLossPriceFailureGraceMs = Number.parseInt(process.env.STOP_LOSS_PRICE_FAILURE_GRACE_MS || "8000", 10);
  const stopLossSubmitStaleMs = Number.parseInt(process.env.STOP_LOSS_SUBMIT_STALE_MS || "15000", 10);
  const stopLossReentryCooldownMs = Number.parseInt(process.env.STOP_LOSS_REENTRY_COOLDOWN_MS || "60000", 10);
  const tpSlMonitorStepTimeoutMs = Number.parseInt(process.env.TP_SL_MONITOR_STEP_TIMEOUT_MS || "12000", 10);
  const tradePlanRunnerStaleMs = Number.parseInt(process.env.TRADE_PLAN_RUNNER_STALE_MS || "45000", 10);
  const pumpLaunchBodyLimitBytes = Number.parseInt(process.env.PUMP_LAUNCH_BODY_LIMIT_BYTES || "12000000", 10);
  const pumpLaunchRequestMode = (process.env.PUMP_LAUNCH_REQUEST_MODE || "json").trim().toLowerCase();
  const pumpLaunchPriorityFeeSol = Number.parseFloat(process.env.PUMP_LAUNCH_PRIORITY_FEE_SOL || "0.00005");
  const pumpLaunchRequiredBufferSol = Number.parseFloat(process.env.PUMP_LAUNCH_REQUIRED_BUFFER_SOL || "0.01");
  // Jito atomic anti-snipe bundle for launches (OFF by default; owner enables + tests
  // before relying on it). When on, create + dev buy + first wallet buys land in one
  // block via a Jito bundle so nothing snipes between launch and the first buys.
  const pumpLaunchJitoBundle = parseBoolean(process.env.PUMP_LAUNCH_JITO_BUNDLE || "false");
  // Autopilot is STOPPED by default (owner paused it 2026-06-22 — never won enough to justify the
  // ST credits + RPC its always-on brain feeders burned). When false: the Fresh-Ape session won't
  // resume, the Ogre A.I. tick won't run, and the winner-follow/copy-feed/seed/observatory pollers
  // stay idle. The live creation stream + the user's Launch Sniper are UNAFFECTED (free WS). Flip
  // AUTOPILOT_ENABLED=true on Render to bring it all back.
  const autopilotEnabled = parseBoolean(process.env.AUTOPILOT_ENABLED || "false");
  // Robinhood Chain (EVM, chain id 4663) RPC for the robinhood launch rail. Public RPC by default;
  // point RH_CHAIN_RPC_URL at an Alchemy endpoint if the public one ever rate-limits.
  const rhChainRpcUrl = (process.env.RH_CHAIN_RPC_URL || RH_DEFAULT_RPC).trim();
  // Automatic Robinhood launches use SlimeWire's verified immutable Sushi V3 factory.
  // The production address is the default so a missing Render override can never
  // silently send users back through the legacy token-only launch path.
  const rhSushiLaunchFactoryAddress = String(process.env.RH_SUSHI_LAUNCH_FACTORY_ADDRESS || RH_SUSHI.launchFactory).trim();
  const rhSushiDefaultMarketCapUsd = Math.max(1_000, Math.min(100_000, Number(process.env.RH_SUSHI_DEFAULT_MARKET_CAP_USD) || 5_000));
  // RH trading fees accrue in ETH and auto-convert to SOL at FEE_WALLET once the pot clears this.
  const rhFeeSweepMinEth = Math.max(0.0005, Number.parseFloat(process.env.RH_FEE_SWEEP_MIN_ETH || "0.002") || 0.002);
  // RH creator fee: every SlimeWire launcher earns this % of trades of their coin THAT GO THROUGH
  // SLIMEWIRE — collected at the venue (like pump.fun's fee), paid to their wallet automatically, and
  // NEVER baked into the token (so the coin stays ✅ Verified-safe). 100 bps = 1%, matching pump's fee.
  const rhCreatorFeeBps = Math.max(0, Math.min(300, Number.parseInt(process.env.RH_CREATOR_FEE_BPS || "100", 10) || 100));
  const holderRewardsAutoClaimEnabled = parseBoolean(process.env.HOLDER_REWARDS_AUTO_CLAIM_ENABLED || "true");
  const holderRewardsAutoClaimIntervalMs = Math.max(60_000, Math.min(60 * 60_000, Number.parseInt(process.env.HOLDER_REWARDS_AUTO_CLAIM_INTERVAL_MS || "300000", 10) || 300_000));
  const holderRewardsAutoClaimMaxPerTick = Math.max(1, Math.min(20, Number.parseInt(process.env.HOLDER_REWARDS_AUTO_CLAIM_MAX_PER_TICK || "4", 10) || 4));
  const creatorFeesAutoClaimEnabled = parseBoolean(process.env.CREATOR_FEES_AUTO_CLAIM_ENABLED || "true");
  // Pump creator fees are real on-chain balances but require a claim. Keep the
  // threshold high enough to avoid empty network-fee churn while making a new
  // launch's first meaningful activity visible in minutes instead of hours.
  const creatorFeesAutoClaimIntervalMs = Math.max(10 * 60_000, Math.min(24 * 60 * 60_000, Number.parseInt(process.env.CREATOR_FEES_AUTO_CLAIM_INTERVAL_MS || "1800000", 10) || 1_800_000));
  const creatorFeesAutoClaimMinVolumeSol = Math.max(0.05, Math.min(100, Number.parseFloat(process.env.CREATOR_FEES_AUTO_CLAIM_MIN_VOLUME_SOL || "0.1") || 0.1));
  // Locked Sushi V3 positions accrue both sides of the pool. Anyone can trigger
  // collection, but the locker always pays the recorded creator. Check often
  // enough to feel automatic while skipping empty on-chain transactions.
  const rhSushiFeeAutoClaimEnabled = parseBoolean(process.env.RH_SUSHI_FEE_AUTO_CLAIM_ENABLED || "true");
  const rhSushiFeeAutoClaimIntervalMs = Math.max(60_000, Math.min(24 * 60 * 60_000, Number.parseInt(process.env.RH_SUSHI_FEE_AUTO_CLAIM_INTERVAL_MS || "600000", 10) || 600_000));
  const pumpLaunchJitoUrl = (process.env.PUMP_LAUNCH_JITO_URL || "https://mainnet.block-engine.jito.wtf/api/v1/bundles").trim();
  const pumpLaunchJitoTipSol = Math.max(0.00001, Number.parseFloat(process.env.PUMP_LAUNCH_JITO_TIP_SOL || "0.001") || 0.001);
  // TRADE JITO — route pump buys/sells through a Jito bundle (swap tx + a tiny tip tx) for FAST,
  // sandwich-proof landing. Default OFF (flip TRADE_JITO_BUNDLE=true on Render after a verified live
  // send). Tips kept LOW + per-type: a buy that misses just falls back, but an EXIT must land so it
  // tips a touch more. Bundle is atomic + the swap tx has one signature → the RPC fallback can never
  // double-trade. (Jupiter trades aren't bundled here — Jupiter's /execute already optimizes landing.)
  const tradeJitoBundle = parseBoolean(process.env.TRADE_JITO_BUNDLE || "false");
  // Tips tuned to the LOWEST that reliably LANDS (live test: 0.0001/0.0003 was too low — Jito
  // accepted the bundle but never included it, so every trade fell back to RPC = Jito "on" but
  // doing nothing). These are still tiny (sub-$0.20/trade) but competitive enough to get included;
  // exits tip more since they MUST land. Raise via env in congestion, lower if they always land.
  const tradeJitoTipSol = Math.max(0.00001, Number.parseFloat(process.env.TRADE_JITO_TIP_SOL || "0.0005") || 0.0005);
  const tradeJitoExitTipSol = Math.max(tradeJitoTipSol, Number.parseFloat(process.env.TRADE_JITO_EXIT_TIP_SOL || "0.001") || 0.001);
  // Short by design: a Jito bundle that wins the auction lands in the first ~1-2 slots (<2s) or not at
  // all, so don't stall an exit waiting on one that lost. Live data (2026-06-21): at low tips bundles
  // get ACCEPTED but rarely WIN, so they almost always fall back — keep the wait short so a stop-loss
  // isn't taxed 6s for nothing. 2.5s still catches a genuine fast landing.
  const tradeJitoConfirmMs = Math.max(1500, Number.parseInt(process.env.TRADE_JITO_CONFIRM_MS || "2500", 10) || 2500);
  const pumpLaunchMetadataProvider = normalizeMetadataProvider(process.env.METADATA_PROVIDER || process.env.PUMP_LAUNCH_METADATA_PROVIDER || "auto");
  const renderExternalHostname = String(process.env.RENDER_EXTERNAL_HOSTNAME || "").trim();
  const pumpLaunchHostedMetadataBaseUrl = (
    process.env.PUMP_LAUNCH_HOSTED_METADATA_BASE_URL
    || process.env.PUMP_LAUNCH_METADATA_PUBLIC_BASE_URL
    || process.env.TELEGRAM_WEBHOOK_URL
    || (renderExternalHostname ? `https://${renderExternalHostname}` : "")
    || process.env.WEB_PORTAL_URL
    || ""
  ).replace(/\/$/, "");
  const pumpLaunchPumpFunIpfsUrl = (process.env.PUMP_LAUNCH_PUMPFUN_IPFS_URL || "https://pump.fun/api/ipfs").trim();
  const rpcConfig = resolveSolanaRpcConfig();
  const readRpcConfig = resolveReadRpcConfig();
  const workerSecret = process.env.WORKER_SECRET || "";
  const runWorker = parseBoolean(process.env.RUN_WORKER || (serviceRole === "worker" ? "true" : "false"));
  const workerTickEnabled = parseOptionalBoolean(
    process.env.WORKER_TICK_ENDPOINT_ENABLED,
    parseOptionalBoolean(process.env.WORKER_TICK_ENABLED, Boolean(workerSecret || runWorker))
  );
  const workerTickRunTradePlans = parseBoolean(process.env.WORKER_TICK_RUN_TRADE_PLANS || "true");
  const workerTickRunRhGuards = parseBoolean(process.env.WORKER_TICK_RUN_RH_GUARDS || "true");
  const workerTickRunLimitOrders = parseBoolean(process.env.WORKER_TICK_RUN_LIMIT_ORDERS || "true");
