function webCriticalTpSlSafetyRunnerEnabled() {
  return CONFIG.serviceRole === "web" && !CONFIG.webInternalTpSlRunnersEnabled;
}

const workerRoleHeartbeatMemory = new Map();
function workerRoleHeartbeatKey(taskSet = "trade") {
  return externalCacheKey(`worker-heartbeat:${normalizeWorkerTaskSet(taskSet)}`, "global");
}
async function recordWorkerRoleHeartbeat(taskSet = "trade", phase = "heartbeat", detail = {}) {
  const role = normalizeWorkerTaskSet(taskSet);
  const heartbeat = {
    role,
    phase: String(phase || "heartbeat").slice(0, 40),
    at: new Date().toISOString(),
    durationMs: Number.isFinite(Number(detail.durationMs)) ? Math.max(0, Math.round(Number(detail.durationMs))) : 0,
    deployId: process.env.RENDER_GIT_COMMIT || ""
  };
  workerRoleHeartbeatMemory.set(role, heartbeat);
  await cacheSetJson(workerRoleHeartbeatKey(role), heartbeat, 90_000).catch(() => false);
  return heartbeat;
}
async function workerRoleHeartbeat(taskSet = "trade") {
  const role = normalizeWorkerTaskSet(taskSet);
  const memory = workerRoleHeartbeatMemory.get(role);
  if (memory && Date.now() - Date.parse(memory.at || 0) < 90_000) return memory;
  const shared = await cacheGetJson(workerRoleHeartbeatKey(role)).catch(() => null);
  if (shared?.at) workerRoleHeartbeatMemory.set(role, shared);
  return shared || null;
}
async function workerRoleHeartbeatFresh(taskSet = "trade", maxAgeMs = 15_000) {
  const heartbeat = await workerRoleHeartbeat(taskSet);
  const ageMs = heartbeat?.at ? Date.now() - Date.parse(heartbeat.at) : Number.POSITIVE_INFINITY;
  return Number.isFinite(ageMs) && ageMs >= 0 && ageMs <= maxAgeMs;
}

function startWebCriticalTpSlSafetyRunner() {
  if (!webCriticalTpSlSafetyRunnerEnabled()) return;
  const intervalMs = Math.max(1_000, Math.min(2_500, CONFIG.stopLossCheckIntervalMs || 2_000));
  const tick = (reason) => void runWebCriticalTpSlSafetyTick(reason).catch((error) => {
    console.warn(`Web critical TP/SL safety tick failed (${reason}): ${friendlyError(error)}`);
  });
  console.log(`Web critical TP/SL safety runner enabled. Active exits checked every ${intervalMs}ms as worker backup.`);
  setTimeout(() => tick("startup"), Math.min(1_000, intervalMs));
  setInterval(() => tick("interval"), intervalMs);
}

async function activeWebCriticalTpSlWork() {
  const [guardStore, planStore] = await Promise.all([
    readWebExitGuards(),
    readTradePlans()
  ]);
  const activeGuards = objectRows(guardStore.guards).filter((guard) => (
    isActiveWebExitGuardStatus(guard.status || guard.exitStatus)
  )).length;
  const activePlans = objectRows(planStore.plans).filter((plan) => (
    plan.status === "watching"
    && objectRows(plan.wallets).some((wallet) => isActiveTimedWalletStatus(wallet.status || wallet.exitStatus))
  )).length;
  return { activeGuards, activePlans };
}

async function runWebCriticalTpSlSafetyTick(reason = "interval") {
  if (!webCriticalTpSlSafetyRunnerEnabled()) return { skipped: true, reason: "disabled" };
  if (webCriticalTpSlSafetyRunnerActive) return { skipped: true, reason: "web_critical_tp_sl_safety_runner_active" };
  webCriticalTpSlSafetyRunnerActive = true;
  try {
    const active = await activeWebCriticalTpSlWork();
    if (!active.activeGuards && !active.activePlans) {
      return { skipped: true, reason: "no_active_tp_sl_work", ...active };
    }
    if (await workerRoleHeartbeatFresh("trade", 15_000)) {
      return { skipped: true, reason: "trade_worker_healthy", ...active };
    }
    const result = { reason, ...active };
    if (active.activeGuards) {
      result.webExitGuards = await processWebExitGuards({
        forcePriceCheck: true,
        skipLiveBackfill: true
      });
    }
    if (active.activePlans) {
      result.tradePlans = await processTradePlansWithLease({ forcePriceCheck: true });
    }
    return result;
  } finally {
    webCriticalTpSlSafetyRunnerActive = false;
  }
}

function startTpSlStartupReconcile() {
  setTimeout(() => void backfillConfirmedSolAutoExitHistory({ limit: 12 }).catch((error) => {
    console.warn(`Confirmed Solana exit history startup backfill failed: ${friendlyError(error)}`);
  }), 1_000);
  if (!webLocalTpSlReconcileEnabled()) {
    console.log("Web startup TP/SL reconcile disabled; Render worker tick owns startup/catch-up checks.");
    return;
  }
  scheduleTpSlBackendReconcile("startup", [250, 2_500, 10_000]);
}

let tpSlReconcileScheduledAt = 0;

function webLocalTpSlReconcileEnabled() {
  return CONFIG.webInternalTpSlRunnersEnabled || CONFIG.runWorker || CONFIG.serviceRole === "worker";
}

function scheduleTpSlBackendReconcile(reason = "scheduled", delays = [250]) {
  if (!webLocalTpSlReconcileEnabled()) return;
  const now = Date.now();
  if (now - tpSlReconcileScheduledAt < 3_000) return;
  tpSlReconcileScheduledAt = now;
  for (const delay of delays) {
    setTimeout(() => void runTpSlBackendReconcile(reason).catch((error) => {
      console.warn(`TP/SL backend reconcile failed (${reason}): ${friendlyError(error)}`);
    }), Math.max(0, Number(delay) || 0));
  }
}

async function runTpSlBackendReconcile(reason = "manual") {
  const startedAt = new Date().toISOString();
  await recordTpSlWorkerHeartbeat("reconcile_started", { reason, startedAt });
  const [webExitGuards, tradePlans, portfolioExits] = await Promise.all([
    processWebExitGuards({ forcePriceCheck: true, forceBackfill: true }),
    processTradePlansWithLease({ forcePriceCheck: true }),
    processWebPortfolioExits({ forcePriceCheck: true })
  ]);
  const result = {
    reason,
    startedAt,
    completedAt: new Date().toISOString(),
    webExitGuards,
    tradePlans,
    portfolioExits
  };
  await recordTpSlWorkerHeartbeat("reconcile_completed", result);
  return result;
}

