// ===== OGREVERSE GAME MOUNT (slimewire.org/Ogreverse) ===================================
// The OgreVerse MMO runs as a lightweight CHILD PROCESS inside this instance; we reverse-proxy
// /Ogreverse/* to it. It inherits DATABASE_URL so accounts + cloud saves are durable in the same
// Postgres. Fully isolated: a game crash never touches the bot — the supervisor restarts it with
// backoff, and the proxy only ever returns 502 for /Ogreverse paths if the child is down.
const OGV_PORT = Number(process.env.OGREVERSE_INTERNAL_PORT || 5178);
const OGV_DIR = path.join(__dirname, "..", "ogreverse");
// The game is a whole SECOND Node server running inside the trading instance (its own RAM + CPU +
// Postgres connections). Default OFF so it never weighs down the money bot — flip OGREVERSE_ENABLED=true
// on Render to bring the MMO back. When off, /Ogreverse serves a lightweight "offline" note (no proxy).
const OGREVERSE_ENABLED = parseBoolean(process.env.OGREVERSE_ENABLED || "false");
let ogvChild = null, ogvRestarts = 0, ogvStartedAt = 0;
function startOgreverse() {
  try {
    if (!OGREVERSE_ENABLED) { console.log("[ogreverse] disabled (OGREVERSE_ENABLED=false) — game not mounted, trading instance stays light"); return; }
    if (!fsSync.existsSync(path.join(OGV_DIR, "server.mjs"))) { console.warn("[ogreverse] server.mjs not found — game mount skipped"); return; }
    ogvStartedAt = Date.now();
    ogvChild = spawn(process.execPath, ["server.mjs"], {
      cwd: OGV_DIR,
      env: { ...process.env, OGREVERSE_PORT: String(OGV_PORT), OGREVERSE_HOST: "127.0.0.1" },
      stdio: ["ignore", "pipe", "pipe"],
    });
    ogvChild.stdout.on("data", (d) => process.stdout.write(`[ogreverse] ${d}`));
    ogvChild.stderr.on("data", (d) => process.stderr.write(`[ogreverse] ${d}`));
    ogvChild.on("exit", (code) => {
      ogvChild = null;
      const ranLong = Date.now() - ogvStartedAt > 60000;
      ogvRestarts = ranLong ? 0 : ogvRestarts + 1;
      if (ogvRestarts >= 12) { console.error("[ogreverse] too many restarts — leaving the game down (bot unaffected)"); return; }
      const delay = Math.min(30000, 1000 * 2 ** ogvRestarts);
      console.warn(`[ogreverse] child exited (code=${code}); restarting in ${delay}ms`);
      setTimeout(startOgreverse, delay);
    });
    console.log(`[ogreverse] game mounted on 127.0.0.1:${OGV_PORT} → /Ogreverse`);
  } catch (e) { console.error("[ogreverse] start failed", e); }
}
function proxyOgreverse(request, response, requestUrl) {
  // CORS so the game CLIENT served statically off-site (slimewire.org/Ogreverse) can reach the
  // multiplayer + account API on this backend. The API is its own auth (tokens) so a permissive
  // origin is fine; we reflect the caller's origin.
  const cors = {
    "access-control-allow-origin": request.headers.origin || "*",
    "access-control-allow-methods": "GET,POST,OPTIONS",
    "access-control-allow-headers": "content-type",
    "access-control-max-age": "86400",
    "vary": "Origin",
  };
  if (request.method === "OPTIONS") { response.writeHead(204, cors); response.end(); return; }
  // Game disabled → no child process to proxy to. Serve a tiny static note, never a hanging 502.
  if (!OGREVERSE_ENABLED) {
    response.writeHead(200, { ...cors, "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
    response.end('<!doctype html><meta charset="utf-8"><title>OgreVerse</title><body style="margin:0;background:#0a140c;color:#8fe38f;font-family:system-ui,sans-serif;display:grid;place-items:center;height:100vh;text-align:center"><div><div style="font-size:40px">🐸</div><h2>OgreVerse is resting</h2><p style="color:#6a8f6a;max-width:26rem;margin:0 auto">The MMO is offline right now so the trading engine stays fast. Back soon.</p><p><a href="/" style="color:#89ff43">← Back to SlimeWire</a></p></div></body>');
    return;
  }
  // Redirect /Ogreverse → /Ogreverse/ so the game's relative assets + API base path resolve.
  if (requestUrl.pathname === "/Ogreverse") { response.writeHead(302, { ...cors, Location: "/Ogreverse/" }); response.end(); return; }
  const upstreamPath = (requestUrl.pathname.replace(/^\/Ogreverse/, "") || "/") + (requestUrl.search || "");
  const proxyReq = http.request(
    { host: "127.0.0.1", port: OGV_PORT, method: request.method, path: upstreamPath, headers: { ...request.headers, host: `127.0.0.1:${OGV_PORT}` } },
    (proxyRes) => { response.writeHead(proxyRes.statusCode || 502, { ...proxyRes.headers, ...cors }); proxyRes.pipe(response); }   // streams SSE too
  );
  proxyReq.on("error", () => { if (!response.headersSent) { response.writeHead(502, { "content-type": "application/json" }); response.end(JSON.stringify({ ok: false, error: "ogreverse_unavailable" })); } else { try { response.end(); } catch {} } });
  // Tear down the upstream on CLIENT disconnect (covers long-lived SSE). Must NOT key off the
  // REQUEST 'close' — for a bodyless GET that fires the instant the request ends, which would kill
  // the in-flight proxy request before its response returns (→ spurious 502 on every request).
  response.on("close", () => { try { proxyReq.destroy(); } catch {} });
  request.pipe(proxyReq);
}

let lastInteractiveRequestAt = 0;
function noteInteractiveRequest(request, requestUrl) {
  const pathname = String(requestUrl?.pathname || "");
  if (/^\/(?:api\/internal|api\/worker|internal\/worker|worker\/)/.test(pathname)) return;
  const method = String(request?.method || "GET").toUpperCase();
  const directRead = /^\/api\/(?:chart|map|web\/(?:rh\/token|scan|quick|trade))/.test(pathname);
  if ((method !== "GET" && method !== "HEAD" && method !== "OPTIONS") || directRead) lastInteractiveRequestAt = Date.now();
}
function interactiveRequestPressure(maxAgeMs = 1_500) {
  return lastInteractiveRequestAt > 0 && Date.now() - lastInteractiveRequestAt <= maxAgeMs;
}

