// Robinhood (0x) trades are intentionally kept OUT of trade-history.json so they never pollute SOL
// PnL/positions boards. They still need to be counted in owner analytics, so they live in their own
// store here (mirrored in the audit log). volume-bot churn is tagged source:"rh_volume" so analytics
// can drop it and count only real user buys/sells.
function rhTradeHistoryPath() {
  return path.join(CONFIG.dataDir, "rh-trade-history.json");
}
async function readRhTradeHistory() {
  const store = await readJson(rhTradeHistoryPath()).catch(() => ({ trades: [] }));
  if (!Array.isArray(store.trades)) store.trades = [];
  return store;
}
async function recordRhTradeEvent(event) {
  if (!event || !event.userId || !["buy", "sell"].includes(String(event.type || "").toLowerCase())) return;
  try {
    await withFileLock(rhTradeHistoryPath(), async () => {
      const store = await readJson(rhTradeHistoryPath());
      if (!Array.isArray(store.trades)) store.trades = [];
      const sig = String(event.signature || "");
      if (sig && store.trades.some((t) => String(t.signature || "") === sig)) return;
      const provenanceId = String(event.provenanceId || "").trim();
      if (provenanceId && store.trades.some((t) => String(t.provenanceId || "") === provenanceId)) return;
      store.trades.push({ id: crypto.randomUUID(), timestamp: new Date().toISOString(), ...event });
      if (store.trades.length > 8000) store.trades = store.trades.slice(-8000);
      await writeJsonFile(rhTradeHistoryPath(), store);
    });
  } catch (error) {
    console.warn(`[rh-trade-history] ${friendlyError(error)}`);
  }
}

