function createIdempotentAssociatedTokenAccountInstruction(payer, associatedToken, owner, mint, tokenProgramId = TOKEN_PROGRAM_ID) {
  return new TransactionInstruction({
    programId: ASSOCIATED_TOKEN_PROGRAM_ID,
    keys: [
      { pubkey: payer, isSigner: true, isWritable: true },
      { pubkey: associatedToken, isSigner: false, isWritable: true },
      { pubkey: owner, isSigner: false, isWritable: false },
      { pubkey: mint, isSigner: false, isWritable: false },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
      { pubkey: tokenProgramId, isSigner: false, isWritable: false }
    ],
    // Associated Token Program instruction 1 = CreateIdempotent. This is safe
    // when a wallet creates its WSOL destination concurrently in another tab.
    data: Buffer.from([1])
  });
}

async function selectVolumeBotFunding(chatId, userId, callbackData) {
  const session = sessions.get(chatId);
  if (!session || String(session.userId) !== String(userId) || session.step !== "vbot_funding" || !session.data?.tokenMint || session.data.walletIndex == null) {
    await say(chatId, "That volume setup expired. Tap 📈 Volume Bot to start again.");
    return;
  }
  const parts = String(callbackData || "").split(":");
  const fundingAsset = parts[1] === "token" ? "token" : "sol";
  const tokenSeedPercent = fundingAsset === "token" ? Number(parts[2] || 0) : 0;
  if (fundingAsset === "token" && ![10, 25, 50].includes(tokenSeedPercent)) {
    await say(chatId, "Choose one of the held-token buttons again.");
    return;
  }
  session.data.fundingAsset = fundingAsset;
  session.data.tokenSeedPercent = tokenSeedPercent;
  session.step = "vbot_style";
  const wallet = { label: session.data.walletLabel || `Wallet ${session.data.walletIndex}` };
  await showVolumeBotStyles(chatId, session.data.tokenMint, wallet, fundingAsset, tokenSeedPercent);
}

