async function runLaunchTrailerFfmpeg(args) {
  const timeoutMs = Math.max(8_000, Math.min(60_000, Number(ogreAgentEnv("LAUNCH_VIDEO_LOCAL_TIMEOUT_MS")) || 35_000));
  await new Promise((resolve, reject) => {
    const proc = spawn(ffmpegPath, args);
    let stderr = "", timedOut = false, settled = false;
    const finish = (error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (error) reject(error); else resolve();
    };
    const timer = setTimeout(() => {
      timedOut = true;
      try { proc.kill("SIGKILL"); } catch {}
    }, timeoutMs);
    proc.stderr.on("data", (chunk) => { stderr += chunk; if (stderr.length > 5000) stderr = stderr.slice(-2500); });
    proc.on("error", (error) => finish(error));
    proc.on("close", (code) => finish(code === 0 ? null : new Error(timedOut ? `ffmpeg timed out after ${timeoutMs}ms` : `ffmpeg ${code}: ${stderr.slice(-500)}`)));
  });
}

// FREE premium mobile trailer: real animated forge footage + exact token art/text,
// rendered locally in one bounded FFmpeg process. No per-launch API charge.
async function buildLaunchTrailerMp4(d = {}, mint = "", cp = null) {
  if (!ffmpegPath) return null;
  let dir = null;
  try {
    dir = await fs.mkdtemp(path.join(os.tmpdir(), "swtrail-"));
    const files = await renderLaunchTrailerOverlays(dir, d, mint, cp);
    const forge = launchTrailerAssetPath("launch", "states", "forge.mp4");
    const launch = launchTrailerAssetPath("launch", "states", "launch.mp4");
    const sfx = launchTrailerAssetPath("launch", "sfx", "forge.mp3");
    await Promise.all([forge, launch, sfx].map((file) => fs.access(file)));
    const out = path.join(dir, "out.mp4");
    const still = (file) => ["-loop", "1", "-framerate", "24", "-t", String(LAUNCH_TRAILER_DURATION_SECONDS), "-i", file];
    const filter = [
      `[0:v]trim=duration=4.40,setpts=PTS-STARTPTS,scale=${LAUNCH_TRAILER_WIDTH}:${LAUNCH_TRAILER_HEIGHT}:flags=lanczos,fps=24,setsar=1,format=yuv420p[v0]`,
      `[1:v]trim=duration=4.40,setpts=PTS-STARTPTS,scale=${LAUNCH_TRAILER_WIDTH}:${LAUNCH_TRAILER_HEIGHT}:flags=lanczos,fps=24,setsar=1,format=yuv420p[v1]`,
      `[v0][v1]xfade=transition=fadeblack:duration=0.30:offset=4.10,eq=contrast=1.04:saturation=1.08:brightness=-0.01[bg]`,
      `[2:v]scale=252:252:flags=lanczos,format=rgba,fade=t=in:st=0.45:d=0.28:alpha=1,fade=t=out:st=6.05:d=0.35:alpha=1[coin]`,
      `[bg][coin]overlay=x='(W-w)/2':y='500+5*sin(2*PI*t)':enable='between(t,0.45,6.40)'[coinbg]`,
      `[3:v]format=rgba,fade=t=in:st=0.05:d=0.22:alpha=1,fade=t=out:st=5.90:d=0.35:alpha=1[identity]`,
      `[coinbg][identity]overlay=0:0:enable='between(t,0.05,6.25)'[identified]`,
      `[4:v]format=rgba,fade=t=in:st=3.84:d=0.07:alpha=1,fade=t=out:st=3.94:d=0.28:alpha=1[impact]`,
      `[identified][impact]overlay=0:0:enable='between(t,3.84,4.25)'[hit]`,
      `[5:v]format=rgba,fade=t=in:st=6.05:d=0.35:alpha=1[endcard]`,
      `[hit][endcard]overlay=0:0:enable='gte(t,6.05)',fps=24,format=yuv420p[vout]`,
      `[6:a]asplit=3[sfx0][sfx1][sfx2]`,
      `[sfx0]atrim=duration=2.0,asetpts=PTS-STARTPTS,volume=0.34,adelay=250|250[a0]`,
      `[sfx1]atrim=duration=2.0,asetpts=PTS-STARTPTS,atempo=0.93,volume=0.48,adelay=2550|2550[a1]`,
      `[sfx2]atrim=duration=2.0,asetpts=PTS-STARTPTS,atempo=1.07,volume=0.72,adelay=3920|3920[a2]`,
      `[7:a]volume=0.025,afade=t=in:st=0:d=0.35,afade=t=out:st=7.9:d=0.6[rumble]`,
      `[rumble][a0][a1][a2]amix=inputs=4:duration=longest:normalize=0,alimiter=limit=0.90,atrim=duration=${LAUNCH_TRAILER_DURATION_SECONDS}[aout]`
    ].join(";");
    const args = [
      "-y", "-hide_banner", "-loglevel", "error", "-filter_complex_threads", "1",
      "-i", forge, "-i", launch,
      ...still(files.coin), ...still(files.identity), ...still(files.impact), ...still(files.end),
      "-i", sfx, "-f", "lavfi", "-t", String(LAUNCH_TRAILER_DURATION_SECONDS), "-i", "sine=frequency=52:sample_rate=44100",
      "-filter_complex", filter, "-map", "[vout]", "-map", "[aout]", "-t", String(LAUNCH_TRAILER_DURATION_SECONDS),
      "-r", "24", "-c:v", "libx264", "-preset", "veryfast", "-crf", "22", "-maxrate", "2400k", "-bufsize", "4800k",
      "-pix_fmt", "yuv420p", "-profile:v", "high", "-level", "3.1", "-threads", "1",
      "-c:a", "aac", "-b:a", "96k", "-ac", "1", "-movflags", "+faststart", out
    ];
    await runLaunchTrailerFfmpeg(args);
    return await fs.readFile(out);
  } catch (error) {
    console.warn(`[launch-trailer] mp4 failed: ${error.message}`);
    return null;
  } finally {
    if (dir) fs.rm(dir, { recursive: true, force: true }).catch(() => {});
  }
}

async function buildBestTrailerUncached(d = {}, mint = "", cp = null) {
  return withLaunchTrailerRenderSlot(async () => {
    const mp4 = await buildLaunchTrailerMp4(d, mint, cp);
    if (mp4?.length) return { kind: "mp4", buffer: mp4, provider: "local" };
    const gif = await buildLaunchTrailerGif(d, mint, cp);
    if (gif?.length) return { kind: "gif", buffer: gif, provider: "local-fallback" };
    return null;
  });
}

// One in-flight/completed result per mint/art pair. The launcher DM, public channel,
// and every opted-in group all reuse this same 3-5MB buffer instead of re-rendering.
async function buildBestTrailer(d = {}, mint = "", cp = null) {
  const now = Date.now();
  pruneLaunchTrailerCache(now);
  const key = launchTrailerCacheKey(d, mint);
  const cached = launchTrailerCache.get(key);
  if (cached && cached.expiresAt > now) return cached.promise;
  pruneLaunchTrailerCache(now, true);
  // If a launch burst already filled every slot with active renders, keep the bot
  // responsive and let the static card stand instead of growing an unbounded queue.
  if (launchTrailerCache.size >= LAUNCH_TRAILER_CACHE_MAX) return null;
  const entry = { settled: false, expiresAt: now + LAUNCH_TRAILER_CACHE_TTL_MS, promise: null };
  entry.promise = buildBestTrailerUncached(d, mint, cp).then((result) => {
    if (!result) launchTrailerCache.delete(key);
    else {
      entry.settled = true;
      entry.expiresAt = Date.now() + LAUNCH_TRAILER_CACHE_TTL_MS;
      const expiryTimer = setTimeout(() => {
        if (launchTrailerCache.get(key) === entry) launchTrailerCache.delete(key);
      }, LAUNCH_TRAILER_CACHE_TTL_MS + 1000);
      expiryTimer.unref?.();
    }
    return result;
  }, (error) => {
    launchTrailerCache.delete(key);
    throw error;
  });
  launchTrailerCache.set(key, entry);
  return entry.promise;
}

async function postLaunchTrailer(chatId, d = {}, mint = "") {
  try {
    const sym = String(d.symbol || "COIN").toUpperCase();
    const cp = await launchHypeCopy(d);
    const socials = launchSocials(d);
    // caption links (clickable in Telegram): pump + chart + each social + ALWAYS website
    const linkLines = [];
    if (mint) { linkLines.push(`💊 <a href="https://pump.fun/${mint}">Pump.fun</a>  ·  📈 <a href="https://www.slimewire.org/t?ca=${mint}">Chart</a>`); }
    for (const s of socials) { linkLines.push(`🔗 <a href="${s.url}">${escapeHtml(s.label)}</a>`); }
    linkLines.push(`🌐 <a href="https://www.slimewire.org">www.SlimeWire.org</a>`);
    const caption = [
      `🚀 <b>$${sym} — born on SlimeWire</b>`,
      escapeHtml(cp.tagline),
      "",
      ...cp.lines.map((l) => escapeHtml(l)),
      mint ? `\nCA: <code>${mint}</code>` : "",
      "",
      ...linkLines
    ].filter(Boolean).join("\n");
    const kbRows = [];
    if (mint) kbRows.push([{ text: "📈 Chart", url: `https://www.slimewire.org/t?ca=${mint}` }, { text: "💊 Pump.fun", url: `https://pump.fun/${mint}` }]);
    const socialBtns = socials.map((s) => ({ text: s.label.length > 16 ? s.label.slice(0, 15) + "…" : s.label, url: s.url }));
    for (let i = 0; i < socialBtns.length; i += 2) kbRows.push(socialBtns.slice(i, i + 2));
    kbRows.push([{ text: "🌐 SlimeWire.org", url: "https://www.slimewire.org" }, { text: "🐸 Swamp", url: "https://www.slimewire.org/swamp" }]);
    const kb = { inline_keyboard: kbRows };

    // Public channel/groups are posted by announceLaunchCard. Here we ONLY give the
    // launcher a private copy (DM = positive chat id) so groups don't get doubles.
    const targets = [];
    if (Number(chatId) > 0) targets.push(chatId);
    const broadcast = ogreAgentEnv("LAUNCH_BROADCAST_CHAT_ID");
    if (broadcast && !targets.map(String).includes(String(broadcast))) targets.push(broadcast);
    if (!targets.length) return;

    // 1) FIRE IMAGE FIRST — the launch card with CA + socials + website (fast, always works)
    const png = await renderLaunchCard(d, mint, cp);
    const fname = `launch-${sanitizeFilenamePart(sym)}.png`;
    for (const t of targets) { try { await sendPhoto(t, fname, png, caption, kb, "HTML"); } catch { /* per-target */ } }

    // 2) THEN THE VIDEO. A configured paid provider can still serve the private
    // launcher copy by URL; otherwise use the shared, zero-cost local render.
    const safeSym = escapeTelegramHtml(sym);
    const videoBase = fname.replace(/\.png$/i, "");
    const vCap = `🎬 <b>$${safeSym}</b> trailer — born on SlimeWire${mint ? `\nCA: <code>${mint}</code>` : ""}`;
    (async () => {
      const hasVideoApi = ogreAgentEnv("FAL_KEY") || ogreAgentEnv("LAUNCH_VIDEO_API_KEY") || ogreAgentEnv("LAUNCH_VIDEO_API_URL");
      if (hasVideoApi) {
        const generated = await generateLaunchVideo(d, mint, cp).catch(() => null);
        if (generated?.url) {
          for (const t of targets) {
            try { await sendTelegramVideo(t, { url: generated.url }, vCap, kb); } catch { /* per-target */ }
          }
          return;
        }
      }
      const tr = await buildBestTrailer(d, mint, cp);
      if (!tr) return;
      for (const t of targets) {
        try {
          if (tr.kind === "mp4") await sendTelegramVideo(t, { buffer: tr.buffer, filename: `${videoBase}.mp4` }, vCap, kb);
          else await sendTelegramAnimation(t, tr.buffer, `${videoBase}.gif`, vCap, kb);
        } catch { /* per-target */ }
      }
    })().catch(() => {});
  } catch { /* launch already succeeded; trailer is bonus */ }
}

async function nextPnlBorderDataUrl() {
  if (PNL_CARD_BORDER_FILES.length === 0) return null;

  for (let attempt = 0; attempt < PNL_CARD_BORDER_FILES.length; attempt += 1) {
    const index = pnlBorderRotationIndex % PNL_CARD_BORDER_FILES.length;
    pnlBorderRotationIndex = (pnlBorderRotationIndex + 1) % PNL_CARD_BORDER_FILES.length;
    const dataUrl = await pnlBorderDataUrl(PNL_CARD_BORDER_FILES[index]);
    if (dataUrl) return dataUrl;
  }

  return null;
}

async function pnlBorderDataUrl(filePath) {
  if (pnlBorderDataUrlCache.has(filePath)) {
    return pnlBorderDataUrlCache.get(filePath);
  }

  try {
    const buffer = await fs.readFile(filePath);
    const dataUrl = `data:image/png;base64,${buffer.toString("base64")}`;
    pnlBorderDataUrlCache.set(filePath, dataUrl);
    return dataUrl;
  } catch {
    pnlBorderDataUrlCache.set(filePath, null);
    return null;
  }
}

