async function fetchTelegramFileText(fileId) {
  const file = await telegram("getFile", { file_id: fileId });
  const response = await fetch(`https://api.telegram.org/file/bot${CONFIG.telegramToken}/${file.file_path}`);
  if (!response.ok) {
    throw new Error(`Could not download backup file: HTTP ${response.status}`);
  }
  return response.text();
}

async function fetchTelegramFileDataUrl(fileId) {
  const file = await telegram("getFile", { file_id: fileId });
  const response = await fetch(`https://api.telegram.org/file/bot${CONFIG.telegramToken}/${file.file_path}`);
  if (!response.ok) throw new Error(`Could not download image: HTTP ${response.status}`);
  const buf = Buffer.from(await response.arrayBuffer());
  const ext = String(file.file_path || "").split(".").pop().toLowerCase();
  const mime = ext === "png" ? "image/png" : ext === "webp" ? "image/webp" : ext === "gif" ? "image/gif" : "image/jpeg";
  return { dataUrl: `data:${mime};base64,${buf.toString("base64")}`, mime, size: buf.length, name: `coin.${ext || "jpg"}` };
}

// ---- 🐸 SlimeWire PFP maker (Telegram): /pfp turns your CURRENT Telegram avatar into a branded slime
// PFP — same free sharp compositor the website uses. Tap a style to restyle in place; no wallet needed.
function pfpWebUrl() { return (CONFIG.webPortalUrl || "https://www.slimewire.org").replace(/\/$/, "") + "/pfp"; }
async function fetchTelegramAvatarBuffer(userId) {
  try {
    const res = await telegram("getUserProfilePhotos", { user_id: userId, limit: 1 });
    const sizes = res && res.photos && res.photos[0];
    if (!sizes || !sizes.length) return null;
    const largest = sizes[sizes.length - 1]; // last size = highest resolution
    const img = await fetchTelegramFileDataUrl(largest.file_id);
    return Buffer.from(String(img.dataUrl).split(",")[1] || "", "base64");
  } catch { return null; }
}
async function pfpFrameButtons(activeId, ownerId) {
  const avail = await availablePfpFrames(PFP_FRAME_DIR);
  const rows = [];
  for (let i = 0; i < avail.length; i += 2) {
    rows.push(avail.slice(i, i + 2).map((f) => ({ text: (f.id === activeId ? "• " : "") + f.label, callback_data: `pfp:f:${f.id}:${ownerId}` })));
  }
  // 🎲 Slime Studio — free combinatorial roll (always available when the Higgs library exists).
  if (await slimeStudioComboCount(PFP_FRAME_DIR).catch(() => 0) > 0) {
    rows.push([{ text: "🎲 Slime Studio (random)", callback_data: `pfp:st:${ownerId}` }]);
  }
  // ✨ AI Slime styles (custom repaint) — only when the model is enabled (FAL_KEY set).
  if (aiPfpConfigured()) {
    const styles = aiPfpStyles().slice(0, 4);
    for (let i = 0; i < styles.length; i += 2) {
      rows.push(styles.slice(i, i + 2).map((s) => ({ text: "✨ " + s.label, callback_data: `pfp:ai:${s.id}:${ownerId}` })));
    }
  }
  rows.push([{ text: "🎨 Upload a different pic on the site", url: pfpWebUrl() }]);
  return { inline_keyboard: rows };
}
const PFP_TG_CAPTION = "🐸 <b>Your SlimeWire PFP</b>\nTap a style below, then save the image and set it as your profile pic.";
async function editMessagePhotoBuffer(chatId, messageId, buffer, caption, replyMarkup) {
  const upload = telegramPhotoUpload(buffer, "slimewire-card.png");
  const send = async (markup) => {
    const form = new FormData();
    form.append("chat_id", String(chatId));
    form.append("message_id", String(messageId));
    form.append("media", JSON.stringify({ type: "photo", media: "attach://pfp", caption, parse_mode: "HTML" }));
    form.append("pfp", new Blob([upload.bytes], { type: upload.mime }), upload.filename);
    if (markup) form.append("reply_markup", JSON.stringify(markup));
    return telegramApiFetchJson(`https://api.telegram.org/bot${CONFIG.telegramToken}/editMessageMedia`, { method: "POST", body: form });
  };
  const fallbackMarkup = telegramLoginUrlFallbackMarkup(replyMarkup);
  let data;
  try {
    data = await send(replyMarkup);
  } catch (error) {
    const detail = error?.providerData?.description || error?.message;
    if (!fallbackMarkup || !telegramLoginUrlSetupError(detail)) throw error;
    console.warn("[tg-login] LoginUrl domain is not linked in BotFather; editing with the public site fallback. Run /setdomain for app.slimewire.org.");
    data = await send(fallbackMarkup);
  }
  if (!data.ok) throw new Error(data.description || "editMessageMedia failed");
  return data.result;
}
