  if (key === "h6") return ["h6", "6h", "sixHour", "six_hour"];
  if (key === "h1") return ["h1", "1h", "hour", "oneHour", "one_hour"];
  if (key === "m5") return ["m5", "5m", "fiveMinute", "five_minute"];
