  const pumpLiq = firstMeaningfulNumber(scanSourceLiquidity(bonding), scanPumpVirtualLiquidity(bonding));
  const dexLiq = firstMeaningfulNumber(scanSourceLiquidity(best), scanSourceLiquidity(meta));
