    liquidityUsd: Math.max(Number(indexedCandidate.liquidityUsd) || 0, Number(selected?.liquidityUsd) || 0),
    volume24h: Math.max(Number(indexedCandidate.volume24h) || 0, Number(selected?.volume24h) || 0)
