    if (amountSol === null) return await xDmSend(senderId, `X DM buy amounts must be ${X_DM_BUY_LIMITS.minSol}-${X_DM_BUY_LIMITS.maxSol} SOL. Update with: set amount 0.1`, state);
    const rec = { action: "buy", userId, amountSol, mint };
