    bounded(getPumpFunTokenMetadata(mint).catch(() => null)),
    bounded(fetchJson(`https://tokens.jup.ag/token/${mint}`, { timeoutMs }).catch(() => null)),
    onchain || bounded(fetchOnchainTokenMeta(mint).catch(() => null))
