    sep: pick([" · ", " | ", " • "]),
    cta: pick(X_REPLY_CTAS),
    ok: pick(["✅", "🟢", "🛡️"]),
    warn: pick(["⚠️", "🟡"]),
    danger: pick(["⛔", "🔴", "🚨"])
