      heliusPaidStats.enhancedBatchRequests += 1;
      heliusPaidStats.enhancedTransactionsRequested += chunk.length;
      parsed = await fetch(`https://api.helius.xyz/v0/transactions?api-key=${CONFIG.heliusApiKey}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ transactions: chunk }),
        signal: AbortSignal.timeout(8000)
      }).then((response) => response.ok ? response.json() : null);
