        signature,
        timestamp: Number(tx?.timestamp) || 0,
        blockTime: Number(tx?.blockTime) || 0,
        events: tx?.events?.swap ? { swap: tx.events.swap } : {},
        tokenTransfers: Array.isArray(tx?.tokenTransfers) ? tx.tokenTransfers : [],
        nativeTransfers: Array.isArray(tx?.nativeTransfers) ? tx.nativeTransfers : []
