      const delta = observation?.delta;
      if (!delta) continue;
      const wallet = delta.wallet;
      if (!delta.hadBaseline) {
        state.seenSignatures[wallet] = delta.observedSignatures.slice(0, SMART_CALL_SIGNATURE_HISTORY);
        delete state.signatureCursors[wallet];
        continue; // deployment baseline never replays old trades
      }
      const parsed = observation.parsed;
      const checked = new Set(parsed?.checkedSignatures || []);
      const allHandled = delta.freshSignatures.every((signature) => checked.has(signature));
      if (delta.freshSignatures.length && !allHandled) continue; // no cursor advance or partial seen-set: retry without holes
      const handled = [...delta.freshSignatures, ...delta.ignoredSignatures];
      if (handled.length) state.seenSignatures[wallet] = [...new Set([...handled, ...delta.seen])].slice(0, SMART_CALL_SIGNATURE_HISTORY);
      if (delta.nextCursor) state.signatureCursors[wallet] = delta.nextCursor;
      else delete state.signatureCursors[wallet];
