async function smartCallPostTick() {
  if (_smartCallPostRunning) return;
  _smartCallPostRunning = true;
  try {
    const targets = await smartCallTargets();
    if (!targets.any || !xConfigured()) return;
    const state = await refreshSmartCallRoster();
    const handles = state.activeHandles.slice(0, SMART_CALL_ROSTER_SIZE);
    if (!handles.length) return;
    const now = Date.now();
    // One combined search covers all 30 callers. It is both faster and far gentler
    // on X than 30 individual searches, while still checking the whole roster each tick.
    const query = `(${handles.map((handle) => `from:${handle}`).join(" OR ")}) -filter:replies -filter:retweets`;
    const posts = await xSearchQuery(query, 40).catch(() => []);
    for (const post of posts) {
      if (!post?.id || state.seenPosts[post.id]) continue;
      state.seenPosts[post.id] = now;
      const handle = String(post.username || "").toLowerCase();
      if (!handle || !handles.includes(handle) || !state.postBaselines[handle] || now - Number(post.createdAtMs || now) > 45 * 60_000) continue;
      const mint = extractMintsFromText([post.text, ...(post.urls || [])].join(" "))[0];
      if (mint) await recordSmartCall({ mint, handle, trigger: "post" }, targets);
    }
    for (const handle of handles) state.postBaselines[handle] = now;
    for (const [id, at] of Object.entries(state.seenPosts)) if (now - Number(at) > 7 * 86_400_000) delete state.seenPosts[id];
    await writeSmartCalls(state);
  } catch (error) { console.warn(`[smart-calls] post tick: ${String(error?.message || error).slice(0, 120)}`); }
  finally { _smartCallPostRunning = false; }
}
async function broadcastSmartCallEvent({ groups = [], browserUsers = [], text = "", keyboard = null, title = "SlimeWire alert", body = "", tag = "smart-call", url = "/terminal" } = {}) {
  let delivered = false;
  for (const chatId of groups) {
    const ok = await sayHtml(chatId, text, keyboard).then(() => true).catch(() => false);
    delivered = delivered || ok;
  }
  const pushed = await sendWebPushToUsers(browserUsers, { title, body, tag, url });
  return delivered || pushed > 0;
}

async function smartCallPumpBondingProof(mint) {
  const token = String(mint || "").trim();
  // Modern Pump launches carry the pump suffix. Limiting graduation alerts to
  // contracts Pump itself can verify prevents ordinary DEX liquidity from
  // masquerading as a bonding-curve migration.
  if (!isLikelySolMint(token) || !token.toLowerCase().endsWith("pump")) return null;
  const pump = await getPumpFunTokenMetadata(token, {
    force: true,
    cacheTtlMs: 0,
    timeoutMs: 2_800
  }).catch(() => null);
  if (!pump || pump.source !== "pumpfun") return null;
  const progress = firstMeaningfulNumber(pump.bondingProgressPct);
  return {
    completed: Boolean(
      pump.graduated
      || pump.isGraduated
      || (progress != null && Number(progress) >= 99.5)
    ),
    progress: progress != null ? Number(progress) : null
  };
}

function smartCallHasVerifiedPostBondPool(live, proof) {
  if (!proof?.completed || !(Number(live?.liq) > 0)) return false;
  return /pumpswap|raydium|meteora|orca/i.test(String(live?.dexId || ""));
}

async function handleSmartCallPumpMigrationEvent(entry = {}) {
  const mint = String(entry.mint || "").trim();
  if (!mint) return false;
  const state = await readSmartCalls();
  const call = state.calls?.[mint];
  if (!call || !(call.alertEligible === true || call.announcedAt)) return false;
  const observedAt = Number(entry.at) || Date.now();
  // The call already existed when PumpPortal emitted migration, proving it was
  // tracked on the curve before the bond completed.
  if (Number(call.firstAt) > 0 && Number(call.firstAt) <= observedAt) {
    call.pumpCurveObservedAt = Number(call.pumpCurveObservedAt) || Number(call.firstAt);
  }
  call.pumpMigrationObservedAt = observedAt;
  call.lastCheckAt = 0;
  await writeSmartCalls(state);
  // First attempt catches the live event; the later attempts let the post-bond
  // pool index without waiting for the normal five-minute receipt cycle.
  for (const delayMs of [250, 3_000, 15_000]) {
    const timer = setTimeout(() => { void smartCallReceiptTick(); }, delayMs);
    if (timer.unref) timer.unref();
  }
  return true;
}

async function smartCallReceiptTick() {
  if (_smartCallReceiptRunning) return;
  _smartCallReceiptRunning = true;
  try {
    const targets = await smartCallTargets();
    const trackingForX = xConfigured() && xKolTradeOn();
    if (!targets.any && !trackingForX) return;
    const state = await readSmartCalls();
    const now = Date.now();
    const due = Object.values(state.calls).filter((call) => (call.alertEligible === true || call.announcedAt) && now - call.firstAt <= SMART_CALL_LIFETIME_MS)
      .sort((a, b) => Number(a.lastCheckAt || 0) - Number(b.lastCheckAt || 0));
    const start = due.length ? _smartCallReceiptRotor % due.length : 0;
    const batch = due.length ? due.slice(start).concat(due.slice(0, start)).slice(0, 10) : [];
    _smartCallReceiptRotor = due.length ? (_smartCallReceiptRotor + batch.length) % due.length : 0;
    const pumpProofs = new Map(await Promise.all(batch.map(async (call) => [
      call.mint,
      await smartCallPumpBondingProof(call.mint)
    ])));
    for (const call of batch) {
      call.lastCheckAt = now;
      call.milestones = Array.isArray(call.milestones) ? call.milestones : [];
      const live = await alphaRadarFetchMc(call.mint).catch(() => null);
      if (!live?.mc) continue;
      const hasLiquidity = Number(live.liq) > 0;
      const pumpProof = pumpProofs.get(call.mint) || null;
      if (!call.liquidityBaselineSet) {
        call.liquidityBaselineSet = true;
        call.bornWithLiquidity = hasLiquidity;
        call.sawCurve = !hasLiquidity;
      } else if (!hasLiquidity) call.sawCurve = true;
      // Pump's native/pre-bond market may already expose liquidity. Pump's curve
      // state, not an LP flicker, proves this Smart Call was observed pre-bond.
      if (pumpProof && !pumpProof.completed) {
        call.sawCurve = true;
        call.pumpCurveObservedAt = Number(call.pumpCurveObservedAt) || now;
      }
      // Repair old false alerts without replaying genuine historical migrations.
      // If Pump still says the coin is on-curve, invalidate the old alert so the
      // real bonded event can fire later. Already-bonded legacy calls baseline
      // silently at the new proof version.
      if (call.migrationAlertedAt
          && Number(call.migrationProofVersion) < SMART_CALL_MIGRATION_PROOF_VERSION
          && pumpProof) {
        if (pumpProof.completed) {
          call.migrationProofVersion = SMART_CALL_MIGRATION_PROOF_VERSION;
        } else {
          call.migrationAlertedAt = null;
          call.migrationInvalidatedAt = now;
        }
      }
      if (!(Number(call.entryMc) > 0)) {
        call.entryMc = live.mc;
        call.peakMc = live.mc;
        call.lastMc = live.mc;
        if (!call.symbol && live.sym) call.symbol = live.sym;
        continue;
      }
      call.lastMc = live.mc;
      call.peakMc = Math.max(Number(call.peakMc) || 0, live.mc);
      if (!call.symbol && live.sym) call.symbol = live.sym;
      if (!call.ruggedAt
          && now - Number(call.qualifiedAt || call.firstAt || 0) >= 10 * 60_000
          && Number(call.lastMc) / Number(call.entryMc) <= 0.45) call.ruggedAt = now;

      if (smartCallHasVerifiedPostBondPool(live, pumpProof)
          && Number(call.pumpCurveObservedAt) > 0
          && !call.migrationAlertedAt) {
        const sym = call.symbol || shortMint(call.mint);
        const text = [
          `🚀 <b>Token migration · $${escapeTelegramHtml(sym)}</b>`,
          `Bonded and graduated to a live DEX pool with <b>${scanFmtMoney(live.liq)} LP</b>.`,
          `MC <b>${scanFmtMoney(live.mc)}</b> · tracked from the original Smart Call.`,
          `<code>${escapeTelegramHtml(call.mint)}</code>`
        ].join("\n");
        const delivered = await broadcastSmartCallEvent({
          groups: targets.migrationGroups, browserUsers: targets.browserUsers, text, keyboard: smartCallKeyboard(call.mint),
          title: `🚀 $${sym} migrated to DEX`, body: `${scanFmtMoney(live.liq)} LP · ${scanFmtMoney(live.mc)} MC`,
          tag: `smart-migration-${call.mint}`, url: `/t?ca=${encodeURIComponent(call.mint)}&source=migration`
        });
        if (delivered) {
          call.migrationAlertedAt = now;
          call.migrationProofVersion = SMART_CALL_MIGRATION_PROOF_VERSION;
          call.verifiedBondedAt = now;
        }
      }

      if (!call.dexPaidAlertedAt && now - Number(call.lastDexPaidCheckAt || 0) >= 15 * 60_000) {
        call.lastDexPaidCheckAt = now;
        const paid = await fetchDexPaidStatus(call.mint);
        if (paid != null) {
          const canAlert = Number(call.alertSchemaVersion) >= 1;
          const wasPaid = call.dexPaidLast === true;
          call.dexPaidInitialized = true;
          call.dexPaidLast = paid;
          // Legacy calls baseline silently on the first post-deploy check. Otherwise hundreds of
          // already-paid historical calls could ping opted-in devices during the rollout.
          call.alertSchemaVersion = 1;
          if (canAlert && paid && !wasPaid && hasLiquidity) {
            const sym = call.symbol || shortMint(call.mint);
            const text = [
              `✅ <b>DEX paid · $${escapeTelegramHtml(sym)}</b>`,
              `The token's DEX profile/order status is now approved.`,
              `MC <b>${scanFmtMoney(live.mc)}</b> · LP <b>${scanFmtMoney(live.liq)}</b>`,
              `<code>${escapeTelegramHtml(call.mint)}</code>`
            ].join("\n");
            const delivered = await broadcastSmartCallEvent({
              groups: targets.dexPaidGroups, browserUsers: targets.browserUsers, text, keyboard: smartCallKeyboard(call.mint),
              title: `✅ $${sym} is DEX paid`, body: `${scanFmtMoney(live.mc)} MC · ${scanFmtMoney(live.liq)} LP`,
              tag: `smart-dex-paid-${call.mint}`, url: `/t?ca=${encodeURIComponent(call.mint)}&source=dex-paid`
            });
            if (delivered) call.dexPaidAlertedAt = now;
          }
        }
      }

      const multiple = call.peakMc / call.entryMc;
      const crossed = SMART_CALL_MILESTONES.filter((stage) => multiple >= stage && !call.milestones.includes(stage));
      if (!crossed.length) continue;
      const stage = crossed[crossed.length - 1];
      const source = (call.sourceNames || []).filter(Boolean).slice(0, 3).join(" + ") || "Top-30 tracked wallet";
      const text = [
        `🏆 <b>Smart Call receipt — ${stage}x</b>`,
        `<b>$${escapeTelegramHtml(call.symbol || shortMint(call.mint))}</b> was tracked at ${scanFmtMoney(call.entryMc)} MC and reached ${scanFmtMoney(call.peakMc)} MC.`,
        `Source: <b>${escapeTelegramHtml(source)}</b>`,
        `<code>${escapeTelegramHtml(call.mint)}</code>`,
        "<i>Verified from the original tracked entry.</i>"
      ].join("\n");
      const delivered = await broadcastSmartCallEvent({
        groups: targets.xReturnGroups, browserUsers: targets.browserUsers, text, keyboard: smartCallKeyboard(call.mint),
        title: `🏆 $${call.symbol || shortMint(call.mint)} reached ${stage}x`,
        body: `${scanFmtMoney(call.entryMc)} entry · ${scanFmtMoney(call.peakMc)} peak`,
        tag: `smart-return-${call.mint}-${stage}`, url: `/t?ca=${encodeURIComponent(call.mint)}&source=x-return`
      });
      if (delivered) call.milestones.push(...crossed);
    }
    await writeSmartCalls(state);
    if (now - Number(state.lastRosterRefreshAt || 0) > 60 * 60_000) await refreshSmartCallRoster(true);
  } catch (error) { console.warn(`[smart-calls] receipt tick: ${String(error?.message || error).slice(0, 120)}`); }
  finally { _smartCallReceiptRunning = false; }
}
async function smartCallRosterView() {
  const state = await refreshSmartCallRoster();
  const rows = state.activeWallets.slice(0, SMART_CALL_ROSTER_SIZE).map((wallet, index) => {
    const rec = state.roster[wallet] || {};
    const name = rec.name || (rec.handle ? `@${rec.handle}` : shortMint(wallet));
    const proof = Number(rec.wins) > 0
      ? `${rec.wins} tracked win${rec.wins === 1 ? "" : "s"}${rec.bestX > 1 ? ` · best ${rec.bestX}x` : ""}`
      : (Number(rec.winRate) > 0 ? `${Math.round(rec.winRate)}% provider win rate` : "learning");
    return `${index + 1}. <b>${escapeTelegramHtml(name)}</b> — ${escapeTelegramHtml(proof)}`;
  });
  const retained = Math.max(0, state.activeWallets.length - rows.length);
  return {
    text: [`📡 <b>Smart Calls — live Top ${rows.length}</b>`, retained ? `🏆 <b>+${retained} retained proven wallet${retained === 1 ? "" : "s"}</b> watched behind the scenes.` : "", "", ...rows, "", `<i>Winners stay in the database. New leaderboard standouts rotate in; a caller is not retired until at least ${SMART_CALL_MIN_SAMPLE} settled calls show weak results.</i>`].filter(Boolean).join("\n"),
    markup: { inline_keyboard: [[{ text: "Back to Signals", callback_data: "sig:back" }], gbTrenchBackRow()] }
  };
}

async function xScorecardTick() {
  if (!xConfigured() || !xScorecardOn()) return;
  try {
    const s = await readXCoins(); const now = Date.now();
    if (now - (s.lastScorecardAt || 0) < 6.8 * 86_400_000) return;   // ~weekly cadence
    const wk = Object.values(s.coins).filter((c) => c.entryMc > 0 && now - c.firstAt < 8 * 86_400_000);
    if (wk.length < 3) return;                                       // not enough to brag about yet
    if (!xBroadcastGateOk()) return;                                 // global gate — weekly post can wait a tick
    const scored = wk.map((c) => ({ ...c, mult: (c.peakMc > 0 && c.entryMc > 0) ? c.peakMc / c.entryMc : 0 })).sort((a, b) => b.mult - a.mult);
    const hits = scored.filter((c) => c.mult >= 2).length;
    const best = scored[0];
    const text = [
      "📊 SlimeWire — week in the trenches",
      `${wk.length} coins flagged · ${hits} did 2x+${best && best.mult >= 2 ? ` · best ${best.symbol ? "$" + best.symbol : ""} +${Math.round((best.mult - 1) * 100)}%` : ""}`,
      "Free reads all week. Tag @SlimeWirebot on any coin 🐸",
    ].join("\n").slice(0, 279);
    const res = await xPost({ text });
    if (res.ok) { xMarkBroadcast(); s.lastScorecardAt = now; await writeXCoins(s); console.log(`[xbot] 📊 scorecard posted id=${res.id}`); await xReplyOwnerNotify(`📊 X weekly scorecard posted (${wk.length} coins · ${hits} 2x+)`).catch(() => {}); }
  } catch (e) { console.log(`[xbot] scorecard tick err: ${String(e?.message || e).slice(0, 100)}`); }
}

// ---- 🐸 REPLY ENRICH: memory ("saw it Xh ago") + degen persona sign-off (text-only, always safe) ----
// Inserts extra beats ABOVE the CTA (last line), each only if it still fits the 279-char cap — so the
// call-to-action is never truncated. Applied to scan/map/chart replies at the poll layer (buildXReply
// stays untouched, keeping the working reply path safe).
async function xEnrichReplyText(mint, reply) {
  if (!reply || typeof reply.text !== "string") return reply;
  const lines = reply.text.split("\n");
  const cta = lines.length > 1 ? lines.pop() : "";
  const inserts = [];
  // Memory: if we surfaced this coin before, show the move since — instant differentiation + a receipt tease.
  try {
    const mem = await xCoinMemory(mint);
    if (mem && mem.entryMc > 0 && Date.now() - mem.firstAt > 25 * 60_000) {
      const cur = Number(reply.mc) || 0;
      const ago = xAgeLabel(Date.now() - mem.firstAt);
      if (cur > 0) {
        const mult = cur / mem.entryMc;
        inserts.push(mult >= 1.5 ? `📈 flagged this ${ago} ago at ${scanFmtMoney(mem.entryMc)} → now ${scanFmtMoney(cur)} (${mult.toFixed(1)}x)`
          : mult <= 0.6 ? `👀 saw this ${ago} ago at ${scanFmtMoney(mem.entryMc)} — down since`
          : `👀 seen it before — flagged ${ago} ago at ${scanFmtMoney(mem.entryMc)}`);
      }
    }
  } catch { /* memory is best-effort */ }
  // Persona: degen attitude on the verdict tone (read from the card glyphs already in the text).
  if (xPersonaOn()) {
    const tone = /⛔|🔴|🚨/.test(reply.text) ? "danger" : /⚠️|🟡/.test(reply.text) ? "warn" : "ok";
    const so = xDegenSignoff(tone, mint);
    if (so) inserts.push(so);
  }
  let out = [...lines];
  for (const ins of inserts) { if ([...out, ins, cta].filter(Boolean).join("\n").length <= 279) out.push(ins); }
  reply.text = [...out, cta].filter(Boolean).join("\n").slice(0, 279);
  return reply;
}
// Degen persona sign-off — attitude keyed to the verdict tone. Deterministic per coin so a reply is stable.
function xDegenSignoff(tone, seed) {
  const bank = tone === "danger"
    ? ["this one looks cooked 💀 be careful ser", "smells like exit liquidity 🚩", "verify before you send it 💀"]
    : tone === "warn"
    ? ["mid — size accordingly 🤝", "not the cleanest, trim risk ⚠️", "playable but keep a stop 🫡"]
    : ["actually not terrible ser 🐸", "structure looks ok — nfa 🫡", "clean-ish, do your own ape 🐸"];
  return bank[Math.abs(xSeedHash(String(seed || ""))) % bank.length];
}

function tickerTruthMetaForMint(mint) {
  const now = Date.now();
  for (const meta of tickerResolutionMetaCache.values()) {
    if (meta && now - Number(meta.at || 0) < 5 * 60_000 && Number(meta.exactMatches) > 1 && String(meta.selectedMint) === String(mint)) return meta;
  }
  return null;
}

