function tickerTruthLine(symbol, mint) {
  const key = String(symbol || "").replace(/^\$+/, "").trim().toLowerCase();
  const meta = tickerResolutionMetaCache.get(key);
  if (!meta || Date.now() - meta.at >= 5 * 60_000 || String(meta.selectedMint) !== String(mint)) return "";
  const picked = (meta.candidates || []).find((candidate) => candidate.mint === mint) || meta.candidates?.[0];
  if (!picked) return "";
  return `🧬 <b>Ticker Truth:</b> strongest exact market of ${meta.exactMatches} exact $${escapeTelegramHtml(meta.symbol)} contracts · MC <b>${escapeTelegramHtml(fmtTickerMarketUsd(picked.marketCap))}</b> · Vol <b>${escapeTelegramHtml(fmtTickerMarketUsd(picked.volume24h))}</b>`;
}

function tickerScanSelectionLine(symbol, target) {
  const key = String(symbol || "").replace(/^\$+/, "").trim().toLowerCase();
  if (!key) return "";
  if (!/^0x[0-9a-fA-F]{40}$/.test(String(target || ""))) return tickerTruthLine(symbol, target);
  const candidate = rhTickerCandidateForTarget(symbol, target);
  if (!candidate) return "";
  if (candidate.activityProof === true && !tickerRhCandidateHasActiveMarket(candidate)) {
    return `🧬 <b>Ticker match:</b> verified active Robinhood $${escapeTelegramHtml(String(symbol).toUpperCase())} contract · recent on-chain activity`;
  }
  return `🧬 <b>Ticker match:</b> strongest Robinhood $${escapeTelegramHtml(String(symbol).toUpperCase())} market by MC + liquidity + 24h volume · MC <b>${escapeTelegramHtml(fmtTickerMarketUsd(candidate.marketCap))}</b> · Liq <b>${escapeTelegramHtml(fmtTickerMarketUsd(candidate.liquidityUsd))}</b> · Vol <b>${escapeTelegramHtml(fmtTickerMarketUsd(candidate.volume24h))}</b>`;
}

function rhTickerCandidateForTarget(symbol, target) {
  const key = String(symbol || "").replace(/^\$+/, "").trim().toLowerCase();
  if (!key || !/^0x[0-9a-fA-F]{40}$/.test(String(target || ""))) return null;
  const cached = rhTickerTargetCache.get(key);
  const candidate = cached && Date.now() - Number(cached.at || 0) < 5 * 60_000 ? cached.candidate : null;
  return candidate && candidate.address.toLowerCase() === String(target).toLowerCase() ? candidate : null;
}

async function handleTickerTruthCallback(query) {
  const symbol = String(query?.data || "").slice(3).replace(/^\$+/, "").trim().toUpperCase();
  if (!/^[A-Z][A-Z0-9._]{1,19}$/.test(symbol)) return false;
  let meta = tickerResolutionMetaCache.get(symbol.toLowerCase());
  if (!meta || Date.now() - meta.at >= 5 * 60_000) {
    await resolveCashtagToMint(symbol).catch(() => null);
    meta = tickerResolutionMetaCache.get(symbol.toLowerCase());
  }
  const chatId = query?.message?.chat?.id;
  if (!chatId || !meta?.candidates?.length) {
    if (chatId) await say(chatId, `No fresh exact-match comparison is available for $${symbol} yet. Try posting the ticker again.`);
    return true;
  }
  const lines = [
    `🧬 <b>Ticker Truth · $${escapeTelegramHtml(symbol)}</b>`,
    `<i>${meta.exactMatches} exact-symbol contracts found, ranked by coherent market cap, liquidity and 24h volume. Open a scan for the full live security check.</i>`,
    ""
  ];
  for (let index = 0; index < meta.candidates.length; index++) {
    const candidate = meta.candidates[index];
    const selected = candidate.mint === meta.selectedMint;
    const sources = (candidate.sources || []).filter((source) => /jupiter|dexscreener|tracker/i.test(source)).map((source) => source.replace(/-/g, " ")).slice(0, 2).join(" + ");
    lines.push(`${selected ? "✅ <b>SELECTED</b>" : `${index + 1}. alternative`} · MC <b>${escapeTelegramHtml(fmtTickerMarketUsd(candidate.marketCap))}</b> · Liq ${escapeTelegramHtml(fmtTickerMarketUsd(candidate.liquidityUsd))} · 24h ${escapeTelegramHtml(fmtTickerMarketUsd(candidate.volume24h))}${sources ? `\n${escapeTelegramHtml(sources)}` : ""}\n<code>${escapeTelegramHtml(candidate.mint)}</code>`);
  }
  lines.push("", "<i>Selection favors the dominant real market plus live activity—not simply whichever tiny clone appears first in one index.</i>");
  const keyboard = { inline_keyboard: meta.candidates.slice(0, 4).map((candidate, index) => [{
    text: `${candidate.mint === meta.selectedMint ? "✅" : "📊"} ${index + 1} · MC ${fmtTickerMarketUsd(candidate.marketCap)}`,
    url: slimewireTokenLinks(candidate.mint).site
  }]) };
  await sayHtml(chatId, lines.join("\n"), keyboard);
  return true;
}

