    const feature = data === "sig:gx" ? "smartXReturn" : data === "sig:gmig" ? "smartMigration" : "smartDexPaid";
    const label = data === "sig:gx" ? "X-return alerts" : data === "sig:gmig" ? "Migration alerts" : "DEX-paid alerts";
    const e = (await readGroupBot()).groups[String(chatId)];
