async function applyBuyPrefInput(message, userId) {
  const pend = buyPrefPending.get(String(userId)); if (!pend) return false;
  if (Date.now() - pend.at > 180000) { buyPrefPending.delete(String(userId)); return false; }
  const raw = String(message.text || "").trim(); if (!raw || raw.startsWith("/")) return false;
  const v = Number(raw.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(v) || v <= 0) { await say(message.chat.id, "Send just the SOL amount, e.g. 0.5"); return true; }
  buyPrefPending.delete(String(userId));
  await setBuyPref(userId, pend.kind, v);
  const menu = buyPresetsMenu(userBuyPrefs(await readBuyPrefs(), userId));
  await sayHtml(message.chat.id, "✅ Saved.\n" + menu.text, menu.markup).catch(() => {});
  return true;
}
async function tgExecuteQuickBuy(userId, mint, amountSol, options = {}) {
  try {
    const [st, prefStore] = await Promise.all([readState().catch(() => null), readBuyPrefs()]);
    if (st && st.paused) return { ok: false, why: "trading is paused right now" };
    const amt = Number(amountSol);
    if (!Number.isFinite(amt) || amt <= 0) return { ok: false, why: "bad amount" };
    let selected;
    try {
      selected = await selectTgSolFundingWallet(userId, amt);
    } catch (error) {
      if (error?.needWallet) return { ok: false, needWallet: true };
      throw error;
    }
    const wallet = selected.wallet;
    const lamports = solToLamports(amt);
    const slippageBps = userBuyPrefs(prefStore, userId).slippageBps;
    // Dedup rapid identical double-taps within ~15s without collapsing different wallets/amounts/settings.
    const extraKeyParts = Array.isArray(options.idempotencyParts) ? options.idempotencyParts.map((v) => String(v || "").replace(/:/g, "_")).filter(Boolean) : [];
    const stableKey = String(options.idempotencyKey || "").trim().replace(/:/g, "_");
    const attemptId = stableKey
      ? [stableKey, mint, wallet.publicKey || "", String(lamports), `slip${slippageBps}`].join(":")
      : [mint, wallet.publicKey || "", String(lamports), `slip${slippageBps}`, ...extraKeyParts, Math.floor(Date.now() / 15000)].join(":");
    const result = await runIdempotentMoneyOp("tg-quick-buy", userId, attemptId,
      () => buyTokenForPlan(wallet, mint, lamports, slippageBps, { trackTokenDelta: true, userId }));
    if (result) {
      const tradeSource = String(options.source || "tg-quick-buy").replace(/[^a-z0-9_-]/gi, "").slice(0, 40) || "tg-quick-buy";
      await recordTradeEvents([{ userId, type: "buy", source: tradeSource, tokenMint: mint, walletLabel: wallet.label, walletPublicKey: wallet.publicKey, solLamportsSpent: String(result.amountLamports || lamports), ...(result.tokenAmount != null ? { tokenAmount: String(result.tokenAmount) } : {}), signature: result.signature }]).catch(() => {});
    }
    return { ok: Boolean(result), result, wallet, walletIndex: selected.walletIndex, amt };
  } catch (e) {
    return {
      ok: false,
      why: (friendlyError ? friendlyError(e) : (e && e.message)) || "buy failed",
      outcomeUnknown: Boolean(e?.tradeSubmissionAmbiguous),
      partialHashes: Array.isArray(e?.partialHashes) ? e.partialHashes : []
    };
  }
}
