async function handleQuickBuyCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("qb:")) return false;
  const ack = (t, alert) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(alert) } : {}) }).catch(() => {});
  const mCustom = data.match(/^qb:x:([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (mCustom) {
    if (!walletsForOwner(await readWalletStore(), userId).length) { await ack(noWalletAckText(await funnelNoWallet(userId)), true); return true; }
    tgQuickBuyPending.set(String(userId), { mint: mCustom[1], at: Date.now() });
    await ack("Sent you a DM — reply with the SOL amount to buy.", true);
    await sayHtml(userId, `⚡ <b>Quick buy</b> — reply with the SOL amount to ape <code>${escapeTelegramHtml(mCustom[1])}</code> (e.g. <b>0.75</b>).`).catch(() => {});
    return true;
  }
  const m = data.match(/^qb:([\d.]+):([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (!m) { await ack(); return true; }
  const amt = m[1], mint = m[2];
  await ack(`⚡ Buying ◎${amt} now — receipt will arrive in your DM.`, false);
  const r = await tgExecuteQuickBuy(userId, mint, amt);
  if (r.needWallet) { await funnelNoWallet(userId); return true; }
  if (!r.ok) {
    await say(userId, `⚠️ Quick Buy didn't land\n${r.why || "Try again in a few seconds."}`).catch(() => {});
    return true;
  }
  await quickBuySendReceipt(userId, mint, amt, r.result);
  return true;
}
async function tgArmRhQuickExit(userId, selected, tokenAddress, symbol, exit, attemptKey) {
  if (!exit?.enabled || exit.mode === "manual") return { armed: null, armError: "" };
  const entry = await rhImpliedPriceUsd(tokenAddress, rhFeeEvmWallet(CONFIG.appSecret, CONFIG.rhChainRpcUrl).address).catch(() => null);
  const entryPriceUsd = Number(entry?.priceUsd) || 0;
  if (!(entryPriceUsd > 0)) return { armed: null, armError: "could not read the post-buy entry price" };
  const exitGroup = `tg-${crypto.createHash("sha256").update(String(attemptKey || tokenAddress)).digest("hex").slice(0, 20)}`;
  const common = {
    walletIndex: String(selected.walletIndex),
    walletPublicKey: selected.wallet.publicKey,
    tokenAddress,
    symbol: symbol || "",
    entryPriceUsd,
    exitGroup
  };
  const jobs = [];
  if (exit.mode === "ladder") {
    exit.takeProfitLadder.forEach((rung, index) => {
      const sellPercent = index === exit.takeProfitLadder.length - 1
        ? 100
        : Math.max(1, Math.min(100, Math.round(Number(rung.sellPercent) || 100)));
      jobs.push({
        slot: `tg-ladder-${index + 1}`,
        body: { ...common, exitSlot: `tg-ladder-${index + 1}`, takeProfitPct: rung.pct, stopLossPct: 0, sellPercent, closesPosition: index === exit.takeProfitLadder.length - 1 }
      });
    });
    if (exit.stopLossPct > 0) {
      jobs.push({ slot: "tg-ladder-stop", body: { ...common, exitSlot: "tg-ladder-stop", takeProfitPct: 0, stopLossPct: exit.stopLossPct, sellPercent: 100, closesPosition: true } });
    }
  } else {
    jobs.push({
      slot: "tg-protected",
      body: { ...common, exitSlot: "tg-protected", takeProfitPct: exit.takeProfitPct, stopLossPct: exit.stopLossPct, sellPercent: 100, closesPosition: true }
    });
  }
  const results = [];
  for (const job of jobs) {
    try {
      const result = await runIdempotentMoneyOp(
        "tg-rh-quick-exit",
        userId,
        `${attemptKey}:${tokenAddress.toLowerCase()}:${job.slot}`,
        () => webRhArmGuard(userId, job.body),
        { ttlMs: 24 * 60 * 60_000 }
      );
      results.push({ ok: Boolean(result?.ok), slot: job.slot });
    } catch (error) {
      results.push({ ok: false, slot: job.slot, error: friendlyError(error) });
    }
  }
  const armedCount = results.filter((row) => row.ok).length;
  const firstError = results.find((row) => !row.ok)?.error || "";
  if (armedCount !== jobs.length) {
    return { armed: armedCount ? { ...exit, guardCount: armedCount, summary: `${exit.summary} (${armedCount}/${jobs.length} guards armed)` } : null, armError: firstError || "not every exit guard armed" };
  }
  return { armed: { ...exit, guardCount: armedCount, summary: exit.summary }, armError: "" };
}

// 🪶⚡ Robinhood one-tap trades from group cards (PvP feed, scan cards): rqb:<sol>:<0x> buys the coin
// with SOL from the tapper's OWN SlimeWire wallet (auto-bridged to RH ETH), rqs:<pct>:<0x> sells.
// Same custodial path the site uses (webRhTrade → Relay), so honeypot guard + idempotency come free.
async function handleRhQuickTradeCallback(query, userId) {
  const data = String(query?.data || "");
  const ack = (t, alert) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(alert) } : {}) }).catch(() => {});
  const mPreset = data.match(/^rqbp:(?:([\d.]+):)?(0x[0-9a-fA-F]{40})$/);
  const mBuy = data.match(/^rqb:([\d.]+):(0x[0-9a-fA-F]{40})$/);
  const mSell = data.match(/^rqs:(\d{1,3}):(0x[0-9a-fA-F]{40})$/);
  if (!mPreset && !mBuy && !mSell) { await ack(); return true; }
  if (!walletsForOwner(await readWalletStore(), userId).length) { await ack(noWalletAckText(await funnelNoWallet(userId)), true); return true; }
  const tokenAddress = mPreset ? mPreset[2] : (mBuy || mSell)[2];
  const prefs = userBuyPrefs(await readBuyPrefs(), userId);
  const savedExit = tgQuickExitConfig(prefs);
  const sellKb = { inline_keyboard: [
    [{ text: "💸 Sell 50%", callback_data: `rqs:50:${tokenAddress}` }, { text: "💸 Sell 100%", callback_data: `rqs:100:${tokenAddress}` }],
    [{ text: "🔄 Buy again", callback_data: `rqbp:${prefs.quickAmount}:${tokenAddress}` }, { text: "⚙️ Preset", callback_data: "pe:open" }],
  ] };
  if (mPreset || mBuy) {
    const amt = mPreset ? (Number(mPreset[1]) > 0 ? Number(mPreset[1]) : prefs.quickAmount) : Number(mBuy[1]);
    if (mPreset && savedExit.enabled) {
      try {
        await grantTelegramQuickExitPermission(userId, `Robinhood ${savedExit.mode} preset buy`);
      } catch (error) {
        await ack(`Protected buy not sent: ${friendlyError(error)}`, true);
        return true;
      }
    }
    await ack("Buying with SOL now. The bridge + trade can take 30–90 seconds; progress is in your DM.", true);
    let selected = null;
    let progress = null;
    try {
      selected = await selectTgSolFundingWallet(userId, amt);
      const walletLabel = escapeTelegramHtml(selected.wallet.label || `Wallet ${selected.walletIndex}`);
      progress = await telegram("sendMessage", {
        chat_id: userId,
        text: [
          "🪶 <b>Robinhood buy started</b>",
          `├ Using <b>${walletLabel}</b>`,
          `├ Converting <b>${amt} SOL</b> to Robinhood ETH`,
          `└ Then buying <code>${escapeTelegramHtml(shortMint(tokenAddress))}</code>`,
          "",
          "<i>Usually 30–90 seconds. Please don't tap Buy again.</i>"
        ].join("\n"),
        parse_mode: "HTML",
        disable_web_page_preview: true
      }).catch(() => null);
      const callbackAttempt = crypto.createHash("sha256").update(String(query.id || crypto.randomUUID())).digest("hex").slice(0, 20);
      const r = await webRhTrade(userId, {
        walletIndex: String(selected.walletIndex), walletPublicKey: selected.wallet.publicKey,
        side: "buy", tokenAddress, amountSol: amt, payCurrency: "sol",
        tradeAttemptId: `tg-rqb-${userId}-${callbackAttempt}`,
      });
      const exitResult = mPreset
        ? await tgArmRhQuickExit(userId, selected, tokenAddress, r.outSymbol || "", savedExit, `tg-rqb-${userId}-${callbackAttempt}`)
        : { armed: null, armError: "" };
      const exitLine = exitResult.armError
        ? `├ ⚠️ Buy landed; exit needs attention: <b>${escapeTelegramHtml(exitResult.armError)}</b>`
        : exitResult.armed
          ? `├ 🎯 Exit armed: <b>${escapeTelegramHtml(exitResult.armed.summary)}</b>`
          : mPreset && savedExit.mode === "manual"
            ? "├ 🖐 Exit: <b>Manual</b> — no automatic selling"
            : "";
      const successText = [
        `🪶 ✅ <b>Bought ${escapeTelegramHtml(String(r.outSymbol || shortMint(tokenAddress)).slice(0, 12))}</b> with <b>${amt} ◎</b>`,
        `├ Wallet: <b>${walletLabel}</b>`,
        `├ Got <b>${escapeTelegramHtml(String(r.outFormatted || "?"))}</b> · now holding ${escapeTelegramHtml(String(r.tokenBalance ?? "?"))}`,
        exitLine,
        `└ <a href="${r.explorerTx}">tx on Blockscout</a>`,
      ].filter(Boolean).join("\n");
      if (progress?.message_id) {
        await telegram("editMessageText", { chat_id: userId, message_id: progress.message_id, text: successText, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: sellKb }).catch(() => sayHtml(userId, successText, sellKb));
      } else await sayHtml(userId, successText, sellKb).catch(() => {});
    } catch (error) {
      const failedText = `🪶 <b>Buy didn't land</b>\n${escapeTelegramHtml(friendlyError(error))}`;
      await audit("tg_rh_quick_buy_failed", { userId, tokenAddress, walletIndex: selected?.walletIndex || null, amountSol: amt, error: friendlyError(error) }).catch(() => {});
      if (progress?.message_id) {
        await telegram("editMessageText", { chat_id: userId, message_id: progress.message_id, text: failedText, parse_mode: "HTML", disable_web_page_preview: true }).catch(() => sayHtml(userId, failedText));
      } else await sayHtml(userId, failedText).catch(() => {});
    }
    return true;
  }
  const pct = Math.min(100, Math.max(1, Number(mSell[1])));
  await ack(`Selling ${pct}% now; receipt will land in your DM.`, true);
  let selected = null;
  try {
    selected = await selectTgRhTokenWallet(userId, tokenAddress);
    const callbackAttempt = crypto.createHash("sha256").update(String(query.id || crypto.randomUUID())).digest("hex").slice(0, 20);
    const r = await webRhTrade(userId, {
      walletIndex: String(selected.walletIndex), walletPublicKey: selected.wallet.publicKey,
      side: "sell", tokenAddress, percent: pct,
      tradeAttemptId: `tg-rqs-${userId}-${callbackAttempt}`,
    });
    const settlement = r.solCashout?.outSol
      ? `├ Returned <b>${escapeTelegramHtml(String(r.solCashout.outSol))} SOL</b> to this wallet automatically`
      : (r.solCashoutError
        ? "├ Sale landed; proceeds remain safe in this wallet while SOL settlement is unavailable"
        : `├ Received <b>${escapeTelegramHtml(String(r.outFormatted || "?"))} ${escapeTelegramHtml(String(r.outSymbol || "ETH"))}</b>`);
    await sayHtml(userId, [
      `🪶 ✅ <b>Sold ${pct}%</b> of <code>${escapeTelegramHtml(shortMint(tokenAddress))}</code>`,
      `├ Wallet: <b>${escapeTelegramHtml(selected.wallet.label || `Wallet ${selected.walletIndex}`)}</b>`,
      settlement,
      `└ <a href="${r.explorerTx}">tx on Blockscout</a>`,
    ].join("\n"), pct < 100 ? sellKb : undefined).catch(() => {});
  } catch (error) {
    await audit("tg_rh_quick_sell_failed", { userId, tokenAddress, walletIndex: selected?.walletIndex || null, percent: pct, error: friendlyError(error) }).catch(() => {});
    await sayHtml(userId, `🪶 Sell didn't land: ${escapeTelegramHtml(friendlyError(error))}`).catch(() => {});
  }
  return true;
}

// Main-menu Buy and /buy-without-an-argument are CA-first. They intentionally open a trade panel,
// not a SlimeShield verdict: the user already chose Buy and should never be bounced into a scam card.
// Both chains share the same compact amount/preset controls used under scan and buy-bot cards.
async function sendDmCaBuyPanel(chatId, userId, target) {
  const rh = /^0x[0-9a-fA-F]{40}$/.test(String(target || ""));
  let symbol = shortMint(target), mc = 0, liq = 0, volume24h = 0;
  if (rh) {
    const info = await scanFastTimeout(gatherRhScan(target), 6_000, null);
    symbol = firstString(info?.symbol, symbol);
    mc = Number(info?.mc) || 0;
    liq = Number(info?.liq) || 0;
    volume24h = Number(info?.vol24) || 0;
  } else {
    const scan = await scanFastTimeout(gatherSlimeScan(target), 6_000, null);
    symbol = firstString(scan?.meta?.symbol, scan?.bonding?.symbol, symbol);
    const stats = scan ? scanMarketStatsFromSources({ meta: scan.meta, bonding: scan.bonding, best: scan.best, rug: scan.rug, supply: scan.supply, mint: target }) : null;
    mc = Number(stats?.mc) || 0;
    liq = Number(stats?.liq) || 0;
    volume24h = scanVolumeWindowValue("h24", scan?.meta, scan?.bonding, scan?.best);
  }
  const keyboard = await telegramQuickBuyPanelKeyboard(target, userId);
  const links = slimewireTokenLinks(target);
  keyboard.inline_keyboard.push([telegramWebLoginButton("🌐 Web Quick Buy", links.telegramQuickLogin, links.quick)]);
  const market = [mc > 0 ? `MC <b>${scanFmtMoney(mc)}</b>` : "", liq > 0 ? `Liq <b>${scanFmtMoney(liq)}</b>` : "", `24h Vol <b>${volume24h > 0 ? scanFmtMoney(volume24h) : "checking"}</b>`].filter(Boolean).join(" · ");
  await sayHtml(chatId, [
    `⚡ <b>Buy $${escapeTelegramHtml(String(symbol).replace(/^\$+/, ""))}</b>${rh ? " · Robinhood Chain" : ""}`,
    `<code>${escapeTelegramHtml(target)}</code>`,
    market,
    "",
    "<i>Tap an amount once to buy from your SlimeWire wallet.</i>"
  ].join("\n"), keyboard);
}

// Telegram has no wallet selector on a compact scan card. For either supported chain, prefer Wallet 1
// when it can cover the SOL-funded buy, otherwise transparently use the user's best-funded normal
// wallet. Never route a personal quick buy through an internal volume/ghost wallet.
async function selectTgSolFundingWallet(userId, amountSol) {
  const store = await readWalletStore();
  const owned = walletsForOwner(store, userId);
  const visible = owned.map((wallet, index) => ({ wallet, walletIndex: index + 1 }))
    .filter(({ wallet }) => !wallet.volumeBot && !wallet.ephemeral);
  const candidates = visible.length ? visible : owned.map((wallet, index) => ({ wallet, walletIndex: index + 1 }));
  if (!candidates.length) {
    const error = new Error("Create a SlimeWire wallet first.");
    error.needWallet = true;
    throw error;
  }
  const requiredLamports = solToLamports(Number(amountSol)) + 2_500_000;
  const cachedRows = () => candidates.map((entry) => ({
    ...entry,
    balanceLamports: Number(getTimedCache(solBalanceCache, String(entry.wallet.publicKey), CONFIG.balanceCacheTtlMs) ?? 0)
  }));
  let balances = cachedRows();
  const preferred = balances[0];
  if (preferred?.balanceLamports >= requiredLamports) return preferred;
  let best = balances.slice().sort((a, b) => b.balanceLamports - a.balanceLamports)[0];
  if (best?.balanceLamports >= requiredLamports) return best;

  // Cold or recently funded wallet: one priority batch read is faster than
  // force-reading Wallet 1 and then every other wallet separately.
  const primed = await primeSolBalancesBatch(candidates.map((entry) => entry.wallet.publicKey), { priority: true }).catch(() => 0);
  if (primed > 0) {
    balances = cachedRows();
  } else {
    balances = await runWithConcurrency(candidates, 4, async (entry) => ({
      ...entry,
      balanceLamports: Number(await getSolBalanceCached(new PublicKey(entry.wallet.publicKey), { force: true, priority: true }).catch(() => 0))
    }));
  }
  const refreshedPreferred = balances[0];
  if (refreshedPreferred?.balanceLamports >= requiredLamports) return refreshedPreferred;
  best = balances.slice().sort((a, b) => b.balanceLamports - a.balanceLamports)[0];
  if (best?.balanceLamports >= requiredLamports) return best;
  throw new Error(`Your best-funded wallet has ${lamportsToSol(best?.balanceLamports || 0)} SOL. Buying ${amountSol} SOL needs about 0.0025 SOL extra for network fees.`);
}

// A buy may have used Wallet 2+ (because that is where the SOL was), so receipt sell buttons locate
// the wallet that really holds the token instead of incorrectly trying Wallet 1 again.
async function selectTgRhTokenWallet(userId, tokenAddress) {
  const store = await readWalletStore();
  const owned = walletsForOwner(store, userId);
  const visible = owned.map((wallet, index) => ({ wallet, walletIndex: index + 1 }))
    .filter(({ wallet }) => !wallet.volumeBot && !wallet.ephemeral);
  const candidates = visible.length ? visible : owned.map((wallet, index) => ({ wallet, walletIndex: index + 1 }));
  const balances = await runWithConcurrency(candidates, 4, async (entry) => {
    try {
      const keypair = decryptWallet(entry.wallet);
      const evmAddress = evmAddressFromSolana(keypair.secretKey);
      const balance = await rhErc20Balance(tokenAddress, evmAddress, CONFIG.rhChainRpcUrl);
      return { ...entry, tokenRaw: BigInt(balance.raw || 0) };
    } catch { return { ...entry, tokenRaw: 0n }; }
  });
  const best = balances.sort((a, b) => (a.tokenRaw === b.tokenRaw ? 0 : a.tokenRaw > b.tokenRaw ? -1 : 1))[0];
  if (!best || best.tokenRaw <= 0n) throw new Error("None of your SlimeWire wallets holds this Robinhood coin.");
  return best;
}
// ⚡ QUICK BUY (preset) — one tap on any group/scan card buys the tapper's saved preset amount from
// their own wallet AND arms their saved take-profit / stop-loss, all without leaving the group. Reuses
// the idempotent own-wallet buy (tgExecuteQuickBuy) + the site's auto-exit engine.
async function tgExecuteQuickBuyPreset(userId, mint, options = {}) {
  const prefs = userBuyPrefs(await readBuyPrefs(), userId);
  const exit = tgQuickExitConfig(prefs);
  const requestedAmount = Number(options.amountSol);
  const amountSol = Number.isFinite(requestedAmount) && requestedAmount > 0 ? requestedAmount : prefs.quickAmount;
  const extraParts = Array.isArray(options.idempotencyParts) ? options.idempotencyParts : [];
  let automationPermission = null;
  if (exit.enabled) {
    try {
      automationPermission = await grantTelegramQuickExitPermission(userId, `Solana ${exit.mode} preset buy`);
    } catch (error) {
      return { ok: false, why: `${friendlyError(error)} No buy was sent.`, amt: amountSol, exit, permissionError: true };
    }
  }
  if (!exit.enabled) {
    const r = await tgExecuteQuickBuy(userId, mint, amountSol, {
      idempotencyParts: [`mode-${exit.mode}`, "preset", ...extraParts],
      source: options.source
    });
    return { ...r, amt: amountSol, exit, armed: null, armError: "" };
  }

  // Protected Telegram presets use the same reserve-before-spend path as the
  // website. Never raw-buy first and attempt to bolt a stop onto the bag later.
  try {
    const st = await readState().catch(() => null);
    if (st?.paused) return { ok: false, why: "trading is paused right now", amt: amountSol, exit };
    const selected = await selectTgSolFundingWallet(userId, amountSol);
    const stableKey = String(options.idempotencyKey || "").trim().replace(/:/g, "_");
    const attemptId = stableKey || [
      "tg-protected-preset",
      mint,
      selected.wallet.publicKey,
      amountSol,
      exit.mode,
      exit.ladderPreset || "single",
      exit.takeProfitPct || 0,
      exit.stopLossPct || 0,
      ...extraParts,
      Math.floor(Date.now() / 15000)
    ].join(":");
    const result = await webTradeBuy(userId, {
      walletIndex: selected.walletIndex,
      walletPublicKey: selected.wallet.publicKey,
      tokenMint: mint,
      amountSol,
      slippageBps: prefs.slippageBps,
      takeProfitPct: String(exit.takeProfitPct || 0),
      stopLossPct: String(exit.stopLossPct || 0),
      takeProfitLadder: exit.takeProfitLadder,
      breakEvenAfterTp1: exit.mode === "ladder" && exit.stopLossPct > 0,
      sellPercent: "100",
      autoExit: true,
      protectionRequired: true,
      tradeAttemptId: attemptId
    });
    const armed = result.autoExitArmed
      ? { ...exit, planId: result.autoExitPlan?.id || null, summary: exit.summary }
      : null;
    return {
      ok: true,
      result,
      wallet: selected.wallet,
      walletIndex: selected.walletIndex,
      amt: amountSol,
      exit,
      armed,
      armError: result.autoExitError || (armed ? "" : "the saved exit did not arm")
    };
  } catch (error) {
    return {
      ok: false,
      why: friendlyError(error) || "buy failed",
      outcomeUnknown: Boolean(error?.tradeSubmissionAmbiguous),
      partialHashes: Array.isArray(error?.partialHashes) ? error.partialHashes : [],
      amt: amountSol,
      exit
    };
  }
}
async function handleQuickBuyPresetCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("qbp:")) return false;
  const ack = (t, alert) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(alert) } : {}) }).catch(() => {});
  const m = data.match(/^qbp:(?:([\d.]+):)?([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (!m) { await ack(); return true; }
  const mint = m[2];
  if (!walletsForOwner(await readWalletStore(), userId).length) {
    await ack(noWalletAckText(await funnelNoWallet(userId)), true);
    return true;
  }
  const prefs = userBuyPrefs(await readBuyPrefs(), userId);
  const requestedAmount = Number(m[1]);
  const displayAmount = Number.isFinite(requestedAmount) && requestedAmount > 0 ? requestedAmount : prefs.quickAmount;
  // A swap can outlast Telegram's callback spinner. Confirm the tap immediately, then deliver the
  // durable success/failure receipt in DM instead of making the button look unresponsive.
  await ack(`Buying ◎${displayAmount} with your saved preset now. Receipt will land in your DM.`, true);
  const r = await tgExecuteQuickBuyPreset(userId, mint, { amountSol: m[1] || undefined });
  if (r.needWallet) {
    await funnelNoWallet(userId);
    return true;
  }
  if (!r.ok) {
    await audit("tg_quick_buy_failed", { userId, mint, amountSol: r.amt || null, error: r.why || "buy failed" }).catch(() => {});
    await sayHtml(userId, `⚠️ <b>Quick Buy didn't land</b>\n${escapeTelegramHtml(r.why || "Try again in a second.")}`).catch(() => {});
    return true;
  }
  await quickBuySendReceipt(userId, mint, r.amt, r.result, { preset: r.exit, armed: r.armed, armError: r.armError });
  return true;
}
// ⚙️ PRESET editor — opens right in the group (button-only, no typing, no DM). Every tap edits the
// TAPPER'S own saved preset (keyed by their userId), so it's collision-safe in a shared chat; the editor
// message is owned by whoever opened it so someone else's taps don't move its displayed numbers.
const PE_AMOUNTS = [0.05, 0.1, 0.25, 0.5, 1, 2];
const PE_TP = [0, 25, 50, 100, 200];
const PE_SL = [0, 8, 10, 20, 30];
function presetEditorView(prefs, uid) {
  const mark = (on, label) => (on ? "• " : "") + label;
  const exit = tgQuickExitConfig(prefs);
  return {
    text: [
      "⚙️ <b>Your Quick Buy preset</b>",
      "",
      `Amount: <b>${prefs.quickAmount} SOL</b>`,
      `Exit mode: <b>${escapeTelegramHtml(exit.summary)}</b>`,
      `Saved TP: <b>${prefs.takeProfitPct ? "+" + prefs.takeProfitPct + "%" : "off"}</b> · Saved SL: <b>${prefs.stopLossPct ? "-" + prefs.stopLossPct + "%" : "off"}</b>`,
      "",
      "🖐 <b>Manual</b> means new preset buys never auto-sell. Existing armed exits keep running until you cancel them in Positions.",
      "🛡 <b>TP/SL</b> uses the saved percentages. 🪜 <b>Ladder</b> sells in stages; SL can stay on or off.",
      "",
      "<i>Tapping a protected or ladder Buy grants/renews 30-day managed-wallet automation so exits keep working after Telegram closes. You can revoke it from Profile or Wallets.</i>"
    ].join("\n"),
    markup: { inline_keyboard: [
      PE_AMOUNTS.slice(0, 3).map((a) => ({ text: mark(prefs.quickAmount === a, `${a} SOL`), callback_data: `pe:a:${a}:${uid}` })),
      PE_AMOUNTS.slice(3).map((a) => ({ text: mark(prefs.quickAmount === a, `${a} SOL`), callback_data: `pe:a:${a}:${uid}` })).concat([{ text: "✏️ amount", callback_data: `pe:ax:${uid}` }]),
      [
        { text: mark(prefs.exitMode === "manual", "🖐 Manual"), callback_data: `pe:m:manual:${uid}` },
        { text: mark(prefs.exitMode === "protected", "🛡 TP/SL"), callback_data: `pe:m:protected:${uid}` },
        { text: mark(prefs.exitMode === "ladder", "🪜 Ladder"), callback_data: `pe:m:ladder:${uid}` }
      ],
      PE_TP.slice(0, 3).map((t) => ({ text: mark(prefs.takeProfitPct === t, t === 0 ? "TP off" : `+${t}%`), callback_data: `pe:tp:${t}:${uid}` })),
      PE_TP.slice(3).map((t) => ({ text: mark(prefs.takeProfitPct === t, `+${t}%`), callback_data: `pe:tp:${t}:${uid}` })).concat([{ text: "✏️ Custom TP", callback_data: `pe:tpx:${uid}` }]),
      PE_SL.slice(0, 3).map((s) => ({ text: mark(prefs.stopLossPct === s, s === 0 ? "SL off" : `-${s}%`), callback_data: `pe:sl:${s}:${uid}` })),
      PE_SL.slice(3).map((s) => ({ text: mark(prefs.stopLossPct === s, `-${s}%`), callback_data: `pe:sl:${s}:${uid}` })).concat([{ text: "✏️ Custom SL", callback_data: `pe:slx:${uid}` }]),
      [
        { text: mark(prefs.ladderPreset === "safe", "Safe"), callback_data: `pe:l:safe:${uid}` },
        { text: mark(prefs.ladderPreset === "balanced", "Balanced"), callback_data: `pe:l:balanced:${uid}` },
        { text: mark(prefs.ladderPreset === "runner", "Runner"), callback_data: `pe:l:runner:${uid}` }
      ],
      [{ text: "💰 Existing positions / exits", callback_data: "positions_overview" }],
      [{ text: "✅ Done", callback_data: `pe:x:${uid}` }]
    ] }
  };
}
async function handlePresetEditorCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("pe:")) return false;
  const chatId = query.message?.chat?.id, messageId = query.message?.message_id;
  const ack = (t, a) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(a) } : {}) }).catch(() => {});
  if (data === "pe:open") {
    const prefs = userBuyPrefs(await readBuyPrefs(), userId);
    const v = presetEditorView(prefs, userId);
    await telegram("sendMessage", { chat_id: chatId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => {});
    await ack(); return true;
  }
  const parts = data.split(":");
  const kind = parts[1];
  const owner = ["x", "ax", "tpx", "slx"].includes(kind) ? parts[2] : parts[3];
  if (String(userId) !== String(owner)) { await ack("Tap ⚙️ Preset to open your own.", true); return true; }
  if (kind === "x") {
    if (messageId) await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => {});
    await ack("Saved ✅"); return true;
  }
  if (kind === "ax") {   // ✏️ custom amount → clean in-chat typed input (auto-deletes), re-renders this editor
    await ack();
    await promptCleanInput(chatId, userId, "💰 Reply with your <b>Quick Buy amount</b> in SOL (e.g. <code>0.5</code>).", "pe_amt", messageId);
    return true;
  }
  if (kind === "tpx" || kind === "slx") {
    await ack();
    await promptCleanInput(
      chatId,
      userId,
      kind === "tpx"
        ? "🎯 Reply with your <b>take-profit %</b> (e.g. <code>75</code>), or <code>0</code> to turn TP off."
        : "🛡 Reply with your <b>stop-loss %</b> (e.g. <code>12</code>), or <code>0</code> to turn SL off.",
      kind === "tpx" ? "pe_tp" : "pe_sl",
      messageId
    );
    return true;
  }
  if (kind === "m" && ["manual", "protected", "ladder"].includes(parts[2])) {
    await setBuyPref(userId, "exitMode", parts[2]);
  } else if (kind === "l" && TG_QUICK_EXIT_LADDERS[parts[2]]) {
    await setBuyPref(userId, "ladderPreset", parts[2]);
  } else {
  const kindMap = { a: "amount", tp: "tp", sl: "sl" };
  if (kindMap[kind]) {
    await setBuyPref(userId, kindMap[kind], Number(parts[2]));
  } else {
    await ack(); return true;
  }
  }
  const v = presetEditorView(userBuyPrefs(await readBuyPrefs(), userId), userId);
  if (messageId) await telegram("editMessageText", { chat_id: chatId, message_id: messageId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => {});
  await ack("Saved"); return true;
}
// Typed custom SOL amount for ⚡ quick buy (DM). Returns true when it consumed the message.
async function applyTgQuickBuyInput(message, userId) {
  const pend = tgQuickBuyPending.get(String(userId));
  if (!pend) return false;
  if (Date.now() - pend.at > 180000) { tgQuickBuyPending.delete(String(userId)); return false; }
  const raw = String(message.text || "").trim();
  if (!raw || raw.startsWith("/")) return false;
  const amt = Number(raw.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(amt) || amt <= 0) { await say(message.chat.id, "Send just the SOL amount, e.g. 0.5"); return true; }
  tgQuickBuyPending.delete(String(userId));
  const r = await tgExecuteQuickBuyPreset(userId, pend.mint, { amountSol: amt, idempotencyParts: ["typed-custom"] });
  if (r.needWallet) { await say(message.chat.id, "Make a wallet first — /start."); return true; }
  if (!r.ok) { await say(message.chat.id, `Buy didn't land: ${r.why || "try again"}.`); return true; }
  await quickBuySendReceipt(userId, pend.mint, amt, r.result, { preset: r.exit, armed: r.armed, armError: r.armError });
  return true;
}

// ⚡ In-DM one-tap SELL — sells `pct`% of a mint across ALL the user's SlimeWire wallets that hold it,
// straight from Telegram (no site redirect). Mirrors tgExecuteQuickBuy: own wallets, own pre-authorized
// action, idempotent per 15s bucket so a double-tap can't double-sell. Advisory nothing — the user tapped.
async function tgExecuteQuickSell(userId, mint, pct, {
  idempotencyKey = "",
  trustedPriorSellAcknowledgements = []
} = {}) {
  try {
    const [st, walletStore, prefStore] = await Promise.all([
      readState().catch(() => null),
      readWalletStore(),
      readBuyPrefs()
    ]);
    if (st && st.paused) return { ok: false, why: "trading is paused right now" };
    const wallets = walletsForOwner(walletStore, userId);
    if (!wallets || !wallets.length) return { ok: false, needWallet: true };
    const slippageBps = userBuyPrefs(prefStore, userId).slippageBps;
    const mintKey = new PublicKey(mint);
    const scanBalances = (force = false) => runWithConcurrency(wallets, Math.min(6, wallets.length), async (wallet) => {
      try {
        const token = await getTokenBalanceForMintCached(new PublicKey(wallet.publicKey), mintKey, { force, priority: true });
        return { wallet, balance: { ok: true, balance: Number(token?.uiAmount || 0) } };
      } catch (error) {
        return { wallet, balance: { ok: false, balance: null, error: friendlyError(error) } };
      }
    });
    let balanceRows = await scanBalances(false);
    // A cached zero can be stale after an external transfer. Refresh once only
    // when the fast pass found no holder, never before every sell.
    if (!balanceRows.some((row) => row.balance.ok && row.balance.balance > 0)) balanceRows = await scanBalances(true);
    const holders = balanceRows.filter((row) => row.balance.ok && row.balance.balance > 0).map((row) => row.wallet);
    const balanceErrors = balanceRows
      .filter((row) => !row.balance.ok)
      .map((row) => `${row.wallet.label || shortMint(row.wallet.publicKey)}: ${row.balance.error || "balance unavailable"}`);
    if (!holders.length) {
      if (balanceErrors.length) return { ok: false, why: `token balance temporarily unavailable (${balanceErrors[0]})` };
      return { ok: false, why: "you don't hold this coin in your SlimeWire wallets" };
    }
    const sellAttemptIdForWallet = (wallet) => (idempotencyKey
      ? `${idempotencyKey}:${mint}:${pct}:${wallet.publicKey}`
      : `${mint}:${pct}:${wallet.publicKey}:${Math.floor(Date.now() / 15000)}`);
    const sellRows = await runWithConcurrency(holders, Math.min(3, holders.length), async (w) => {
      const attemptId = sellAttemptIdForWallet(w);
      const trustedPrior = objectRows(trustedPriorSellAcknowledgements).find((row) => (
        String(row.walletPublicKey || "") === String(w.publicKey || "")
      ));
      try {
        const r = await runIdempotentMoneyOp("tg-quick-sell", userId, attemptId, () => (
          withExitSellLock(userId, w.publicKey, mint, () => (
            executeManualSolSellWithProtection(w, mint, pct, (onSigned) => (
              sellTokenFromWallet(w, mint, pct, slippageBps, { userId, priority: true, onSigned })
            ), {
              userId,
              manualSellAttemptId: attemptId,
              trustedPriorManualSellAttemptId: trustedPrior?.manualSellAttemptId,
              trustedPriorManualSellSignature: trustedPrior?.signature
            })
          ))
        ));
        if (r) {
          const receiptAmounts = confirmedSolSellReceiptAmounts(r);
          const keep = positiveBigIntOrZero(receiptAmounts.solLamportsReceived);
          await recordTradeEvents([{ userId, type: "sell", source: "tg-quick-sell", tokenMint: mint, walletLabel: w.label, walletPublicKey: w.publicKey, ...receiptAmounts, ...(r.tokenAmount != null ? { tokenAmount: String(r.tokenAmount) } : {}), signature: r.signature }]).catch(() => {});
          return {
            ok: true,
            walletPublicKey: w.publicKey,
            soldLamports: keep,
            signature: String(r.signature || ""),
            attemptedManualSellAttemptId: attemptId,
            manualSellAttemptId: normalizeManualSellAttemptId(r.manualSellAttemptId || attemptId),
            duplicate: r.duplicate === true,
            recovered: r.recovered === true,
            crossAttemptReplay: r.crossAttemptReplay === true,
            blockedNewSubmission: r.blockedNewSubmission === true,
            priorManualSellAttemptId: normalizeManualSellAttemptId(r.priorManualSellAttemptId),
            priorManualSellSignature: String(r.priorManualSellSignature || (r.crossAttemptReplay ? r.signature : "") || ""),
            recordWarning: manualSellReceiptWarning(r)
          };
        }
      } catch (error) {
        return {
          ok: false,
          walletPublicKey: w.publicKey,
          walletLabel: w.label || "Managed wallet",
          attemptedManualSellAttemptId: attemptId,
          manualSellAttemptId: attemptId,
          signature: String(error?.partialHashes?.[0] || error?.signature || ""),
          soldLamports: 0n,
          outcomeUnknown: Boolean(error?.tradeSubmissionAmbiguous),
          partialHashes: Array.isArray(error?.partialHashes) ? error.partialHashes : [],
          failReason: friendlyError(error) || "sell failed"
        };
      }
      return {
        ok: false,
        walletPublicKey: w.publicKey,
        walletLabel: w.label || "Managed wallet",
        attemptedManualSellAttemptId: attemptId,
        manualSellAttemptId: attemptId,
        signature: "",
        soldLamports: 0n,
        outcomeUnknown: false,
        partialHashes: [],
        failReason: "sell returned no receipt"
      };
    });
    // A balance lookup failure may have skipped a wallet that still holds this
    // mint. Preserve that wallet as an incomplete attempt so a success from a
    // different wallet cannot make a multi-wallet limit order look fully filled.
    for (const row of balanceRows.filter((item) => !item.balance.ok)) {
      const attemptId = sellAttemptIdForWallet(row.wallet);
      sellRows.push({
        ok: false,
        walletPublicKey: row.wallet.publicKey,
        walletLabel: row.wallet.label || "Managed wallet",
        attemptedManualSellAttemptId: attemptId,
        manualSellAttemptId: attemptId,
        signature: "",
        soldLamports: 0n,
        outcomeUnknown: false,
        partialHashes: [],
        failReason: row.balance.error || "token balance unavailable",
        balanceUnavailable: true
      });
    }
    const ok = sellRows.filter((row) => row.ok).length;
    const fails = sellRows.length - ok;
    const soldLamports = sellRows.reduce((total, row) => total + row.soldLamports, 0n);
    const unknown = sellRows.find((row) => row.outcomeUnknown);
    const recordError = sellRows.map((row) => row.recordWarning).filter(Boolean).join("; ");
    return {
      ok: ok > 0,
      okCount: ok,
      fails,
      soldLamports,
      pct,
      recordError,
      outcomeUnknown: Boolean(unknown),
      partialHashes: unknown?.partialHashes || [],
      sellResults: sellRows,
      crossAttemptReplay: sellRows.some((row) => row.crossAttemptReplay === true),
      blockedNewSubmission: sellRows.some((row) => row.blockedNewSubmission === true),
      priorManualSellAttemptIds: [...new Set(sellRows.map((row) => row.priorManualSellAttemptId).filter(Boolean))],
      priorManualSellSignatures: [...new Set(sellRows.map((row) => row.priorManualSellSignature).filter(Boolean))]
    };
  } catch (e) { return { ok: false, why: (friendlyError ? friendlyError(e) : (e && e.message)) || "sell failed" }; }
}
// Realized PnL for a mint = all SOL back out (sells) minus all SOL in (buys), from this user's trade
// history. After a sell the sell event is already recorded, so this reflects the trade you just made.
async function realizedPnlForMint(userId, mint) {
  try {
    const h = await readTradeHistory();
    let spent = 0n, received = 0n;
    for (const t of (h.trades || [])) {
      if (String(t.userId) !== String(userId) || t.tokenMint !== mint) continue;
      if (t.type === "buy") spent += positiveBigIntOrZero(t.solLamportsSpent);
      else if (t.type === "sell") received += positiveBigIntOrZero(t.solLamportsReceived);
    }
    const net = received - spent;
    const pct = spent > 0n ? Number((received - spent) * 10000n / spent) / 100 : 0;
    return { spent, received, net, pct, hasBuys: spent > 0n };
  } catch (_) { return null; }
}
async function tgQuickSellReceipt(userId, mint, r) {
  const lx = slimewireTokenLinks(mint);
  const sol = lamportsBigToSol(r.soldLamports || 0n);
  const [info, pnl, kb] = await Promise.all([
    alphaRadarFetchMc(mint).catch(() => null),
    realizedPnlForMint(userId, mint),
    quickBuyReceiptKeyboard(mint, userId)
  ]);
  const sym = (info && info.sym) ? `$${escapeTelegramHtml(info.sym)}` : `<code>${escapeTelegramHtml(shortMint(mint))}</code>`;
  let pnlLine = "";
  if (pnl && pnl.hasBuys) {
    const up = pnl.net >= 0n;
    pnlLine = `${up ? "🟢" : "🔻"} <b>Realized: ${up ? "+" : ""}◎${lamportsBigToSol(pnl.net)}</b> (${up ? "+" : ""}${pnl.pct.toFixed(0)}%)`;
  }
  // On a win, offer a one-tap shareable flex card at the top of the receipt (viral loop).
  if (pnl && pnl.hasBuys && pnl.net > 0n && pnl.pct >= 25) {
    kb.inline_keyboard = [[{ text: "📸 Flex this win", callback_data: `wf:${mint}` }], ...kb.inline_keyboard];
  }
  await sayHtml(userId, [
    `🔴 <b>Sold ${r.pct}%</b> of ${sym} — ~<b>◎${sol}</b> back to your wallet${r.fails ? ` (${r.fails} wallet(s) skipped)` : ""}.`,
    r.recordError ? `Warning: ${escapeTelegramHtml(r.recordError)}` : "",
    pnlLine,
    `<a href="${lx.site}">Chart · positions →</a>`,
    "",
    "<i>Sell more, buy back, or arm ⏰ limit / TP-SL:</i>"
  ].filter(Boolean).join("\n"), kb).catch(() => {});
}
async function handleQuickSellCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("qs:")) return false;
  const ack = (t, alert) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(alert) } : {}) }).catch(() => {});
  const m = data.match(/^qs:(25|50|100):([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (!m) { await ack(); return true; }
  const pct = Number(m[1]), mint = m[2];
  await ack(`🔴 Selling ${pct}% now — receipt will arrive in your DM.`, false);
  const r = await tgExecuteQuickSell(userId, mint, pct, { idempotencyKey: `tg-quick-sell-callback:${query.id}` });
  if (r.needWallet) { await funnelNoWallet(userId); return true; }
  if (r.outcomeUnknown) {
    await say(userId, "Quick Sell was submitted, but confirmation is still unknown. It will not be sent again. Check Activity for the transaction before taking another action.").catch(() => {});
    return true;
  }
  if (!r.ok) {
    await say(userId, `⚠️ Quick Sell didn't land\n${r.why || "Try again in a few seconds."}`).catch(() => {});
    return true;
  }
  await tgQuickSellReceipt(userId, mint, r);
  return true;
}

// ===== ⏰ LIMIT ORDERS — market-cap-triggered buy-the-dip / take-profit / stop-loss, in-DM =====
// The last Trojan-parity trading feature. A user arms "buy 0.5◎ when MC hits $30k" or "sell 100% at
// $250k"; a background poller watches the MC (free DexScreener→pump fallback via alphaRadarFetchMc) and,
// when it crosses, fires the SAME own-wallet money-path the ⚡ quick buy/sell use (idempotent, recorded,
// DM receipt). Boundary-OK: the user's own pre-authorized action on their own custodial wallet, same as
// autopilot / community-snipe / DCA. Direction is auto-derived from the MC at arm time so the user never
// has to reason about ≤ vs ≥: a buy target below now = dip-buy, above = breakout; a sell target above
// now = take-profit, below = stop-loss. DCA (recurring, time-based) already exists — see the Bundle menu
// (dca_buy/dca_sell → createDcaPlanFlow); the ⏰ Orders hub links to it.
const LIMIT_MAX_PER_USER = 25;           // don't let one user arm thousands of watches
const LIMIT_MIN_SOL = 0.01, LIMIT_MAX_SOL = 50;
const LIMIT_ORDER_TTL_MS = 14 * 24 * 60 * 60 * 1000;   // orders auto-expire after 14 days
function limitOrdersPath() { return path.join(CONFIG.dataDir, "limit-orders.json"); }
async function readLimitOrders() {
  const store = await readJson(limitOrdersPath());
  if (!store || !Array.isArray(store.orders)) return { orders: [] };
  return store;
}
async function writeLimitOrders(store) { await writeJsonFile(limitOrdersPath(), store); }
function limitOrdersForUser(store, userId) {
  return (store.orders || []).filter((o) => String(o.userId) === String(userId));
}
// Parse a market-cap the human way: "30k" → 30000, "1.2m" → 1200000, bare "30" → 30000 (assume $k for
// small numbers so a fat-finger can't arm a $30 target), "50000" → 50000 literal. Returns 0 on junk.
function parseMcInput(raw) {
  const s = String(raw || "").trim().toLowerCase().replace(/[$,\s]/g, "");
  const m = s.match(/^([0-9]*\.?[0-9]+)(k|m|b)?$/);
  if (!m) return 0;
  let n = Number(m[1]); if (!Number.isFinite(n) || n <= 0) return 0;
  if (m[2] === "b") n *= 1e9; else if (m[2] === "m") n *= 1e6; else if (m[2] === "k") n *= 1e3;
  else if (n < 10000) n *= 1e3;   // bare small number → treat as $k (buy at "30" = $30k, not $30)
  return Math.round(n);
}
function fmtMc(n) {
  const v = Number(n) || 0;
  if (v >= 1e9) return `$${(v / 1e9).toFixed(2)}B`;
  if (v >= 1e6) return `$${(v / 1e6).toFixed(2)}M`;
  if (v >= 1e3) return `$${Math.round(v / 1e3)}k`;
  return `$${Math.round(v)}`;
}
function limitOrderLine(o) {
  if (o.side === "alert") {
    return `🔔 <b>${escapeTelegramHtml(o.sym || shortMint(o.mint))}</b> — alert ${o.dir === ">=" ? "≥" : "≤"} <b>${fmtMc(o.triggerMc)}</b>`;
  }
  const dirWord = o.side === "buy"
    ? (o.dir === ">=" ? "breakout ≥" : "dip ≤")
    : (o.dir === ">=" ? "take-profit ≥" : "stop-loss ≤");
  const amt = o.side === "buy" ? `${o.amountSol}◎` : `${o.pct}%`;
  const icon = o.side === "buy" ? "🟢" : "🔴";
  return `${icon} <b>${escapeTelegramHtml(o.sym || shortMint(o.mint))}</b> — ${o.side} ${amt} · ${dirWord} <b>${fmtMc(o.triggerMc)}</b>`;
}
// Create + persist an armed order (RMW under a file lock). Returns { ok, why?, order?, count }.
async function addLimitOrder(userId, spec) {
  return withFileLock(limitOrdersPath(), async () => {
    const store = await readLimitOrders();
    const mine = limitOrdersForUser(store, userId).filter((o) => o.status === "armed");
    if (mine.length >= LIMIT_MAX_PER_USER) return { ok: false, why: `you already have ${LIMIT_MAX_PER_USER} armed orders — cancel one first` };
    const order = {
      id: crypto.randomUUID(),
      userId: String(userId),
      side: spec.side,
      mint: spec.mint,
      sym: spec.sym || "",
      refMc: spec.refMc || 0,
      triggerMc: spec.triggerMc,
      dir: spec.dir,
      ...(spec.side === "buy" ? { amountSol: spec.amountSol } : spec.side === "sell" ? { pct: spec.pct } : {}),
      slippageBps: spec.slippageBps || 0,
      source: spec.source || "telegram",
      walletIndex: spec.walletIndex || null,
      walletPublicKey: spec.walletPublicKey || null,
      automationPermission: spec.automationPermission || null,
      status: "armed",
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + LIMIT_ORDER_TTL_MS).toISOString()
    };
    store.orders.push(order);
    await writeLimitOrders(store);
    return { ok: true, order, count: mine.length + 1 };
  });
}

async function addLimitOrdersBatch(userId, specs = []) {
  return withFileLock(limitOrdersPath(), async () => {
    const store = await readLimitOrders();
    if (!specs.length) return { ok: false, why: "add at least one order" };
    const keyFor = (order) => `${order.side}:${order.mint}:${Number(order.triggerMc)}:${String(order.walletPublicKey || order.walletIndex || "")}`;
    const incomingKeys = new Set(specs.map(keyFor));
    const inFlight = limitOrdersForUser(store, userId).find((order) => (
      String(order.status || "").toLowerCase() === "filling" && incomingKeys.has(keyFor(order))
    ));
    if (inFlight) return { ok: false, why: "A matching order is already submitting. Wait for its receipt before changing it." };
    // A reviewed replacement updates an armed target instead of stacking a
    // second order that could fire at the same market cap.
    store.orders = (store.orders || []).filter((order) => !(
      String(order.userId) === String(userId)
      && String(order.status || "").toLowerCase() === "armed"
      && incomingKeys.has(keyFor(order))
    ));
    const mine = limitOrdersForUser(store, userId).filter((order) => order.status === "armed");
    if (mine.length + specs.length > LIMIT_MAX_PER_USER) {
      return { ok: false, why: `these orders would exceed your ${LIMIT_MAX_PER_USER} armed-order limit` };
    }
    const createdAt = new Date().toISOString();
    const expiresAt = new Date(Date.now() + LIMIT_ORDER_TTL_MS).toISOString();
    const orders = specs.map((spec) => ({
      id: crypto.randomUUID(),
      userId: String(userId),
      side: spec.side,
      mint: spec.mint,
      sym: spec.sym || "",
      refMc: spec.refMc || 0,
      triggerMc: spec.triggerMc,
      dir: spec.dir,
      ...(spec.side === "buy" ? { amountSol: spec.amountSol } : spec.side === "sell" ? { pct: spec.pct } : {}),
      slippageBps: spec.slippageBps || 0,
      source: spec.source || "web",
      walletIndex: spec.walletIndex || null,
      walletPublicKey: spec.walletPublicKey || null,
      automationPermission: spec.automationPermission || null,
      status: "armed",
      createdAt,
      expiresAt
    }));
    store.orders.push(...orders);
    await writeLimitOrders(store);
    return { ok: true, orders, count: mine.length + orders.length };
  });
}
async function cancelLimitOrder(userId, id) {
  return withFileLock(limitOrdersPath(), async () => {
    const store = await readLimitOrders();
    const o = (store.orders || []).find((x) => x.id === id && String(x.userId) === String(userId) && x.status === "armed");
    if (!o) return false;
    o.status = "cancelled"; o.cancelledAt = new Date().toISOString();
    await writeLimitOrders(store);
    return true;
  });
}
// Flip one order to a terminal status (filled/failed/expired) under the lock, so the poller and a user
// cancel can't race. Returns the fresh order snapshot (or null if it's no longer armed).
async function settleLimitOrder(id, status, patch = {}) {
  return withFileLock(limitOrdersPath(), async () => {
    const store = await readLimitOrders();
    const o = (store.orders || []).find((x) => x.id === id);
    if (!o || o.status !== "armed") return null;
    o.status = status; Object.assign(o, patch);
    await writeLimitOrders(store);
    return { ...o };
  });
}
let _limitPolling = false;
let limitOrderMintCursor = 0;

function rotatingLimitOrderMints(mints = [], maxPerTick = 12) {
  const window = rotatingUniqueWindow(mints, limitOrderMintCursor, maxPerTick);
  limitOrderMintCursor = window.nextCursor;
  return window.items;
}

function limitOrderResultSignature(result = {}) {
  if (result.signature) return String(result.signature);
  if (Array.isArray(result.signatures) && result.signatures[0]) return String(result.signatures[0]);
  if (Array.isArray(result.results)) {
    const row = result.results.find((item) => item?.signature || item?.tx || item?.txid);
    if (row) return String(row.signature || row.tx || row.txid || "");
  }
  if (Array.isArray(result.sellResults)) {
    const row = result.sellResults.find((item) => item?.signature);
    if (row) return String(row.signature || "");
  }
  return "";
}

function limitOrderSellResultDisposition(order = {}, result = {}) {
  const orderId = String(order.id || "").trim();
  const source = String(order.source || "").toLowerCase();
  const sellRows = objectRows(result.sellResults);
  const successfulRows = sellRows.filter((row) => row?.ok === true);
  const failedRows = sellRows.filter((row) => row?.ok !== true);
  const crossRows = sellRows.filter((row) => row?.crossAttemptReplay === true || row?.blockedNewSubmission === true);
  const walletOutcomes = sellRows.map((row) => ({
    walletPublicKey: String(row.walletPublicKey || ""),
    walletLabel: String(row.walletLabel || ""),
    attemptedManualSellAttemptId: normalizeManualSellAttemptId(row.attemptedManualSellAttemptId),
    manualSellAttemptId: normalizeManualSellAttemptId(row.manualSellAttemptId),
    ok: row.ok === true,
    signature: String(row.signature || row.partialHashes?.[0] || ""),
    outcomeUnknown: row.outcomeUnknown === true,
    failReason: String(row.failReason || ""),
    balanceUnavailable: row.balanceUnavailable === true
  }));
  const completedWalletSellReceipts = walletOutcomes.filter((row) => row.ok);
  const incompleteWalletSellAttempts = walletOutcomes.filter((row) => !row.ok);
  const walletOutcomeDetails = walletOutcomes.length
    ? { walletOutcomes, completedWalletSellReceipts, incompleteWalletSellAttempts }
    : {};
  const crossAttemptReplay = result.crossAttemptReplay === true
    || result.blockedNewSubmission === true
    || crossRows.length > 0;
  if (crossAttemptReplay) {
    const priorAttempts = [
      result.priorManualSellAttemptId,
      ...(Array.isArray(result.priorManualSellAttemptIds) ? result.priorManualSellAttemptIds : []),
      ...crossRows.map((row) => row.priorManualSellAttemptId)
    ].map((value) => normalizeManualSellAttemptId(value)).filter(Boolean);
    const priorSignatures = [
      result.priorManualSellSignature,
      ...(Array.isArray(result.priorManualSellSignatures) ? result.priorManualSellSignatures : []),
      ...crossRows.map((row) => row.priorManualSellSignature || row.signature)
    ].map((value) => String(value || "").trim()).filter(Boolean);
    const completePriorReceipt = priorAttempts.length > 0 && priorSignatures.length > 0;
    return {
      ...walletOutcomeDetails,
      status: completePriorReceipt ? "needs_attention" : "outcome_unknown",
      signature: priorSignatures[0] || limitOrderResultSignature(result),
      priorManualSellAttemptId: priorAttempts[0] || "",
      priorManualSellSignature: priorSignatures[0] || "",
      failReason: completePriorReceipt
        ? "A different recent confirmed sell receipt was replayed; this limit order submitted no new sell and was not marked filled. Review Activity before placing another order."
        : "A prior sell receipt was replayed without complete provenance. This order submitted no new sell and requires review."
    };
  }

  if (result.outcomeUnknown === true) {
    return {
      ...walletOutcomeDetails,
      status: "outcome_unknown",
      signature: String(result.partialHashes?.[0] || limitOrderResultSignature(result) || ""),
      partialFill: successfulRows.length > 0,
      failReason: successfulRows.length > 0
        ? "Some wallets sold, but another wallet's submission outcome is unknown. The order was not marked fully filled; review each wallet in Activity."
        : "Submission outcome unknown; no automatic retry. Check wallet Activity before trading again."
    };
  }

  if (source === "web") {
    const expectedAttemptId = `web-mc-order-${orderId}`;
    const recovered = result.recovered === true || result.duplicate === true;
    const signature = String(result.signature || "").trim();
    const exactRecovery = normalizeManualSellAttemptId(result.manualSellAttemptId) === expectedAttemptId
      && Boolean(signature);
    if (recovered && !exactRecovery) {
      return {
        ...walletOutcomeDetails,
        status: "outcome_unknown",
        signature: limitOrderResultSignature(result),
        failReason: "The recovered sell receipt did not match this limit order's exact attempt. It was not marked filled."
      };
    }
    if (!signature) {
      return {
        ...walletOutcomeDetails,
        status: "outcome_unknown",
        signature: "",
        failReason: "This limit order did not return a confirmed sell signature, so it was not marked filled."
      };
    }
    return {
      ...walletOutcomeDetails,
      status: "filled",
      signature,
      failReason: null
    };
  }

  const recoveredRows = successfulRows.filter((row) => row.recovered === true || row.duplicate === true);
  if (recoveredRows.length) {
    const expectedPrefix = `limit-order-${orderId}:`;
    const exactRecovery = recoveredRows.every((row) => {
      const attempted = normalizeManualSellAttemptId(row.attemptedManualSellAttemptId);
      return attempted.startsWith(expectedPrefix)
        && normalizeManualSellAttemptId(row.manualSellAttemptId) === attempted
        && Boolean(String(row.signature || "").trim());
    });
    if (!exactRecovery) {
      return {
        ...walletOutcomeDetails,
        status: "outcome_unknown",
        signature: limitOrderResultSignature(result),
        failReason: "A recovered Telegram sell receipt did not match this limit order's exact wallet attempt. It was not marked filled."
      };
    }
  }
  if (result.ok === true && (!successfulRows.length || successfulRows.some((row) => !String(row.signature || "").trim()))) {
    return {
      ...walletOutcomeDetails,
      status: "outcome_unknown",
      signature: limitOrderResultSignature(result),
      failReason: "This Telegram limit order did not return complete confirmed sell signatures, so it was not marked filled."
    };
  }
  const reportedFailures = Math.max(0, Number.parseInt(result.fails || 0, 10) || 0);
  if (result.ok === true && (reportedFailures > 0 || failedRows.length > 0)) {
    return {
      ...walletOutcomeDetails,
      status: "needs_attention",
      signature: limitOrderResultSignature(result),
      partialFill: true,
      failReason: `Only ${successfulRows.length} wallet(s) completed; ${Math.max(reportedFailures, failedRows.length)} wallet(s) were skipped or failed. Completed wallet receipts were saved, but this order was not marked fully filled.`
    };
  }
  return result.ok === true
    ? { ...walletOutcomeDetails, status: "filled", signature: limitOrderResultSignature(result), failReason: null }
    : { ...walletOutcomeDetails, status: "failed", signature: "", failReason: result.why || "sell failed" };
}

async function reconcileStaleLimitOrderSubmissions() {
  const store = await readLimitOrders();
  // Do not reconcile a slow but still-live swap while its submission lease may
  // be active. Unknown outcomes stop permanently, so this window must be
  // conservative enough to avoid a false terminal state.
  const staleMs = Math.max(5 * 60_000, Number(CONFIG.stopLossSubmitStaleMs || 90_000));
  const now = Date.now();
  const candidates = (store.orders || []).filter((order) => {
    if (String(order.status || "").toLowerCase() !== "filling") return false;
    return staleAutomationClaim(order.firedAt || order.updatedAt || order.createdAt, now, staleMs);
  });
  if (!candidates.length) return { reconciled: 0 };

  const outcomes = new Map();
  for (const order of candidates) {
    let cached = null;
    if (order.source === "web") {
      const attemptId = `web-mc-order-${order.id}`;
      const cacheName = order.side === "buy"
        ? `web-buy-result:${attemptId}`
        : `manual-sell-result:${attemptId}`;
      cached = await idemResultGet(externalCacheKey(cacheName, order.userId)).catch(() => null);
    }
    outcomes.set(order.id, cached);
  }

  return withFileLock(limitOrdersPath(), async () => {
    const liveStore = await readLimitOrders();
    let reconciled = 0;
    for (const order of liveStore.orders || []) {
      if (!outcomes.has(order.id) || String(order.status || "").toLowerCase() !== "filling") continue;
      const cached = outcomes.get(order.id);
      if (cached?.result) {
        const disposition = order.side === "sell"
          ? limitOrderSellResultDisposition(order, cached.result)
          : { status: "filled", signature: limitOrderResultSignature(cached.result), failReason: null };
        order.status = disposition.status;
        if (disposition.status === "filled") order.filledAt = order.filledAt || new Date().toISOString();
        order.signature = order.signature || disposition.signature || "";
        order.failReason = disposition.failReason;
        if (disposition.priorManualSellAttemptId) order.priorManualSellAttemptId = disposition.priorManualSellAttemptId;
        if (disposition.priorManualSellSignature) order.priorManualSellSignature = disposition.priorManualSellSignature;
      } else {
        order.status = "outcome_unknown";
        order.failReason = cached?.ambiguousError?.message
          || "The prior submission may have reached the chain. Automatic retry is paused to prevent a duplicate trade.";
        order.signature = order.signature || String(cached?.ambiguousError?.partialHashes?.[0] || "");
      }
      order.reconciledAt = new Date().toISOString();
      order.updatedAt = order.reconciledAt;
      reconciled += 1;
    }
    if (reconciled) await writeLimitOrders(liveStore);
    return { reconciled };
  });
}

async function pollLimitOrders() {
  if (_limitPolling) return { skipped: true, reason: "limit_order_poll_active" };
  _limitPolling = true;
  const summary = { checkedOrders: 0, checkedMints: 0, triggered: 0, filled: 0, failed: 0, reconciled: 0 };
  try {
    const reconciliation = await reconcileStaleLimitOrderSubmissions();
    summary.reconciled = Number(reconciliation?.reconciled || 0);
    const store = await readLimitOrders();
    const armed = (store.orders || []).filter((o) => o.status === "armed");
    if (!armed.length) return summary;
    const st = await readState().catch(() => null);
    const paused = Boolean(st && st.paused);
    const now = Date.now();
    // Expire stale orders first (cheap, no network).
    const expired = armed.filter((o) => Date.parse(o.expiresAt || 0) && Date.parse(o.expiresAt) < now);
    for (const o of expired) { await settleLimitOrder(o.id, "expired"); }
    const live = armed.filter((o) => !expired.includes(o));
    if (!live.length || paused) { summary.paused = paused; return summary; } // when paused, still expire but don't fire
    // One MC fetch per distinct mint, shared across that mint's orders.
    const mints = [...new Set(live.map((o) => o.mint))];
    const mcByMint = new Map();
    const selectedMints = rotatingLimitOrderMints(mints, 12);
    summary.checkedMints = selectedMints.length;
    await runWithConcurrency(selectedMints, 4, async (mint) => {
      const info = await alphaRadarFetchMc(mint, { timeoutMs: 2_500 }).catch(() => null);
      if (info && info.mc > 0) mcByMint.set(mint, info);
    });
    for (const o of live) {
      const info = mcByMint.get(o.mint); if (!info) continue;
      summary.checkedOrders += 1;
      const mc = info.mc;
      const hit = o.dir === ">=" ? mc >= o.triggerMc : mc <= o.triggerMc;
      if (!hit) continue;
      // Claim it (terminal status) BEFORE executing so a slow fill can't double-fire next tick.
      const claimed = await settleLimitOrder(o.id, "filling", { firedMc: mc, firedAt: new Date().toISOString() });
      if (!claimed) continue;
      summary.triggered += 1;
      try {
        let trustedPriorSellAcknowledgements = [];
        if (o.side === "sell") {
          trustedPriorSellAcknowledgements = await trustedAutomationManualSellAcknowledgements(
            o.userId,
            o.mint,
            o.walletPublicKey ? [o.walletPublicKey] : []
          );
          if (trustedPriorSellAcknowledgements.length) {
            const savedAcknowledgement = await settleLimitOrderStatus(o.id, "filling", {
              priorSellAcknowledgements: trustedPriorSellAcknowledgements,
              priorSellAcknowledgedAt: new Date().toISOString()
            });
            if (!savedAcknowledgement) throw new Error("The limit order could not save its exact prior-sell acknowledgement.");
          }
        }
        if (o.source === "web") {
          await requireWebAutomationPermission(o.userId, "market-cap order submission");
          const result = o.side === "buy"
            ? await webTradeBuy(o.userId, {
                walletIndex: String(o.walletIndex || 1),
                walletPublicKey: o.walletPublicKey || "",
                tokenMint: o.mint,
                amountSol: String(o.amountSol),
                slippageBps: String(o.slippageBps || CONFIG.defaultSlippageBps),
                disableAutoExit: true,
                tradeAttemptId: `web-mc-order-${o.id}`
              })
            : await webTradeSell(o.userId, {
                walletIndex: String(o.walletIndex || 1),
                walletPublicKey: o.walletPublicKey || "",
                tokenMint: o.mint,
                percent: String(o.pct),
                strictWallet: true,
                slippageBps: String(o.slippageBps || CONFIG.defaultSlippageBps),
                manualSellAttemptId: `web-mc-order-${o.id}`
              }, {
                trustedPriorManualSellAcknowledgement: trustedPriorSellAcknowledgements.find((row) => (
                  String(row.walletPublicKey || "") === String(o.walletPublicKey || "")
                )) || null
              });
          if (o.side === "sell") {
            const disposition = limitOrderSellResultDisposition(o, result);
            if (disposition.status !== "filled") {
              await settleLimitOrderStatus(o.id, disposition.status, {
                failReason: disposition.failReason,
                signature: disposition.signature || "",
                ...(disposition.priorManualSellAttemptId
                  ? { priorManualSellAttemptId: disposition.priorManualSellAttemptId }
                  : {}),
                ...(disposition.priorManualSellSignature
                  ? { priorManualSellSignature: disposition.priorManualSellSignature }
                  : {})
              });
              summary.failed += 1;
              await sayHtml(o.userId, `â°âš ï¸ Limit SELL for ${escapeTelegramHtml(o.sym || shortMint(o.mint))} did not submit a new sale: ${escapeTelegramHtml(disposition.failReason)}.`).catch(() => {});
              continue;
            }
          }
          await settleLimitOrderStatus(o.id, "filled", {
            filledAt: new Date().toISOString(),
            signature: result?.signature || ""
          });
          await audit("web_market_cap_order_filled", {
            userId: o.userId,
            orderId: o.id,
            side: o.side,
            mint: o.mint,
            firedMc: mc,
            signature: result?.signature || ""
          }).catch(() => {});
          summary.filled += 1;
          continue;
        }
        if (o.side === "alert") {
          // Price/MC alert — no trade, just a heads-up DM. (Alerts fire even when trading is paused
          // is irrelevant here since we already returned on paused; alerts are advisory anyway.)
          await settleLimitOrderStatus(o.id, "filled");
          summary.filled += 1;
          await sayHtml(o.userId, [
            `🔔 <b>Price alert</b> — ${escapeTelegramHtml(info.sym || o.sym || shortMint(o.mint))} hit <b>${fmtMc(mc)}</b> (your target ${o.dir === ">=" ? "≥" : "≤"} ${fmtMc(o.triggerMc)}).`,
            "Tap to buy, sell, or re-arm:"
          ].join("\n"), await quickBuyReceiptKeyboard(o.mint, o.userId)).catch(() => {});
        } else if (o.side === "buy") {
          const r = await tgExecuteQuickBuy(o.userId, o.mint, o.amountSol, { idempotencyKey: `limit-order-${o.id}`, source: "tg-limit-order" });
          if (r.outcomeUnknown) {
            await settleLimitOrderStatus(o.id, "outcome_unknown", {
              failReason: "Submission outcome unknown; no automatic retry. Check the wallet activity before trading again.",
              ...(r.partialHashes?.[0] ? { signature: String(r.partialHashes[0]) } : {})
            });
            summary.failed += 1;
            await sayHtml(o.userId, `⏰⚠️ Limit BUY for ${escapeTelegramHtml(o.sym || shortMint(o.mint))} was submitted, but confirmation is unknown. SlimeWire will not retry it automatically; check your wallet activity first.`).catch(() => {});
          } else if (r.ok) {
            await settleLimitOrderStatus(o.id, "filled");
            summary.filled += 1;
            await sayHtml(o.userId, [
              `⏰✅ <b>Limit BUY filled</b> — ${escapeTelegramHtml(info.sym || o.sym || shortMint(o.mint))} hit <b>${fmtMc(mc)}</b>.`,
              `Bought <b>${o.amountSol}◎</b> from your SlimeWire wallet.`
            ].join("\n"), await quickBuyReceiptKeyboard(o.mint, o.userId)).catch(() => {});
          } else {
            await settleLimitOrderStatus(o.id, r.needWallet ? "failed" : "failed", { failReason: r.why || (r.needWallet ? "no wallet" : "buy failed") });
            summary.failed += 1;
            await sayHtml(o.userId, `⏰⚠️ Limit BUY for ${escapeTelegramHtml(o.sym || shortMint(o.mint))} triggered at ${fmtMc(mc)} but didn't land: ${escapeTelegramHtml(r.why || "no wallet / try again")}.`).catch(() => {});
          }
        } else {
          const r = await tgExecuteQuickSell(o.userId, o.mint, o.pct, {
            idempotencyKey: `limit-order-${o.id}`,
            trustedPriorSellAcknowledgements
          });
          const disposition = limitOrderSellResultDisposition(o, r);
          const walletOutcomePatch = {
            ...(Array.isArray(disposition.walletOutcomes)
              ? { walletOutcomes: disposition.walletOutcomes }
              : {}),
            ...(Array.isArray(disposition.completedWalletSellReceipts)
              ? { completedWalletSellReceipts: disposition.completedWalletSellReceipts }
              : {}),
            ...(Array.isArray(disposition.incompleteWalletSellAttempts)
              ? { incompleteWalletSellAttempts: disposition.incompleteWalletSellAttempts }
              : {}),
            ...(disposition.partialFill === true ? { partialFill: true } : {})
          };
          if (["outcome_unknown", "needs_attention"].includes(disposition.status)) {
            await settleLimitOrderStatus(o.id, disposition.status, {
              ...walletOutcomePatch,
              failReason: disposition.failReason,
              ...(disposition.signature ? { signature: disposition.signature } : {}),
              ...(disposition.priorManualSellAttemptId
                ? { priorManualSellAttemptId: disposition.priorManualSellAttemptId }
                : {}),
              ...(disposition.priorManualSellSignature
                ? { priorManualSellSignature: disposition.priorManualSellSignature }
                : {})
            });
            summary.failed += 1;
            await sayHtml(o.userId, disposition.partialFill
              ? `⏰⚠️ Limit SELL for ${escapeTelegramHtml(o.sym || shortMint(o.mint))} only filled on some wallets. Completed wallet receipts were saved; skipped or failed wallets need review and will not be retried automatically.`
              : `⏰⚠️ Limit SELL for ${escapeTelegramHtml(o.sym || shortMint(o.mint))} was submitted, but confirmation is unknown. SlimeWire will not retry it automatically; check your wallet activity first.`).catch(() => {});
          } else if (disposition.status === "filled") {
            await settleLimitOrderStatus(o.id, "filled", {
              ...walletOutcomePatch,
              ...(disposition.signature ? { signature: disposition.signature } : {})
            });
            summary.filled += 1;
            await tgQuickSellReceipt(o.userId, o.mint, r);
            await sayHtml(o.userId, `⏰✅ <b>Limit SELL filled</b> — ${escapeTelegramHtml(info.sym || o.sym || shortMint(o.mint))} hit <b>${fmtMc(mc)}</b> (sold ${o.pct}%).`).catch(() => {});
          } else {
            await settleLimitOrderStatus(o.id, "failed", {
              ...walletOutcomePatch,
              failReason: disposition.failReason || r.why || "sell failed"
            });
            summary.failed += 1;
            await sayHtml(o.userId, `⏰⚠️ Limit SELL for ${escapeTelegramHtml(o.sym || shortMint(o.mint))} triggered at ${fmtMc(mc)} but didn't land: ${escapeTelegramHtml(r.why || "no balance / try again")}.`).catch(() => {});
          }
        }
      } catch (e) {
        const ambiguous = Boolean(e?.tradeSubmissionAmbiguous);
        await settleLimitOrderStatus(o.id, ambiguous ? "outcome_unknown" : "failed", {
          failReason: ambiguous
            ? `Submission outcome unknown; no automatic retry. ${friendlyError(e)}`.slice(0, 300)
            : (e && e.message) || "error",
          ...(ambiguous && Array.isArray(e.partialHashes) && e.partialHashes[0]
            ? { signature: String(e.partialHashes[0]) }
            : {})
        }).catch(() => {});
        summary.failed += 1;
      }
    }
    return summary;
  } catch (e) {
    summary.error = friendlyError(e);
    console.warn(`[limit-orders] ${e && e.message}`);
    return summary;
  }
  finally { _limitPolling = false; }
}
// Small helper: move an order from the transient "filling" claim to a real terminal status.
async function settleLimitOrderStatus(id, status, patch = {}) {
  return withFileLock(limitOrdersPath(), async () => {
    const store = await readLimitOrders();
    const o = (store.orders || []).find((x) => x.id === id);
    if (!o) return null;
    o.status = status; Object.assign(o, patch);
    await writeLimitOrders(store);
    return { ...o };
  });
}

// ---- ⏰ Orders UI: hub (list + cancel + DCA link), per-coin builder, typed input ----
const limitOrderPending = new Map(); // userId -> { side, mint, sym, refMc, at }
async function ordersHubView(userId) {
  const store = await readLimitOrders();
  const mine = limitOrdersForUser(store, userId).filter((o) => o.status === "armed")
    .sort((a, b) => Date.parse(b.createdAt || 0) - Date.parse(a.createdAt || 0));
  const lines = ["⏰ <b>Your Orders</b>", ""];
  if (mine.length) {
    lines.push("<b>Armed limit orders</b> (auto-fire on market cap):");
    for (const o of mine.slice(0, 25)) lines.push(limitOrderLine(o));
  } else {
    lines.push("No armed limit orders yet.");
  }
  lines.push("", "🟢 <b>Limit orders</b>: open any coin (paste its CA or tap ⏰ on a buy card) to arm a buy-the-dip / take-profit / stop-loss on its market cap.");
  lines.push("🔁 <b>DCA</b>: recurring timed buys/sells — set one up under Bundle → DCA.");
  const rows = mine.slice(0, 10).map((o) => ([{ text: `❌ ${o.side === "buy" ? "🟢" : "🔴"} ${o.sym || shortMint(o.mint)} @ ${fmtMc(o.triggerMc)}`, callback_data: `lo:x:${o.id}` }]));
  rows.push([{ text: "🔁 DCA Buy", callback_data: "dca_buy" }, { text: "🔁 DCA Sell", callback_data: "dca_sell" }]);
  rows.push([{ text: "💰 Positions", callback_data: "positions_overview" }, { text: "🏠 Main Menu", callback_data: "main_menu" }]);
  return { text: lines.join("\n"), markup: { inline_keyboard: rows } };
}
async function showOrdersHub(chatId, userId, messageId = null) {
  const v = await ordersHubView(userId);
  if (messageId) await telegram("editMessageText", { chat_id: chatId, message_id: messageId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => {});
  else await sayHtml(chatId, v.text, v.markup);
}
// Per-coin builder: shows current MC + the two limit choices. Called from the ⏰ button (lo:new:<mint>).
async function showLimitOrderBuilder(userId, mint, messageId = null) {
  const info = await alphaRadarFetchMc(mint).catch(() => null);
  const mc = info && info.mc > 0 ? info.mc : 0;
  const sym = (info && info.sym) || "";
  const text = [
    `⏰ <b>Limit order</b> — ${escapeTelegramHtml(sym || shortMint(mint))}`,
    mc ? `Current market cap: <b>${fmtMc(mc)}</b>` : "Current market cap: <i>unavailable right now</i>",
    "",
    "Pick a side, then I'll ask for the trigger + amount. It fires automatically when the market cap crosses your target — from your own SlimeWire wallet.",
  ].join("\n");
  const markup = { inline_keyboard: [
    [{ text: "🟢 Limit Buy (dip / breakout)", callback_data: `lo:b:${mint}` }],
    [{ text: "🔴 Limit Sell (TP / SL)", callback_data: `lo:s:${mint}` }],
    [{ text: "🔔 Price Alert (no trade)", callback_data: `lo:a:${mint}` }],
    [{ text: "⏰ My Orders", callback_data: "orders_hub" }, { text: "🏠 Main Menu", callback_data: "main_menu" }]
  ] };
  if (messageId) await telegram("editMessageText", { chat_id: userId, message_id: messageId, text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: markup }).catch(() => {});
  else await sayHtml(userId, text, markup);
}
async function handleLimitOrderCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("lo:")) return false;
  const chatId = query.message?.chat?.id, messageId = query.message?.message_id;
  const ack = (t, alert) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(alert) } : {}) }).catch(() => {});
  // cancel
  let m = data.match(/^lo:x:(.+)$/);
  if (m) { const ok = await cancelLimitOrder(userId, m[1]); await ack(ok ? "Cancelled." : "Already gone."); await showOrdersHub(chatId, userId, messageId); return true; }
  // open the clean per-coin builder (sub-menu buttons, in-chat, tidy typed inputs) — works in groups + DM
  m = data.match(/^lo:new:([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (m) { await ack(); await openLimitBuilder(chatId, userId, m[1]); return true; }
  // price alert (no trade) → prompt for the target MC only
  m = data.match(/^lo:a:([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (m) {
    const mint = m[1];
    const info = await alphaRadarFetchMc(mint).catch(() => null);
    const refMc = info && info.mc > 0 ? info.mc : 0;
    limitOrderPending.set(String(userId), { side: "alert", mint, sym: (info && info.sym) || "", refMc, at: Date.now() });
    await ack();
    await sayHtml(userId, [
      `🔔 <b>Price alert</b>${refMc ? ` (now ${fmtMc(refMc)})` : ""} — reply with the <b>target market cap</b>.`,
      "e.g. <code>1m</code> = DM me when it hits $1M. I'll watch it; no trade, just a ping.",
      "Target above now = pings on a pump · below now = pings on a dip."
    ].join("\n")).catch(() => {});
    return true;
  }
  // choose a side → prompt for the trigger + amount
  m = data.match(/^lo:(b|s):([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (m) {
    if (!walletsForOwner(await readWalletStore(), userId).length) { await ack("Make a free SlimeWire wallet first — DM me /start.", true); return true; }
    const side = m[1] === "b" ? "buy" : "sell", mint = m[2];
    const info = await alphaRadarFetchMc(mint).catch(() => null);
    const refMc = info && info.mc > 0 ? info.mc : 0;
    limitOrderPending.set(String(userId), { side, mint, sym: (info && info.sym) || "", refMc, at: Date.now() });
    await ack();
    const now = refMc ? ` (now ${fmtMc(refMc)})` : "";
    if (side === "buy") {
      await sayHtml(userId, [
        `🟢 <b>Limit Buy</b>${now} — reply with <b>target MC</b> and <b>SOL amount</b>.`,
        "e.g. <code>30k 0.5</code> = buy 0.5◎ when it hits $30k.",
        "Target below now = buy the dip · above now = buy the breakout."
      ].join("\n")).catch(() => {});
    } else {
      await sayHtml(userId, [
        `🔴 <b>Limit Sell</b>${now} — reply with <b>target MC</b> and <b>sell %</b>.`,
        "e.g. <code>250k 100</code> = sell 100% when it hits $250k.",
        "Target above now = take profit · below now = stop loss."
      ].join("\n")).catch(() => {});
    }
    return true;
  }
  await ack();
  return true;
}
// ---- ⏰ CLEAN in-chat Limit builder (lo2:*) — sub-menu buttons, per-field, tidy typed inputs -----------
// Everything happens right in the chat (group or DM): tap Side, tap 🎯 Target MC / 💰 Amount to type ONE
// value, and the bot deletes both the prompt and your typed reply so the chat never fills with text.
// Per-user (owner-gated) + keyed by chat+user, so many people can build orders in the same group.
const limitDraft = new Map();        // `${chatId}:${userId}` -> { mint, sym, refMc, side, triggerMc, amount, uid, builderMsgId, at }
const cleanInputPending = new Map();  // `${chatId}:${userId}` -> { kind, at, promptMsgId, builderMsgId }
function limitBuilderView(draft, mc) {
  const side = draft.side || "buy";
  const uid = draft.uid;
  const mk = (on, l) => (on ? "• " : "") + l;
  const sideLabel = side === "buy" ? "🟢 Buy" : side === "sell" ? "🔴 Sell" : "🔔 Alert";
  const mcLine = draft.triggerMc ? fmtMc(draft.triggerMc) : "— tap to set";
  const dir = draft.triggerMc && mc ? (draft.triggerMc >= mc ? "▲ up" : "▼ down") : "";
  const amtLine = side === "alert" ? "" : (draft.amount ? (side === "buy" ? `${draft.amount}◎` : `${draft.amount}%`) : "— tap to set");
  const rows = [
    [
      { text: mk(side === "buy", "🟢 Buy"), callback_data: `lo2:s:b:${uid}` },
      { text: mk(side === "sell", "🔴 Sell"), callback_data: `lo2:s:s:${uid}` },
      { text: mk(side === "alert", "🔔 Alert"), callback_data: `lo2:s:a:${uid}` }
    ],
    [{ text: `🎯 Target MC${draft.triggerMc ? `: ${fmtMc(draft.triggerMc)}` : ""}`, callback_data: `lo2:mc:${uid}` }]
  ];
  if (side !== "alert") {
    const quick = side === "buy" ? [0.1, 0.25, 0.5, 1] : [25, 50, 100];
    rows.push(quick.map((v) => ({ text: mk(draft.amount === v, side === "buy" ? `${v}◎` : `${v}%`), callback_data: `lo2:amt:${v}:${uid}` }))
      .concat([{ text: "✏️", callback_data: `lo2:amtx:${uid}` }]));
  }
  rows.push([{ text: "✅ Arm order", callback_data: `lo2:arm:${uid}` }, { text: "✖ Cancel", callback_data: `lo2:x:${uid}` }]);
  const text = [
    `⏰ <b>Limit order</b> — ${escapeTelegramHtml(draft.sym || shortMint(draft.mint))}`,
    mc ? `Now: <b>${fmtMc(mc)}</b>` : "Now: <i>MC unavailable</i>",
    "",
    `Side: <b>${sideLabel}</b>`,
    `Target MC: <b>${mcLine}</b>${dir ? ` <i>(${dir})</i>` : ""}`,
    side === "alert" ? "" : `Amount: <b>${amtLine}</b>`,
    "",
    side === "buy" ? "<i>Below now = buy the dip · above = buy the breakout. Fires from your own wallet.</i>"
      : side === "sell" ? "<i>Above now = take profit · below = stop loss. Fires from your own wallet.</i>"
      : "<i>I'll DM you when it crosses — no trade.</i>"
  ].filter(Boolean).join("\n");
  return { text, markup: { inline_keyboard: rows } };
}
async function openLimitBuilder(chatId, userId, mint) {
  const info = await alphaRadarFetchMc(mint).catch(() => null);
  const mc = info && info.mc > 0 ? info.mc : 0;
  const draft = { mint, sym: (info && info.sym) || "", refMc: mc, side: "buy", triggerMc: 0, amount: 0, uid: String(userId), builderMsgId: null, at: Date.now() };
  limitDraft.set(`${chatId}:${userId}`, draft);
  const v = limitBuilderView(draft, mc);
  const res = await telegram("sendMessage", { chat_id: chatId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => null);
  if (res && res.message_id) draft.builderMsgId = res.message_id;
}
async function renderLimitBuilder(chatId, userId) {
  const draft = limitDraft.get(`${chatId}:${userId}`);
  if (!draft || !draft.builderMsgId) return;
  const v = limitBuilderView(draft, draft.refMc);
  await telegram("editMessageText", { chat_id: chatId, message_id: draft.builderMsgId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => {});
}
async function handleLimitBuilderCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("lo2:")) return false;
  const chatId = query.message?.chat?.id, messageId = query.message?.message_id;
  const ack = (t, a) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(a) } : {}) }).catch(() => {});
  const parts = data.split(":");
  const kind = parts[1];
  const owner = parts[parts.length - 1];
  if (String(userId) !== String(owner)) { await ack("Tap ⏰ Limit to open your own.", true); return true; }
  const key = `${chatId}:${owner}`;
  const draft = limitDraft.get(key);
  if (!draft) { await ack("That order builder expired — tap ⏰ Limit again.", true); return true; }
  if (messageId) draft.builderMsgId = messageId;
  if (kind === "s") {
    const s = parts[2]; draft.side = s === "b" ? "buy" : s === "s" ? "sell" : "alert";
    if (draft.side === "alert") draft.amount = 0;
    await renderLimitBuilder(chatId, userId); await ack(); return true;
  }
  if (kind === "mc") { await ack(); await promptCleanInput(chatId, userId, "🎯 Reply with the <b>target market cap</b> (e.g. <code>30k</code>, <code>250k</code>, <code>1.2m</code>).", "lo_mc"); return true; }
  if (kind === "amt") { draft.amount = Number(parts[2]); await renderLimitBuilder(chatId, userId); await ack(); return true; }
  if (kind === "amtx") { await ack(); await promptCleanInput(chatId, userId, draft.side === "buy" ? "💰 Reply with the <b>SOL amount</b> (e.g. <code>0.5</code>)." : "💰 Reply with the <b>sell %</b> (e.g. <code>100</code>).", "lo_amt"); return true; }
  if (kind === "x") { limitDraft.delete(key); if (messageId) await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => {}); await ack("Cancelled"); return true; }
  if (kind === "arm") {
    if (!draft.triggerMc) { await ack("Set the target market cap first.", true); return true; }
    if (draft.side !== "alert" && !(draft.amount > 0)) { await ack(draft.side === "buy" ? "Set the SOL amount first." : "Set the sell % first.", true); return true; }
    if (draft.side !== "alert" && !walletsForOwner(await readWalletStore(), userId).length) { await ack(noWalletAckText(await funnelNoWallet(userId)), true); return true; }
    const slippageBps = userBuyPrefs(await readBuyPrefs(), userId).slippageBps;
    const dir = draft.triggerMc >= (draft.refMc || 0) ? ">=" : "<=";
    const spec = { side: draft.side, mint: draft.mint, sym: draft.sym, refMc: draft.refMc || 0, triggerMc: draft.triggerMc, dir, slippageBps };
    if (draft.side === "buy") spec.amountSol = Math.min(LIMIT_MAX_SOL, Math.max(LIMIT_MIN_SOL, draft.amount));
    else if (draft.side === "sell") spec.pct = Math.min(100, Math.max(1, Math.round(draft.amount)));
    const res = await addLimitOrder(userId, spec);
    if (!res.ok) { if (res.needWallet) await ack(noWalletAckText(await funnelNoWallet(userId)), true); else await ack(`Couldn't arm: ${res.why || "try again"}.`, true); return true; }
    limitDraft.delete(key);
    const o = res.order;
    const text = ["⏰✅ <b>Order armed</b>", limitOrderLine(o), "", `<i>Fires automatically when ${escapeTelegramHtml(o.sym || shortMint(o.mint))} crosses ${fmtMc(o.triggerMc)}. Expires in 14 days.</i>`].join("\n");
    const markup = { inline_keyboard: [[{ text: "⏰ My Orders", callback_data: "orders_hub" }, { text: "➕ Another", callback_data: `lo:new:${draft.mint}` }]] };
    if (messageId) await telegram("editMessageText", { chat_id: chatId, message_id: messageId, text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: markup }).catch(() => {});
    await ack("⏰ Armed!");
    return true;
  }
  await ack(); return true;
}
// Prompt for ONE value with force-reply; store the prompt id so we can delete it after the answer.
async function promptCleanInput(chatId, userId, promptText, kind, builderMsgId = null) {
  const res = await telegram("sendMessage", { chat_id: chatId, text: promptText, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: { force_reply: true, selective: true } }).catch(() => null);
  cleanInputPending.set(`${chatId}:${userId}`, { kind, at: Date.now(), promptMsgId: (res && res.message_id) || null, builderMsgId });
}
// Consume a typed value for a pending clean-input, then DELETE the user's message + the prompt so the
// chat stays clean (message deletion in groups needs the bot's Delete-messages admin right; best-effort).
async function applyCleanInput(message, userId) {
  const chatId = message.chat.id;
  const key = `${chatId}:${userId}`;
  const pend = cleanInputPending.get(key);
  if (!pend) return false;
  if (Date.now() - pend.at > 180000) { cleanInputPending.delete(key); return false; }
  const raw = String(message.text || "").trim();
  if (!raw || raw.startsWith("/")) return false;
  const cleanup = () => {
    telegram("deleteMessage", { chat_id: chatId, message_id: message.message_id }).catch(() => {});
    if (pend.promptMsgId) telegram("deleteMessage", { chat_id: chatId, message_id: pend.promptMsgId }).catch(() => {});
  };
  const reprompt = async (hint) => {
    cleanup();
    const res = await telegram("sendMessage", { chat_id: chatId, text: hint, parse_mode: "HTML", reply_markup: { force_reply: true, selective: true } }).catch(() => null);
    cleanInputPending.set(key, { ...pend, at: Date.now(), promptMsgId: (res && res.message_id) || null });
  };
  if (pend.kind === "lo_mc" || pend.kind === "lo_amt") {
    const draft = limitDraft.get(key);
    if (!draft) { cleanInputPending.delete(key); cleanup(); return true; }
    if (pend.kind === "lo_mc") {
      const mc = parseMcInput(raw);
      if (!mc) { await reprompt("🎯 Couldn't read that. Reply with a market cap like <code>30k</code>, <code>250k</code>, or <code>1.2m</code>."); return true; }
      draft.triggerMc = mc;
    } else {
      const n = Number(raw.replace(/[^0-9.]/g, ""));
      if (!Number.isFinite(n) || n <= 0) { await reprompt(draft.side === "buy" ? "💰 Couldn't read that. Reply with a SOL amount like <code>0.5</code>." : "💰 Couldn't read that. Reply with a sell % like <code>100</code>."); return true; }
      draft.amount = draft.side === "buy" ? n : Math.min(100, Math.max(1, Math.round(n)));
    }
    cleanInputPending.delete(key);
    cleanup();
    await renderLimitBuilder(chatId, userId);
    return true;
  }
  if (pend.kind === "pe_amt") {
    const n = Number(raw.replace(/[^0-9.]/g, ""));
    if (!Number.isFinite(n) || n <= 0) { await reprompt("💰 Couldn't read that. Reply with a SOL amount like <code>0.5</code>."); return true; }
    cleanInputPending.delete(key);
    cleanup();
    await setBuyPref(userId, "amount", n);
    if (pend.builderMsgId) {
      const v = presetEditorView(userBuyPrefs(await readBuyPrefs(), userId), userId);
      await telegram("editMessageText", { chat_id: chatId, message_id: pend.builderMsgId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => {});
    }
    return true;
  }
  if (pend.kind === "pe_tp" || pend.kind === "pe_sl") {
    const n = Number(raw.replace(/[^0-9.]/g, ""));
    const max = pend.kind === "pe_tp" ? 10000 : 95;
    if (!Number.isFinite(n) || n < 0 || n > max) {
      await reprompt(pend.kind === "pe_tp"
        ? "🎯 Reply with a TP percentage from <code>0</code> (off) to <code>10000</code>."
        : "🛡 Reply with an SL percentage from <code>0</code> (off) to <code>95</code>.");
      return true;
    }
    cleanInputPending.delete(key);
    cleanup();
    await setBuyPref(userId, pend.kind === "pe_tp" ? "tp" : "sl", n);
    if (pend.builderMsgId) {
      const v = presetEditorView(userBuyPrefs(await readBuyPrefs(), userId), userId);
      await telegram("editMessageText", { chat_id: chatId, message_id: pend.builderMsgId, text: v.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: v.markup }).catch(() => {});
    }
    return true;
  }
  cleanInputPending.delete(key);
  return true;
}
// ---- 🎯 Auto-TP ladder: one tap after a buy arms a set of limit-sell rungs at multiples of entry MC ----
const TP_LADDERS = {
  balanced: { label: "Balanced — 2× / 4×", rungs: [{ mult: 2, pct: 50 }, { mult: 4, pct: 50 }] },
  runner:   { label: "Runner — 2× / 5× / 10×", rungs: [{ mult: 2, pct: 34 }, { mult: 5, pct: 33 }, { mult: 10, pct: 33 }] },
  safe:     { label: "Safe — 1.5× / 3×", rungs: [{ mult: 1.5, pct: 50 }, { mult: 3, pct: 50 }] }
};
async function showTpLadder(userId, mint, messageId = null) {
  const info = await alphaRadarFetchMc(mint).catch(() => null);
  const mc = info && info.mc > 0 ? info.mc : 0;
  const sym = (info && info.sym) || shortMint(mint);
  const text = [
    `🎯 <b>Auto-TP ladder</b> — ${escapeTelegramHtml(sym)}`,
    mc ? `From here (${fmtMc(mc)}), I'll arm limit sells that auto-fire as it climbs:` : "Market cap unavailable right now — try the ⏰ Limit menu to set an exact target.",
    mc ? `• <b>Balanced</b>: sell 50% at ${fmtMc(mc * 2)}, 50% at ${fmtMc(mc * 4)}` : "",
    mc ? `• <b>Runner</b>: 34% at ${fmtMc(mc * 2)}, 33% at ${fmtMc(mc * 5)}, 33% at ${fmtMc(mc * 10)}` : "",
    mc ? `• <b>Safe</b>: 50% at ${fmtMc(mc * 1.5)}, 50% at ${fmtMc(mc * 3)}` : ""
  ].filter(Boolean).join("\n");
  const rows = mc ? [
    [{ text: "🎯 Balanced 2×/4×", callback_data: `tp:set:balanced:${mint}` }],
    [{ text: "🚀 Runner 2×/5×/10×", callback_data: `tp:set:runner:${mint}` }],
    [{ text: "🛡 Safe 1.5×/3×", callback_data: `tp:set:safe:${mint}` }],
    [{ text: "⏰ Custom limit", callback_data: `lo:new:${mint}` }, { text: "🏠 Main Menu", callback_data: "main_menu" }]
  ] : [[{ text: "⏰ Limit menu", callback_data: `lo:new:${mint}` }, { text: "🏠 Main Menu", callback_data: "main_menu" }]];
  if (messageId) await telegram("editMessageText", { chat_id: userId, message_id: messageId, text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: { inline_keyboard: rows } }).catch(() => {});
  else await sayHtml(userId, text, { inline_keyboard: rows });
}
async function handleTpCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("tp:")) return false;
  const messageId = query.message?.message_id;
  const ack = (t, alert) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t, show_alert: Boolean(alert) } : {}) }).catch(() => {});
  let m = data.match(/^tp:([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (m) { await ack(); await showTpLadder(userId, m[1], isPrivateChat(query.message?.chat) ? messageId : null); return true; }
  m = data.match(/^tp:set:(balanced|runner|safe):([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (m) {
    const ladder = TP_LADDERS[m[1]], mint = m[2];
    if (!walletsForOwner(await readWalletStore(), userId).length) { await ack("Make a free SlimeWire wallet first — DM me /start.", true); return true; }
    const info = await alphaRadarFetchMc(mint).catch(() => null);
    const mc = info && info.mc > 0 ? info.mc : 0;
    if (!mc) { await ack("Market cap unavailable — use ⏰ Custom limit.", true); return true; }
    const slippageBps = userBuyPrefs(await readBuyPrefs(), userId).slippageBps;
    const armed = [];
    for (const rung of ladder.rungs) {
      const triggerMc = Math.round(mc * rung.mult);
      const res = await addLimitOrder(userId, { side: "sell", mint, sym: (info && info.sym) || "", refMc: mc, triggerMc, dir: ">=", pct: rung.pct, slippageBps });
      if (res.ok) armed.push(`sell ${rung.pct}% at ${fmtMc(triggerMc)} (${rung.mult}×)`);
    }
    await ack(armed.length ? `🎯 Armed ${armed.length} take-profits!` : "Couldn't arm — maybe you hit the order cap.", true);
    if (armed.length) {
      await sayHtml(userId, [
        `🎯 <b>Auto-TP armed</b> — ${escapeTelegramHtml((info && info.sym) || shortMint(mint))}`,
        ...armed.map((a) => `• ${a}`),
        "",
        "<i>Each fires automatically as the market cap climbs. Manage or cancel under ⏰ My Orders.</i>"
      ].join("\n"), { inline_keyboard: [[{ text: "⏰ My Orders", callback_data: "orders_hub" }, { text: "🏠 Main Menu", callback_data: "main_menu" }]] }).catch(() => {});
    }
    return true;
  }
  await ack();
  return true;
}

// Typed "<targetMC> <amount>" for a pending limit order. Returns true when it consumed the message.
async function applyLimitOrderInput(message, userId) {
  const pend = limitOrderPending.get(String(userId));
  if (!pend) return false;
  if (Date.now() - pend.at > 180000) { limitOrderPending.delete(String(userId)); return false; }
  const raw = String(message.text || "").trim();
  if (!raw || raw.startsWith("/")) return false;
  const parts = raw.split(/[\s,]+/).filter(Boolean);
  const isAlert = pend.side === "alert";
  if (!isAlert && parts.length < 2) { await say(message.chat.id, "Send two values: target MC then amount, e.g. `30k 0.5`."); return true; }
  const triggerMc = parseMcInput(parts[0]);
  if (!triggerMc) { await say(message.chat.id, "Couldn't read the target MC. Try like `30k`, `250k`, or `1.2m`."); return true; }
  const amtNum = isAlert ? 0 : Number(String(parts[1]).replace(/[^0-9.]/g, ""));
  if (!isAlert && (!Number.isFinite(amtNum) || amtNum <= 0)) { await say(message.chat.id, pend.side === "buy" ? "Couldn't read the SOL amount, e.g. 0.5" : "Couldn't read the sell %, e.g. 100"); return true; }
  limitOrderPending.delete(String(userId));
  const slippageBps = userBuyPrefs(await readBuyPrefs(), userId).slippageBps;
  const ref = pend.refMc || 0;
  const dir = triggerMc >= ref ? ">=" : "<=";   // ref 0 → ">=" (treat as breakout/TP; harmless)
  const spec = { side: pend.side, mint: pend.mint, sym: pend.sym, refMc: ref, triggerMc, dir, slippageBps };
  if (pend.side === "buy") {
    const sol = Math.min(LIMIT_MAX_SOL, Math.max(LIMIT_MIN_SOL, amtNum));
    spec.amountSol = sol;
  } else if (pend.side === "sell") {
    spec.pct = Math.min(100, Math.max(1, Math.round(amtNum)));
  }
  const res = await addLimitOrder(userId, spec);
  if (!res.ok) { await sayHtml(message.chat.id, `⏰ Couldn't arm it: ${escapeTelegramHtml(res.why || "try again")}.`); return true; }
  const o = res.order;
  await sayHtml(message.chat.id, [
    "⏰✅ <b>Order armed.</b>",
    limitOrderLine(o),
    "",
    `<i>Fires automatically when ${escapeTelegramHtml(o.sym || shortMint(o.mint))} crosses ${fmtMc(o.triggerMc)}. I watch it for you — expires in 14 days.</i>`
  ].join("\n"), { inline_keyboard: [[{ text: "⏰ My Orders", callback_data: "orders_hub" }, { text: "🏠 Main Menu", callback_data: "main_menu" }]] }).catch(() => {});
  return true;
}

// Caller footer for the scan card: who FIRST called this CA in this channel, when, and how
// it's done since the call (live X / %, plus peak). Also refreshes the call's last/peak MC so
// the caller-intel warehouse stays current on every look/refresh. Channel-only (no record in
// DMs). Returns "" when there's no recorded call (e.g. a DM or a never-called coin).
async function buildScanCallerFooter(chatId, mint, currentMc, message) {
  try {
    if (!mint) return "";
    mint = /^0x[0-9a-fA-F]{40}$/.test(String(mint)) ? String(mint).toLowerCase() : String(mint);
    const store = await readTelegramCalls();
    if (!store.calls) return "";
    const mc = Number(currentMc) || 0;
    // Freshen THIS chat's record if it exists (per-channel warehouse stays current).
    let here = chatId ? store.calls[`${chatId}:${mint}`] : null;
    // SELF-SEED: if this is a channel look and nobody has recorded a call for THIS chat yet, record
    // it now so the footer appears from the very first look (and any later Refresh keeps tracking it).
    // Belt-and-suspenders for paths that build the footer without recording first.
    if (!here && message && !isPrivateChat(message.chat)) {
      here = await recordTelegramCall(message, mint, mc).catch(() => null);
    }
    if (here && mc > 0) {
      refreshCallerIntelMarketProof(here, { mc }, Date.now());
      scheduleTelegramCallsFlush();
    }
    // The footer shows the EARLIEST caller of this mint ANYWHERE in the warehouse (not just this
    // chat) — so it appears in DM and on $ticker looks too, surfacing who really called it first
    // and where. Also track the best peak across every channel that called it.
    let rec = null, bestPeak = 0;
    for (const k in store.calls) {
      const r = store.calls[k];
      const recordMint = /^0x[0-9a-fA-F]{40}$/.test(String(r?.mint || "")) ? String(r.mint).toLowerCase() : String(r?.mint || "");
      if (!r || recordMint !== mint) continue;
      // Repair older RH calls that were recorded during an all-N/A market response. The first later scan
      // with a real MC becomes their honest measurable baseline; caller identity/timestamp never changes.
      if (mc > 0) {
        refreshCallerIntelMarketProof(r, { mc }, Date.now());
        scheduleTelegramCallsFlush();
      }
      if (Number(r.peakMc) > bestPeak) bestPeak = Number(r.peakMc) || 0;
      if (!rec || (Number(r.firstAt) || 0) < (Number(rec.firstAt) || 0)) rec = r;
    }
    if (!rec) return "";
    const entry = Number(rec.entryMc) || 0;
    const ago = alphaAgeLabel(Math.max(0, Date.now() - Number(rec.firstAt || Date.now())));
    // Scanner-bot footer the user asked for: WHO first called it · the MC then · the move since
    // (green/red %), plus the peak if it ran. e.g. "📣 First called by @x at $12k · 🟢 +340% · 2h ago".
    const atMc = entry > 0 ? ` at ${scanFmtMoney(entry)} MC` : " at MC pending";
    // Live MC to measure the move: prefer the current scan's MC, else the freshest stored value.
    const liveMc = mc > 0 ? mc : (Number(rec.lastMc) || 0);
    let bracket = "";
    if (entry > 0 && liveMc > 0) {
      const pct = Math.round((liveMc / entry - 1) * 100);
      bracket = ` · ${pct >= 0 ? "🟢" : "🔴"} ${pct >= 0 ? "+" : ""}${pct}%`;
    } else bracket = " · move pending";
    const peakX = entry > 0 ? bestPeak / entry : 0;
    const peakStr = peakX >= 2 ? ` · peak +${Math.round((peakX - 1) * 100)}%` : "";
    // Name the room it was first called in when that's somewhere other than here (informative in DM).
    const sameChat = chatId && String(rec.chatId || "") === String(chatId);
    const where = !sameChat && rec.chatTitle ? ` in ${escapeTelegramHtml(String(rec.chatTitle).slice(0, 28))}` : "";
    return `📣 First called by <b>${escapeTelegramHtml(rec.callerName || "someone")}</b>${where}${atMc}${bracket}${peakStr} · ${ago}`;
  } catch { return ""; }
}

// Group /flex and /pnl: render the CALL's performance — credited to the FIRST caller, measured from
// the call's entry MC (not a personal buy/sell). This is "flex/pnl based off first call and caller".
// NEVER dead-ends in a group: if nobody has called this coin yet, it RECORDS the call right now
// (seeding the caller-intel warehouse so the footer + future /pnl track it) and posts a live-stats
// card from the coin's real DexScreener momentum + ATH — so /pnl <CA> always answers with something
// useful instead of the old "No PnL data... only works for buys/sells made from this bot." dead-end.
// Returns true whenever a card was posted (effectively always, for a valid mint with a live read).
async function postCallFlexCard(chatId, mint, message) {
  try {
    // Always pull the live read first — needed for both the recorded-call card and the seed/fallback.
    let curMc = 0, sym = "", meta = null, ath = null;
    try {
      const scan = await gatherSlimeScan(mint);
      curMc = Number(scan?.meta?.marketCap || scan?.meta?.fdv || scan?.bonding?.marketCap || 0);
      sym = scan?.meta?.symbol || scan?.bonding?.symbol || "";
      meta = scan?.meta || null; ath = scan?.ath || null;
    } catch {}

    let rec = null, bestPeak = 0;
    const store = await readTelegramCalls();
    for (const k in (store.calls || {})) {
      const r = store.calls[k];
      if (!r || r.mint !== mint) continue;
      if (Number(r.peakMc) > bestPeak) bestPeak = Number(r.peakMc) || 0;
      if (!rec || (Number(r.firstAt) || 0) < (Number(rec.firstAt) || 0)) rec = r;
    }

    // No call on record yet → SEED it now (so the caller-intel warehouse + footer start tracking
    // from this moment) and re-read so the rest of the function treats it like any recorded call.
    if (!rec && message && !isPrivateChat(message.chat)) {
      rec = await recordTelegramCall(message, mint, curMc).catch(() => null);
      if (rec) bestPeak = Math.max(bestPeak, Number(rec.peakMc) || 0);
    }

    // Still no record (e.g. couldn't seed) → post an honest live-momentum card from DexScreener
    // so the command never dead-ends. Real recent change + ATH, credited to "just spotted".
    if (!rec) {
      const ch24 = meta?.priceChange?.h24, ch1 = meta?.priceChange?.h1;
      const live = curMc > 0 ? curMc : Number(meta?.fdv || meta?.marketCap || 0);
      const lines = [
        `🟢 <b>$${escapeTelegramHtml(sym || shortMint(mint))}</b>${live > 0 ? ` — now ${scanFmtMoney(live)}` : ""}`,
        `📣 First spotted here — tracking from now`,
        (ch24 != null || ch1 != null) ? `📊 24h <b>${scanFmtPct(ch24)}</b>${ch1 != null ? ` · 1h <b>${scanFmtPct(ch1)}</b>` : ""}` : null,
        (ath && Number(ath.mc) > 0 && live > 0 && Number(ath.mc) > live * 1.05) ? `🏔 ATH ${scanFmtMoney(ath.mc)} <i>(${Math.round((live / ath.mc - 1) * 100)}% from peak)</i>` : null,
        `⚡ <a href="https://slimewire.org/t?ca=${mint}">Trade $${escapeTelegramHtml(sym || "it")} on SlimeWire</a>`
      ].filter(Boolean);
      await sayHtml(chatId, lines.join("\n"), slimeScanKeyboard(mint));
      return true;
    }

    const entry = Number(rec.entryMc) || 0;
    const live = curMc > 0 ? curMc : (Number(rec.lastMc) || 0);
    if (live > 0) {
      refreshCallerIntelMarketProof(rec, { mc: live, symbol: sym }, Date.now());
      bestPeak = Math.max(bestPeak, Number(rec.peakMc) || live);
      scheduleTelegramCallsFlush();
    }
    const pct = entry > 0 && live > 0 ? Math.round((live / entry - 1) * 100) : 0;
    const x = entry > 0 && live > 0 ? live / entry : 0;
    const peakPct = entry > 0 && bestPeak > 0 ? Math.round((bestPeak / entry - 1) * 100) : 0;
    const up = pct >= 0;
    const fresh = (Date.now() - Number(rec.firstAt || Date.now())) < 90_000; // seeded in the last ~90s
    const ago = alphaAgeLabel(Math.max(0, Date.now() - Number(rec.firstAt || Date.now())));
    const lines = [
      `${up ? "🟢" : "🔴"} <b>$${escapeTelegramHtml(sym || shortMint(mint))} — the call</b>`,
      fresh
        ? `📣 First spotted here — tracking from now`
        : `📣 Called by <b>${escapeTelegramHtml(rec.callerName || "someone")}</b>${rec.chatTitle ? ` in ${escapeTelegramHtml(String(rec.chatTitle).slice(0, 28))}` : ""} · ${ago} ago`,
      entry > 0 ? `🎯 Entry ${scanFmtMoney(entry)} → ${scanFmtMoney(live)}` : `now ${scanFmtMoney(live)}`,
      fresh && meta?.priceChange
        ? `📊 24h <b>${scanFmtPct(meta.priceChange.h24)}</b>${meta.priceChange.h1 != null ? ` · 1h <b>${scanFmtPct(meta.priceChange.h1)}</b>` : ""}`
        : `${up ? "📈" : "📉"} <b>${up ? "+" : ""}${pct}%</b>${x >= 2 ? ` · <b>${x.toFixed(1)}x</b>` : ""}${peakPct >= pct + 25 ? ` · peak +${peakPct}%` : ""}`,
      `⚡ <a href="https://slimewire.org/t?ca=${mint}">Trade $${escapeTelegramHtml(sym || "it")} on SlimeWire</a>`
    ].filter(Boolean);
    await sayHtml(chatId, lines.join("\n"), slimeScanKeyboard(mint));
    return true;
  } catch { return false; }
}

// SCAN BOT — PnL FLEX CARDS. When someone in a group brags a win that names a coin ("+340% on
// $OGRE 🚀", "just did 5x on <CA>"), reply with OUR rotating SlimeWire slime-card (the same
// 15-background design the app + site rotate through) showing that coin's CALL performance — so a
// competitor's screenshot never owns the moment in your chat. Renders in receipt mode (no personal
// round-trip P&L needed — it's the call's move from first-seen MC). Falls back to the text card.
async function sendCallFlexImageCard(chatId, mint, message) {
  try {
    let curMc = 0, sym = "", name = "", imageUrl = "";
    try {
      const scan = await gatherSlimeScan(mint);
      curMc = Number(scan?.meta?.marketCap || scan?.meta?.fdv || scan?.bonding?.marketCap || 0);
      sym = scan?.meta?.symbol || scan?.bonding?.symbol || "";
      name = scan?.meta?.name || scan?.bonding?.name || "";
      imageUrl = scan?.meta?.imageUrl || scan?.meta?.avatarUrl || "";
    } catch {}
    // Find or seed the call (entry MC) so the % is honest — measured from first-seen, not a made-up base.
    let rec = null, bestPeak = 0;
    const store = await readTelegramCalls();
    for (const k in (store.calls || {})) {
      const r = store.calls[k];
      if (!r || r.mint !== mint) continue;
      if (Number(r.peakMc) > bestPeak) bestPeak = Number(r.peakMc) || 0;
      if (!rec || (Number(r.firstAt) || 0) < (Number(rec.firstAt) || 0)) rec = r;
    }
    if (!rec && message) rec = await recordTelegramCall(message, mint, curMc).catch(() => null);
    const entry = rec ? Number(rec.entryMc) || 0 : 0;
    const live = curMc > 0 ? curMc : (rec ? Number(rec.lastMc) || 0 : 0);
    if (rec && live > 0) {
      refreshCallerIntelMarketProof(rec, { mc: live, symbol: sym }, Date.now());
      bestPeak = Math.max(bestPeak, Number(rec.peakMc) || live);
      scheduleTelegramCallsFlush();
    }
    // Need a real entry + move to render a meaningful flex; otherwise fall back to the honest text card.
    if (!(entry > 0 && live > 0)) return await postCallFlexCard(chatId, mint, message);
    const gainPct = Math.round((live / entry - 1) * 100);
    const x = live / entry;
    const win = gainPct >= 0;
    const fresh = (Date.now() - Number(rec.firstAt || Date.now())) < 90_000;
    const ago = alphaAgeLabel(Math.max(0, Date.now() - Number(rec.firstAt || Date.now())));
    const png = await renderSlimeCard({
      mint, symbol: sym || shortMint(mint), name: name || "SlimeWire", imageUrl,
      loss: !win, receipt: true,
      headline: win ? `${Math.round(x * 10) / 10}X` : `-${Math.abs(gainPct)}%`,
      lines: [
        win ? `Called +${gainPct}%` : `Down ${gainPct}%`,
        entry > 0 ? `Entry ${formatUsdCompact(entry)} -> ${formatUsdCompact(live)}` : "",
        fresh ? "First spotted here" : `Called by ${String(rec.callerName || "someone").slice(0, 20)} · ${ago} ago`
      ]
    }).catch(() => null);
    if (!png) return await postCallFlexCard(chatId, mint, message);
    const cap = `${win ? "🟢" : "🔴"} <b>$${escapeTelegramHtml(sym || shortMint(mint))} — the call</b> ${win ? `<b>+${gainPct}%</b>` : `${gainPct}%`}\n⚡ <a href="https://www.slimewire.org/t?ca=${mint}">Trade it on SlimeWire</a>`;
    await sendPhoto(chatId, `flex-${sanitizeFilenamePart(sym || mint)}.png`, png, cap, slimeScanKeyboard(mint), "HTML");
    return true;
  } catch { try { return await postCallFlexCard(chatId, mint, message); } catch { return false; } }
}

// 📸 Personal win-flex — a shareable card of YOUR realized PnL on a coin (from your own trades, not a
// channel call). Fires from a button on the sell receipt when you're up. Viral loop: forward it, it
// links back to SlimeWire. Honest — the numbers come straight from your recorded buys/sells.
async function sendUserWinFlex(userId, mint) {
  try {
    const pnl = await realizedPnlForMint(userId, mint);
    if (!pnl || !pnl.hasBuys) { await sayHtml(userId, "No recorded PnL on this coin yet — buy/sell it through the bot first."); return true; }
    const info = await alphaRadarFetchMc(mint).catch(() => null);
    const sym = (info && info.sym) || shortMint(mint);
    const win = pnl.net >= 0n;
    const spentSol = Number(lamportsBigToSol(pnl.spent)) || 0;
    const recvSol = Number(lamportsBigToSol(pnl.received)) || 0;
    const x = spentSol > 0 ? recvSol / spentSol : 0;
    const png = await renderSlimeCard({
      mint, symbol: sym, name: "SlimeWire", imageUrl: "",
      loss: !win, receipt: true,
      headline: win ? (x >= 2 ? `${Math.round(x * 10) / 10}X` : `+${pnl.pct.toFixed(0)}%`) : `${pnl.pct.toFixed(0)}%`,
      lines: [
        win ? `Banked +◎${lamportsBigToSol(pnl.net)}` : `Down ◎${lamportsBigToSol(-pnl.net)}`,
        `on $${sym}`,
        "traded on @SlimeWiredBot"
      ]
    }).catch(() => null);
    const lx = slimewireTokenLinks(mint);
    if (!png) {
      await sayHtml(userId, `${win ? "🟢" : "🔴"} <b>$${escapeTelegramHtml(sym)}</b> — realized ${win ? "+" : ""}◎${lamportsBigToSol(pnl.net)} (${win ? "+" : ""}${pnl.pct.toFixed(0)}%).\n⚡ <a href="${lx.site}">Trade it on SlimeWire</a>`);
      return true;
    }
    const cap = `${win ? "🟢" : "🔴"} <b>$${escapeTelegramHtml(sym)}</b> — I ${win ? "banked" : "took"} <b>${win ? "+" : ""}◎${lamportsBigToSol(pnl.net)}</b> (${win ? "+" : ""}${pnl.pct.toFixed(0)}%) on @SlimeWiredBot.\n⚡ <a href="${lx.site}">Trade it here →</a>`;
    await sendPhoto(userId, `flex-${sanitizeFilenamePart(sym)}.png`, png, cap, { inline_keyboard: [[{ text: "⚡ Trade on SlimeWire", url: lx.site }]] }, "HTML");
    return true;
  } catch { return false; }
}
async function handleWinFlexCallback(query, userId) {
  const data = String(query?.data || ""); if (!data.startsWith("wf:")) return false;
  const ack = (t) => telegram("answerCallbackQuery", { callback_query_id: query.id, ...(t ? { text: t } : {}) }).catch(() => {});
  const m = data.match(/^wf:([1-9A-HJ-NP-Za-km-z]{32,44})$/);
  if (!m) { await ack(); return true; }
  await ack("📸 Building your flex card…");
  await sendUserWinFlex(userId, m[1]);
  return true;
}

// Detect a "PnL flex / brag" that names a coin, so the scan bot can answer with a SlimeWire card.
// Returns { mint } (a pasted CA wins), { ticker } (first $cashtag), or null. Deliberately tight so it
// only fires on a real win-brag — a numeric gain (+NN% / NNx) OR profit words — that also names a coin.
function detectFlexBragMint(raw) {
  const text = String(raw || "").trim();
  if (text.length < 4 || text.length > 400) return null;
  if (text.startsWith("/")) return null;
  const gain = /(?:^|[\s(+])\+?\d{2,}\s?%/.test(text)                       // +250% or 250%
    || /(?:^|[\s(x])\d{1,3}(?:\.\d+)?\s?x\b/i.test(text)                     // 5x, 12.5x
    || /\b(pnl|profit|profits|gains?|printed|bagged|banger|moon(?:ed|ing|shot)?|ath)\b/i.test(text);
  if (!gain) return null;
  // A pasted contract address anywhere beats a ticker (exact + unambiguous).
  for (const tok of text.split(/[\s,]+/)) {
    const clean = tok.replace(/^\$/, "").replace(/[.,!?)]+$/, "");
    if (isLikelySolMint(clean)) return { mint: clean };
  }
  const tag = /\$([A-Za-z][A-Za-z0-9._]{1,19})\b/.exec(text);
  if (tag) return { ticker: tag[1] };
  return null;
}

async function renderSolScanCardPng(scan = {}, mint, seed = "") {
  const { meta, bonding, best, shield, rug, onchain } = scan || {};
  const stats = scanMarketStatsFromSources({ meta, bonding, best, rug, supply: scan?.supply, mint });
  const bondPct = firstMeaningfulNumber(bonding?.bondingProgressPct);
  const onCurve = typeof stats.onCurve === "boolean"
    ? stats.onCurve
    : Boolean(bonding && bondPct != null && !meta?.graduated);
  const identity = slimeScanPairIdentity({ meta, bonding, best, onchain }, mint, { preferBonding: onCurve });
  const symbol = String(identity.symbol || shortMint(mint)).replace(/^\$+/, "").slice(0, 12);
  const name = String(identity.name || "Solana pair").slice(0, 40);
  const createdAt = Number(stats.createdAt) || 0;
  const rail = xRailLabel(mint, best, bonding);
  const { verdict, tone } = xVerdict(shield, rug, stats.liq, stats.mc, seed || mint);
  // The text acknowledgement is already visible before this render runs, so let a cold image CDN finish.
  // The former 1.2s cap routinely threw away valid metadata PFPs on Render.
  const liveLogo = scan?.pending ? null : await scanFastTimeout(
    xCoinLogo(scan, mint),
    Math.max(1_500, Number(process.env.TG_SCAN_PFP_TIMEOUT_MS || 3_500)),
    null
  );
  const logo = liveLogo || await xFallbackLogoBuffer(symbol || shortMint(mint), seed || mint);
  return renderXScanCard({
    symbol,
    name,
    mcLabel: stats.mc > 0 ? scanFmtMoney(stats.mc) : "—",
    liqLabel: stats.liq > 0 ? scanFmtMoney(stats.liq) : "—",
    ageLabel: createdAt > 0 ? xAgeLabel(Date.now() - createdAt) : "checking",
    railLabel: rail,
    volumeLabel: stats.volume24h > 0 ? `${scanFmtMoney(stats.volume24h)} 24H` : "checking 24H",
    holderLabel: stats.holders > 0 ? scanFmtSupply(stats.holders) : "checking",
    verdict,
    verdictTone: tone,
    changeLabel: Number.isFinite(stats.ch1) ? `${stats.ch1 >= 0 ? "+" : ""}${stats.ch1.toFixed(1)}%` : "checking",
    changeTone: Number.isFinite(stats.ch1) ? (stats.ch1 >= 0 ? "up" : "down") : "",
    logoBuffer: logo,
    bgDir: X_CARD_BG_DIR,
    seed: seed || symbol || mint
  });
}

function slimeScanHardTradeRisk(scan = null) {
  if (!scan) return false;
  const verdict = String(scan?.shield?.verdict || "").trim().toUpperCase();
  return Boolean(
    slimeShieldHasHardDanger(scan.shield)
    || verdict === "AVOID"
    || scan?.rug?.rugged
    || scan?.rug?.mintAuthority
    || scan?.rug?.freezeAuthority
  );
}

function slimeScanSafetyProofReady(scan = null) {
  return Boolean(scan?.shield && scan?.rug?.authoritiesKnown === true);
}

function slimeScanPendingKeyboard(mint, reason = "pair") {
  const label = reason === "safety" ? "⏳ Safety check running" : "⏳ Pair check running";
  return { inline_keyboard: [
    [{ text: label, url: reason === "safety" ? `https://rugcheck.xyz/tokens/${mint}` : `https://dexscreener.com/solana/${mint}` }],
    [{ text: "🔎 Solscan", url: `https://solscan.io/token/${mint}` }]
  ] };
}

function slimeScanKeyboardForResult(mint, tickerSymbol = "", scan = null, fallback = null) {
  if (slimeScanHardTradeRisk(scan)) {
    return { inline_keyboard: [
      [{ text: "🚫 Hard risk · Buy disabled", url: `https://rugcheck.xyz/tokens/${mint}` }],
      [{ text: "📊 View-only chart", callback_data: `scchart:s:${mint}:30m` }, { text: "🔎 Solscan", url: `https://solscan.io/token/${mint}` }]
    ] };
  }
  if (!slimeScanPairIdentity(scan, mint).ready) return slimeScanPendingKeyboard(mint, "pair");
  if (!slimeScanSafetyProofReady(scan)) return slimeScanPendingKeyboard(mint, "safety");
  return fallback || slimeScanKeyboard(mint, tickerSymbol);
}

function formatSlimeScanCard({ mint, meta, rug, shield, bonding, best, dexPaid, dexPromotion, supply, callerLine, contextHtml, ath }) {
  const esc = escapeTelegramHtml;
  const links = slimewireTokenLinks(mint);
  const dex = dexScreenerUrl(mint);
  const dexId = meta?.dexId || (mint.endsWith("pump") ? "pump" : "sol");

  // header status FIRST — it also decides metadata PRECEDENCE: a coin still ON the bonding
  // curve reads Pump-first (live + accurate there); a migrated coin reads Dex-first (Pump
  // metadata freezes at migration). This is the "pump coins use Pump first" priority.
  const stats = scanMarketStatsFromSources({ meta, bonding, best, rug, supply, mint });
  const bondPct = firstMeaningfulNumber(bonding?.bondingProgressPct);
  const onCurve = typeof stats.onCurve === "boolean"
    ? stats.onCurve
    : Boolean(bonding && bondPct != null && !meta?.graduated);
  const identity = slimeScanPairIdentity({ meta, bonding, best }, mint, { preferBonding: onCurve });
  const sym = (identity.symbol || shortMint(mint)).slice(0, 18);
  const name = (identity.name || "Solana pair").slice(0, 40);
  const quoteSymbol = (identity.quoteSymbol || "SOL").slice(0, 16);
  const pick = (pumpVal, dexVal) => onCurve ? firstMeaningfulNumber(pumpVal, dexVal) : firstMeaningfulNumber(dexVal, pumpVal);
  const mc = stats.mc;
  const liq = stats.liq;
  const { volume24h, ch24, ch1, buys1, sells1 } = stats;
  const priceValue = pick(Number(bonding?.priceUsd), Number(best?.priceUsd || meta?.priceUsd)) || (mc && supply ? mc / supply : 0);
  const price = priceValue > 0 ? scanFmtPriceSub(priceValue) : "checking";
  // ATH (real, from SolanaTracker) — only shown when genuinely at/above the current MC.
  const showAth = ath && Number(ath.mc) > 0 && Number(ath.mc) >= mc * 0.999;
  let athTail = "";
  if (showAth) {
    const fromAth = mc > 0 ? Math.round((mc / ath.mc - 1) * 100) : null;
    const aAge = ath.at ? alphaAgeLabel(Math.max(0, Date.now() - Number(ath.at))) : "";
    const parts = [fromAth != null ? `${fromAth}%` : "", aAge].filter(Boolean).join(" / ");
    athTail = parts ? ` <i>(${parts})</i>` : "";
  }

  const headStatus = onCurve
    ? `(Pump @ ${Math.max(0, Math.min(100, Math.round(bondPct)))}%)`
    : (meta?.graduated ? "(Migrated)" : "");
  // AGE + holders come from the aggregator now (all sources + sticky cache) so they always populate.
  const createdMs = Number(stats.createdAt) || 0;
  const headerTail = [`#SOL${headStatus ? ` ${headStatus}` : ""}`, `🌱 ${scanFmtAge(createdMs)}`]
    .concat(stats.holders ? [`∞ ${scanFmtSupply(stats.holders)}`] : [])
    .join(" | ");

  // socials: REAL links only — X, website, Telegram, Pump.fun. (Dropped the generic "about";
  // show only what the token actually has, with a chart/Pump link always present.)
  // Socials: prefer DexScreener, fall back to the creator-entered pump.fun links (bonding). pump has
  // these the instant a coin launches — long before Dex lists it — so a fresh coin shows real 𝕏/TG/Web
  // instead of just the search fallback. (This was reading `meta` only → empty socials on new coins.)
  const twUrl = meta?.twitterUrl || bonding?.twitterUrl;
  const webUrl = meta?.websiteUrl || bonding?.websiteUrl;
  const tgUrl = meta?.telegramUrl || bonding?.telegramUrl;
  const socialBits = [];
  socialBits.push(`<a href="${esc(twUrl || `https://x.com/search?q=${encodeURIComponent(mint)}&f=live`)}">𝕏</a>`);
  if (webUrl) socialBits.push(`<a href="${esc(webUrl)}">🌐 Web</a>`);
  if (tgUrl) socialBits.push(`<a href="${esc(tgUrl)}">✈️ TG</a>`);
  socialBits.push(`<a href="https://pump.fun/coin/${mint}">🚀 Pump</a>`);

  // security (RugCheck full)
  const light = (b, onYes) => b === true ? (onYes ? "🟢" : "🔴") : b === false ? (onYes ? "🔴" : "🟢") : "⚪";
  const top10 = rug?.top10Pct != null ? `${Math.round(rug.top10Pct)}%` : "n/a";
  const holders = stats.holders ? ` | ${stats.holders} (total)` : "";
  const th = rug?.topHolders?.length ? rug.topHolders.map((p) => (Number(p) || 0).toFixed(1)).join("|") : "n/a";
  const devSold = rug ? `${light(rug.devSold, false)} ${rug.devSold === true ? "Yes" : rug.devSold === false ? "No" : "n/a"}` : "⚪ n/a";
  const activeBoosts = dexPromotion?.activeBoosts !== null && dexPromotion?.activeBoosts !== undefined
    && Number.isFinite(Number(dexPromotion.activeBoosts))
    ? Math.max(0, Math.round(Number(dexPromotion.activeBoosts)))
    : null;
  // Keep this actionable and current: approved profile/banner state plus boosts active right now.
  // Unknown provider state is omitted during the instant preview rather than shown as "checking";
  // the progressive scan edit inserts the verified rows as soon as the exact-CA reads finish.
  const dexVisibilityRows = [
    typeof dexPaid === "boolean" ? `DEX Paid <b>${dexPaid ? "✅ Yes" : "⚪ No"}</b>` : null,
    activeBoosts != null
      ? `Active Boosts <b>${activeBoosts > 0 ? `⚡ ${activeBoosts.toLocaleString("en-US")}${dexPromotion?.goldenTicker ? " • 🟡 Golden Ticker" : ""}` : "⚪ None"}</b>`
      : null
  ].filter(Boolean);
  const shieldVerdict = String(shield?.verdict || "").trim().toUpperCase();
  const shieldDanger = Boolean(shield && slimeShieldHasHardDanger(shield));
  const shieldTone = !shield
    ? "⚪"
    : (shieldDanger || shieldVerdict === "AVOID" ? "🔴" : (/RISK|CAUTION|WARN/.test(shieldVerdict) ? "🟡" : "🟢"));
  const shieldScore = Number.isFinite(Number(shield?.score)) ? ` · ${Math.round(Number(shield.score))}/100` : "";
  const shieldStr = shield ? `${shieldTone} ${shieldDanger ? "HARD RISK" : (shieldVerdict || "SCANNED")}${shieldScore}` : "⚪ n/a";
  // Authorities: only render 🟢 none (revoked) when we DEFINITELY read the state (RugCheck report or an
  // on-chain mint decode). If neither resolved, show n/a rather than a false "revoked".
  const authKnown = Boolean(rug && rug.authoritiesKnown);
  const mintAuth = authKnown ? (rug.mintAuthority ? "🔴 active" : "🟢 none") : (rug && rug.mintAuthority ? "🔴 active" : "⚪ n/a");
  const freezeAuth = authKnown ? (rug.freezeAuthority ? "🔴 active" : "🟢 none") : (rug && rug.freezeAuthority ? "🔴 active" : "⚪ n/a");

  const lines = [
    contextHtml || null,
    contextHtml ? "" : null,
    `💊 <b>${esc(name)} ($${esc(sym)} / ${esc(quoteSymbol)})</b>`,
    `├ <code>${esc(mint)}</code>`,
    `└ ${headerTail}`,
    "",
    `📊 <b>Stats</b>`,
    `├ USD  <b>${price}</b> (${scanFmtPct(ch24)})`,
    `├ MC   <b>${mc > 0 ? scanFmtMoney(mc) : "checking"}</b>`,
    `├ Vol  <b>${volume24h > 0 ? scanFmtMoney(volume24h) : "checking"}</b> <i>24h</i>`,
    `├ LP   <b>${liq > 0 ? scanFmtMoney(liq) : "checking"}</b>`,
    `├ Sup  <b>${supply ? scanFmtSupply(supply) : "checking"}</b>`,
    `${showAth ? "├" : "└"} 1H   <b>${scanFmtPct(ch1)}</b>  🟢 ${buys1}  🔴 ${sells1}`,
    showAth ? `└ ATH  <b>${scanFmtMoney(ath.mc)}</b>${athTail}` : null,
    "",
    `🔗 <b>Socials</b>`,
    `└ ${socialBits.join(" • ")}`,
    "",
    dexVisibilityRows.length ? `📣 <b>DEX Visibility</b>` : null,
    ...dexVisibilityRows.map((row, index) => `${index === dexVisibilityRows.length - 1 ? "└" : "├"} ${row}`),
    dexVisibilityRows.length ? "" : null,
    `🔒 <b>Security</b>`,
    `├ Shield   <b>${shieldStr}</b>`,
    `├ Top 10   <b>${top10}</b>${holders}`,
    `├ TH       <b>${th}</b>`,
    `├ Dev Sold <b>${devSold}</b>`,
    `└ Mint <b>${mintAuth}</b> | Freeze <b>${freezeAuth}</b>`,
    "",
    // CALLER INTEL: who first called it here, the MC then, the move since, and how long ago.
    callerLine || null,
    // Compact quick-links row (matches scanner-bot style) — SlimeWire chart first.
    `🔗 <a href="${links.site}">Chart</a> • <a href="${dex}">DS</a> • <a href="https://www.geckoterminal.com/solana/tokens/${mint}">GT</a> • <a href="https://rugcheck.xyz/tokens/${mint}">Rug</a> • <a href="https://solscan.io/token/${mint}">Sol</a> • <a href="${links.proof}">Proof</a>`,
    `<a href="https://www.slimewire.org">⚡ Powered by SlimeWire</a> — Quick Buy below`
  ].filter((l) => l != null); // keep intentional "" section separators; drop omitted (null) lines
  return lines.join("\n");
}

async function deliverTelegramSolScan({ chatId, message, mint, tickerSymbol = "", contextHtml = "", statusHtml = "", keyboard, scan, messageId = null, isPhoto = false, preferText = false, photoOnly = false }) {
  const replyMarkup = slimeScanKeyboardForResult(mint, tickerSymbol, scan, keyboard);
  const stats = scan ? scanMarketStatsFromSources({ meta: scan.meta, bonding: scan.bonding, best: scan.best, rug: scan.rug, supply: scan.supply, mint }) : null;
  const curMc = Number(stats?.mc) || 0;
  const inChannel = Boolean(message?.chat && !isPrivateChat(message.chat));
  const pairIdentity = slimeScanPairIdentity(scan, mint);
  const pairVerified = pairIdentity.ready;
  if (inChannel && pairVerified) {
    await recordTelegramCall(message, mint, curMc, pairIdentity.symbol).catch(() => {});
    if (slimeScanSafetyProofReady(scan) && !slimeScanHardTradeRisk(scan)) {
      void queueScanCopyFromResolvedScan(message, mint, "solana", pairIdentity.symbol).catch(() => {});
    }
  }
  const callerLine = pairVerified
    ? await buildScanCallerFooter(message?.chat?.id, mint, curMc, message).catch(() => "")
    : "";
  const matchLine = tickerScanSelectionLine(tickerSymbol, mint);
  const scanContextLine = [String(contextHtml || "").trim(), matchLine].filter(Boolean).join("\n");
  let text = null;
  if (scan && (scan.meta || scan.bonding || scan.shield || scan.rug || scan.onchain)) {
    try { text = formatSlimeScanCard({ mint, ...scan, contextHtml: scanContextLine, callerLine }); } catch { text = null; }
  }
  if (text && statusHtml) text = `${text}\n\n${statusHtml}`;
  if (text) text = telegramWithCommunityFooter(text);
  if (!text) {
    const failed = telegramWithCommunityFooter(`Could not pull a clean read on <code>${escapeTelegramHtml(mint)}</code> right now. Tap Refresh in More.`);
    let failedSent = null;
    if (messageId && isPhoto) await telegram("editMessageCaption", { chat_id: chatId, message_id: messageId, caption: failed, parse_mode: "HTML", reply_markup: replyMarkup }).catch(() => {});
    else if (messageId) await telegram("editMessageText", { chat_id: chatId, message_id: messageId, text: failed, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: replyMarkup }).catch(() => {});
    else if (!photoOnly) failedSent = await sayHtml(chatId, failed, replyMarkup).catch(() => null);
    return { ok: false, messageId: messageId || failedSent?.message_id || null, isPhoto };
  }
  const captionVisibleLen = text.replace(/<[^>]+>/g, "").length;
  // A message that began as the instant text shell stays text while it is progressively edited. Rendering
  // and uploading a PNG before editMessageText added no value and could hold every market/security update
  // behind a cold image host or Telegram media timeout.
  const shouldRenderPng = (!messageId && !preferText) || isPhoto;
  const renderTimeoutMs = photoOnly
    ? Math.max(6_000, Number(process.env.TG_SCAN_LOGO_TIMEOUT_MS || 0))
    : Math.max(3_800, Number(process.env.TG_SCAN_LOGO_TIMEOUT_MS || 0));
  const png = shouldRenderPng
    ? await scanFastTimeout(renderSolScanCardPng(scan, mint, tickerSymbol || mint), renderTimeoutMs, null)
    : null;
  if (messageId) {
    if (isPhoto && png && captionVisibleLen <= 1024) await editMessagePhotoBuffer(chatId, messageId, png, text, replyMarkup).catch(() => {});
    else if (isPhoto && captionVisibleLen <= 1024) await telegram("editMessageCaption", { chat_id: chatId, message_id: messageId, caption: text, parse_mode: "HTML", reply_markup: replyMarkup }).catch(() => {});
    else if (!isPhoto) await telegram("editMessageText", { chat_id: chatId, message_id: messageId, text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: replyMarkup }).catch(() => {});
    else {
      const shortCaption = `🐸 <b>$${escapeTelegramHtml(firstString(scan?.meta?.symbol, scan?.bonding?.symbol, shortMint(mint)))}</b> · full scan below`;
      if (png) await editMessagePhotoBuffer(chatId, messageId, png, shortCaption, replyMarkup).catch(() => {});
      await sayHtml(chatId, text, replyMarkup).catch(() => {});
    }
    return { ok: true, messageId, isPhoto };
  }
  let sent = null;
  if (png && captionVisibleLen <= 1024) {
    sent = await sendPhoto(chatId, "scan.png", png, text, replyMarkup, "HTML").catch(async () => (
      photoOnly ? null : sayHtml(chatId, text, replyMarkup).catch(() => null)
    ));
  } else if (!photoOnly) sent = await sayHtml(chatId, text, replyMarkup).catch(() => null);
  return { ok: Boolean(sent), messageId: sent?.message_id || null, isPhoto: Boolean(png && captionVisibleLen <= 1024 && sent?.photo) };
}

function slimeScanProgressHtml(missing = [], final = false) {
  const fields = [...new Set((missing || []).map((field) => String(field || "").trim()).filter(Boolean))];
  if (!fields.length) return "";
  const shown = fields.slice(0, 6);
  const tail = fields.length > shown.length ? ` +${fields.length - shown.length} more` : "";
  const label = escapeTelegramHtml(`${shown.join(", ")}${tail}`);
  return final
    ? `⚠️ <i>Live providers did not return: ${label}. Tap Refresh to retry every source.</i>`
    : `⏳ <i>Finishing ${label}…</i>`;
}

async function settleTelegramSolScanCard({
  chatId,
  message,
  mint,
  tickerSymbol = "",
  contextHtml = "",
  keyboard,
  initialScan = null,
  messageId,
  isPhoto = false,
  initialAlreadyRendered = false
}) {
  let accumulated = initialScan;
  let activeMessageId = messageId;
  let activeIsPhoto = isPhoto;
  const updateCard = async (statusHtml = "") => {
    if (!accumulated) return;
    // A normal pasted-CA scan acknowledges with text in under a second. Promote that same logical card
    // once a real metadata image arrives. Previously promotion was attempted only once; one cold CDN or
    // Telegram upload timeout left the scan permanently text-only even though later retries had the PFP.
    if (!activeIsPhoto && activeMessageId && scanImageUrlFromScan(accumulated)) {
      const promoted = await deliverTelegramSolScan({
        chatId, message, mint, tickerSymbol, contextHtml, keyboard, scan: accumulated,
        statusHtml, photoOnly: true
      }).catch(() => null);
      if (promoted?.isPhoto && promoted?.messageId) {
        await telegram("deleteMessage", { chat_id: chatId, message_id: activeMessageId }).catch(() => {});
        activeMessageId = promoted.messageId;
        activeIsPhoto = true;
        return;
      }
    }
    await deliverTelegramSolScan({
      chatId, message, mint, tickerSymbol, contextHtml, keyboard, scan: accumulated,
      messageId: activeMessageId, isPhoto: activeIsPhoto, statusHtml
    });
  };
  let missing = slimeScanRetryMissingFields(accumulated, mint);
  if (accumulated && !initialAlreadyRendered) {
    await updateCard(slimeScanProgressHtml(missing));
  } else if (accumulated && !activeIsPhoto) {
    // The first full response may have fallen back to text because its image host was cold. Give the
    // already-loaded scan the same promotion path before deciding no settling work remains.
    await updateCard(slimeScanProgressHtml(missing));
  }

  // Market scans use stale-while-revalidate for speed, but paid-profile and active-boost state must be
  // current. Refresh just these lightweight exact-CA facts behind the already-posted card, then edit the
  // same message when either value changed. No ticker, market, safety, or RPC fan-out is repeated here.
  const previousDexPaid = accumulated?.dexPaid;
  const previousActiveBoosts = accumulated?.dexPromotion?.activeBoosts;
  const [freshPromotion, freshActiveBoosts] = await Promise.all([
    scanFastTimeout(fetchDexPromotionStatus(mint), 5_500, null),
    scanFastTimeout(fetchDexActiveBoosts(mint), 4_000, null)
  ]);
  const freshDexPromotion = dexPromotionWithBoosts(
    freshPromotion,
    mint,
    accumulated?.best ? [accumulated.best] : [],
    freshActiveBoosts
  );
  const freshDexPaid = typeof freshDexPromotion?.paid === "boolean" ? freshDexPromotion.paid : null;
  if (freshDexPromotion && (
    freshDexPaid !== previousDexPaid
    || freshDexPromotion.activeBoosts !== previousActiveBoosts
  )) {
    accumulated = mergeSlimeScanResults({
      dexPaid: freshDexPaid,
      dexPromotion: freshDexPromotion
    }, accumulated);
    missing = slimeScanRetryMissingFields(accumulated, mint);
    await updateCard(slimeScanProgressHtml(missing));
  }
  if (!missing.length) return accumulated;

  // A just-launched pool and a rate-limited provider are both normal. Keep filling the exact same card
  // through the short indexing window; each pass is upgrade-only, so a later blank response cannot erase
  // an earlier PFP, security read, holder count, volume, or market field.
  const retryAtMs = [1_200, 3_500, 7_000];
  const retryStartedAt = Date.now();
  for (let index = 0; index < retryAtMs.length; index += 1) {
    await sleep(Math.max(0, retryAtMs[index] - (Date.now() - retryStartedAt)));
    const fresh = await gatherSlimeScan(mint, { force: true }).catch(() => null);
    accumulated = mergeSlimeScanResults(fresh, accumulated);
    missing = slimeScanRetryMissingFields(accumulated, mint);
    if (accumulated) {
      const finalAttempt = index === retryAtMs.length - 1;
      if (finalAttempt && missing.includes("identity")) {
        const unresolvedText = telegramWithCommunityFooter([
          "⚠️ <b>Exact Solana pair not found</b>",
          `<code>${escapeTelegramHtml(mint)}</code>`,
          "",
          "This address did not resolve to an exact token pair. Solana CAs are case-sensitive — copy the CA again from the token's official Dex or Pump page, then rescan.",
          "",
          "<i>No trade controls are shown for an unverified pair.</i>"
        ].join("\n"));
        const unresolvedMarkup = { inline_keyboard: [[
          { text: "🔎 Check exact CA", url: `https://solscan.io/account/${mint}` },
          { text: "📊 Search pair", url: `https://dexscreener.com/solana/${mint}` }
        ]] };
        if (activeIsPhoto) await telegram("editMessageCaption", { chat_id: chatId, message_id: activeMessageId, caption: unresolvedText, parse_mode: "HTML", reply_markup: unresolvedMarkup }).catch(() => {});
        else await telegram("editMessageText", { chat_id: chatId, message_id: activeMessageId, text: unresolvedText, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: unresolvedMarkup }).catch(() => {});
        return accumulated;
      }
      await updateCard(slimeScanProgressHtml(missing, finalAttempt));
    }
    if (!missing.length) return accumulated;
  }
  if (!accumulated) {
    await deliverTelegramSolScan({ chatId, message, mint, tickerSymbol, contextHtml, keyboard, scan: null, messageId: activeMessageId, isPhoto: activeIsPhoto });
  }
  return accumulated;
}

// /look <CA>: instant SlimeShield read with trade links - the group-native version of
// pasting a CA into Slime Scope.
async function handleTelegramLookCommand(chatId, message, argument, options = {}) {
  const scanStartedAt = Date.now();
  void telegram("sendChatAction", { chat_id: chatId, action: "typing" }).catch(() => {});
  const rawArgument = String(argument || "");
  const chainHint = options.chainHint || tickerChainHintFromText(rawArgument);
  const tickerArgument = stripTickerChainHintWords(rawArgument, chainHint);
  const tickerSymbol = String(options.tickerSymbol || extractCashtags(rawArgument)[0] || extractBareTickerHints(tickerArgument)[0] || "").replace(/^\$+/, "").trim().toUpperCase();
  const canonicalCryptoId = !hasExplicitScanAddressHint(rawArgument) && !chainHint && tickerSymbol
    ? INFO_MAJOR_CRYPTO_IDS[tickerSymbol.toLowerCase()]
    : "";
  if (canonicalCryptoId) {
    await sendTelegramCryptoInfoCard(chatId, canonicalCryptoId);
    return;
  }
  // One resolver for CA, Dex/Pump links, $tickers, bare scan tickers, and Robinhood Chain 0x contracts.
  const target = await resolveScanTargetFromText(rawArgument, [], { chainHint, interactive: true }).catch(() => null);
  let rhAddr = /^0x[0-9a-fA-F]{40}$/.test(String(target || "")) ? String(target) : "";
  if (rhAddr) {
    const provenTickerCoin = Boolean(rhTickerCandidateForTarget(tickerSymbol, rhAddr)?.contractProof);
    const suppliedRoute = ["token", "wallet", "unknown"].includes(options.rhAddressRoute) ? options.rhAddressRoute : "";
    let rhRoute = provenTickerCoin
      ? "token"
      : suppliedRoute || await scanFastTimeout(classifyRhScanAddress(rhAddr), 700, "unknown").catch(() => "unknown");
    ({ address: rhAddr, route: rhRoute } = await preserveRhPoolBeforeWallet(rhAddr, rhRoute, { provenTickerCoin }));
    if (!options.skipCooldown && tgCommandOnCooldown(chatId, `look:${rhAddr.toLowerCase()}`, TG_LOOK_COOLDOWN_MS)) return;
    const tickerLine = tickerScanSelectionLine(tickerSymbol, rhAddr);
    const contextHtml = [String(options.contextHtml || "").trim(), tickerLine].filter(Boolean).join("\n");
    if (rhRoute !== "wallet") await sendRhScanCard(chatId, rhAddr, {
      ...options,
      rhAddressRoute: rhRoute,
      contextHtml,
      message,
      scanStartedAt,
      brandedMedia: Boolean(String(options.contextHtml || "").trim())
    });
    else await sendWalletScanCard(chatId, rhAddr, message?.from?.id || null);
    return;
  }
  const mint = isLikelySolMint(target) ? String(target) : "";
  if (!mint) {
    if (tickerSymbol) await sayHtml(chatId, `Couldn't verify a strong exact market for <b>$${escapeTelegramHtml(tickerSymbol)}</b> yet. Try again in a few seconds or paste the coin CA.`);
    else await say(chatId, "Usage: /look <token CA> — Solana mint OR Robinhood Chain 0x… address. I'll post the PFP scan card with safety + quick-buy.");
    return;
  }
  // Deduplicate only the SAME token. A busy group may paste several different CAs within 20 seconds;
  // the old chat-wide cooldown silently discarded all but the first and looked like a broken scanner.
  if (!options.skipCooldown && tgCommandOnCooldown(chatId, `look:${mint.toLowerCase()}`, TG_LOOK_COOLDOWN_MS)) return;
  const keyboard = slimeScanKeyboard(mint, tickerSymbol);
  // Clean OgreScanBot-style scan card: stats + audit + socials + a prefilled
  // "Buy on SlimeWire" button. The all-in-one funnel — scan in any channel, buy on the site.
  const previewPromise = waitForSlimeScanPreview(mint, Number(process.env.TG_SCAN_MARKET_PREVIEW_MS || 7_000));
  const scanPromise = gatherSlimeScan(mint).catch(() => null);
  const firstResponseBudgetMs = Math.min(900, Math.max(300, Number(process.env.TG_SCAN_FIRST_RESPONSE_MS || 650)));
  const firstScan = await Promise.race([
    scanPromise.then((value) => ({ kind: "full", value })),
    previewPromise.then((value) => value
      ? ({ kind: "preview", value })
      : scanPromise.then((full) => ({ kind: "full", value: full }))),
    sleep(firstResponseBudgetMs).then(() => ({ kind: "pending", pending: true }))
  ]);
  if (firstScan.pending) {
    const quickScan = { pending: true, meta: { symbol: tickerSymbol || shortMint(mint), name: "Solana token" }, bonding: null, best: null, shield: null, rug: null, supply: 0 };
    const quickKeyboard = slimeScanPendingKeyboard(mint);
    const quickText = [
      String(options.contextHtml || "").trim(),
      `🐸 <b>$${escapeTelegramHtml(tickerSymbol || shortMint(mint))}</b> · Solana`,
      `<code>${escapeTelegramHtml(mint)}</code>`,
      "⏳ <i>Loading live market data now; safety follows on this same card…</i>"
    ].filter(Boolean).join("\n");
    let sent = null;
    let quickHasPhoto = false;
    // Source-attributed Smart Calls keep their branded image shell. Normal /look and pasted-CA scans
    // send text first so a cold Sharp render or Telegram media upload can never delay acknowledgement.
    const quickMediaAllowed = Boolean(String(options.contextHtml || "").trim());
    if (quickMediaAllowed) {
      try {
        const quickPng = await scanFastTimeout(renderSolScanCardPng(quickScan, mint, `quick:${mint}`), 900, null);
        if (quickPng) {
          sent = await sendPhoto(chatId, "scan.png", quickPng, quickText, quickKeyboard, "HTML");
          quickHasPhoto = Boolean(sent?.message_id);
        }
      } catch (error) {
        console.warn(`[tg-scan] quick Sol photo failed ${shortMint(mint)}: ${friendlyError(error)}`);
      }
    }
    // A Telegram media rejection must never look like a dead scanner. Post the same quick card as
    // text immediately, then replace it with the branded card when provider data is ready.
    if (!sent) {
      sent = await telegram("sendMessage", {
        chat_id: chatId,
        text: quickText,
        parse_mode: "HTML",
        disable_web_page_preview: true,
        reply_markup: quickKeyboard
      }).catch((error) => {
        console.warn(`[tg-scan] quick Sol text failed ${shortMint(mint)}: ${friendlyError(error)}`);
        return null;
      });
    }
    if (sent?.message_id) {
      console.info(JSON.stringify({ event: "tg_scan_ack", chain: "solana", mode: "loading", duration_ms: Date.now() - scanStartedAt }));
      void (async () => {
        const staged = await Promise.race([
          previewPromise.then((value) => ({ kind: "preview", value })),
          scanPromise.then((value) => ({ kind: "full", value }))
        ]);
        let loaded = staged.value;
        let activeMessageId = sent.message_id;
        let activeIsPhoto = quickHasPhoto;
        if (loaded && !activeIsPhoto) {
          const promoted = await deliverTelegramSolScan({
            chatId,
            message,
            mint,
            tickerSymbol,
            contextHtml: options.contextHtml,
            keyboard,
            scan: loaded,
            statusHtml: slimeScanProgressHtml(slimeScanRetryMissingFields(loaded, mint)),
            photoOnly: true
          });
          if (promoted.isPhoto && promoted.messageId) {
            await telegram("deleteMessage", { chat_id: chatId, message_id: activeMessageId }).catch(() => {});
            activeMessageId = promoted.messageId;
            activeIsPhoto = true;
            console.info(JSON.stringify({ event: "tg_scan_card", chain: "solana", status: "promoted", chat_id: String(chatId), scan_message_id: activeMessageId }));
          }
        }
        if (staged.kind === "preview") {
          if (loaded && !activeIsPhoto) {
            const previewMissing = slimeScanRetryMissingFields(loaded, mint);
            await deliverTelegramSolScan({
              chatId,
              message,
              mint,
              tickerSymbol,
              contextHtml: options.contextHtml,
              keyboard,
              scan: loaded,
              messageId: activeMessageId,
              isPhoto: activeIsPhoto,
              statusHtml: slimeScanProgressHtml(previewMissing)
            });
          }
          loaded = mergeSlimeScanResults(await scanPromise, loaded);
        }
        await settleTelegramSolScanCard({
          chatId,
          message,
          mint,
          tickerSymbol,
          contextHtml: options.contextHtml,
          keyboard,
          initialScan: loaded,
          messageId: activeMessageId,
          isPhoto: activeIsPhoto
        });
      })().catch((error) => console.warn(`[tg-scan] Sol background upgrade failed ${shortMint(mint)}: ${friendlyError(error)}`));
      return;
    }
  }
  const scan = firstScan.value || await scanPromise;
  const missing = slimeScanRetryMissingFields(scan, mint);
  const delivered = await deliverTelegramSolScan({
    chatId,
    message,
    mint,
    tickerSymbol,
    contextHtml: options.contextHtml,
    keyboard,
    scan,
    statusHtml: slimeScanProgressHtml(missing),
    preferText: true
  });
  if (delivered.messageId) console.info(JSON.stringify({ event: "tg_scan_ack", chain: "solana", mode: firstScan.kind || "full", duration_ms: Date.now() - scanStartedAt }));
  if (delivered.messageId) {
    void (async () => {
      const initialScan = firstScan.kind === "preview"
        ? mergeSlimeScanResults(await scanPromise, scan)
        : scan;
      await settleTelegramSolScanCard({
        chatId,
        message,
        mint,
        tickerSymbol,
        contextHtml: options.contextHtml,
        keyboard,
        initialScan,
        messageId: delivered.messageId,
        isPhoto: delivered.isPhoto,
        initialAlreadyRendered: firstScan.kind !== "preview"
      });
    })().catch((error) => console.warn(`[tg-scan] Sol settling refresh failed ${shortMint(mint)}: ${friendlyError(error)}`));
  }
}

// /alpha: current top picks. Falls through scanner modes and finally the live feed so
// it ALWAYS returns candidates - an empty alpha reply teaches people to stop asking.
async function telegramAlphaRows(chatId) {
  const sources = [
    {
      label: "live trending · safety-screened",
      load: () => webLivePairs(`tg:${chatId}:trending`, "dexTrending", { sort: "best" })
    },
    {
      label: "live surging · safety-screened",
      load: () => webLivePairs(`tg:${chatId}:surging`, "gtSurging", { sort: "best" })
    },
    ...["safe", "fast", "moonshot"].map((mode) => ({
      label: `${mode} scanner · safety-screened`,
      load: () => webSniperScan(`tg:${chatId}:${mode}`, mode)
    }))
  ];
  for (const source of sources) {
    try {
      const feed = await source.load();
      const rows = await telegramSafetyScreenTrendingRows(feed?.rows || [], 3);
      if (rows.length) return { rows, source: source.label };
    } catch {
      // try the next independent source
    }
  }
  try {
    const feed = await webLivePairs(`tg:${chatId}`, "live", { sort: "best" });
    const rows = await telegramSafetyScreenTrendingRows(feed?.rows || [], 3);
    if (rows.length) return { rows, source: "live feed · safety-screened" };
  } catch {
    // degraded reply below
  }
  return { rows: [], source: "" };
}

async function telegramSafetyScreenTrendingRows(rows, limit = 3) {
  const unique = [];
  const seen = new Set();
  for (const row of rows || []) {
    const mint = String(row?.tokenMint || "").trim();
    if (!mint || seen.has(mint) || hasHardBlockedLivePairRisk(row)) continue;
    seen.add(mint);
    unique.push(row);
    if (unique.length >= Math.max(6, Math.max(1, Number(limit) || 3) * 2)) break;
  }
  const checked = await Promise.all(unique.map((row) => screenTickerCandidateSafety({ mint: row.tokenMint, row })));
  return checked
    .filter(({ blocked }) => !blocked)
    .slice(0, Math.max(1, Number(limit) || 3))
    .map(({ candidate, shield }) => ({ ...candidate.row, telegramShield: shield }));
}

async function handleTelegramAlphaCommand(chatId, message) {
  if (tgCommandOnCooldown(chatId, "alpha", isPrivateChat(message?.chat) ? TG_LOOK_COOLDOWN_MS : TG_ALPHA_COOLDOWN_MS)) {
    return;
  }
  const { rows, source } = await telegramAlphaRows(chatId);
  if (!rows.length) {
    await say(chatId, "Feed is warming up - try /alpha again in a minute, or watch the live board on slimewire.org.");
    return;
  }
  // Every pair name is a tappable link straight to its SlimeWire chart; the CA is
  // tap-to-copy. One chart button per pick plus a Quick Buy deep link for the top one.
  const lines = rows.map((row, index) => {
    const symbol = escapeTelegramHtml(row.symbol || shortMint(row.tokenMint));
    const stats = [row.marketCapLabel ? `MC ${row.marketCapLabel}` : "", row.liquidityLabel ? `Liq ${row.liquidityLabel}` : "", row.pairAgeLabel || ""].filter(Boolean).map(escapeTelegramHtml).join(" | ");
    const links = slimewireTokenLinks(row.tokenMint);
    const verdict = String(row.telegramShield?.verdict || "").toUpperCase();
    const shield = verdict ? ` · Shield ${escapeTelegramHtml(verdict)}` : "";
    return `${index + 1}. <a href="${links.site}"><b>$${symbol}</b></a>${stats ? ` - ${stats}` : ""}${shield}\n<code>${escapeTelegramHtml(row.tokenMint)}</code>`;
  });
  const keyboard = {
    inline_keyboard: [
      rows.map((row) => ({
        text: `📈 $${(row.symbol || shortMint(row.tokenMint)).slice(0, 12)}`,
        url: slimewireTokenLinks(row.tokenMint).site
      })),
      [
        ...(slimewireTokenLinks(rows[0].tokenMint).dmBuy ? [{ text: "⚡ Quick Buy (DM)", url: slimewireTokenLinks(rows[0].tokenMint).dmBuy }] : []),
        { text: "Dex", url: dexScreenerUrl(rows[0].tokenMint) }
      ]
    ]
  };
  await sayHtml(chatId, [
    `🐸 <b>SlimeWire alpha</b> (${escapeTelegramHtml(source)}) - tap a pair to open its chart:`,
    ...lines,
    "",
    `/look &lt;CA&gt; for a SlimeShield read | <a href="https://www.slimewire.org">slimewire.org</a>`
  ].join("\n"), keyboard);
}

// /receipts: the SlimeShield brag sheet - flagged tokens that went on to rug, with
// minutes of warning. The single most shareable proof the shield works.
function swampReceiptsKeyboard({ hitRate = null, rugged = 0 } = {}) {
  const receiptsUrl = slimewirePublicUrl("/receipts", { source: "telegram" });
  const reportUrl = slimewirePublicUrl("/api/web/shield-report-card", { days: 7, source: "telegram" });
  const rows = [
    [{ text: "🧾 Swamp Receipts", url: receiptsUrl }, { text: "🖼️ Weekly Card", url: reportUrl }],
    [{ text: "🏅 Proof Wall", url: slimewirePublicUrl("/proof", { source: "telegram" }) }, { text: "Post to X", url: xPostIntentUrl({
      text: `SlimeWire Swamp Receipts: ${rugged} confirmed rugs flagged${hitRate !== null ? `, ${hitRate}% hit-rate on resolved flags` : ""}. Receipts over hype.`,
      url: receiptsUrl,
      hashtags: ["SlimeWire", "Solana"]
    }) }]
  ];
  const startApp = telegramStartAppLink("receipts");
  const addGroup = telegramStartGroupLink("alerts");
  if (startApp || addGroup) rows.push([
    ...(startApp ? [{ text: "Open Mini App", url: startApp }] : []),
    ...(addGroup ? [{ text: "Add to Group", url: addGroup }] : [])
  ]);
  return { inline_keyboard: rows };
}

async function handleTelegramReceiptsCommand(chatId) {
  if (tgCommandOnCooldown(chatId, "receipts", TG_LOOK_COOLDOWN_MS)) return;
  const store = await readShieldReceipts().catch(() => ({ receipts: [] }));
  const receipts = store.receipts || [];
  const resolved = receipts.filter((item) => item.status === "resolved");
  const rugged = resolved.filter((item) => item.outcome === "rugged");
  const recent = rugged.slice(-5).reverse();
  const hitRate = resolved.length ? Math.round((rugged.length / resolved.length) * 100) : null;
  if (!receipts.length) {
    await say(chatId, "Shield receipts are still building - every AVOID/RISK flag gets recorded and tracked to its outcome. Check back soon.");
    return;
  }
  const lines = recent.map((item) => {
    const symbol = escapeTelegramHtml(item.symbol || shortMint(item.mint));
    const warning = item.confirmedAfterMinutes ? `${item.confirmedAfterMinutes >= 90 ? `${Math.round(item.confirmedAfterMinutes / 60)}h` : `${item.confirmedAfterMinutes} min`} of warning` : "flag confirmed";
    return `🔴 $${symbol} - flagged ${escapeTelegramHtml(item.verdict)} (score ${item.score}), rugged. ${warning}.`;
  });
  await sayHtml(chatId, [
    `🛡 <b>Swamp Receipts</b>: ${receipts.length} tokens flagged${hitRate !== null ? `, <b>${hitRate}%</b> of resolved flags went on to rug or die` : ""}.`,
    ...(lines.length ? lines : ["No confirmed rugs in the log yet - flags resolve as the market moves."]),
    "",
    `Live shield reads on every pair: <a href="${slimewireBaseUrl()}">slimewire.org</a> | /look &lt;CA&gt; here`
  ].join("\n"), swampReceiptsKeyboard({ hitRate, rugged: rugged.length }));
}

// One-tap account link: the site issues a short-lived code, the user taps a t.me
// deep link, and the bot maps their Telegram id to their web account. After that the
// engine can credit their wins regardless of how the account was created.
const telegramLinkCodes = new Map(); // code -> { webUserId, expiresAt }

function telegramLinksPath() {
  return path.join(CONFIG.dataDir, "telegram-links.json");
}

async function readTelegramLinks() {
  const store = await readJson(telegramLinksPath());
  if (!store.links || typeof store.links !== "object") store.links = {};
  return store;
}

function issueTelegramLinkCode(webUserId) {
  const code = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
  telegramLinkCodes.set(code, { webUserId: String(webUserId), expiresAt: Date.now() + 10 * 60 * 1000 });
  if (telegramLinkCodes.size > 200) {
    for (const [key, value] of telegramLinkCodes) {
      if (value.expiresAt < Date.now()) telegramLinkCodes.delete(key);
    }
  }
  return code;
}

async function completeTelegramLink(code, tgUserId) {
  const entry = telegramLinkCodes.get(String(code));
  if (!entry || entry.expiresAt < Date.now()) return null;
  telegramLinkCodes.delete(String(code));
  await withFileLock(telegramLinksPath(), async () => {
    const store = await readTelegramLinks();
    store.links[entry.webUserId] = String(tgUserId);
    await writeJsonFile(telegramLinksPath(), store);
  });
  return entry.webUserId;
}

// /mywins on|off (any member, in a group): opt your own TP/SL wins into this chat.
// Link path: DM the bot /web -> log into slimewire.org with the code -> your site
// account IS your Telegram id, so the engine knows which exits are yours.
async function handleTelegramMyWinsToggle(chatId, message, userId, argument) {
  if (isPrivateChat(message.chat)) {
    await say(chatId, "/mywins works inside a group: it posts YOUR SlimeWire take-profit wins to that chat (you opt in per group). First link your account: DM me /web and log into slimewire.org with the code.");
    return;
  }
  const turnOn = /^(on|enable|start|yes)$/i.test(String(argument || "").trim());
  const turnOff = /^(off|disable|stop|no)$/i.test(String(argument || "").trim());
  if (!turnOn && !turnOff) {
    await say(chatId, "Usage: /mywins on - your SlimeWire TP wins post here with credit. /mywins off stops it. Make sure you logged into slimewire.org via the /web code in my DM, or the engine cannot match your trades.");
    return;
  }
  const handle = message.from?.username ? `@${message.from.username}` : (message.from?.first_name || "a degen");
  await withFileLock(telegramGroupsPath(), async () => {
    const store = await readTelegramGroups();
    const key = String(chatId);
    store.groups[key] = store.groups[key] || { addedAt: new Date().toISOString(), alerts: false };
    const subscribers = store.groups[key].winSubscribers || {};
    if (turnOn) subscribers[String(userId)] = String(handle).slice(0, 40);
    else delete subscribers[String(userId)];
    store.groups[key].winSubscribers = subscribers;
    await writeJsonFile(telegramGroupsPath(), store);
  });
  await say(chatId, turnOn
    ? `${handle} - your SlimeWire take-profit wins will post here. (Heads up: that links your wins to this handle in this chat.)`
    : "Your wins will no longer post in this chat.");
}

// Personal win posts: when a TP fires for a user who opted in somewhere, those chats
// get the flex with credit. Anonymous engine posts stay anonymous; this is opt-in.
function postUserWinToGroups(plan, planWallet, triggerReason = "") {
  if (!/^take-profit/i.test(String(triggerReason || ""))) return;
  const planUser = String(plan?.userId || "");
  if (!planUser) return;
  void (async () => {
    try {
      const store = await readTelegramGroups();
      const links = await readTelegramLinks().catch(() => ({ links: {} }));
      const linkedTgId = links.links?.[planUser] || "";
      const movePct = Number(planWallet?.lastTriggerMovePct ?? planWallet?.lastMovePct);
      const moveLabel = Number.isFinite(movePct) ? `+${movePct.toFixed(1)}%` : "a take-profit";
      for (const [groupChatId, group] of Object.entries(store.groups || {})) {
        const handle = group?.winSubscribers?.[planUser] || (linkedTgId ? group?.winSubscribers?.[linkedTgId] : "");
        if (!handle) continue;
        groupBridgeFor(groupChatId).announce("user-win", `${planUser}:${plan?.id || plan?.tokenMint}`, [
          `🎯 <b>${escapeTelegramHtml(handle)} just banked ${escapeTelegramHtml(moveLabel)}</b> on $${escapeTelegramHtml(plan?.copySignal?.symbol || shortMint(plan?.tokenMint || ""))} - SlimeWire server TP fired for them automatically.`,
          `<a href="https://www.slimewire.org">run your exits on slimewire.org</a> | <a href="https://www.slimewire.org/proof">proof</a>`
        ].join("\n"));
      }
    } catch (error) {
      console.warn(`[my-wins] post failed: ${error.message}`);
    }
  })();
}

