const groupBotAdminCache = new Map();
const groupBotDmMenuTargets = new Map(); // `${dmChatId}:${messageId}` -> selected group/channel
async function isGroupBotAdmin(chatId, userId, message = null) {
  // Anonymous group admins post AS the group (sender_chat === chat) — treat as admin.
  if (message?.sender_chat && String(message.sender_chat.id) === String(chatId)) return true;
  const key = `${chatId}:${userId}`;
  const c = groupBotAdminCache.get(key);
  if (c && Date.now() - c.at < 60_000) return c.ok;
  let ok = false;
  try {
    const m = await telegram("getChatMember", { chat_id: chatId, user_id: userId });
    const status = m?.status || m?.result?.status || "";
    ok = ["creator", "administrator"].includes(status);
  } catch {}
  groupBotAdminCache.set(key, { ok, at: Date.now() });
  return ok;
}

function rememberGroupBotDmMenuTarget(dmChatId, messageId, targetChatId, title = "") {
  const key = `${dmChatId}:${messageId}`;
  groupBotDmMenuTargets.set(key, { targetChatId: String(targetChatId), title: String(title || "").slice(0, 80), at: Date.now() });
  if (groupBotDmMenuTargets.size > 1_000) groupBotDmMenuTargets.delete(groupBotDmMenuTargets.keys().next().value);
}

function groupBotDmMenuTarget(dmChatId, messageId) {
  const key = `${dmChatId}:${messageId}`;
  const target = groupBotDmMenuTargets.get(key);
  if (!target) return null;
  if (Date.now() - Number(target.at || 0) > 6 * 60 * 60_000) { groupBotDmMenuTargets.delete(key); return null; }
  return target;
}

async function groupBotDmAdminRooms(userId, selector = "") {
  const store = await readGroupBot();
  const registry = await readTelegramGroups().catch(() => ({ groups: {} }));
  let candidates = Object.entries(store.groups || {}).filter(([chatId]) => /^-?\d+$/.test(chatId)).map(([chatId, entry]) => {
    const registered = registry.groups?.[String(chatId)] || {};
    return {
      chatId: String(chatId),
      title: String(entry?.title || registered.title || `Group ${chatId}`).slice(0, 80),
      username: String(entry?.username || registered.username || "").replace(/^@/, "").slice(0, 64),
      entry,
    };
  });
  const query = String(selector || "").trim();
  if (query) {
    let matches = candidates.filter((room) => groupBotDmRoomMatches(room, query));
    if (!matches.length && /^@[A-Za-z0-9_]{5,32}$/.test(query)) {
      const resolved = await telegram("getChat", { chat_id: query }).catch(() => null);
      const resolvedId = String(resolved?.id || "");
      if (resolvedId) matches = candidates.filter((room) => room.chatId === resolvedId);
    }
    candidates = matches;
  }
  const rooms = [];
  await runWithConcurrency(candidates, 5, async (room) => {
    if (await isGroupBotAdmin(room.chatId, userId).catch(() => false)) rooms.push(room);
  });
  return rooms.sort((a, b) => a.title.localeCompare(b.title));
}

function groupBotDmRoomMatches(room, selector = "") {
  const query = String(selector || "").trim().toLowerCase();
  if (!query) return true;
  const bare = query.replace(/^@/, "");
  const chatId = String(room?.chatId || "").toLowerCase();
  const token = String(room?.entry?.token || "").trim().toLowerCase();
  const username = String(room?.username || room?.entry?.username || "").replace(/^@/, "").toLowerCase();
  const title = String(room?.title || "").toLowerCase();
  return chatId === query || token === query || (username && username === bare) || (bare && title.includes(bare));
}

async function groupBotDmRoomsForSelector(userId, selector = "") {
  return groupBotDmAdminRooms(userId, selector);
}

function groupBotDmRoomListView(rooms = [], selector = "", totalCount = rooms.length) {
  const query = String(selector || "").trim();
  const overflow = Number(totalCount || 0) > rooms.length
    ? `Showing the first ${rooms.length} of ${Number(totalCount)} rooms. Use the fast command below to jump directly.`
    : "";
  return {
    text: rooms.length
      ? [
          query ? `🔎 <b>Matches for</b> <code>${escapeTelegramHtml(query)}</code>` : "🔒 <b>Private group settings</b>",
          "Choose a group or channel you administer. All menus and setup replies stay here in DM; only intentional public actions (like starting a contest) post in the room.",
          overflow,
          "Fast jump: <code>/groupsettings &lt;coin CA, title, @username, or chat ID&gt;</code>",
        ].filter(Boolean).join("\n\n")
      : query
        ? [
            "🔎 <b>No matching admin room</b>",
            `Nothing you administer matched <code>${escapeTelegramHtml(query)}</code>. Try its configured coin CA, group title, @username, or numeric chat ID.`,
          ].join("\n\n")
        : ["🔒 <b>No manageable rooms found</b>", "Add SlimeWireBot to a group/channel, make it an admin, then open <code>/settings</code> there once. Return here and send <code>/groupsettings</code>."].join("\n\n"),
    markup: { inline_keyboard: [
      ...rooms.map((room) => [{ text: `⚙️ ${room.title.slice(0, 42)}`, callback_data: `gb:dm:open:${room.chatId}` }]),
      [{ text: query ? "🏘 Show all" : "🔄 Refresh", callback_data: "gb:dm:list" }],
      [{ text: "✓ Done", callback_data: "gb:close" }],
    ] },
  };
}

async function showGroupBotDmRoomList(dmChatId, userId, messageId = null, selector = "") {
  const query = String(selector || "").trim();
  const rooms = await groupBotDmRoomsForSelector(userId, query);
  if (query && rooms.length === 1) {
    const room = rooms[0];
    const sent = await groupBotPostSetup(room.chatId, room.entry, messageId, dmChatId);
    const menuMessageId = Number(sent?.message_id || messageId || 0);
    if (menuMessageId) rememberGroupBotDmMenuTarget(dmChatId, menuMessageId, room.chatId, room.title);
    return;
  }
  const visibleRooms = rooms.slice(0, 50);
  const view = groupBotDmRoomListView(visibleRooms, query, rooms.length);
  if (messageId) {
    groupBotDmMenuTargets.delete(`${dmChatId}:${messageId}`);
    await telegram("editMessageText", { chat_id: dmChatId, message_id: messageId, text: view.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: view.markup }).catch(() => {});
  } else {
    await sayHtml(dmChatId, view.text, view.markup);
  }
}
// ── Multi-level settings menu: HOME (pick a bot) → per-module sub-menu ──────────
