    [{ text: "📦 Alert Packs", callback_data: "gb:m:packs" }, { text: `${alertsOn ? "🟢" : "⚪"} 📣 Alerts`, callback_data: "gb:alerts" }],
    [{ text: `${refOn} 🎟️ Referral Contest`, callback_data: "gb:m:ref" }],
    [{ text: "✓ Done", callback_data: "gb:close" }]
