async function applyGbInput(message, userId) {
  const chatId = message?.chat?.id;
  const pkey = String(chatId) + ":" + String(userId);
  const pend = gbInputPending.get(pkey);
  if (!pend) return false;
  if (Date.now() - pend.at > 180000) { gbInputPending.delete(pkey); return false; }
  const targetChatId = pend.targetChatId || chatId;
  if (String(targetChatId) !== String(chatId) && !(await isGroupBotAdmin(targetChatId, userId))) {
    gbInputPending.delete(pkey);
    await say(chatId, "You are no longer an admin in that room. Reopen /groupsettings.").catch(() => {});
    return true;
  }
  const raw = String(message.text || "").trim();
  if (!raw) return false;                       // wait for text; don't trap non-text
  gbInputPending.delete(pkey);
  if (/^\/cancel$/i.test(raw)) return true;
  const off = /^off$/i.test(raw);
  if (pend.field === "raidpreset") {
    const parts = raw.split(/\s+/);
    if (parts.length !== 5 || parts.some((value) => !/^\d{1,7}$/.test(value))) {
      await say(chatId, "Use five whole numbers: likes RT replies bookmarks duration-min. Example: 10 5 5 1 15").catch(() => {});
      return true;
    }
    const nums = parts.map(Number);
    if (!nums.slice(0, 4).some((value) => value > 0) || nums[4] < 1 || nums[4] > 24 * 60) {
      await say(chatId, "Set at least one goal above 0 and use a duration from 1 to 1440 minutes.").catch(() => {});
      return true;
    }
    const saved = await setRaidConfig(targetChatId, {
      targets: { likes: nums[0], rts: nums[1], replies: nums[2], bookmarks: nums[3] },
      durationMin: nums[4],
    });
    try { await telegram("deleteMessage", { chat_id: chatId, message_id: message.message_id }); } catch {}
    await groupBotRenderModule(targetChatId, "raid", pend.setupMsgId, chatId).catch(() => {});
    await sayHtml(chatId, `⚔️ Raid default saved: <b>${escapeTelegramHtml(raidPresetLabel(saved))}</b>.`).catch(() => {});
    return true;
  }
  if (pend.field === "portal") {
    try {
      await configureRosePortalIdentity(targetChatId, raw);
      try { await telegram("deleteMessage", { chat_id: chatId, message_id: message.message_id }); } catch {}
      await postRosePortalInvite(targetChatId);
      await groupBotRenderModule(targetChatId, "rose", pend.setupMsgId, chatId).catch(() => {});
    } catch (error) {
      await say(chatId, `Could not save that portal name: ${friendlyError(error)}`).catch(() => {});
    }
    return true;
  }
  const store = await readGroupBot(); const k = String(targetChatId); const e = store.groups[k] || defaultGroupBotEntry();
  const previousTrackedToken = e.token;
  const setRose = (patch) => { e.rose = { ...roseDefaults(), ...(e.rose || {}), ...patch }; };
  switch (pend.field) {
    case "buyemoji": {
      const p = raw.split(/\s+/), custom = telegramCustomEmojiFromMessage(message);
      e.buyEmoji = custom?.fallback || p[0].slice(0, 8);
      e.buyEmojiId = custom?.id || "";
      if (p[1] && Number(p[1]) > 0) e.buyEmojiStep = Math.max(0.01, Math.min(10, Number(p[1])));
      break;
    }
    case "message": e.customText = off ? "" : raw.slice(0, 160); break;
    case "minbuy": e.minBuySol = Math.max(0, Number(raw) || 0); break;
    case "track": {
      if (/^0x[0-9a-fA-F]{40}$/.test(raw) && !(await isRhContract(raw).catch(() => false))) {
        await say(chatId, "That Robinhood address is a wallet, not a coin contract, so Buy Bot did not track it.");
      } else if (solanaPublicKeyLike(raw) || /^0x[0-9a-fA-F]{40}$/.test(raw)) {
        e.token = raw; e.tokenAt = Date.now(); e.features = e.features || {}; e.features.buybot = true;
      }
      break;
    }
    case "welcome": setRose({ welcome: off ? null : raw.slice(0, 3500) }); break;
    case "rules": setRose({ rules: off ? null : raw.slice(0, 3500) }); break;
    case "antiflood": setRose({ antiflood: Math.max(0, Math.min(50, parseInt(raw, 10) || 0)) }); break;
    case "autowhitelist": setRose({ autoWhitelist: Math.max(0, Math.min(100, parseInt(raw, 10) || 0)) }); break;
    case "whalesmin": {
      const current = whalesConfig(e);
      e.whales = {
        ...current,
        on: off ? false : current.on,
        minHold: off ? current.minHold : Math.max(1, Number(raw) || 1),
        mint: current.mint || e.token || null
      };
      break;
    }
    case "refprize": e.referral = { ...referralConfig(e), prize: off ? "" : raw.slice(0, 100) }; break;
    case "refamount": e.referral = { ...referralConfig(e), rewardAmount: Math.max(0, Number(raw) || 0) }; break;
    case "refcoin": {
      const rc = referralConfig(e);
      if (off) { e.referral = { ...rc, rewardMint: "", rewardSymbol: "" }; }
      else if (solanaPublicKeyLike(raw)) {
        let sym = "";
        try { const meta = await getDexScreenerTokenMetadata(raw).catch(() => null); sym = meta ? String(meta.symbol || meta.baseSymbol || meta.ticker || "").slice(0, 12) : ""; } catch {}
        e.referral = { ...rc, rewardKind: "coin", rewardMint: raw, rewardSymbol: sym };
      }
      break;
    }
    default: break;
  }
  store.groups[k] = e; await writeGroupBot(store);
  if (pend.field === "track") {
    await onGroupBotTokenChanged(targetChatId, previousTrackedToken, e.token);
  }
  try { await telegram("deleteMessage", { chat_id: chatId, message_id: message.message_id }); } catch {}
  await groupBotRenderModule(targetChatId, pend.module || GB_INPUT_MODULE[pend.field] || "buy", pend.setupMsgId, chatId).catch(() => {});
  return true;
}
// Telegram rejects text messages over 4,096 characters. Help is deliberately compact, and this
// final guard keeps future additions safe by sending complete lines in <=3,900-character chunks.
function telegramHelpChunks(text, limit = 3900) {
  const chunks = [];
  let current = "";
  const flush = () => { if (current) { chunks.push(current); current = ""; } };
  for (const rawLine of String(text || "").split("\n")) {
    let lines = [rawLine];
    if (rawLine.length > limit) {
      lines = [];
      let part = "";
      for (const char of rawLine.replace(/<[^>]*>/g, "")) {
        const escaped = escapeTelegramHtml(char);
        if (part && part.length + escaped.length > limit) { lines.push(part); part = ""; }
        part += escaped;
      }
      if (part) lines.push(part);
    }
    for (const line of lines) {
      const next = current ? `${current}\n${line}` : line;
      if (next.length > limit) flush();
      current = current ? `${current}\n${line}` : line;
    }
  }
  flush();
  return chunks.length ? chunks : ["Use /menu to open SlimeWire."];
}
async function sendTelegramHelp(chatId, text) {
  for (const chunk of telegramHelpChunks(text)) await sayHtml(chatId, chunk);
}

