  if (data === "gb:ref:board") { await sayHtml(outputChatId, referralBoardText(referralConfig(await getGroupBotEntry(chatId)), userId)).catch(() => {}); await ack(); return true; }
  if (data === "gb:ref:kind") { const cfg = referralConfig(await getGroupBotEntry(chatId)); await setGroupSub(chatId, "referral", { rewardKind: cfg.rewardKind === "coin" ? "sol" : "coin" }); await groupBotRenderModule(chatId, "ref", messageId, outputChatId); await ack(cfg.rewardKind === "coin" ? "Reward kind: SOL" : "Reward kind: Coin"); return true; }
