const GROUP_BUY_STATS_INTERVAL_MS = 8 * 60 * 60_000;
const groupBuyStatsEvents = new Map(); // token -> rolling observed buys (deduped, max 24h)
let groupBuyStatsTickRunning = false;

function groupBuyStatsEventTime(value) {
  let at = Number(value) || 0;
  if (at > 0 && at < 1e12) at *= 1000;
  if (!(at > 0)) at = Date.parse(String(value || "")) || Date.now();
  return at;
}

function groupBuyStatsSmartTrader(trader) {
  const wallet = String(trader || "").trim();
  if (!wallet) return false;
  return KOL_WALLETS.has(wallet)
    || autoKolWallets.has(wallet)
    || trackedKolWallets.has(wallet)
    || isWinnerWallet(walletObs.get(wallet));
}

function recordGroupBuyStats(token, event = {}) {
  const target = String(token || "").trim();
  if (!target) return;
  const key = target.toLowerCase();
  const now = Date.now();
  const at = groupBuyStatsEventTime(event.at);
  const tx = String(event.tx || "").trim();
  const trader = String(event.trader || "").trim();
  const native = Number(event.native) || 0;
  const usd = Number(event.usd) || 0;
  const fingerprint = tx || `${trader}:${native.toFixed(9)}:${Math.floor(at / 30_000)}`;
  const current = groupBuyStatsEvents.get(key) || [];
  if (!current.some((row) => row.fingerprint === fingerprint)) {
    current.push({ at, tx, trader, native, usd, network: event.network === "robinhood" ? "robinhood" : "solana", smart: groupBuyStatsSmartTrader(trader), fingerprint });
  }
  const fresh = current.filter((row) => now - row.at <= 24 * 60 * 60_000).slice(-2_000);
  groupBuyStatsEvents.set(key, fresh);
}

function groupBuyStatsObserved(token) {
  const now = Date.now();
  const rows = (groupBuyStatsEvents.get(String(token || "").toLowerCase()) || []).filter((row) => now - row.at <= 24 * 60 * 60_000);
  const eightHour = rows.filter((row) => now - row.at <= GROUP_BUY_STATS_INTERVAL_MS);
  const whales = rows.filter((row) => row.usd >= 500);
  const smart = rows.filter((row) => row.smart);
  const biggest = rows.slice().sort((a, b) => b.usd - a.usd)[0] || null;
  return { rows, eightHour, whales, smart, biggest };
}
// Buttons under a buy card: Chart · Buy · Vote (the reference's clickable row), then a socials row
