const GROUP_BUY_TRADE_SEEN_LIMIT = 5_000;
const GROUP_BUY_INITIAL_LOOKBACK_MS = 30_000;
const GROUP_BUY_PROCESS_STARTED_AT = Date.now();
const configuredGroupBuyHttpSpacingMs = Number(process.env.GROUP_BUY_HTTP_MIN_INTERVAL_MS);
const GROUP_BUY_HTTP_MIN_INTERVAL_MS = Number.isFinite(configuredGroupBuyHttpSpacingMs)
  ? Math.max(100, Math.min(5_000, configuredGroupBuyHttpSpacingMs))
  : 350;
const groupBuySeenTx = new Map(); // cross-source events already handed to the downstream queue
const groupBuyHttpState = new Map(); // HTTP-only boundaries; websocket events never mutate this map
const groupBuyTradeDeliveryQueues = new Map();
const groupBuyTradeHandoffInFlight = new Map();
const groupBuyTradePollInFlight = new Set();
const groupBuyTradeWakePending = new Map();
const groupBuyTradeWakeConfirmTimers = new Map();
const GROUP_BUY_WAKE_CONFIRM_DELAYS_MS = [500, 1_000, 2_000, 4_000];
const groupBuyTradeBackoff = new Map();
