// GROUP_BUY_RELIABILITY_HELPERS_START
// These small state machines stay dependency-light so the failure cases can be exercised without
// booting the monolith or talking to Pump/Telegram in tests.
function createGroupBuyHostRateGate({
  minIntervalMs = 250,
  maxPriorityBurst = 8,
  evictionPriority = 120,
  maxQueue = Number.POSITIVE_INFINITY,
  maxWaitMs = 0,
  nowFn = () => Date.now(),
  sleepFn = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds)),
} = {}) {
  const queue = [];
  let sequence = 0;
  let pumping = false;
  let priorityBurst = 0;
  let nextStartAt = 0;
  let cooldownUntil = 0;
  let rejected = 0;
  let evicted = 0;
  let expired = 0;
  const spacing = Math.max(0, Number(minIntervalMs) || 0);
  const capacity = Number.isFinite(Number(maxQueue))
    ? Math.max(1, Math.floor(Number(maxQueue)))
    : Number.POSITIVE_INFINITY;
  const defaultWaitMs = Math.max(0, Number(maxWaitMs) || 0);
  const gateError = (code, message) => {
    const error = new Error(message);
    error.code = code;
    return error;
  };
  const rejectExpired = () => {
    const now = nowFn();
    for (let index = queue.length - 1; index >= 0; index -= 1) {
      const item = queue[index];
      if (!(item.expiresAt > 0) || item.expiresAt > now) continue;
      queue.splice(index, 1);
      expired += 1;
      item.reject(gateError("GROUP_BUY_GATE_EXPIRED", "Provider request expired in the host queue"));
    }
  };
  const pump = async () => {
    if (pumping) return;
    pumping = true;
    try {
      while (queue.length) {
        rejectExpired();
        if (!queue.length) break;
        while (true) {
          const now = nowFn();
          const gateWaitMs = Math.max(0, nextStartAt - now, cooldownUntil - now);
          const earliestExpiryAt = queue.reduce((earliest, item) => (
            item.expiresAt > 0 && (!earliest || item.expiresAt < earliest) ? item.expiresAt : earliest
          ), 0);
          const expiryWaitMs = earliestExpiryAt > now ? earliestExpiryAt - now : 0;
          const waitMs = gateWaitMs > 0 && expiryWaitMs > 0
            ? Math.min(gateWaitMs, expiryWaitMs)
            : gateWaitMs;
          if (!(waitMs > 0)) break;
          await sleepFn(waitMs);
          rejectExpired();
          if (!queue.length) break;
        }
        if (!queue.length) break;
        queue.sort((a, b) => b.priority - a.priority || a.sequence - b.sequence);
        const lowerPriorityIndex = priorityBurst >= Math.max(1, Number(maxPriorityBurst) || 8)
          ? queue.findIndex((item) => item.priority <= 0)
          : -1;
        const [item] = queue.splice(lowerPriorityIndex >= 0 ? lowerPriorityIndex : 0, 1);
        priorityBurst = item.priority > 0 ? priorityBurst + 1 : 0;
        nextStartAt = nowFn() + spacing;
        Promise.resolve()
          .then(item.operation)
          .then(item.resolve, item.reject);
      }
    } finally {
      pumping = false;
      if (queue.length) void pump();
    }
  };
  return {
    schedule(operation, { priority = 0 } = {}) {
      return new Promise((resolve, reject) => {
        rejectExpired();
        const normalizedPriority = Number(priority) || 0;
        if (queue.length >= capacity) {
          const evictionIndex = normalizedPriority >= Math.max(1, Number(evictionPriority) || 120) ? queue
            .map((item, index) => ({ item, index }))
            .filter(({ item }) => item.priority < normalizedPriority)
            .sort((a, b) => a.item.priority - b.item.priority || a.item.sequence - b.item.sequence)[0]?.index ?? -1
            : -1;
          if (evictionIndex < 0) {
            rejected += 1;
            reject(gateError("GROUP_BUY_GATE_FULL", "Provider request queue is full"));
            return;
          }
          const [discarded] = queue.splice(evictionIndex, 1);
          evicted += 1;
          discarded.reject(gateError("GROUP_BUY_GATE_EVICTED", "Background provider request yielded to a live buy"));
        }
        const queuedAt = nowFn();
        const waitLimit = defaultWaitMs;
        queue.push({
          operation,
          priority: normalizedPriority,
          sequence: sequence++,
          queuedAt,
          expiresAt: waitLimit > 0 ? queuedAt + waitLimit : 0,
          resolve,
          reject,
        });
        void pump();
      });
    },
    cooldown(milliseconds) {
      const delay = Math.max(0, Number(milliseconds) || 0);
      cooldownUntil = Math.max(cooldownUntil, nowFn() + delay);
      return cooldownUntil;
    },
    snapshot() {
      const now = nowFn();
      const oldestQueuedAt = queue.reduce((oldest, item) => !oldest || item.queuedAt < oldest ? item.queuedAt : oldest, 0);
      return {
        nextStartAt,
        cooldownUntil,
        minIntervalMs: spacing,
        maxQueue: capacity,
        queued: queue.length,
        queuedHighPriority: queue.filter((item) => item.priority > 0).length,
        oldestQueueAgeMs: oldestQueuedAt ? Math.max(0, now - oldestQueuedAt) : 0,
        priorityBurst,
        rejected,
        evicted,
        expired,
      };
    },
  };
}

function groupBuyHeaderValue(headers, name) {
  if (!headers) return "";
  if (typeof headers.get === "function") return String(headers.get(name) || "").trim();
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === String(name).toLowerCase());
  return key ? String(headers[key] || "").trim() : "";
}

function groupBuyRateLimitDelayMs(headers, nowMs = Date.now()) {
  const delays = [];
  const retryAfter = groupBuyHeaderValue(headers, "retry-after");
  if (retryAfter) {
    const seconds = Number(retryAfter);
    if (Number.isFinite(seconds)) delays.push(Math.max(0, seconds * 1_000));
    else {
      const at = Date.parse(retryAfter);
      if (Number.isFinite(at)) delays.push(Math.max(0, at - nowMs));
    }
  }
  for (const name of ["x-ratelimit-reset", "x-rate-limit-reset", "ratelimit-reset"]) {
    const raw = groupBuyHeaderValue(headers, name);
    if (!raw) continue;
    const value = Number(raw);
    if (!Number.isFinite(value)) continue;
    if (value > 1e12) delays.push(Math.max(0, value - nowMs));
    else if (value > 1e9) delays.push(Math.max(0, value * 1_000 - nowMs));
    else delays.push(Math.max(0, value * 1_000));
  }
  return delays.length ? Math.max(...delays) : 0;
}

function groupBuyBackoffDelayMs(failures, retryAfterMs = 0, jitterUnit = Math.random()) {
  const attempt = Math.max(1, Number(failures) || 1);
  const exponential = Math.min(60_000, 1_500 * (2 ** Math.min(6, attempt - 1)));
  const jitter = Math.max(0, Math.min(1, Number(jitterUnit) || 0)) * 250;
  return Math.min(5 * 60_000, Math.max(exponential, Number(retryAfterMs) || 0) + Math.round(jitter));
}

function groupBuyFeedRetryDelayMs(error, failures = 1, jitterUnit = Math.random()) {
  const status = Number(error?.status) || 0;
  const message = String(error?.message || error || "");
  const retryable = [408, 425, 429].includes(status)
    || (status >= 500 && status <= 599)
    || /too many requests|rate limit|timeout|timed out|fetch failed|network|ECONNRESET|ECONNREFUSED|ETIMEDOUT|EAI_AGAIN|socket hang up/i.test(message);
  if (!retryable) return 0;
  // A bare Pump 429 does not always include Retry-After. Five seconds prevents an immediate retry
  // wave, while an explicit provider reset always wins when it is longer.
  const providerDelayMs = Math.max(
    status === 429 ? 5_000 : 0,
    Number(error?.retryAfterMs) || groupBuyRateLimitDelayMs(error?.headers)
  );
  return groupBuyBackoffDelayMs(failures, providerDelayMs, jitterUnit);
}

async function retryGroupBuyFeedOperation(operation, {
  maxAttempts = 4,
  cooldownFn = () => {},
  onRetry = () => {},
} = {}) {
  const attempts = Math.max(1, Math.floor(Number(maxAttempts) || 1));
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await operation({ attempt });
    } catch (error) {
      lastError = error;
      const delayMs = groupBuyFeedRetryDelayMs(error, attempt);
      if (!(delayMs > 0) || attempt >= attempts) throw error;
      // The operation itself is scheduled through the host gate. Extending that gate's cooldown
      // here makes this retry and every other Pump request wait together instead of stampeding.
      cooldownFn(delayMs);
      onRetry({ attempt, delayMs, error });
    }
  }
  throw lastError;
}

function createGroupBuyHttpState(activatedAt = 0) {
  return {
    initialized: false,
    activatedAt: Math.max(0, Number(activatedAt) || 0),
    seen: new Set(),
    aliases: new Set(),
    resume: null,
    lastSuccessAt: 0,
  };
}

function beginGroupBuyHttpProgress(state, activationLookbackMs = 0) {
  if (state.resume) return state.resume;
  state.resume = {
    firstPoll: !state.initialized,
    activationCutoffAt: !state.initialized && Number(state.activatedAt) > 0
      ? Math.max(0, Number(state.activatedAt) - Math.max(0, Number(activationLookbackMs) || 0))
      : 0,
    boundarySeen: new Set(state.seen || []),
    boundaryAliases: new Set(state.aliases || []),
    fresh: [],
    freshSeen: new Set(),
    cursor: "",
    cursors: new Set(),
    reachedSeen: false,
    complete: false,
    pageCountTotal: 0,
  };
  return state.resume;
}

function applyGroupBuyHttpPage(progress, payload, identityFn, aliasFn, timestampFn = () => 0) {
  const trades = Array.isArray(payload?.trades) ? payload.trades : [];
  progress.pageCountTotal += 1;
  for (const trade of trades) {
    const identity = identityFn(trade);
    if (!identity) continue;
    const alias = aliasFn(trade);
    if (progress.boundarySeen.has(identity)) {
      progress.reachedSeen = true;
      break;
    }
    if (progress.freshSeen.has(identity)) continue;
    progress.freshSeen.add(identity);
    progress.fresh.push(trade);
    const timestamp = Number(timestampFn(trade)) || 0;
    if (progress.firstPoll && progress.activationCutoffAt > 0 && timestamp > 0 && timestamp < progress.activationCutoffAt) {
      // Keep this first older row in `fresh` only as the durable HTTP boundary. The caller filters it
      // out of delivery, while commit stores its slot so the next turn stops without walking history.
      progress.reachedSeen = true;
      break;
    }
  }
  const hasMore = Boolean(payload?.pagination?.hasMore);
  if ((progress.firstPoll && !(progress.activationCutoffAt > 0)) || progress.reachedSeen || !hasMore) {
    progress.complete = true;
    return progress;
  }
  const nextCursor = String(payload?.pagination?.nextCursor || "");
  if (!nextCursor || progress.cursors.has(nextCursor)) throw new Error("Pump trade feed returned a broken pagination cursor");
  progress.cursors.add(nextCursor);
  progress.cursor = nextCursor;
  return progress;
}

function commitGroupBuyHttpProgress(state, progress, identityFn, aliasFn, seenLimit = 5_000) {
  if (!progress?.complete || state.resume !== progress) return false;
  const freshIds = progress.fresh.map(identityFn).filter(Boolean);
  const freshAliases = progress.fresh.map(aliasFn).filter(Boolean);
  state.seen = new Set([...freshIds, ...(state.seen || [])].slice(0, seenLimit));
  state.aliases = new Set([...freshAliases, ...(state.aliases || [])].slice(0, seenLimit));
  state.initialized = true;
  state.resume = null;
  state.lastSuccessAt = Date.now();
  return true;
}

function serializeGroupBuyHttpState(state, seenLimit = 5_000) {
  const resume = state?.resume;
  return {
    initialized: Boolean(state?.initialized),
    activatedAt: Number(state?.activatedAt) || 0,
    seen: [...(state?.seen || [])].slice(0, seenLimit),
    aliases: [...(state?.aliases || [])].slice(0, seenLimit),
    lastSuccessAt: Number(state?.lastSuccessAt) || 0,
    resume: resume ? {
      firstPoll: Boolean(resume.firstPoll),
      activationCutoffAt: Number(resume.activationCutoffAt) || 0,
      boundarySeen: [...(resume.boundarySeen || [])].slice(0, seenLimit),
      boundaryAliases: [...(resume.boundaryAliases || [])].slice(0, seenLimit),
      fresh: Array.isArray(resume.fresh) ? resume.fresh : [],
      freshSeen: [...(resume.freshSeen || [])],
      cursor: String(resume.cursor || ""),
      cursors: [...(resume.cursors || [])],
      reachedSeen: Boolean(resume.reachedSeen),
      complete: Boolean(resume.complete),
      pageCountTotal: Math.max(0, Number(resume.pageCountTotal) || 0),
    } : null,
  };
}

function hydrateGroupBuyHttpState(value, seenLimit = 5_000) {
  const state = createGroupBuyHttpState();
  if (!value || typeof value !== "object") return state;
  state.initialized = Boolean(value.initialized);
  state.activatedAt = Number(value.activatedAt) || 0;
  state.seen = new Set((Array.isArray(value.seen) ? value.seen : []).map(String).filter(Boolean).slice(0, seenLimit));
  state.aliases = new Set((Array.isArray(value.aliases) ? value.aliases : []).map(String).filter(Boolean).slice(0, seenLimit));
  state.lastSuccessAt = Number(value.lastSuccessAt) || 0;
  const resume = value.resume;
  if (resume && typeof resume === "object") {
    state.resume = {
      firstPoll: Boolean(resume.firstPoll),
      activationCutoffAt: Number(resume.activationCutoffAt) || 0,
      boundarySeen: new Set((Array.isArray(resume.boundarySeen) ? resume.boundarySeen : []).map(String).filter(Boolean).slice(0, seenLimit)),
      boundaryAliases: new Set((Array.isArray(resume.boundaryAliases) ? resume.boundaryAliases : []).map(String).filter(Boolean).slice(0, seenLimit)),
      fresh: Array.isArray(resume.fresh) ? resume.fresh : [],
      freshSeen: new Set((Array.isArray(resume.freshSeen) ? resume.freshSeen : []).map(String).filter(Boolean)),
      cursor: String(resume.cursor || ""),
      cursors: new Set((Array.isArray(resume.cursors) ? resume.cursors : []).map(String).filter(Boolean)),
      reachedSeen: Boolean(resume.reachedSeen),
      complete: Boolean(resume.complete),
      pageCountTotal: Math.max(0, Number(resume.pageCountTotal) || 0),
    };
  }
  return state;
}

function serializeGroupBuyHandoffState(value, seenLimit = 5_000) {
  return {
    seen: [...(value?.seen || [])].slice(0, seenLimit),
    aliases: [...(value?.aliases || [])].slice(0, seenLimit),
    firstHttpSlotByAlias: [...(value?.firstHttpSlotByAlias || new Map())].slice(-seenLimit),
    initializedAt: Number(value?.initializedAt) || 0,
    lastSuccessAt: Number(value?.lastSuccessAt) || 0,
  };
}

function hydrateGroupBuyHandoffState(value, seenLimit = 5_000) {
  if (!value || typeof value !== "object") return null;
  return {
    seen: new Set((Array.isArray(value.seen) ? value.seen : []).map(String).filter(Boolean).slice(0, seenLimit)),
    aliases: new Set((Array.isArray(value.aliases) ? value.aliases : []).map(String).filter(Boolean).slice(0, seenLimit)),
    firstHttpSlotByAlias: new Map(
      (Array.isArray(value.firstHttpSlotByAlias) ? value.firstHttpSlotByAlias : [])
        .filter((row) => Array.isArray(row) && row.length >= 2 && row[0] && row[1])
        .slice(-seenLimit)
        .map(([alias, slot]) => [String(alias), String(slot)])
    ),
    initializedAt: Number(value.initializedAt) || 0,
    lastSuccessAt: Number(value.lastSuccessAt) || 0,
  };
}

function groupBuyTradeHandoffCandidate(trade, prior, { normalizeFn, identityFn, aliasFn }) {
  const event = normalizeFn(trade);
  const identity = identityFn(trade);
  const alias = aliasFn(trade);
  if (!(Number(event?.solAmount) > 0) || !identity) return null;
  if (prior?.seen?.has(identity)) return null;
  const isHttpSlot = identity.startsWith("slot:");
  if (!isHttpSlot && alias && prior?.aliases?.has(alias)) return null;
  const firstHttpSlot = alias ? prior?.firstHttpSlotByAlias?.get(alias) : "";
  return {
    event,
    identity,
    alias,
    durableKey: isHttpSlot && firstHttpSlot ? identity : (alias || identity),
    firstHttpSlot: isHttpSlot && alias && !firstHttpSlot ? identity : "",
  };
}
// GROUP_BUY_RELIABILITY_HELPERS_END

// Keep the authoritative HTTP boundary and any unfinished page walk on the persistent disk. The
// durable Telegram outbox and these cursors share one locked store, so a restart either replays a
// deterministic alert ID or resumes from the last contiguous Pump page; it never silently baselines
// buys that happened while Render was restarting.
const GROUP_BUY_TRADE_PERSISTED_SEEN_LIMIT = 1_500;
const groupBuySolPersistedFingerprints = new Map();

function groupBuySolStateRecord(mint) {
  return {
    mint: String(mint),
    http: serializeGroupBuyHttpState(
      groupBuyHttpState.get(mint) || createGroupBuyHttpState(),
      GROUP_BUY_TRADE_PERSISTED_SEEN_LIMIT
    ),
    handoff: serializeGroupBuyHandoffState(
      groupBuySeenTx.get(mint),
      GROUP_BUY_TRADE_PERSISTED_SEEN_LIMIT
    ),
    updatedAt: Date.now(),
  };
}

function groupBuySolStateFingerprint(record) {
  const stable = cloneJson(record);
  delete stable.updatedAt;
  if (stable.http) stable.http.lastSuccessAt = 0;
  if (stable.handoff) {
    stable.handoff.initializedAt = 0;
    stable.handoff.lastSuccessAt = 0;
  }
  return JSON.stringify(stable);
}

async function persistGroupBuySolState(mint) {
  const key = String(mint || "").trim();
  if (!key) return false;
  const record = groupBuySolStateRecord(key);
  const fingerprint = groupBuySolStateFingerprint(record);
  if (groupBuySolPersistedFingerprints.get(key) === fingerprint) return false;
  await mutateGroupBuyDeliveryStore((store) => {
    if (!store.sol || typeof store.sol !== "object") store.sol = {};
    if (!store.sol.tokens || typeof store.sol.tokens !== "object") store.sol.tokens = {};
    store.sol.tokens[key] = record;
    return { store };
  });
  groupBuySolPersistedFingerprints.set(key, fingerprint);
  return true;
}

async function restoreGroupBuyReliabilityState() {
  const store = await readGroupBuyDeliveryStore();
  for (const [fromChatId, toChatId] of Object.entries(store.chatRedirects || {})) {
    rememberGroupBuyTelegramChatRedirect(fromChatId, toChatId);
  }
  const tokens = store.sol?.tokens && typeof store.sol.tokens === "object"
    ? store.sol.tokens
    : {};
  for (const [mint, record] of Object.entries(tokens)) {
    if (!mint || !record || typeof record !== "object") continue;
    const http = hydrateGroupBuyHttpState(record.http, GROUP_BUY_TRADE_PERSISTED_SEEN_LIMIT);
    if (!http.initialized && !(http.activatedAt > 0)) http.activatedAt = GROUP_BUY_PROCESS_STARTED_AT;
    groupBuyHttpState.set(mint, http);
    const handoff = hydrateGroupBuyHandoffState(
      record.handoff,
      GROUP_BUY_TRADE_PERSISTED_SEEN_LIMIT
    );
    if (handoff) groupBuySeenTx.set(mint, handoff);
    groupBuySolPersistedFingerprints.set(mint, groupBuySolStateFingerprint(record));
  }
  for (const chatId of pendingGroupBuyChats(store)) scheduleGroupBuyAlertDrain(chatId, 0);
  return {
    solTokens: Object.keys(tokens).length,
    pendingChats: pendingGroupBuyChats(store).length,
  };
}

// Every server-side swap-api.pump.fun consumer shares this one per-IP budget. Buy-feed pages use a
// high priority so chart/observatory/held-price bursts cannot queue live Telegram buys behind them.
// All swap-api.pump.fun consumers share one bounded per-IP lane. Current buy pages use priority
// admission, so a chart storm can no longer build a 40k-request queue or put a live buy behind
// minutes of stale work, while real provider Retry-After still applies host-wide.
const pumpSwapApiHostGate = createGroupBuyHostRateGate({
  minIntervalMs: GROUP_BUY_HTTP_MIN_INTERVAL_MS,
  maxQueue: 64,
  maxWaitMs: 10_000,
});
let pumpSwapApiBackgroundPauseUntil = 0;

function groupBuyHealthSnapshot() {
  const now = Date.now();
  const gate = pumpSwapApiHostGate.snapshot();
  const stream = pumpPortalStream.stats() || {};
  const pendingAgeMs = groupBuyDeliveryHealthState.oldestPendingAt
    ? Math.max(0, now - groupBuyDeliveryHealthState.oldestPendingAt)
    : 0;
  return {
    websocketConnected: Boolean(buyWsDiag.connected),
    websocketTradeEnabled: Boolean(stream.tradeStreamEnabled),
    websocketTradeAuthorized: Boolean(stream.tradeStreamAuthorized),
    websocketTradeAuthorization: String(stream.tradeStreamAuthorization || (stream.tradeStreamEnabled ? "pending" : "disabled")),
    websocketSubscriptions: buyWsSubs.size,
    websocketDesiredSubscriptions: Number(stream.desiredTradeSubscriptions) || 0,
    websocketTrades: Number(buyWsDiag.trades) || 0,
    websocketSubscriptionErrors: Number(stream.currentSubscriptionErrors ?? stream.counters?.subscriptionErrors) || 0,
    websocketLastProviderError: stream.lastProviderError || null,
    chainWakeEnabled: Boolean(GROUP_BUY_CHAIN_WAKE_URL),
    chainWakeConnected: groupBuyChainWakeConnected(),
    chainWakeDesiredSubscriptions: groupBuyChainWakeDesired.size,
    chainWakeSubscriptions: groupBuyChainWakeMintSubscription.size,
    chainWakeNotifications: Number(groupBuyChainWakeDiag.notifications) || 0,
    chainWakePollTriggers: Number(groupBuyChainWakeDiag.pollTriggers) || 0,
    chainWakeErrors: Number(groupBuyChainWakeDiag.errors) || 0,
    chainWakeReconnects: Number(groupBuyChainWakeDiag.reconnects) || 0,
    chainWakeLastEventAgoMs: groupBuyChainWakeDiag.lastEventAt
      ? Math.max(0, now - Number(groupBuyChainWakeDiag.lastEventAt))
      : null,
    chainWakeLastError: groupBuyChainWakeDiag.lastError || null,
    trackedSolTokens: groupBuyHttpState.size,
    polls: Number(groupBuyTradeDiag.polls) || 0,
    pages: Number(groupBuyTradeDiag.pages) || 0,
    rows: Number(groupBuyTradeDiag.rows) || 0,
    buysQueued: Number(groupBuyTradeDiag.buysQueued) || 0,
    errors: Number(groupBuyTradeDiag.errors) || 0,
    rateLimits: Number(groupBuyTradeDiag.rateLimits) || 0,
    retries: Number(groupBuyTradeDiag.retries) || 0,
    wakePolls: Number(groupBuyTradeDiag.wakePolls) || 0,
    wakeBatches: Number(groupBuyTradeDiag.wakeBatches) || 0,
    wakeHits: Number(groupBuyTradeDiag.wakeHits) || 0,
    wakeConfirmations: Number(groupBuyTradeDiag.wakeConfirmations) || 0,
    recoveryQueued: Number(groupBuyTradeDiag.recoveryQueued) || 0,
    cursorGaps: Number(groupBuyTradeDiag.cursorGaps) || 0,
    lastSuccessAgoMs: groupBuyTradeDiag.lastSuccessAt
      ? Math.max(0, now - Number(groupBuyTradeDiag.lastSuccessAt))
      : null,
    httpGateQueued: Number(gate.queued) || 0,
    httpGateOldestQueueAgeMs: Number(gate.oldestQueueAgeMs) || 0,
    httpGateDropped: (Number(gate.rejected) || 0) + (Number(gate.evicted) || 0) + (Number(gate.expired) || 0),
    httpGateCooldownRemainingMs: Math.max(0, Number(gate.cooldownUntil) - now),
    httpBackgroundPauseRemainingMs: Math.max(0, Number(pumpSwapApiBackgroundPauseUntil) - now),
    deliveryPendingAlerts: groupBuyDeliveryHealthState.pendingAlerts,
    deliveryPendingChats: groupBuyDeliveryHealthState.pendingChats,
    deliveryOldestPendingAgeMs: pendingAgeMs,
    deliveryAlertsEnqueued: groupBuyDeliveryDiag.alertsEnqueued,
    deliveryAlertsDelivered: groupBuyDeliveryDiag.alertsDelivered,
    deliveryAlertsRetried: groupBuyDeliveryDiag.alertsRetried,
    deliveryAlertsTerminal: groupBuyDeliveryDiag.alertsTerminal,
    deliveryBuysEnqueued: groupBuyDeliveryDiag.buysEnqueued,
    deliveryBuysDelivered: groupBuyDeliveryDiag.buysDelivered,
    deliveryBuysRetried: groupBuyDeliveryDiag.buysRetried,
    deliveryBuysTerminal: groupBuyDeliveryDiag.buysTerminal,
    deliveryBuysOver10s: groupBuyDeliveryDiag.buysOver10s,
    deliveryLastBuyLatencyMs: groupBuyDeliveryDiag.lastBuyLatencyMs,
    deliveryMaxBuyLatencyMs: groupBuyDeliveryDiag.maxBuyLatencyMs,
    deliveryLastSuccessAgoMs: groupBuyDeliveryDiag.lastDeliveredAt
      ? Math.max(0, now - groupBuyDeliveryDiag.lastDeliveredAt)
      : null,
    deliveryLastErrorAgoMs: groupBuyDeliveryDiag.lastErrorAt
      ? Math.max(0, now - groupBuyDeliveryDiag.lastErrorAt)
      : null,
    persistedSolTokens: groupBuyDeliveryHealthState.persistedSolTokens,
    persistedRobinhoodTokens: groupBuyDeliveryHealthState.persistedRobinhoodTokens,
  };
}

async function pumpSwapApiFetch(url, options = {}, { priority = 0 } = {}) {
  const { timeoutMs = 0, ...fetchOptions } = options || {};
  const normalizedPriority = Number(priority) || 0;
  const backgroundPauseError = () => {
    const error = new Error("Background Pump request deferred to reserve live-buy capacity");
    error.code = "GROUP_BUY_BACKGROUND_DEFERRED";
    error.retryAfterMs = Math.max(0, pumpSwapApiBackgroundPauseUntil - Date.now());
    return error;
  };
  if (normalizedPriority < 120 && Date.now() < pumpSwapApiBackgroundPauseUntil) throw backgroundPauseError();
  return pumpSwapApiHostGate.schedule(async () => {
    // Recheck at execution time because this request may have queued before another response exposed
    // the provider's final quota slot. Recovery/chart work yields; a priority-120 live buy does not.
    if (normalizedPriority < 120 && Date.now() < pumpSwapApiBackgroundPauseUntil) throw backgroundPauseError();
    const response = await fetch(url, {
      ...fetchOptions,
      signal: fetchOptions.signal || (Number(timeoutMs) > 0 ? AbortSignal.timeout(Number(timeoutMs)) : undefined),
    });
    const headerDelayMs = groupBuyRateLimitDelayMs(response.headers);
    const remainingHeader = groupBuyHeaderValue(response.headers, "x-ratelimit-remaining");
    const remaining = remainingHeader ? Number(remainingHeader) : Number.NaN;
    // Leave the final provider slot for a real activity wake. Pausing only background work is crucial:
    // a host-wide cooldown here used to make an observed buy wait for the entire reset window.
    if (Number.isFinite(remaining) && remaining <= 1 && headerDelayMs > 0) {
      pumpSwapApiBackgroundPauseUntil = Math.max(pumpSwapApiBackgroundPauseUntil, Date.now() + headerDelayMs);
    }
    if (response.status === 429) {
      const delayMs = Math.max(5_000, headerDelayMs);
      pumpSwapApiBackgroundPauseUntil = Math.max(pumpSwapApiBackgroundPauseUntil, Date.now() + delayMs);
      // A genuine live request may retry soon, but background work stays parked through the full
      // provider reset. This avoids both a retry storm and a minute-long live-buy gate freeze.
      if (normalizedPriority >= 120) pumpSwapApiHostGate.cooldown(Math.min(5_000, delayMs));
    }
    return response;
  }, { priority: normalizedPriority });
}

async function pumpSwapApiJson(url, options = {}, gateOptions = {}) {
  const { timeoutMs = 5_000, ...fetchOptions } = options || {};
  const response = await pumpSwapApiFetch(url, { ...fetchOptions, timeoutMs }, gateOptions);
  if (!response.ok) {
    const error = new Error(`Pump swap API returned HTTP ${response.status}`);
    error.status = response.status;
    error.retryAfterMs = groupBuyRateLimitDelayMs(response.headers);
    throw error;
  }
  return response.json();
}

function groupBuyTradeNumberKey(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number.toPrecision(12) : "0";
}

function groupBuyTradeTimestampMs(trade) {
  const raw = firstString(trade?.timestamp, trade?.time, trade?.createdAt, trade?.blockTime);
  if (!raw) return 0;
  const numeric = Number(raw);
  if (Number.isFinite(numeric) && numeric > 0) return numeric < 1e12 ? numeric * 1_000 : numeric;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : 0;
}

function groupBuyTradeAlias(trade) {
  const tx = firstString(trade?.tx, trade?.signature);
  const side = String(trade?.type || trade?.txType || "").toLowerCase();
  const trader = firstString(trade?.userAddress, trade?.traderPublicKey, trade?.trader);
  const native = firstMeaningfulNumber(trade?.amountSol, trade?.solAmount, trade?.quoteAmount) || 0;
  const tokens = firstMeaningfulNumber(trade?.baseAmount, trade?.tokenAmount, trade?.tokens) || 0;
  // This shared shape lets the socket and HTTP poller recognize the same buy while still keeping
  // two distinct instructions in one transaction separate when their amounts differ.
  if (tx) return `tx:${tx}:${side}:${trader}:${groupBuyTradeNumberKey(native)}:${groupBuyTradeNumberKey(tokens)}`;
  const timestamp = firstString(trade?.timestamp, trade?.time, trade?.createdAt);
  return timestamp ? `event:${timestamp}:${side}:${trader}:${groupBuyTradeNumberKey(native)}:${groupBuyTradeNumberKey(tokens)}` : "";
}

function groupBuyTradeIdentity(trade) {
  // Pump's slot+instruction id is its stable cursor identity. Prefer it for HTTP pagination; the
  // cross-source transaction alias above separately dedupes a matching websocket event.
  const slotIndexId = firstString(trade?.slotIndexId);
  return slotIndexId ? `slot:${slotIndexId}` : groupBuyTradeAlias(trade);
}

function noteGroupBuyTradePollError(mint, error) {
  const message = friendlyError(error).slice(0, 180);
  groupBuyTradeDiag.errors += 1;
  groupBuyTradeDiag.lastError = message;
  if (Date.now() - groupBuyTradeLastWarnAt >= 60_000) {
    groupBuyTradeLastWarnAt = Date.now();
    console.warn(`[buy-bot] Pump trade feed failed for ${shortMint(mint)}: ${message}`);
  }
}

function scheduleGroupBuyTradeBackoff(mint, error) {
  const current = groupBuyTradeBackoff.get(mint) || { failures: 0, nextAttemptAt: 0 };
  const failures = current.failures + 1;
  const retryAfterMs = Math.max(0, Number(error?.retryAfterMs) || 0);
  const delayMs = groupBuyBackoffDelayMs(failures, retryAfterMs);
  const next = { failures, nextAttemptAt: Date.now() + delayMs, delayMs };
  groupBuyTradeBackoff.set(mint, next);
  if (Number(error?.status) === 429) {
    groupBuyTradeDiag.rateLimits += 1;
  }
  return next;
}

function clearGroupBuyTradeBackoff(mint) {
  groupBuyTradeBackoff.delete(mint);
}

async function fetchGroupBuyTradePage(mint, cursor, options) {
  const priority = Number(options?.priority) || 100;
  const url = new URL(`https://swap-api.pump.fun/v2/coins/${encodeURIComponent(mint)}/trades`);
  url.searchParams.set("limit", String(GROUP_BUY_TRADE_PAGE_LIMIT));
  if (cursor) url.searchParams.set("cursor", cursor);
  return retryGroupBuyFeedOperation(async ({ attempt }) => {
    const response = await pumpSwapApiFetch(url, {
      headers: { accept: "application/json" },
      timeoutMs: 5_000
    }, { priority: Math.max(Number(priority) || 100, attempt > 1 ? 110 : 0) });
    const headerDelayMs = groupBuyRateLimitDelayMs(response.headers);
    if (!response.ok) {
      const error = new Error(`Pump trade feed returned HTTP ${response.status}`);
      error.status = response.status;
      error.retryAfterMs = headerDelayMs;
      error.headers = response.headers;
      // Undici cannot reuse the connection reliably while an error body remains unread.
      try { await response.body?.cancel(); } catch { /* retry still remains cursor-safe */ }
      throw error;
    }
    let payload;
    try {
      payload = await response.json();
    } catch (cause) {
      const error = new Error("Pump trade feed returned invalid JSON", { cause });
      error.status = 502;
      throw error;
    }
    if (!payload || !Array.isArray(payload.trades)) {
      const error = new Error("Pump trade feed returned an invalid response");
      error.status = 502;
      throw error;
    }
    return payload;
  }, {
    maxAttempts: GROUP_BUY_TRADE_FETCH_ATTEMPTS,
    // pumpSwapApiFetch already applies the provider's real Retry-After to the shared host lane. Cap the
    // shared retry pause so one unhealthy mint cannot freeze every other tracked coin for a minute.
    cooldownFn: (delayMs) => pumpSwapApiHostGate.cooldown(Math.min(5_000, delayMs)),
    onRetry: ({ error }) => {
      groupBuyTradeDiag.retries += 1;
      if (Number(error?.status) === 429) groupBuyTradeDiag.rateLimits += 1;
    },
  });
}

async function collectGroupBuyTrades(mint, { onFreshPage = null, priority = 100 } = {}) {
  // The HTTP boundary is deliberately independent from groupBuySeenTx. A websocket event may arrive
  // before Pump's HTTP index contains it; it must never turn the first HTTP read into a historical walk.
  const state = groupBuyHttpState.get(mint) || createGroupBuyHttpState(Date.now());
  groupBuyHttpState.set(mint, state);
  const progress = beginGroupBuyHttpProgress(state, GROUP_BUY_INITIAL_LOOKBACK_MS);
  const firstPoll = progress.firstPoll;
  let pageCount = 0;
  while (pageCount < GROUP_BUY_TRADE_MAX_PAGES && !progress.complete) {
    const payload = await fetchGroupBuyTradePage(mint, progress.cursor, { priority });
    const newestPage = progress.pageCountTotal === 0 && !progress.cursor;
    pageCount += 1;
    groupBuyTradeDiag.pages += 1;
    const trades = payload.trades;
    groupBuyTradeDiag.rows += trades.length;
    const freshStart = progress.fresh.length;
    applyGroupBuyHttpPage(progress, payload, groupBuyTradeIdentity, groupBuyTradeAlias, groupBuyTradeTimestampMs);
    groupBuyTradeDiag.lastSuccessAt = Date.now();
    const pageFresh = progress.fresh.slice(freshStart);
    if (newestPage && !progress.complete && pageFresh.length && typeof onFreshPage === "function") {
      // Pump returns newest-first. Hand current buys to the durable outbox immediately instead of
      // making page one wait for a deep historical cursor walk to finish.
      await onFreshPage(pageFresh, {
        firstPoll,
        activationCutoffAt: Number(progress.activationCutoffAt) || 0,
        pageCount,
      });
    }
  }
  if (!progress.complete) {
    // This is a yield, never a cursor gap: cursor + accumulated rows remain on state.resume. The next
    // turn continues from that exact page instead of finalizing/lossily jumping the boundary.
    groupBuyTradeDiag.paginationYields += 1;
    return { firstPoll, fresh: [], incomplete: true, commit: () => false };
  }
  return {
    firstPoll,
    activationCutoffAt: Number(progress.activationCutoffAt) || 0,
    fresh: progress.fresh.slice(),
    incomplete: false,
    commit: () => commitGroupBuyHttpProgress(
      state,
      progress,
      groupBuyTradeIdentity,
      groupBuyTradeAlias,
      GROUP_BUY_TRADE_SEEN_LIMIT
    ),
  };
}

function normalizeGroupBuyTrade(trade) {
  return {
    eventKey: firstString(trade?.eventKey, groupBuyTradeIdentity(trade)),
    eventAlias: firstString(trade?.eventAlias, groupBuyTradeAlias(trade)),
    detectedAt: firstMeaningfulNumber(trade?.detectedAt, groupBuyTradeTimestampMs(trade)) || Date.now(),
    solAmount: firstMeaningfulNumber(trade?.amountSol, trade?.solAmount, trade?.quoteAmount) || 0,
    usdAmount: firstMeaningfulNumber(trade?.amountUsd, trade?.usdAmount) || 0,
    tokens: firstMeaningfulNumber(trade?.baseAmount, trade?.tokenAmount, trade?.tokens) || 0,
    // priceUsd is the post-trade spot (best for MC); fillPriceUsd is the exact execution fallback.
    priceUsd: firstMeaningfulNumber(trade?.priceUsd, trade?.fillPriceUsd) || 0,
    mcUsd: firstMeaningfulNumber(trade?.mcUsd, trade?.marketCapUsd) || 0,
    liqUsd: firstMeaningfulNumber(trade?.liqUsd, trade?.liquidityUsd) || 0,
    vol24: firstMeaningfulNumber(trade?.vol24, trade?.volume24h) || 0,
    change24: Number.isFinite(Number(trade?.change24)) ? Number(trade.change24) : null,
    trader: firstString(trade?.userAddress, trade?.traderPublicKey, trade?.trader),
    sym: firstString(trade?.symbol, trade?.sym),
    tx: firstString(trade?.tx, trade?.signature)
  };
}

async function handoffGroupBuyTrade(mint, trade) {
  const prior = groupBuySeenTx.get(mint);
  const candidate = groupBuyTradeHandoffCandidate(trade, prior, {
    normalizeFn: normalizeGroupBuyTrade,
    identityFn: groupBuyTradeIdentity,
    aliasFn: groupBuyTradeAlias,
  });
  if (!candidate) return false;
  const claimKeys = [candidate.identity, candidate.alias].filter(Boolean).map((key) => `${mint}:${key}`);
  const existing = claimKeys.map((key) => groupBuyTradeHandoffInFlight.get(key)).find(Boolean);
  if (existing) {
    await existing;
    // Re-evaluate against the newly committed handoff state. This lets an HTTP slot arriving behind
    // its websocket alias safely claim the alias (or its own slot for a second identical instruction).
    return handoffGroupBuyTrade(mint, trade);
  }
  // postGroupBuy resolves only after every target alert is durably inserted into the delivery outbox.
  // Do not claim this event (or let the HTTP cursor commit it) before that durable acceptance.
  const durableHandoff = queueGroupBuyTradeDelivery(mint, {
    ...trade,
    eventKey: candidate.durableKey,
    eventAlias: candidate.alias,
  });
  for (const key of claimKeys) groupBuyTradeHandoffInFlight.set(key, durableHandoff);
  try {
    await durableHandoff;
    const latest = groupBuySeenTx.get(mint) || prior;
    const seen = new Set([candidate.identity, ...(latest?.seen || [])].filter(Boolean).slice(0, GROUP_BUY_TRADE_SEEN_LIMIT));
    const aliases = new Set([candidate.alias, ...(latest?.aliases || [])].filter(Boolean).slice(0, GROUP_BUY_TRADE_SEEN_LIMIT));
    const firstHttpSlotByAlias = new Map(latest?.firstHttpSlotByAlias || []);
    if (candidate.alias && candidate.firstHttpSlot && !firstHttpSlotByAlias.has(candidate.alias)) {
      firstHttpSlotByAlias.set(candidate.alias, candidate.firstHttpSlot);
    }
    while (firstHttpSlotByAlias.size > GROUP_BUY_TRADE_SEEN_LIMIT) {
      firstHttpSlotByAlias.delete(firstHttpSlotByAlias.keys().next().value);
    }
    groupBuySeenTx.set(mint, {
      seen,
      aliases,
      firstHttpSlotByAlias,
      initializedAt: latest?.initializedAt || Date.now(),
      lastSuccessAt: Date.now(),
    });
    return true;
  } finally {
    for (const key of claimKeys) {
      if (groupBuyTradeHandoffInFlight.get(key) === durableHandoff) groupBuyTradeHandoffInFlight.delete(key);
    }
  }
}

async function drainGroupBuyTradeDeliveryQueue(mint) {
  const state = groupBuyTradeDeliveryQueues.get(mint);
  if (!state || state.running) return;
  state.running = true;
  try {
    while (state.items.length) {
      const item = state.items[0];
      try {
        await postGroupBuy(mint, item.event);
        state.items.shift();
        item.resolve(true);
      } catch (error) {
        state.items.shift();
        item.reject(error);
        noteGroupBuyTradePollError(mint, error);
      }
    }
  } finally {
    state.running = false;
    if (!state.items.length) groupBuyTradeDeliveryQueues.delete(mint);
    else void drainGroupBuyTradeDeliveryQueue(mint);
  }
}

function queueGroupBuyTradeDelivery(mint, trade) {
  const event = normalizeGroupBuyTrade(trade);
  if (!(event.solAmount > 0)) return Promise.reject(new Error("Pump buy event did not include a positive SOL amount"));
  if (event.trader) { try { recordEarlyBuyer(mint, { side: "buy", trader: event.trader }); } catch {} }
  const state = groupBuyTradeDeliveryQueues.get(mint) || { items: [], running: false };
  let resolveDelivery;
  let rejectDelivery;
  const durable = new Promise((resolve, reject) => { resolveDelivery = resolve; rejectDelivery = reject; });
  state.items.push({ event, resolve: resolveDelivery, reject: rejectDelivery });
  groupBuyTradeDeliveryQueues.set(mint, state);
  groupBuyTradeDiag.buysQueued += 1;
  void drainGroupBuyTradeDeliveryQueue(mint);
  return durable;
}

async function pollGroupBuyTradesForMint(mint, options) {
  const priority = Number(options?.priority) || 100;
  warmGroupBuyMarketContext(mint);
  let collected;
  let handedOff = 0;
  let buysObserved = 0;
  try {
    collected = await collectGroupBuyTrades(mint, {
      priority,
      onFreshPage: async (pageFresh, { firstPoll, activationCutoffAt }) => {
        const liveFresh = firstPoll
          ? pageFresh.filter((trade) => {
              const at = groupBuyTradeTimestampMs(trade);
              return !(activationCutoffAt > 0) || !(at > 0) || at >= activationCutoffAt;
            })
          : pageFresh;
        // Pump returns newest first. Invoke every handoff immediately, but claim the durable
        // per-mint queue oldest first so a burst still reaches Telegram chronologically.
        const buys = liveFresh
          .filter((trade) => String(trade?.type || "").toLowerCase() === "buy")
          .reverse();
        buysObserved += buys.length;
        const results = await Promise.all(buys.map((trade) => handoffGroupBuyTrade(mint, trade)));
        handedOff += results.filter(Boolean).length;
        if (handedOff > 0) groupBuyLastAlertAt.set(mint, Date.now());
      },
    });
  } catch (error) {
    // A page-N failure leaves state.resume pointing at that exact page. Persist the completed prefix
    // before backing off so a Render restart continues the same walk instead of starting over.
    await persistGroupBuySolState(mint).catch((persistError) => {
      console.warn(`[buy-bot] could not checkpoint ${shortMint(mint)} after a feed error: ${friendlyError(persistError)}`);
    });
    scheduleGroupBuyTradeBackoff(mint, error);
    noteGroupBuyTradePollError(mint, error);
    return { handedOff, buysObserved, foundBuy: buysObserved > 0 || handedOff > 0, ok: false };
  }
  clearGroupBuyTradeBackoff(mint);
  const { firstPoll, activationCutoffAt, fresh, incomplete, commit } = collected;
  if (incomplete) {
    await persistGroupBuySolState(mint).catch((error) => {
      console.warn(`[buy-bot] could not checkpoint ${shortMint(mint)} pagination: ${friendlyError(error)}`);
    });
    return { handedOff, buysObserved, foundBuy: buysObserved > 0 || handedOff > 0, ok: true, incomplete: true };
  }
  if (firstPoll) {
    // Walk to a bounded activation cutoff instead of swallowing the whole first page. The one older
    // boundary row remains cursor-only; every timestamped trade in the live startup/enable window is
    // handed off durably before the initial cursor commits.
    const liveFresh = fresh.filter((trade) => {
      const at = groupBuyTradeTimestampMs(trade);
      return !(activationCutoffAt > 0) || !(at > 0) || at >= activationCutoffAt;
    });
    try {
      const buys = liveFresh.filter((trade) => String(trade?.type || "").toLowerCase() === "buy");
      for (const trade of buys.reverse()) if (await handoffGroupBuyTrade(mint, trade)) handedOff += 1;
      if (!commit()) throw new Error("Pump baseline cursor could not be committed");
      await persistGroupBuySolState(mint);
      if (handedOff > 0) groupBuyLastAlertAt.set(mint, Date.now());
    } catch (error) {
      scheduleGroupBuyTradeBackoff(mint, error);
      noteGroupBuyTradePollError(mint, error);
      return { handedOff, buysObserved, foundBuy: buysObserved > 0 || handedOff > 0, ok: false };
    }
    return { handedOff, buysObserved, foundBuy: buysObserved > 0 || handedOff > 0, ok: true };
  }
  // The completed window remains oldest-first after the newest page got its latency-first handoff.
  // Its page-one rows are already claimed, so this pass only queues the older undispatched buys.
  const buys = fresh.filter((trade) => String(trade?.type || "").toLowerCase() === "buy");
  try {
    for (const trade of buys.reverse()) if (await handoffGroupBuyTrade(mint, trade)) handedOff += 1;
    // Commit the HTTP boundary only after every discovered buy has entered the durable delivery outbox
    // (or was already claimed by the websocket). A thrown handoff leaves the completed resume window
    // intact, and the next turn safely tries it again.
    if (!commit()) throw new Error("Pump trade cursor could not be committed");
    await persistGroupBuySolState(mint);
  } catch (error) {
    await persistGroupBuySolState(mint).catch((persistError) => {
      console.warn(`[buy-bot] could not checkpoint ${shortMint(mint)} delivery retry: ${friendlyError(persistError)}`);
    });
    scheduleGroupBuyTradeBackoff(mint, error);
    noteGroupBuyTradePollError(mint, error);
    return { handedOff, buysObserved, foundBuy: buysObserved > 0 || handedOff > 0, ok: false };
  }
  if (handedOff > 0) groupBuyLastAlertAt.set(mint, Date.now());
  return { handedOff, buysObserved, foundBuy: buysObserved > 0 || handedOff > 0, ok: true };
}

function queueGroupBuyTradePoll(mint, options) {
  const force = Boolean(options?.force);
  const priority = Number(options?.priority) || 100;
  const confirmOnce = Boolean(options?.confirmOnce);
  const confirmAttempt = Math.max(0, Number.parseInt(options?.confirmAttempt ?? "0", 10) || 0);
  mint = String(mint || "").trim();
  if (!mint) return false;
  if (confirmOnce && groupBuyTradeWakeConfirmTimers.has(mint)) {
    clearTimeout(groupBuyTradeWakeConfirmTimers.get(mint));
    groupBuyTradeWakeConfirmTimers.delete(mint);
  }
  if (groupBuyTradePollInFlight.has(mint)) {
    if (force) {
      const pending = groupBuyTradeWakePending.get(mint) || {};
      groupBuyTradeWakePending.set(mint, {
        force: true,
        priority: Math.max(Number(pending.priority) || 100, Number(priority) || 100),
        confirmOnce: Boolean(pending.confirmOnce || confirmOnce),
        confirmAttempt: confirmOnce ? confirmAttempt : (Number(pending.confirmAttempt) || 0),
      });
    }
    return false;
  }
  const backoff = groupBuyTradeBackoff.get(mint);
  if (!force && backoff && Date.now() < backoff.nextAttemptAt) return false;
  groupBuyTradePollInFlight.add(mint);
  void pollGroupBuyTradesForMint(mint, { priority })
    .then((result) => {
      if (!confirmOnce || result?.foundBuy || groupBuyTradeBackoff.has(mint)) return;
      const delayMs = GROUP_BUY_WAKE_CONFIRM_DELAYS_MS[confirmAttempt];
      if (!(delayMs > 0)) return;
      const timer = setTimeout(() => {
        groupBuyTradeWakeConfirmTimers.delete(mint);
        groupBuyTradeDiag.wakeConfirmations += 1;
        queueGroupBuyTradePoll(mint, {
          force: true,
          priority: 120,
          confirmOnce: true,
          confirmAttempt: confirmAttempt + 1,
        });
      }, delayMs);
      if (timer.unref) timer.unref();
      groupBuyTradeWakeConfirmTimers.set(mint, timer);
    })
    .catch((error) => noteGroupBuyTradePollError(mint, error))
    .finally(() => {
      groupBuyTradePollInFlight.delete(mint);
      const pending = groupBuyTradeWakePending.get(mint);
      if (!pending) return;
      groupBuyTradeWakePending.delete(mint);
      queueGroupBuyTradePoll(mint, pending);
    });
  return true;
}

async function pollGroupBuyTrades() {
  groupBuyTradeDiag.polls += 1;
  try {
    const store = await readGroupBot();
    const mints = [];
    for (const entry of Object.values(store.groups || {})) {
      const mint = String(entry?.token || "").trim();
      if (groupBotFeatureOn(entry, "buybot") && mint && !/^0x[0-9a-fA-F]{40}$/.test(mint) && !mints.includes(mint)) mints.push(mint);
    }
    const active = new Set(mints);
    for (const mint of groupBuySeenTx.keys()) if (!active.has(mint) && !groupBuyTradePollInFlight.has(mint)) groupBuySeenTx.delete(mint);
    for (const mint of groupBuyHttpState.keys()) if (!active.has(mint) && !groupBuyTradePollInFlight.has(mint)) groupBuyHttpState.delete(mint);
    for (const mint of groupBuyTradeBackoff.keys()) if (!active.has(mint) && !groupBuyTradePollInFlight.has(mint)) groupBuyTradeBackoff.delete(mint);
    for (const mint of groupBuyTradeWakePending.keys()) if (!active.has(mint)) groupBuyTradeWakePending.delete(mint);
    for (const [mint, timer] of groupBuyTradeWakeConfirmTimers) {
      if (active.has(mint)) continue;
      clearTimeout(timer);
      groupBuyTradeWakeConfirmTimers.delete(mint);
    }
    if (!mints.length) return;
    // The wake lane handles active buys. Keep routine reconciliation cheap while it is healthy, but
    // automatically widen the slice during a websocket/provider outage instead of waiting 10+ minutes
    // for one rotation. Priority 120 also prevents live-buy recovery from being suppressed by unrelated
    // background Pump work; the shared host gate still enforces bounded request spacing.
    const liveWake = Boolean(buyWsDiag.connected || groupBuyChainWakeConnected());
    const cadenceMs = liveWake ? GROUP_BUY_LIVE_RECOVERY_POLL_MS : GROUP_BUY_RECOVERY_POLL_MS;
    const now = Date.now();
    if (now - groupBuyRecoveryLastAt < cadenceMs - 250) return;
    groupBuyRecoveryLastAt = now;
    const batchSize = liveWake ? GROUP_BUY_LIVE_RECOVERY_BATCH : GROUP_BUY_RECOVERY_BATCH;
    const count = Math.min(batchSize, mints.length);
    for (let index = 0; index < count; index += 1) {
      const mint = mints[(groupBuyRecoveryOffset + index) % mints.length];
      if (queueGroupBuyTradePoll(mint, { priority: liveWake ? 100 : 120 })) groupBuyTradeDiag.recoveryQueued += 1;
    }
    groupBuyRecoveryOffset = (groupBuyRecoveryOffset + count) % mints.length;
  } catch (error) {
    noteGroupBuyTradePollError("poll", error);
  }
}

async function buildGroupBuyStatsSnapshot(token) {
  const target = String(token || "").trim();
  const isRh = /^0x[0-9a-fA-F]{40}$/.test(target);
  const observed = groupBuyStatsObserved(target);
  if (isRh) {
    const [info, pairs] = await Promise.all([
      gatherRhScan(target).catch(() => null),
      fetchDexScreenerTokenPairsFallback(target).catch(() => [])
    ]);
    if (!info) return null;
    const best = bestDexPairForToken(target, pairs);
    const socials = Array.isArray(best?.info?.socials) ? best.info.socials : [];
    const websites = Array.isArray(best?.info?.websites) ? best.info.websites : [];
    return {
      target, network: "robinhood",
      symbol: firstString(info.symbol, best?.baseToken?.symbol, shortMint(target)).replace(/^\$+/, "").slice(0, 18),
      name: firstString(info.name, best?.baseToken?.name, info.symbol, shortMint(target)).slice(0, 50),
      priceUsd: firstMeaningfulNumber(info.priceUsd, best?.priceUsd) || 0,
      change24h: info.ch24 != null && Number.isFinite(Number(info.ch24)) ? Number(info.ch24) : (best?.priceChange?.h24 != null ? Number(best.priceChange.h24) : null),
      marketCap: firstMeaningfulNumber(info.mc, best?.marketCap, best?.fdv) || 0,
      liquidity: firstMeaningfulNumber(info.liq, best?.liquidity?.usd) || 0,
      holders: firstMeaningfulNumber(info.holders) || 0,
      volume1h: firstMeaningfulNumber(info.vol1, best?.volume?.h1) || 0,
      volume24h: firstMeaningfulNumber(info.vol24, best?.volume?.h24) || 0,
      buys24h: firstMeaningfulNumber(best?.txns?.h24?.buys) || observed.rows.length,
      dexPaid: null,
      websiteUrl: firstString(info.websiteUrl, websites[0]?.url),
      telegramUrl: firstString(info.telegramUrl, (socials.find((row) => /telegram|tg/i.test(row?.type || row?.label || "")) || {}).url),
      twitterUrl: firstString(info.twitterUrl, (socials.find((row) => /twitter|x/i.test(row?.type || row?.label || "")) || {}).url),
      observed
    };
  }

  const scan = await getGroupBuyScan(target).catch(() => null);
  if (!scan) return null;
  const meta = scan.meta || {}, bonding = scan.bonding || {}, best = scan.best || {};
  const stats = scanMarketStatsFromSources({ meta, bonding, best, rug: scan.rug, supply: scan.supply, mint: target });
  return {
    target, network: "solana",
    symbol: firstString(meta.symbol, bonding.symbol, best?.baseToken?.symbol, shortMint(target)).replace(/^\$+/, "").slice(0, 18),
    name: firstString(meta.name, bonding.name, best?.baseToken?.name, meta.symbol, shortMint(target)).slice(0, 50),
    priceUsd: firstMeaningfulNumber(meta.priceUsd, best.priceUsd, bonding.priceUsd, bonding.price_usd) || 0,
    change24h: stats.ch24 != null && Number.isFinite(Number(stats.ch24)) ? Number(stats.ch24) : null,
    marketCap: firstMeaningfulNumber(stats.mc) || 0,
    liquidity: firstMeaningfulNumber(stats.liq) || 0,
    holders: firstMeaningfulNumber(stats.holders) || 0,
    volume1h: scanVolumeWindowValue("h1", meta, bonding, best),
    volume24h: firstMeaningfulNumber(stats.volume24h) || 0,
    buys24h: scanBestTxnCount("buys", "h24", meta, bonding, best) || observed.rows.length,
    dexPaid: scan.dexPaid,
    websiteUrl: firstString(meta.websiteUrl, bonding.websiteUrl),
    telegramUrl: firstString(meta.telegramUrl, bonding.telegramUrl),
    twitterUrl: firstString(meta.twitterUrl, bonding.twitterUrl),
    observed
  };
}

