function sharePageDate(value) {
  const ts = Date.parse(value || "");
  if (!Number.isFinite(ts)) return "unknown";
  return new Date(ts).toUTCString().replace(":00 GMT", " UTC");
}

function sendShareHtml(response, html) {
  response.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=30, stale-while-revalidate=120" });
  response.end(html);
}

// /t and /proof pages served with share-crawler-grade meta tags. For /t?ca=
// the OG title/description/image are rewritten per token: symbol, SlimeShield
// verdict (from the warm cache only - never block a crawler on a cold compute),
// market stats, and the PNG signal card as the unfurl image.
// Serve a standalone HTML page from the built web dir (no template injection).
function readRequestCookie(request, name) {
  const raw = String(request?.headers?.cookie || "");
  const match = raw.match(new RegExp(`(?:^|;\\s*)${name}=([^;]+)`));
  return match ? decodeURIComponent(match[1]) : "";
}

// OWNER-ONLY admin panel. The autopilot-live page exposes paper mode, every mode
// name + strategy label, the running-log download, and full controls — i.e. exactly
// how the bot is set up. It must NEVER be visible to anyone but the owner. We gate the
// PAGE itself on the owner key (via ?k= once, then an HttpOnly cookie) and 404 otherwise
// so its very existence stays hidden. The key is injected into localStorage so the
// owner's API calls keep working without re-entering it. Fails CLOSED if no key is set.
async function serveAutopilotAdminPage(requestUrl, request, response) {
  const ownerKey = CONFIG.autopilotOwnerKey || "";
  const controlKey = CONFIG.autopilotControlKey || "";
  const provided = String(
    requestUrl.searchParams.get("k")
    || requestUrl.searchParams.get("key")
    || readRequestCookie(request, "apk")
    || ""
  ).trim();
  const authed = Boolean(provided) && ((ownerKey && provided === ownerKey) || (controlKey && provided === controlKey));
  if (!authed) {
    // Pretend it doesn't exist — never hint that an admin panel is here.
    response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
    response.end("Not found");
    return;
  }
  let html;
  try {
    html = await fs.readFile(path.join(WEB_STATIC_DIR, "autopilot-live.html"), "utf8");
  } catch {
    response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
    response.end("Not found");
    return;
  }
  // Auto-fill the API owner key so the gated owner never has to paste it twice.
  const inject = `<script>try{localStorage.setItem('apOwnerKey', ${JSON.stringify(provided)});}catch(e){}</script>`;
  html = html.includes("</head>") ? html.replace("</head>", `${inject}</head>`) : `${inject}${html}`;
  response.writeHead(200, {
    "Content-Type": "text/html; charset=utf-8",
    // Never cache a page carrying the key, and keep it off any shared/CDN cache.
    "Cache-Control": "no-store, private",
    "Set-Cookie": `apk=${encodeURIComponent(provided)}; Path=/; Max-Age=2592000; HttpOnly; Secure; SameSite=Lax`
  });
  response.end(html);
}

async function serveStaticHtmlPage(response, fileName, cacheControl = "public, max-age=60, stale-while-revalidate=600", extraHeaders = {}) {
  try {
    const html = await fs.readFile(path.join(WEB_STATIC_DIR, fileName), "utf8");
    response.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": cacheControl,
      ...extraHeaders
    });
    response.end(html);
  } catch {
    response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
    response.end("Not found");
  }
}

// /old = the ARCHIVED original terminal, kept ONLY for visual reference. We serve the old index.html
// but inject a guard (before app.js) that neutralizes every DATA call — fetch + XHR to any /api or
// market/data host return empty — so it renders the old UI shell with ZERO pairs loaded and ZERO API
// credits spent. Its assets (app.js/css/images) still load via the absolute /paths (base href="/").
async function serveOldReference(response) {
  // old.html is the FROZEN old terminal with the data-API guard baked in (built from the original
  // index.html). index.html itself is now the new gg app, so we serve old.html for /old.
  await serveStaticHtmlPage(response, "old.html", "no-store, max-age=0");
}

async function serveTokenSharePage(requestUrl, response) {
  const page = requestUrl.pathname.startsWith("/proof") ? "proof.html" : "t.html";
  let html;
  try {
    html = await fs.readFile(path.join(WEB_STATIC_DIR, page), "utf8");
  } catch {
    response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
    response.end("Not found");
    return;
  }
  if (page === "t.html") {
    const mint = (requestUrl.searchParams.get("ca") || requestUrl.searchParams.get("token") || "")
      .replace(/[^A-HJ-NP-Za-km-z1-9]/g, "").slice(0, 48);
    if (mint) {
      try {
        html = await injectTokenShareTags(html, mint);
      } catch {
        // share tags are best-effort; the page itself must always render
      }
    }
  }
  response.writeHead(200, {
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "public, max-age=30, stale-while-revalidate=300"
  });
  response.end(html);
}

async function injectTokenShareTags(html, mint) {
  let pair = pairLiteCache.get(mint)?.payload?.pair || null;
  if (!pair) {
    // Cold hit (usually a crawler): give market data a short budget, then ship.
    pair = await Promise.race([
      (async () => {
        const pairs = await fetchDexScreenerTokenPairsFallback(mint).catch(() => []);
        return bestDexPairForToken(mint, pairs) || await pumpCurvePairFallback(mint).catch(() => null);
      })(),
      new Promise((resolve) => setTimeout(() => resolve(null), 900))
    ]).catch(() => null);
  }
  const shield = cachedSlimeShieldRecord(mint);
  const symbol = String(pair?.baseToken?.symbol || "").trim() || shortMint(mint);
  const marketCap = Number(pair?.marketCap || pair?.fdv) || null;
  const liquidity = Number(pair?.liquidity?.usd) || null;
  const title = shield
    ? `$${symbol} — SlimeShield says ${shield.verdict} (${shield.score}/100) | SlimeWire`
    : `$${symbol} — live shield read | SlimeWire`;
  const statBits = [
    marketCap ? `MC ${formatUsdCompact(marketCap)}` : "",
    liquidity ? `Liq ${formatUsdCompact(liquidity)}` : ""
  ].filter(Boolean).join(" · ");
  const description = `${statBits ? statBits + ". " : ""}Triple-engine risk read (SlimeShield × Rugcheck × GoPlus), live chart, holder map, tracked calls. Verify before you ape.`;
  const image = `${SHARE_PAGE_ORIGIN}/api/web/signal-card?tokenMint=${encodeURIComponent(mint)}`;
  const safe = (text) => escapeHtml(String(text)).replace(/"/g, "&quot;");
  return html
    .replace(/<title>[^<]*<\/title>/, `<title>${safe(title)}</title>`)
    .replace(/(<meta name="description" content=")[^"]*(")/, `$1${safe(description)}$2`)
    .replace(/(<meta property="og:title" content=")[^"]*(")/, `$1${safe(title)}$2`)
    .replace(/(<meta property="og:description" content=")[^"]*(")/, `$1${safe(description)}$2`)
    .replace(/(<meta property="og:image" content=")[^"]*(")/, `$1${safe(image)}$2`);
}

