function communityRaidsPath() {
  return path.join(CONFIG.dataDir, "community-raids.json");
}
async function readCommunityRaids() {
  const store = await readJson(communityRaidsPath());
  if (!Array.isArray(store.raids)) store.raids = [];
  return store;
}
async function submitCommunityRaid(body = {}) {
  const mint = String(body.mint || "").replace(/[^A-Za-z0-9]/g, "").slice(0, 64);
  if (mint.length < 32) return { ok: false, error: "bad mint" };
  const symbol = String(body.symbol || "").replace(/[^A-Za-z0-9_$]/g, "").slice(0, 12) || "COIN";
  const by = String(body.by || "anon").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16) || "anon";
  const store = await readCommunityRaids();
  const now = new Date().toISOString();
  const idx = store.raids.findIndex((r) => r.mint === mint);
  if (idx >= 0) {
    store.raids[idx].bumps = (store.raids[idx].bumps || 1) + 1;
    store.raids[idx].at = now;
  } else {
    store.raids.push({ mint, symbol, by, at: now, bumps: 1 });
  }
  // keep newest 80
  store.raids = store.raids.slice(-80);
  await writeJsonFile(communityRaidsPath(), store);
  return { ok: true, mint, symbol };
}

// --- Swamp Receipts + metadata summaries -----------------------------------------
// Opt-in proof crumbs for scan/trade/share/launch moments. This store is deliberately
// metadata-only: no transaction construction, signing, or delegated wallet powers.
const SWAMP_RECEIPT_LIMIT = 1000;
const SWAMP_PUBLIC_RECEIPT_LIMIT = 80;
const SWAMP_RECEIPT_KINDS = new Set(["scan", "trade", "share", "launch", "raid", "passport"]);

function swampReceiptsPath() { return path.join(CONFIG.dataDir, "swamp-receipts.json"); }
async function readSwampReceipts() {
  const store = await readJson(swampReceiptsPath());
  if (!Array.isArray(store.receipts)) store.receipts = [];
  return store;
}

function normalizeSwampReceiptKind(value = "") {
  const kind = String(value || "").trim().toLowerCase();
  return SWAMP_RECEIPT_KINDS.has(kind) ? kind : "share";
}

function safeSwampText(value = "", max = 160) {
  return String(value || "")
    .replace(/[\r\n\t]+/g, " ")
    .replace(/[^\x20-\x7E]/g, "")
    .trim()
    .slice(0, max);
}

function safeSwampUrl(value = "", fallback = "") {
  const raw = String(value || fallback || "").trim();
  if (!raw) return "";
  try {
    const url = new URL(raw);
    if (!["http:", "https:"].includes(url.protocol)) return "";
    return url.toString().slice(0, 320);
  } catch {
    return "";
  }
}

function swampReceiptMint(value = "") {
  const raw = String(value || "").trim();
  if (!raw || !solanaPublicKeyLike(raw)) return "";
  try { return new PublicKey(raw).toBase58(); } catch { return ""; }
}

function swampReceiptDefaultLabel(kind) {
  return {
    scan: "Scan Receipt",
    trade: "Trade Receipt",
    share: "Share Receipt",
    launch: "Launch Receipt",
    raid: "Raid Receipt",
    passport: "Passport Receipt"
  }[kind] || "Swamp Receipt";
}

function swampReceiptSiteUrl(receipt = {}) {
  if (receipt.tokenMint) return `https://www.slimewire.org/t?ca=${encodeURIComponent(receipt.tokenMint)}`;
  return safeSwampUrl(receipt.url, CONFIG.webPortalUrl || "https://www.slimewire.org") || "https://www.slimewire.org";
}

function swampReceiptShareText(receipt = {}) {
  const symbol = receipt.symbol ? `$${receipt.symbol}` : (receipt.tokenMint ? shortMint(receipt.tokenMint) : "SlimeWire");
  const label = safeSwampText(receipt.label || swampReceiptDefaultLabel(receipt.kind), 60);
  const summary = safeSwampText(receipt.summary || "", 120);
  return [label, symbol, summary].filter(Boolean).join(" - ");
}

function swampReceiptShareTargets(receipt = {}) {
  const site = swampReceiptSiteUrl(receipt);
  const text = swampReceiptShareText(receipt);
  return {
    site,
    x: xShareUrl(text, site),
    telegram: `https://t.me/share/url?url=${encodeURIComponent(site)}&text=${encodeURIComponent(text)}`
  };
}

function publicSwampReceipt(receipt = {}, options = {}) {
  const own = Boolean(options.own);
  return {
    id: receipt.id,
    kind: receipt.kind,
    label: receipt.label,
    summary: receipt.summary,
    tokenMint: receipt.tokenMint || "",
    shortMint: receipt.tokenMint ? shortMint(receipt.tokenMint) : "",
    symbol: receipt.symbol || "",
    url: receipt.url || swampReceiptSiteUrl(receipt),
    source: receipt.source || "",
    public: Boolean(receipt.public),
    createdAt: receipt.createdAt || "",
    stats: receipt.stats || {},
    share: swampReceiptShareTargets(receipt),
    ...(own ? { userScope: "self" } : {})
  };
}

function swampReceiptStats(receipts = []) {
  const byKind = {};
  for (const receipt of receipts) {
    const kind = normalizeSwampReceiptKind(receipt.kind);
    byKind[kind] = (byKind[kind] || 0) + 1;
  }
  return {
    total: receipts.length,
    public: receipts.filter((receipt) => receipt.public).length,
    byKind
  };
}

async function buildSwampReceipt(userId, body = {}) {
  const kind = normalizeSwampReceiptKind(body.kind || body.type);
  const tokenMint = swampReceiptMint(firstString(body.tokenMint, body.mint, body.ca));
  const label = safeSwampText(body.label || swampReceiptDefaultLabel(kind), 70);
  let summary = safeSwampText(body.summary || body.note || "", 180);
  let symbol = safeSwampText(body.symbol || "", 18).replace(/^\$+/, "");
  const stats = {};

  if (tokenMint) {
    const metadata = await getDexTokenMetadata(tokenMint).catch(() => ({}));
    symbol = safeSwampText(symbol || metadata.symbol || shortMint(tokenMint), 18).replace(/^\$+/, "");
    if (kind === "scan") {
      const shield = await webSlimeShield(tokenMint).catch(() => null);
      if (shield) {
        stats.verdict = shield.verdict || "";
        stats.score = shield.score ?? null;
        stats.confidence = shield.confidence ?? null;
        if (!summary) summary = safeSwampText(shield.summary || `SlimeShield ${shield.verdict || "read"} for $${symbol}.`, 180);
      }
    } else if (kind === "trade") {
      const rows = await pnlRows(userId, tokenMint, { groupByToken: true, limit: 1 }).catch(() => []);
      const row = rows[0] || null;
      if (row) {
        stats.buys = row.buys || 0;
        stats.sells = row.sells || 0;
        stats.spentSol = lamportsBigToSol(row.spent || 0n);
        stats.receivedSol = lamportsBigToSol(row.received || 0n);
        stats.realizedSol = formatSignedLamports((row.received || 0n) - (row.spent || 0n));
        if (!summary) summary = `Realized ${stats.realizedSol} SOL on $${symbol}.`;
      }
    } else if (kind === "launch") {
      const launches = await readPumpLaunchAttempts().catch(() => ({ attempts: [] }));
      const attempt = [...(launches.attempts || [])].reverse().find((item) =>
        String(item.userId || "") === String(userId)
        && firstString(item.tokenMint, item.mintPublicKey, item.mint) === tokenMint);
      if (attempt) {
        stats.status = String(attempt.status || "").toUpperCase();
        stats.rail = String(attempt.rail || "pump").slice(0, 24);
        stats.txSignature = firstString(attempt.txSignature, attempt.signature, attempt.createSignature);
        if (!summary) summary = `$${symbol} launched through SlimeWire.`;
      }
    }
  }

  if (!summary) {
    summary = {
      scan: "Token scan saved as a swamp receipt.",
      trade: "Trade moment saved as a swamp receipt.",
      share: "Share moment saved as a swamp receipt.",
      launch: "Launch moment saved as a swamp receipt.",
      raid: "Raid moment saved as a swamp receipt.",
      passport: "Passport badge moment saved as a swamp receipt."
    }[kind];
  }

  const publicOptIn = parseBoolean(firstString(body.public, body.sharePublic, body.publicReceipt, "false"));
  const url = safeSwampUrl(body.url || body.shareUrl || "", tokenMint ? `https://www.slimewire.org/t?ca=${encodeURIComponent(tokenMint)}` : "");
  return {
    id: `swr-${Date.now().toString(36)}-${crypto.randomBytes(4).toString("hex")}`,
    userId: String(userId),
    kind,
    label,
    summary,
    tokenMint,
    symbol,
    url,
    source: safeSwampText(body.source || "web", 40),
    public: publicOptIn,
    stats,
    createdAt: new Date().toISOString()
  };
}

async function webCreateSwampReceipt(userId, body = {}) {
  const receipt = await buildSwampReceipt(userId, body);
  await withFileLock(swampReceiptsPath(), async () => {
    const store = await readSwampReceipts();
    store.receipts.push(receipt);
    store.receipts = store.receipts.slice(-SWAMP_RECEIPT_LIMIT);
    await writeJsonFile(swampReceiptsPath(), store);
  });
  await audit("web_swamp_receipt_create", {
    userId,
    kind: receipt.kind,
    tokenMint: receipt.tokenMint || "",
    public: receipt.public
  }).catch(() => {});
  return publicSwampReceipt(receipt, { own: true });
}

async function webSwampReceiptsForUser(userId, options = {}) {
  const limit = Math.max(1, Math.min(200, Number(options.limit) || 80));
  const store = await readSwampReceipts();
  const mine = (store.receipts || [])
    .filter((receipt) => String(receipt.userId || "") === String(userId))
    .sort((a, b) => Date.parse(b.createdAt || "") - Date.parse(a.createdAt || ""));
  return {
    receipts: mine.slice(0, limit).map((receipt) => publicSwampReceipt(receipt, { own: true })),
    stats: swampReceiptStats(mine)
  };
}

async function webPublicSwampReceipts(options = {}) {
  const mint = swampReceiptMint(options.mint || "");
  const limit = Math.max(1, Math.min(SWAMP_PUBLIC_RECEIPT_LIMIT, Number(options.limit) || 40));
  const store = await readSwampReceipts();
  const receipts = (store.receipts || [])
    .filter((receipt) => receipt.public)
    .filter((receipt) => !mint || receipt.tokenMint === mint)
    .sort((a, b) => Date.parse(b.createdAt || "") - Date.parse(a.createdAt || ""))
    .slice(0, limit)
    .map((receipt) => publicSwampReceipt(receipt));
  return { receipts, stats: swampReceiptStats(receipts) };
}

function swampActionMetadata(kind = "scan", requestUrl = null) {
  const action = ["scan", "trade", "share"].includes(String(kind || "").toLowerCase()) ? String(kind).toLowerCase() : "scan";
  const rawMint = firstString(
    requestUrl?.searchParams?.get("tokenMint"),
    requestUrl?.searchParams?.get("mint"),
    requestUrl?.searchParams?.get("ca")
  );
  const mint = swampReceiptMint(rawMint);
  const base = (CONFIG.webPortalUrl || "https://www.slimewire.org").replace(/\/+$/, "");
  const links = mint ? slimewireTokenLinks(mint) : null;
  const targetUrl = action === "trade"
    ? (links?.siteBuy || `${base}/terminal`)
    : action === "scan"
      ? (links?.site || `${base}/terminal`)
      : safeSwampUrl(requestUrl?.searchParams?.get("url") || "", links?.site || base);
  const title = {
    scan: "SlimeWire Scan",
    trade: "SlimeWire Trade",
    share: "SlimeWire Share"
  }[action];
  const description = {
    scan: "Open a SlimeWire token read with chart, SlimeShield, proof receipts, and socials.",
    trade: "Open the SlimeWire trade panel for user-confirmed wallet actions.",
    share: "Share a SlimeWire token, receipt, chart, or proof page."
  }[action];
  const shareText = safeSwampText(requestUrl?.searchParams?.get("text") || (mint ? `Check ${shortMint(mint)} on SlimeWire` : "Open SlimeWire"), 180);
  const actions = [
    { label: action === "trade" ? "Open Trade Panel" : action === "share" ? "Open Share Page" : "Scan Token", href: targetUrl },
    ...(mint ? [{ label: "Signal Card", href: `${base}/api/web/signal-card?tokenMint=${encodeURIComponent(mint)}` }] : []),
    { label: "Proof Wall", href: `${base}/proof` }
  ];
  return {
    ok: true,
    type: "swamp-action-metadata",
    action,
    title: mint ? `${title} ${shortMint(mint)}` : title,
    icon: `${base}/assets/slimewire/png/slimewire-mark.png`,
    description,
    label: actions[0].label,
    disabled: false,
    links: { actions },
    metadata: {
      version: "2026-07-09",
      noTransaction: true,
      tokenMint: mint,
      targetUrl,
      xShareUrl: xShareUrl(shareText, targetUrl),
      telegramShareUrl: `https://t.me/share/url?url=${encodeURIComponent(targetUrl)}&text=${encodeURIComponent(shareText)}`,
      telegramBotUrl: telegramBotStartUrl()
    }
  };
}

function swampActionKindFromPath(pathname = "") {
  const tail = String(pathname || "").split("/").filter(Boolean).pop() || "scan";
  return tail.replace(/^swamp-/, "").replace(/^blink-/, "").toLowerCase();
}

function publicLaunchAttemptSummary(attempt = {}) {
  const mint = firstString(attempt.tokenMint, attempt.mintPublicKey, attempt.mint);
  const symbol = safeSwampText(firstString(attempt.symbol, attempt.ticker, attempt.metadataJson?.symbol), 18).replace(/^\$+/, "");
  const status = String(attempt.status || "").toUpperCase();
  const feeSharing = pumpFeeSharingPublic(attempt);
  return {
    status,
    stage: safeSwampText(firstString(attempt.stage, attempt.stageText), 80),
    rail: safeSwampText(attempt.rail || "pump", 24),
    tokenMint: mint,
    shortMint: mint ? shortMint(mint) : "",
    symbol,
    name: safeSwampText(firstString(attempt.name, attempt.tokenName, attempt.metadataJson?.name), 48),
    createdAt: firstString(attempt.createdAt, attempt.startedAt),
    completedAt: firstString(attempt.completedAt, attempt.confirmedAt, attempt.updatedAt),
    url: mint ? `https://www.slimewire.org/t?ca=${encodeURIComponent(mint)}` : "",
    ...(feeSharing ? { feeSharing } : {})
  };
}

async function webLaunchBossRaidSummary() {
  const [launches, community, posts] = await Promise.all([
    readPumpLaunchAttempts().catch(() => ({ attempts: [] })),
    readCommunityRaids().catch(() => ({ raids: [] })),
    readRaidPosts().catch(() => ({ posts: [] }))
  ]);
  const completedLaunches = [...(launches.attempts || [])]
    .reverse()
    .filter((attempt) => ["COMPLETE", "CONFIRMED", "LAUNCHED"].includes(String(attempt.status || "").toUpperCase()))
    .slice(0, 12)
    .map((attempt) => ({ kind: "slimewire-launch", ...publicLaunchAttemptSummary(attempt) }));
  const communityBosses = [...(community.raids || [])]
    .reverse()
    .slice(0, 12)
    .map((raid) => ({
      kind: "community-raid",
      tokenMint: raid.mint || "",
      shortMint: raid.mint ? shortMint(raid.mint) : "",
      symbol: safeSwampText(raid.symbol || "COIN", 18).replace(/^\$+/, ""),
      bumps: Number(raid.bumps || 0),
      at: raid.at || "",
      url: raid.mint ? `https://www.slimewire.org/t?ca=${encodeURIComponent(raid.mint)}` : ""
    }));
  const xRaids = [...(posts.posts || [])]
    .sort((a, b) => (Number(b.score || 0) - Number(a.score || 0)) || Date.parse(b.at || "") - Date.parse(a.at || ""))
    .slice(0, 12)
    .map((post) => ({
      kind: "x-raid",
      id: post.tid || "",
      symbol: safeSwampText(post.symbol || "POST", 18).replace(/^\$+/, ""),
      score: Number(post.score || 0),
      likes: Number(post.likes || 0),
      reposts: Number(post.rts || post.reposts || 0),
      replies: Number(post.replies || 0),
      url: safeSwampUrl(post.url || "")
    }));
  return {
    updatedAt: new Date().toISOString(),
    active: completedLaunches.length + communityBosses.length + xRaids.length,
    bosses: [...completedLaunches, ...communityBosses, ...xRaids].slice(0, 24),
    sources: {
      launches: completedLaunches.length,
      communityRaids: communityBosses.length,
      xRaids: xRaids.length
    }
  };
}

async function webLaunchEggSummary(options = {}) {
  const userId = options.userId ? String(options.userId) : "";
  const [launches, hype, presales] = await Promise.all([
    readPumpLaunchAttempts().catch(() => ({ attempts: [] })),
    readLaunchHype().catch(() => ({ pages: {} })),
    readPresales().catch(() => ({ presales: [] }))
  ]);
  const attempts = userId ? (launches.attempts || [])
    .filter((attempt) => String(attempt.userId || "") === userId)
    .filter((attempt) => {
      const status = String(attempt.status || "").toUpperCase();
      return status && !["COMPLETE", "CONFIRMED", "LAUNCHED", "FAILED", "CANCELLED"].includes(status);
    })
    .slice(-20)
    .map((attempt) => ({ kind: "launch-attempt", ...publicLaunchAttemptSummary(attempt) })) : [];
  const now = Date.now();
  const hypeEggs = Object.values(hype.pages || {})
    .filter((page) => !userId || String(page.userId || "") === userId)
    .filter((page) => !page.mint)
    .sort((a, b) => Date.parse(a.launchAt || "") - Date.parse(b.launchAt || ""))
    .slice(0, 20)
    .map((page) => ({
      kind: "hype-page",
      id: page.id,
      name: safeSwampText(page.name || "", 48),
      symbol: safeSwampText(page.symbol || "", 18).replace(/^\$+/, ""),
      launchAt: page.launchAt || "",
      subscriberCount: Array.isArray(page.subscriberTgIds) ? page.subscriberTgIds.length : 0,
      url: `${SHARE_PAGE_ORIGIN}/hype/${encodeURIComponent(page.id)}`
    }));
  const presaleEggs = (presales.presales || [])
    .filter((item) => Date.parse(item.deadline || "") > now)
    .sort((a, b) => Date.parse(a.deadline || "") - Date.parse(b.deadline || ""))
    .slice(0, 12)
    .map((item) => ({
      kind: "presale",
      id: item.id,
      name: safeSwampText(item.name || "", 48),
      symbol: safeSwampText(item.symbol || "", 18).replace(/^\$+/, ""),
      deadline: item.deadline || "",
      target: Number(item.target || 0),
      interest: Number(item.interest || 0)
    }));
  const eggs = [...attempts, ...hypeEggs, ...presaleEggs].slice(0, 36);
  return {
    updatedAt: new Date().toISOString(),
    count: eggs.length,
    eggs,
    sources: {
      launchAttempts: attempts.length,
      hypePages: hypeEggs.length,
      presales: presaleEggs.length
    }
  };
}

async function webSwampLaunchStateSummary(options = {}) {
  const [bossRaid, launchEgg] = await Promise.all([
    webLaunchBossRaidSummary(),
    webLaunchEggSummary(options)
  ]);
  return { bossRaid, launchEgg };
}

function swampPassportBadge(id, label, earned, progress = 0, detail = "", count = 0) {
  return {
    id,
    label,
    earned: Boolean(earned),
    progress: Math.max(0, Math.min(100, Math.round(Number(progress) || 0))),
    detail: safeSwampText(detail, 140),
    count: Number(count || 0)
  };
}

async function webSwampPassportSummary(userId) {
  const [profile, walletStore, tradeStore, launchStore, receiptStore] = await Promise.all([
    webProfileForUser(userId).catch(() => ({})),
    readWalletStore().catch(() => ({ wallets: [] })),
    readTradeHistory().catch(() => ({ trades: [] })),
    readPumpLaunchAttempts().catch(() => ({ attempts: [] })),
    readSwampReceipts().catch(() => ({ receipts: [] }))
  ]);
  const wallets = walletsForOwner(walletStore, userId);
  const trades = (tradeStore.trades || []).filter((trade) => String(trade.userId || "") === String(userId));
  const buys = trades.filter((trade) => trade.type === "buy").length;
  const sells = trades.filter((trade) => trade.type === "sell").length;
  const tokenCount = new Set(trades.map((trade) => trade.tokenMint).filter(Boolean)).size;
  const spent = trades.reduce((sum, trade) => trade.type === "buy" ? sum + positiveBigIntOrZero(trade.solLamportsSpent) : sum, 0n);
  const received = trades.reduce((sum, trade) => trade.type === "sell" ? sum + positiveBigIntOrZero(trade.solLamportsReceived) : sum, 0n);
  const launches = (launchStore.attempts || []).filter((attempt) =>
    String(attempt.userId || "") === String(userId)
    && ["COMPLETE", "CONFIRMED", "LAUNCHED"].includes(String(attempt.status || "").toUpperCase()));
  const receipts = (receiptStore.receipts || []).filter((receipt) => String(receipt.userId || "") === String(userId));
  const receiptKinds = swampReceiptStats(receipts).byKind;
  const referralStats = normalizeReferralStats(profile.referralStats || {});
  const referralCount = Array.isArray(referralStats.referrals) ? referralStats.referrals.length : 0;
  const badges = [
    swampPassportBadge("account", "Swamp Account", true, 100, "Profile is initialized.", 1),
    swampPassportBadge("managed-wallet", "Managed Wallet", wallets.length > 0, wallets.length ? 100 : 0, "Create or import a managed wallet.", wallets.length),
    swampPassportBadge("connected-wallet", "Connected Wallet", Boolean(profile.connectedWallet?.publicKey), profile.connectedWallet?.publicKey ? 100 : 0, "Connect a browser wallet for view-only context.", profile.connectedWallet?.publicKey ? 1 : 0),
    swampPassportBadge("x-handle", "X Handle", Boolean(profile.xHandle), profile.xHandle ? 100 : 0, "Link an X handle for share flows.", profile.xHandle ? 1 : 0),
    swampPassportBadge("first-trade", "First Trade", trades.length > 0, Math.min(100, trades.length * 100), "Make a user-confirmed SlimeWire trade.", trades.length),
    swampPassportBadge("pnl-tracker", "PnL Tracker", tokenCount > 0, Math.min(100, tokenCount * 25), "Build token-level PnL history.", tokenCount),
    swampPassportBadge("scan-receipt", "Scan Receipt", Number(receiptKinds.scan || 0) > 0, Math.min(100, Number(receiptKinds.scan || 0) * 50), "Save an opt-in scan receipt.", Number(receiptKinds.scan || 0)),
    swampPassportBadge("public-receipt", "Public Receipt", receipts.some((receipt) => receipt.public), receipts.some((receipt) => receipt.public) ? 100 : 0, "Opt a receipt into the public proof feed.", receipts.filter((receipt) => receipt.public).length),
    swampPassportBadge("launch-boss", "Launch Boss", launches.length > 0, Math.min(100, launches.length * 50), "Launch a coin through SlimeWire.", launches.length),
    swampPassportBadge("referral-link", "Referral Link", Boolean(profile.referralCode), profile.referralCode ? 100 : 0, "Own a referral link.", profile.referralCode ? 1 : 0),
    swampPassportBadge("referral-builder", "Referral Builder", referralCount > 0, Math.min(100, referralCount * 25), "Bring in referred traders.", referralCount)
  ];
  const earned = badges.filter((badge) => badge.earned).length;
  const score = earned * 100 + Math.min(400, trades.length * 10) + Math.min(300, receipts.length * 25) + Math.min(300, launches.length * 75);
  return {
    updatedAt: new Date().toISOString(),
    summary: {
      earned,
      total: badges.length,
      score,
      level: score >= 1400 ? "legend" : score >= 900 ? "raider" : score >= 500 ? "scout" : "newt"
    },
    stats: {
      wallets: wallets.length,
      connectedWallet: Boolean(profile.connectedWallet?.publicKey),
      trades: trades.length,
      buys,
      sells,
      tokenCount,
      realizedSol: formatSignedLamports(received - spent),
      launches: launches.length,
      receipts: receipts.length,
      publicReceipts: receipts.filter((receipt) => receipt.public).length,
      referralCount
    },
    badges
  };
}

// --- PvP deck duels: a small published-deck store for async battles ---
function swampDecksPath() { return path.join(CONFIG.dataDir, "swamp-decks.json"); }
async function readSwampDecks() { const s = await readJson(swampDecksPath()); if (!Array.isArray(s.decks)) s.decks = []; return s; }
async function publishSwampDeck(body = {}) {
  const id = String(body.id || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 40);
  if (!id) return { ok: false, error: "no id" };
  const name = String(body.name || "anon").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16) || "anon";
  const clan = String(body.clan || "").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16);
  const level = Math.max(1, Math.min(999, Number(body.level) || 1));
  const cards = Array.isArray(body.deck) ? body.deck.slice(0, 6).map((c) => ({
    sym: String(c.sym || "COIN").replace(/[^A-Za-z0-9_$]/g, "").slice(0, 12) || "COIN",
    el: String(c.el || "Slime").replace(/[^A-Za-z]/g, "").slice(0, 8) || "Slime",
    atk: Math.max(1, Math.min(999, Number(c.atk) || 40)),
    def: Math.max(1, Math.min(999, Number(c.def) || 40)),
    hp: Math.max(1, Math.min(9999, Number(c.hp) || 120)),
    rarity: String(c.rarity || "common").replace(/[^a-z]/g, "").slice(0, 12) || "common"
  })) : [];
  if (!cards.length) return { ok: false, error: "empty deck" };
  const store = await readSwampDecks();
  const rec = { id, name, clan, level, deck: cards, at: new Date().toISOString() };
  const idx = store.decks.findIndex((d) => d.id === id);
  if (idx >= 0) store.decks[idx] = rec; else store.decks.push(rec);
  store.decks = store.decks.slice(-600);
  await writeJsonFile(swampDecksPath(), store);
  return { ok: true };
}

const SWAMP_NFT_ARCHETYPES = [
  { key: "ogre", kind: "Ogre", sprite: "/assets/slimewire/swamp/ogres/ogre-warlord.png", weapon: "boulder", over: "quake" },
  { key: "goblin", kind: "Goblin", sprite: "/assets/slimewire/swamp/ogres/ogre-goblin.png", weapon: "triple", over: "speed burst" },
  { key: "undead|zombie|skeleton|reaper|death", kind: "Undead", sprite: "/assets/slimewire/swamp/ogres/ogre-zombie.png", weapon: "acid", over: "lifedrain" },
  { key: "giant|titan|rock|mountain|stone", kind: "Giant", sprite: "/assets/slimewire/swamp/ogres/ogre-titan.png", weapon: "boulder", over: "stone rage" },
  { key: "elf|nymph|fairy|forest|witch|shaman", kind: "Nymph", sprite: "/assets/slimewire/swamp/ogres/ogre-shaman.png", weapon: "vine", over: "healing bloom" },
  { key: "knight|warrior|paladin|dwarf", kind: "Warrior", sprite: "/assets/slimewire/swamp/ogres/ogre-knight.png", weapon: "laser", over: "shield rush" },
  { key: "pirate|raider|bandit", kind: "Raider", sprite: "/assets/slimewire/swamp/ogres/ogre-pirate.png", weapon: "fan", over: "loot frenzy" },
  { key: "fire|lava|inferno", kind: "Fire", sprite: "/assets/slimewire/swamp/ogres/ogre-lava.png", weapon: "bomb", over: "magma rush" },
  { key: "ice|frost|snow", kind: "Frost", sprite: "/assets/slimewire/swamp/ogres/ogre-frost.png", weapon: "thunder", over: "freeze frame" },
  { key: "cyber|robot|mech", kind: "Cyber", sprite: "/assets/slimewire/swamp/ogres/ogre-cyber.png", weapon: "laser", over: "overclock" }
];
const SWAMP_NFT_RARITIES = ["common", "uncommon", "rare", "epic", "legendary"];
const SWAMP_NFT_WEAPON_BY_RARITY = { common: "slime", uncommon: "triple", rare: "vine", epic: "laser", legendary: "boulder" };

function swampHashText(value = "") {
  let h = 2166136261;
  for (const ch of String(value || "")) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}

function swampNftText(asset = {}) {
  const content = asset.content || {};
  const metadata = content.metadata || {};
  const collection = asset.grouping?.find?.((g) => /collection/i.test(String(g?.group_key || "")))?.group_value || "";
  return [
    metadata.name,
    asset.name,
    metadata.symbol,
    asset.symbol,
    collection,
    asset.collection?.name,
    asset.authorities?.[0]?.address
  ].filter(Boolean).join(" ").toLowerCase();
}

function swampNftArchetype(asset = {}) {
  const text = swampNftText(asset);
  return SWAMP_NFT_ARCHETYPES.find((a) => new RegExp(`\\b(${a.key})\\b`, "i").test(text)) || SWAMP_NFT_ARCHETYPES[swampHashText(text || asset.id || "swamp") % SWAMP_NFT_ARCHETYPES.length];
}

function swampNftRarity(asset = {}) {
  const text = swampNftText(asset);
  if (/\b(legendary|mythic|god|king|queen|titan|apex|one of one|1\/1)\b/i.test(text)) return "legendary";
  if (/\b(epic|ancient|warlord|reaper|dragon|cyber)\b/i.test(text)) return "epic";
  if (/\b(rare|gold|frost|lava|knight|shaman)\b/i.test(text)) return "rare";
  if (/\b(uncommon|silver|goblin|pirate)\b/i.test(text)) return "uncommon";
  return SWAMP_NFT_RARITIES[swampHashText(`${asset.id || ""}:${text}`) % SWAMP_NFT_RARITIES.length];
}

function swampNftImageUrl(asset = {}) {
  const content = asset.content || {};
  const metadata = content.metadata || {};
  const links = content.links || {};
  const files = Array.isArray(content.files) ? content.files : [];
  const imageFile = files.find((file) => /image/i.test(String(file?.mime || file?.type || ""))) || files[0] || {};
  return firstString(links.image, links.imageUrl, metadata.image, metadata.image_url, imageFile.cdn_uri, imageFile.uri);
}

function swampNftCollectionName(asset = {}) {
  const content = asset.content || {};
  const metadata = content.metadata || {};
  const group = Array.isArray(asset.grouping) ? asset.grouping.find((g) => /collection/i.test(String(g?.group_key || ""))) : null;
  return firstString(asset.collection?.name, metadata.collection?.name, group?.group_value, "Wallet NFT");
}

function swampNftAssetToChampion(asset = {}, index = 0) {
  const id = String(asset.id || asset.interface || `wallet_nft_${index}`).slice(0, 80);
  const name = firstString(asset.content?.metadata?.name, asset.name, `Wallet Monster ${index + 1}`).replace(/[^\x20-\x7E]/g, "").slice(0, 42) || `Wallet Monster ${index + 1}`;
  const rarity = swampNftRarity(asset);
  const archetype = swampNftArchetype(asset);
  return {
    id,
    mint: id,
    name,
    kind: archetype.kind,
    rarity,
    sprite: archetype.sprite,
    imageUrl: swampNftImageUrl(asset),
    collection: swampNftCollectionName(asset),
    weapon: SWAMP_NFT_WEAPON_BY_RARITY[rarity] || archetype.weapon || "slime",
    over: archetype.over,
    source: "wallet-nft"
  };
}

function swampNftAssetLooksPlayable(asset = {}) {
  const iface = String(asset.interface || asset.token_info?.token_standard || "").toLowerCase();
  if (/fungible/.test(iface)) return false;
  if (/collection/.test(iface)) return false;
  if (asset.token_info?.decimals != null && Number(asset.token_info.decimals) > 0) return false;
  const name = firstString(asset.content?.metadata?.name, asset.name);
  return Boolean(asset.id && name);
}

async function fetchSwampWalletNfts(wallet = "") {
  const owner = parsePublicKey(String(wallet || "")).toBase58();
  const cached = swampNftWalletCache.get(owner);
  if (cached && Date.now() - Number(cached.cachedAt || 0) < 60_000) {
    return cached.value;
  }
  if (!heliusDasEnabled()) {
    const value = { ok: true, wallet: owner, nfts: [], indexerReady: false, message: "Helius DAS wallet indexing is not configured on this backend yet." };
    swampNftWalletCache.set(owner, { cachedAt: Date.now(), value });
    return value;
  }
  try {
    const response = await rpcWithRetry("helius das getAssetsByOwner", () => fetchJson(CONFIG.rpcUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Accept": "application/json" },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: "slimewire-swamp-nfts",
        method: "getAssetsByOwner",
        params: {
          ownerAddress: owner,
          page: 1,
          limit: 40,
          displayOptions: {
            showFungible: false,
            showNativeBalance: false,
            showCollectionMetadata: true
          }
        }
      }),
      timeoutMs: CONFIG.heliusDasTimeoutMs
    }), 1, { priority: false });
    if (response?.error) throw new Error(providerErrorValue(response.error) || "Helius DAS returned an error");
    const items = Array.isArray(response?.result?.items) ? response.result.items : [];
    const nfts = items.filter(swampNftAssetLooksPlayable).slice(0, 24).map(swampNftAssetToChampion);
    const value = { ok: true, wallet: owner, nfts, indexerReady: true, scannedAt: new Date().toISOString() };
    swampNftWalletCache.set(owner, { cachedAt: Date.now(), value });
    return value;
  } catch (error) {
    const value = {
      ok: true,
      wallet: owner,
      nfts: [],
      indexerReady: false,
      message: "Wallet NFT indexer was unavailable; local Beam champions still work.",
      warning: safePerfEventText(error?.message || "DAS wallet scan failed", 120)
    };
    swampNftWalletCache.set(owner, { cachedAt: Date.now(), value });
    return value;
  }
}

// --- Presales: hype/commit listings (NO custody — interest only, for now) ---
function presalesPath() { return path.join(CONFIG.dataDir, "presales.json"); }
async function readPresales() { const s = await readJson(presalesPath()); if (!Array.isArray(s.presales)) s.presales = []; return s; }
async function submitPresale(body = {}) {
  const name = String(body.name || "").replace(/[^A-Za-z0-9 _$.-]/g, "").slice(0, 32).trim();
  const symbol = String(body.symbol || "").replace(/[^A-Za-z0-9_$]/g, "").toUpperCase().slice(0, 12);
  if (!name || !symbol) return { ok: false, error: "name + ticker required" };
  const target = Math.max(1, Math.min(100000, Math.round(Number(body.target) || 0))) || 10;
  const days = Math.max(1, Math.min(30, Math.round(Number(body.days) || 3)));
  const blurb = String(body.blurb || "").replace(/[^\x20-\x7E]/g, "").slice(0, 400);
  const by = String(body.by || "anon").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16) || "anon";
  const x = String(body.x || "").slice(0, 120), tg = String(body.tg || "").slice(0, 120), web = String(body.web || "").slice(0, 120);
  // NON-CUSTODIAL deposit wallet: the creator's OWN Solana address where supporters send SOL. We
  // never hold funds — we just display it and read its balance + incoming count on-chain to show
  // "raised" + "contributors". Stored only if it's a valid pubkey.
  const walletRaw = String(body.wallet || "").trim();
  const wallet = solanaPublicKeyLike(walletRaw) ? walletRaw : "";
  const store = await readPresales();
  const now = Date.now();
  const id = "ps" + now.toString(36) + Math.random().toString(36).slice(2, 6);
  store.presales.push({ id, name, symbol, target, blurb, by, x, tg, web, wallet, raisedSol: 0, contributors: 0, interest: 1, backers: [], at: new Date(now).toISOString(), deadline: new Date(now + days * 86400000).toISOString() });
  store.presales = store.presales.slice(-120);
  await writeJsonFile(presalesPath(), store);
  return { ok: true, id, name, symbol };
}
async function bumpPresaleInterest(body = {}) {
  const id = String(body.id || "").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
  const who = String(body.by || "").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16);
  if (!id) return { ok: false, error: "bad id" };
  const store = await readPresales();
  const p = store.presales.find((x) => x.id === id);
  if (!p) return { ok: false, error: "not found" };
  p.backers = Array.isArray(p.backers) ? p.backers : [];
  if (who && !p.backers.includes(who)) p.backers.push(who);
  p.interest = Math.max(Number(p.interest) || 0, p.backers.length) + (who ? 0 : 1);
  // REFERRAL credit: whoever's link brought this hyper gets a point on the referral leaderboard.
  const ref = String(body.ref || "").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16);
  if (ref && ref !== who) { p.refs = p.refs && typeof p.refs === "object" ? p.refs : {}; p.refs[ref] = (p.refs[ref] || 0) + 1; }
  await writeJsonFile(presalesPath(), store);
  return { ok: true, interest: p.interest, backerCount: p.backers.length };
}

// --- PRESALE "buy + send at launch" ESCROW (GATED: PRESALE_ESCROW_ENABLED, default false) ------------
// Unlike the non-custodial board above, an ESCROW presale CUSTODIES contributor SOL in a SlimeWire-
// managed wallet until the creator finalizes: the escrow buys the token with the pooled SOL and sends
// each contributor their PRO-RATA token share — or refunds everyone if it's called off. This is real
// money custody + a token fan-out, so it stays OFF (every mutating call 501s) until the owner has
// dust-tested it end to end and flips PRESALE_ESCROW_ENABLED=true. Prod presales stay non-custodial.
const PRESALE_ESCROW_OWNER = "__presale_escrow__";
const PRESALE_ESCROW_MAX_CONTRIBUTORS = 20;
function presaleEscrowEnabled() { return parseBoolean(process.env.PRESALE_ESCROW_ENABLED || "false"); }
function assertPresaleEscrowEnabled() {
  if (!presaleEscrowEnabled()) {
    const e = new Error("Presale escrow is in TEST MODE — not live yet. Owner: dust-test it, then set PRESALE_ESCROW_ENABLED=true.");
    e.statusCode = 501; throw e;
  }
}
// The managed escrow wallet for a presale (we hold the key; contributors send SOL here).
async function getPresaleEscrowWallet(presaleId) {
  const label = `psesc:${String(presaleId).replace(/[^A-Za-z0-9]/g, "").slice(0, 24)}`;
  const existing = (await readWalletStore()).wallets.find((x) => String(x.ownerId) === PRESALE_ESCROW_OWNER && x.label === label);
  if (existing) return existing;
  return mutateWalletStore((store) => {
    let w = store.wallets.find((x) => String(x.ownerId) === PRESALE_ESCROW_OWNER && x.label === label);
    if (!w) { const kp = Keypair.generate(); w = walletRecord(label, kp, PRESALE_ESCROW_OWNER); store.wallets.push(w); }
    return w;
  });
}
// Contribution ledger from the chain: sender -> total lamports sent INTO the escrow wallet. Bounded.
async function presaleEscrowLedger(escrowPubkey) {
  const key = new PublicKey(escrowPubkey);
  const sigs = await rpcRead("presale escrow sigs", (c) => c.getSignaturesForAddress(key, { limit: 200 }), {}).catch(() => null);
  const byWallet = new Map();
  for (const s of (Array.isArray(sigs) ? sigs : []).slice(0, 120)) {
    const tx = await rpcRead("presale escrow tx", (c) => c.getParsedTransaction(s.signature, { maxSupportedTransactionVersion: 0 }), {}).catch(() => null);
    const instrs = tx?.transaction?.message?.instructions || [];
    for (const ix of instrs) {
      const info = ix?.parsed?.info;
      if (ix?.program === "system" && ix?.parsed?.type === "transfer" && info?.destination === escrowPubkey) {
        const from = String(info.source || "");
        const lamports = Number(info.lamports || 0);
        if (from && from !== escrowPubkey && lamports > 0) byWallet.set(from, (byWallet.get(from) || 0) + lamports);
      }
    }
  }
  return [...byWallet.entries()].map(([wallet, lamports]) => ({ wallet, lamports })).sort((a, b) => b.lamports - a.lamports);
}
function findEscrowPresale(store, id) {
  return (store.presales || []).find((x) => x.id === id && x.escrow);
}
async function webCreatePresaleEscrow(userId, body = {}) {
  assertPresaleEscrowEnabled();
  const name = String(body.name || "").replace(/[^A-Za-z0-9 _$.-]/g, "").slice(0, 32).trim();
  const symbol = String(body.symbol || "").replace(/[^A-Za-z0-9_$]/g, "").toUpperCase().slice(0, 12);
  if (!name || !symbol) { const e = new Error("name + ticker required"); e.statusCode = 400; throw e; }
  const target = Math.max(0.1, Math.min(100000, Number(body.target) || 10));
  const days = Math.max(1, Math.min(30, Math.round(Number(body.days) || 3)));
  const store = await readWalletStore();
  const dev = getWalletAt(store, parseWebWalletIndex(firstString(body.devWalletIndex, body.walletIndex)), userId);
  const now = Date.now();
  const id = "pse" + now.toString(36) + Math.random().toString(36).slice(2, 6);
  const escrow = await getPresaleEscrowWallet(id);
  const psStore = await readPresales();
  psStore.presales.push({
    id, name, symbol, target, escrow: true,
    by: String(body.by || "anon").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16) || "anon",
    blurb: String(body.blurb || "").replace(/[^\x20-\x7E]/g, "").slice(0, 400),
    x: String(body.x || "").slice(0, 120), tg: String(body.tg || "").slice(0, 120), web: String(body.web || "").slice(0, 120),
    wallet: escrow.publicKey, escrowWallet: escrow.publicKey, creatorUserId: String(userId), devPublicKey: dev.publicKey,
    raisedSol: 0, contributors: 0, interest: 1, backers: [],
    at: new Date(now).toISOString(), deadline: new Date(now + days * 86400000).toISOString(), status: "open"
  });
  psStore.presales = psStore.presales.slice(-120);
  await writeJsonFile(presalesPath(), psStore);
  return { ok: true, id, escrowWallet: escrow.publicKey, note: "Contributors send SOL to escrowWallet. Finalize buys + distributes pro-rata; refund returns it." };
}
async function webPresaleEscrowStatus(userId, id) {
  assertPresaleEscrowEnabled();
  const store = await readPresales();
  const p = findEscrowPresale(store, String(id || ""));
  if (!p) { const e = new Error("escrow presale not found"); e.statusCode = 404; throw e; }
  const escrow = p.escrowWallet || p.wallet;
  const bal = await rpcRead("presale escrow balance", (c) => c.getBalance(new PublicKey(escrow), "confirmed"), {}).catch(() => 0);
  const ledger = await presaleEscrowLedger(escrow);
  return {
    ok: true, id, escrowWallet: escrow, balanceSol: lamportsToSol(Number(bal) || 0), targetSol: p.target,
    contributors: ledger.length, ledger: ledger.map((l) => ({ wallet: l.wallet, sol: lamportsToSol(l.lamports) })),
    status: p.status || "open", deadline: p.deadline, isCreator: String(p.creatorUserId || "") === String(userId)
  };
}
function loadEscrowForCreator(psStore, wStore, id, userId) {
  const p = findEscrowPresale(psStore, id);
  if (!p) { const e = new Error("escrow presale not found"); e.statusCode = 404; throw e; }
  if (String(p.creatorUserId || "") !== String(userId)) { const e = new Error("Only the presale creator can do that."); e.statusCode = 403; throw e; }
  const escrowRec = wStore.wallets.find((w) => w.publicKey === (p.escrowWallet || p.wallet) && String(w.ownerId) === PRESALE_ESCROW_OWNER);
  if (!escrowRec) { const e = new Error("escrow wallet missing"); e.statusCode = 500; throw e; }
  return { p, escrowRec };
}
async function webRefundPresaleEscrow(userId, body = {}) {
  assertPresaleEscrowEnabled();
  return runIdempotentMoneyOp("presale-refund", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    () => webRefundPresaleEscrowCore(userId, body), { busyMessage: "Refund is already running — SlimeWire won't double-refund." });
}
async function webRefundPresaleEscrowCore(userId, body = {}) {
  const id = String(body.id || "").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
  const psStore = await readPresales();
  const wStore = await readWalletStore();
  const { p, escrowRec } = loadEscrowForCreator(psStore, wStore, id, userId);
  const keypair = decryptWallet(escrowRec);
  const ledger = (await presaleEscrowLedger(escrowRec.publicKey)).slice(0, PRESALE_ESCROW_MAX_CONTRIBUTORS);
  if (!ledger.length) { const e = new Error("No contributions to refund."); e.statusCode = 400; throw e; }
  const bal = Number(await rpcRead("escrow balance", (c) => c.getBalance(keypair.publicKey, "confirmed"), {}).catch(() => 0));
  const feeReserve = 5000 * (ledger.length + 1);
  const distributable = bal - feeReserve;
  if (distributable <= 0) { const e = new Error("Escrow balance too low to refund after the network fee."); e.statusCode = 400; throw e; }
  // Refund pro-rata to actual contributions (escrow may be slightly under sum-of-contributions after fees).
  const parts = splitReferralLamports(BigInt(distributable), ledger.map((c) => ({ wallet: c.wallet, pct: c.lamports }))).filter((x) => x.lamports > 0n);
  const tx = new Transaction();
  for (const part of parts) tx.add(SystemProgram.transfer({ fromPubkey: keypair.publicKey, toPubkey: new PublicKey(part.wallet), lamports: Number(part.lamports) }));
  const signature = await sendLegacyTransaction(tx, [keypair]);
  invalidateWalletReadCache(escrowRec.publicKey);
  p.status = "refunded"; p.refundedAt = new Date().toISOString();
  await writeJsonFile(presalesPath(), psStore);
  await audit("presale_escrow_refund", { userId, id, contributors: parts.length, signature });
  return { ok: true, action: "refund", refunded: parts.length, signature };
}
async function webFinalizePresaleEscrow(userId, body = {}) {
  assertPresaleEscrowEnabled();
  return runIdempotentMoneyOp("presale-finalize", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    () => webFinalizePresaleEscrowCore(userId, body), { lockMs: 180_000, busyMessage: "Finalize is already running — SlimeWire won't buy/distribute twice." });
}
async function webFinalizePresaleEscrowCore(userId, body = {}) {
  const id = String(body.id || "").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
  const tokenMint = parsePublicKey(String(body.tokenMint || "")).toBase58();
  const slippageBps = parseWebSlippage(body.slippageBps);
  const psStore = await readPresales();
  const wStore = await readWalletStore();
  const { p, escrowRec } = loadEscrowForCreator(psStore, wStore, id, userId);
  if (p.status === "finalized") { const e = new Error("This presale was already finalized."); e.statusCode = 409; throw e; }
  const ledger = (await presaleEscrowLedger(escrowRec.publicKey)).slice(0, PRESALE_ESCROW_MAX_CONTRIBUTORS);
  if (!ledger.length) { const e = new Error("No contributions to finalize."); e.statusCode = 400; throw e; }
  const totalContrib = ledger.reduce((a, c) => a + c.lamports, 0);
  const bal = Number(await rpcRead("escrow balance", (c) => c.getBalance(escrowRec.publicKey, "confirmed"), {}).catch(() => 0));
  // Reserve buy fees + per-contributor ATA rent (~0.00204 SOL each) + transfer fees, so the buy can't
  // strand the distribution with no SOL for token-account rent.
  const reserve = CONFIG.buyReserveLamports + 2_100_000 * ledger.length + 5000 * (ledger.length + 2);
  const buyLamports = bal - reserve;
  if (buyLamports <= 0) { const e = new Error(`Escrow needs more SOL: has ${lamportsToSol(bal)}, needs ~${lamportsToSol(reserve)} reserved for buy + ${ledger.length} payouts.`); e.statusCode = 400; throw e; }
  // 1) Escrow buys the token with the pooled SOL.
  const buyResult = await buyTokenForPlan(escrowRec, tokenMint, buyLamports, slippageBps, { trackTokenDelta: true, userId });
  // 2) Read the escrow's real token account for the bought mint (ATA + program + decimals + raw amount).
  const escrowKp = decryptWallet(escrowRec);
  const lookup = await getOwnedTokenAccountsWithWarningsCached(escrowKp.publicKey, { force: true });
  const acct = (lookup.accounts || []).find((a) => a.mint === tokenMint && a.rawAmount > 0n);
  if (!acct) { const e = new Error("Buy succeeded but no tokens landed in escrow to distribute — refund instead."); e.statusCode = 500; throw e; }
  const mint = new PublicKey(tokenMint);
  const decimals = Number.isInteger(acct.decimals) ? acct.decimals : await getMintDecimals(mint);
  const tokenProgramId = new PublicKey(acct.tokenProgramId || TOKEN_PROGRAM_ID);
  const sourceAta = new PublicKey(acct.pubkey);
  const totalTokens = BigInt(acct.rawAmount);
  // 3) Distribute PRO-RATA to each contributor (one tx each; bounded ≤20). Last gets the remainder.
  const payouts = [];
  let assigned = 0n;
  const distrib = [];
  for (let i = 0; i < ledger.length; i += 1) {
    const share = i === ledger.length - 1
      ? (totalTokens - assigned)
      : (totalTokens * BigInt(ledger[i].lamports)) / BigInt(totalContrib);
    assigned += share;
    distrib.push({ wallet: ledger[i].wallet, rawAmount: share });
  }
  for (const d of distrib) {
    if (d.rawAmount <= 0n) { payouts.push({ wallet: d.wallet, ok: false, message: "share rounded to zero" }); continue; }
    try {
      const dest = new PublicKey(d.wallet);
      const destAta = getAssociatedTokenAddress(mint, dest, tokenProgramId);
      const tx = new Transaction();
      const destInfo = await rpcWithRetry("check contributor token account", () => connection.getAccountInfo(destAta, "confirmed"));
      if (!destInfo) tx.add(createAssociatedTokenAccountInstruction(escrowKp.publicKey, destAta, dest, mint, tokenProgramId));
      tx.add(createTransferCheckedInstruction(sourceAta, mint, destAta, escrowKp.publicKey, d.rawAmount, decimals, [], tokenProgramId));
      const sig = await sendLegacyTransaction(tx, [escrowKp]);
      payouts.push({ wallet: d.wallet, ok: true, tokens: rawTokenAmountToUi(d.rawAmount, decimals), signature: sig });
    } catch (error) {
      payouts.push({ wallet: d.wallet, ok: false, message: friendlyError(error) });
    }
  }
  invalidateWalletReadCache(escrowRec.publicKey);
  const okCount = payouts.filter((x) => x.ok).length;
  p.status = "finalized"; p.finalizedAt = new Date().toISOString(); p.tokenMint = tokenMint; p.buySignature = buyResult.signature;
  await writeJsonFile(presalesPath(), psStore);
  await audit("presale_escrow_finalize", { userId, id, tokenMint, buyLamports: String(buyLamports), distributed: okCount, contributors: ledger.length, buySignature: buyResult.signature });
  return { ok: true, action: "finalize", tokenMint, buySignature: buyResult.signature, distributed: okCount, contributors: ledger.length, payouts };
}
// NON-CUSTODIAL on-chain tracking: for each ACTIVE presale that set a deposit wallet, read the
// wallet's SOL balance (= raised) and its transfer count (= contributors / how many sent) straight
// from the chain. Throttled + fire-and-forget from the GET so the board stays live without us ever
// touching the funds. Best-effort: a failed RPC just keeps the last value.
let _presaleChainAt = 0, _presaleChainBusy = false;
async function refreshPresaleChain(maxAgeMs = 90_000) {
  if (_presaleChainBusy || Date.now() - _presaleChainAt < maxAgeMs) return;
  _presaleChainBusy = true; _presaleChainAt = Date.now();
  try {
    const store = await readPresales();
    const now = Date.now();
    const active = (store.presales || []).filter((p) => p.wallet && Date.parse(p.deadline || "") > now).slice(0, 20);
    let changed = false;
    for (const p of active) {
      try {
        const key = new PublicKey(p.wallet);
        const lamports = await rpcRead("presale balance", (c) => c.getBalance(key, "confirmed"), {}).catch(() => null);
        if (lamports != null) { p.raisedSol = Math.round((Number(lamports) / 1_000_000_000) * 1000) / 1000; changed = true; }
        const sigs = await rpcRead("presale signatures", (c) => c.getSignaturesForAddress(key, { limit: 1000 }), {}).catch(() => null);
        if (Array.isArray(sigs)) { p.contributors = sigs.length; changed = true; }
        p.chainAt = new Date().toISOString();
      } catch {}
    }
    if (changed) await writeJsonFile(presalesPath(), store);
  } catch {} finally { _presaleChainBusy = false; }
}

// --- Raid posts: /raid in Telegram registers an X post, ranked by likes+RTs ---
function raidPostsPath() { return path.join(CONFIG.dataDir, "raid-posts.json"); }
async function readRaidPosts() { const s = await readJson(raidPostsPath()); if (!Array.isArray(s.posts)) s.posts = []; return s; }
function parseTweetId(url) {
  const m = /(?:www\.|mobile\.)?(?:x|twitter|fxtwitter|vxtwitter|fixupx)\.com\/(?:[^/?#\s]+\/)*status\/(\d+)/i.exec(String(url || ""));
  return m ? m[1] : null;
}
async function fetchXEngagement(tweetId) {
  if (!tweetId) return null;
  // PREFERRED: official X API, but ONLY if a bearer token is configured (most accurate, has
  // impressions). Most deploys won't set one — that's a paid product — so this is best-effort.
  const token = process.env.X_BEARER_TOKEN || process.env.TWITTER_BEARER_TOKEN;
  if (token) {
    try {
      const r = await fetch(`https://api.twitter.com/2/tweets/${tweetId}?tweet.fields=public_metrics`, { headers: { Authorization: `Bearer ${token}` } });
      if (r.ok) {
        const j = await r.json(); const m = j && j.data && j.data.public_metrics;
        if (m) return { likes: m.like_count || 0, rts: (m.retweet_count || 0) + (m.quote_count || 0), replies: m.reply_count || 0, bookmarks: Number(m.bookmark_count) || 0, views: Number(m.impression_count) || 0, source: "x-api" };
      }
    } catch {}
  }
  // FREE FALLBACK (no API key, no cost): fxtwitter mirrors a post's PUBLIC counts as plain JSON.
  // This is what makes the raid board's likes/RTs real without paying for the X API. Same mirror
  // we already use for in-chat tweet previews (embedTweetLinks / postXPost).
  try {
    const j = await fetchJson(`https://api.fxtwitter.com/status/${tweetId}`, { timeoutMs: 7000, headers: { "User-Agent": "SlimeWireBot/1.0" } }).catch(() => null);
    const t = j && (j.tweet || (j.tweets && j.tweets[0]));
    if (t) {
      return {
        likes: Number(t.likes) || 0,
        rts: (Number(t.retweets) || 0) + (Number(t.quotes) || 0),
        replies: Number(t.replies) || 0,
        bookmarks: Number(t.bookmarks) || 0,
        views: Number(t.views) || 0,
        source: "fxtwitter"
      };
    }
  } catch {}
  return null;
}
function raidPostScore(p) { return (p.likes || 0) + (p.rts || 0) * 3 + (p.replies || 0) + (p.bumps || 0) * 5; }

// Keep the raid board's like/RT counts LIVE without anyone re-bumping: throttled to once/60s and
// fire-and-forget from the GET, it re-pulls the top posts' engagement from the free fxtwitter
// mirror so the boss gauges climb on their own as the swamp raids. Zero cost (no X API key).
let _raidRefreshAt = 0;
let _raidRefreshing = false;
async function refreshRaidEngagement(maxAgeMs = 60_000) {
  if (_raidRefreshing || Date.now() - _raidRefreshAt < maxAgeMs) return;
  _raidRefreshing = true; _raidRefreshAt = Date.now();
  try {
    const store = await readRaidPosts();
    const posts = (store.posts || []).slice(0, 15);
    let changed = false;
    for (const p of posts) {
      const eng = await fetchXEngagement(p.tid).catch(() => null);
      if (eng) {
        p.likes = eng.likes; p.rts = eng.rts; p.replies = eng.replies;
        if (eng.views) p.views = eng.views;
        p.score = raidPostScore(p); p.refreshedAt = new Date().toISOString();
        changed = true;
      }
    }
    if (changed) { store.posts = store.posts.sort((a, b) => (b.score || 0) - (a.score || 0)); await writeJsonFile(raidPostsPath(), store); }
  } catch {} finally { _raidRefreshing = false; }
}
async function submitRaidPost(body = {}) {
  const url = String(body.url || "").slice(0, 300);
  const tid = parseTweetId(url);
  if (!tid) return { ok: false, error: "need an x.com post link" };
  const by = String(body.by || "anon").replace(/[^A-Za-z0-9_@. -]/g, "").slice(0, 24) || "anon";
  const sym = String(body.symbol || "").replace(/[^A-Za-z0-9_$]/g, "").slice(0, 12);
  // Per-metric raid targets (Raidar-style live checklist): likes / retweets / replies / bookmarks. Optional.
  const clampT = (v) => Math.max(0, Math.min(1000000, Math.round(Number(v) || 0)));
  const targets = body.targets && typeof body.targets === "object"
    ? { likes: clampT(body.targets.likes), rts: clampT(body.targets.rts), replies: clampT(body.targets.replies), bookmarks: clampT(body.targets.bookmarks) }
    : null;
  const target = Math.max(0, Math.min(1000000, Math.round(Number(body.target) || (targets ? targets.likes + targets.rts + targets.replies + targets.bookmarks : 0)))); // 0 = auto milestone on the board
  const store = await readRaidPosts();
  const now = new Date().toISOString();
  const eng = await fetchXEngagement(tid);
  let p = store.posts.find((x) => x.tid === tid);
  if (p) { p.bumps = (p.bumps || 1) + 1; p.at = now; if (sym) p.symbol = sym; if (target) p.target = target; if (targets) p.targets = targets; if (eng) { p.likes = eng.likes; p.rts = eng.rts; p.replies = eng.replies; p.bookmarks = eng.bookmarks || 0; } }
  else { p = { tid, url: `https://x.com/i/status/${tid}`, by, symbol: sym, target, targets, at: now, bumps: 1, likes: eng ? eng.likes : 0, rts: eng ? eng.rts : 0, replies: eng ? eng.replies : 0, bookmarks: eng ? (eng.bookmarks || 0) : 0 }; store.posts.push(p); }
  p.score = raidPostScore(p);
  store.posts = store.posts.sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 200);
  await writeJsonFile(raidPostsPath(), store);
  return { ok: true, score: p.score, liveMetrics: !!eng, tid, url: p.url, symbol: p.symbol, targets: p.targets || null, likes: p.likes || 0, rts: p.rts || 0, replies: p.replies || 0, bookmarks: p.bookmarks || 0 };
}

// ---- RAIDAR-STYLE LIVE RAID CARDS (Telegram) ----------------------------------------------
// /raid <link> opens an interactive SETUP menu (tap to set likes/RT/reply/bookmark goals + a
// duration, then Start). The posted card then EDITS ITSELF as engagement climbs: one overall
// progress bar plus clean N / target rows, a live countdown, and
// "RAID SMASHED" when every goal is hit or "Raid Ended — Time limit reached!" when the timer runs
// out. Counts come from the free fxtwitter mirror (no X API key, no cost). State lives in
// raid-tg.json (separate from the leaderboard's raid-posts.json so the board refresh never clobbers
// the live message refs).
function raidDurStr(ms) { ms = Math.max(0, Number(ms) || 0); const h = Math.floor(ms / 3600000), m = Math.floor((ms % 3600000) / 60000); return h > 0 ? (h + "h" + (m > 0 ? " " + m + "m" : "")) : (m + "m"); }
function raidBar(pct) { const seg = 10; const f = Math.max(0, Math.min(seg, Math.round((Number(pct) || 0) / 100 * seg))); return "█".repeat(f) + "░".repeat(seg - f); }
function raidCompact(n) { n = Number(n) || 0; return n >= 1e6 ? (n / 1e6).toFixed(1) + "M" : n >= 1e3 ? (n / 1e3).toFixed(1) + "K" : String(n); }
function buildRaidProgressCard(p) {
  const sym = p.symbol ? "$" + String(p.symbol).replace(/[^A-Za-z0-9_]/g, "").slice(0, 12) + " " : "";
  const t = p.targets || {};
  const defs = [
    { emoji: "❤️", label: "Likes", cur: Number(p.likes) || 0, tgt: Number(t.likes) || 0 },
    { emoji: "🔁", label: "Retweets", cur: Number(p.rts) || 0, tgt: Number(t.rts) || 0 },
    { emoji: "💬", label: "Replies", cur: Number(p.replies) || 0, tgt: Number(t.replies) || 0 },
    { emoji: "🔖", label: "Bookmarks", cur: Number(p.bookmarks) || 0, tgt: Number(t.bookmarks) || 0 }
  ];
  const active = defs.filter((d) => d.tgt > 0);
  const hasTargets = active.length > 0;
  const startedAt = Number(p.startedAt) || 0, durationMs = Number(p.durationMs) || 0;
  const elapsed = startedAt ? Date.now() - startedAt : 0;
  const timedOut = Boolean(startedAt && durationMs && elapsed >= durationMs);
  let allHit = hasTargets, pctSum = 0;
  // Plain, uncluttered rows — no per-metric colour squares. Just the goal
  // and how many are left, e.g. "❤️ Likes  1 / 5  ·  4 to go".
  const rows = (hasTargets ? active : defs).map((d) => {
    if (d.tgt > 0) {
      const hit = d.cur >= d.tgt; if (!hit) allHit = false;
      pctSum += Math.min(1, d.cur / d.tgt);
      const to = hit ? "✅ done" : `${(d.tgt - d.cur).toLocaleString()} to go`;
      return `${d.emoji} <b>${d.label}</b>  ${d.cur.toLocaleString()} / ${d.tgt.toLocaleString()}  ·  ${to}`;
    }
    return `${d.emoji} <b>${d.label}</b> ${d.cur.toLocaleString()}`;
  });
  const overall = hasTargets ? Math.round((pctSum / active.length) * 100) : 0;
  const progressLine = hasTargets ? `Progress <code>${raidBar(overall)}</code> <b>${overall}%</b>` : "";
  const done = allHit || timedOut; // stop editing once smashed or timed out
  const header = allHit
    ? `🔥🔥 <b>${sym}RAID SMASHED!</b> 🔥🔥`
    : timedOut
      ? "⚠️ <b>Raid Ended — Time limit reached!</b>"
      : `⚔️ <b>${sym}RAID is LIVE</b>`;
  const durLine = (startedAt && durationMs)
    ? (done ? `🕐 Duration: ${raidDurStr(durationMs)}` : `⏳ Ends in <b>${raidDurStr(Math.max(0, durationMs - elapsed))}</b>`)
    : "";
  const viewsLine = Number(p.views) > 0 ? `👀 ${raidCompact(p.views)} views` : "";
  const lines = [
    header, progressLine, "",
    ...rows,
    viewsLine ? "\n" + viewsLine : "",
    "",
    `👉 <a href="${p.url}">Open the post & raid it</a>`,
    durLine,
    done ? "🔥 <a href=\"https://www.slimewire.org/raids\">Trending board</a>" : "👆 Like · RT · reply · bookmark — this card updates live."
  ].filter(Boolean);
  const btns = [{ text: done ? "✅ Raided" : "⚔️ Raid this post", url: p.url }];
  if (!done && p.tid) btns.push({ text: "🔄 Refresh", callback_data: "rr:" + p.tid });
  btns.push({ text: "🔥 Trending", url: "https://www.slimewire.org/raids" });
  const markup = { inline_keyboard: [btns] };
  return { text: lines.join("\n"), markup, done };
}
// Force an on-demand engagement pull when a raider taps 🔄 Refresh. Returns true when handled.
async function handleRaidRefreshCallback(query, userId) {
  const data = String(query?.data || "");
  if (!data.startsWith("rr:")) return false;
  const tid = data.slice(3);
  const chatId = query.message?.chat?.id, msgId = query.message?.message_id;
  try {
    const s = await readRaidTg();
    const c = s.cards[tid];
    if (!c) { try { await telegram("answerCallbackQuery", { callback_query_id: query.id, text: "This raid has ended." }); } catch {} return true; }
    const eng = await fetchXEngagement(tid).catch(() => null);
    const likes = eng ? eng.likes : (c.likes || 0), rts = eng ? eng.rts : (c.rts || 0);
    const replies = eng ? eng.replies : (c.replies || 0), bookmarks = eng ? (eng.bookmarks || 0) : (c.bookmarks || 0);
    const views = eng ? (eng.views || 0) : 0;
    const card = buildRaidProgressCard({ tid, symbol: c.symbol, targets: c.targets, likes, rts, replies, bookmarks, views, url: c.url, startedAt: c.startedAt, durationMs: c.durationMs });
    const ref = (c.refs || []).find((r) => String(r.messageId) === String(msgId)) || {};
    try {
      if (ref.hasMedia) await telegram("editMessageCaption", { chat_id: chatId, message_id: msgId, caption: card.text, parse_mode: "HTML", reply_markup: card.markup });
      else await telegram("editMessageText", { chat_id: chatId, message_id: msgId, text: card.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: card.markup });
    } catch (e) { if (!/not modified/i.test(String(e?.message || ""))) throw e; }
    await updateRaidTgCard(tid, { likes, rts, replies, bookmarks, lastCard: card.text, done: card.done });
    if (card.done) {
      const chats = [...new Set((c.refs || []).map((item) => String(item.chatId)))];
      for (const doneChatId of chats) {
        const doneRef = (c.refs || []).find((item) => String(item.chatId) === doneChatId);
        if (doneRef) await telegram("unpinChatMessage", { chat_id: doneChatId, message_id: doneRef.messageId }).catch(() => {});
        await startNextQueuedRaidForChat(doneChatId).catch(() => false);
      }
    }
    try { await telegram("answerCallbackQuery", { callback_query_id: query.id, text: eng ? "🔄 Refreshed" : "Couldn't reach X — try again." }); } catch {}
  } catch { try { await telegram("answerCallbackQuery", { callback_query_id: query.id, text: "Refresh failed — try again." }); } catch {} }
  return true;
}
// ---- Interactive /raid setup: tap-to-set goals + duration, then Start (no typing needed) -------
const raidDrafts = new Map(); // `${chatId}:${messageId}` -> draft {tid,url,symbol,by,targets,durationMin,at}
// Pending typed-input: after a metric button is tapped, we wait for that admin's
// next message (a number) in that chat. key = `${chatId}:${userId}`.
const raidInputPending = new Map();
const raidExpiryTimers = new Map(); // `${chatId}:${tid}` -> hard timeout, independent of X refresh
const RAID_QUEUE_MAX = 10;
const RAID_FIELD_META = {
  likes: { label: "❤️ Likes", eg: 25 },
  rts: { label: "🔁 Retweets", eg: 25 },
  replies: { label: "💬 Replies", eg: 10 },
  bm: { label: "🔖 Bookmarks", eg: 10 },
  dur: { label: "🕐 Duration (minutes)", eg: 15 },
};
function raidDraftKey(chatId, msgId) { return String(chatId) + ":" + String(msgId); }
function raidExpiryKey(chatId, tid) { return `${chatId}:${tid}`; }
function scheduleRaidHardExpiry(chatId, tid, startedAt, durationMs) {
  const key = raidExpiryKey(chatId, tid);
  const old = raidExpiryTimers.get(key);
  if (old) clearTimeout(old);
  const delay = Math.max(0, Number(startedAt) + Number(durationMs) - Date.now());
  const timer = setTimeout(() => {
    raidExpiryTimers.delete(key);
    void finishExpiredRaidForChat(tid, chatId, startedAt).catch(() => {});
  }, Math.min(delay, 2_147_000_000));
  if (typeof timer.unref === "function") timer.unref();
  raidExpiryTimers.set(key, timer);
}
function raidSetupCard(d) {
  const sym = d.symbol ? "$" + escapeTelegramHtml(d.symbol) + " " : "";
  const v = (n) => (Number(n) > 0 ? n : "—");
  const preset = d.savedPresetLabel ? `\nDefault: <b>${escapeTelegramHtml(d.savedPresetLabel)}</b>` : "";
  return {
    text: [
      `⚔️ <b>Set up the ${sym}raid</b>`,
      "Tap a goal, then reply with the number you want (e.g. <b>25</b>). Duration is in <b>minutes</b>. Then 🚀 Start.",
      preset,
      "",
      `👉 <a href="${escapeTelegramHtml(d.url)}">The post you're raiding</a>`
    ].join("\n"),
    markup: { inline_keyboard: [
      [{ text: "⚡ Quick 10/5/5 · 15m", callback_data: "rd:p:quick" }, { text: "⭐ Use Default", callback_data: "rd:p:def" }],
      [{ text: `❤️ Likes: ${v(d.targets.likes)}`, callback_data: "rd:c:likes" }, { text: `🔁 RT: ${v(d.targets.rts)}`, callback_data: "rd:c:rts" }],
      [{ text: `💬 Replies: ${v(d.targets.replies)}`, callback_data: "rd:c:replies" }, { text: `🔖 Bookmarks: ${v(d.targets.bookmarks)}`, callback_data: "rd:c:bm" }],
      [{ text: `🕐 Duration: ${cleanRaidDuration(d.durationMin)}m`, callback_data: "rd:c:dur" }],
      [{ text: "💾 Save as Default", callback_data: "rd:p:save" }, { text: "↩ Reset", callback_data: "rd:p:reset" }],
      [{ text: "🚀 Start Raid", callback_data: "rd:go" }, { text: "✖ Cancel", callback_data: "rd:x" }]
    ] }
  };
}
async function renderRaidSetupCard(chatId, messageId, draft) {
  const card = raidSetupCard(draft);
  try {
    await telegram("editMessageText", { chat_id: chatId, message_id: messageId, text: card.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: card.markup });
  } catch (error) {
    // Re-tapping an already-selected preset is still a successful action; Telegram rejects only the
    // redundant edit. Any other error is real and must be surfaced to the admin.
    if (!friendlyError(error).toLowerCase().includes("message is not modified")) throw error;
  }
  return card;
}
// Apply a typed number to a raid draft field, re-render the setup card. Returns
// true when it consumed the message (an admin was mid-entry for a field).
async function applyRaidTypedInput(message, userId) {
  const chatId = message?.chat?.id;
  const pkey = String(chatId) + ":" + String(userId);
  const pend = raidInputPending.get(pkey);
  if (!pend) return false;
  if (Date.now() - pend.at > 120000) { raidInputPending.delete(pkey); return false; } // expired
  const text = String(message.text || "").trim();
  if (!/^\d{1,7}$/.test(text)) { raidInputPending.delete(pkey); return false; } // not a number → release, don't trap chat
  raidInputPending.delete(pkey);
  const n = Math.max(0, Math.min(1_000_000, parseInt(text, 10)));
  const d = raidDrafts.get(pend.draftKey);
  if (!d) { await say(chatId, "That raid setup expired — run /raid <link> again.").catch(() => {}); return true; }
  if (pend.field === "dur") d.durationMin = cleanRaidDuration(n);
  else if (pend.field === "bm") d.targets.bookmarks = n;
  else d.targets[pend.field] = n;
  raidDrafts.set(pend.draftKey, d);
  // Tidy: remove the prompt + the number the admin typed so the card stays clean.
  if (pend.promptMsgId) { try { await telegram("deleteMessage", { chat_id: chatId, message_id: pend.promptMsgId }); } catch {} }
  try { await telegram("deleteMessage", { chat_id: chatId, message_id: message.message_id }); } catch {}
  try {
    await renderRaidSetupCard(chatId, pend.setupMsgId, d);
  } catch (error) {
    console.warn(`[raid] typed setup render failed chat=${chatId}: ${friendlyError(error)}`);
    await telegram("sendMessage", {
      chat_id: chatId,
      ...(d.messageThreadId ? { message_thread_id: d.messageThreadId } : {}),
      text: "I saved that number, but couldn't refresh the setup card. Run /raid with the link again if the card stays stale."
    }).catch(() => {});
  }
  return true;
}
// Launch a configured raid: record it, post the live card, register the auto-updating message ref.
async function startRaidFromDraft(chatId, d, { fromQueue = false } = {}) {
  if (!fromQueue) {
    const queued = await queueRaidBehindActive(chatId, d);
    if (queued.queued) {
      const queuedText = queued.full
        ? `⏳ The raid queue is full (${RAID_QUEUE_MAX}). Let one finish or use <code>/cancel raid</code>.`
        : queued.active
        ? "⚔️ That post is already the live raid."
        : queued.duplicate
        ? `⏳ That post is already <b>#${queued.position}</b> in the raid queue.`
        : `⏳ <b>Raid queued · #${queued.position} of ${RAID_QUEUE_MAX}</b>\nIt starts automatically when the live raid is completed or its timer ends.`;
      await telegram("sendMessage", {
        chat_id: chatId,
        ...(d.messageThreadId ? { message_thread_id: d.messageThreadId } : {}),
        text: queuedText,
        parse_mode: "HTML"
      }).catch(() => {});
      return { queued: true, position: queued.position };
    }
  }
  const res = await submitRaidPost({ url: d.url, by: d.by, symbol: d.symbol, targets: d.targets });
  if (!res.ok) {
    await telegram("sendMessage", {
      chat_id: chatId,
      ...(d.messageThreadId ? { message_thread_id: d.messageThreadId } : {}),
      text: "Couldn't start that raid — send a valid X post link."
    }).catch(() => {});
    if (fromQueue) await startNextQueuedRaidForChat(chatId).catch(() => false);
    return { started: false };
  }
  const ge = await getGroupBotEntry(chatId).catch(() => null);
  const startedAt = Date.now(), durationMs = cleanRaidDuration(d.durationMin) * 60_000;
  const card = buildRaidProgressCard({ tid: res.tid, symbol: res.symbol || d.symbol, targets: d.targets, likes: res.likes, rts: res.rts, replies: res.replies, bookmarks: res.bookmarks || 0, url: res.url || d.url, startedAt, durationMs });
  // Raid uses its OWN art (raidMedia) if set, else falls back to the buy art (customMedia).
  const media = (ge && ge.raidMedia && ge.raidMedia.value) ? ge.raidMedia
    : (ge && ge.customMedia && ge.customMedia.value) ? ge.customMedia : null;
  const sent = await sendGroupAlertMedia(chatId, media, card.text, card.markup, { messageThreadId: d.messageThreadId });
  if (sent && sent.result && sent.result.message_id) {
    await attachRaidTgCard(res.tid, { url: res.url || d.url, symbol: res.symbol || d.symbol, targets: d.targets, startedAt, durationMs, ref: { chatId, messageId: sent.result.message_id, hasMedia: sent.hasMedia, messageThreadId: d.messageThreadId || null }, eng: { likes: res.likes, rts: res.rts, replies: res.replies, bookmarks: res.bookmarks || 0 } });
    scheduleRaidHardExpiry(chatId, res.tid, startedAt, durationMs);
    await unpinOtherRaidCardsForChat(chatId, sent.result.message_id);
    const pinned = await telegram("pinChatMessage", { chat_id: chatId, message_id: sent.result.message_id, disable_notification: true }).then(() => true).catch(() => false);
    if (!pinned) await telegram("sendMessage", {
      chat_id: chatId,
      ...(d.messageThreadId ? { message_thread_id: d.messageThreadId } : {}),
      text: "Raid started, but I need the group's Pin Messages permission to keep it pinned."
    }).catch(() => {});
  } else {
    console.warn(`[raid] live card send failed chat=${chatId} thread=${d.messageThreadId || 0}: ${friendlyError(sent?.error)}`);
    await telegram("sendMessage", {
      chat_id: chatId,
      ...(d.messageThreadId ? { message_thread_id: d.messageThreadId } : {}),
      text: "Couldn't post that raid card. Check my Send Messages permission; I'll move to the next queued raid."
    }).catch(() => {});
    if (fromQueue) setTimeout(() => { void startNextQueuedRaidForChat(chatId); }, 0);
    return { started: false };
  }
  return { started: true };
}
// Route raid-setup CALLBACKS (rd:*) — the tap-to-configure menu. Returns true if handled.
async function handleRaidSetupCallback(query, userId) {
  const data = String(query?.data || "");
  if (!data.startsWith("rd:")) return false;
  const chatId = query.message?.chat?.id, msgId = query.message?.message_id;
  const ack = (text = "", showAlert = false) => telegram("answerCallbackQuery", {
    callback_query_id: query.id,
    ...(text ? { text } : {}),
    ...(showAlert ? { show_alert: true } : {})
  }).catch(() => {});
  const key = raidDraftKey(chatId, msgId);
  const d = raidDrafts.get(key);
  if (!d) {
    try { await telegram("editMessageText", { chat_id: chatId, message_id: msgId, text: "This raid setup expired — run /raid <link> again." }); } catch {}
    await ack("This raid setup expired. Run /raid with the link again.", true);
    return true;
  }
  if (!(await isGroupBotAdmin(chatId, userId, query.message).catch(() => false))) {
    await ack("Only group admins can change or start this raid.", true);
    return true;
  }
  if (data === "rd:x") {
    raidDrafts.delete(key);
    try { await telegram("editMessageText", { chat_id: chatId, message_id: msgId, text: "Raid setup cancelled." }); } catch {}
    await ack("Raid setup cancelled.");
    return true;
  }
  if (data === "rd:go") {
    if (!(d.targets.likes || d.targets.rts || d.targets.replies || d.targets.bookmarks)) { await ack("Set at least one goal first.", true); return true; }
    await ack("Starting raid…");
    raidDrafts.delete(key);
    try { await telegram("deleteMessage", { chat_id: chatId, message_id: msgId }); } catch {}
    await startRaidFromDraft(chatId, d).catch(async (error) => {
      console.warn(`[raid] start failed chat=${chatId}: ${friendlyError(error)}`);
      await say(chatId, "Couldn't start the raid. Check my Send Messages and Pin Messages permissions, then run /raid with the link again.").catch(() => {});
    });
    return true;
  }
  if (data.startsWith("rd:p:")) {
    const action = data.slice(5);
    let notice = "Preset applied.";
    try {
      if (action === "quick" || action === "five") {
        d.targets = { ...RAID_DEFAULT_PRESET.targets };
        d.durationMin = RAID_DEFAULT_PRESET.durationMin;
        notice = `Quick preset applied: ${raidPresetLabel(RAID_DEFAULT_PRESET)}`;
      } else if (action === "def") {
        const cfg = raidConfig(await getGroupBotEntry(chatId).catch(() => null));
        d.targets = { ...cfg.targets };
        d.durationMin = cfg.durationMin;
        d.savedPresetLabel = raidPresetLabel(cfg);
        notice = `Saved default applied: ${raidPresetLabel(cfg)}`;
      } else if (action === "reset") {
        d.targets = { ...RAID_DEFAULT_PRESET.targets };
        d.durationMin = RAID_DEFAULT_PRESET.durationMin;
        notice = `Reset to ${raidPresetLabel(RAID_DEFAULT_PRESET)}`;
      } else if (action === "save") {
        const cfg = await setRaidConfig(chatId, { targets: d.targets, durationMin: d.durationMin });
        d.targets = { ...cfg.targets };
        d.durationMin = cfg.durationMin;
        d.savedPresetLabel = raidPresetLabel(cfg);
        notice = `Default saved: ${raidPresetLabel(cfg)}`;
      } else {
        await ack("That preset is no longer available. Reopen /raid.", true);
        return true;
      }
      d.at = Date.now();
      raidDrafts.set(key, d);
      await renderRaidSetupCard(chatId, msgId, d);
      await ack(notice);
    } catch (error) {
      console.warn(`[raid] preset ${action || "unknown"} failed chat=${chatId}: ${friendlyError(error)}`);
      await ack(action === "save" ? "Couldn't save that preset. Try again." : "Couldn't apply that preset. Reopen /raid and try again.", true);
    }
    return true;
  }
  if (data.startsWith("rd:c:")) {
    const field = data.slice(5);
    const meta = RAID_FIELD_META[field];
    if (!meta) { await ack("That raid field is no longer available. Reopen /raid.", true); return true; }
    // Ask via a POPUP (answerCallbackQuery show_alert) — NO chat message, so the
    // setup never floods the group. The admin's next number is captured + deleted
    // by applyRaidTypedInput. promptMsgId stays null (nothing to clean up).
    raidInputPending.set(String(chatId) + ":" + String(userId), {
      draftKey: key, field, setupMsgId: msgId, promptMsgId: null, at: Date.now(),
    });
    await ack(`Reply with the number for ${meta.label.replace(/<[^>]+>/g, "")} (e.g. ${meta.eg})${field === "dur" ? "" : ". Send 0 to clear"}.`, true);
    return true;
  }
  await ack();
  return true;
}
function raidTgPath() { return path.join(CONFIG.dataDir, "raid-tg.json"); }
async function readRaidTg() {
  let s = null;
  try { s = await readJson(raidTgPath()); } catch { s = null; }
  if (!s || typeof s !== "object") s = {};
  if (!s.cards || typeof s.cards !== "object") s.cards = {};
  if (!s.queues || typeof s.queues !== "object") s.queues = {};
  for (const [chatId, queue] of Object.entries(s.queues)) {
    if (!Array.isArray(queue) || !queue.length) delete s.queues[chatId];
    else {
      const active = Object.values(s.cards).find((card) => raidCardIsActiveForQueue(card, chatId));
      const ref = active?.refs?.find((item) => String(item.chatId) === String(chatId));
      const activeDurationMin = Math.max(1, Math.round(Number(ref?.durationMs || active?.durationMs || 0) / 60_000));
      s.queues[chatId] = queue.slice(0, RAID_QUEUE_MAX).map((item) => active ? { ...item, durationMin: activeDurationMin } : item);
    }
  }
  return s;
}

async function unpinOtherRaidCardsForChat(chatId, keepMessageId) {
  const store = await readRaidTg().catch(() => ({ cards: {} }));
  const oldMessageIds = [];
  for (const card of Object.values(store.cards || {})) {
    for (const ref of (Array.isArray(card?.refs) ? card.refs : [])) {
      if (String(ref.chatId) === String(chatId) && String(ref.messageId) !== String(keepMessageId)) oldMessageIds.push(ref.messageId);
    }
  }
  const unique = [...new Set(oldMessageIds)].slice(-20);
  for (const messageId of unique) await telegram("unpinChatMessage", { chat_id: chatId, message_id: messageId }).catch(() => {});
  return unique.length;
}

function raidCardIsActiveForQueue(card, chatId) {
  if (!card || card.done || !Array.isArray(card.refs)) return false;
  const ref = card.refs.find((item) => String(item.chatId) === String(chatId));
  if (!ref) return false;
  return !buildRaidProgressCard({ ...card, startedAt: Number(ref.startedAt) || card.startedAt, durationMs: Number(ref.durationMs) || card.durationMs }).done;
}

async function queueRaidBehindActive(chatId, draft) {
  return withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    const active = Object.values(s.cards).find((card) => raidCardIsActiveForQueue(card, chatId));
    if (!active) return { queued: false, position: 0, duplicate: false };
    if (String(active.tid) === String(draft.tid)) return { queued: true, position: 0, duplicate: true, active: true };
    const key = String(chatId);
    const queue = Array.isArray(s.queues[key]) ? s.queues[key] : [];
    const existing = queue.findIndex((item) => String(item.tid) === String(draft.tid));
    if (existing >= 0) return { queued: true, position: existing + 1, duplicate: true };
    if (queue.length >= RAID_QUEUE_MAX) return { queued: true, position: queue.length, duplicate: false, full: true };
    queue.push({
      tid: String(draft.tid), url: String(draft.url || "").slice(0, 300), symbol: String(draft.symbol || "").slice(0, 12),
      by: String(draft.by || "anon").slice(0, 30), targets: cleanRaidTargets(draft.targets),
      durationMin: cleanRaidDuration(draft.durationMin),
      messageThreadId: Number(draft.messageThreadId) > 0 ? Number(draft.messageThreadId) : null,
      queuedAt: Date.now()
    });
    s.queues[key] = queue.slice(0, RAID_QUEUE_MAX);
    await writeJsonFile(raidTgPath(), s);
    return { queued: true, position: s.queues[key].length, duplicate: false };
  }).catch(() => ({ queued: false, position: 0, duplicate: false }));
}

async function raidQueueStatus(chatId) {
  const s = await readRaidTg();
  const activeCard = Object.values(s.cards).find((card) => raidCardIsActiveForQueue(card, chatId));
  const ref = activeCard?.refs?.find((item) => String(item.chatId) === String(chatId));
  const activeRaid = activeCard ? {
    targets: cleanRaidTargets(activeCard.targets),
    durationMin: cleanRaidDuration(Number(ref?.durationMs || activeCard.durationMs || RAID_DEFAULT_PRESET.durationMin * 60_000) / 60_000)
  } : null;
  const queue = Array.isArray(s.queues[String(chatId)]) ? s.queues[String(chatId)].slice(0, RAID_QUEUE_MAX) : [];
  return { active: Boolean(activeCard), activeRaid, queue };
}

async function startNextQueuedRaidForChat(chatId) {
  const draft = await withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    if (Object.values(s.cards).some((card) => raidCardIsActiveForQueue(card, chatId))) return null;
    const key = String(chatId);
    const queue = Array.isArray(s.queues[key]) ? s.queues[key] : [];
    const next = queue.shift() || null;
    if (queue.length) s.queues[key] = queue; else delete s.queues[key];
    if (next) await writeJsonFile(raidTgPath(), s);
    return next;
  }).catch(() => null);
  if (!draft) return false;
  const result = await startRaidFromDraft(chatId, draft, { fromQueue: true });
  return Boolean(result?.started);
}
// Attach (or refresh) the live TG message ref for a raided tweet. One ref per chat (newest wins),
// so the same tweet raided in several groups updates all of them.
async function attachRaidTgCard(tid, { url, symbol, targets, ref, eng, startedAt, durationMs } = {}) {
  if (!tid || !ref || !ref.messageId) return;
  await withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    let c = s.cards[tid];
    if (!c) c = s.cards[tid] = { tid, url: url || `https://x.com/i/status/${tid}`, symbol: symbol || "", targets: targets || null, refs: [], likes: 0, rts: 0, replies: 0, bookmarks: 0, done: false, lastCard: "", at: new Date().toISOString() };
    if (url) c.url = url;
    if (symbol) c.symbol = symbol;
    if (targets) c.targets = targets;
    if (startedAt) c.startedAt = startedAt;
    if (durationMs) c.durationMs = durationMs;
    if (eng) { c.likes = Number(eng.likes) || 0; c.rts = Number(eng.rts) || 0; c.replies = Number(eng.replies) || 0; c.bookmarks = Number(eng.bookmarks) || 0; }
    c.refs = (c.refs || []).filter((r) => String(r.chatId) !== String(ref.chatId));
    c.refs.push({ chatId: String(ref.chatId), messageId: ref.messageId, hasMedia: !!ref.hasMedia, messageThreadId: Number(ref.messageThreadId) > 0 ? Number(ref.messageThreadId) : null, postsSinceRefresh: 0, startedAt: Number(startedAt) || Date.now(), durationMs: Number(durationMs) || RAID_DEFAULT_PRESET.durationMin * 60_000 });
    c.done = false; c.lastCard = ""; // re-arm so the new card edits at least once
    // bound the store: keep the 120 most recent cards
    const ids = Object.keys(s.cards);
    if (ids.length > 120) {
      const stale = ids.map((id) => [id, s.cards[id]]).sort((a, b) => String(a[1].at || "").localeCompare(String(b[1].at || ""))).slice(0, ids.length - 120);
      for (const [id] of stale) delete s.cards[id];
    }
    await writeJsonFile(raidTgPath(), s);
  }).catch(() => {});
}
async function updateRaidTgCard(tid, { likes, rts, replies, bookmarks, lastCard, done, dropRefMessageIds } = {}) {
  await withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    const c = s.cards[tid];
    if (!c) return;
    if (likes != null) c.likes = likes;
    if (rts != null) c.rts = rts;
    if (replies != null) c.replies = replies;
    if (bookmarks != null) c.bookmarks = bookmarks;
    if (lastCard != null) c.lastCard = lastCard;
    if (done != null) c.done = done;
    if (Array.isArray(dropRefMessageIds) && dropRefMessageIds.length) c.refs = (c.refs || []).filter((r) => !dropRefMessageIds.includes(r.messageId));
    await writeJsonFile(raidTgPath(), s);
  }).catch(() => {});
}

async function finishExpiredRaidForChat(tid, chatId, expectedStartedAt = 0) {
  const expired = await withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    const card = s.cards[String(tid)];
    if (!card || card.done || !Array.isArray(card.refs)) return null;
    const ref = card.refs.find((item) => String(item.chatId) === String(chatId));
    if (!ref) return null;
    const startedAt = Number(ref.startedAt) || Number(card.startedAt) || 0;
    const durationMs = Number(ref.durationMs) || Number(card.durationMs) || RAID_DEFAULT_PRESET.durationMin * 60_000;
    if (expectedStartedAt && startedAt !== Number(expectedStartedAt)) return null; // stale timer after a replacement raid
    if (!startedAt || Date.now() < startedAt + durationMs) return null;
    card.refs = card.refs.filter((item) => String(item.chatId) !== String(chatId));
    if (!card.refs.length) card.done = true;
    card.endedAt = new Date().toISOString();
    await writeJsonFile(raidTgPath(), s);
    return { card: { ...card, refs: undefined }, ref: { ...ref }, startedAt, durationMs };
  }).catch(() => null);
  if (!expired) return { expired: false, nextStarted: false };

  const c = expired.card;
  const finalCard = buildRaidProgressCard({
    tid: c.tid, symbol: c.symbol, targets: c.targets, likes: c.likes, rts: c.rts,
    replies: c.replies, bookmarks: c.bookmarks, views: c.views, url: c.url,
    startedAt: expired.startedAt, durationMs: expired.durationMs
  });
  try {
    if (expired.ref.hasMedia) await telegram("editMessageCaption", { chat_id: chatId, message_id: expired.ref.messageId, caption: finalCard.text, parse_mode: "HTML", reply_markup: finalCard.markup });
    else await telegram("editMessageText", { chat_id: chatId, message_id: expired.ref.messageId, text: finalCard.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: finalCard.markup });
  } catch { /* the hard stop and queue handoff still happen if the old card was deleted */ }
  await telegram("unpinChatMessage", { chat_id: chatId, message_id: expired.ref.messageId }).catch(() => {});
  const nextStarted = await startNextQueuedRaidForChat(chatId).catch(() => false);
  if (!nextStarted) {
    await telegram("sendMessage", {
      chat_id: chatId,
      ...(expired.ref.messageThreadId ? { message_thread_id: expired.ref.messageThreadId } : {}),
      text: "⏭ Raid time is up. Time for the next raid — send /raid <X post link> when ready."
    }).catch(() => {});
  }
  return { expired: true, nextStarted };
}

async function cancelActiveRaidForChat(chatId) {
  let draftCancelled = false;
  for (const key of [...raidDrafts.keys()]) {
    if (key.startsWith(`${chatId}:`)) { raidDrafts.delete(key); draftCancelled = true; }
  }
  for (const key of [...raidInputPending.keys()]) {
    if (key.startsWith(`${chatId}:`)) raidInputPending.delete(key);
  }
  const cancelled = await withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    const candidates = Object.values(s.cards || {})
      .filter((card) => !card.done && Array.isArray(card.refs) && card.refs.some((ref) => String(ref.chatId) === String(chatId)))
      .sort((a, b) => Number(b.startedAt || Date.parse(b.at || 0) || 0) - Number(a.startedAt || Date.parse(a.at || 0) || 0));
    const card = candidates[0];
    if (!card) return null;
    const ref = card.refs.find((item) => String(item.chatId) === String(chatId));
    card.refs = card.refs.filter((item) => String(item.chatId) !== String(chatId));
    if (!card.refs.length) card.done = true;
    await writeJsonFile(raidTgPath(), s);
    return ref ? { tid: card.tid, url: card.url, ref: { ...ref } } : null;
  }).catch(() => null);
  if (!cancelled) return { cancelled: false, draftCancelled };
  const expiryKey = raidExpiryKey(chatId, cancelled.tid);
  if (raidExpiryTimers.has(expiryKey)) { clearTimeout(raidExpiryTimers.get(expiryKey)); raidExpiryTimers.delete(expiryKey); }
  const text = `🛑 <b>Raid cancelled</b>${cancelled.url ? `\n<a href="${escapeTelegramHtml(cancelled.url)}">View the X post</a>` : ""}`;
  try {
    if (cancelled.ref.hasMedia) {
      await telegram("editMessageCaption", { chat_id: chatId, message_id: cancelled.ref.messageId, caption: text, parse_mode: "HTML", reply_markup: { inline_keyboard: [] } });
    } else {
      await telegram("editMessageText", { chat_id: chatId, message_id: cancelled.ref.messageId, text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: { inline_keyboard: [] } });
    }
  } catch {}
  await telegram("unpinChatMessage", { chat_id: chatId, message_id: cancelled.ref.messageId }).catch(() => {});
  const nextStarted = await startNextQueuedRaidForChat(chatId).catch(() => false);
  return { cancelled: true, draftCancelled, nextStarted };
}

async function claimRaidGroupResurface(chatId, incomingMessageId, incomingMessageThreadId = null) {
  return withFileLock(raidTgPath(), async () => {
    const s = await readRaidTg();
    const candidates = Object.values(s.cards || {})
      .filter((card) => !card.done && Array.isArray(card.refs) && card.refs.some((ref) => String(ref.chatId) === String(chatId)))
      .sort((a, b) => Number(b.startedAt || Date.parse(b.at || 0) || 0) - Number(a.startedAt || Date.parse(a.at || 0) || 0));
    const card = candidates[0];
    if (!card) return null;
    const wantedThreadId = Number(incomingMessageThreadId) > 0 ? Number(incomingMessageThreadId) : null;
    const ref = card.refs.find((item) => String(item.chatId) === String(chatId)
      && (Number(item.messageThreadId) > 0 ? Number(item.messageThreadId) : null) === wantedThreadId);
    if (!ref || Number(incomingMessageId) <= Number(ref.messageId)) return null;
    ref.postsSinceRefresh = Math.max(0, Number(ref.postsSinceRefresh) || 0) + 1;
    const due = ref.postsSinceRefresh >= 5;
    if (due) ref.postsSinceRefresh = 0;
    await writeJsonFile(raidTgPath(), s);
    return due ? { card: { ...card, refs: undefined }, ref: { ...ref } } : null;
  }).catch(() => null);
}

async function maybeResurfaceActiveRaid(chatId, incomingMessageId, incomingMessageThreadId = null) {
  const job = await claimRaidGroupResurface(chatId, incomingMessageId, incomingMessageThreadId);
  if (!job) return false;
  const c = job.card;
  const live = buildRaidProgressCard({
    tid: c.tid, symbol: c.symbol, targets: c.targets, likes: c.likes, rts: c.rts,
    replies: c.replies, bookmarks: c.bookmarks, views: c.views, url: c.url,
    startedAt: c.startedAt, durationMs: c.durationMs
  });
  if (live.done) {
    await updateRaidTgCard(c.tid, { lastCard: live.text, done: true });
    await telegram("unpinChatMessage", { chat_id: chatId, message_id: job.ref.messageId }).catch(() => {});
    await startNextQueuedRaidForChat(chatId).catch(() => false);
    return false;
  }
  const copied = await telegram("copyMessage", {
    chat_id: chatId,
    ...(job.ref.messageThreadId ? { message_thread_id: job.ref.messageThreadId } : {}),
    from_chat_id: chatId,
    message_id: job.ref.messageId,
    disable_notification: true,
    reply_markup: live.markup
  }).catch(() => null);
  if (!copied?.message_id) return false;
  try {
    if (job.ref.hasMedia) {
      await telegram("editMessageCaption", { chat_id: chatId, message_id: copied.message_id, caption: live.text, parse_mode: "HTML", reply_markup: live.markup });
    } else {
      await telegram("editMessageText", { chat_id: chatId, message_id: copied.message_id, text: live.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: live.markup });
    }
  } catch { /* the copied card is still usable even if Telegram says it was not modified */ }
  await attachRaidTgCard(c.tid, {
    url: c.url, symbol: c.symbol, targets: c.targets, startedAt: c.startedAt, durationMs: c.durationMs,
    ref: { chatId, messageId: copied.message_id, hasMedia: job.ref.hasMedia, messageThreadId: job.ref.messageThreadId || null },
    eng: { likes: c.likes, rts: c.rts, replies: c.replies, bookmarks: c.bookmarks }
  });
  await telegram("pinChatMessage", { chat_id: chatId, message_id: copied.message_id, disable_notification: true }).catch(() => {});
  await telegram("unpinChatMessage", { chat_id: chatId, message_id: job.ref.messageId }).catch(() => {});
  await telegram("deleteMessage", { chat_id: chatId, message_id: job.ref.messageId }).catch(() => {});
  return true;
}

// Interval loop: pull fresh engagement for every active raid card and edit its TG message(s).
let _raidTgRefreshing = false;
async function refreshRaidTgCards() {
  if (_raidTgRefreshing) return;
  _raidTgRefreshing = true;
  try {
    let s = await readRaidTg();
    // Hard-stop recovery runs before any X request. This closes expired raids even when X is slow,
    // and re-arms precise timers after a Render restart.
    const now = Date.now();
    for (const c of Object.values(s.cards || {}).filter((item) => !item.done && Array.isArray(item.refs))) {
      for (const ref of c.refs) {
        const startedAt = Number(ref.startedAt) || Number(c.startedAt) || 0;
        const durationMs = Number(ref.durationMs) || Number(c.durationMs) || RAID_DEFAULT_PRESET.durationMin * 60_000;
        if (startedAt && now >= startedAt + durationMs) await finishExpiredRaidForChat(c.tid, ref.chatId, startedAt).catch(() => {});
        else if (startedAt && !raidExpiryTimers.has(raidExpiryKey(ref.chatId, c.tid))) scheduleRaidHardExpiry(ref.chatId, c.tid, startedAt, durationMs);
      }
    }
    s = await readRaidTg();
    const cards = Object.values(s.cards || {}).filter((c) => Array.isArray(c.refs) && c.refs.length && !c.done);
    for (const c of cards) {
      const eng = await fetchXEngagement(c.tid).catch(() => null);
      const likes = eng ? eng.likes : (c.likes || 0);
      const rts = eng ? eng.rts : (c.rts || 0);
      const replies = eng ? eng.replies : (c.replies || 0);
      const bookmarks = eng ? (eng.bookmarks || 0) : (c.bookmarks || 0);
      const views = eng ? (eng.views || 0) : (c.views || 0);
      const card = buildRaidProgressCard({ tid: c.tid, symbol: c.symbol, targets: c.targets, likes, rts, replies, bookmarks, views, url: c.url, startedAt: c.startedAt, durationMs: c.durationMs });
      if (card.text === c.lastCard && !card.done) { await updateRaidTgCard(c.tid, { likes, rts, replies, bookmarks }); continue; }
      const dead = [];
      for (const ref of c.refs) {
        try {
          if (ref.hasMedia) await telegram("editMessageCaption", { chat_id: ref.chatId, message_id: ref.messageId, caption: card.text, parse_mode: "HTML", reply_markup: card.markup });
          else await telegram("editMessageText", { chat_id: ref.chatId, message_id: ref.messageId, text: card.text, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: card.markup });
        } catch (e) {
          const m = String((e && e.message) || "");
          // "message is not modified" is benign (keep the ref); a genuinely gone message / kicked bot drops it.
          if (!/not modified/i.test(m) && /not found|to edit not found|message_id_invalid|chat not found|bot was kicked|forbidden|blocked/i.test(m)) dead.push(ref.messageId);
        }
      }
      if (card.done) {
        for (const ref of c.refs) await telegram("unpinChatMessage", { chat_id: ref.chatId, message_id: ref.messageId }).catch(() => {});
      }
      await updateRaidTgCard(c.tid, { likes, rts, replies, bookmarks, lastCard: card.text, done: card.done, dropRefMessageIds: dead });
      if (card.done) {
        const chats = [...new Set(c.refs.map((ref) => String(ref.chatId)))];
        for (const queuedChatId of chats) await startNextQueuedRaidForChat(queuedChatId).catch(() => false);
      }
    }
    // Recovery path: after a restart or a deleted raid card, a persisted queue may have no live card
    // left to trigger its handoff. Sweep every queued group; active groups are a cheap no-op.
    const queuedState = await readRaidTg();
    for (const queuedChatId of Object.keys(queuedState.queues || {})) await startNextQueuedRaidForChat(queuedChatId).catch(() => false);
  } catch {} finally { _raidTgRefreshing = false; }
}

async function submitSwampScore(body = {}) {
  const mode = String(body.mode || "").toLowerCase();
  if (!["survival", "arena", "catches", "raids", "pvp"].includes(mode)) return { ok: false, error: "bad mode" };
  const score = Math.max(0, Math.min(1e9, Math.round(Number(body.score) || 0)));
  if (!score) return { ok: false, error: "no score" };
  let name = String(body.name || "anon").replace(/[^A-Za-z0-9_$. -]/g, "").slice(0, 16).trim() || "anon";
  const meta = String(body.meta || "").replace(/[^A-Za-z0-9_$.,: -]/g, "").slice(0, 40);
  const clan = String(body.clan || "").replace(/[^A-Za-z0-9 _-]/g, "").slice(0, 12).trim();
  const store = await readSwampLeaderboard();
  // keep one best row per (mode,name): replace if this beats their prior best
  const idx = store.scores.findIndex((s) => s.mode === mode && s.name === name);
  if (idx >= 0) {
    if (clan) store.scores[idx].clan = clan; // keep clan fresh even if score didn't beat
    if (score <= store.scores[idx].score) {
      const rank = store.scores.filter((s) => s.mode === mode && s.score > store.scores[idx].score).length + 1;
      await writeJsonFile(swampLeaderboardPath(), store);
      return { ok: true, improved: false, best: store.scores[idx].score, rank };
    }
    store.scores[idx] = { mode, name, score, meta, clan, at: new Date().toISOString() };
  } else {
    store.scores.push({ mode, name, score, meta, clan, at: new Date().toISOString() });
  }
  // cap stored rows per mode to keep the file small
  const byMode = {};
  for (const s of store.scores) (byMode[s.mode] = byMode[s.mode] || []).push(s);
  store.scores = Object.values(byMode).flatMap((arr) => arr.sort((a, b) => b.score - a.score).slice(0, 200));
  await writeJsonFile(swampLeaderboardPath(), store);
  const rank = store.scores.filter((s) => s.mode === mode && s.score > score).length + 1;
  return { ok: true, improved: true, rank };
}

async function upsertPumpLaunchAttempt(update = {}) {
  if (!update.id && !update.launchAttemptId) return;
  const id = String(update.id || update.launchAttemptId);
  await withFileLock(pumpLaunchAttemptsPath(), async () => {
    const store = await readPumpLaunchAttempts();
    const index = store.attempts.findIndex((attempt) => String(attempt.id || attempt.launchAttemptId) === id);
    const next = {
      ...(index >= 0 ? store.attempts[index] : {}),
      ...update,
      id,
      launchAttemptId: id,
      updatedAt: update.updatedAt || new Date().toISOString()
    };
    if (next.encryptedMintSecret) next.mintSecretStored = true;
    if (index >= 0) {
      store.attempts[index] = next;
    } else {
      store.attempts.push(next);
    }
    await writePumpLaunchAttempts(store);
  });
}

function pumpLaunchAttemptHasSignedOrSubmittedEvidence(attempt = {}) {
  const status = String(attempt.status || "").toUpperCase();
  const stage = String(attempt.stage || "").toLowerCase();
  const signatures = [
    attempt.txSignature,
    attempt.signature,
    attempt.submittedSignature,
    attempt.bundleId,
    attempt.confirmedBundleCandidate?.bundleId,
    ...(Array.isArray(attempt.confirmedBundleCandidate?.signatures) ? attempt.confirmedBundleCandidate.signatures : [])
  ].filter(Boolean);
  return signatures.length > 0
    || (Array.isArray(attempt.bundleCandidates) && attempt.bundleCandidates.length > 0)
    || ["SENDING", "SUBMITTED", "CONFIRMING", "REGISTERING_TOKEN", "COMPLETE", "CONFIRMED", "LAUNCHED", "SUBMITTING"].includes(status)
    || ["send_transaction", "store_result"].includes(stage);
}

function pumpLaunchAttemptRestartDisposition(attempt = {}) {
  if (!attempt || pumpLaunchAttemptHasSignedOrSubmittedEvidence(attempt)) return "preserve";
  const status = String(attempt.status || "").toUpperCase();
  const mint = firstString(attempt.tokenMint, attempt.mintPublicKey, attempt.mint);
  const intentOnly = !status && !mint && !attempt.metadataUri && !attempt.requestBody && !attempt.provider;
  if (intentOnly) return "restart_intent_only";
  if (["", "PENDING", "VALIDATING", "UPLOADING_METADATA", "METADATA_UPLOADED", "BUILDING_TX", "SIGNING"].includes(status)) {
    return "terminal_pre_broadcast";
  }
  return "preserve";
}

async function terminalizePersistedPreBroadcastPumpLaunch(attempt = {}, reason = "") {
  const id = String(attempt.id || attempt.launchAttemptId || "");
  if (!id) return attempt;
  const now = new Date().toISOString();
  const priorStatus = String(attempt.status || "INTENT_ONLY").toUpperCase();
  const postLaunchBuyIntent = attempt.postLaunchBuyIntent
    ? {
        ...attempt.postLaunchBuyIntent,
        status: "LAUNCH_NOT_SUBMITTED",
        entries: (attempt.postLaunchBuyIntent.entries || []).map((entry) => ({
          ...entry,
          status: ["ENTERED", "ENTERED_EXIT_NEEDS_ATTENTION"].includes(entry.status) ? entry.status : "NEEDS_ATTENTION",
          error: reason || "The launch stopped before broadcast; no deferred buy was sent.",
          nextRetryAt: "",
          updatedAt: now
        })),
        updatedAt: now
      }
    : undefined;
  await upsertPumpLaunchAttempt({
    id,
    status: "FAILED_PRE_BROADCAST_RESTART",
    stage: "pre_broadcast_restart",
    previousStatus: priorStatus,
    failureReason: reason || "The server restarted before this launch was broadcast. Nothing was sent; start a fresh launch.",
    errorCode: "PUMP_LAUNCH_PRE_BROADCAST_RESTART",
    failedAt: now,
    ...(postLaunchBuyIntent ? { postLaunchBuyIntent } : {})
  });
  return { ...attempt, status: "FAILED_PRE_BROADCAST_RESTART", stage: "pre_broadcast_restart", previousStatus: priorStatus, failureReason: reason, errorCode: "PUMP_LAUNCH_PRE_BROADCAST_RESTART", failedAt: now, ...(postLaunchBuyIntent ? { postLaunchBuyIntent } : {}) };
}

function linkedNftCollectionPublicResult(attempt = {}, override = {}) {
  const address = firstString(override.address, attempt.nftCollectionAddress);
  const status = String(override.status || attempt.nftCollectionStatus || (address ? "COMPLETE" : "")).toUpperCase();
  if (!status && !attempt.nftCollectionSpec?.enabled) return null;
  return {
    enabled: Boolean(attempt.nftCollectionSpec?.enabled),
    status: status || "PENDING",
    address,
    name: firstString(override.name, attempt.nftCollectionSpec?.name),
    standard: "metaplex-core",
    supplyMode: attempt.nftCollectionSpec?.supplyMode || "expandable",
    supplyCap: Number(attempt.nftCollectionSpec?.supplyCap || 500),
    royaltyBps: Number(attempt.nftCollectionSpec?.royaltyBps || 0),
    metadataUri: firstString(override.metadataUri, attempt.nftCollectionMetadataUri),
    signature: firstString(override.signature, attempt.nftCollectionSignature),
    explorerUrl: address ? `https://solscan.io/account/${address}` : "",
    error: firstString(override.error, attempt.nftCollectionError).slice(0, 220)
  };
}

async function attachLinkedNftCollectionToLaunch(userId, basePayload = {}, launchResult = {}) {
  const tokenMint = firstString(launchResult.tokenMint, launchResult.mint);
  const spec = normalizeLinkedNftCollection(basePayload.nftCollection, basePayload);
  if (!spec.enabled || !tokenMint || String(launchResult.status || "").toUpperCase() !== "COMPLETE") {
    return launchResult;
  }
  const attemptId = firstString(basePayload.clientRequestId, launchResult.launchAttemptId, launchResult.requestId);
  let attempt = (await readPumpLaunchAttempts().catch(() => ({ attempts: [] }))).attempts
    ?.find((row) => String(row.id || row.launchAttemptId) === String(attemptId)) || {};
  if (attempt.nftCollectionAddress) {
    const account = await connection.getAccountInfo(new PublicKey(attempt.nftCollectionAddress), "confirmed").catch(() => null);
    if (account) {
      await upsertPumpLaunchAttempt({ id: attemptId, nftCollectionStatus: "COMPLETE", nftCollectionError: "" });
      return { ...launchResult, nftCollection: linkedNftCollectionPublicResult(attempt, { status: "COMPLETE" }) };
    }
  }

  try {
    const store = await readWalletStore();
    const selected = selectPumpLaunchWallet(store, userId, firstString(
      basePayload.devBuy?.walletIndex,
      attempt.selectedDevWalletId,
      attempt.devWalletPublicKey
    ));
    const authorityKeypair = decryptWallet(selected.wallet);
    const externalUrl = `${CONFIG.cashPublicOrigin || "https://www.slimewire.org"}/fun?ca=${encodeURIComponent(tokenMint)}`;

    let metadataUri = firstString(attempt.nftCollectionMetadataUri, attempt.metadataUri);
    let imageUri = firstString(attempt.imageUri, attempt.metadataJson?.image, launchResult.imageUri);
    if (!metadataUri) {
      // Use the already-proven launch upload path so creators do not need another
      // storage account. Pinata, when configured, adds the explicit mint attribute;
      // the pump.fun IPFS fallback still has the on-chain collection + durable app link.
      const fallback = await uploadPumpLaunchMetadata({
        ...basePayload,
        name: spec.name,
        symbol: `${basePayload.symbol || "NFT"}`.slice(0, 10),
        description: `${spec.description}\n\nOfficial collection for ${tokenMint}`.slice(0, 800),
        website: externalUrl,
        twitter: basePayload.twitter || "",
        telegram: basePayload.telegram || "",
        bannerDataUrl: ""
      });
      metadataUri = fallback.uri;
      imageUri = firstString(fallback.imageUri, imageUri);
      try {
        const pinataConfig = assertPinataConfigured({
          tokenValue: CONFIG.pumpLaunchPinataJwt,
          metadataUrl: CONFIG.pumpLaunchMetadataUrl
        });
        const metadata = linkedCollectionMetadata({
          collection: spec,
          coin: basePayload,
          tokenMint,
          imageUri,
          externalUrl
        });
        const upload = await uploadJsonMetadata({
          metadata,
          filename: `${cleanTickerSymbol(basePayload.symbol || "coin").toLowerCase() || "coin"}-nft-collection.json`,
          tokenValue: CONFIG.pumpLaunchPinataJwt,
          metadataUrl: pinataConfig.metadataUrl,
          timeoutMs: CONFIG.pumpLaunchTimeoutMs
        });
        if (upload?.uri) metadataUri = upload.uri;
      } catch (error) {
        console.warn(`[linked-nft] explicit metadata fallback used: ${friendlyError(error)}`);
      }
      await upsertPumpLaunchAttempt({
        id: attemptId,
        nftCollectionSpec: spec,
        nftCollectionStatus: "CREATING",
        nftCollectionMetadataUri: metadataUri,
        nftCollectionImageUri: imageUri,
        nftCollectionError: ""
      });
    }

    attempt = (await readPumpLaunchAttempts()).attempts
      .find((row) => String(row.id || row.launchAttemptId) === String(attemptId)) || attempt;
    const storedSecret = attempt.encryptedNftCollectionSecret
      ? decryptSecretBuffer(attempt.encryptedNftCollectionSecret)
      : null;
    const created = await createMetaplexCoreCollection({
      rpcUrl: CONFIG.rpcUrl,
      authorityKeypair,
      name: spec.name,
      uri: metadataUri,
      supplyMode: spec.supplyMode,
      supplyCap: spec.supplyCap,
      royaltyBps: spec.royaltyBps,
      signerSecretKey: storedSecret,
      onSigner: async ({ address, secretKey }) => {
        await upsertPumpLaunchAttempt({
          id: attemptId,
          nftCollectionSpec: spec,
          nftCollectionStatus: "CREATING",
          nftCollectionAddress: address,
          nftCollectionMetadataUri: metadataUri,
          encryptedNftCollectionSecret: encryptSecret(Buffer.from(secretKey)),
          nftCollectionSecretStored: true,
          nftCollectionError: ""
        });
      }
    });
    const signature = created.signatureBytes?.length ? bs58.encode(created.signatureBytes) : "";
    await upsertPumpLaunchAttempt({
      id: attemptId,
      nftCollectionSpec: spec,
      nftCollectionStatus: "COMPLETE",
      nftCollectionAddress: created.address,
      nftCollectionSignature: signature,
      nftCollectionMetadataUri: metadataUri,
      nftCollectionError: "",
      nftCollectionCreatedAt: new Date().toISOString()
    });
    return {
      ...launchResult,
      nftCollection: linkedNftCollectionPublicResult({ nftCollectionSpec: spec }, {
        status: "COMPLETE", address: created.address, signature, metadataUri, name: spec.name
      })
    };
  } catch (error) {
    const message = `Coin launched, but its NFT collection needs a retry: ${friendlyError(error)}`.slice(0, 400);
    await upsertPumpLaunchAttempt({
      id: attemptId,
      nftCollectionSpec: spec,
      nftCollectionStatus: "FAILED",
      nftCollectionError: message,
      nftCollectionFailedAt: new Date().toISOString()
    }).catch(() => {});
    console.warn(`[linked-nft] ${attemptId} ${message}`);
    return {
      ...launchResult,
      nftCollection: linkedNftCollectionPublicResult({ nftCollectionSpec: spec }, {
        status: "FAILED", address: attempt.nftCollectionAddress || "", name: spec.name, error: message
      })
    };
  }
}

async function webRetryLinkedNftCollection(userId, body = {}) {
  const store = await readPumpLaunchAttempts();
  const requestedId = firstString(body.launchAttemptId, body.id);
  const requestedMint = firstString(body.tokenMint, body.mint);
  const attempt = (store.attempts || []).find((row) =>
    String(row.userId || "") === String(userId)
    && ((requestedId && String(row.id || row.launchAttemptId) === requestedId)
      || (requestedMint && firstString(row.tokenMint, row.mintPublicKey, row.mint) === requestedMint))
  );
  if (!attempt) {
    const error = new Error("That launch was not found for this account.");
    error.statusCode = 404;
    throw error;
  }
  if (!attempt.nftCollectionSpec?.enabled) {
    const error = new Error("This launch does not have the linked NFT collection option enabled.");
    error.statusCode = 400;
    throw error;
  }
  const tokenMint = firstString(attempt.tokenMint, attempt.mintPublicKey, attempt.mint);
  if (!tokenMint) {
    const error = new Error("The coin CA is not confirmed yet, so its collection cannot be created.");
    error.statusCode = 409;
    throw error;
  }
  const basePayload = {
    clientRequestId: String(attempt.id || attempt.launchAttemptId),
    name: firstString(attempt.tokenName, attempt.name, "SlimeWire Meme"),
    symbol: firstString(attempt.symbol, "NFT"),
    description: firstString(attempt.description),
    website: firstString(attempt.website),
    twitter: firstString(attempt.x, attempt.twitter),
    telegram: firstString(attempt.telegram),
    nftCollection: attempt.nftCollectionSpec,
    devBuy: { walletIndex: firstString(attempt.selectedDevWalletId, attempt.devWalletPublicKey) }
  };
  return attachLinkedNftCollectionToLaunch(userId, basePayload, {
    status: "COMPLETE",
    tokenMint,
    launchAttemptId: basePayload.clientRequestId
  });
}

function normalizeNftLoyaltyStore(store = {}) {
  return {
    items: Array.isArray(store.items) ? store.items : [],
    campaigns: Array.isArray(store.campaigns) ? store.campaigns : [],
    generationJobs: Array.isArray(store.generationJobs) ? store.generationJobs : [],
    ownership: store.ownership && typeof store.ownership === "object" ? store.ownership : {}
  };
}

async function readNftLoyaltyStore() {
  return normalizeNftLoyaltyStore(await readJson(nftLoyaltyPath()).catch(() => ({})));
}

async function mutateNftLoyaltyStore(mutator) {
  let result;
  await withFileLock(nftLoyaltyPath(), async () => {
    const store = await readNftLoyaltyStore();
    result = await mutator(store);
    store.items = store.items.slice(-2_000);
    store.campaigns = store.campaigns.slice(-1_000);
    store.generationJobs = store.generationJobs.slice(-500);
    await writeJsonFile(nftLoyaltyPath(), store);
  });
  return result;
}

function launchMint(attempt = {}) {
  return firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint);
}

async function nftLaunchForUser(userId, tokenMint) {
  const mint = parsePublicKey(String(tokenMint || "")).toBase58();
  const store = await readPumpLaunchAttempts();
  const attempt = (store.attempts || []).slice().reverse().find((row) => (
    String(row.userId || "") === String(userId) && launchMint(row) === mint
  ));
  if (!attempt) {
    const error = new Error("That launched coin was not found for this account.");
    error.statusCode = 404;
    throw error;
  }
  if (String(attempt.rail || "pump").toLowerCase() === "robinhood") {
    const error = new Error("NFT collection minting is currently available for Solana launches.");
    error.statusCode = 400;
    throw error;
  }
  return { attempt, mint };
}

async function webCreateLaterNftCollection(userId, body = {}) {
  const { attempt, mint } = await nftLaunchForUser(userId, body.tokenMint || body.mint);
  const spec = normalizeLinkedNftCollection({
    enabled: true,
    name: body.name,
    description: body.description,
    useCoinArt: true,
    supplyMode: body.supplyMode,
    supplyCap: body.supplyCap,
    royaltyBps: body.royaltyBps
  }, { name: firstString(attempt.tokenName, attempt.name), symbol: attempt.symbol });
  await upsertPumpLaunchAttempt({
    id: String(attempt.id || attempt.launchAttemptId),
    nftCollectionSpec: spec,
    nftCollectionStatus: attempt.nftCollectionAddress ? "COMPLETE" : "PENDING",
    nftCollectionError: ""
  });
  const launch = await webRetryLinkedNftCollection(userId, { tokenMint: mint });
  return { ok: true, launch };
}

async function webLinkExistingNftCollection(userId, body = {}) {
  const { attempt, mint } = await nftLaunchForUser(userId, body.tokenMint || body.mint);
  const address = parsePublicKey(String(body.collectionAddress || body.address || "")).toBase58();
  const walletStore = await readWalletStore();
  const devWallet = walletsForOwner(walletStore, userId).find((wallet) => wallet.publicKey === attempt.devWalletPublicKey);
  if (!devWallet) throw new Error("The launch creator wallet is not available in this account.");
  const collection = await fetchMetaplexCoreCollection({ rpcUrl: CONFIG.rpcUrl, address });
  if (collection.updateAuthority !== devWallet.publicKey) {
    const error = new Error("That collection is not controlled by this coin's creator wallet.");
    error.statusCode = 403;
    throw error;
  }
  const spec = normalizeLinkedNftCollection({
    enabled: true,
    name: body.name || collection.name,
    description: body.description || `Official NFT collection linked to $${attempt.symbol || "this coin"} on SlimeWire.`,
    useCoinArt: false,
    supplyMode: body.supplyMode || (collection.maxSupply > 0 ? "fixed" : "expandable"),
    supplyCap: body.supplyCap || collection.maxSupply || 500,
    royaltyBps: body.royaltyBps ?? collection.royaltyBps
  }, { name: firstString(attempt.tokenName, attempt.name), symbol: attempt.symbol });
  await upsertPumpLaunchAttempt({
    id: String(attempt.id || attempt.launchAttemptId),
    nftCollectionSpec: spec,
    nftCollectionStatus: "COMPLETE",
    nftCollectionAddress: address,
    nftCollectionMetadataUri: collection.uri,
    nftCollectionLinkedExisting: true,
    nftCollectionError: ""
  });
  return { ok: true, collection: linkedNftCollectionPublicResult({ nftCollectionSpec: spec, nftCollectionStatus: "COMPLETE", nftCollectionAddress: address, nftCollectionMetadataUri: collection.uri }) };
}

function nftItemPublic(row = {}) {
  return {
    id: row.id,
    tokenMint: row.tokenMint,
    collectionAddress: row.collectionAddress,
    address: row.address || "",
    name: row.name || "",
    description: row.description || "",
    rarity: row.rarity || "common",
    editionNumber: Number(row.editionNumber || 0),
    recipient: row.recipient || "",
    imageUri: row.imageUri || "",
    metadataUri: row.metadataUri || "",
    status: row.status || "",
    signature: row.signature || "",
    generatedArt: Boolean(row.generatedArt),
    artStyle: row.artStyle || "",
    artProvider: row.artProvider || "",
    generatorFeeSol: Number(row.generatorFeeSol || 0),
    generatorFeeSignature: row.generatorFeeSignature || "",
    mintedAt: row.mintedAt || "",
    explorerUrl: row.address ? `https://solscan.io/account/${encodeURIComponent(row.address)}` : ""
  };
}

function nftGeneratorStyle(value) {
  const style = String(value || "slime-degen").trim().toLowerCase();
  return ["slime-degen", "premium-3d", "pixel-degen", "dark-ogre", "comic", "cyber"].includes(style)
    ? style
    : "slime-degen";
}

function nftGeneratorStyleDirection(style) {
  return {
    "slime-degen": "premium glossy slime degen PFP, bold silhouette, tactile ooze, collector-grade finish",
    "premium-3d": "high-end cinematic 3D collectible character, studio lighting, rich materials, crisp PFP composition",
    "pixel-degen": "hand-authored premium pixel-art degen avatar, limited palette, sharp readable traits, no blur",
    "dark-ogre": "dark swamp ogre collectible, neon slime accents, dramatic rim light, detailed fantasy streetwear",
    comic: "premium graphic-novel collectible portrait, confident ink work, screen-print texture, bold color blocking",
    cyber: "cyber-slime collectible avatar, holographic materials, neon circuitry, futuristic fashion, premium render"
  }[style] || "premium slime collectible avatar";
}

function nftStudioUsdSetting(name, fallback, minimum, maximum) {
  const value = Number(process.env[name] || fallback);
  return clamp(Number.isFinite(value) ? value : fallback, minimum, maximum);
}

function nftStudioConfig() {
  const live = parseBoolean(process.env.NFT_STUDIO_ENABLED || "false");
  return {
    enabled: live && scenarioNftConfigured(),
    comingSoon: !live,
    provider: "Scenario",
    modelId: live && scenarioNftConfigured() ? scenarioNftModelId() : "",
    previewCount: 4,
    maxItems: 100,
    previewUsdEach: nftStudioUsdSetting("NFT_STUDIO_PREVIEW_USD_EACH", 0.06, 0.01, 5),
    itemUsdEach: nftStudioUsdSetting("NFT_STUDIO_ITEM_USD_EACH", 0.10, 0.01, 10),
    platformFeeBps: Math.round(nftStudioUsdSetting("NFT_STUDIO_PLATFORM_FEE_BPS", 1200, 0, 5000)),
    reserveBufferBps: Math.round(nftStudioUsdSetting("NFT_STUDIO_RESERVE_BUFFER_BPS", 1000, 0, 5000))
  };
}

function nftStudioStyles() {
  return [
    { id: "slime-degen", label: "Slime Degen" },
    { id: "premium-3d", label: "Premium 3D" },
    { id: "pixel-degen", label: "Pixel Degen" },
    { id: "dark-ogre", label: "Dark Ogre" },
    { id: "comic", label: "Comic" },
    { id: "cyber", label: "Cyber" }
  ];
}

async function nftStudioQuote(body = {}) {
  const config = nftStudioConfig();
  if (!config.enabled) {
    const error = new Error("AI NFT generation is coming soon. Upload and mint your own artwork for now.");
    error.statusCode = 503;
    throw error;
  }
  const quantity = Math.max(1, Math.min(config.maxItems, Math.floor(Number(body.quantity || 1) || 1)));
  const solUsd = await getSolUsdPrice({ timeoutMs: 2_500 }).catch(() => 0);
  if (!(solUsd > 0)) {
    const error = new Error("SOL/USD price is temporarily unavailable. Try the quote again in a moment.");
    error.statusCode = 503;
    throw error;
  }
  const toLamports = (usd) => Math.max(1, Math.ceil((usd / solUsd) * LAMPORTS_PER_SOL));
  const previewUnitLamports = toLamports(config.previewUsdEach);
  const itemUnitLamports = toLamports(config.itemUsdEach);
  const apiExpenseLamports = previewUnitLamports * config.previewCount + itemUnitLamports * quantity;
  const platformFeeLamports = Math.ceil((apiExpenseLamports * config.platformFeeBps) / 10_000);
  const bufferLamports = Math.ceil((apiExpenseLamports * config.reserveBufferBps) / 10_000);
  const settlementNetworkLamports = 15_000;
  const totalLamports = apiExpenseLamports + platformFeeLamports + bufferLamports + settlementNetworkLamports;
  return {
    asset: "SOL",
    quantity,
    previewCount: config.previewCount,
    previewUnitLamports,
    itemUnitLamports,
    apiExpenseLamports,
    platformFeeBps: config.platformFeeBps,
    platformFeeLamports,
    platformFeeSol: Number((platformFeeLamports / LAMPORTS_PER_SOL).toFixed(6)),
    platformFeeUsd: Number((platformFeeLamports / LAMPORTS_PER_SOL * solUsd).toFixed(2)),
    bufferLamports,
    settlementNetworkLamports,
    totalLamports,
    totalSol: Number((totalLamports / LAMPORTS_PER_SOL).toFixed(6)),
    estimatedUsd: Number((totalLamports / LAMPORTS_PER_SOL * solUsd).toFixed(2)),
    solUsd: Number(solUsd.toFixed(4)),
    validUntil: new Date(Date.now() + 10 * 60_000).toISOString()
  };
}

function signNftStudioQuote(userId, tokenMint, quote) {
  const payload = Buffer.from(JSON.stringify({
    userId: String(userId), tokenMint: String(tokenMint),
    quantity: quote.quantity, previewCount: quote.previewCount,
    previewUnitLamports: quote.previewUnitLamports, itemUnitLamports: quote.itemUnitLamports,
    apiExpenseLamports: quote.apiExpenseLamports, platformFeeBps: quote.platformFeeBps,
    platformFeeLamports: quote.platformFeeLamports, bufferLamports: quote.bufferLamports,
    settlementNetworkLamports: quote.settlementNetworkLamports, totalLamports: quote.totalLamports,
    solUsd: quote.solUsd, validUntil: quote.validUntil
  })).toString("base64url");
  const signature = crypto.createHmac("sha256", CONFIG.appSecret).update(payload).digest("base64url");
  return `${payload}.${signature}`;
}

function verifyNftStudioQuote(userId, tokenMint, token) {
  const [payload, suppliedSignature, ...extra] = String(token || "").split(".");
  if (!payload || !suppliedSignature || extra.length) throw Object.assign(new Error("Get a fresh Studio quote before funding."), { statusCode: 409 });
  const expected = crypto.createHmac("sha256", CONFIG.appSecret).update(payload).digest("base64url");
  const suppliedBuffer = Buffer.from(suppliedSignature);
  const expectedBuffer = Buffer.from(expected);
  if (suppliedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(suppliedBuffer, expectedBuffer)) throw Object.assign(new Error("That Studio quote is invalid. Refresh it before funding."), { statusCode: 409 });
  let parsed;
  try { parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8")); } catch { throw Object.assign(new Error("That Studio quote is invalid. Refresh it before funding."), { statusCode: 409 }); }
  if (String(parsed.userId) !== String(userId) || String(parsed.tokenMint) !== String(tokenMint)) throw Object.assign(new Error("That Studio quote belongs to a different account or collection."), { statusCode: 403 });
  if (Date.parse(parsed.validUntil || "") <= Date.now()) throw Object.assign(new Error("That Studio quote expired. Refresh it before funding."), { statusCode: 409 });
  const integerFields = ["quantity", "previewCount", "previewUnitLamports", "itemUnitLamports", "apiExpenseLamports", "platformFeeBps", "platformFeeLamports", "bufferLamports", "settlementNetworkLamports", "totalLamports"];
  if (integerFields.some((field) => !Number.isSafeInteger(Number(parsed[field])) || Number(parsed[field]) < 0)) throw Object.assign(new Error("That Studio quote is malformed. Refresh it before funding."), { statusCode: 409 });
  return {
    ...parsed,
    asset: "SOL",
    totalSol: Number((Number(parsed.totalLamports) / LAMPORTS_PER_SOL).toFixed(6))
  };
}

function nftStudioJobPublic(row = {}) {
  const quotedLamports = Number(row.quotedLamports || 0);
  const apiExpenseLamports = Number(row.consumedLamports || 0);
  const platformFeeBps = Number(row.platformFeeBps || 1200);
  const platformFeeLamports = Number(row.platformFeeChargedLamports ?? Math.ceil((apiExpenseLamports * platformFeeBps) / 10_000));
  const chargedLamports = Number(row.chargedLamports ?? (apiExpenseLamports + platformFeeLamports));
  const staleProcessing = Date.now() - Date.parse(row.updatedAt || 0) >= 5 * 60_000;
  return {
    id: row.id,
    tokenMint: row.tokenMint,
    collectionAddress: row.collectionAddress,
    status: row.status || "",
    quantity: Number(row.quantity || 0),
    generatedCount: Number(row.generatedCount || 0),
    mintedCount: Array.isArray(row.mintedItemIds) ? row.mintedItemIds.length : 0,
    nameBase: row.nameBase || "",
    rarity: row.rarity || "common",
    recipient: row.recipient || "",
    artStyle: row.artStyle || "slime-degen",
    artPrompt: row.artPrompt || "",
    provider: row.provider || "Scenario",
    providerModelId: row.providerModelId || "",
    vaultPublicKey: row.vaultPublicKey || "",
    fundingSignature: row.fundingSignature || "",
    settlementSignature: row.settlementSignature || "",
    quotedSol: Number((quotedLamports / LAMPORTS_PER_SOL).toFixed(6)),
    consumedSol: Number((chargedLamports / LAMPORTS_PER_SOL).toFixed(6)),
    refundableSol: Number(((row.refundLamports != null
      ? Math.max(0, Number(row.refundLamports))
      : Math.max(0, quotedLamports - chargedLamports - Number(row.settlementNetworkLamports || 0))) / LAMPORTS_PER_SOL).toFixed(6)),
    previews: (Array.isArray(row.previews) ? row.previews : []).map((preview, index) => ({
      index,
      imageUri: preview.imageUri || "",
      providerAssetId: preview.providerAssetId || ""
    })),
    selectedPreview: Number.isInteger(row.selectedPreview) ? row.selectedPreview : null,
    pendingImageUri: row.pendingGenerated?.imageUri || "",
    error: row.error || "",
    createdAt: row.createdAt || "",
    updatedAt: row.updatedAt || "",
    completedAt: row.completedAt || "",
    canceledAt: row.canceledAt || "",
    canGeneratePreviews: ["FUNDED", "PREVIEW_FAILED"].includes(String(row.status || "")) || (String(row.status || "") === "PREVIEWING" && staleProcessing),
    canApprove: String(row.status || "") === "AWAITING_APPROVAL",
    canBuild: ["READY_TO_BUILD", "BUILD_FAILED"].includes(String(row.status || "")) || (String(row.status || "") === "GENERATING" && staleProcessing),
    canCancel: !["COMPLETE", "CANCELLED", "SETTLED"].includes(String(row.status || ""))
  };
}

async function generatedNftReferenceDataUrl(attempt, suppliedDataUrl = "") {
  if (decodePfpImageDataUrl(suppliedDataUrl)) return suppliedDataUrl;
  for (const candidate of [attempt.nftCollectionImageUri, attempt.imageUri, attempt.metadataJson?.image]) {
    if (!candidate) continue;
    const image = await launchOsTrustedTokenImageBuffer(candidate).catch(() => null);
    if (!image) continue;
    const png = await sharp(image).rotate().resize(1024, 1024, {
      fit: "cover", position: "attention"
    }).png().toBuffer();
    return `data:image/png;base64,${png.toString("base64")}`;
  }
  throw new Error("Upload collection reference art before generating NFT artwork.");
}

async function webMintLinkedNftItem(userId, body = {}) {
  const requestId = firstString(body.clientRequestId, body.mintAttemptId) || crypto.randomUUID();
  return runIdempotentMoneyOp("web-nft-item-mint", userId, requestId, async () => {
    const { attempt, mint } = await nftLaunchForUser(userId, body.tokenMint || body.mint);
    const collectionAddress = firstString(attempt.nftCollectionAddress);
    if (!collectionAddress || String(attempt.nftCollectionStatus || "").toUpperCase() !== "COMPLETE") {
      const error = new Error("Create or link the NFT collection before minting items.");
      error.statusCode = 409;
      throw error;
    }
    const walletStore = await readWalletStore();
    const creatorWallet = walletsForOwner(walletStore, userId).find((wallet) => wallet.publicKey === attempt.devWalletPublicKey);
    if (!creatorWallet) throw new Error("The collection creator wallet is not available.");
    const authorityKeypair = decryptWallet(creatorWallet);
    const collection = await fetchMetaplexCoreCollection({ rpcUrl: CONFIG.rpcUrl, address: collectionAddress });
    if (collection.updateAuthority !== creatorWallet.publicKey) throw new Error("The creator wallet no longer controls this collection.");
    const collectionSpec = normalizeLinkedNftCollection(attempt.nftCollectionSpec || { enabled: true }, {
      name: firstString(attempt.tokenName, attempt.name), symbol: attempt.symbol
    });
    const item = normalizeNftItem(body, {
      name: `${firstString(attempt.symbol, "SLIME")} NFT`,
      recipient: creatorWallet.publicKey
    });
    if (parseBoolean(body.generateArt || "false")) {
      const error = new Error("AI NFT generation is coming soon. Upload and mint your own artwork for now.");
      error.statusCode = 409;
      throw error;
    }
    if (!decodePfpImageDataUrl(item.imageDataUrl)) {
      const error = new Error("Upload artwork for this NFT before minting.");
      error.statusCode = 400;
      throw error;
    }
    const recipient = parsePublicKey(item.recipient || creatorWallet.publicKey).toBase58();
    let loyalty = await readNftLoyaltyStore();
    let row = loyalty.items.find((entry) => entry.id === requestId && String(entry.userId) === String(userId));
    if (row?.address && await connection.getAccountInfo(new PublicKey(row.address), "confirmed").catch(() => null)) {
      return { ok: true, item: nftItemPublic({ ...row, status: "COMPLETE" }) };
    }
    const collectionRows = loyalty.items.filter((entry) => entry.collectionAddress === collectionAddress && ["MINTING", "COMPLETE"].includes(String(entry.status || "").toUpperCase()));
    const mintedCount = Math.max(Number(collection.numMinted || 0), Number(collection.currentSize || 0), collectionRows.length);
    if (mintedCount >= Number(collectionSpec.supplyCap || 500)) {
      const error = new Error(`${collectionSpec.supplyMode === "fixed" ? "Fixed" : "SlimeWire"} collection supply cap reached (${collectionSpec.supplyCap}).`);
      error.statusCode = 409;
      throw error;
    }
    const editionNumber = Math.max(
      Number(collection.numMinted || 0),
      ...collectionRows.map((entry) => Number(entry.editionNumber || 0))
    ) + 1;

    const externalUrl = `${CONFIG.cashPublicOrigin || "https://www.slimewire.org"}/fun?ca=${encodeURIComponent(mint)}`;
    const fallback = await uploadPumpLaunchMetadata({
      name: item.name,
      symbol: String(attempt.symbol || "NFT").slice(0, 10),
      description: `${item.description || `Official ${item.rarity} NFT.`}\n\nLinked coin: ${mint}\nRarity: ${item.rarity}`.slice(0, 800),
      website: externalUrl,
      imageDataUrl: item.imageDataUrl,
      imageName: item.imageName,
      bannerDataUrl: ""
    });
    let metadataUri = fallback.uri;
    const imageUri = firstString(fallback.imageUri, attempt.nftCollectionImageUri, attempt.imageUri);
    try {
      const pinataConfig = assertPinataConfigured({ tokenValue: CONFIG.pumpLaunchPinataJwt, metadataUrl: CONFIG.pumpLaunchMetadataUrl });
      const uploaded = await uploadJsonMetadata({
        metadata: {
          name: item.name,
          symbol: String(attempt.symbol || "NFT").slice(0, 10),
          description: item.description || `Official ${item.rarity} NFT linked to ${mint}.`,
          image: imageUri,
          external_url: externalUrl,
          attributes: [
            { trait_type: "Rarity", value: item.rarity },
            { trait_type: "Edition", value: editionNumber },
            { trait_type: "Linked Coin", value: mint },
            { trait_type: "Collection", value: collectionAddress },
            ...(body._studioJobId ? [
              { trait_type: "Art Style", value: nftGeneratorStyle(body._studioArtStyle) },
              { trait_type: "Generated By", value: "SlimeWire Funded Collection Studio" }
            ] : [])
          ],
          properties: { category: "image", linked_token_mint: mint, rarity: item.rarity, edition_number: editionNumber }
        },
        filename: `${cleanTickerSymbol(attempt.symbol || "nft").toLowerCase() || "nft"}-${requestId.slice(0, 8)}.json`,
        tokenValue: CONFIG.pumpLaunchPinataJwt,
        metadataUrl: pinataConfig.metadataUrl,
        timeoutMs: CONFIG.pumpLaunchTimeoutMs
      });
      if (uploaded?.uri) metadataUri = uploaded.uri;
    } catch (error) {
      console.warn(`[linked-nft] item metadata fallback used: ${friendlyError(error)}`);
    }
    row = {
      ...(row || {}), id: requestId, userId: String(userId), tokenMint: mint, collectionAddress,
      name: item.name, description: item.description, rarity: item.rarity, recipient, imageUri, metadataUri,
      generatedArt: Boolean(body._studioJobId), artStyle: body._studioJobId ? nftGeneratorStyle(body._studioArtStyle) : "",
      artProvider: body._studioJobId ? "Scenario" : "", studioJobId: firstString(body._studioJobId),
      editionNumber,
      status: "MINTING", createdAt: row?.createdAt || new Date().toISOString()
    };
    await mutateNftLoyaltyStore((store) => {
      const index = store.items.findIndex((entry) => entry.id === requestId && String(entry.userId) === String(userId));
      if (index >= 0) store.items[index] = { ...store.items[index], ...row };
      else store.items.push(row);
    });
    loyalty = await readNftLoyaltyStore();
    row = loyalty.items.find((entry) => entry.id === requestId && String(entry.userId) === String(userId)) || row;
    const storedSecret = row.encryptedAssetSecret ? decryptSecretBuffer(row.encryptedAssetSecret) : null;
    const created = await createMetaplexCoreAsset({
      rpcUrl: CONFIG.rpcUrl,
      authorityKeypair,
      collectionAddress,
      recipient,
      name: item.name,
      uri: metadataUri,
      editionNumber,
      signerSecretKey: storedSecret,
      onSigner: async ({ address, secretKey }) => mutateNftLoyaltyStore((store) => {
        const index = store.items.findIndex((entry) => entry.id === requestId && String(entry.userId) === String(userId));
        if (index >= 0) store.items[index] = { ...store.items[index], address, encryptedAssetSecret: encryptSecret(Buffer.from(secretKey)), status: "MINTING" };
      })
    });
    const signature = created.signatureBytes?.length ? bs58.encode(created.signatureBytes) : "";
    const completed = { ...row, address: created.address, signature, status: "COMPLETE", mintedAt: new Date().toISOString() };
    await mutateNftLoyaltyStore((store) => {
      const index = store.items.findIndex((entry) => entry.id === requestId && String(entry.userId) === String(userId));
      store.items[index] = { ...store.items[index], ...completed };
      if (!store.ownership[collectionAddress]) store.ownership[collectionAddress] = {};
      store.ownership[collectionAddress][created.address] = { asset: created.address, owner: recipient, ownerSince: Date.now(), lastCheckedAt: Date.now() };
    });
    await audit("web_nft_item_minted", { userId, tokenMint: mint, collectionAddress, asset: created.address, recipient, rarity: item.rarity, signature });
    return { ok: true, item: nftItemPublic(completed) };
  }, { lockMs: 180_000, busyMessage: "This NFT item is already being minted." });
}

function nftStudioFinalStatus(status) {
  return ["COMPLETE", "CANCELLED"].includes(String(status || "").toUpperCase());
}

async function nftStudioJobForUser(userId, jobId) {
  const loyalty = await readNftLoyaltyStore();
  const job = loyalty.generationJobs.find((row) => row.id === String(jobId || "") && String(row.userId) === String(userId));
  if (!job) {
    const error = new Error("That Collection Studio job was not found.");
    error.statusCode = 404;
    throw error;
  }
  return job;
}

async function updateNftStudioJob(userId, jobId, updater) {
  let updated = null;
  await mutateNftLoyaltyStore((store) => {
    const index = store.generationJobs.findIndex((row) => row.id === String(jobId) && String(row.userId) === String(userId));
    if (index < 0) return;
    const result = updater(store.generationJobs[index]) || store.generationJobs[index];
    updated = { ...result, updatedAt: new Date().toISOString() };
    store.generationJobs[index] = updated;
  });
  if (!updated) throw Object.assign(new Error("That Collection Studio job was not found."), { statusCode: 404 });
  return updated;
}

async function nftStudioReferenceDataUrl(uri) {
  const buffer = await launchOsTrustedTokenImageBuffer(uri);
  const png = await sharp(buffer).rotate().resize(1024, 1024, { fit: "cover", position: "attention" }).png().toBuffer();
  return `data:image/png;base64,${png.toString("base64")}`;
}

async function persistNftStudioImage(attempt, jobId, label, buffer) {
  const png = await sharp(buffer).rotate().resize(1024, 1024, { fit: "cover", position: "attention" }).png().toBuffer();
  const uploaded = await uploadPumpLaunchMetadata({
    name: `${firstString(attempt.symbol, "NFT")} ${label}`,
    symbol: String(attempt.symbol || "NFT").slice(0, 10),
    description: `SlimeWire funded Collection Studio artwork for ${launchMint(attempt)}.`,
    website: `${CONFIG.cashPublicOrigin || "https://www.slimewire.org"}/fun?ca=${encodeURIComponent(launchMint(attempt))}`,
    imageDataUrl: `data:image/png;base64,${png.toString("base64")}`,
    imageName: `${cleanTickerSymbol(attempt.symbol || "nft").toLowerCase()}-${jobId.slice(0, 8)}-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}.png`,
    bannerDataUrl: ""
  });
  const imageUri = firstString(uploaded.imageUri);
  if (!imageUri) throw new Error("The generated image could not be stored permanently.");
  return { imageUri, dataUrl: `data:image/png;base64,${png.toString("base64")}` };
}

function nftStudioPrompt(job, attempt, kind, ordinal = 0) {
  const identity = `${firstString(attempt.tokenName, attempt.name, attempt.symbol, "meme coin")} (${firstString(attempt.symbol, "NFT")})`;
  const base = [
    `Create a ${nftGeneratorStyleDirection(job.artStyle)} for the official ${identity} NFT collection.`,
    "Keep the same recognizable character identity, facial structure, palette and collection-level art direction as the supplied reference.",
    "Centered square avatar, polished commercial NFT quality, clean silhouette, intentional traits, no text, no ticker, no watermark, no frame.",
    job.artPrompt
  ];
  if (kind === "preview") base.push(`This is art-direction preview ${ordinal + 1} of 4. Explore a distinct pose, outfit and setting.`);
  else base.push(`This is final collection item ${ordinal + 1} of ${job.quantity}. Make its pose, expression, wardrobe, background and traits visibly unique without drifting from the approved collection identity. Rarity: ${job.rarity}.`);
  return base.filter(Boolean).join(" ").slice(0, 1800);
}

async function webNftStudioQuote(userId, body = {}) {
  const { attempt, mint } = await nftLaunchForUser(userId, body.tokenMint || body.mint);
  if (!attempt.nftCollectionAddress || String(attempt.nftCollectionStatus || "").toUpperCase() !== "COMPLETE") {
    throw Object.assign(new Error("Create or link the NFT collection before starting a funded art job."), { statusCode: 409 });
  }
  const quote = await nftStudioQuote(body);
  await scenarioValidateNftModel();
  return {
    ok: true,
    tokenMint: mint,
    quote: {
      asset: quote.asset,
      quantity: quote.quantity,
      previewCount: quote.previewCount,
      totalSol: quote.totalSol,
      estimatedUsd: quote.estimatedUsd,
      validUntil: quote.validUntil
    },
    quoteToken: signNftStudioQuote(userId, mint, quote),
    provider: "Scenario"
  };
}

async function webStartNftStudioJob(userId, body = {}) {
  const requestId = firstString(body.clientRequestId, body.jobId) || crypto.randomUUID();
  return runIdempotentMoneyOp("web-nft-studio-fund", userId, requestId, async () => {
    const { attempt, mint } = await nftLaunchForUser(userId, body.tokenMint || body.mint);
    const collectionAddress = firstString(attempt.nftCollectionAddress);
    if (!collectionAddress || String(attempt.nftCollectionStatus || "").toUpperCase() !== "COMPLETE") {
      throw Object.assign(new Error("Create or link the NFT collection before starting a funded art job."), { statusCode: 409 });
    }
    const quote = verifyNftStudioQuote(userId, mint, body.quoteToken);
    const loyalty = await readNftLoyaltyStore();
    const existing = loyalty.generationJobs.find((row) => row.id === requestId && String(row.userId) === String(userId));
    if (existing?.fundingSignature || existing?.status === "FUNDED") return { ok: true, job: nftStudioJobPublic(existing) };
    const active = loyalty.generationJobs.find((row) => row.collectionAddress === collectionAddress && String(row.userId) === String(userId) && !nftStudioFinalStatus(row.status) && row.id !== requestId);
    if (active) throw Object.assign(new Error("Finish, cancel, or refund the current Collection Studio job before starting another."), { statusCode: 409, job: nftStudioJobPublic(active) });

    const walletStore = await readWalletStore();
    const creatorWallet = walletsForOwner(walletStore, userId).find((wallet) => wallet.publicKey === attempt.devWalletPublicKey);
    if (!creatorWallet) throw new Error("The collection creator wallet is not available.");
    const creatorKeypair = decryptWallet(creatorWallet);
    const recipient = parsePublicKey(String(body.recipient || creatorWallet.publicKey)).toBase58();
    const vault = existing?.encryptedVaultSecret
      ? Keypair.fromSecretKey(decryptSecretBuffer(existing.encryptedVaultSecret))
      : Keypair.generate();
    const suppliedReference = String(body.referenceImageDataUrl || "");
    let referenceImageUri = firstString(existing?.referenceImageUri, attempt.nftCollectionImageUri, attempt.imageUri, attempt.metadataJson?.image);
    if (suppliedReference) {
      const referenceDataUrl = await generatedNftReferenceDataUrl(attempt, suppliedReference);
      const referenceUpload = await uploadPumpLaunchMetadata({
        name: `${firstString(attempt.symbol, "NFT")} Collection Reference`,
        symbol: String(attempt.symbol || "NFT").slice(0, 10),
        description: "Creator-supplied direction image for a SlimeWire Collection Studio job.",
        website: `${CONFIG.cashPublicOrigin || "https://www.slimewire.org"}/fun?ca=${encodeURIComponent(mint)}`,
        imageDataUrl: referenceDataUrl,
        imageName: `${cleanTickerSymbol(attempt.symbol || "nft").toLowerCase()}-${requestId.slice(0, 8)}-reference.png`,
        bannerDataUrl: ""
      });
      referenceImageUri = firstString(referenceUpload.imageUri, referenceImageUri);
    }
    if (!referenceImageUri) throw new Error("Add a collection reference image before funding the art job.");
    const nowIso = new Date().toISOString();
    const job = {
      ...(existing || {}), id: requestId, userId: String(userId), tokenMint: mint, collectionAddress,
      creatorWalletPublicKey: creatorWallet.publicKey, recipient,
      nameBase: String(body.nameBase || body.name || `${attempt.symbol || "NFT"} NFT`).replace(/[\u0000-\u001f]/g, " ").trim().slice(0, 64),
      description: String(body.description || "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, 800),
      rarity: normalizeNftRarity(body.rarity),
      artStyle: nftGeneratorStyle(body.artStyle),
      artPrompt: String(body.artPrompt || "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, 500),
      quantity: quote.quantity, previewCount: quote.previewCount,
      quotedLamports: quote.totalLamports, previewUnitLamports: quote.previewUnitLamports,
      itemUnitLamports: quote.itemUnitLamports, apiExpenseLamports: quote.apiExpenseLamports,
      platformFeeBps: quote.platformFeeBps, platformFeeQuotedLamports: quote.platformFeeLamports,
      bufferLamports: quote.bufferLamports, settlementNetworkLamports: quote.settlementNetworkLamports,
      quoteSolUsd: quote.solUsd, quoteValidUntil: quote.validUntil,
      referenceImageUri, provider: "Scenario", providerModelId: scenarioNftModelId(),
      vaultPublicKey: vault.publicKey.toBase58(), encryptedVaultSecret: existing?.encryptedVaultSecret || encryptSecret(Buffer.from(vault.secretKey)),
      previews: Array.isArray(existing?.previews) ? existing.previews : [], mintedItemIds: Array.isArray(existing?.mintedItemIds) ? existing.mintedItemIds : [],
      consumedLamports: Number(existing?.consumedLamports || 0), generatedCount: Number(existing?.generatedCount || 0),
      status: "FUNDING", error: "", createdAt: existing?.createdAt || nowIso, updatedAt: nowIso
    };
    await mutateNftLoyaltyStore((store) => {
      const index = store.generationJobs.findIndex((row) => row.id === requestId && String(row.userId) === String(userId));
      if (index >= 0) store.generationJobs[index] = job;
      else store.generationJobs.push(job);
    });
    const vaultBalance = await connection.getBalance(vault.publicKey, "confirmed").catch(() => 0);
    if (vaultBalance < quote.totalLamports) {
      const tx = addSolFeeMemo(new Transaction(), `nft-studio:${requestId}`, "nft-studio-fund").add(SystemProgram.transfer({
        fromPubkey: creatorKeypair.publicKey,
        toPubkey: vault.publicKey,
        lamports: quote.totalLamports - vaultBalance
      }));
      job.fundingSignature = await sendLegacyTransaction(tx, [creatorKeypair], { markAmbiguous: true });
    }
    job.status = "FUNDED";
    job.fundedAt = new Date().toISOString();
    await updateNftStudioJob(userId, requestId, (row) => ({ ...row, ...job }));
    await audit("web_nft_studio_funded", { userId, jobId: requestId, tokenMint: mint, collectionAddress, quantity: quote.quantity, quotedLamports: quote.totalLamports, vault: job.vaultPublicKey, signature: job.fundingSignature || "already-funded" });
    return { ok: true, job: nftStudioJobPublic(job) };
  }, { lockMs: 180_000, busyMessage: "This Collection Studio reserve is already being funded." });
}

async function webGenerateNftStudioPreviews(userId, body = {}) {
  const jobId = firstString(body.jobId, body.id);
  let job = await nftStudioJobForUser(userId, jobId);
  const previewStale = String(job.status || "") === "PREVIEWING" && Date.now() - Date.parse(job.updatedAt || 0) >= 5 * 60_000;
  if (!["FUNDED", "PREVIEW_FAILED"].includes(String(job.status || "")) && !previewStale) {
    if (job.status === "AWAITING_APPROVAL") return { ok: true, job: nftStudioJobPublic(job) };
    throw Object.assign(new Error("This job is not ready to generate previews."), { statusCode: 409 });
  }
  job = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, status: "PREVIEWING", error: "" }));
  try {
    const { attempt } = await nftLaunchForUser(userId, job.tokenMint);
    const reference = await nftStudioReferenceDataUrl(job.referenceImageUri);
    let previews = Array.isArray(job.previews) ? job.previews.slice() : [];
    while (previews.length < Number(job.previewCount || 4)) {
      const index = previews.length;
      const generated = await scenarioGenerateNftImage({ prompt: nftStudioPrompt(job, attempt, "preview", index), referenceImageDataUrl: reference });
      const stored = await persistNftStudioImage(attempt, job.id, `preview-${index + 1}`, generated.buffer);
      previews.push({ imageUri: stored.imageUri, providerAssetId: generated.assetId, providerJobId: generated.jobId, creativeUnitsCost: generated.creativeUnitsCost });
      job = await updateNftStudioJob(userId, jobId, (row) => ({
        ...row, previews,
        consumedLamports: Number(row.consumedLamports || 0) + Number(row.previewUnitLamports || 0)
      }));
    }
    job = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, previews, status: "AWAITING_APPROVAL", error: "" }));
    return { ok: true, job: nftStudioJobPublic(job) };
  } catch (error) {
    job = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, status: "PREVIEW_FAILED", error: friendlyError(error).slice(0, 240) }));
    throw Object.assign(new Error(`${friendlyError(error)} Your completed previews are saved; retry or cancel for the unused refund.`), { statusCode: 502, job: nftStudioJobPublic(job) });
  }
}

async function webApproveNftStudioPreview(userId, body = {}) {
  const jobId = firstString(body.jobId, body.id);
  const job = await nftStudioJobForUser(userId, jobId);
  if (String(job.status || "") !== "AWAITING_APPROVAL") throw Object.assign(new Error("Generate the four previews before approving a direction."), { statusCode: 409 });
  const selectedPreview = Math.floor(Number(body.selectedPreview));
  if (!Number.isInteger(selectedPreview) || selectedPreview < 0 || selectedPreview >= (job.previews || []).length) throw new Error("Choose one of the generated previews.");
  const updated = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, selectedPreview, status: "READY_TO_BUILD", approvedAt: new Date().toISOString(), error: "" }));
  return { ok: true, job: nftStudioJobPublic(updated) };
}

async function settleNftStudioJob(userId, jobId, targetStatus) {
  let job = await nftStudioJobForUser(userId, jobId);
  if (job.settlementSignature && nftStudioFinalStatus(job.status)) return job;
  const vault = Keypair.fromSecretKey(decryptSecretBuffer(job.encryptedVaultSecret));
  const balance = await connection.getBalance(vault.publicKey, "confirmed").catch(() => 0);
  const completed = targetStatus === "COMPLETE";
  const apiExpenseLamports = Number(job.consumedLamports || 0);
  const platformFeeBps = Number(job.platformFeeBps || 1200);
  const platformFeeChargedLamports = Math.ceil((apiExpenseLamports * platformFeeBps) / 10_000);
  const targetChargeLamports = apiExpenseLamports + platformFeeChargedLamports;
  const latestBlockhash = await rpcWithRetry("get NFT Studio settlement blockhash", () => connection.getLatestBlockhash("confirmed"));
  const buildSettlement = (charged, refund) => {
    const tx = new Transaction({ recentBlockhash: latestBlockhash.blockhash, feePayer: vault.publicKey });
    if (charged > 0) tx.add(SystemProgram.transfer({ fromPubkey: vault.publicKey, toPubkey: new PublicKey(CONFIG.feeWallet), lamports: charged }));
    if (refund > 0) tx.add(SystemProgram.transfer({ fromPubkey: vault.publicKey, toPubkey: new PublicKey(job.creatorWalletPublicKey), lamports: refund }));
    return addSolFeeMemo(tx, `nft-studio-settle:${jobId}`, "nft-studio-settle");
  };
  const provisionalCharge = Math.min(balance, targetChargeLamports);
  const provisionalRefund = Math.max(0, balance - provisionalCharge - 5_000);
  const settlementFeeLamports = balance > 0
    ? await estimateLegacyTransactionFee(buildSettlement(provisionalCharge, provisionalRefund)).catch(() => 5_000)
    : 0;
  const spendable = Math.max(0, balance - settlementFeeLamports);
  const chargedLamports = Math.min(spendable, targetChargeLamports);
  const refundLamports = Math.max(0, spendable - chargedLamports);
  const tx = buildSettlement(chargedLamports, refundLamports);
  let settlementSignature = job.settlementSignature || "";
  if (chargedLamports > 0 || refundLamports > 0) settlementSignature = await sendLegacyTransaction(tx, [vault], { markAmbiguous: true, latestBlockhash });
  job = await updateNftStudioJob(userId, jobId, (row) => ({
    ...row, status: targetStatus, settlementSignature,
    consumedLamports: apiExpenseLamports, platformFeeChargedLamports, chargedLamports, refundLamports, settlementFeeLamports,
    completedAt: completed ? new Date().toISOString() : row.completedAt,
    canceledAt: completed ? row.canceledAt : new Date().toISOString(), error: ""
  }));
  await audit("web_nft_studio_settled", { userId, jobId, status: targetStatus, apiExpenseLamports, platformFeeBps, platformFeeChargedLamports, chargedLamports, refundLamports, settlementFeeLamports, signature: settlementSignature || "empty-vault" });
  return job;
}

async function webRunNftStudioNext(userId, body = {}) {
  const jobId = firstString(body.jobId, body.id);
  let job = await nftStudioJobForUser(userId, jobId);
  const buildStale = String(job.status || "") === "GENERATING" && Date.now() - Date.parse(job.updatedAt || 0) >= 5 * 60_000;
  if (!["READY_TO_BUILD", "BUILD_FAILED"].includes(String(job.status || "")) && !buildStale) {
    if (job.status === "COMPLETE") return { ok: true, job: nftStudioJobPublic(job) };
    throw Object.assign(new Error("Approve a preview before building the collection."), { statusCode: 409 });
  }
  if ((job.mintedItemIds || []).length >= Number(job.quantity || 0)) {
    job = await settleNftStudioJob(userId, jobId, "COMPLETE");
    return { ok: true, job: nftStudioJobPublic(job), complete: true };
  }
  job = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, status: "GENERATING", error: "" }));
  try {
    const { attempt } = await nftLaunchForUser(userId, job.tokenMint);
    const ordinal = (job.mintedItemIds || []).length;
    let pending = job.pendingGenerated && Number(job.pendingGenerated.ordinal) === ordinal ? job.pendingGenerated : null;
    if (!pending) {
      const selected = job.previews?.[job.selectedPreview];
      if (!selected?.imageUri) throw new Error("The approved preview is missing. Generate previews again.");
      const reference = await nftStudioReferenceDataUrl(selected.imageUri);
      const generated = await scenarioGenerateNftImage({ prompt: nftStudioPrompt(job, attempt, "item", ordinal), referenceImageDataUrl: reference });
      const stored = await persistNftStudioImage(attempt, job.id, `item-${ordinal + 1}`, generated.buffer);
      pending = { ordinal, imageUri: stored.imageUri, providerAssetId: generated.assetId, providerJobId: generated.jobId, creativeUnitsCost: generated.creativeUnitsCost };
      job = await updateNftStudioJob(userId, jobId, (row) => ({
        ...row, pendingGenerated: pending,
        consumedLamports: Number(row.consumedLamports || 0) + Number(row.itemUnitLamports || 0)
      }));
    }
    const imageDataUrl = await nftStudioReferenceDataUrl(pending.imageUri);
    const result = await webMintLinkedNftItem(userId, {
      clientRequestId: `nft-studio:${job.id}:${ordinal}`,
      tokenMint: job.tokenMint,
      name: Number(job.quantity || 1) > 1 ? `${job.nameBase} #${ordinal + 1}` : job.nameBase,
      description: job.description,
      rarity: job.rarity,
      recipient: job.recipient,
      imageDataUrl,
      imageName: `${cleanTickerSymbol(attempt.symbol || "nft").toLowerCase()}-${job.id.slice(0, 8)}-${ordinal + 1}.png`,
      _studioJobId: job.id,
      _studioArtStyle: job.artStyle
    });
    const mintedIds = [...new Set([...(job.mintedItemIds || []), result.item.id])];
    job = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, mintedItemIds: mintedIds, generatedCount: mintedIds.length, pendingGenerated: null, status: "READY_TO_BUILD", error: "" }));
    if (mintedIds.length >= Number(job.quantity || 0)) job = await settleNftStudioJob(userId, jobId, "COMPLETE");
    return { ok: true, item: result.item, job: nftStudioJobPublic(job), complete: job.status === "COMPLETE" };
  } catch (error) {
    job = await updateNftStudioJob(userId, jobId, (row) => ({ ...row, status: "BUILD_FAILED", error: friendlyError(error).slice(0, 240) }));
    throw Object.assign(new Error(`${friendlyError(error)} Progress is saved; retry this item or cancel for the unused refund.`), { statusCode: 502, job: nftStudioJobPublic(job) });
  }
}

async function webCancelNftStudioJob(userId, body = {}) {
  const jobId = firstString(body.jobId, body.id);
  const job = await nftStudioJobForUser(userId, jobId);
  if (job.status === "COMPLETE") throw Object.assign(new Error("This Collection Studio job is already complete."), { statusCode: 409 });
  if (["PREVIEWING", "GENERATING"].includes(String(job.status || "")) && Date.now() - Date.parse(job.updatedAt || 0) < 5 * 60_000) {
    throw Object.assign(new Error("This job is finishing its current image. Refresh in a moment, then cancel."), { statusCode: 409 });
  }
  const updated = await settleNftStudioJob(userId, jobId, "CANCELLED");
  return { ok: true, job: nftStudioJobPublic(updated) };
}

async function webSettleNftStudioJob(userId, body = {}) {
  const jobId = firstString(body.jobId, body.id);
  const job = await nftStudioJobForUser(userId, jobId);
  const target = job.settlementTarget === "COMPLETE" || (job.mintedItemIds || []).length >= Number(job.quantity || 0) ? "COMPLETE" : "CANCELLED";
  return { ok: true, job: nftStudioJobPublic(await settleNftStudioJob(userId, jobId, target)) };
}

function nftCampaignPublic(row = {}, viewerWallets = []) {
  const viewerSet = new Set(viewerWallets.map((wallet) => wallet.publicKey));
  const allocations = Array.isArray(row.allocations) ? row.allocations : [];
  const viewerRows = allocations.filter((allocation) => viewerSet.has(allocation.owner));
  return {
    id: row.id,
    tokenMint: row.tokenMint,
    collectionAddress: row.collectionAddress,
    rewardMint: row.rewardMint,
    rewardSymbol: row.rewardSymbol || "TOKEN",
    rewardDecimals: Number(row.rewardDecimals || 0),
    totalAmount: row.totalAmount || "0",
    totalRaw: row.totalRaw || "0",
    status: row.status || "",
    snapshotAt: row.snapshotAt || "",
    expiresAt: row.expiresAt || "",
    assetCount: allocations.length,
    holderCount: new Set(allocations.map((allocation) => allocation.owner)).size,
    claimedAssetCount: allocations.filter((allocation) => allocation.claimedAt).length,
    viewerAllocationRaw: viewerRows.reduce((sum, allocation) => sum + BigInt(allocation.claimedAt ? 0 : allocation.allocationRaw || 0), 0n).toString(),
    viewerCanClaim: viewerRows.some((allocation) => !allocation.claimedAt),
    creatorFeeAutoFundPct: Number(row.creatorFeeAutoFundPct || 0),
    fundingBasis: "creator_deposit",
    explorerUrl: row.rewardMint ? `https://solscan.io/token/${encodeURIComponent(row.rewardMint)}` : ""
  };
}

async function currentCollectionOwnership(collectionAddress, store) {
  const assets = await fetchMetaplexCoreAssets({ rpcUrl: CONFIG.rpcUrl, collectionAddress });
  if (assets.length > 500) throw new Error("This collection is too large for the current loyalty snapshot limit (500 NFTs).");
  const prior = store.ownership[collectionAddress] || {};
  const synced = syncNftOwnership(prior, assets.map((asset) => ({ asset: asset.address, owner: asset.owner })), Date.now());
  store.ownership[collectionAddress] = synced;
  return assets.map((asset) => ({ ...asset, ...synced[asset.address] }));
}

async function webCreateNftRewardCampaign(userId, body = {}) {
  const requestId = firstString(body.clientRequestId, body.campaignId) || crypto.randomUUID();
  return runIdempotentMoneyOp("web-nft-reward-campaign", userId, requestId, async () => {
    const { attempt, mint } = await nftLaunchForUser(userId, body.tokenMint || body.mint);
    const collectionAddress = firstString(attempt.nftCollectionAddress);
    if (!collectionAddress) throw new Error("Create or link the NFT collection first.");
    const rewardMint = parsePublicKey(String(body.rewardMint || "")).toBase58();
    const walletStore = await readWalletStore();
    const walletIndex = parseWebWalletIndex(body.walletIndex || body.fundingWalletIndex);
    const fundingWallet = assertServerSignableWallet(getWalletAt(walletStore, walletIndex, userId), "fund NFT rewards from");
    const fundingKeypair = decryptWallet(fundingWallet);
    const rewardMintKey = new PublicKey(rewardMint);
    const lookup = await getOwnedTokenAccountsWithWarningsCached(fundingKeypair.publicKey, { force: true, priority: true });
    const sourceAccounts = (lookup.accounts || []).filter((account) => account.mint === rewardMint && account.rawAmount > 0n);
    if (!sourceAccounts.length) throw new Error("The selected funding wallet does not hold that reward token.");
    const decimals = Number.isInteger(sourceAccounts[0].decimals) ? sourceAccounts[0].decimals : await getMintDecimals(rewardMintKey);
    const totalRaw = parseCashDecimalToRaw(body.amount, decimals, "reward amount");
    const totalAvailable = sourceAccounts.reduce((sum, account) => sum + BigInt(account.rawAmount), 0n);
    if (totalRaw <= 0n || totalRaw > totalAvailable) throw new Error("That reward amount is greater than the selected wallet's token balance.");

    let loyalty = await readNftLoyaltyStore();
    let campaign = loyalty.campaigns.find((row) => row.id === requestId && String(row.userId) === String(userId));
    const vault = campaign?.encryptedVaultSecret
      ? Keypair.fromSecretKey(decryptSecretBuffer(campaign.encryptedVaultSecret))
      : Keypair.generate();
    const collectionItems = new Map(loyalty.items.filter((item) => item.collectionAddress === collectionAddress && item.address).map((item) => [item.address, item]));
    let ownershipRows;
    await mutateNftLoyaltyStore(async (store) => {
      ownershipRows = await currentCollectionOwnership(collectionAddress, store);
    });
    if (!ownershipRows?.length) throw new Error("Mint at least one NFT in this collection before creating a reward campaign.");
    const assetRows = ownershipRows.map((row) => ({
      asset: row.address,
      owner: row.owner,
      ownerSince: row.ownerSince,
      rarity: collectionItems.get(row.address)?.rarity || "common"
    }));
    const allocations = allocateNftRewards(totalRaw, assetRows, Date.now());
    campaign = {
      ...(campaign || {}), id: requestId, userId: String(userId), tokenMint: mint, collectionAddress,
      rewardMint, rewardSymbol: String(body.rewardSymbol || "TOKEN").replace(/[^A-Za-z0-9_$]/g, "").slice(0, 16).toUpperCase() || "TOKEN",
      rewardDecimals: decimals, totalAmount: rawCashAmountToUi(totalRaw, decimals), totalRaw: totalRaw.toString(),
      fundingWalletPublicKey: fundingWallet.publicKey, fundingWalletIndex: walletIndex,
      vaultPublicKey: vault.publicKey.toBase58(), encryptedVaultSecret: campaign?.encryptedVaultSecret || encryptSecret(Buffer.from(vault.secretKey)),
      allocations, status: "FUNDING", snapshotAt: campaign?.snapshotAt || new Date().toISOString(),
      expiresAt: new Date(Date.now() + Math.max(1, Math.min(365, Number(body.expiresDays || 90))) * 86_400_000).toISOString(),
      creatorFeeAutoFundPct: parseBoolean(body.creatorFeeAutoFund) ? 20 : 0,
      fundingBasis: "creator_deposit", createdAt: campaign?.createdAt || new Date().toISOString()
    };
    await mutateNftLoyaltyStore((store) => {
      const index = store.campaigns.findIndex((row) => row.id === requestId && String(row.userId) === String(userId));
      if (index >= 0) store.campaigns[index] = { ...store.campaigns[index], ...campaign };
      else store.campaigns.push(campaign);
    });

    const tokenProgramId = new PublicKey(sourceAccounts[0].tokenProgramId || TOKEN_PROGRAM_ID);
    const destinationAta = getAssociatedTokenAddress(rewardMintKey, vault.publicKey, tokenProgramId);
    const currentVaultBalance = await getTokenBalanceForMint(vault.publicKey, rewardMintKey, { priority: true }).catch(() => null);
    const alreadyFunded = BigInt(currentVaultBalance?.rawAmount || 0);
    if (alreadyFunded < totalRaw) {
      let remaining = totalRaw - alreadyFunded;
      const tx = new Transaction();
      const destinationInfo = await rpcWithRetry("check NFT reward vault token account", () => connection.getAccountInfo(destinationAta, "confirmed"));
      if (!destinationInfo) tx.add(createAssociatedTokenAccountInstruction(fundingKeypair.publicKey, destinationAta, vault.publicKey, rewardMintKey, tokenProgramId));
      for (const account of sourceAccounts) {
        if (remaining <= 0n) break;
        const available = BigInt(account.rawAmount || 0);
        const amount = available < remaining ? available : remaining;
        if (amount <= 0n) continue;
        tx.add(createTransferCheckedInstruction(new PublicKey(account.pubkey), rewardMintKey, destinationAta, fundingKeypair.publicKey, amount, decimals, [], tokenProgramId));
        remaining -= amount;
      }
      if (remaining > 0n) throw new Error("The reward-token balance changed before funding. Refresh and try again.");
      campaign.fundingSignature = await sendLegacyTransaction(tx, [fundingKeypair]);
    }
    campaign.status = "ACTIVE";
    campaign.fundedAt = new Date().toISOString();
    await mutateNftLoyaltyStore((store) => {
      const index = store.campaigns.findIndex((row) => row.id === requestId && String(row.userId) === String(userId));
      store.campaigns[index] = { ...store.campaigns[index], ...campaign };
    });
    await audit("web_nft_reward_campaign_created", { userId, campaignId: requestId, tokenMint: mint, collectionAddress, rewardMint, totalRaw: totalRaw.toString(), assetCount: allocations.length, creatorFeeAutoFundPct: campaign.creatorFeeAutoFundPct });
    return { ok: true, campaign: nftCampaignPublic(campaign, walletsForOwner(walletStore, userId)) };
  }, { lockMs: 180_000, busyMessage: "This NFT reward campaign is already being funded." });
}

async function webClaimNftRewardCampaign(userId, body = {}) {
  const campaignId = firstString(body.campaignId, body.id);
  const requestId = firstString(body.clientRequestId, body.claimAttemptId) || `${campaignId}:${body.walletIndex || 1}`;
  return runIdempotentMoneyOp("web-nft-reward-claim", userId, requestId, async () => {
    const loyalty = await readNftLoyaltyStore();
    const campaign = loyalty.campaigns.find((row) => row.id === campaignId);
    if (!campaign || campaign.status !== "ACTIVE") throw new Error("That NFT reward campaign is not active.");
    if (Date.parse(campaign.expiresAt || "") <= Date.now()) throw new Error("That NFT reward campaign has ended.");
    const walletStore = await readWalletStore();
    const walletIndex = parseWebWalletIndex(body.walletIndex);
    const claimantWallet = assertServerSignableWallet(getWalletAt(walletStore, walletIndex, userId), "claim NFT rewards to");
    const claimant = decryptWallet(claimantWallet);
    const pendingRows = (campaign.allocations || []).filter((row) => row.owner === claimantWallet.publicKey && !row.claimedAt);
    if (!pendingRows.length) throw new Error("This wallet has no unclaimed allocation in that campaign.");
    const currentAssets = await fetchMetaplexCoreAssetsByAddress({ rpcUrl: CONFIG.rpcUrl, addresses: pendingRows.map((row) => row.asset) });
    const currentOwnerByAsset = new Map(currentAssets.map((asset) => [asset.address, asset.owner]));
    const eligible = pendingRows.filter((row) => currentOwnerByAsset.get(row.asset) === claimantWallet.publicKey);
    if (!eligible.length) throw new Error("This wallet no longer holds the NFTs from its campaign snapshot.");
    const amountRaw = eligible.reduce((sum, row) => sum + BigInt(row.allocationRaw || 0), 0n);
    if (amountRaw <= 0n) throw new Error("This NFT allocation rounded below the token's smallest unit.");
    const vault = Keypair.fromSecretKey(decryptSecretBuffer(campaign.encryptedVaultSecret));
    const rewardMint = new PublicKey(campaign.rewardMint);
    const tokenProgramId = await getMintTokenProgramId(rewardMint, { priority: true });
    const sourceAta = getAssociatedTokenAddress(rewardMint, vault.publicKey, tokenProgramId);
    const destinationAta = getAssociatedTokenAddress(rewardMint, claimant.publicKey, tokenProgramId);
    const tx = new Transaction();
    const destinationInfo = await rpcWithRetry("check NFT reward destination", () => connection.getAccountInfo(destinationAta, "confirmed"));
    if (!destinationInfo) tx.add(createAssociatedTokenAccountInstruction(claimant.publicKey, destinationAta, claimant.publicKey, rewardMint, tokenProgramId));
    tx.add(createTransferCheckedInstruction(sourceAta, rewardMint, destinationAta, vault.publicKey, amountRaw, Number(campaign.rewardDecimals || 0), [], tokenProgramId));
    const signature = await sendLegacyTransaction(tx, [claimant, vault]);
    const claimedAt = new Date().toISOString();
    const eligibleSet = new Set(eligible.map((row) => row.asset));
    await mutateNftLoyaltyStore((store) => {
      const row = store.campaigns.find((entry) => entry.id === campaignId);
      if (!row) return;
      row.allocations = (row.allocations || []).map((allocation) => eligibleSet.has(allocation.asset)
        ? { ...allocation, claimedAt, claimSignature: signature, claimedByUserId: String(userId) }
        : allocation);
      if (row.allocations.every((allocation) => allocation.claimedAt)) row.status = "COMPLETE";
    });
    await audit("web_nft_reward_claimed", { userId, campaignId, wallet: claimantWallet.publicKey, amountRaw: amountRaw.toString(), assetCount: eligible.length, signature });
    return { ok: true, claim: { campaignId, wallet: claimantWallet.publicKey, amount: rawCashAmountToUi(amountRaw, Number(campaign.rewardDecimals || 0)), amountRaw: amountRaw.toString(), rewardMint: campaign.rewardMint, assetCount: eligible.length, signature } };
  }, { busyMessage: "This NFT reward claim is already being submitted." });
}

async function webNftLoyaltyOverview(userId, tokenMint) {
  const mint = parsePublicKey(String(tokenMint || "")).toBase58();
  const launchStore = await readPumpLaunchAttempts();
  const attempt = (launchStore.attempts || []).slice().reverse().find((row) => launchMint(row) === mint);
  if (!attempt) {
    const error = new Error("No SlimeWire launch was found for that coin CA.");
    error.statusCode = 404;
    throw error;
  }
  const loyalty = await readNftLoyaltyStore();
  const collectionAddress = firstString(attempt.nftCollectionAddress);
  const walletStore = await readWalletStore();
  const viewerWallets = walletsForOwner(walletStore, userId);
  const indexedViewerWallets = viewerWallets.map((wallet, index) => ({ ...wallet, index: index + 1 }));
  const ownsLaunch = String(attempt.userId || "") === String(userId);
  const creatorWallet = ownsLaunch
    ? indexedViewerWallets.find((wallet) => wallet.publicKey === attempt.devWalletPublicKey)
    : null;
  const slimeCashWallet = ownsLaunch
    ? indexedViewerWallets.find((wallet) => !wallet.volumeBot && !wallet.ephemeral && !wallet.sessionWallet)
    : null;
  const studioConfig = nftStudioConfig();
  const studioJobs = loyalty.generationJobs
    .filter((job) => job.collectionAddress === collectionAddress && String(job.userId) === String(userId))
    .slice(-10)
    .reverse()
    .map(nftStudioJobPublic);
  return {
    ok: true,
    tokenMint: mint,
    collection: linkedNftCollectionPublicResult(attempt),
    rarityTiers: nftRarityTiers(),
    items: loyalty.items.filter((item) => item.collectionAddress === collectionAddress).map(nftItemPublic),
    artStudio: {
      enabled: studioConfig.enabled,
      comingSoon: studioConfig.comingSoon,
      provider: studioConfig.provider,
      modelId: studioConfig.modelId,
      previewCount: studioConfig.previewCount,
      maxItems: studioConfig.maxItems,
      styles: nftStudioStyles(),
      fundingAsset: "SOL",
      currentJob: studioJobs.find((job) => !nftStudioFinalStatus(job.status)) || null,
      latestJob: studioJobs[0] || null,
      jobs: studioJobs,
      note: studioConfig.enabled
        ? "Fund one all-in maximum quote, review four permanent previews, approve a direction, then build. Only completed work is used; the unused reserve returns to the creator wallet. On-chain mint rent and network fees remain paid by the creator wallet."
        : "AI collection generation is coming soon. Upload and mint your own finished artwork now."
    },
    campaigns: loyalty.campaigns.filter((campaign) => campaign.collectionAddress === collectionAddress).map((campaign) => nftCampaignPublic(campaign, viewerWallets)),
    funding: ownsLaunch ? {
      creatorWallet: creatorWallet ? { index: creatorWallet.index, publicKey: creatorWallet.publicKey, label: creatorWallet.label || `Wallet ${creatorWallet.index}` } : null,
      slimeCashWallet: slimeCashWallet ? { index: slimeCashWallet.index, publicKey: slimeCashWallet.publicKey, label: slimeCashWallet.label || "SlimeCash" } : null,
      sameWallet: Boolean(creatorWallet && slimeCashWallet && creatorWallet.publicKey === slimeCashWallet.publicKey),
      network: "solana",
      standard: "metaplex-core"
    } : null,
    model: {
      custody: "hold-in-wallet",
      loyalty: "10% reward-power step every 30 uninterrupted days, capped at 2x",
      transferRule: "transfers reset the hold-time bonus",
      funding: "creator deposits only",
      platformFeesUsed: false,
      pricePromise: false
    }
  };
}

async function distributeCreatorFeesToNftHolders({ userId, tokenMint, signer, totalLamports, alreadyCommittedLamports = 0n }) {
  const total = BigInt(totalLamports || 0);
  if (total <= 0n) return { enabled: false, paidLamports: 0n, count: 0, reason: "empty_claim" };
  const loyalty = await readNftLoyaltyStore();
  const campaign = loyalty.campaigns.slice().reverse().find((row) => (
    String(row.userId || "") === String(userId)
    && row.tokenMint === tokenMint
    && Number(row.creatorFeeAutoFundPct || 0) === 20
    && ["ACTIVE", "COMPLETE"].includes(String(row.status || ""))
  ));
  if (!campaign) return { enabled: false, paidLamports: 0n, count: 0, reason: "not_enabled" };
  let owners = [];
  await mutateNftLoyaltyStore(async (store) => {
    owners = await currentCollectionOwnership(campaign.collectionAddress, store);
  });
  const rarityByAsset = new Map(loyalty.items.filter((item) => item.collectionAddress === campaign.collectionAddress).map((item) => [item.address, item.rarity]));
  const target = (total * 20n) / 100n;
  // Never over-allocate the same creator-fee claim when legacy coin-holder rewards
  // are also enabled. Leave a small network-fee reserve in the creator wallet.
  const available = total > BigInt(alreadyCommittedLamports || 0) + 20_000n
    ? total - BigInt(alreadyCommittedLamports || 0) - 20_000n
    : 0n;
  const distributable = target < available ? target : available;
  if (distributable < 5_000n) return { enabled: true, paidLamports: 0n, count: 0, reason: "dust_or_already_allocated" };
  const assetAllocations = allocateNftRewards(distributable, owners.map((row) => ({
    asset: row.address,
    owner: row.owner,
    ownerSince: row.ownerSince,
    rarity: rarityByAsset.get(row.address) || "common"
  })), Date.now());
  const byOwner = new Map();
  for (const row of assetAllocations) byOwner.set(row.owner, (byOwner.get(row.owner) || 0n) + BigInt(row.allocationRaw || 0));
  // One atomic payout prevents a retry from paying an earlier chunk twice if a
  // later chunk fails. The highest Reward Power holders fit in one legacy tx.
  const recipients = [...byOwner.entries()]
    .map(([wallet, lamports]) => ({ wallet, lamports }))
    .filter((row) => row.lamports >= 5_000n)
    .sort((left, right) => compareBigInt(right.lamports, left.lamports))
    .slice(0, 18);
  if (!recipients.length) return { enabled: true, paidLamports: 0n, count: 0, reason: "no_current_holders" };
  const signatures = [];
  let paidLamports = 0n;
  const tx = new Transaction();
  for (const row of recipients) {
    tx.add(SystemProgram.transfer({ fromPubkey: signer.publicKey, toPubkey: new PublicKey(row.wallet), lamports: Number(row.lamports) }));
    paidLamports += row.lamports;
  }
  signatures.push(await sendLegacyTransaction(tx, [signer]));
  return { enabled: true, paidLamports, count: recipients.length, signatures, campaignId: campaign.id };
}

// The coins THIS user launched (the "My launches & fees" tracker). De-duped by mint, newest first, with
// each coin's creator wallet mapped back to the user's wallet index so the client can claim by index.
async function webLaunchedCoins(userId) {
  const store = await readPumpLaunchAttempts();
  const seen = new Set();
  const rows = [];
  for (const a of (store.attempts || []).slice().reverse()) {
    if (String(a.userId || "") !== String(userId)) continue;
    const mint = firstString(a.mintPublicKey, a.tokenMint, a.mint);
    if (!mint || seen.has(mint)) continue;
    seen.add(mint);
    const launchRail = String(a.rail || "pump").toLowerCase();
    const pumpDedicatedCreatorClaim = launchRail !== "pump"
      || pumpCreatorHasDedicatedInvariant(a, a.devWalletPublicKey, mint);
    const storedCreatorClaimSol = Math.max(0, Number(a.creatorFeesAutoClaimSol || 0));
    const creatorFeeClaimedSol = pumpDedicatedCreatorClaim ? storedCreatorClaimSol : 0;
    const storedCreatorFeeStatus = firstString(
      a.creatorFeesAutoClaimStatus,
      normalizeCreatorFeeClaimMode(a.creatorFeeClaimMode) === "manual" ? "accruing" : "watching"
    );
    rows.push({
      mint, symbol: a.symbol || "", name: a.tokenName || a.name || "",
      rail: a.rail || "pump", devWallet: a.devWalletPublicKey || "", status: a.status || "",
      txSignature: a.txSignature || "", imageUri: a.imageUri || (a.metadataJson && a.metadataJson.image) || "",
      createdAt: a.createdAt || a.updatedAt || "",
      pumpCashback: normalizePumpCashback(a.pumpCashback),
      holderRewards: launchHolderRewardsFromAttempt(a),
      feeSharing: pumpFeeSharingPublic(a),
      creatorFeeClaimMode: normalizeCreatorFeeClaimMode(a.creatorFeeClaimMode),
      creatorFeeStatus: launchRail === "pump" && !pumpDedicatedCreatorClaim && storedCreatorClaimSol > 0
        ? "wallet_claimed_unattributed"
        : storedCreatorFeeStatus,
      creatorFeeClaimScope: launchRail === "pump" ? "wallet" : "mint",
      creatorFeeClaimReceiptId: firstString(a.creatorFeesWalletClaimReceiptId),
      creatorFeePendingVolumeSol: Math.max(0, Number(a.creatorFeesAutoClaimPendingVolumeSol || 0)),
      creatorFeeClaimedSol: creatorFeeClaimedSol,
      holderRewardPendingSol: Math.max(0, Number(a.holderRewardsPendingLamports || 0) / LAMPORTS_PER_SOL),
      holderRewardPaidSol: Math.max(0, Number(a.holderRewardsPaidLamports || 0) / LAMPORTS_PER_SOL),
      holderRewardStatus: firstString(a.holderRewardsAutoClaimStatus, a.holderRewardsLastError ? "failed" : "watching"),
      holderRewardLastPayoutAt: firstString(a.holderRewardsLastPayoutAt),
      holderRewardLastPayoutCount: Math.max(0, Number(a.holderRewardsLastPayoutCount || 0)),
      creatorFeeCheckedAt: firstString(a.creatorFeesAutoClaimCheckedAt),
      creatorFeeClaimedAt: firstString(a.creatorFeesAutoClaimAt),
      creatorFeeError: firstString(a.creatorFeesAutoClaimError).slice(0, 180),
      rhPool: firstString(a.rhPool),
      rhTokenId: a.rhTokenId == null ? "" : String(a.rhTokenId),
      rhLiquidityLocker: firstString(a.rhLiquidityLocker),
      rhPoolFeeStatus: firstString(a.rhPoolFeesAutoClaimStatus, "watching"),
      rhPoolFeeCheckedAt: firstString(a.rhPoolFeesAutoClaimCheckedAt),
      rhPoolFeeClaimedAt: firstString(a.rhPoolFeesAutoClaimAt),
      rhPoolFeeAmount0: firstString(a.rhPoolFeesAmount0, "0"),
      rhPoolFeeAmount1: firstString(a.rhPoolFeesAmount1, "0"),
      rhPoolFeeSignature: firstString(a.rhPoolFeesAutoClaimSignature),
      rhPoolFeeError: firstString(a.rhPoolFeesAutoClaimError).slice(0, 180),
      nftCollection: linkedNftCollectionPublicResult(a)
    });
  }
  const walletStore = await readWalletStore();
  const idxByKey = new Map(walletsForOwner(walletStore, userId).map((w, i) => [w.publicKey, i + 1]));
  return rows.slice(0, 60).map((r) => ({ ...r, devWalletIndex: idxByKey.get(r.devWallet) || null, devWalletShort: r.devWallet ? shortMint(r.devWallet) : "" }));
}

// Claim accrued CREATOR fees to the creator wallet via PumpPortal's collectCreatorFee — no pump.fun trip.
// pump: claims ALL that wallet's accrued pump fees at once (mint omitted). meteora: per-coin (mint + pool).
const pumpRewardBalanceCache = new Map();
const PUMP_REWARD_BALANCE_TTL_MS = 12_000;

function pumpRewardCacheKey(userId, publicKey) {
  return `${String(userId)}:${String(publicKey)}`;
}

function pumpRewardAtomic(value) {
  try { return BigInt(String(value || "0").replace(/[^\d]/g, "") || "0"); }
  catch { return 0n; }
}

function pumpRewardSol(value) {
  return Number(pumpRewardAtomic(value)) / LAMPORTS_PER_SOL;
}

function invalidatePumpRewardBalanceCache(userId, publicKey = "") {
  const exact = publicKey ? pumpRewardCacheKey(userId, publicKey) : "";
  for (const key of pumpRewardBalanceCache.keys()) {
    if ((exact && key === exact) || (!exact && key.startsWith(`${String(userId)}:`))) {
      pumpRewardBalanceCache.delete(key);
    }
  }
}

async function readPumpRewardBalanceCached(userId, wallet, { force = false } = {}) {
  const key = pumpRewardCacheKey(userId, wallet.publicKey);
  const cached = pumpRewardBalanceCache.get(key);
  if (!force && cached && Date.now() - cached.createdAt < PUMP_REWARD_BALANCE_TTL_MS) return cached.value;
  const value = await getPumpRewardBalances({
    connection: readConnection,
    wallet: wallet.publicKey,
    commitment: "confirmed"
  });
  pumpRewardBalanceCache.set(key, { createdAt: Date.now(), value });
  return value;
}

function publicPumpRewardWallet(wallet, walletIndex, balances, error = "") {
  const creatorTotal = pumpRewardAtomic(balances?.creator?.totalAtomic);
  const cashbackTotal = pumpRewardAtomic(balances?.cashback?.totalAtomic);
  return {
    walletIndex,
    label: wallet.label || `Wallet ${walletIndex}`,
    publicKey: wallet.publicKey,
    shortPublicKey: shortMint(wallet.publicKey),
    scope: "wallet",
    creator: {
      curveLamports: String(balances?.creator?.curveLamports || "0"),
      ammWsolAtomic: String(balances?.creator?.ammWsolAtomic || "0"),
      totalAtomic: creatorTotal.toString(),
      totalLamports: creatorTotal.toString(),
      totalSol: pumpRewardSol(creatorTotal)
    },
    cashback: {
      curveLamports: String(balances?.cashback?.curveLamports || "0"),
      ammWsolAtomic: String(balances?.cashback?.ammWsolAtomic || "0"),
      totalAtomic: cashbackTotal.toString(),
      totalLamports: cashbackTotal.toString(),
      totalSol: pumpRewardSol(cashbackTotal)
    },
    checkedAt: new Date().toISOString(),
    ...(error ? { error: String(error).slice(0, 180) } : {})
  };
}

async function webPumpRewards(userId, walletIndexValue = "1", options = {}) {
  const walletStore = await readWalletStore();
  const owned = walletsForOwner(walletStore, userId);
  const requestedIndex = parseWebWalletIndex(walletIndexValue);
  if (!owned[requestedIndex - 1]) {
    const error = new Error("That wallet does not exist.");
    error.statusCode = 404;
    throw error;
  }
  const rows = await runWithConcurrency(
    owned.map((wallet, index) => ({ wallet, walletIndex: index + 1 })),
    Math.min(3, owned.length),
    async ({ wallet, walletIndex }) => {
      try {
        const balances = await readPumpRewardBalanceCached(userId, wallet, options);
        await reconcilePumpCreatorRewardObligations(userId, wallet.publicKey, balances).catch(() => {});
        return publicPumpRewardWallet(wallet, walletIndex, balances);
      } catch (error) {
        return publicPumpRewardWallet(wallet, walletIndex, null, friendlyError(error));
      }
    }
  );
  const receiptStore = await readPumpLaunchAttempts().catch(() => ({ attempts: [], creatorRewardObligations: [] }));
  // A creator-wallet badge is private account context, not a public claim about a wallet.
  // Mark a managed wallet when this user has a completed non-Cash-Back Pump launch on it,
  // or later when an authoritative on-chain balance / durable claim receipt proves it.
  // Reuse the launch-store read needed for receipts so opening Wallet adds no provider call.
  const creatorLaunchMintsByWallet = new Map();
  for (const attempt of receiptStore.attempts || []) {
    if (String(attempt.userId || "") !== String(userId)) continue;
    if (String(attempt.rail || "pump").toLowerCase() !== "pump") continue;
    if (normalizePumpCashback(attempt.pumpCashback)) continue;
    const status = String(attempt.status || "").toUpperCase();
    if (status && !["COMPLETE", "CONFIRMED", "LAUNCHED", "SUBMITTED"].includes(status)) continue;
    const publicKey = String(attempt.devWalletPublicKey || "");
    const mint = firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint);
    if (!publicKey || !mint) continue;
    const mints = creatorLaunchMintsByWallet.get(publicKey) || new Set();
    mints.add(mint);
    creatorLaunchMintsByWallet.set(publicKey, mints);
  }
  const receiptsByWallet = new Map();
  for (const receipt of receiptStore.creatorRewardObligations || []) {
    if (String(receipt.userId || "") !== String(userId)) continue;
    const publicKey = String(receipt.walletPublicKey || "");
    if (!publicKey) continue;
    const current = receiptsByWallet.get(publicKey) || { claimedAtomic: 0n, count: 0, pendingCount: 0, latestAt: "" };
    const claimedAtomic = pumpRewardAtomic(receipt.claimedAtomic);
    if (claimedAtomic > 0n) {
      current.claimedAtomic += claimedAtomic;
      current.count += 1;
    }
    if (["SUBMITTING", "RECONCILING", "PARTIAL_OR_FAILED"].includes(String(receipt.status || ""))) current.pendingCount += 1;
    const timestamp = firstString(receipt.updatedAt, receipt.createdAt);
    if (timestamp > current.latestAt) current.latestAt = timestamp;
    receiptsByWallet.set(publicKey, current);
  }
  const publicRows = rows.map((row) => {
    const claims = receiptsByWallet.get(row.publicKey) || { claimedAtomic: 0n, count: 0, pendingCount: 0, latestAt: "" };
    const creatorLaunchCount = creatorLaunchMintsByWallet.get(row.publicKey)?.size || 0;
    const creatorEligible = creatorLaunchCount > 0
      || pumpRewardAtomic(row.creator?.totalAtomic) > 0n
      || claims.claimedAtomic > 0n
      || claims.pendingCount > 0;
    return {
      ...row,
      creatorEligible,
      creatorLaunchCount,
      creatorClaims: {
        scope: "wallet",
        claimedAtomic: claims.claimedAtomic.toString(),
        claimedSol: pumpRewardSol(claims.claimedAtomic),
        count: claims.count,
        pendingCount: claims.pendingCount,
        latestAt: claims.latestAt
      }
    };
  });
  const creatorAtomic = publicRows.reduce((sum, row) => sum + pumpRewardAtomic(row.creator.totalAtomic), 0n);
  const cashbackAtomic = publicRows.reduce((sum, row) => sum + pumpRewardAtomic(row.cashback.totalAtomic), 0n);
  const creatorClaimedAtomic = publicRows.reduce((sum, row) => sum + pumpRewardAtomic(row.creatorClaims.claimedAtomic), 0n);
  return {
    ok: true,
    checkedAt: new Date().toISOString(),
    scope: "wallet",
    wallets: publicRows,
    wallet: publicRows.find((row) => row.walletIndex === requestedIndex) || publicRows[0],
    totals: {
      creatorAtomic: creatorAtomic.toString(),
      creatorSol: pumpRewardSol(creatorAtomic),
      creatorClaimedAtomic: creatorClaimedAtomic.toString(),
      creatorClaimedSol: pumpRewardSol(creatorClaimedAtomic),
      cashbackAtomic: cashbackAtomic.toString(),
      cashbackSol: pumpRewardSol(cashbackAtomic)
    }
  };
}

async function sendPumpRewardProgramClaim({ keypair, instruction, destinationExists, programName = "pump", onSigned = null }) {
  if (!instruction) return { signature: "", payoutAsset: "SOL" };
  const destination = getAssociatedTokenAddress(PUMP_WRAPPED_SOL_MINT, keypair.publicKey, PUMP_TOKEN_PROGRAM_ID);
  const tx = new Transaction();
  if (!destinationExists) {
    tx.add(createIdempotentAssociatedTokenAccountInstruction(
      keypair.publicKey,
      destination,
      keypair.publicKey,
      PUMP_WRAPPED_SOL_MINT,
      PUMP_TOKEN_PROGRAM_ID
    ));
  }
  tx.add(instruction);
  // Only close an ATA this request created. Existing WSOL accounts may contain
  // user funds and are never touched. Closing converts this claim's WSOL to SOL.
  if (!destinationExists) {
    tx.add(createCloseAccountInstruction(
      destination,
      keypair.publicKey,
      keypair.publicKey,
      [],
      PUMP_TOKEN_PROGRAM_ID
    ));
  }
  const signature = await sendLegacyTransaction(tx, [keypair], {
    priority: true,
    markAmbiguous: true,
    ambiguousOnAnySendError: true,
    onSigned
  });
  return {
    signature,
    // Pump's legacy-SOL bonding-curve instructions pay native SOL directly.
    // PumpSwap pays WSOL; it becomes native SOL only when this request safely
    // created and closed the destination ATA.
    payoutAsset: programName === "pumpAmm" && destinationExists ? "WSOL" : "SOL"
  };
}

async function webClaimPumpRewards(userId, body = {}) {
  const kind = String(body.kind || "creator").trim().toLowerCase();
  if (!["creator", "cashback"].includes(kind)) {
    const error = new Error("Choose creator rewards or Pump Cash Back.");
    error.statusCode = 400;
    throw error;
  }
  const walletIndex = parseWebWalletIndex(body.walletIndex);
  const attemptId = firstString(body.tradeAttemptId, body.clientRequestId);
  return runIdempotentMoneyOp(`pump-${kind}-claim`, userId, attemptId,
    () => webClaimPumpRewardsCore(userId, { walletIndex, kind, claimOperationId: attemptId || crypto.randomUUID() }),
    {
      ttlMs: 24 * 60 * 60_000,
      lockMs: 120_000,
      busyMessage: `This ${kind === "cashback" ? "cash-back" : "creator reward"} claim is already submitting.`
    });
}

function pumpCreatorDedicatedProof(attempt = {}, walletPublicKey = "", mint = "") {
  const launchId = String(attempt.id || attempt.launchAttemptId || "");
  const userId = String(attempt.userId || "");
  if (!launchId || !userId || !walletPublicKey || !mint) return "";
  return crypto.createHmac("sha256", CONFIG.appSecret)
    .update(`pump-dedicated-creator-v1:${userId}:${launchId}:${walletPublicKey}:${mint}`)
    .digest("hex");
}

function pumpCreatorHasDedicatedInvariant(attempt = {}, walletPublicKey = "", mint = "") {
  const provided = String(attempt.creatorRewardDedicatedProof || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(provided)) return false;
  if (String(attempt.creatorRewardDedicatedWallet || "") !== String(walletPublicKey || "")) return false;
  if (String(attempt.creatorRewardDedicatedMint || "") !== String(mint || "")) return false;
  const expected = pumpCreatorDedicatedProof(attempt, walletPublicKey, mint);
  if (!expected) return false;
  return crypto.timingSafeEqual(Buffer.from(provided, "hex"), Buffer.from(expected, "hex"));
}

function pumpCreatorObligationPublicLaunch(attempt = {}, nftCampaignMints = new Set()) {
  const mint = firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint);
  // Official Pump fee sharing routes this mint's holder allocation directly
  // into its dedicated per-mint vault. It must never be counted again as a
  // legacy wallet-wide creator-claim obligation.
  const holderRewards = launchHolderRewardsFromAttempt(attempt).enabled && !pumpUsesOfficialHolderFeeSharing(attempt);
  const nftRewards = Boolean(mint && nftCampaignMints.has(mint));
  return {
    id: String(attempt.id || attempt.launchAttemptId || ""),
    mint,
    holderRewards,
    nftRewards
  };
}

async function createPumpCreatorRewardObligation({
  id,
  userId,
  walletIndex,
  walletPublicKey,
  attribution,
  built
}) {
  if (!id) return null;
  const protectedLaunches = Array.isArray(attribution?.protectedLaunches)
    ? attribution.protectedLaunches
    : [];
  const hasProtectedAttribution = protectedLaunches.length > 0;
  const expectedByProgram = {
    pump: String(built?.balances?.creator?.curveLamports || "0"),
    pumpAmm: String(built?.balances?.creator?.ammWsolAtomic || "0")
  };
  const now = new Date().toISOString();
  const obligation = {
    id: String(id),
    kind: "pump_creator_wallet_claim",
    userId: String(userId),
    walletIndex: Number(walletIndex),
    walletPublicKey: String(walletPublicKey),
    status: "SUBMITTING",
    scope: "wallet",
    attributionStatus: attribution.dedicatedLaunch
      ? "PROVEN_DEDICATED"
      : (hasProtectedAttribution ? "UNPROVEN_WALLET_WIDE" : "WALLET_TOTAL_ONLY"),
    dedicatedMint: attribution.dedicatedLaunch
      ? firstString(attribution.dedicatedLaunch.mintPublicKey, attribution.dedicatedLaunch.tokenMint, attribution.dedicatedLaunch.mint)
      : "",
    protectedLaunches,
    beforeAtomic: String(built?.balances?.creator?.totalAtomic || "0"),
    expectedByProgram,
    programs: {
      pump: { expectedAtomic: expectedByProgram.pump, status: BigInt(expectedByProgram.pump) > 0n ? "PENDING" : "EMPTY", signatures: [] },
      pumpAmm: { expectedAtomic: expectedByProgram.pumpAmm, status: BigInt(expectedByProgram.pumpAmm) > 0n ? "PENDING" : "EMPTY", signatures: [] }
    },
    confirmedAtomic: "0",
    observedDeltaAtomic: "0",
    distributedAtomic: "0",
    distributionStatus: hasProtectedAttribution ? "NOT_STARTED" : "NOT_APPLICABLE",
    createdAt: now,
    updatedAt: now
  };
  await withFileLock(pumpLaunchAttemptsPath(), async () => {
    const store = await readPumpLaunchAttempts();
    const existing = store.creatorRewardObligations.find((row) => row.id === obligation.id && String(row.userId) === String(userId));
    const unresolved = store.creatorRewardObligations.find((row) => (
      row.id !== obligation.id
      && String(row.userId) === String(userId)
      && String(row.walletPublicKey || "") === String(walletPublicKey)
      && ["SUBMITTING", "RECONCILING", "PARTIAL_OR_FAILED"].includes(String(row.status || ""))
    ));
    if (unresolved) {
      const error = new Error("A prior creator-reward claim for this wallet is still reconciling on-chain. Refresh rewards before claiming again.");
      error.statusCode = 409;
      throw error;
    }
    if (!existing) store.creatorRewardObligations.push(obligation);
    await writePumpLaunchAttempts(store);
  });
  return obligation;
}

async function patchPumpCreatorRewardObligation(id, userId, patch = {}) {
  if (!id) return null;
  let saved = null;
  await withFileLock(pumpLaunchAttemptsPath(), async () => {
    const store = await readPumpLaunchAttempts();
    const row = store.creatorRewardObligations.find((entry) => entry.id === String(id) && String(entry.userId) === String(userId));
    if (!row) return;
    const programs = patch.programs
      ? {
          ...(row.programs || {}),
          ...Object.fromEntries(Object.entries(patch.programs).map(([name, value]) => [name, { ...(row.programs?.[name] || {}), ...(value || {}) }]))
        }
      : row.programs;
    Object.assign(row, patch, { programs, updatedAt: new Date().toISOString() });
    saved = { ...row, programs: structuredClone(programs || {}) };
    await writePumpLaunchAttempts(store);
  });
  return saved;
}

function confirmedPumpCreatorObligationAtomic(programs = {}) {
  return ["pump", "pumpAmm"].reduce((sum, name) => (
    String(programs?.[name]?.status || "") === "CONFIRMED"
      ? sum + pumpRewardAtomic(programs[name].expectedAtomic)
      : sum
  ), 0n);
}

async function reconcilePumpCreatorRewardObligations(userId, walletPublicKey, balances = null) {
  const store = await readPumpLaunchAttempts().catch(() => ({ creatorRewardObligations: [] }));
  const pending = (store.creatorRewardObligations || []).filter((row) => (
    String(row.userId || "") === String(userId)
    && String(row.walletPublicKey || "") === String(walletPublicKey)
    && ["SUBMITTING", "RECONCILING", "PARTIAL_OR_FAILED"].includes(String(row.status || ""))
  ));
  if (!pending.length) return 0;
  let reconciled = 0;
  let currentBlockHeight = null;
  let blockHeightChecked = false;
  const readCurrentBlockHeight = async () => {
    if (!blockHeightChecked) {
      blockHeightChecked = true;
      currentBlockHeight = await connection.getBlockHeight("confirmed").catch(() => null);
    }
    return currentBlockHeight;
  };
  for (const obligation of pending) {
    const programs = structuredClone(obligation.programs || {});
    let stillReconciling = false;
    for (const name of ["pump", "pumpAmm"]) {
      const program = programs[name] || {};
      if (!["SUBMITTING", "RECONCILING"].includes(String(program.status || ""))) continue;
      const hashes = [...new Set([
        ...(Array.isArray(program.signatures) ? program.signatures : []),
        program.signature || ""
      ].filter(Boolean))];
      let confirmedSignature = "";
      const reconciledHashes = [];
      for (const signature of hashes) {
        const status = await connection.getSignatureStatus(signature, { searchTransactionHistory: true }).catch(() => null);
        const signatureStatus = status?.value ?? null;
        const height = signatureStatus == null && program.lastValidBlockHeight
          ? await readCurrentBlockHeight()
          : null;
        const classification = classifySignedPumpClaimReconciliation({
          signatureStatus,
          currentBlockHeight: height,
          lastValidBlockHeight: program.lastValidBlockHeight
        });
        reconciledHashes.push({ signature, classification });
        if (classification.state === "CONFIRMED") {
          confirmedSignature = signature;
          break;
        }
      }
      if (confirmedSignature) {
        programs[name] = { ...program, status: "CONFIRMED", signature: confirmedSignature, confirmedAt: new Date().toISOString() };
      } else if (hashes.length && reconciledHashes.length === hashes.length && reconciledHashes.every((row) => row.classification.terminal)) {
        const expired = reconciledHashes.some((row) => row.classification.state === "EXPIRED");
        programs[name] = {
          ...program,
          status: expired ? "FAILED_EXPIRED" : "FAILED",
          failedAt: new Date().toISOString(),
          reconciliationReason: expired ? "blockhash_expired_unconfirmed" : "signature_failed"
        };
      } else {
        stillReconciling = true;
      }
    }
    const confirmedAtomic = confirmedPumpCreatorObligationAtomic(programs);
    const currentAtomic = balances ? pumpRewardAtomic(balances?.creator?.totalAtomic) : null;
    const beforeAtomic = pumpRewardAtomic(obligation.beforeAtomic);
    const observedDeltaAtomic = currentAtomic != null && beforeAtomic > currentAtomic ? beforeAtomic - currentAtomic : 0n;
    const claimedAtomic = confirmedAtomic > observedDeltaAtomic ? confirmedAtomic : observedDeltaAtomic;
    const hasSubmittedSignature = ["pump", "pumpAmm"].some((name) => {
      const program = programs[name] || {};
      return Boolean(program.signature) || (Array.isArray(program.signatures) && program.signatures.some(Boolean));
    });
    const createdAtMs = Date.parse(obligation.createdAt || "");
    const expiredWithoutEvidence = !hasSubmittedSignature
      && Number.isFinite(createdAtMs)
      && Date.now() - createdAtMs > 180_000;
    const hasProtectedAttribution = Array.isArray(obligation.protectedLaunches)
      && obligation.protectedLaunches.length > 0;
    await patchPumpCreatorRewardObligation(obligation.id, userId, {
      programs,
      confirmedAtomic: confirmedAtomic.toString(),
      observedDeltaAtomic: observedDeltaAtomic.toString(),
      claimedAtomic: claimedAtomic.toString(),
      remainingAtomic: currentAtomic == null ? String(obligation.remainingAtomic || beforeAtomic) : currentAtomic.toString(),
      remainingAtomicKnown: currentAtomic != null,
      // A confirmed signature or a lower on-chain vault balance is enough to
      // preserve the claim as an obligation even if one program cannot be
      // identified after a process restart. Terminalizing that record prevents
      // a later claim from being counted against it a second time.
      status: claimedAtomic > 0n
        ? (hasProtectedAttribution ? "MANUAL_ATTRIBUTION_REQUIRED" : "CONFIRMED_WALLET_CLAIM")
        : (stillReconciling && !expiredWithoutEvidence ? "RECONCILING" : "NO_CONFIRMED_CLAIM"),
      distributionStatus: hasProtectedAttribution
        ? "SKIPPED_UNPROVEN_WALLET_WIDE_ATTRIBUTION"
        : "NOT_APPLICABLE"
    });
    reconciled += 1;
  }
  return reconciled;
}

async function pumpCreatorRewardAttribution(userId, walletPublicKey) {
  const store = await readPumpLaunchAttempts().catch(() => ({ attempts: [] }));
  const loyalty = await readNftLoyaltyStore().catch(() => ({ campaigns: [] }));
  const nftCampaignMints = new Set((loyalty.campaigns || []).filter((row) => (
    String(row.userId || "") === String(userId)
    && Number(row.creatorFeeAutoFundPct || 0) === 20
    && ["ACTIVE", "COMPLETE"].includes(String(row.status || ""))
  )).map((row) => String(row.tokenMint || "")).filter(Boolean));
  const byMint = new Map();
  for (const attempt of (store.attempts || []).slice().reverse()) {
    if (String(attempt.userId || "") !== String(userId)) continue;
    if (String(attempt.rail || "pump").toLowerCase() !== "pump") continue;
    if (String(attempt.devWalletPublicKey || "") !== String(walletPublicKey)) continue;
    if (normalizePumpCashback(attempt.pumpCashback)) continue;
    const status = String(attempt.status || "").toUpperCase();
    if (status && !["COMPLETE", "CONFIRMED", "LAUNCHED", "SUBMITTED"].includes(status)) continue;
    const mint = firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint);
    if (mint && !byMint.has(mint)) byMint.set(mint, attempt);
  }
  const launches = [...byMint.values()];
  const protectedAttempts = launches.filter((attempt) => {
    const mint = firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint);
    const legacyHolderRewards = launchHolderRewardsFromAttempt(attempt).enabled && !pumpUsesOfficialHolderFeeSharing(attempt);
    return legacyHolderRewards || nftCampaignMints.has(mint);
  });
  const dedicatedLaunch = protectedAttempts.length === 1 && launches.length === 1
    && pumpCreatorHasDedicatedInvariant(
      protectedAttempts[0],
      walletPublicKey,
      firstString(protectedAttempts[0].mintPublicKey, protectedAttempts[0].tokenMint, protectedAttempts[0].mint)
    )
    ? protectedAttempts[0]
    : null;
  return {
    launches,
    dedicatedLaunch,
    protectedLaunches: protectedAttempts.map((attempt) => pumpCreatorObligationPublicLaunch(attempt, nftCampaignMints)),
    attributionProven: Boolean(dedicatedLaunch)
  };
}

async function distributeAttributedPumpCreatorRewards({ userId, wallet, keypair, launch, claimedAtomic, dedicatedProofVerified = false }) {
  if (!dedicatedProofVerified) {
    return {
      holderRewards: { enabled: true, skipped: true, reason: "dedicated_creator_invariant_not_proven" },
      nftHolderRewards: { enabled: true, skipped: true, reason: "dedicated_creator_invariant_not_proven" }
    };
  }
  if (!launch || pumpRewardAtomic(claimedAtomic) <= 0n) return { holderRewards: null, nftHolderRewards: null };
  const claimMint = firstString(launch.mintPublicKey, launch.tokenMint, launch.mint);
  if (!claimMint) return { holderRewards: null, nftHolderRewards: null };
  const claimedLamports = pumpRewardAtomic(claimedAtomic);
  let holderRewards = null;
  const policy = launchHolderRewardsFromAttempt(launch);
  if (policy.enabled && !pumpUsesOfficialHolderFeeSharing(launch)) {
    try {
      const priorPendingLamports = pumpRewardAtomic(launch.holderRewardsPendingLamports);
      const dist = await distributeSolHolderRewards({
        signer: keypair,
        tokenMint: claimMint,
        policy,
        totalLamports: claimedLamports,
        pendingLamports: priorPendingLamports
      });
      holderRewards = {
        enabled: true,
        shareBps: policy.shareBps,
        count: dist.count || 0,
        paidLamports: String(dist.paidLamports || 0n),
        pendingLamports: String(dist.pendingLamports || 0n),
        accruedLamports: String(dist.accruedLamports || 0n),
        signature: dist.signature || "",
        signatures: dist.signatures || [],
        reason: dist.reason || "",
        error: dist.error || ""
      };
      const launchId = String(launch.id || launch.launchAttemptId || "");
      if (launchId) {
        const priorPaid = pumpRewardAtomic(launch.holderRewardsPaidLamports);
        const priorAccrued = pumpRewardAtomic(launch.holderRewardsAccruedLamports);
        await upsertPumpLaunchAttempt({
          id: launchId,
          holderRewardsPendingLamports: String(dist.pendingLamports || 0n),
          holderRewardsPaidLamports: String(priorPaid + BigInt(dist.paidLamports || 0n)),
          holderRewardsAccruedLamports: String(priorAccrued + BigInt(dist.accruedLamports || 0n)),
          holderRewardsLastPayoutAt: dist.paidLamports > 0n ? new Date().toISOString() : firstString(launch.holderRewardsLastPayoutAt),
          holderRewardsLastPayoutSignature: dist.signature || firstString(launch.holderRewardsLastPayoutSignature),
          holderRewardsLastPayoutCount: dist.count || 0,
          holderRewardsAutoClaimStatus: dist.paidLamports > 0n ? "paid" : dist.reason || "accumulating",
          holderRewardsLastError: dist.error || ""
        });
      }
    } catch (error) {
      holderRewards = { enabled: true, error: friendlyError(error) };
      await audit("web_claim_holder_rewards_failed", { userId, wallet: wallet.publicKey, rail: "pump", mint: claimMint, error: friendlyError(error) }).catch(() => {});
    }
  } else if (policy.enabled) {
    holderRewards = { enabled: true, official: true, skipped: true, reason: "dedicated_fee_sharing_vault" };
  }

  let nftHolderRewards = null;
  try {
    const alreadyCommitted = pumpRewardAtomic(holderRewards?.paidLamports);
    const dist = await distributeCreatorFeesToNftHolders({
      userId,
      tokenMint: claimMint,
      signer: keypair,
      totalLamports: claimedLamports,
      alreadyCommittedLamports: alreadyCommitted
    });
    nftHolderRewards = {
      enabled: Boolean(dist.enabled),
      percent: dist.enabled ? 20 : 0,
      count: dist.count || 0,
      paidLamports: String(dist.paidLamports || 0n),
      signatures: dist.signatures || [],
      campaignId: dist.campaignId || "",
      reason: dist.reason || ""
    };
  } catch (error) {
    nftHolderRewards = { enabled: true, percent: 20, error: friendlyError(error) };
    await audit("web_claim_nft_holder_rewards_failed", { userId, wallet: wallet.publicKey, rail: "pump", mint: claimMint, error: friendlyError(error) }).catch(() => {});
  }
  return { holderRewards, nftHolderRewards, claimMint };
}

async function webClaimPumpRewardsCore(userId, { walletIndex, kind, claimOperationId = "" }) {
  const walletStore = await readWalletStore();
  const wallet = getWalletAt(walletStore, walletIndex, userId);
  const operationId = String(claimOperationId || crypto.randomUUID());
  // Serialize every Pump claim for this wallet, not only claims of the same
  // kind. Creator and Cash Back claims share the WSOL destination account.
  const lockName = `pump-reward-wallet:${manualSellUserHash(userId)}:${wallet.publicKey}`;
  return LockService.withLock(lockName, 180_000, () => webClaimPumpRewardsCoreLocked(userId, {
    walletIndex,
    kind,
    operationId,
    walletStore,
    wallet
  }), () => {
    const error = new Error("This wallet already has a Pump reward claim submitting. Wait for it to finish before trying again.");
    error.statusCode = 409;
    throw error;
  });
}

async function webClaimPumpRewardsCoreLocked(userId, { walletIndex, kind, operationId, walletStore, wallet }) {
  const keypair = decryptWallet(wallet);
  const attribution = kind === "creator"
    ? await pumpCreatorRewardAttribution(userId, wallet.publicKey)
    : { dedicatedLaunch: null, protectedLaunches: [], attributionProven: false };
  const built = kind === "cashback"
    ? await buildPumpCashbackClaimInstructions({ connection, user: keypair.publicKey, feePayer: keypair.publicKey })
    : await buildPumpCreatorClaimInstructions({ connection, creator: keypair.publicKey, feePayer: keypair.publicKey });
  if (kind === "creator") {
    // Settle any durable record against this authoritative pre-claim balance
    // before a new claim can create another obligation for the same wallet.
    await reconcilePumpCreatorRewardObligations(userId, wallet.publicKey, built.balances).catch(() => {});
  }
  const beforeAtomic = pumpRewardAtomic(built.balances?.[kind]?.totalAtomic);
  if (beforeAtomic <= 0n || !built.instructions.length) {
    invalidatePumpRewardBalanceCache(userId, wallet.publicKey);
    return {
      ok: true,
      claimed: false,
      kind,
      scope: "wallet",
      walletIndex,
      wallet: wallet.publicKey,
      claimedAtomic: "0",
      claimedSol: 0,
      signatures: [],
      message: kind === "cashback" ? "No Pump Cash Back is ready for this wallet yet." : "No Pump creator rewards are ready for this wallet yet."
    };
  }

  const destinationExists = Boolean(built.wsolAccounts?.destination?.exists);
  // A missing WSOL ATA needs temporary rent in addition to the transaction
  // fee. It is closed back to SOL in the same transaction after the claim.
  const feeFloor = destinationExists ? 100_000 : 2_500_000;
  let funded = false;
  const startingSol = Number(await getSolBalanceCached(keypair.publicKey, { force: true }).catch(() => 0));
  if (startingSol < feeFloor) {
    funded = await topUpSellFees(walletStore, userId, wallet, feeFloor).catch(() => false);
    const available = Number(await getSolBalanceCached(keypair.publicKey, { force: true }).catch(() => startingSol));
    if (available < feeFloor) {
      const error = new Error("This wallet needs a little SOL for the claim transaction, and no funded sibling wallet can cover it. Send about 0.005 SOL to this wallet, then claim.");
      error.statusCode = 400;
      throw error;
    }
  }
  // Protected holder/NFT promises make a wallet-wide creator claim an
  // allocation-sensitive money operation. Persist it before the first claim
  // instruction can leave the process so a stale follow-up RPC cannot erase
  // the obligation. Current records do not prove exclusive creator-wallet use,
  // therefore the obligation is recorded but never auto-attributed to a mint.
  const obligation = kind === "creator"
    ? await createPumpCreatorRewardObligation({
        id: operationId,
        userId,
        walletIndex,
        walletPublicKey: wallet.publicKey,
        attribution,
        built
      })
    : null;
  const protectedCreatorRewards = kind === "creator"
    && Array.isArray(attribution.protectedLaunches)
    && attribution.protectedLaunches.length > 0;
  const programs = [
    { name: "pump", instruction: built.byProgram?.pump },
    { name: "pumpAmm", instruction: built.byProgram?.pumpAmm }
  ].filter((row) => row.instruction);
  const signatures = [];
  const completedPrograms = [];
  let claimError = "";
  let outcomeUnknown = false;
  for (const program of programs) {
    let persistedSigned = null;
    if (obligation) {
      await patchPumpCreatorRewardObligation(operationId, userId, {
        activeProgram: program.name,
        programs: { [program.name]: { status: "SUBMITTING", submittedAt: new Date().toISOString() } }
      });
    }
    try {
      const sent = await sendPumpRewardProgramClaim({
        keypair,
        instruction: program.instruction,
        destinationExists,
        programName: program.name,
        onSigned: obligation ? async ({ signature, blockhash, lastValidBlockHeight }) => {
          persistedSigned = { signature, blockhash, lastValidBlockHeight };
          const saved = await patchPumpCreatorRewardObligation(operationId, userId, {
            activeProgram: program.name,
            programs: {
              [program.name]: {
                status: "SUBMITTING",
                signature,
                signatures: [signature],
                blockhash,
                lastValidBlockHeight,
                signedAt: new Date().toISOString(),
                error: ""
              }
            }
          });
          if (!saved) throw new Error("Creator-reward claim receipt could not be persisted before broadcast.");
        } : null
      });
      const signature = sent.signature || "";
      if (signature) signatures.push(signature);
      completedPrograms.push(program.name);
      if (obligation) {
        await patchPumpCreatorRewardObligation(operationId, userId, {
          activeProgram: "",
          programs: {
            [program.name]: {
              status: "CONFIRMED",
              signature,
              signatures: signature ? [signature] : [],
              payoutAsset: sent.payoutAsset || "SOL",
              confirmedAt: new Date().toISOString()
            }
          }
        });
      }
    } catch (error) {
      claimError = friendlyError(error);
      outcomeUnknown = Boolean(error?.tradeSubmissionAmbiguous);
      const hashes = [...new Set([
        persistedSigned?.signature || "",
        error?.signature || "",
        ...(Array.isArray(error?.partialHashes) ? error.partialHashes : [])
      ].filter(Boolean))];
      for (const hash of hashes) if (!signatures.includes(hash)) signatures.push(hash);
      if (obligation) {
        await patchPumpCreatorRewardObligation(operationId, userId, {
          status: outcomeUnknown ? "RECONCILING" : "PARTIAL_OR_FAILED",
          activeProgram: outcomeUnknown ? program.name : "",
          programs: {
            [program.name]: {
              status: outcomeUnknown ? "RECONCILING" : "FAILED",
              signatures: hashes,
              error: claimError
            }
          }
        });
      }
      // A confirmed first program must never be replayed just because the second
      // one failed. A fresh click claims only the balance still on-chain.
      if (!completedPrograms.length && !outcomeUnknown) {
        if (obligation) await patchPumpCreatorRewardObligation(operationId, userId, { status: "FAILED", error: claimError });
        throw error;
      }
      break;
    }
  }

  invalidatePumpRewardBalanceCache(userId, wallet.publicKey);
  invalidateWalletReadCache(wallet.publicKey);
  let afterBalances = null;
  try {
    afterBalances = await getPumpRewardBalances({ connection: readConnection, wallet: wallet.publicKey, commitment: "confirmed" });
    pumpRewardBalanceCache.set(pumpRewardCacheKey(userId, wallet.publicKey), { createdAt: Date.now(), value: afterBalances });
  } catch { /* confirmed signatures remain authoritative; the UI can refresh */ }
  const afterAtomic = afterBalances ? pumpRewardAtomic(afterBalances?.[kind]?.totalAtomic) : beforeAtomic;
  const observedDeltaAtomic = beforeAtomic > afterAtomic ? beforeAtomic - afterAtomic : 0n;
  const expectedByProgram = {
    pump: kind === "creator"
      ? pumpRewardAtomic(built.balances?.creator?.curveLamports)
      : pumpRewardAtomic(built.balances?.cashback?.curveLamports),
    pumpAmm: kind === "creator"
      ? pumpRewardAtomic(built.balances?.creator?.ammWsolAtomic)
      : pumpRewardAtomic(built.balances?.cashback?.ammWsolAtomic)
  };
  const confirmedAtomic = completedPrograms.reduce((sum, name) => sum + (expectedByProgram[name] || 0n), 0n);
  // sendLegacyTransaction returns only after confirmation. Preserve the exact
  // pre-submit amount for every confirmed program even when the post-claim RPC
  // is stale or unavailable.
  const claimedAtomic = observedDeltaAtomic > confirmedAtomic ? observedDeltaAtomic : confirmedAtomic;
  const partial = completedPrograms.length < programs.length || outcomeUnknown;
  if (obligation) {
    const latest = await patchPumpCreatorRewardObligation(operationId, userId, {
      status: outcomeUnknown
        ? "RECONCILING"
        : (claimedAtomic > 0n
            ? (protectedCreatorRewards ? "MANUAL_ATTRIBUTION_REQUIRED" : "CONFIRMED_WALLET_CLAIM")
            : "NO_CONFIRMED_CLAIM"),
      confirmedAtomic: confirmedAtomic.toString(),
      observedDeltaAtomic: observedDeltaAtomic.toString(),
      claimedAtomic: claimedAtomic.toString(),
      remainingAtomic: afterAtomic.toString(),
      remainingAtomicKnown: Boolean(afterBalances),
      signatures,
      distributionStatus: protectedCreatorRewards
        ? "SKIPPED_UNPROVEN_WALLET_WIDE_ATTRIBUTION"
        : "NOT_APPLICABLE",
      error: claimError
    });
    if (latest && pumpRewardAtomic(latest.distributedAtomic) !== 0n) {
      throw new Error("Protected Pump creator rewards have an unexpected prior distribution state.");
    }
  }
  // A wallet-wide creator vault cannot prove which mint generated a claim.
  // Keep protected holder/NFT obligations durable and unallocated instead of
  // guessing and potentially paying unrelated creator earnings to one coin.
  const distributions = obligation
    ? {
        holderRewards: attribution.protectedLaunches.some((row) => row.holderRewards)
          ? { enabled: true, skipped: true, reason: "wallet_wide_attribution_unproven", obligationId: operationId }
          : null,
        nftHolderRewards: attribution.protectedLaunches.some((row) => row.nftRewards)
          ? { enabled: true, skipped: true, reason: "wallet_wide_attribution_unproven", obligationId: operationId }
          : null
      }
    : { holderRewards: null, nftHolderRewards: null };
  const pumpNativeAtomic = completedPrograms.includes("pump") ? expectedByProgram.pump : 0n;
  const ammClaimedAtomic = completedPrograms.includes("pumpAmm") ? expectedByProgram.pumpAmm : 0n;
  const nativeSolAtomic = pumpNativeAtomic + (destinationExists ? 0n : ammClaimedAtomic);
  const wsolAtomic = destinationExists ? ammClaimedAtomic : 0n;
  const payoutAsset = wsolAtomic > 0n && nativeSolAtomic > 0n
    ? "SOL_AND_WSOL"
    : (wsolAtomic > 0n ? "WSOL" : "SOL");
  const result = {
    ok: true,
    claimed: claimedAtomic > 0n || signatures.length > 0,
    kind,
    scope: "wallet",
    walletIndex,
    wallet: wallet.publicKey,
    beforeAtomic: beforeAtomic.toString(),
    remainingAtomic: afterAtomic.toString(),
    claimedAtomic: claimedAtomic.toString(),
    claimedSol: pumpRewardSol(claimedAtomic),
    nativeSolAtomic: nativeSolAtomic.toString(),
    nativeSol: pumpRewardSol(nativeSolAtomic),
    wsolAtomic: wsolAtomic.toString(),
    wsol: pumpRewardSol(wsolAtomic),
    payoutAsset,
    payoutNote: payoutAsset === "SOL"
      ? "Claimed rewards reached native SOL."
      : "PumpSwap rewards remain WSOL because this wallet already had a WSOL account; SlimeWire did not close or alter that pre-existing account.",
    signatures,
    signature: signatures.at(-1) || "",
    completedPrograms,
    partial,
    outcomeUnknown,
    funded,
    protectedDistributionDeferred: protectedCreatorRewards,
    creatorRewardObligationId: obligation?.id || "",
    holderRewards: distributions.holderRewards,
    nftHolderRewards: distributions.nftHolderRewards,
    ...(claimError ? { error: claimError } : {})
  };
  await audit(`web_claim_pump_${kind}`, {
    userId,
    wallet: wallet.publicKey,
    walletIndex,
    beforeAtomic: beforeAtomic.toString(),
    remainingAtomic: afterAtomic.toString(),
    claimedAtomic: claimedAtomic.toString(),
    signatures,
    completedPrograms,
    partial,
    outcomeUnknown,
    funded,
    payoutAsset,
    nativeSolAtomic: nativeSolAtomic.toString(),
    wsolAtomic: wsolAtomic.toString(),
    protectedDistributionDeferred: protectedCreatorRewards,
    creatorRewardObligationId: obligation?.id || ""
  }).catch(() => {});
  return result;
}

async function webClaimCreatorFees(userId, body = {}) {
  return runIdempotentMoneyOp("web-claim-fees", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    () => webClaimCreatorFeesCore(userId, body),
    { busyMessage: "A fee claim is already in flight for this wallet — give it a moment." });
}
async function webClaimCreatorFeesCore(userId, body = {}) {
  const store = await readWalletStore();
  const wallet = getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId);
  const keypair = decryptWallet(wallet);
  const rail = String(body.rail || "pump").toLowerCase();
  if (["robinhood", "rh", "sushi"].includes(rail)) {
    const mint = String(body.mint || body.tokenAddress || "").trim().toLowerCase();
    const launchStore = await readPumpLaunchAttempts().catch(() => ({ attempts: [] }));
    const launch = (launchStore.attempts || []).slice().reverse().find((attempt) => {
      const attemptMint = firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint).toLowerCase();
      return String(attempt.userId || "") === String(userId)
        && String(attempt.rail || "").toLowerCase() === "robinhood"
        && (!mint || attemptMint === mint)
        && String(attempt.devWalletPublicKey || "") === String(wallet.publicKey || "");
    });
    if (!launch?.rhLiquidityLocker || launch?.rhTokenId == null || launch?.rhTokenId === "") {
      const error = new Error("This launch does not have a locked Sushi position to collect yet.");
      error.statusCode = 400;
      throw error;
    }
    const claim = await rhCollectSushiPositionFees({
      solanaSecretKey: keypair.secretKey,
      lockerAddress: launch.rhLiquidityLocker,
      tokenId: launch.rhTokenId,
      rpcUrl: CONFIG.rhChainRpcUrl,
    });
    const checkedAt = new Date().toISOString();
    await upsertPumpLaunchAttempt({
      id: String(launch.id || launch.launchAttemptId || ""),
      rhPoolFeesAutoClaimAt: claim.claimed ? checkedAt : firstString(launch.rhPoolFeesAutoClaimAt),
      rhPoolFeesAutoClaimCheckedAt: checkedAt,
      rhPoolFeesAutoClaimStatus: claim.claimed ? "claimed" : "nothing_to_claim",
      rhPoolFeesAutoClaimSignature: claim.txHash || "",
      rhPoolFeesAmount0: claim.amount0 || "0",
      rhPoolFeesAmount1: claim.amount1 || "0",
      rhPoolFeesAutoClaimError: "",
    });
    await audit("web_claim_rh_sushi_fees", {
      userId,
      wallet: wallet.publicKey,
      mint: firstString(launch.mintPublicKey, launch.tokenMint, launch.mint),
      tokenId: String(launch.rhTokenId),
      claimed: Boolean(claim.claimed),
      amount0: claim.amount0 || "0",
      amount1: claim.amount1 || "0",
      signature: claim.txHash || "",
    }).catch(() => {});
    return {
      ok: true,
      claimed: Boolean(claim.claimed),
      signature: claim.txHash || "",
      amount0: claim.amount0 || "0",
      amount1: claim.amount1 || "0",
      wallet: wallet.publicKey,
      rail: "robinhood",
    };
  }
  if (rail === "pump") {
    const claim = await webClaimPumpRewardsCore(userId, {
      walletIndex: parseWebWalletIndex(body.walletIndex),
      kind: "creator"
    });
    await markPumpWalletCreatorClaimOnLaunches(userId, wallet.publicKey, claim);
    return { ...claim, rail: "pump" };
  }
  const payload = { publicKey: keypair.publicKey.toBase58(), action: "collectCreatorFee", priorityFee: CONFIG.pumpLaunchPriorityFeeSol || 0.000005 };
  if (rail === "meteora") { payload.pool = "meteora-dbc"; if (body.mint) payload.mint = parsePublicKey(String(body.mint)).toBase58(); }
  else if (body.mint) { payload.pool = "pump"; payload.mint = parsePublicKey(String(body.mint)).toBase58(); }

  // Creator wallets are almost always swept to ~0 after launch, so the claim tx has no SOL to pay its
  // OWN network fee — it fails simulation with "Attempt to debit an account but found no record of a
  // prior credit". So: proactively move a sliver of SOL in from a funded sibling first, and retry once
  // if the send still trips the fee error. Claims go via plain RPC (no Jito tip) — a claim needs no MEV
  // protection, and the tip would just demand more SOL up front.
  const FEE_FLOOR = 1_500_000; // 0.0015 SOL — plenty for a plain-RPC priority-fee'd claim (no Jito tip)
  let toppedUp = false;
  const startBal = Number(await getSolBalanceCached(keypair.publicKey, { force: true }).catch(() => 0));
  if (startBal < FEE_FLOOR) toppedUp = await topUpSellFees(store, userId, wallet, FEE_FLOOR).catch(() => false);

  // Build → sign → send one claim attempt. `before` is captured AFTER any top-up so the reported
  // claimedSol reflects only fees collected (minus this tx's fee), not the sibling top-up.
  const doClaim = async () => {
    const tx = await requestPumpPortalLocalTransaction(payload, 20_000, { url: CONFIG.pumpPortalTradeLocalUrl });
    invalidateWalletReadCache(wallet.publicKey);
    const before = Number(await getSolBalanceCached(keypair.publicKey, { force: true }).catch(() => 0));
    let signature;
    if (tx?.signature) signature = tx.signature;
    else { tx.sign([keypair]); signature = await sendVersionedTransaction(tx, "collect creator fees"); }
    return { signature, before };
  };

  let result;
  try {
    result = await doClaim();
  } catch (error) {
    if (isInsufficientFeeError(error)) {
      if (!toppedUp) toppedUp = await topUpSellFees(store, userId, wallet).catch(() => false);
      if (!toppedUp) {
        const e = new Error("This creator wallet has no SOL to pay the claim's network fee, and no other wallet has SOL to cover it. Send a little SOL (~0.01) to this wallet, then claim.");
        e.statusCode = 400; throw e;
      }
      invalidateWalletReadCache(wallet.publicKey);
      try { result = await doClaim(); }
      catch (retryError) {
        const e = new Error(isInsufficientFeeError(retryError)
          ? "Funded the wallet but the claim still couldn't pay its fee — try again in a moment."
          : `Nothing to claim right now (or pump rejected the claim): ${friendlyError(retryError)}`);
        e.statusCode = 400; throw e;
      }
    } else {
      const e = new Error(`Nothing to claim right now (or pump rejected the claim): ${friendlyError(error)}`);
      e.statusCode = 400; throw e;
    }
  }

  const { signature, before } = result;
  invalidateWalletReadCache(wallet.publicKey);
  const after = Number(await getSolBalanceCached(keypair.publicKey, { force: true }).catch(() => before));
  const claimedSol = lamportsToSol(Math.max(0, after - before));
  let holderRewards = null;
  let nftHolderRewards = null;
  const claimMint = String(body.mint || "").trim();
  if (claimMint) {
    const rewardLaunch = await holderRewardLaunchAttemptForMint(claimMint, rail, userId).catch(() => null);
    const policy = rewardLaunch ? launchHolderRewardsFromAttempt(rewardLaunch) : { enabled: false };
    if (policy?.enabled) {
      try {
        const claimedLamports = BigInt(Math.max(0, Math.floor(Number(claimedSol || 0) * LAMPORTS_PER_SOL)));
        const priorPendingLamports = BigInt(String(rewardLaunch?.holderRewardsPendingLamports || "0").replace(/[^\d]/g, "") || "0");
        const dist = await distributeSolHolderRewards({
          signer: keypair,
          tokenMint: claimMint,
          policy,
          totalLamports: claimedLamports,
          pendingLamports: priorPendingLamports
        });
        holderRewards = {
          enabled: true,
          shareBps: policy.shareBps,
          count: dist.count || 0,
          paidLamports: String(dist.paidLamports || 0n),
          pendingLamports: String(dist.pendingLamports || 0n),
          accruedLamports: String(dist.accruedLamports || 0n),
          signature: dist.signature || "",
          signatures: dist.signatures || [],
          reason: dist.reason || "",
          error: dist.error || ""
        };
        const rewardLaunchId = String(rewardLaunch?.id || rewardLaunch?.launchAttemptId || "");
        if (rewardLaunchId) {
          const priorPaidLamports = BigInt(String(rewardLaunch?.holderRewardsPaidLamports || "0").replace(/[^\d]/g, "") || "0");
          const priorAccruedLamports = BigInt(String(rewardLaunch?.holderRewardsAccruedLamports || "0").replace(/[^\d]/g, "") || "0");
          await upsertPumpLaunchAttempt({
            id: rewardLaunchId,
            holderRewardsPendingLamports: String(dist.pendingLamports || 0n),
            holderRewardsPaidLamports: String(priorPaidLamports + BigInt(dist.paidLamports || 0n)),
            holderRewardsAccruedLamports: String(priorAccruedLamports + BigInt(dist.accruedLamports || 0n)),
            holderRewardsLastPayoutAt: dist.paidLamports > 0n ? new Date().toISOString() : firstString(rewardLaunch?.holderRewardsLastPayoutAt),
            holderRewardsLastPayoutSignature: dist.signature || firstString(rewardLaunch?.holderRewardsLastPayoutSignature),
            holderRewardsLastPayoutCount: dist.count || 0,
            holderRewardsAutoClaimStatus: dist.paidLamports > 0n ? "paid" : dist.reason || "accumulating",
            holderRewardsLastError: dist.error || ""
          });
        }
      } catch (error) {
        holderRewards = { enabled: true, error: friendlyError(error) };
        await audit("web_claim_holder_rewards_failed", { userId, wallet: wallet.publicKey, rail, mint: claimMint, error: friendlyError(error) }).catch(() => {});
      }
    }
  }
  if (claimMint && rail !== "robinhood") {
    try {
      const claimedLamports = BigInt(Math.max(0, Math.floor(Number(claimedSol || 0) * LAMPORTS_PER_SOL)));
      const alreadyCommitted = BigInt(holderRewards?.paidLamports || 0);
      const dist = await distributeCreatorFeesToNftHolders({ userId, tokenMint: claimMint, signer: keypair, totalLamports: claimedLamports, alreadyCommittedLamports: alreadyCommitted });
      nftHolderRewards = {
        enabled: Boolean(dist.enabled),
        percent: dist.enabled ? 20 : 0,
        count: dist.count || 0,
        paidLamports: String(dist.paidLamports || 0n),
        signatures: dist.signatures || [],
        campaignId: dist.campaignId || "",
        reason: dist.reason || ""
      };
    } catch (error) {
      nftHolderRewards = { enabled: true, percent: 20, error: friendlyError(error) };
      await audit("web_claim_nft_holder_rewards_failed", { userId, wallet: wallet.publicKey, rail, mint: claimMint, error: friendlyError(error) }).catch(() => {});
    }
  }
  await audit("web_claim_creator_fees", { userId, wallet: wallet.publicKey, rail, mint: body.mint || "", signature, claimedSol, toppedUp, holderRewards, nftHolderRewards });
  if (rail === "pump" && claimMint) {
    const launchStore = await readPumpLaunchAttempts().catch(() => ({ attempts: [] }));
    const launch = (launchStore.attempts || []).slice().reverse().find((attempt) => (
      String(attempt.userId || "") === String(userId)
      && firstString(attempt.mintPublicKey, attempt.tokenMint, attempt.mint) === claimMint
    ));
    const launchId = String(launch?.id || launch?.launchAttemptId || "");
    if (launchId) {
      await upsertPumpLaunchAttempt({
        id: launchId,
        creatorFeesAutoClaimAt: new Date().toISOString(),
        creatorFeesAutoClaimCheckedAt: new Date().toISOString(),
        creatorFeesAutoClaimPendingVolumeSol: 0,
        creatorFeesAutoClaimStatus: "claimed",
        creatorFeesAutoClaimSignature: signature || "",
        creatorFeesAutoClaimSol: Number(claimedSol || 0),
        creatorFeesAutoClaimError: ""
      });
    }
  }
  return { ok: true, signature, claimedSol, wallet: wallet.publicKey, rail, funded: toppedUp, holderRewards, nftHolderRewards };
}

// ---------- Robinhood Chain (EVM) launch rail ----------
// No launchpad exists on Robinhood Chain, so WE deploy the token: a fixed-supply, no-owner ERC-20
// (src/lib/robinhoodChain.js). Each SlimeWire wallet gets a deterministic EVM address derived from its
// existing key — the user bridges a little ETH to it, then launches. Gas is estimated BEFORE sending,
// so a broken or underfunded launch costs nothing.
async function webRhWallet(userId, walletIndex) {
  const store = await readWalletStore();
  const wallet = getWalletAt(store, parseWebWalletIndex(walletIndex), userId);
  const keypair = decryptWallet(wallet);
  const address = evmAddressFromSolana(keypair.secretKey);
  const [bal, tokens, scan] = await Promise.all([
    rhEthBalance(address, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0", wei: "0" })),
    rhAddressTokens(address),
    rhWalletScan(address, { rpcUrl: CONFIG.rhChainRpcUrl }).catch(() => null)
  ]);
  const holdingByAddress = new Map((scan?.holdings || []).map((holding) => [String(holding.addr || "").toLowerCase(), holding]));
  const valuedTokens = tokens.map((token) => {
    const holding = holdingByAddress.get(String(token.address || "").toLowerCase());
    const costUsd = Number(holding?.costUsd);
    const valueUsd = Number(holding?.valueUsd);
    const pnlUsd = Number(holding?.pnlUsd);
    return {
      ...token,
      valueUsd: Number.isFinite(valueUsd) && valueUsd >= 0 ? valueUsd : null,
      costUsd: Number.isFinite(costUsd) && costUsd > 0 ? costUsd : null,
      pnlUsd: Number.isFinite(pnlUsd) && costUsd > 0 ? pnlUsd : null,
      pnlPercent: Number.isFinite(pnlUsd) && costUsd > 0 ? (pnlUsd / costUsd) * 100 : null
    };
  });
  return {
    ok: true,
    chainId: RH_CHAIN_ID,
    address,
    eth: bal.eth,
    tokens: valuedTokens,
    pnlAvailable: Boolean(scan?.hasPnl),
    pnlPartial: Boolean(scan?.pnlPartial),
    explorer: rhExplorerAddress(address),
    wallet: wallet.publicKey,
    automaticLaunch: rhSushiLaunchConfigured(CONFIG.rhSushiLaunchFactoryAddress),
    launchVenue: "SushiSwap V3"
  };
}

async function webRhBalanceRows(userId, walletIndexValue = "") {
  const store = await readWalletStore();
  const requestedIndex = String(walletIndexValue || "").trim()
    ? parseWebWalletIndex(walletIndexValue)
    : null;
  const wallets = walletsForOwner(store, userId)
    .map((wallet, ownerIndex) => ({ wallet, walletIndex: ownerIndex + 1 }))
    .filter(({ wallet, walletIndex }) => !wallet.volumeBot && !wallet.ephemeral && (!requestedIndex || walletIndex === requestedIndex));
  if (requestedIndex && !wallets.length) {
    const error = new Error("That wallet does not exist.");
    error.statusCode = 404;
    throw error;
  }
  if (!wallets.length) {
    return { ok: true, wallets: [], ethUsd: await rhEthUsd().catch(() => 0) };
  }
  const rows = await runWithConcurrency(wallets, Math.min(5, wallets.length), async ({ wallet, walletIndex }) => {
    const keypair = decryptWallet(wallet);
    const address = evmAddressFromSolana(keypair.secretKey);
    try {
      const balance = await rhEthBalance(address, CONFIG.rhChainRpcUrl);
      return {
        walletIndex,
        label: wallet.label || `Wallet ${walletIndex}`,
        wallet: wallet.publicKey,
        address,
        eth: balance.eth,
        explorer: rhExplorerAddress(address),
        available: true
      };
    } catch (error) {
      return {
        walletIndex,
        label: wallet.label || `Wallet ${walletIndex}`,
        wallet: wallet.publicKey,
        address,
        eth: null,
        explorer: rhExplorerAddress(address),
        available: false,
        error: friendlyError(error).slice(0, 160)
      };
    }
  });
  const ethUsd = await rhEthUsd().catch(() => 0);
  return { ok: true, wallets: rows, ethUsd };
}

async function webRhWallets(userId) {
  const [store, rhHistory, launchStore] = await Promise.all([
    readWalletStore(),
    readRhTradeHistory().catch(() => ({ trades: [] })),
    readPumpLaunchAttempts().catch(() => ({ attempts: [] }))
  ]);
  const wallets = walletsForOwner(store, userId)
    .map((wallet, ownerIndex) => ({ wallet, walletIndex: ownerIndex + 1 }))
    .filter(({ wallet }) => !wallet.volumeBot && !wallet.ephemeral);
  // Blockscout's token-balance index can trail a brand-new launch by minutes. Keep a small per-wallet
  // candidate set from our own confirmed trades/launches, then verify those balances directly over RPC.
  // This makes every successful bundle wallet appear immediately without inventing holdings: a row is
  // added only when balanceOf() confirms a positive balance on-chain.
  const candidatesByWallet = new Map();
  const remember = (walletPublicKey, tokenAddress, meta = {}) => {
    const walletKey = String(walletPublicKey || "");
    const address = String(tokenAddress || "");
    if (!walletKey || !/^0x[0-9a-fA-F]{40}$/.test(address)) return;
    let byAddress = candidatesByWallet.get(walletKey);
    if (!byAddress) candidatesByWallet.set(walletKey, byAddress = new Map());
    const key = address.toLowerCase();
    if (!byAddress.has(key) && byAddress.size < 40) byAddress.set(key, { address, ...meta });
  };
  for (const trade of [...(rhHistory.trades || [])].reverse()) {
    if (String(trade.userId || "") !== String(userId)) continue;
    remember(trade.walletPublicKey, firstString(trade.tokenAddress, trade.tokenMint), {
      symbol: String(trade.symbol || ""), name: String(trade.name || "")
    });
  }
  for (const launch of [...(launchStore.attempts || [])].reverse()) {
    if (String(launch.userId || "") !== String(userId) || String(launch.rail || "") !== "robinhood") continue;
    remember(launch.devWalletPublicKey, firstString(launch.mintPublicKey, launch.tokenAddress, launch.mint), {
      symbol: String(launch.symbol || ""), name: String(launch.tokenName || "")
    });
  }
  const rows = await runWithConcurrency(wallets, Math.min(5, wallets.length), async ({ wallet, walletIndex }) => {
    try {
      const keypair = decryptWallet(wallet);
      const address = evmAddressFromSolana(keypair.secretKey);
      const [bal, indexedTokens] = await Promise.all([
        rhEthBalance(address, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0", wei: "0" })),
        rhAddressTokens(address).catch(() => [])
      ]);
      const tokensByAddress = new Map((indexedTokens || [])
        .filter((token) => /^0x[0-9a-fA-F]{40}$/.test(String(token.address || "")))
        .map((token) => [String(token.address).toLowerCase(), token]));
      const candidates = [...(candidatesByWallet.get(wallet.publicKey)?.values() || [])];
      const live = await runWithConcurrency(candidates, Math.min(5, candidates.length), async (candidate) => {
        const holding = await rhErc20Balance(candidate.address, address, CONFIG.rhChainRpcUrl).catch(() => null);
        if (!holding || !(Number(holding.uiAmount) > 0)) return null;
        const indexed = tokensByAddress.get(candidate.address.toLowerCase()) || {};
        return { ...candidate, ...indexed, ...holding, address: candidate.address };
      });
      for (const token of live) if (token) tokensByAddress.set(String(token.address).toLowerCase(), token);
      const tokens = [...tokensByAddress.values()].filter((token) => Number(token.uiAmount || 0) > 0);
      return { walletIndex, label: wallet.label || `Wallet ${walletIndex}`, wallet: wallet.publicKey, address, eth: bal.eth, tokens, explorer: rhExplorerAddress(address) };
    } catch (error) {
      return { walletIndex, label: wallet.label || `Wallet ${walletIndex}`, wallet: wallet.publicKey, address: "", eth: "0", tokens: [], error: friendlyError(error).slice(0, 160) };
    }
  });
  return { ok: true, wallets: rows };
}

async function webRhSendToken(userId, body = {}) {
  return runIdempotentMoneyOp(
    "web-rh-send-token",
    userId,
    firstString(body.sendAttemptId, body.transferAttemptId, body.clientRequestId),
    () => webRhSendTokenCore(userId, body),
    { busyMessage: "This Robinhood token send is already being submitted. SlimeWire will not send it twice." }
  );
}

const RH_ETH_SEND_RESERVE_WEI = 50_000_000_000_000n; // 0.00005 ETH, retained for one recovery/network action.

async function webRhSendEthPlan(userId, body = {}) {
  const store = await readWalletStore();
  const walletIndex = parseWebWalletIndex(body.walletIndex || body.fromWalletIndex);
  const wallet = assertServerSignableWallet(assertFrozenManagedWallet(
    getWalletAt(store, walletIndex, userId),
    body.walletPublicKey || body.sourcePublicKey,
    "Robinhood ETH send"
  ), "send Robinhood ETH from");
  const keypair = decryptWallet(wallet);
  const sourceAddress = evmAddressFromSolana(keypair.secretKey);
  const destination = String(body.destination || body.destinationWallet || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(destination)) throw new Error("Enter a valid Robinhood Chain wallet address.");
  if (sourceAddress.toLowerCase() === destination.toLowerCase()) throw new Error("That destination is this wallet.");
  const balance = await rhEthBalance(sourceAddress, CONFIG.rhChainRpcUrl);
  const balanceWei = positiveBigIntOrZero(balance.wei);
  const sendAll = body.sendAll === true || String(body.sendAll || body.amountEth || "").trim().toLowerCase() === "all";
  const amountWei = sendAll
    ? balanceWei - RH_ETH_SEND_RESERVE_WEI
    : parseCashDecimalToRaw(body.amountEth ?? body.amount, 18, "ETH amount");
  if (amountWei <= 0n) throw new Error("Not enough Robinhood ETH to send after the protected network reserve.");
  if (amountWei + RH_ETH_SEND_RESERVE_WEI > balanceWei) {
    throw new Error(`Not enough Robinhood ETH. This wallet has ${balance.eth} ETH and keeps 0.00005 ETH available for network recovery.`);
  }
  return { walletIndex, wallet, keypair, sourceAddress, destination, balanceWei, amountWei, sendAll };
}

async function webRhSendEth(userId, body = {}) {
  return runIdempotentMoneyOp(
    "web-rh-send-eth",
    userId,
    firstString(body.sendAttemptId, body.transferAttemptId, body.tradeAttemptId, body.clientRequestId),
    () => webRhSendEthCore(userId, body),
    { busyMessage: "This Robinhood ETH send is already being submitted. SlimeWire will not send it twice." }
  );
}

async function webRhSendEthCore(userId, body = {}) {
  const plan = body._rhEthSendPlan || await webRhSendEthPlan(userId, body);
  const signature = await rhTransferEth(plan.keypair.secretKey, plan.destination, plan.amountWei, CONFIG.rhChainRpcUrl);
  const amountEth = rawCashAmountToUi(plan.amountWei, 18);
  const explorerUrl = `https://robinhoodchain.blockscout.com/tx/${signature}`;
  await audit("web_rh_send_eth", {
    userId,
    walletIndex: plan.walletIndex,
    wallet: plan.wallet.publicKey,
    sourceAddress: plan.sourceAddress,
    destination: plan.destination,
    amountEth,
    rawAmount: plan.amountWei.toString(),
    signature
  });
  return {
    ok: true,
    action: "send-eth",
    asset: "ETH",
    chain: "robinhood",
    sourceAddress: plan.sourceAddress,
    destination: plan.destination,
    amountEth,
    rawAmount: plan.amountWei.toString(),
    signature,
    explorerUrl,
    summary: `Sent ${amountEth} ETH to ${shortMint(plan.destination)} on Robinhood Chain.`
  };
}

async function webRhSendTokenCore(userId, body = {}) {
  const store = await readWalletStore();
  const walletIndex = parseWebWalletIndex(body.walletIndex || body.fromWalletIndex);
  const wallet = assertServerSignableWallet(assertFrozenManagedWallet(
    getWalletAt(store, walletIndex, userId),
    body.walletPublicKey || body.sourcePublicKey,
    "Robinhood token send"
  ), "send Robinhood tokens from");
  const keypair = decryptWallet(wallet);
  const sourceAddress = evmAddressFromSolana(keypair.secretKey);
  const tokenAddress = String(body.tokenAddress || body.tokenMint || "").trim();
  const destination = String(body.destination || body.destinationWallet || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) throw new Error("Enter a valid Robinhood token address.");
  if (!/^0x[0-9a-fA-F]{40}$/.test(destination)) throw new Error("Enter a valid Robinhood Chain wallet address.");
  if (sourceAddress.toLowerCase() === destination.toLowerCase()) throw new Error("That destination is this wallet.");
  const balance = await rhErc20Balance(tokenAddress, sourceAddress, CONFIG.rhChainRpcUrl);
  const totalRaw = positiveBigIntOrZero(balance.raw);
  if (totalRaw <= 0n) throw new Error("This wallet no longer holds that token.");
  const percent = Number(body.percent || 0);
  let amountRaw;
  if (Number.isFinite(percent) && percent > 0) {
    if (percent > 100) throw new Error("Choose a token percentage from 1 to 100.");
    amountRaw = percent === 100 ? totalRaw : (totalRaw * BigInt(Math.round(percent * 100))) / 10_000n;
  } else {
    amountRaw = parseCashDecimalToRaw(body.amount, balance.decimals, "token amount");
  }
  if (amountRaw <= 0n) throw new Error("The selected amount is below this token's smallest unit.");
  if (amountRaw > totalRaw) throw new Error("That amount is greater than this wallet's token balance.");
  const signature = await rhTransferErc20(keypair.secretKey, tokenAddress, destination, amountRaw, CONFIG.rhChainRpcUrl);
  const amount = rawCashAmountToUi(amountRaw, balance.decimals);
  await audit("web_rh_send_token", {
    userId,
    walletIndex: parseWebWalletIndex(body.walletIndex),
    wallet: wallet.publicKey,
    sourceAddress,
    destination,
    tokenAddress,
    rawAmount: amountRaw.toString(),
    amount,
    signature
  });
  return {
    action: "send-token",
    chain: "robinhood",
    sourceAddress,
    destination,
    tokenAddress,
    amount,
    rawAmount: amountRaw.toString(),
    signature,
    explorerUrl: `https://robinhoodchain.blockscout.com/tx/${signature}`,
    summary: `Sent ${amount} tokens to ${shortMint(destination)}.`
  };
}

// Plain-English Robinhood activity trail for this user — every buy / sell / auto-sell / SOL-funding,
// newest first, with the ETH that moved and a Blockscout link. This is the "where did my money go"
// answer: an auto-sell puts ETH BACK in the same wallet, and this shows the exact tx + amount.
async function webRhActivity(userId) {
  const [history, auditLog] = await Promise.all([
    readRhTradeHistory().catch(() => ({ trades: [] })),
    readJson(auditPath()).catch(() => ({ entries: [] }))
  ]);
  const txUrl = (h) => (h ? `https://robinhoodchain.blockscout.com/tx/${h}` : "");
  const rows = [];
  const tradeSignatures = new Set();
  for (const trade of history.trades || []) {
    if (String(trade.userId || "") !== String(userId)) continue;
    const side = String(trade.type || "").toLowerCase();
    if (!['buy', 'sell'].includes(side)) continue;
    const signature = String(trade.signature || "");
    if (signature) tradeSignatures.add(signature);
    const tokenAmount = trade.tokenUiAmount != null && String(trade.tokenUiAmount).trim() !== ""
      ? String(trade.tokenUiAmount)
      : null;
    const amountEth = trade.rhEthAmount != null && String(trade.rhEthAmount).trim() !== ""
      ? String(trade.rhEthAmount)
      : null;
    const amountSol = side === "buy" && positiveBigIntOrZero(trade.solLamportsSpent) > 0n
      ? lamportsBigToSol(positiveBigIntOrZero(trade.solLamportsSpent))
      : side === "sell" && positiveBigIntOrZero(trade.solLamportsReceived) > 0n
        ? lamportsBigToSol(positiveBigIntOrZero(trade.solLamportsReceived))
        : null;
    const symbol = String(trade.symbol || "");
    rows.push({
      at: trade.timestamp || trade.createdAt || "",
      kind: side,
      side,
      chain: "robinhood",
      tokenAddress: firstString(trade.tokenAddress, trade.tokenMint),
      symbol,
      walletPublicKey: String(trade.walletPublicKey || ""),
      walletIndex: Number.parseInt(trade.walletIndex || 0, 10) || null,
      tokenAmount,
      amountEth,
      amountSol,
      inputAmount: side === "buy" ? (amountSol ?? amountEth) : tokenAmount,
      inputSymbol: side === "buy" ? (amountSol != null ? "SOL" : "ETH") : symbol,
      outputAmount: side === "buy" ? tokenAmount : (amountSol ?? amountEth),
      outputSymbol: side === "buy" ? symbol : (amountSol != null ? "SOL" : "ETH"),
      source: formatTradeSource(trade.source || "web_rh_trade"),
      tx: signature,
      url: txUrl(signature)
    });
  }
  for (const e of (auditLog.entries || [])) {
    const d = e.details || {};
    if (String(d.userId || "") !== String(userId)) continue;
    if (e.action === "web_rh_trade") {
      const h = Array.isArray(d.txHashes) ? d.txHashes[d.txHashes.length - 1] : "";
      if (!h || !tradeSignatures.has(h)) {
        rows.push({ at: e.timestamp, kind: d.side === "buy" ? "buy" : "sell", side: d.side === "buy" ? "buy" : "sell", chain: "robinhood", tokenAddress: d.tokenAddress || "", out: d.out || "", amountEth: d.out || null, source: formatTradeSource(d.source || "web_rh_trade"), tx: h, url: txUrl(h) });
      }
    } else if (e.action === "web_rh_guard_fired") {
      const h = (d.tx || [])[(d.tx || []).length - 1] || "";
      const confirmed = h ? rows.find((row) => row.tx === h) : null;
      if (confirmed) {
        confirmed.kind = "auto-sell";
        confirmed.trigger = d.trigger || "";
        confirmed.movePct = d.movePct || "";
      } else {
        rows.push({ at: e.timestamp, kind: "auto-sell", trigger: d.trigger || "", tokenAddress: d.tokenAddress || "", movePct: d.movePct || "", tx: h, url: txUrl(h) });
      }
    } else if (e.action === "web_rh_fund_sol") {
      rows.push({ at: e.timestamp, kind: "fund", amountSol: d.amountSol || "", quotedEth: d.outEthQuoted || d.quotedEth || "", tx: d.signature || "", url: d.signature ? `https://solscan.io/tx/${d.signature}` : "" });
    } else if (e.action === "web_rh_bridge_sol") {
      const h = Array.isArray(d.hashes) ? d.hashes[d.hashes.length - 1] : "";
      rows.push({ at: e.timestamp, kind: "cashout", sentEth: d.sentEth || "", outSol: d.outSol || "", tx: h, url: txUrl(h) });
    } else if (e.action === "web_rh_send_eth") {
      rows.push({ at: e.timestamp, kind: "send", sentEth: d.amountEth || "", destination: d.destination || "", tx: d.signature || "", url: txUrl(d.signature) });
    } else if (e.action === "web_rh_launch") {
      rows.push({ at: e.timestamp, kind: "launch", tokenAddress: d.token || "", tx: d.tx || "", url: txUrl(d.tx) });
    }
  }
  // Enrich sells/auto-sells with the coin symbol from the feed cache (best-effort, no extra chain calls).
  const symByAddr = new Map(rhFeedCache.tokens.map((t) => [t.address.toLowerCase(), t.symbol]));
  for (const r of rows) if (r.tokenAddress) r.symbol = symByAddr.get(r.tokenAddress.toLowerCase()) || r.symbol || "";
  rows.sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
  return { ok: true, activity: rows.slice(0, 50) };
}

// ---------- Robinhood Chain coin feed (Trenches "🪶 Robinhood" tab) ----------
// No DexScreener/Gecko coverage for chain 4663 yet — the feed comes from the chain's own Blockscout:
// trending = 24h volume desc (then mcap/holders), new = creation time desc (lazily resolved + cached,
// creation never changes). Coins launched THROUGH SlimeWire are enriched from our own metadata
// registry (image/socials/description captured at launch) — EVM tokens have no native PFP standard,
// so the site plays the address->logo registry role that wallets/DEXes play on other chains.
// Infra / non-memecoin symbols to hide (stablecoins, wrapped ETH, LP-position NFTs). The official
// Robinhood tokenized STOCKS are hidden separately by their cdn.robinhood.com / coingecko icon — this
// board is memecoins only. Symbol-matched, case-insensitive.
const RH_FEED_HIDE = new Set(["weth", "usdg", "pusdg", "arcusdg", "usde", "susde", "uni-v3-pos", "wsteth", "usdc", "usdt", "dai"]);
const rhIsStockOrBluechip = (iconUrl) => /robinhood\.com|coingecko/i.test(String(iconUrl || ""));

// FULL token universe, refreshed in the background (Blockscout has 1400+ ERC-20s — pulling only a few
// pages made the board "light"). Paginate everything once, cache ~4 min, serve stale while refreshing so
// requests never block on the ~40-call sweep. Cold start falls back to the fast rhListTokens path.
let rhUniverseCache = { at: 0, items: [] };
let rhUniverseBusy = false;
function scheduleRhUniverse() {
  if (rhUniverseBusy || Date.now() - rhUniverseCache.at < 240_000) return;
  rhUniverseBusy = true;
  // Delay the ~45-call sweep so it never competes with the feed's own fast-path fetch on a cold start
  // (firing both at once rate-limited Blockscout and briefly emptied the board right after a deploy).
  setTimeout(async () => {
    try { const items = await rhListTokens(45); if (items.length) rhUniverseCache = { at: Date.now(), items }; }
    catch { /* Blockscout hiccup — keep the stale cache, never throw (would crash the process) */ }
    finally { rhUniverseBusy = false; }
  }, 5_000);
}

// The whole drain operation's token addresses, refreshed in the background (~15 min). Feed excludes these
// outright — a definitive scam-group filter that doesn't need a per-coin scan.
let rhScamCache = { at: 0, set: new Set() };
let rhScamBusy = false;
function scheduleRhScamSet() {
  if (rhScamBusy || Date.now() - rhScamCache.at < 900_000) return;
  rhScamBusy = true;
  // Staggered after the universe sweep so the two big background jobs don't saturate Blockscout together.
  setTimeout(async () => {
    try { const r = await rhScamTokenSet(); if (r && r.tokens) rhScamCache = { at: Date.now(), set: new Set(r.tokens.map((a) => a.toLowerCase())) }; }
    catch { /* Blockscout hiccup — keep the stale set, never throw */ }
    finally { rhScamBusy = false; }
  }, 12_000);
}

let rhFeedCache = { at: 0, tokens: [] };
const rhPairsSharedMemory = new Map();
function rhPairsSharedKey(category = "trending") {
  const cat = String(category || "trending").trim().toLowerCase().replace(/[^a-z]/g, "").slice(0, 20) || "trending";
  return externalCacheKey(`rh-pairs:${cat}`, "global");
}
async function refreshSharedRhPairs(category = "trending", options = {}) {
  const cat = String(category || "trending").trim().toLowerCase();
  return LockService.withLock(`rh-pairs-refresh:${cat}`, 35_000, async () => {
    const rows = await webRhPairs(cat, { force: Boolean(options.force) });
    const envelope = displayCacheEnvelope(rows, Date.now());
    rhPairsSharedMemory.set(cat, envelope);
    await cacheSetJson(rhPairsSharedKey(cat), envelope, 5 * 60_000).catch(() => false);
    return envelope;
  }, null);
}
async function cachedWebRhPairs(category = "trending", options = {}) {
  const cat = String(category || "trending").trim().toLowerCase();
  const now = Date.now();
  const freshMs = cat === "new" ? 4_000 : 10_000;
  const staleMs = 5 * 60_000;
  const finish = (rows, cachedAt = now, stale = false) => options.withMeta
    ? { rows: Array.isArray(rows) ? rows : [], cachedAt: Number(cachedAt || now), stale: Boolean(stale) }
    : (Array.isArray(rows) ? rows : []);
  let envelope = rhPairsSharedMemory.get(cat) || null;
  if (!options.force && envelope?.value && now - Number(envelope.cachedAt || 0) <= freshMs) {
    return finish(envelope.value, envelope.cachedAt, false);
  }
  if (!envelope?.value) {
    envelope = await cacheGetJson(rhPairsSharedKey(cat)).catch(() => null);
    if (envelope?.value) rhPairsSharedMemory.set(cat, envelope);
  }
  const ageMs = envelope?.value ? now - Number(envelope.cachedAt || 0) : Number.POSITIVE_INFINITY;
  if (!options.force && envelope?.value && ageMs <= freshMs) return finish(envelope.value, envelope.cachedAt, false);
  if (!options.force && envelope?.value && ageMs <= staleMs) {
    void refreshSharedRhPairs(cat).catch(() => null);
    return finish(envelope.value, envelope.cachedAt, true);
  }
  const refreshed = await refreshSharedRhPairs(cat, options);
  if (refreshed?.value) return finish(refreshed.value, refreshed.cachedAt, false);
  if (envelope?.value) return finish(envelope.value, envelope.cachedAt, true);
  return finish(await webRhPairs(cat), Date.now(), false);
}
// 🚀 NOXA fresh-launch feed — read straight off NOXA's launchpad on-chain (the fresh coins DexScreener +
// Blockscout's holder feed miss). Background-cached like the universe so it never blocks the board, and
// never throws from the timer (a bad RPC sweep must not crash the money service — see rh-safety notes).
let noxaFeedCache = { at: 0, tokens: [] };
let noxaFeedBusy = false;
function scheduleNoxaFeed() {
  if (noxaFeedBusy || Date.now() - noxaFeedCache.at < 60_000) return;   // fast bounded refresh, serve-stale
  noxaFeedBusy = true;
  setTimeout(async () => {
    try {
      const rows = await fetchNoxaFeed({ rpcUrl: CONFIG.rhChainRpcUrl, lookbackBlocks: 60000, max: 60 }).catch(() => []);
      if (rows.length) {
        noxaFeedCache = { at: Date.now(), tokens: rows };
        for (const row of rows) maybeRhCommunitySnipe(row, { source: "noxa-feed" });
      }
    } catch { /* never throw from a background timer */ } finally { noxaFeedBusy = false; }
  }, 30);
}
// The RH RPC is slow/rate-limited from Render's IP, so an on-demand NOXA read can hang. The background
// feed cache is already warm — serve fresh coins from it instantly, and cap any live read so a scan never
// stalls the request. `noxaScanFast` returns a ready coin fast or null (caller keeps its DexScreener data).
function noxaFromFeedCache(address) {
  const a = String(address || "").toLowerCase();
  return (noxaFeedCache.tokens || []).find((t) => String(t.token || "").toLowerCase() === a) || null;
}
async function noxaScanFast(address, timeoutMs = 12_000) {
  scheduleNoxaFeed();
  const cached = noxaFromFeedCache(address);
  if (cached) return cached;
  return await Promise.race([
    getNoxaScan(address, { rpcUrl: CONFIG.rhChainRpcUrl }).catch(() => null),
    new Promise((res) => setTimeout(() => res(null), timeoutMs)),
  ]);
}
async function rhFeedTokens(options = {}) {
  scheduleRhUniverse(); scheduleRhScamSet(); scheduleNoxaFeed();   // keep the big caches warm
  const cacheAgeMs = Date.now() - rhFeedCache.at;
  // Manual refresh may bypass the normal display cache, but repeated taps must not fan out into an
  // unbounded Blockscout workload. One deep refresh per three seconds is enough for a live-feeling UI.
  if (rhFeedCache.tokens.length && (!options.force ? cacheAgeMs < 12_000 : cacheAgeMs < 3_000)) return rhFeedCache.tokens;
  // Base = full universe once warm (else the fast top-by-holders path), PLUS the time-ordered transfers
  // feed for brand-new launches. Dedupe by address.
  // Cold start must paint quickly: one holders page + one activity page in parallel is enough
  // for the first screen. The full 45-page universe continues warming in the background.
  const [base, byActivity] = await Promise.all([
    rhUniverseCache.items.length ? Promise.resolve(rhUniverseCache.items) : rhListTokens(1).catch(() => []),
    rhRecentActiveTokens(options.fresh ? 2 : 1).catch(() => [])
  ]);
  const scam = rhScamCache.set;
  const merged = new Map();
  for (const t of [...base, ...byActivity]) {
    const addr = String(t.address_hash || t.address || "").toLowerCase();
    if (!addr || scam.has(addr)) continue;                  // drop the scam operation's coins outright
    if (!merged.has(addr)) merged.set(addr, t); else if (t.lastActiveAt) merged.get(addr).lastActiveAt = t.lastActiveAt;
  }
  const tokens = [...merged.values()].map((t) => {
    const decimals = Number(t.decimals || 18);
    let totalSupplyUi = 0;
    try { totalSupplyUi = Number(BigInt(t.total_supply || "0") / 10n ** BigInt(Math.max(0, decimals - 6))) / 1e6; } catch { /* odd supply strings */ }
    return {
      address: t.address_hash || t.address || "",
      name: t.name || "",
      symbol: t.symbol || "",
      decimals,
      totalSupplyUi,
      iconUrl: t.icon_url || "",
      holders: Number(t.holders_count || 0),
      priceUsd: Number(t.exchange_rate || 0) || null,
      marketCapUsd: Number(t.circulating_market_cap || 0) || null,
      volume24hUsd: Number(t.volume_24h || 0) || null,
      reputation: t.reputation || "",
      lastActiveAt: t.lastActiveAt || ""
    };
  }).filter((t) => t.address && t.symbol && !RH_FEED_HIDE.has(t.symbol.toLowerCase()) && !rhIsStockOrBluechip(t.iconUrl));
  // 🚀 Merge in fresh NOXA launches (on-chain read) that aren't already in the Blockscout-sourced list —
  // these are the brand-new coins the holder/transfer feeds haven't surfaced yet, with live MC/liq/price.
  const have = new Set(tokens.map((t) => t.address.toLowerCase()));
  for (const n of (noxaFeedCache.tokens || [])) {
    const addr = String(n.token || "").toLowerCase();
    if (!addr || have.has(addr) || scam.has(addr)) continue;
    if (n.symbol && RH_FEED_HIDE.has(String(n.symbol).toLowerCase())) continue;
    have.add(addr);
    tokens.push({
      address: n.token, name: n.name || "", symbol: n.symbol || "", decimals: Number(n.decimals || 18),
      totalSupplyUi: Number(n.supply || 0), iconUrl: "", holders: 0,
      priceUsd: n.priceUsd || null, marketCapUsd: n.mc || null, volume24hUsd: null, liquidityUsd: n.liq || null,
      reputation: "", lastActiveAt: "", source: "noxa", noxaUrl: n.noxaUrl || "", launchBlock: n.block || 0,
    });
  }
  rhFeedCache = { at: Date.now(), tokens };
  return tokens;
}

// Server-side SAFETY verdict cache for the feed — so every row can carry a 🛡/✅/⚠️/⛔ badge and the
// "Safe" tab can filter to proven-safe coins. rhHoneypotCheck is expensive (several calls each), so we
// fill in the BACKGROUND in small batches and serve from cache; the board polls every 30s and picks up
// verdicts as they resolve. 10-min TTL (drain-service membership doesn't change minute-to-minute).
const rhSafetyFeedCache = new Map(); // addrLc -> { verdict, at }
let rhSafetyFillBusy = false;
function scheduleRhSafetyFill(rows, want = 12) {
  if (rhSafetyFillBusy) return;
  const missing = rows.filter((r) => {
    const c = rhSafetyFeedCache.get(r.address.toLowerCase());
    return !c || Date.now() - c.at > 600_000;
  }).slice(0, want);
  if (!missing.length) return;
  rhSafetyFillBusy = true;
  setTimeout(async () => {
    try {
      for (const r of missing) {
        const s = await rhHoneypotCheck(r.address).catch(() => null);
        if (s) rhSafetyFeedCache.set(r.address.toLowerCase(), { verdict: s.verdict, at: Date.now() });
      }
    } catch { /* never throw from a background timer */ } finally { rhSafetyFillBusy = false; }
  }, 50);
}

// Pool-implied price fallback for coins DexScreener/Blockscout can't price yet ("fresh coins with no
// MC"). Prices resolve in the BACKGROUND (single-flight, small batches) so feed requests stay fast —
// the board polls every 30s and picks the values up next cycle. noPool coins are remembered too, so
// the UI can say "no pool yet" instead of showing an empty row.
const rhPriceCache = new Map(); // addrLc -> { at, priceUsd | noPool }
let rhPriceFillBusy = false;
function scheduleRhPriceFill(rows) {
  if (rhPriceFillBusy) return;
  const missing = rows.filter((r) => {
    const c = rhPriceCache.get(r.address.toLowerCase());
    return !r.priceUsd && (!c || Date.now() - c.at > 90_000);
  }).slice(0, 12);
  if (!missing.length) return;
  rhPriceFillBusy = true;
  setTimeout(async () => {
    try {
      const probe = rhFeeEvmWallet(CONFIG.appSecret, CONFIG.rhChainRpcUrl).address;
      for (const r of missing) {
        const res = await rhImpliedPriceUsd(r.address, probe).catch(() => null);
        if (res) rhPriceCache.set(r.address.toLowerCase(), { at: Date.now(), ...(res.noPool ? { noPool: true } : { priceUsd: res.priceUsd }) });
      }
    } finally {
      rhPriceFillBusy = false;
    }
  }, 50);
}

// Creation-time cache so Trending rows + the coin chart show age (New already resolves it inline).
const rhCreatedCache = new Map(); // addrLc -> ISO
let rhCreatedFillBusy = false;
function scheduleRhCreatedFill(rows) {
  if (rhCreatedFillBusy) return;
  const missing = rows.filter((r) => !r.createdAt && !rhCreatedCache.has(r.address.toLowerCase())).slice(0, 15);
  if (!missing.length) return;
  rhCreatedFillBusy = true;
  setTimeout(async () => {
    try {
      for (const r of missing) {
        const ts = await rhTokenCreationTime(r.address).catch(() => "");
        if (ts) rhCreatedCache.set(r.address.toLowerCase(), ts);
      }
    } finally {
      rhCreatedFillBusy = false;
    }
  }, 50);
}

async function rhLaunchMetaByAddress() {
  const store = await readPumpLaunchAttempts().catch(() => ({ attempts: [] }));
  const map = new Map();
  for (const a of store.attempts || []) {
    if (String(a.rail || "") !== "robinhood") continue;
    const addr = String(a.mintPublicKey || "").toLowerCase();
    if (!addr) continue;
    map.set(addr, {
      name: a.tokenName || "",
      symbol: a.symbol || "",
      description: a.description || "",
      website: a.website || "",
      x: a.x || "",
      telegram: a.telegram || "",
      hasImage: Boolean(a.rhImageFile),
      creatorFeeBps: Number(a.rhCreatorFeeBps || 0),
      creatorFeeRecipient: a.rhCreatorFeeRecipient || "",
      holderRewards: launchHolderRewardsFromAttempt(a),
      deployer: a.rhDeployer || "",
      devWalletPublicKey: a.devWalletPublicKey || "",
      metadataUri: a.metadataUri || "",
      supplyTokens: firstString(a.rhSupplyTokens, a.supplyTokens),
      pairAddress: a.rhPool || "",
      venue: a.rhVenue || "",
      liquidityLocked: Boolean(a.rhLiquidityLocked),
      createdAt: a.createdAt || "",
      slimewire: true
    });
  }
  return map;
}

const RH_NOXA_PUBLIC_API = "https://awk00kk00gskkw0o8kc488kg.notoriouslywrong.com";
const rhFeedArtworkCache = new Map();
let rhNoxaArtworkSnapshot = { at: 0, byToken: new Map() };
let rhNoxaArtworkInFlight = null;
let rhBankrArtworkSnapshot = { at: 0, byToken: new Map() };
let rhBankrArtworkInFlight = null;
const rhOnchainMetadataCache = new Map();
const rhOpenSeaArtworkCache = new Map();
const rhOpenSeaArtworkInFlight = new Map();

// OpenSea's public token page is one of the first address-indexed surfaces to retain Robinhood
// artwork. Read only the bounded initial HTML stream and accept an image when the CDN path itself
// contains the exact requested chain + contract. This fills real PFPs without a ticker guess and
// without holding the page's full response in memory.
async function getRhOpenSeaArtwork(address = "", timeoutMs = 3_200) {
  const key = String(address || "").trim().toLowerCase();
  if (!/^0x[0-9a-f]{40}$/.test(key)) return "";
  const cached = rhOpenSeaArtworkCache.get(key);
  if (cached && Date.now() - cached.at < (cached.imageUrl ? 30 * 24 * 60 * 60_000 : 5 * 60_000)) return cached.imageUrl;
  if (rhOpenSeaArtworkInFlight.has(key)) return rhOpenSeaArtworkInFlight.get(key);
  const task = (async () => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), Math.max(1_000, Number(timeoutMs) || 3_200));
    let imageUrl = "";
    try {
      const response = await fetch(`https://opensea.io/token/robinhood/${key}/liquidity`, {
        signal: controller.signal,
        redirect: "follow",
        headers: {
          "Accept": "text/html,application/xhtml+xml",
          "User-Agent": "Mozilla/5.0 SlimeWire/1.0"
        }
      });
      if (!response.ok || !response.body) return "";
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      const exactPrefix = `https://i2c.seadn.io/robinhood/${key}/`;
      let html = "";
      let bytes = 0;
      while (bytes < 320_000) {
        const { value, done } = await reader.read();
        if (done) break;
        bytes += value?.byteLength || 0;
        html += decoder.decode(value || new Uint8Array(), { stream: true });
        const at = html.toLowerCase().indexOf(exactPrefix);
        if (at >= 0) {
          const raw = html.slice(at).match(/^https:\/\/i2c\.seadn\.io\/robinhood\/0x[0-9a-f]{40}\/[^\s"'<>\\]+/i)?.[0] || "";
          imageUrl = normalizeTokenAvatarUrl(raw.replace(/&amp;/gi, "&"));
          if (imageUrl) break;
        }
        if (html.length > 340_000) html = html.slice(-320_000);
      }
      try { await reader.cancel(); } catch { /* stream already ended */ }
      return imageUrl;
    } catch {
      return "";
    } finally {
      clearTimeout(timer);
      controller.abort();
      rhOpenSeaArtworkCache.set(key, { at: Date.now(), imageUrl });
      if (rhOpenSeaArtworkCache.size > 1_000) {
        const oldest = [...rhOpenSeaArtworkCache.entries()].sort((a, b) => a[1].at - b[1].at).slice(0, 200);
        for (const [oldKey] of oldest) rhOpenSeaArtworkCache.delete(oldKey);
      }
    }
  })().finally(() => rhOpenSeaArtworkInFlight.delete(key));
  rhOpenSeaArtworkInFlight.set(key, task);
  return task;
}

async function getNoxaRhTokenMetadata(address, options = {}) {
  const token = await fetchJson(`${RH_NOXA_PUBLIC_API}/v1/robinhood/token/${encodeURIComponent(address)}`, {
    headers: { "Accept": "application/json", "User-Agent": "solana-telegram-wallet-ops-bot" },
    timeoutMs: options.timeoutMs || 1_500
  });
  return {
    address: firstString(token?.address, address),
    imageUrl: firstString(token?.logo, token?.imageUrl, token?.image),
    twitterUrl: firstString(token?.twitter),
    telegramUrl: firstString(token?.telegram),
    websiteUrl: firstString(token?.website)
  };
}

async function rhNoxaArtworkMap() {
  if (Date.now() - rhNoxaArtworkSnapshot.at < 60_000) return rhNoxaArtworkSnapshot.byToken;
  if (rhNoxaArtworkInFlight) return rhNoxaArtworkInFlight;
  rhNoxaArtworkInFlight = (async () => {
    const result = await fetchJson(`${RH_NOXA_PUBLIC_API}/v1/robinhood/tokens?limit=100&hasImage=true`, {
      headers: { "Accept": "application/json", "User-Agent": "solana-telegram-wallet-ops-bot" },
      timeoutMs: 1_500
    }).catch(() => null);
    const byToken = new Map();
    for (const token of Array.isArray(result?.tokens) ? result.tokens : []) {
      const key = String(token?.address || "").toLowerCase();
      const imageUrl = firstString(token?.logo, token?.imageUrl, token?.image);
      if (key && imageUrl) byToken.set(key, imageUrl);
    }
    if (byToken.size) rhNoxaArtworkSnapshot = { at: Date.now(), byToken };
    else rhNoxaArtworkSnapshot.at = Date.now();
    return rhNoxaArtworkSnapshot.byToken;
  })().finally(() => { rhNoxaArtworkInFlight = null; });
  return rhNoxaArtworkInFlight;
}

// Bankr exposes the metadata attached to its newest Robinhood launches. Reading this public index is
// both faster and more exact than a ticker search: every image is keyed by the 0x contract address.
async function rhBankrArtworkMap() {
  if (Date.now() - rhBankrArtworkSnapshot.at < 60_000) return rhBankrArtworkSnapshot.byToken;
  if (rhBankrArtworkInFlight) return rhBankrArtworkInFlight;
  rhBankrArtworkInFlight = (async () => {
    const result = await fetchJson("https://api.bankr.bot/token-launches", {
      headers: { "Accept": "application/json", "User-Agent": "solana-telegram-wallet-ops-bot" },
      timeoutMs: 1_500
    }).catch(() => null);
    const byToken = new Map();
    for (const launch of Array.isArray(result?.launches) ? result.launches : []) {
      if (String(launch?.chain || "").toLowerCase() !== "robinhood") continue;
      const key = String(launch?.tokenAddress || "").toLowerCase();
      if (!/^0x[0-9a-f]{40}$/.test(key)) continue;
      byToken.set(key, {
        imageUrl: firstString(launch?.imageUri, launch?.imageUrl, launch?.image),
        metadataUri: firstString(launch?.metadataUri, launch?.metadata_uri),
        twitterUrl: firstString(launch?.tweetUrl),
        websiteUrl: firstString(launch?.websiteUrl)
      });
    }
    if (byToken.size) rhBankrArtworkSnapshot = { at: Date.now(), byToken };
    else rhBankrArtworkSnapshot.at = Date.now();
    return rhBankrArtworkSnapshot.byToken;
  })().finally(() => { rhBankrArtworkInFlight = null; });
  return rhBankrArtworkInFlight;
}

function rhMetadataUriFromEncodedCall(value = "") {
  const hex = String(value || "").replace(/^0x/i, "");
  if (!hex || hex.length % 2 || !/^[0-9a-f]+$/i.test(hex)) return "";
  const decoded = Buffer.from(hex, "hex").toString("utf8");
  return firstString((decoded.match(/ipfs:\/\/[A-Za-z0-9][A-Za-z0-9._\/-]{20,350}/i) || [])[0]);
}

async function rhMetadataDocument(metadataUri = "") {
  const candidates = metadataUriGatewayCandidates(metadataUri).sort((left, right) => {
    const rank = (value) => /\/\/ipfs\.io\//i.test(value) ? 0 : /gateway\.pinata\.cloud/i.test(value) ? 1 : 2;
    return rank(left) - rank(right);
  });
  for (const candidate of candidates) {
    try {
      const metadata = await fetchJson(candidate, {
        headers: { "Accept": "application/json", "User-Agent": "solana-telegram-wallet-ops-bot" },
        timeoutMs: 1_500
      });
      if (!metadata || typeof metadata !== "object" || Array.isArray(metadata)) continue;
      return {
        imageUrl: firstString(metadata.image, metadata.imageUrl, metadata.image_url, metadata.logo, metadata.logoURI),
        twitterUrl: normalizeSocialLink(firstString(metadata.twitter, metadata.x, metadata.twitterUrl, metadata.twitter_url), "twitter"),
        telegramUrl: normalizeSocialLink(firstString(metadata.telegram, metadata.telegramUrl, metadata.telegram_url), "telegram"),
        websiteUrl: normalizeSocialLink(firstString(metadata.website, metadata.websiteUrl, metadata.website_url, metadata.external_url), "website")
      };
    } catch { /* try the next public gateway */ }
  }
  return {};
}

// Some Robinhood launchers store the token's metadata URI only in their factory initializer. When the
// usual indexes have no logo, recover that exact URI from the creation transaction instead of guessing
// by ticker. This path is bounded, cached, and only runs after the fast providers miss.
async function getRhOnchainLaunchMetadata(address = "", knownMetadataUri = "") {
  const key = String(address || "").trim().toLowerCase();
  if (!/^0x[0-9a-f]{40}$/.test(key)) return {};
  const cached = rhOnchainMetadataCache.get(key);
  // Successful immutable artwork is sticky; image-less metadata is retried quickly because launchers
  // can publish/update contractURI shortly after the pair first appears.
  if (cached && Date.now() - cached.at < (cached.imageUrl ? 30 * 24 * 60 * 60_000 : 60_000)) return cached;
  let metadataUri = String(knownMetadataUri || "").trim();
  if (!metadataUri) {
    // DropERC20 clones publish their exact PFP metadata here. This survives missing DexScreener,
    // Blockscout and launcher indexes and avoids ever matching artwork by a duplicate ticker.
    metadataUri = await rhTokenContractUri(key, CONFIG.rhChainRpcUrl, 1_800).catch(() => "");
  }
  if (!metadataUri) {
    const creation = await fetchJson(
      `https://robinhoodchain.blockscout.com/api?module=contract&action=getcontractcreation&contractaddresses=${encodeURIComponent(key)}`,
      { headers: { "Accept": "application/json" }, timeoutMs: 1_500 }
    ).catch(() => null);
    const txHash = firstString(Array.isArray(creation?.result) ? creation.result[0]?.txHash : "");
    if (txHash) {
      const transaction = await fetchJson(`https://robinhoodchain.blockscout.com/api/v2/transactions/${encodeURIComponent(txHash)}`, {
        headers: { "Accept": "application/json" }, timeoutMs: 1_500
      }).catch(() => null);
      const callData = firstString(
        ...(Array.isArray(transaction?.decoded_input?.parameters)
          ? transaction.decoded_input.parameters.filter((item) => item?.name === "data" || item?.type === "bytes").map((item) => item?.value)
          : []),
        transaction?.input
      );
      metadataUri = rhMetadataUriFromEncodedCall(callData);
    }
  }
  const metadata = metadataUri ? await rhMetadataDocument(metadataUri) : {};
  const value = { at: Date.now(), metadataUri, ...metadata };
  rhOnchainMetadataCache.set(key, value);
  if (rhOnchainMetadataCache.size > 750) {
    const oldest = [...rhOnchainMetadataCache.entries()].sort((a, b) => a[1].at - b[1].at).slice(0, 150);
    for (const [oldKey] of oldest) rhOnchainMetadataCache.delete(oldKey);
  }
  return value;
}

async function enrichRhFeedArtwork(rows = []) {
  // `iconUrl` is only the explorer's optional fallback. Keep searching for address-verified market
  // artwork whenever `imageUrl` is empty so an explorer placeholder cannot block the real coin PFP.
  const targets = rows.filter((row) => row?.address && !row.imageUrl).slice(0, 50);
  const persistedIdentity = await rhScanIdentityMapLoad().catch(() => new Map());
  const missing = [];
  for (const row of targets) {
    const key = String(row.address).toLowerCase();
    const remembered = tokenAvatarMemoryRecord(key);
    const rememberedUrl = normalizeTokenAvatarUrl(firstString(
      remembered?.state === "ready" ? remembered.avatarUrl : "",
      persistedIdentity.get(key)?.imageUrl
    ));
    if (rememberedUrl) {
      row.imageUrl = rememberedUrl;
      rhFeedArtworkCache.set(key, { at: Date.now(), imageUrl: rememberedUrl });
      continue;
    }
    const cached = rhFeedArtworkCache.get(key);
    if (cached && Date.now() - cached.at < (cached.imageUrl ? 30 * 60_000 : 45_000)) {
      if (cached.imageUrl) row.imageUrl = cached.imageUrl;
    } else missing.push(row);
  }
  if (missing.length) {
    // Dex accepts bounded address batches. Two small requests cover the whole visible feed in about one RTT.
    const chunks = [];
    for (let index = 0; index < missing.length; index += 25) chunks.push(missing.slice(index, index + 25));
    const [pairGroups, noxaArtwork, bankrArtwork] = await Promise.all([
      Promise.all(chunks.map((chunk) => fetchJson(
        `https://api.dexscreener.com/tokens/v1/robinhood/${chunk.map((row) => row.address).join(",")}`,
        { headers: { "Accept": "application/json", "User-Agent": "solana-telegram-wallet-ops-bot" }, timeoutMs: 1_800 }
      ).catch(() => []))),
      rhNoxaArtworkMap().catch(() => new Map()),
      rhBankrArtworkMap().catch(() => new Map())
    ]);
    const pairs = pairGroups.flatMap((group) => Array.isArray(group) ? group : []);
    const byToken = new Map();
    for (const pair of Array.isArray(pairs) ? pairs : []) {
      const key = String(pair?.baseToken?.address || "").toLowerCase();
      if (!key || !pair?.info?.imageUrl) continue;
      const previous = byToken.get(key);
      if (!previous || Number(pair?.liquidity?.usd || 0) > Number(previous?.liquidity?.usd || 0)) byToken.set(key, pair);
    }
    for (const row of missing) {
      const key = String(row.address).toLowerCase();
      const imageUrl = normalizeTokenAvatarUrl(firstString(
        byToken.get(key)?.info?.imageUrl,
        noxaArtwork.get(key),
        bankrArtwork.get(key)?.imageUrl,
        persistedIdentity.get(key)?.imageUrl,
        row.iconUrl
      ));
      rhFeedArtworkCache.set(key, { at: Date.now(), imageUrl }); if (imageUrl) row.imageUrl = imageUrl;
      if (!imageUrl) scheduleTokenAvatarLookup(row.address, row);
    }
  }
  // Blockscout icon_url is contract-address keyed metadata. It is a valid final exact-token fallback,
  // and copying it into imageUrl keeps every site surface on the same field after deeper lookups miss.
  for (const row of rows) if (!row.imageUrl && row.iconUrl) row.imageUrl = normalizeTokenAvatarUrl(row.iconUrl);
  if (rhFeedArtworkCache.size > 1_000) {
    const oldest = [...rhFeedArtworkCache.entries()].sort((a, b) => a[1].at - b[1].at).slice(0, 200);
    for (const [key] of oldest) rhFeedArtworkCache.delete(key);
  }
  return rows;
}

async function webRhPairs(category = "trending", options = {}) {
  const cat = String(category || "trending").toLowerCase();
  // SLIMEHOOD — coins launched THROUGH SlimeWire on Robinhood Chain (from our launch store, so even a
  // brand-new one with zero holders shows immediately). These run our verified no-rug contract → ✅.
  if (cat === "slimewire") {
    const store = await readPumpLaunchAttempts().catch(() => ({ attempts: [] }));
    const seen = new Set(); let rows = [];
    for (const a of (store.attempts || [])) {
      if (String(a.rail || "") !== "robinhood") continue;
      const addr = String(a.mintPublicKey || ""); if (!addr || seen.has(addr.toLowerCase())) continue;
      seen.add(addr.toLowerCase());
      rows.push({
        address: addr, name: a.tokenName || "", symbol: a.symbol || "", createdAt: a.createdAt || "",
        holders: null, marketCapUsd: null, volume24hUsd: null, priceUsd: null, totalSupplyUi: 0,
        slimewire: true, description: a.description || "", website: a.website || "", x: a.x || "", telegram: a.telegram || "",
        imageUrl: a.rhImageFile ? `/api/web/rh/token-image/${addr}` : "",
        creatorFeeBps: Number(a.rhCreatorFeeBps || 0), holderRewards: launchHolderRewardsFromAttempt(a), explorer: rhExplorerToken(addr),
      });
    }
    rows.sort((x, y) => Date.parse(y.createdAt || 0) - Date.parse(x.createdAt || 0));
    const feed = await rhFeedTokens().catch(() => []);
    const byAddr = new Map(feed.map((t) => [t.address.toLowerCase(), t]));
    for (const r of rows) {
      const t = byAddr.get(r.address.toLowerCase());
      if (t) { r.holders = t.holders; r.marketCapUsd = t.marketCapUsd; r.volume24hUsd = t.volume24hUsd; r.priceUsd = t.priceUsd; r.totalSupplyUi = t.totalSupplyUi; }
      const s = rhSafetyFeedCache.get(r.address.toLowerCase()); if (s) r.safety = s.verdict;
    }
    scheduleRhSafetyFill(rows);
    const visible = rows.slice(0, 60);
    await enrichRhFeedArtwork(visible).catch(() => visible);
    return visible;
  }
  const [tokens, meta] = await Promise.all([
    rhFeedTokens({ force: Boolean(options.force), fresh: cat === "new" }),
    rhLaunchMetaByAddress()
  ]);
  let rows = tokens.map((t) => {
    const m = meta.get(t.address.toLowerCase());
    return {
      ...t,
      ...(m ? { slimewire: true, description: m.description, website: m.website, x: m.x, telegram: m.telegram, holderRewards: m.holderRewards } : {}),
      imageUrl: (m && m.hasImage) ? `/api/web/rh/token-image/${t.address}` : "",
      explorer: rhExplorerToken(t.address)
    };
  });
  // A successful SlimeWire launch should appear in New immediately, before Blockscout, NOXA,
  // DexScreener or GeckoTerminal has indexed its first transfer/pool. Keep the launch-store row in
  // every feed's candidate universe; normal category sorting decides where it lands afterward.
  const rowAddresses = new Set(rows.map((row) => String(row.address || "").toLowerCase()));
  for (const [address, launch] of meta) {
    if (!/^0x[0-9a-f]{40}$/.test(address) || rowAddresses.has(address)) continue;
    rowAddresses.add(address);
    rows.push({
      address,
      name: launch.name || "",
      symbol: launch.symbol || "",
      decimals: 18,
      totalSupplyUi: Number(launch.supplyTokens || 0),
      holders: 0,
      priceUsd: null,
      marketCapUsd: null,
      volume24hUsd: null,
      liquidityUsd: null,
      createdAt: launch.createdAt || new Date().toISOString(),
      lastActiveAt: launch.createdAt || "",
      imageUrl: launch.hasImage ? `/api/web/rh/token-image/${address}` : "",
      description: launch.description || "",
      website: launch.website || "",
      x: launch.x || "",
      telegram: launch.telegram || "",
      holderRewards: launch.holderRewards || null,
      slimewire: true,
      pendingIndex: true,
      pairAddress: launch.pairAddress || "",
      venue: launch.venue || "",
      explorer: rhExplorerToken(address)
    });
  }
  // Start artwork immediately and overlap it with safety/age/price work. Awaiting before JSON serialization
  // fixes the old race where enrichment mutated the rows only after the response had already been sent.
  const artworkPromise = enrichRhFeedArtwork(rows).catch(() => rows);
  // Attach the cached server-side safety verdict to EVERY row (all tabs show the 🛡/✅/⚠️/⛔ badge).
  for (const r of rows) { const s = rhSafetyFeedCache.get(r.address.toLowerCase()); if (s) r.safety = s.verdict; }
  if (cat === "safe") {
    // SAFE tab: only coins our scanner has confirmed clean (ok/verified) — everything tied to the drain
    // service or otherwise flagged is excluded. Rank by real activity. Scan broadly in the background so
    // the safe set keeps filling in; until a coin is scanned it's withheld (conservative — never show an
    // unvetted coin as "safe"). This is the curated list for "what's actually safe to buy right now."
    scheduleRhSafetyFill(rows, 24);
    rows = rows
      .filter((r) => r.safety === "ok" || r.safety === "verified")
      .sort((a, b) => (b.safety === "verified" ? 1 : 0) - (a.safety === "verified" ? 1 : 0)
        || (b.volume24hUsd || 0) - (a.volume24hUsd || 0) || (b.marketCapUsd || 0) - (a.marketCapUsd || 0) || b.holders - a.holders);
  } else if (cat === "soon") {
    rows = rows
      .filter((row) => Number(row.marketCapUsd || 0) >= 17_000 && Number(row.marketCapUsd || 0) <= 40_000)
      .sort((a, b) => Number(b.marketCapUsd || 0) - Number(a.marketCapUsd || 0));
  } else if (cat === "new") {
    // Never block the feed on dozens of explorer creation-time reads. Show the activity-ordered universe
    // immediately, merge permanent cached ages, and let the existing bounded filler improve later refreshes.
    const slice = rows
      .slice()
      .sort((a, b) => Date.parse(b.createdAt || b.lastActiveAt || 0) - Date.parse(a.createdAt || a.lastActiveAt || 0))
      .slice(0, 60);
    for (const r of slice) {
      const cachedCreatedAt = rhCreatedCache.get(r.address.toLowerCase());
      if (cachedCreatedAt) r.createdAt = cachedCreatedAt;
    }
    scheduleRhCreatedFill(slice);
    rows = slice.sort((a, b) => Date.parse(b.createdAt || b.lastActiveAt || 0) - Date.parse(a.createdAt || a.lastActiveAt || 0));
  } else {
    rows.sort((a, b) => (b.volume24hUsd || 0) - (a.volume24hUsd || 0) || (b.marketCapUsd || 0) - (a.marketCapUsd || 0) || b.holders - a.holders);
  }
  rows = rows.slice(0, 50);
  scheduleRhSafetyFill(rows);
  // Attach coin age from the creation-time cache (so Trending rows + the chart show age too, like New);
  // creation never changes, so once resolved it's permanent. Missing ones fill in the background.
  for (const r of rows) { if (!r.createdAt) { const c = rhCreatedCache.get(r.address.toLowerCase()); if (c) r.createdAt = c; } }
  scheduleRhCreatedFill(rows);
  // Fill fresh coins from the implied-price cache (pool quote x on-chain supply) so no row sits empty,
  // and mark true no-pool coins so the UI can say so. Missing ones resolve in the background.
  for (const r of rows) {
    const cached = rhPriceCache.get(r.address.toLowerCase());
    if (!cached) continue;
    if (cached.noPool && !r.priceUsd) r.noPool = true;
    if (cached.priceUsd && !r.priceUsd) {
      r.priceUsd = cached.priceUsd;
      if (!r.marketCapUsd && r.totalSupplyUi > 0) r.marketCapUsd = cached.priceUsd * r.totalSupplyUi;
    }
  }
  scheduleRhPriceFill(rows);
  await artworkPromise;
  await enrichRhFeedArtwork(rows).catch(() => rows);
  return rows;
}

// Public per-token image for coins launched through the site (img tags can't send a Bearer token).
function rhTokenImagePath(address) {
  return path.join(CONFIG.dataDir, "rh-token-images", `${String(address).toLowerCase().replace(/[^0-9a-fx]/g, "")}.jpg`);
}
async function saveRhTokenImage(address, imageDataUrl) {
  const match = /^data:image\/[a-z+.-]+;base64,(.+)$/i.exec(String(imageDataUrl || ""));
  if (!match) return false;
  const raw = Buffer.from(match[1], "base64");
  if (!raw.length || raw.length > 3_000_000) return false;
  const file = rhTokenImagePath(address);
  await fs.mkdir(path.dirname(file), { recursive: true });
  // Normalize to a small JPEG so the feed loads fast no matter what was uploaded.
  const image = await sharp(raw).resize(256, 256, { fit: "cover" }).jpeg({ quality: 82 }).toBuffer();
  await fs.writeFile(file, image);
  return true;
}

// Trade a Robinhood Chain coin from the active wallet's derived EVM account — buy (ETH -> token) or
// sell (token -> ETH, % of balance), routed through the chain's live pools via Relay. Sells execute
// approve + swap sequentially; every tx is gas-estimated BEFORE sending so failures cost nothing.
function rhAutoExitGuardId(userId, body = {}) {
  const attemptId = firstString(body.tradeAttemptId, body.clientRequestId, crypto.randomUUID());
  return `rh-auto-exit-${crypto.createHash("sha256").update(`${userId}:${attemptId}`).digest("hex").slice(0, 24)}`;
}

async function reserveRhAutoExitProtection(userId, body = {}, automationPermission = null) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId),
    body.walletPublicKey,
    "Robinhood protected buy"
  );
  const tokenAddress = String(body.tokenAddress || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) {
    const error = new Error("Invalid token address.");
    error.statusCode = 400;
    throw error;
  }
  const guard = {
    id: rhAutoExitGuardId(userId, body),
    userId,
    walletIndex: parseWebWalletIndex(body.walletIndex),
    walletPublicKey: wallet.publicKey,
    tokenAddress,
    symbol: String(body.symbol || "").slice(0, 16),
    kind: "exit",
    exitSlot: "single",
    exitGroup: null,
    closesPosition: false,
    takeProfitPct: Number(body.takeProfitPct) > 0 ? Number(body.takeProfitPct) : null,
    stopLossPct: Number(body.stopLossPct) > 0 ? Number(body.stopLossPct) : null,
    sellPercent: Math.min(100, Math.max(1, Number(body.sellPercent || 100))),
    automationPermission: automationPermission || await requireWebAutomationPermission(userId, "Robinhood TP/SL guard"),
    tradeAttemptId: firstString(body.tradeAttemptId, body.clientRequestId),
    status: "pending_buy",
    protectionIntent: "pending_buy",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  await mutateRhGuards((guardStore) => {
    const existing = objectRows(guardStore.guards).find((row) => row.id === guard.id);
    if (existing) {
      if (String(existing.status || "").toLowerCase() !== "failed") {
        const error = new Error("This protected Robinhood buy is already submitting or armed. Check Orders & exits before retrying.");
        error.statusCode = 409;
        throw error;
      }
      Object.assign(existing, guard, { createdAt: existing.createdAt || guard.createdAt });
    } else {
      guardStore.guards.push(guard);
    }
    guardStore.guards = pruneRhGuardHistory(guardStore.guards);
  });
  return guard;
}

async function updateRhAutoExitProtection(id, patch = {}) {
  return mutateRhGuards((store) => {
    const guard = objectRows(store.guards).find((row) => row.id === String(id || ""));
    if (!guard) return null;
    Object.assign(guard, patch, { updatedAt: new Date().toISOString() });
    return guard;
  });
}

async function recordRhAutoExitNeedsAttention(userId, body = {}, trade = {}, errorMessage = "") {
  const attemptId = firstString(body.tradeAttemptId, body.clientRequestId, crypto.randomUUID());
  const id = rhAutoExitGuardId(userId, { ...body, tradeAttemptId: attemptId });
  const now = new Date().toISOString();
  const guard = {
    id,
    userId,
    walletIndex: parseWebWalletIndex(body.walletIndex),
    walletPublicKey: String(body.walletPublicKey || ""),
    tokenAddress: String(body.tokenAddress || ""),
    symbol: String(firstString(body.symbol, trade.outSymbol) || "").slice(0, 16),
    kind: "exit",
    exitSlot: "single",
    exitGroup: null,
    closesPosition: false,
    entryPriceUsd: 0,
    takeProfitPct: Number(body.takeProfitPct) > 0 ? Number(body.takeProfitPct) : null,
    stopLossPct: Number(body.stopLossPct) > 0 ? Number(body.stopLossPct) : null,
    sellPercent: Math.min(100, Math.max(1, Number(body.sellPercent || 100))),
    status: "needs_attention",
    protectionIntent: "pending_buy",
    buyConfirmed: true,
    tradeAttemptId: attemptId,
    txHashes: Array.isArray(trade.txHashes) ? trade.txHashes : [],
    lastError: String(errorMessage || "The buy landed, but its automatic exit needs attention.").slice(0, 300),
    createdAt: now,
    updatedAt: now
  };
  await mutateRhGuards((store) => {
    const existing = store.guards.find((row) => row.id === id);
    if (existing) Object.assign(existing, guard, { createdAt: existing.createdAt || now });
    else store.guards.push(guard);
    store.guards = pruneRhGuardHistory(store.guards);
  });
  return guard;
}

async function assertRhBuyReentryAllowed(wallet, tokenAddress) {
  const normalizedToken = String(tokenAddress || "").trim().toLowerCase();
  const guardStore = await readRhGuards();
  const exits = objectRows(guardStore.guards).map((guard) => ({
    ...guard,
    walletPublicKey: firstString(guard.walletPublicKey, guard.publicKey),
    tokenMint: String(guard.tokenAddress || guard.tokenMint || "").trim().toLowerCase()
  }));
  const decision = sameWalletTokenBuyBlockDecision({
    walletPublicKey: wallet.publicKey,
    tokenMint: normalizedToken
  }, exits, {
    stopClosedCooldownMs: CONFIG.stopLossReentryCooldownMs
  });
  if (!decision.blocked) return;
  const error = new Error(decision.reason === "exit_outcome_unknown"
    ? "A Robinhood Chain exit for this wallet and coin needs receipt review. The new buy was blocked so it cannot overlap an unknown sell."
    : "An automatic exit is already active or settling for this Robinhood Chain wallet and coin. Check Orders & exits before buying again.");
  error.statusCode = 409;
  error.retryAfterMs = decision.retryAfterMs || null;
  throw error;
}

function rhManualSellGuardBusyError() {
  const error = new Error("A Robinhood automatic exit for this wallet and coin is already submitting or needs receipt review. SlimeWire blocked the manual sell so the same tokens cannot be sold twice.");
  error.statusCode = 409;
  error.manualSellProtectionBusy = true;
  return error;
}

async function claimRhManualSellGuards(walletPublicKey, tokenAddress, claimToken) {
  const normalizedToken = String(tokenAddress || "").trim().toLowerCase();
  const nowIso = new Date().toISOString();
  const guardIds = [];
  await mutateRhGuards((store) => {
    for (const guard of objectRows(store.guards)) {
      if (String(guard.walletPublicKey || "") !== String(walletPublicKey || "")) continue;
      if (String(guard.tokenAddress || "").trim().toLowerCase() !== normalizedToken) continue;
      if (String(guard.kind || "exit").toLowerCase() === "limit-buy") continue;
      const status = String(guard.status || "").toLowerCase();
      if (["pending_buy", "arming", "submitting", "outcome_unknown", "manual_sell_submitting"].includes(status)) {
        throw rhManualSellGuardBusyError();
      }
      if (status !== "active" && status !== "needs_attention") continue;
      guard.manualSellPreviousStatus = guard.status;
      guard.manualSellClaimToken = claimToken;
      guard.manualSellStartedAt = nowIso;
      guard.status = "manual_sell_submitting";
      guard.updatedAt = nowIso;
      guardIds.push(guard.id);
    }
  });
  return { claimToken, guardIds };
}

async function settleRhManualSellGuards(claimed, outcome, result = {}, percent = 100, error = null) {
  if (!claimed?.claimToken || !claimed.guardIds?.length) return;
  const nowIso = new Date().toISOString();
  await mutateRhGuards((store) => {
    for (const guard of objectRows(store.guards)) {
      if (!claimed.guardIds.includes(guard.id) || guard.manualSellClaimToken !== claimed.claimToken) continue;
      if (outcome === "ambiguous") {
        guard.status = "outcome_unknown";
        guard.manualSellOutcomeUnknownAt = nowIso;
        guard.txHashes = [...new Set([...(guard.txHashes || []), ...submittedUnknownHashes(error)])];
        guard.lastError = "The manual sell was submitted but its on-chain outcome is unknown. Automatic exits are paused to prevent a duplicate sell.";
      } else if (outcome === "confirmed") {
        guard.manualSellConfirmedAt = nowIso;
        guard.manualSellPercent = percent;
        guard.manualSellTxHashes = Array.isArray(result.txHashes) ? result.txHashes : [];
        guard.lastError = null;
        if (Number(percent) >= 99.999) {
          guard.status = "triggered";
          guard.trigger = "manual-sell";
          guard.triggeredAt = nowIso;
          guard.txHashes = [...new Set([...(guard.txHashes || []), ...(result.txHashes || [])])];
        } else {
          guard.status = guard.manualSellPreviousStatus === "needs_attention" ? "needs_attention" : "active";
        }
      } else {
        guard.status = guard.manualSellPreviousStatus || "active";
      }
      delete guard.manualSellPreviousStatus;
      delete guard.manualSellClaimToken;
      delete guard.manualSellStartedAt;
      guard.updatedAt = nowIso;
    }
  });
}

async function webRhTrade(userId, body = {}) {
  return runIdempotentMoneyOp("web-rh-trade", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    async () => {
      const identityStore = await readWalletStore();
      const positionWallet = assertFrozenManagedWallet(
        getWalletAt(identityStore, parseWebWalletIndex(body.walletIndex), userId),
        body.walletPublicKey,
        "Robinhood trade"
      );
      const positionToken = String(body.tokenAddress || "").trim().toLowerCase();
      if (!/^0x[0-9a-f]{40}$/.test(positionToken)) {
        const error = new Error("Invalid token address.");
        error.statusCode = 400;
        throw error;
      }
      return withExitSellLock(userId, positionWallet.publicKey, `rh:${positionToken}`, async () => {
        try {
        const side = String(body.side || "").toLowerCase();
        const tradeBody = side === "buy"
          ? await resolveWebTradeProtectionBody(userId, body)
          : body;
        const wantsAutoExit = side === "buy"
          && cleanLaunchBoolean(tradeBody.autoExit)
          && (Number(tradeBody.takeProfitPct) > 0 || Number(tradeBody.stopLossPct) > 0);
        if (side === "buy" && cleanLaunchBoolean(tradeBody.protectionRequired) && !wantsAutoExit) {
          throw webProtectionRequiredError("Robinhood Chain protected buys require an active take-profit or stop-loss. The buy was not submitted.");
        }
        // Validate unattended-trading permission before any money moves. The
        // guard is then created inside this same backend request so closing the
        // page (or losing mobile signal) cannot skip a second browser request.
        const automationPermission = wantsAutoExit
          ? await requireWebAutomationPermission(userId, "Robinhood TP/SL guard")
          : null;
        if (side === "buy") {
          await assertRhBuyReentryAllowed(positionWallet, positionToken);
        }
        const pendingGuard = wantsAutoExit
          ? await reserveRhAutoExitProtection(userId, tradeBody, automationPermission)
          : null;
        const manualSellClaim = side === "sell"
          ? await claimRhManualSellGuards(positionWallet.publicKey, positionToken, crypto.randomUUID())
          : null;
        let trade;
        try {
          trade = await webRhTradeCore(userId, tradeBody, { positionLockHeld: true });
        } catch (tradeError) {
          if (manualSellClaim) {
            await settleRhManualSellGuards(
              manualSellClaim,
              tradeError?.tradeSubmissionAmbiguous ? "ambiguous" : "failed",
              {},
              Number(tradeBody.percent || 100),
              tradeError
            ).catch(() => {});
          }
          if (pendingGuard) {
            const ambiguous = Boolean(tradeError?.tradeSubmissionAmbiguous);
            const partialHashes = [...new Set([
              ...(Array.isArray(tradeError?.partialHashes) ? tradeError.partialHashes : []),
              tradeError?.transactionHash,
              tradeError?.hash
            ].map((value) => String(value || "").trim()).filter((value) => /^0x[0-9a-fA-F]{64}$/.test(value)))];
            await updateRhAutoExitProtection(pendingGuard.id, {
              status: ambiguous ? "outcome_unknown" : "failed",
              txHashes: partialHashes,
              expectedRhTxCount: Number(tradeError?.expectedRhTxCount || 0) || null,
              submittedAt: partialHashes.length ? new Date().toISOString() : null,
              lastError: ambiguous
                ? `Buy submission outcome is unknown; no automatic retry will be sent. ${friendlyError(tradeError)}`
                : `Buy did not submit; protection reservation released. ${friendlyError(tradeError)}`
            }).catch(() => {});
          }
          throw tradeError;
        }
        if (manualSellClaim) {
          await settleRhManualSellGuards(manualSellClaim, "confirmed", trade, Number(tradeBody.percent || 100)).catch(async (error) => {
            await audit("rh_manual_sell_guard_update_failed", {
              userId,
              walletPublicKey: positionWallet.publicKey,
              tokenAddress: positionToken,
              txHashes: trade.txHashes || [],
              error: friendlyError(error)
            }).catch(() => {});
          });
        }
        if (!wantsAutoExit) return trade;
        try {
          const armed = await webRhArmGuard(userId, {
            walletIndex: tradeBody.walletIndex,
            walletPublicKey: tradeBody.walletPublicKey,
            tokenAddress: tradeBody.tokenAddress,
            symbol: firstString(tradeBody.symbol, trade.outSymbol),
            takeProfitPct: tradeBody.takeProfitPct,
            stopLossPct: tradeBody.stopLossPct,
            sellPercent: tradeBody.sellPercent || 100,
            pendingGuardId: pendingGuard?.id || ""
          });
          return {
            ...trade,
            autoExitArmed: true,
            autoExitGuardId: armed.guard?.id || ""
          };
        } catch (guardError) {
          const message = friendlyError(guardError).slice(0, 220);
          const attention = await recordRhAutoExitNeedsAttention(userId, tradeBody, trade, message).catch(() => null);
          await audit("web_rh_auto_exit_arm_failed", {
            userId,
            tokenAddress: String(tradeBody.tokenAddress || "").slice(0, 64),
            walletIndex: parseWebWalletIndex(tradeBody.walletIndex),
            tradeAttemptId: firstString(tradeBody.tradeAttemptId, tradeBody.clientRequestId),
            error: message
          }).catch(() => {});
          return { ...trade, autoExitArmed: false, autoExitGuardId: attention?.id || "", autoExitError: message };
        }
        } catch (error) {
          await audit("web_rh_trade_failed", {
            userId,
            side: String(body.side || "").toLowerCase(),
            tokenAddress: String(body.tokenAddress || "").slice(0, 64),
            walletIndex: parseWebWalletIndex(body.walletIndex),
            payCurrency: firstString(body.payCurrency, body.payWith, body.fundingAsset),
            source: firstString(body.source, "web_rh_trade"),
            error: friendlyError(error)
          }).catch(() => {});
          throw error;
        }
      });
    },
    {
      busyMessage: "A Robinhood Chain trade is already in flight for this wallet — give it a moment.",
      ttlMs: 24 * 60 * 60_000,
      lockMs: 30 * 60_000
    });
}

function rhWeiFromEthNumber(amountEth) {
  return BigInt(Math.round(Number(amountEth) * 1e9)) * 10n ** 9n;
}

async function rhReferralTradeTarget(userId) {
  if (!userId || CONFIG.referralFeeBps <= 0) return null;
  try {
    const authStore = await readWebAuthStore();
    const profile = authStore.profiles[String(userId)] || {};
    const referrerUserId = String(profile.referredByUserId || "");
    if (!referrerUserId || !authStore.profiles[referrerUserId]) return null;
    const wallet = await cashPrimaryWallet(referrerUserId).catch(() => null);
    if (!wallet?.publicKey) return null;
    const address = evmAddressFromSolana(decryptWallet(wallet).secretKey);
    if (!/^0x[0-9a-fA-F]{40}$/.test(address)) return null;
    return { referrerUserId, wallet: wallet.publicKey, address };
  } catch {
    return null;
  }
}

async function waitForRhEthBalanceAtLeast(evmAddress, minEth, timeoutMs = 45_000) {
  const deadline = Date.now() + Math.max(3_000, Number(timeoutMs) || 45_000);
  let last = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0", wei: "0" }));
  while (Number(last.eth || 0) < minEth && Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 1_000));
    last = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => last);
  }
  return last;
}

async function firstSuccessfulRhQuote(quoteAttempts, round = 1) {
  const errors = [];
  const candidates = quoteAttempts.map(async ([label, attempt]) => {
    try {
      return { label, quote: await attempt() };
    } catch (error) {
      errors.push(`round ${round} ${label}: ${friendlyError(error)}`);
      throw error;
    }
  });
  try {
    const winner = await Promise.any(candidates);
    return { quote: winner.quote, label: winner.label, errors };
  } catch {
    await Promise.allSettled(candidates);
    return { quote: null, label: "", errors };
  }
}

async function webRhTradeCore(userId, body = {}, internal = {}) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId),
    body.walletPublicKey,
    "Robinhood trade"
  );
  const keypair = decryptWallet(wallet);
  const evmAddress = evmAddressFromSolana(keypair.secretKey);
  const tokenAddress = String(body.tokenAddress || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) {
    const e = new Error("Invalid token address.");
    e.statusCode = 400; throw e;
  }
  const side = String(body.side || "").toLowerCase();
  if (!internal.positionLockHeld) {
    return withExitSellLock(userId, wallet.publicKey, `rh:${tokenAddress.toLowerCase()}`, () => (
      webRhTradeCore(userId, body, { ...internal, positionLockHeld: true })
    ));
  }
  const ETH = "0x0000000000000000000000000000000000000000";
  let fromCurrency, toCurrency, amountRaw;
  let tokenDecimals = 18;
  let solFunding = null;
  if (side === "buy") {
    const payCurrency = String(firstString(body.payCurrency, body.payWith, body.fundingAsset) || "").trim().toLowerCase();
    const solFundedBuy = ["sol", "solana", "native_sol"].includes(payCurrency) || (!body.amountEth && body.amountSol);
    let amountEth = Number(body.amountEth || 0);
    if (solFundedBuy) {
      const amountSol = Number(firstString(body.amountSol, body.amount) || 0);
      if (!Number.isFinite(amountSol) || amountSol < 0.005 || amountSol > 5) {
        const e = new Error("Enter a SOL amount between 0.005 and 5.");
        e.statusCode = 400; throw e;
      }
      const beforeEth = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0" }));
      const stableFundingId = firstString(body.fundingAttemptId);
      const fundingAttemptId = stableFundingId || (firstString(body.tradeAttemptId, body.clientRequestId)
        ? `${firstString(body.tradeAttemptId, body.clientRequestId)}-rh-sol-fund`
        : crypto.randomUUID());
      let funding = null;
      for (let fundingTry = 1; fundingTry <= 3; fundingTry += 1) {
        try {
          funding = await webRhFundWithSol(userId, {
            walletIndex: body.walletIndex,
            walletPublicKey: wallet.publicKey,
            amountSol,
            tradeAttemptId: fundingAttemptId,
            waitForDelivery: false
          });
          break;
        } catch (error) {
          // The idempotency receipt makes the same attempt safe to resume. Never
          // retry a submitted transaction whose outcome is unknown.
          if (error?.tradeSubmissionAmbiguous || fundingTry >= 3 || !isRetryableSwapError(error)) throw error;
          await sleep(750 * fundingTry);
        }
      }
      const quotedEth = Number(funding?.quotedEth || 0);
      const fundingReplayed = Boolean(funding?.duplicate);
      const targetEth = fundingReplayed
        ? Math.max(0.00001, Math.min(Number(beforeEth.eth || 0), quotedEth * 0.86))
        : Number(beforeEth.eth || 0) + Math.max(0.00001, quotedEth * 0.86);
      const afterEth = await waitForRhEthBalanceAtLeast(evmAddress, targetEth, 45_000);
      const spendPlan = await rhBuySpendPlan({
        availableWei: afterEth.wei || "0",
        quotedEth: funding?.quotedEth || "0",
        userReserveEth: body.rhGasReserveEth,
        rpcUrl: CONFIG.rhChainRpcUrl
      });
      amountEth = Number(spendPlan.spendEth || 0);
      solFunding = {
        amountSol,
        quotedEth: funding?.quotedEth || "",
        relayStatus: funding?.relayStatus || "",
        requestId: funding?.requestId || "",
        signature: funding?.signature || "",
        spendEth: amountEth,
        gasReserveEth: spendPlan.gasReserveEth
      };
      if (!(amountEth >= 0.00001)) {
        const e = new Error("SOL reached Robinhood, but this amount is too small after the live network fee reserve. Increase the SOL amount or retry when gas is lower.");
        e.statusCode = 425;
        throw e;
      }
    }
    if (!Number.isFinite(amountEth) || amountEth < 0.00001 || amountEth > 2) {
      const e = new Error("Enter an ETH amount between 0.00001 and 2.");
      e.statusCode = 400; throw e;
    }
    // Honeypot guard: NEVER let a buy through on a coin a real holder can't even transfer (can't-sell
    // trap). Fail-open only if the check itself errors — but a definite "can't sell" is a hard stop.
    const safety = await rhHoneypotCheck(tokenAddress, CONFIG.rhChainRpcUrl).catch(() => null);
    if (safety && safety.verdict === "block") {
      const e = new Error(`Blocked to protect you: ${safety.reasons[0] || "this coin can't be sold (honeypot)"}.`);
      e.statusCode = 400; throw e;
    }
    fromCurrency = ETH; toCurrency = tokenAddress;
    amountRaw = rhWeiFromEthNumber(amountEth); // ETH -> wei without float overflow
  } else if (side === "sell") {
    const percent = Math.min(100, Math.max(1, Number(body.percent || 100)));
    const bal = await rhErc20Balance(tokenAddress, evmAddress, CONFIG.rhChainRpcUrl);
    tokenDecimals = Number.isInteger(Number(bal.decimals)) ? Number(bal.decimals) : 18;
    amountRaw = (BigInt(bal.raw) * BigInt(Math.round(percent))) / 100n;
    if (amountRaw <= 0n) {
      const e = new Error("This wallet holds none of that coin on Robinhood Chain.");
      e.statusCode = 400; throw e;
    }
    fromCurrency = tokenAddress; toCurrency = ETH;
  } else {
    const e = new Error("side must be buy or sell.");
    e.statusCode = 400; throw e;
  }
  // Robinhood mirrors Solana's one fixed fee. A valid referral receives its
  // allocation from that total; otherwise a token-scoped Community Rewards
  // program may receive its own in-fee allocation. Neither can stack a surcharge.
  const referralTarget = await rhReferralTradeTarget(userId);
  const partner = referralTarget ? null : await partnerProgramByToken(tokenAddress, "robinhood").catch(() => null);
  const partnerPolicy = partnerTradeFeePolicy(partner);
  const allocationBps = referralTarget
    ? CONFIG.referralFeeBps
    : Math.min(CONFIG.baseTradeFeeBps, Number(partnerPolicy.rewardBps) || 0);
  const feeBps = BigInt(CONFIG.baseTradeFeeBps);
  let feeWei = 0n;
  let grossFeeBasisWei = 0n;
  if (side === "buy" && feeBps > 0n) {
    grossFeeBasisWei = amountRaw;
    feeWei = calculateTradeFeeAmount(grossFeeBasisWei, CONFIG.baseTradeFeeBps);
    amountRaw -= feeWei; // swap the remainder
  }
  // Relay aggregates every RH venue. If its index/API lags, query both live V3
  // factories directly before falling back to Sushi's hosted route API.
  const quoteAttempts = [
    ["Relay", () => relayQuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw })],
    ["Sushi V3", () => sushiV3QuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw, rpcUrl: CONFIG.rhChainRpcUrl })],
    ["Uniswap V3", () => uniswapQuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw, rpcUrl: CONFIG.rhChainRpcUrl })],
    ["Sushi API", () => sushiQuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw })]
  ];
  let quote = null;
  let hashes = [];
  const quoteErrors = [];
  // Fresh launch pools can be visible to one indexer a moment before every
  // route is executable. Requote safely inside this same funded trade. No
  // transaction is resubmitted when its outcome is unknown.
  for (let routeRound = 1; routeRound <= 4; routeRound += 1) {
    quote = null;
    const quoteResult = await firstSuccessfulRhQuote(quoteAttempts, routeRound);
    quoteErrors.push(...quoteResult.errors);
    quote = quoteResult.quote;
    if (quote) quote.fallbackQuoteErrors = quoteErrors.slice();
    if (!quote) {
      if (routeRound < 4) { await sleep(700 * routeRound); continue; }
      break;
    }
    try {
      ({ hashes } = await rhExecuteEvmSteps(keypair.secretKey, quote.txs, CONFIG.rhChainRpcUrl));
      break;
    } catch (error) {
      error.expectedRhTxCount = Array.isArray(quote?.txs) ? quote.txs.length : null;
      if (error?.tradeSubmissionAmbiguous || routeRound >= 4 || !isRetryableSwapError(error)) throw error;
      quoteErrors.push(`round ${routeRound} execute: ${friendlyError(error)}`);
      quote = null;
      await sleep(700 * routeRound);
    }
  }
  if (!quote) {
    const e = new Error(`No executable Robinhood trade route right now. ${quoteErrors.join(" ")}`.slice(0, 760));
    e.statusCode = 400;
    throw e;
  }
  if (side === "sell" && feeBps > 0n) {
    const outEth = Number(quote.outFormatted || 0);
    if (outEth > 0) {
      grossFeeBasisWei = BigInt(Math.round(outEth * 1e9)) * 10n ** 9n;
      feeWei = calculateTradeFeeAmount(grossFeeBasisWei, CONFIG.baseTradeFeeBps);
    }
  }
  // Skim the fee to the platform's RH fee account (converted to SOL at the fee wallet by the sweep).
  // Best-effort: the user's trade is already done — a failed skim logs, never throws.
  let feeTxHash = "";
  let partnerFeeTxHash = "";
  let referralFeeTxHash = "";
  if (feeWei > 0n) {
    try {
      const feeSplit = splitTradeFeeAllocation(feeWei, {
        totalFeeBps: CONFIG.baseTradeFeeBps,
        allocationBps,
        allocationEnabled: Boolean(referralTarget || partner)
      });
      const referralWei = referralTarget ? feeSplit.allocatedAmount : 0n;
      const partnerWei = !referralTarget && partner ? feeSplit.allocatedAmount : 0n;
      const ownerWei = feeSplit.ownerAmount;
      if (partnerWei > 0n && partner?.vaultRhWallet) {
        try {
          partnerFeeTxHash = await rhTransferEth(keypair.secretKey, partner.vaultRhWallet, partnerWei, CONFIG.rhChainRpcUrl);
          await recordPartnerRhFee({ programId: partner.id, token: tokenAddress, rewardWei: partnerWei, grossFeeWei: feeWei, signature: partnerFeeTxHash, userId });
        } catch (error) {
          await audit("web_rh_partner_fee_failed", { userId, tokenAddress, programId: partner.id, partnerWei: partnerWei.toString(), error: friendlyError(error) }).catch(() => {});
        }
      }
      if (referralWei > 0n && referralTarget?.address) {
        try {
          referralFeeTxHash = await rhTransferEth(keypair.secretKey, referralTarget.address, referralWei, CONFIG.rhChainRpcUrl);
          await audit("referral_rh_fee_paid", {
            userId,
            referrerUserId: referralTarget.referrerUserId,
            referralWallet: referralTarget.wallet,
            referralAddress: referralTarget.address,
            wei: referralWei.toString(),
            signature: referralFeeTxHash
          }).catch(() => {});
        } catch (error) {
          await audit("web_rh_referral_fee_failed", { userId, tokenAddress, referrerUserId: referralTarget.referrerUserId, referralWei: referralWei.toString(), error: friendlyError(error) }).catch(() => {});
        }
      }
      if (ownerWei > 0n) feeTxHash = await rhTransferEth(keypair.secretKey, rhFeeEvmWallet(CONFIG.appSecret, CONFIG.rhChainRpcUrl).address, ownerWei, CONFIG.rhChainRpcUrl);
    } catch (error) {
      await audit("web_rh_fee_skim_failed", { userId, side, tokenAddress, feeWei: feeWei.toString(), error: friendlyError(error) }).catch(() => {});
    }
  }
  scheduleRhFeeSweep(); // fire-and-forget: converts the pot to SOL at the fee wallet when big enough
  // Creator fee (pump-style, venue-side): if this coin's launcher opted in, pay them their % of this
  // trade in ETH — straight to their wallet, on top of the platform fee. Best-effort, never blocks.
  let creatorFeeTxHash = "";
  let holderRewardTxHashes = [];
  let holderRewardCount = 0;
  try {
    const meta = (await rhLaunchMetaByAddress().catch(() => new Map())).get(tokenAddress.toLowerCase());
    const cBps = BigInt(Math.max(0, (meta && meta.creatorFeeBps) || 0));
    const cRecipient = meta && meta.creatorFeeRecipient;
    if (cBps > 0n && /^0x[0-9a-fA-F]{40}$/.test(String(cRecipient || "")) && String(cRecipient).toLowerCase() !== evmAddress.toLowerCase()) {
      let cWei = 0n;
      if (side === "buy") cWei = (feeBps > 0n ? (amountRaw + feeWei) : amountRaw) * cBps / 10_000n; // % of gross ETH in
      else { const outEth = Number(quote.outFormatted || 0); if (outEth > 0) cWei = (BigInt(Math.round(outEth * 1e9)) * 10n ** 9n * cBps) / 10_000n; }
      if (cWei > 0n) {
        let paidToHolders = 0n;
        const holderPolicy = normalizeHolderRewardPolicy(meta?.holderRewards || {});
        if (holderPolicy.enabled) {
          const secretKey = keypair.secretKey;
          const creatorRecipient = cRecipient;
          const settleHolderAndCreatorRewards = async () => {
            let dist = null;
            try {
              dist = await distributeRhHolderRewards({
                signerSecretKey: secretKey,
                tokenAddress,
                policy: holderPolicy,
                totalWei: cWei,
                payerAddress: evmAddress
              });
            } catch (error) {
              await audit("web_rh_holder_rewards_failed", { userId, tokenAddress, error: friendlyError(error) }).catch(() => {});
            }
            const asyncPaidToHolders = BigInt(dist?.paidWei || 0);
            const asyncCreatorWei = cWei > asyncPaidToHolders ? cWei - asyncPaidToHolders : 0n;
            let asyncCreatorFeeTxHash = "";
            if (asyncCreatorWei > 0n) {
              try { asyncCreatorFeeTxHash = await rhTransferEth(secretKey, creatorRecipient, asyncCreatorWei, CONFIG.rhChainRpcUrl); }
              catch (error) { await audit("web_rh_creator_fee_failed", { userId, tokenAddress, error: friendlyError(error) }).catch(() => {}); }
            }
            await audit("web_rh_holder_rewards_payout", {
              userId,
              tokenAddress,
              holderRewardCount: Number(dist?.count || 0),
              holderRewardTxHashes: dist?.txHashes || [],
              holderRewardWei: asyncPaidToHolders.toString(),
              creatorFeeTxHash: asyncCreatorFeeTxHash,
              creatorWei: asyncCreatorWei.toString()
            }).catch(() => {});
            return { dist, creatorFeeTxHash: asyncCreatorFeeTxHash };
          };
          if (side === "sell") {
            // A sell cashes the wallet back to SOL below. Finish every payout
            // from this signer first so Cash out all cannot drain reward funds
            // or race the payout transactions for the same EVM nonce.
            const settlement = await settleHolderAndCreatorRewards();
            holderRewardTxHashes = Array.isArray(settlement.dist?.txHashes) ? settlement.dist.txHashes : [];
            holderRewardCount = Number(settlement.dist?.count || 0);
            creatorFeeTxHash = settlement.creatorFeeTxHash || "";
          } else {
            // Buys have no same-request cash-out, so keep their receipt fast.
            void settleHolderAndCreatorRewards().catch(() => {});
            holderRewardTxHashes = ["queued"];
            holderRewardCount = -1;
          }
          paidToHolders = cWei;
        }
        const creatorWei = cWei > paidToHolders ? cWei - paidToHolders : 0n;
        if (creatorWei > 0n) creatorFeeTxHash = await rhTransferEth(keypair.secretKey, cRecipient, creatorWei, CONFIG.rhChainRpcUrl);
      }
    }
  } catch (error) {
    await audit("web_rh_creator_fee_failed", { userId, tokenAddress, error: friendlyError(error) }).catch(() => {});
  }
  // User-facing Robinhood trading is SOL-first. After a sell lands, sweep the
  // remaining ETH proceeds back to the same managed wallet's Solana address.
  // Internal volume rounds opt out because they reuse ETH within one run.
  let solCashout = null;
  let solCashoutError = "";
  const autoCashout = side === "sell"
    && !Boolean(body.skipAutoCashout)
    && String(body.source || "").trim().toLowerCase() !== "rh_volume";
  if (autoCashout) {
    try {
      solCashout = await webRhBridgeToSolCore(userId, {
        walletIndex: body.walletIndex,
        walletPublicKey: wallet.publicKey,
        amountEth: "all"
      });
    } catch (error) {
      // The token sale is already final. Keep the ETH safely in the same wallet
      // and report the separate settlement failure without inviting a re-sell.
      solCashoutError = friendlyError(error);
      await audit("web_rh_auto_cashout_failed", {
        userId,
        wallet: wallet.publicKey,
        evmAddress,
        tokenAddress,
        error: solCashoutError
      }).catch(() => {});
    }
  }
  const [ethBal, tokenBal] = await Promise.all([
    rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0" })),
    rhErc20Balance(tokenAddress, evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ uiAmount: 0 }))
  ]);
  let recordError = "";
  try {
    await audit("web_rh_trade", { userId, wallet: wallet.publicKey, evmAddress, side, tokenAddress, txHashes: hashes, out: quote.outFormatted, impact: quote.impactPercent, feeWei: feeWei.toString(), feeTxHash, partnerFeeTxHash, referralFeeTxHash, creatorFeeTxHash, holderRewardTxHashes, holderRewardCount, solFunding, solCashout, solCashoutError, source: firstString(body.source, "web_rh_trade") });
  } catch (error) {
    // The chain transaction already landed. Never turn a delayed audit write
    // into a failed response that invites the user to submit the trade again.
    recordError = `Audit: ${friendlyError(error)}`;
  }
  // 🥊 PvP live feed: Robinhood trades count too — post to the trader's arena groups. Direct call
  // (not recordTradeEvents) so 0x rows never pollute the SOL trade history / PnL boards.
  const rhTradeEvent = {
    userId,
    type: side,
    tokenMint: tokenAddress,
    tokenAddress,
    walletIndex: parseWebWalletIndex(body.walletIndex),
    walletPublicKey: wallet.publicKey,
    signature: hashes[hashes.length - 1],
    tradeAttemptId: firstString(body.tradeAttemptId, body.clientRequestId),
    ...(internal.tradeProvenanceId ? { provenanceId: String(internal.tradeProvenanceId).slice(0, 128) } : {}),
    symbol: side === "buy" ? String(quote.outSymbol || "") : "",
    tokenUiAmount: side === "buy"
      ? String(quote.outFormatted || "0")
      : String(rawCashAmountToUi(amountRaw, tokenDecimals)),
    rhEthAmount: side === "buy"
      ? String(rawCashAmountToUi(amountRaw, 18))
      : String(quote.outFormatted || "0"),
    ...(solFunding ? { solLamportsSpent: String(solToLamports(solFunding.amountSol)) } : {}),
    // A sell may sweep *all* wallet ETH back to SOL, including ETH that was
    // already present. Keep the exact sale proceeds in rhEthAmount and record
    // the broader settlement separately so one sell is never overstated.
    ...(solCashout?.outSol ? { settlementOutSol: String(solCashout.outSol), autoCashout: true } : {}),
  };
  // Await the local receipt write so Positions can discover a just-bought token before Blockscout indexes it.
  // recordRhTradeEvent is internally failure-safe, so a delayed analytics write can never turn a landed trade
  // into a failed response or invite a duplicate submission.
  await recordRhTradeEvent({ ...rhTradeEvent, chain: "robinhood", source: firstString(body.source, "web_rh_trade") });
  void pvpBroadcastTradeEvents([rhTradeEvent]).catch(() => {});
  void notifyProfileTradeFollowers([{ id: `rh-${hashes[hashes.length - 1]}`, ...rhTradeEvent }]).catch(() => {});
  return {
    ok: true,
    side,
    txHashes: hashes,
    explorerTx: `https://robinhoodchain.blockscout.com/tx/${hashes[hashes.length - 1]}`,
    outFormatted: quote.outFormatted,
    outSymbol: quote.outSymbol,
    impactPercent: quote.impactPercent,
    feeEth: feeWei > 0n ? lamportsToSol(Number(feeWei / 10n ** 9n)) : "0", // wei -> gwei -> formatted like SOL (both 9dp)
    ethBalance: ethBal.eth,
    tokenBalance: tokenBal.uiAmount,
    solFunding,
    solCashout,
    solCashoutError,
    recordError
  };
}

// Debounced fee sweep: at most one attempt per 10 min, only when the pot clears the threshold. The
// SOL lands at CONFIG.feeWallet — same pile as every Solana trading fee.
let rhFeeSweepBusy = false;
let rhFeeSweepLastMs = 0;
function scheduleRhFeeSweep() {
  if (rhFeeSweepBusy || Date.now() - rhFeeSweepLastMs < 600_000) return;
  rhFeeSweepBusy = true;
  setTimeout(async () => {
    try {
      const result = await rhSweepFeesToSol({ appSecret: CONFIG.appSecret, solFeeWallet: CONFIG.feeWallet, rpcUrl: CONFIG.rhChainRpcUrl, minEth: CONFIG.rhFeeSweepMinEth });
      rhFeeSweepLastMs = Date.now();
      if (result.swept) await audit("web_rh_fee_sweep", { sentEth: result.sentEth, outSol: result.outSol, hashes: result.hashes, to: CONFIG.feeWallet });
    } catch (error) {
      rhFeeSweepLastMs = Date.now(); // failed attempts also wait out the debounce (no hot-looping)
      console.warn(`[rh-fees] sweep failed: ${friendlyError(error)}`);
    } finally {
      rhFeeSweepBusy = false;
    }
  }, 2_000);
}

// ---------- Robinhood Chain power tools: TP/SL guards, bundle buys, volume bot ----------
// Same features the Solana side has, on RH coins. All trades route through webRhTradeCore (Relay
// swaps, gas-estimated, fee-skimmed), so every tool inherits the same safety + fee behavior.

// TP/SL guards: armed positions persisted to disk; a ticker checks pool-implied prices (Relay quote —
// Render's IP is rate-limited on DexScreener, and implied prices work even for unindexed coins) and
// fires the sell through the normal trade path when a target/floor is hit.
function rhGuardsPath() { return path.join(CONFIG.dataDir, "rh-exit-guards.json"); }
async function readRhGuards() {
  const store = await readJson(rhGuardsPath()).catch(() => null);
  return store && Array.isArray(store.guards) ? store : { guards: [] };
}
async function writeRhGuards(store) { await writeJsonFile(rhGuardsPath(), store); }
async function mutateRhGuards(fn) {
  return withFileLock(rhGuardsPath(), async () => {
    const store = await readRhGuards();
    const result = await fn(store);
    await writeRhGuards(store);
    return result;
  });
}

function pruneRhGuardHistory(guards = [], terminalLimit = 300) {
  const terminal = new Set(["triggered", "cancelled", "canceled", "failed", "expired"]);
  const terminalRows = guards.filter((guard) => terminal.has(String(guard?.status || "").toLowerCase()));
  const keepTerminal = new Set(terminalRows.slice(-Math.max(0, terminalLimit)).map((guard) => guard.id));
  // Never discard a guard that can still protect money or whose outcome needs
  // review. Only old, definitively terminal history is bounded.
  return guards.filter((guard) => {
    const status = String(guard?.status || "").toLowerCase();
    return !terminal.has(status) || keepTerminal.has(guard.id);
  });
}

async function webRhArmGuard(userId, body = {}) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId),
    body.walletPublicKey,
    "Robinhood guard"
  );
  const tokenAddress = String(body.tokenAddress || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) { const e = new Error("Invalid token address."); e.statusCode = 400; throw e; }
  const kind = ["limit-buy", "limit-sell"].includes(String(body.kind || body.orderType || "").toLowerCase())
    ? String(body.kind || body.orderType).toLowerCase()
    : "exit";
  const exitSlot = kind === "exit"
    ? (String(body.exitSlot || "single").trim().replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 48) || "single")
    : null;
  const exitGroup = kind === "exit"
    ? (String(body.exitGroup || "").trim().replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 64) || null)
    : null;
  const tpPct = Number(body.takeProfitPct || 0);
  const slPct = Number(body.stopLossPct || 0);
  const sellPercent = Math.min(100, Math.max(1, Number(body.sellPercent || 100)));
  const amountSol = Number(body.amountSol || 0);
  const targetMarketCapUsd = Number(String(body.targetMarketCapUsd || body.targetMc || "0").replace(/[$,\s]/g, ""));
  if (kind === "exit" && !(tpPct > 0) && !(slPct > 0)) { const e = new Error("Set a take-profit %, a stop-loss %, or both."); e.statusCode = 400; throw e; }
  if (kind !== "exit" && (!Number.isFinite(targetMarketCapUsd) || !(targetMarketCapUsd > 0) || targetMarketCapUsd > 1_000_000_000_000_000)) { const e = new Error("Enter a valid target market cap."); e.statusCode = 400; throw e; }
  if (kind === "limit-buy" && (!(amountSol >= 0.005) || amountSol > 5)) { const e = new Error("Enter a buy amount between 0.005 and 5 SOL."); e.statusCode = 400; throw e; }
  if (kind === "limit-sell" && (!Number.isFinite(Number(body.sellPercent)) || Number(body.sellPercent) < 1 || Number(body.sellPercent) > 100)) { const e = new Error("Sell percent must be between 1 and 100."); e.statusCode = 400; throw e; }
  const automationPermission = await requireWebAutomationPermission(userId, kind === "exit" ? "Robinhood TP/SL guard" : "Robinhood limit order");
  const clientEntryPriceUsd = Number(body.entryPriceUsd || 0);
  const [scanInfo, implied] = await Promise.all([
    kind !== "exit" ? gatherRhScan(tokenAddress).catch(() => null) : Promise.resolve(null),
    // A browser quote can be several refreshes old by the time the buy lands. Always
    // anchor an automated exit to a fresh server-side executable quote; the client
    // value is display context only and is used solely when both live sources fail.
    rhImpliedPriceUsd(tokenAddress, rhFeeEvmWallet(CONFIG.appSecret, CONFIG.rhChainRpcUrl).address).catch(() => null)
  ]);
  const entryPriceUsd = firstMeaningfulNumber(
    implied?.priceUsd,
    scanInfo?.priceUsd,
    clientEntryPriceUsd
  ) || 0;
  if (!(entryPriceUsd > 0)) { const e = new Error("Couldn't read a live price for this coin — try again in a moment."); e.statusCode = 400; throw e; }
  const currentMarketCapUsd = firstMeaningfulNumber(scanInfo?.mc, body.currentMarketCapUsd) || 0;
  const supply = firstMeaningfulNumber(scanInfo?.supply, currentMarketCapUsd > 0 ? currentMarketCapUsd / entryPriceUsd : 0) || 0;
  const targetPriceUsd = kind !== "exit" && supply > 0 ? targetMarketCapUsd / supply : 0;
  if (kind !== "exit" && !(targetPriceUsd > 0)) { const e = new Error("Couldn't calculate this coin's target price yet — wait for market data, then try again."); e.statusCode = 400; throw e; }
  const guard = {
    id: String(body.pendingGuardId || "").trim() || crypto.randomUUID(),
    userId,
    walletIndex: parseWebWalletIndex(body.walletIndex),
    walletPublicKey: wallet.publicKey,
    tokenAddress,
    symbol: String(body.symbol || "").slice(0, 16),
    kind,
    exitSlot,
    exitGroup,
    closesPosition: kind === "exit" && cleanLaunchBoolean(body.closesPosition),
    entryPriceUsd,
    takeProfitPct: kind === "exit" && tpPct > 0 ? tpPct : null,
    stopLossPct: kind === "exit" && slPct > 0 ? slPct : null,
    targetMarketCapUsd: kind !== "exit" ? targetMarketCapUsd : null,
    targetPriceUsd: kind !== "exit" ? targetPriceUsd : null,
    triggerDirection: kind !== "exit" ? (targetPriceUsd >= entryPriceUsd ? ">=" : "<=") : null,
    amountSol: kind === "limit-buy" ? amountSol : null,
    sellPercent,
    automationPermission,
    status: "active",
    failCount: 0,
    createdAt: new Date().toISOString()
  };
  await mutateRhGuards((gs) => {
    const pendingIndex = gs.guards.findIndex((row) => (
      row.id === guard.id
      && row.userId === userId
      && String(row.walletPublicKey || "") === guard.walletPublicKey
      && String(row.tokenAddress || "").toLowerCase() === tokenAddress.toLowerCase()
      && ["pending_buy", "arming", "outcome_unknown", "needs_attention"].includes(String(row.status || "").toLowerCase())
    ));
    const unresolvedCollision = gs.guards.find((g) => (
      g.id !== guard.id
      &&
      g.userId === userId
      && String(g.walletPublicKey || "") === guard.walletPublicKey
      && g.tokenAddress.toLowerCase() === tokenAddress.toLowerCase()
      && String(g.kind || "exit") === kind
      && (kind === "exit"
        ? String(g.exitSlot || "single") === exitSlot
        : Number(g.targetMarketCapUsd) === Number(guard.targetMarketCapUsd))
      && automationExitReplacementBlocked(g)
    ));
    if (unresolvedCollision) {
      const error = new Error("This exit is still submitting or needs attention. Check its receipt before changing protection.");
      error.statusCode = 409;
      throw error;
    }
    const sameToken = gs.guards.filter((g) => g.status === "active" && g.userId === userId && String(g.walletPublicKey || "") === guard.walletPublicKey && g.tokenAddress.toLowerCase() === tokenAddress.toLowerCase());
    if (sameToken.length >= 12) { const error = new Error("This coin already has 12 active orders. Cancel one before adding another."); error.statusCode = 400; throw error; }
    // Replace only the exact same target/slot. A named exitSlot lets a Telegram ladder keep
    // multiple staged exits plus one independent stop, while the default "single" slot retains
    // the old one-TP/one-SL replacement behavior for every existing caller.
    gs.guards = gs.guards.filter((g) => !(
      g.status === "active"
      && g.userId === userId
      && String(g.walletPublicKey || "") === guard.walletPublicKey
      && g.tokenAddress.toLowerCase() === tokenAddress.toLowerCase()
      && String(g.kind || "exit") === kind
      && (kind === "exit"
        ? String(g.exitSlot || "single") === exitSlot
        : Number(g.targetMarketCapUsd) === Number(guard.targetMarketCapUsd))
    ));
    const livePendingIndex = pendingIndex >= 0 ? gs.guards.findIndex((row) => row.id === guard.id) : -1;
    if (livePendingIndex >= 0) {
      guard.createdAt = gs.guards[livePendingIndex].createdAt || guard.createdAt;
      guard.protectionIntent = "armed";
      guard.protectionFinalizedAt = new Date().toISOString();
      gs.guards[livePendingIndex] = guard;
    } else {
      gs.guards.push(guard);
    }
    gs.guards = pruneRhGuardHistory(gs.guards);
  });
  await audit("web_rh_guard_arm", { userId, tokenAddress, kind, tpPct, slPct, sellPercent, amountSol, entryPriceUsd, targetMarketCapUsd, targetPriceUsd }).catch(() => {});
  return { ok: true, guard };
}

async function webRhGuards(userId) {
  const gs = await readRhGuards();
  const mine = gs.guards
    .filter((guard) => guard.userId === userId)
    .sort((left, right) => Date.parse(right.updatedAt || right.createdAt || 0) - Date.parse(left.updatedAt || left.createdAt || 0));
  const active = mine.filter((guard) => ["active", "pending_buy", "arming", "submitting", "manual_sell_submitting", "outcome_unknown", "needs_attention"].includes(String(guard.status || "").toLowerCase()));
  const history = mine.filter((guard) => !active.includes(guard)).slice(0, Math.max(0, 100 - active.length));
  return { ok: true, guards: [...active, ...history] };
}

async function webRhCancelGuard(userId, body = {}) {
  await mutateRhGuards((gs) => {
    const guard = gs.guards.find((g) => g.id === String(body.id || "") && g.userId === userId);
    if (!guard) { const e = new Error("Guard not found."); e.statusCode = 404; throw e; }
    if (String(guard.status || "").toLowerCase() !== "active") {
      const e = new Error("This order is already submitting or finished. Refresh its status before taking another action.");
      e.statusCode = 409;
      throw e;
    }
    guard.status = "cancelled";
    guard.cancelledAt = new Date().toISOString();
    guard.updatedAt = new Date().toISOString();
  });
  return { ok: true };
}

// Auto-bundle-when-pool-opens: the honest version of "bundle at launch" for RH. A brand-new coin has
// no pool to buy from, so we ARM a bundle; the guard ticker watches for a tradeable pool and fires the
// bundle the instant one appears (24h window). Persisted next to the guards.
function rhAutoBundlesPath() { return path.join(CONFIG.dataDir, "rh-auto-bundles.json"); }
async function readRhAutoBundles() {
  const store = await readJson(rhAutoBundlesPath()).catch(() => null);
  return store && Array.isArray(store.bundles) ? store : { bundles: [] };
}
async function writeRhAutoBundles(store) { await writeJsonFile(rhAutoBundlesPath(), store); }
function rhLaunchBundleWalletConfigs(body = {}, indexes = []) {
  const allowed = new Set(indexes.map((value) => Number(value)));
  const rows = Array.isArray(body.walletConfigs) ? body.walletConfigs : [];
  return rows.map((row) => {
    const walletIndex = Number.parseInt(row?.walletIndex, 10);
    const amountSol = Number(row?.amountSol);
    if (!allowed.has(walletIndex)) return null;
    if (!(amountSol > 0) || amountSol > 5) { const error = new Error("Each Robinhood bundle buy must be between 0 and 5 SOL."); error.statusCode = 400; throw error; }
    return { walletIndex, amountSol, exitStrategy: pumpLaunchExitStrategy(row?.exitStrategy || {}) };
  }).filter(Boolean);
}
async function webRhArmAutoBundle(userId, body = {}) {
  const tokenAddress = String(body.tokenAddress || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) { const e = new Error("Invalid token address."); e.statusCode = 400; throw e; }
  const indexes = (Array.isArray(body.walletIndexes) ? body.walletIndexes : []).map((v) => Number.parseInt(v, 10)).filter((n) => Number.isInteger(n) && n >= 1);
  if (!indexes.length || indexes.length > 20) { const e = new Error("Pick 1-20 wallets."); e.statusCode = 400; throw e; }
  const solFunded = body.minSol != null || body.maxSol != null || ["sol", "solana"].includes(String(body.payCurrency || body.payWith || "").toLowerCase());
  const minAmount = Number(solFunded ? body.minSol : body.minEth || 0);
  const maxAmount = Number(solFunded ? body.maxSol : body.maxEth || 0);
  const maxAllowed = solFunded ? 5 : 0.5;
  const unit = solFunded ? "SOL" : "ETH";
  if (!(minAmount > 0) || !(maxAmount >= minAmount) || maxAmount > maxAllowed) { const e = new Error(`Buy range must be 0 < min ≤ max ≤ ${maxAllowed} ${unit}.`); e.statusCode = 400; throw e; }
  const walletConfigs = solFunded ? rhLaunchBundleWalletConfigs(body, indexes) : [];
  const store = await readRhAutoBundles();
  store.bundles = store.bundles.filter((b) => !(b.status === "armed" && b.userId === userId && b.tokenAddress.toLowerCase() === tokenAddress.toLowerCase()));
  const bundle = { id: crypto.randomUUID(), userId, tokenAddress, walletIndexes: indexes, ...(walletConfigs.length ? { walletConfigs } : {}), fundingAsset: solFunded ? "sol" : "eth", ...(solFunded ? { minSol: minAmount, maxSol: maxAmount } : { minEth: minAmount, maxEth: maxAmount }), symbol: String(body.symbol || "").slice(0, 16), launchWave: Boolean(body.launchWave), status: "armed", createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + 86_400_000).toISOString() };
  store.bundles.push(bundle);
  store.bundles = store.bundles.slice(-200);
  await writeRhAutoBundles(store);
  await audit("web_rh_autobundle_arm", { userId, tokenAddress, wallets: indexes.length });
  return { ok: true, bundle };
}
async function webRhAutoBundles(userId) {
  const store = await readRhAutoBundles();
  return { ok: true, bundles: store.bundles.filter((b) => b.userId === userId).slice(-30).reverse() };
}
async function webRhCancelAutoBundle(userId, body = {}) {
  const store = await readRhAutoBundles();
  const b = store.bundles.find((x) => x.id === String(body.id || "") && x.userId === userId);
  if (!b) { const e = new Error("Not found."); e.statusCode = 404; throw e; }
  b.status = "cancelled";
  await writeRhAutoBundles(store);
  return { ok: true };
}
async function rhAutoBundleTick(probe) {
  const store = await readRhAutoBundles();
  const armed = store.bundles.filter((b) => b.status === "armed");
  if (!armed.length) return;
  let changed = false;
  for (const b of armed) {
    if (Date.parse(b.expiresAt) < Date.now()) { b.status = "expired"; changed = true; continue; }
    const res = await rhImpliedPriceUsd(b.tokenAddress, probe).catch(() => null);
    if (!res || res.noPool || !(res.priceUsd > 0)) continue; // no pool yet — keep waiting
    b.status = "firing"; changed = true;
    await writeRhAutoBundles(store); // persist BEFORE the slow bundle so a restart can't double-fire
    try {
      const result = await webRhBundleCore(b.userId, {
        tokenAddress: b.tokenAddress,
        walletIndexes: b.walletIndexes,
        walletConfigs: b.walletConfigs,
        launchWave: Boolean(b.launchWave),
        ...(b.fundingAsset === "sol" || b.minSol != null
          ? { payCurrency: "SOL", minSol: b.minSol, maxSol: b.maxSol }
          : { minEth: b.minEth, maxEth: b.maxEth })
      });
      const failedRows = (result.rows || []).filter((row) => !row.ok);
      b.status = failedRows.length ? "needs_attention" : "fired";
      b.firedAt = new Date().toISOString();
      b.result = result.summary;
      b.rows = (result.rows || []).map((row) => ({
        walletIndex: row.walletIndex,
        walletPublicKey: row.walletPublicKey,
        ok: Boolean(row.ok),
        ...(row.ok ? { tx: row.tx, exitStatus: row.exitStatus } : { error: row.error })
      }));
      console.log(`[rh-autobundle] token=${shortMint(b.tokenAddress)} ${result.summary}`);
      await audit("web_rh_autobundle_fired", { userId: b.userId, tokenAddress: b.tokenAddress, summary: result.summary });
    } catch (error) {
      b.status = "failed"; b.lastError = friendlyError(error).slice(0, 200);
    }
  }
  if (changed) await writeRhAutoBundles(store);
}

let rhGuardTickBusy = false;

async function recoverRhAutoExitProtectionIntents(limit = 4) {
  const [guardStore, historyStore] = await Promise.all([
    readRhGuards(),
    readRhTradeHistory().catch(() => ({ trades: [] }))
  ]);
  const candidates = objectRows(guardStore.guards)
    .filter((guard) => guard.kind === "exit" && guard.protectionIntent === "pending_buy")
    .filter((guard) => ["pending_buy", "arming", "outcome_unknown", "needs_attention"].includes(String(guard.status || "").toLowerCase()))
    .filter((guard) => {
      const last = Date.parse(guard.lastProtectionRecoveryAt || guard.updatedAt || guard.createdAt || 0);
      return !Number.isFinite(last) || Date.now() - last >= 5_000;
    })
    .slice(0, Math.max(1, Math.min(10, Number(limit) || 4)));
  let recovered = 0;
  const provider = rhProvider(CONFIG.rhChainRpcUrl);
  for (const guard of candidates) {
    const receipt = objectRows(historyStore.trades).find((trade) => (
      String(trade.userId || "") === String(guard.userId || "")
      && String(trade.walletPublicKey || "") === String(guard.walletPublicKey || "")
      && String(trade.tokenAddress || trade.tokenMint || "").toLowerCase() === String(guard.tokenAddress || "").toLowerCase()
      && String(trade.tradeAttemptId || "") === String(guard.tradeAttemptId || "")
      && String(trade.type || "").toLowerCase() === "buy"
      && Boolean(trade.signature)
    ));
    const hashes = [...new Set((Array.isArray(guard.txHashes) ? guard.txHashes : [])
      .map((value) => String(value || "").trim())
      .filter((value) => /^0x[0-9a-fA-F]{64}$/.test(value)))];
    let buyConfirmed = Boolean(guard.buyConfirmed || receipt);
    if (!buyConfirmed && hashes.length) {
      const receipts = await Promise.all(hashes.map((hash) => provider.getTransactionReceipt(hash).catch(() => null)));
      const failedReceipt = receipts.find((row) => row && Number(row.status) === 0);
      if (failedReceipt) {
        await updateRhAutoExitProtection(guard.id, {
          status: "failed",
          protectionIntent: "failed",
          lastProtectionRecoveryAt: new Date().toISOString(),
          lastError: "The signed Robinhood buy failed on-chain; protection was not armed and the buy was not replayed."
        }).catch(() => {});
        continue;
      }
      const expected = Math.max(1, Number(guard.expectedRhTxCount || hashes.length) || hashes.length);
      buyConfirmed = hashes.length >= expected
        && receipts.length >= expected
        && receipts.slice(0, expected).every((row) => row && Number(row.status) === 1);
      if (!buyConfirmed) {
        await updateRhAutoExitProtection(guard.id, {
          status: "outcome_unknown",
          txHashes: hashes,
          lastProtectionRecoveryAt: new Date().toISOString(),
          lastError: "The signed Robinhood buy is still awaiting complete on-chain receipts. No replay will be sent."
        }).catch(() => {});
        continue;
      }
    }
    if (!buyConfirmed) {
      await updateRhAutoExitProtection(guard.id, {
        lastProtectionRecoveryAt: new Date().toISOString()
      }).catch(() => {});
      continue;
    }
    try {
      await webRhArmGuard(guard.userId, {
        walletIndex: guard.walletIndex,
        walletPublicKey: guard.walletPublicKey,
        tokenAddress: guard.tokenAddress,
        symbol: guard.symbol,
        takeProfitPct: guard.takeProfitPct,
        stopLossPct: guard.stopLossPct,
        sellPercent: guard.sellPercent || 100,
        pendingGuardId: guard.id
      });
      recovered += 1;
    } catch (error) {
      await updateRhAutoExitProtection(guard.id, {
        status: "needs_attention",
        buyConfirmed,
        txHashes: hashes.length ? hashes : (receipt?.signature ? [receipt.signature] : []),
        lastProtectionRecoveryAt: new Date().toISOString(),
        lastError: `Protection recovery retry: ${friendlyError(error)}`.slice(0, 300)
      }).catch(() => {});
    }
  }
  return recovered;
}

async function reconcileStaleRhGuardSubmissions() {
  // A live Relay trade can legitimately take longer than a minute. Do not
  // classify it as unknown while its 180s submission lease may still be live.
  const staleMs = Math.max(5 * 60_000, Number(CONFIG.stopLossSubmitStaleMs || 90_000));
  const now = Date.now();
  return mutateRhGuards(async (store) => {
    let reconciled = 0;
    for (const guard of store.guards || []) {
      if (String(guard.status || "").toLowerCase() !== "submitting") continue;
      if (!staleAutomationClaim(guard.submittingAt || guard.updatedAt, now, staleMs)) continue;

      const resultKey = externalCacheKey(`web-rh-trade-result:rh-order-${guard.id}`, guard.userId);
      const cached = await idemResultGet(resultKey).catch(() => null);
      if (cached?.result) {
        guard.status = "triggered";
        guard.triggeredAt = guard.triggeredAt || new Date().toISOString();
        guard.txHashes = Array.isArray(cached.result.txHashes) ? cached.result.txHashes : guard.txHashes || [];
        guard.lastError = null;
        if (guard.closesPosition && guard.exitGroup) {
          for (const sibling of store.guards || []) {
            if (sibling.id === guard.id || sibling.status !== "active") continue;
            if (sibling.userId !== guard.userId) continue;
            if (String(sibling.walletPublicKey || "") !== String(guard.walletPublicKey || "")) continue;
            if (String(sibling.tokenAddress || "").toLowerCase() !== String(guard.tokenAddress || "").toLowerCase()) continue;
            if (String(sibling.exitGroup || "") !== String(guard.exitGroup)) continue;
            sibling.status = "canceled";
            sibling.cancelReason = `position closed by ${guard.trigger || "exit"}`;
            sibling.updatedAt = guard.triggeredAt;
          }
        }
      } else {
        // Never blindly re-arm a money action after a process restart. If the
        // idempotency receipt is unavailable, surface the uncertainty and stop.
        guard.status = "outcome_unknown";
        guard.lastError = cached?.ambiguousError?.message
          || "The prior submission may have reached the chain. Automatic retry is paused to prevent a duplicate trade.";
        guard.txHashes = Array.isArray(cached?.ambiguousError?.partialHashes)
          ? cached.ambiguousError.partialHashes
          : guard.txHashes || [];
      }
      guard.reconciledAt = new Date().toISOString();
      guard.updatedAt = guard.reconciledAt;
      reconciled += 1;
    }
    return { reconciled };
  });
}

async function rhGuardTick() {
  if (rhGuardTickBusy) return { skipped: true, reason: "rh_guard_tick_active" };
  rhGuardTickBusy = true;
  const summary = { checked: 0, triggered: 0, executed: 0, failed: 0, reconciled: 0 };
  try {
    const probe = rhFeeEvmWallet(CONFIG.appSecret, CONFIG.rhChainRpcUrl).address;
    summary.recoveredProtection = await recoverRhAutoExitProtectionIntents().catch((error) => {
      console.warn(`[rh-guards] pending protection recovery failed: ${friendlyError(error)}`);
      return 0;
    });
    const reconciliation = await reconcileStaleRhGuardSubmissions().catch((error) => {
      console.warn(`[rh-guards] stale submission reconciliation failed: ${friendlyError(error)}`);
      return null;
    });
    summary.reconciled = Number(reconciliation?.reconciled || 0);
    await rhAutoBundleTick(probe).catch((e) => console.warn(`[rh-autobundle] ${friendlyError(e)}`));
    const gs = await readRhGuards();
    const active = gs.guards.filter((g) => g.status === "active");
    if (!active.length) return summary;
    const [automationStore, walletStore] = await Promise.all([
      readWebAuthStore().catch(() => null),
      readWalletStore()
    ]);
    const priceByToken = new Map();
    const guardUpdates = new Map();
    for (const guard of active) {
      // A full-position sibling (final ladder rung or stop) may cancel this guard earlier in the same tick.
      if (guard.status !== "active") continue;
      summary.checked += 1;
      if (guard.automationPermission) {
        const currentProfile = automationStore?.profiles?.[String(guard.userId)] || {};
        if (!webAutomationExecutionAllowed(guard.automationPermission, currentProfile)) {
          guard.lastError = "Managed-wallet automation permission is inactive. Re-enable it to resume this guard.";
          guard.updatedAt = new Date().toISOString();
          guardUpdates.set(guard.id, { guard: { ...guard }, expectedStatus: "active" });
          continue;
        }
      }
      const key = guard.tokenAddress.toLowerCase();
      if (!priceByToken.has(key)) priceByToken.set(key, await rhImpliedPriceUsd(guard.tokenAddress, probe).catch(() => null));
      const res = priceByToken.get(key);
      const price = res && res.priceUsd > 0 ? res.priceUsd : 0;
      if (!(price > 0)) continue;
      const movePct = ((price - guard.entryPriceUsd) / guard.entryPriceUsd) * 100;
      const kind = String(guard.kind || "exit");
      const hitTp = kind === "exit" && guard.takeProfitPct != null && movePct >= guard.takeProfitPct;
      const hitSl = kind === "exit" && guard.stopLossPct != null && movePct <= -guard.stopLossPct;
      const hitLimit = kind !== "exit" && Number(guard.targetPriceUsd) > 0
        && (guard.triggerDirection === ">=" ? price >= Number(guard.targetPriceUsd) : price <= Number(guard.targetPriceUsd));
      if (!hitTp && !hitSl && !hitLimit) continue;
      summary.triggered += 1;
      let claimedForSubmission = false;
      try {
        await requireWebAutomationPermission(guard.userId, "Robinhood guard submission");
        const ownerWallets = walletsForOwner(walletStore, guard.userId);
        const frozenWallet = guard.walletPublicKey
          ? ownerWallets.find((wallet) => wallet.publicKey === guard.walletPublicKey)
          : ownerWallets[Number(guard.walletIndex || 1) - 1];
        if (!frozenWallet) throw new Error("The ordered wallet was removed; no trade was sent.");
        const currentWalletIndex = ownerWallets.indexOf(frozenWallet) + 1;
        guard.status = "submitting";
        guard.submittingAt = new Date().toISOString();
        guard.trigger = hitLimit ? kind : (hitTp ? "take-profit" : "stop-loss");
        guard.triggerPriceUsd = price;
        guard.updatedAt = guard.submittingAt;
        const claimed = await mutateRhGuards((liveStore) => {
          const live = liveStore.guards.find((row) => row.id === guard.id && row.status === "active");
          if (!live) return false;
          Object.assign(live, {
            status: "submitting",
            submittingAt: guard.submittingAt,
            trigger: guard.trigger,
            triggerPriceUsd: price,
            updatedAt: guard.updatedAt
          });
          return true;
        });
        if (!claimed) continue;
        claimedForSubmission = true;
        if (kind === "exit") {
          logTpSlEvent("tp_sl_trade_triggered", {
            tradeId: guard.id,
            userId: guard.userId,
            symbol: guard.symbol || guard.tokenAddress,
            side: "LONG",
            entryPrice: guard.entryPriceUsd,
            currentPrice: price,
            stopLoss: guard.stopLossPct != null ? -Number(guard.stopLossPct) : null,
            takeProfit: guard.takeProfitPct,
            status: "submitting",
            reason: guard.trigger
          });
        }
        const tradeBody = {
          walletIndex: String(currentWalletIndex),
          walletPublicKey: frozenWallet.publicKey,
          side: kind === "limit-buy" ? "buy" : "sell",
          tokenAddress: guard.tokenAddress,
          tradeAttemptId: `rh-order-${guard.id}`,
          ...(kind === "limit-buy"
            ? { payCurrency: "SOL", amountSol: guard.amountSol }
            : { percent: guard.sellPercent })
        };
        const result = await runIdempotentMoneyOp(
          "web-rh-trade",
          guard.userId,
          tradeBody.tradeAttemptId,
          () => webRhTradeCore(guard.userId, tradeBody),
          {
            busyMessage: "This Robinhood exit is already submitting — SlimeWire won't send a duplicate.",
            ttlMs: 24 * 60 * 60_000,
            lockMs: 30 * 60_000
          }
        );
        guard.status = "triggered";
        guard.triggeredAt = new Date().toISOString();
        guard.txHashes = result.txHashes;
        guardUpdates.set(guard.id, { guard: { ...guard }, expectedStatus: "submitting" });
        summary.executed += 1;
        if (kind === "exit") {
          logTpSlEvent("tp_sl_trade_closed", {
            tradeId: guard.id,
            userId: guard.userId,
            symbol: guard.symbol || guard.tokenAddress,
            side: "LONG",
            entryPrice: guard.entryPriceUsd,
            currentPrice: price,
            stopLoss: guard.stopLossPct != null ? -Number(guard.stopLossPct) : null,
            takeProfit: guard.takeProfitPct,
            status: "triggered",
            reason: guard.trigger
          });
        }
        if (kind === "exit" && guard.closesPosition && guard.exitGroup) {
          const landedIds = [guard.id];
          for (const sibling of gs.guards) {
            if (sibling.id === guard.id || sibling.status !== "active") continue;
            if (sibling.userId !== guard.userId) continue;
            if (String(sibling.walletPublicKey || "") !== String(guard.walletPublicKey || "")) continue;
            if (String(sibling.tokenAddress || "").toLowerCase() !== String(guard.tokenAddress || "").toLowerCase()) continue;
            if (String(sibling.exitGroup || "") !== String(guard.exitGroup)) continue;
            sibling.status = "canceled";
            sibling.cancelReason = `position closed by ${guard.trigger || "exit"}`;
            sibling.updatedAt = guard.triggeredAt;
            guardUpdates.set(sibling.id, { guard: { ...sibling }, expectedStatus: "active" });
            landedIds.push(sibling.id);
          }
          // Persist a completed position and its sibling cancellations together.
          // If this write fails, the 24h idempotency receipt lets startup
          // reconciliation finish it without resubmitting the trade.
          try {
            await mutateRhGuards((liveStore) => {
              for (const id of landedIds) {
                const pending = guardUpdates.get(id);
                const live = liveStore.guards.find((row) => row.id === id);
                if (!pending || !live || String(live.status || "").toLowerCase() !== pending.expectedStatus) continue;
                Object.assign(live, pending.guard);
              }
            });
            landedIds.forEach((id) => guardUpdates.delete(id));
          } catch (persistError) {
            console.warn(`[rh-guards] landed exit persistence deferred: ${friendlyError(persistError)}`);
          }
        } else {
          try {
            await mutateRhGuards((liveStore) => {
              const pending = guardUpdates.get(guard.id);
              const live = liveStore.guards.find((row) => row.id === guard.id);
              if (pending && live && String(live.status || "").toLowerCase() === pending.expectedStatus) Object.assign(live, pending.guard);
            });
            guardUpdates.delete(guard.id);
          } catch (persistError) {
            console.warn(`[rh-guards] landed order persistence deferred: ${friendlyError(persistError)}`);
          }
        }
        await audit("web_rh_guard_fired", { userId: guard.userId, tokenAddress: guard.tokenAddress, kind, trigger: guard.trigger, movePct: movePct.toFixed(1), targetMarketCapUsd: guard.targetMarketCapUsd, tx: result.txHashes }).catch(() => {});
      } catch (error) {
        summary.failed += 1;
        guard.failCount = (guard.failCount || 0) + 1;
        guard.lastError = friendlyError(error).slice(0, 200);
        if (error?.tradeSubmissionAmbiguous) {
          guard.status = "outcome_unknown";
          guard.txHashes = Array.isArray(error.partialHashes) ? error.partialHashes : [];
          guard.lastError = `Submission outcome unknown; no automatic retry. ${guard.lastError}`;
        } else {
          guard.status = guard.failCount >= 3 ? "failed" : "active";   // e.g. bag already sold manually
        }
        guardUpdates.set(guard.id, {
          guard: { ...guard },
          expectedStatus: claimedForSubmission ? "submitting" : "active"
        });
        if (kind === "exit") {
          logTpSlEvent("tp_sl_trade_failed", {
            tradeId: guard.id,
            userId: guard.userId,
            symbol: guard.symbol || guard.tokenAddress,
            side: "LONG",
            entryPrice: guard.entryPriceUsd,
            currentPrice: price,
            stopLoss: guard.stopLossPct != null ? -Number(guard.stopLossPct) : null,
            takeProfit: guard.takeProfitPct,
            status: guard.status,
            reason: guard.lastError
          });
        }
      }
    }
    if (guardUpdates.size) await mutateRhGuards((liveStore) => {
      for (const { guard: update, expectedStatus } of guardUpdates.values()) {
        const live = liveStore.guards.find((row) => row.id === update.id);
        if (!live || String(live.status || "").toLowerCase() !== expectedStatus) continue;
        Object.assign(live, update);
      }
    });
    return summary;
  } catch (error) {
    console.warn(`[rh-guards] tick failed: ${friendlyError(error)}`);
    return { ...summary, error: friendlyError(error) };
  } finally {
    rhGuardTickBusy = false;
  }
}
if (parseBoolean(process.env.RH_GUARDS_ENABLED || "true")) {
  setTimeout(() => { void runWorkerTask("rhGuards", () => rhGuardTick(), { leaseMs: 30_000 }); }, 2_000);
  setInterval(() => { void runWorkerTask("rhGuards", () => rhGuardTick(), { leaseMs: 30_000 }); }, 30_000);
}

// Bundle buy: hit one RH coin from several wallets with randomized sizes + gaps (each wallet's derived
// EVM account pays for its own buy — fund them first).
async function webRhBundle(userId, body = {}) {
  return runIdempotentMoneyOp("web-rh-bundle", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    () => webRhBundleCore(userId, body),
    { busyMessage: "A Robinhood bundle is already in flight — give it a moment.", lockMs: 30 * 60_000, ttlMs: 24 * 60 * 60_000 });
}
async function webRhBundleCore(userId, body = {}) {
  const tokenAddress = String(body.tokenAddress || "").trim();
  const walletStore = await readWalletStore();
  const selectedWallets = webSelectedWallets(walletStore, userId, body.walletIndexes, "", { walletPublicKeys: body.walletPublicKeys });
  const indexes = selectedWallets.map((wallet) => Number(wallet.webIndex));
  const solFunded = body.minSol != null || body.maxSol != null || ["sol", "solana"].includes(String(body.payCurrency || body.payWith || "").toLowerCase());
  const minAmount = Number(solFunded ? body.minSol : body.minEth || 0);
  const maxAmount = Number(solFunded ? body.maxSol : body.maxEth || 0);
  const maxAllowed = solFunded ? 5 : 0.5;
  const unit = solFunded ? "SOL" : "ETH";
  if (!(minAmount > 0) || !(maxAmount >= minAmount) || maxAmount > maxAllowed) { const e = new Error(`Buy range must be 0 < min ≤ max ≤ ${maxAllowed} ${unit}.`); e.statusCode = 400; throw e; }
  const walletConfigs = solFunded ? rhLaunchBundleWalletConfigs(body, indexes) : [];
  const configByIndex = new Map(walletConfigs.map((row) => [Number(row.walletIndex), row]));
  const bundleAttemptId = firstString(body.tradeAttemptId, body.clientRequestId) || crypto.randomUUID();
  const buyOne = async (wallet) => {
    const idx = Number(wallet.webIndex);
    const walletConfig = configByIndex.get(idx) || null;
    const amount = walletConfig ? Number(walletConfig.amountSol).toFixed(6) : (minAmount + Math.random() * (maxAmount - minAmount)).toFixed(6);
    try {
      const strategy = walletConfig?.exitStrategy || null;
      const protectedBuy = Boolean(strategy
        && !pumpLaunchManualExit(strategy)
        && (Number(strategy.takeProfitPct) > 0 || Number(strategy.stopLossPct) > 0));
      const tradeBody = {
        walletIndex: String(idx),
        walletPublicKey: wallet.publicKey,
        side: "buy",
        tokenAddress,
        symbol: body.symbol || "",
        tradeAttemptId: `${bundleAttemptId}:wallet:${idx}`,
        ...(solFunded ? { payCurrency: "SOL", amountSol: amount } : { amountEth: amount }),
        ...(protectedBuy ? {
          autoExit: true,
          protectionRequired: true,
          takeProfitPct: Number(strategy.takeProfitPct) || 0,
          stopLossPct: Number(strategy.stopLossPct) || 0,
          sellPercent: 100
        } : {
          // Manual/no-exit bundle legs still pass through the guarded trade
          // wrapper, but must not inherit or manufacture an automatic exit.
          autoExit: false,
          protectionRequired: false,
          disableAutoExit: true,
          manualExit: Boolean(walletConfig && pumpLaunchManualExit(walletConfig.exitStrategy)),
          takeProfitPct: 0,
          stopLossPct: 0
        })
      };
      // Every bundle leg uses the wallet-scoped wrapper. That is where active
      // guard re-entry is rejected and where this stable attempt is tombstoned;
      // manual/no-exit is a strategy choice, never permission to bypass it.
      const r = await webRhTrade(userId, tradeBody);
      let exitStatus = protectedBuy ? (r.autoExitArmed ? "armed" : "needs_attention")
        : walletConfig && pumpLaunchManualExit(walletConfig.exitStrategy) ? "manual" : "none";
      const exitError = protectedBuy && !r.autoExitArmed ? friendlyError(r.autoExitError || "Protection needs review.").slice(0, 160) : "";
      return { walletIndex: idx, walletPublicKey: wallet.publicKey, ok: true, ...(solFunded ? { amountSol: amount } : { amountEth: amount }), out: r.outFormatted, tx: r.txHashes[r.txHashes.length - 1], exitStatus, ...(exitError ? { exitError } : {}) };
    } catch (error) {
      return { walletIndex: idx, walletPublicKey: wallet.publicKey, ok: false, ...(solFunded ? { amountSol: amount } : { amountEth: amount }), error: friendlyError(error).slice(0, 160) };
    }
  };
  let rows;
  if (body.launchWave) {
    rows = await runWithConcurrency(selectedWallets, Math.min(20, selectedWallets.length), buyOne);
  } else {
    rows = [];
    for (const wallet of selectedWallets) {
      rows.push(await buyOne(wallet));
      await new Promise((resolve) => setTimeout(resolve, 400 + Math.random() * 1_800)); // human-ish gaps
    }
  }
  let recordError = "";
  try {
    await audit("web_rh_bundle", { userId, tokenAddress, wallets: indexes.length, okCount: rows.filter((r) => r.ok).length });
  } catch (error) {
    recordError = `Audit: ${friendlyError(error)}`;
  }
  return { ok: true, rows, recordError, summary: `${rows.filter((r) => r.ok).length}/${rows.length} wallets bought.` };
}

async function webRhBundleSell(userId, body = {}) {
  return runIdempotentMoneyOp("web-rh-bundle-sell", userId, firstString(body.tradeAttemptId, body.clientRequestId), async () => {
    const tokenAddress = String(body.tokenAddress || "").trim();
    if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) { const error = new Error("Invalid token address."); error.statusCode = 400; throw error; }
    const walletStore = await readWalletStore();
    const wallets = webSelectedWallets(walletStore, userId, body.walletIndexes, body.walletGroup, { walletPublicKeys: body.walletPublicKeys });
    const percent = parsePercent(String(body.percent || "100"));
    const configs = webWalletTradeConfigMap(body, wallets, { percent: String(percent) });
    const bundleAttemptId = firstString(body.tradeAttemptId, body.clientRequestId) || crypto.randomUUID();
    const ambiguousErrors = [];
    const rows = await runWithConcurrency(wallets, CONFIG.bundleConcurrency, async (wallet) => {
      const walletIndex = Number(wallet.webIndex || wallets.indexOf(wallet) + 1);
      const walletPercent = configs.get(walletIndex)?.percent || percent;
      try {
        const result = await webRhTrade(userId, {
          walletIndex: String(walletIndex),
          walletPublicKey: wallet.publicKey,
          side: "sell",
          tokenAddress,
          percent: walletPercent,
          source: "web_bundle",
          tradeAttemptId: `${bundleAttemptId}:wallet:${walletIndex}`
        });
        return { walletIndex, walletPublicKey: wallet.publicKey, ok: true, percent: walletPercent, tx: result.txHashes?.at?.(-1) || "", out: result.outFormatted || "" };
      } catch (error) {
        const outcomeUnknown = Boolean(error?.tradeSubmissionAmbiguous);
        if (outcomeUnknown) ambiguousErrors.push(error);
        return {
          walletIndex,
          walletPublicKey: wallet.publicKey,
          ok: false,
          percent: walletPercent,
          outcomeUnknown,
          partialHashes: outcomeUnknown ? submittedUnknownHashes(error) : [],
          error: friendlyError(error).slice(0, 160)
        };
      }
    });
    await audit("web_rh_bundle_sell", { userId, tokenAddress, wallets: wallets.length, okCount: rows.filter((row) => row.ok).length }).catch(() => {});
    if (ambiguousErrors.length) {
      throw aggregateTradeSubmissionAmbiguous("Robinhood bundle sell outcome unknown", ambiguousErrors, rows);
    }
    return { ok: true, rows, summary: `${rows.filter((row) => row.ok).length}/${rows.length} wallets sold.` };
  }, { busyMessage: "This Robinhood bundle sell is already submitting.", lockMs: 30 * 60_000, ttlMs: 24 * 60 * 60_000 });
}

// Volume bot: rounds of buy -> sell-back per wallet on one RH coin, randomized sizes + gaps. Runs in
// the background (job map + status endpoint) exactly like the Solana auto round-trip.
const rhVolumeJobs = new Map(); // userId -> job
async function webRhVolumeStart(userId, body = {}) {
  const existing = rhVolumeJobs.get(userId);
  if (existing && ["funding", "running", "stopping"].includes(existing.status)) { const e = new Error("Your Robinhood volume bot is already running — stop it first."); e.statusCode = 409; throw e; }
  const tokenAddress = String(body.tokenAddress || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) { const e = new Error("Invalid token address."); e.statusCode = 400; throw e; }
  const indexes = (Array.isArray(body.walletIndexes) ? body.walletIndexes : []).map((v) => Number.parseInt(v, 10)).filter((n) => Number.isInteger(n) && n >= 1).slice(0, 10);
  if (!indexes.length) { const e = new Error("Pick at least one wallet."); e.statusCode = 400; throw e; }
  const rounds = Math.min(10, Math.max(1, Number.parseInt(body.rounds || "3", 10) || 3));
  const fundSolPerWallet = Number(firstString(body.fundSolPerWallet, body.fundSol, body.investmentSol, body.amountSol) || 0);
  const solFunded = ["sol", "solana"].includes(String(firstString(body.payCurrency, body.payWith) || "").toLowerCase()) || fundSolPerWallet > 0;
  const minEth = Number(body.minEth || 0), maxEth = Number(body.maxEth || 0);
  if (solFunded) {
    if (!(fundSolPerWallet >= 0.005) || fundSolPerWallet > 5) { const e = new Error("SOL per wallet must be between 0.005 and 5 SOL."); e.statusCode = 400; throw e; }
  } else if (!(minEth > 0) || !(maxEth >= minEth) || maxEth > 0.2) {
    const e = new Error("Trade size must be 0 < min ≤ max ≤ 0.2 ETH."); e.statusCode = 400; throw e;
  }
  const job = {
    id: crypto.randomUUID(), status: solFunded ? "funding" : "running", tokenAddress, rounds,
    walletIndexes: indexes, walletCount: indexes.length, payCurrency: solFunded ? "SOL" : "ETH",
    fundSolPerWallet: solFunded ? fundSolPerWallet : 0, funding: [], done: 0, trades: [], stop: false,
    startedAt: new Date().toISOString()
  };
  rhVolumeJobs.set(userId, job);
  job.mode = solFunded ? "churn" : "direct";
  rhVolumeJobs.set(userId, job);
  (async () => {
    const rpc = CONFIG.rhChainRpcUrl;
    const GAS_WEI = 250000000000000n;             // ~0.00025 ETH kept for gas / the sweep tx
    const CAP_WEI = 50000000000000000n;           // 0.05 ETH max per cycle
    const MIN_WEI = 3000000000000n;               // ~0.000003 ETH floor per cycle
    const wait = (min, max) => new Promise((resolve) => setTimeout(resolve, min + Math.random() * (max - min)));
    const rhLog = (msg) => { job.log = (job.log || []).slice(-40); job.log.push({ at: new Date().toISOString(), message: String(msg).slice(0, 160) }); };
    async function ephemeralIndexOf(publicKey) {
      const s = await readWalletStore();
      return walletsForOwner(s, userId).findIndex((w) => w.publicKey === publicKey) + 1;
    }
    try {
      if (!solFunded) {
        // Direct-ETH mode (user already holds ETH): fast per-wallet round trips on the selected wallets.
        for (let round = 0; round < rounds && !job.stop; round += 1) {
          for (const idx of indexes) {
            if (job.stop) break;
            const amountEth = (minEth + Math.random() * (maxEth - minEth)).toFixed(6);
            try {
              await webRhTrade(userId, {
                source: "rh_volume", walletIndex: String(idx), side: "buy", tokenAddress, amountEth,
                tradeAttemptId: `rh-volume:${job.id}:direct:${round}:wallet:${idx}:buy`
              });
              await wait(900, 2200);
              const sold = await webRhTrade(userId, {
                source: "rh_volume", walletIndex: String(idx), side: "sell", tokenAddress, percent: 100,
                tradeAttemptId: `rh-volume:${job.id}:direct:${round}:wallet:${idx}:sell`
              });
              job.trades.push({ walletIndex: idx, round: round + 1, ok: true, amountEth, backEth: sold.outFormatted });
            } catch (error) {
              job.trades.push({ walletIndex: idx, round: round + 1, ok: false, outcomeUnknown: Boolean(error?.tradeSubmissionAmbiguous), error: friendlyError(error).slice(0, 160) });
              if (error?.tradeSubmissionAmbiguous) {
                job.status = "needs_attention";
                job.stop = true;
                job.error = "A Robinhood volume trade has an unknown outcome. The job and all automatic sweeps are paused for receipt review.";
                job.outcomeUnknownHashes = submittedUnknownHashes(error).slice(0, 12);
              }
            }
            await wait(600, 1500);
          }
          job.done = round + 1;
        }
        if (!["failed", "stopped", "needs_attention"].includes(job.status)) job.status = job.stop ? "stopped" : "done";
      } else {
        // Fresh-wallet churn: bridge SOL -> ETH once into the source wallet, then keep spinning up a
        // NEW throwaway wallet for each buy/sell, leaving one dust token, sweeping the ETH back to the
        // funding wallet, and retiring the wallet -- until Stop or the source ETH runs low.
        const sourceIdx = indexes[0];
        rhLog(`Converting ${fundSolPerWallet} SOL to ETH in your funding wallet...`);
        try {
          const funding = await webRhFundWithSol(userId, { walletIndex: String(sourceIdx), amountSol: String(fundSolPerWallet), tradeAttemptId: `rh-volume-${job.id}-fund` });
          job.funding.push({ walletIndex: sourceIdx, ok: true, amountSol: fundSolPerWallet, quotedEth: funding?.quotedEth || "" });
        } catch (error) {
          job.status = "failed"; job.error = friendlyError(error).slice(0, 200);
          job.funding.push({ walletIndex: sourceIdx, ok: false, amountSol: fundSolPerWallet, error: job.error });
          rhLog(`Conversion failed: ${job.error}`);
        }
        if (job.status !== "failed") {
          const store0 = await readWalletStore();
          const sourceWallet = getWalletAt(store0, sourceIdx, userId);
          const sourceSecret = decryptWallet(sourceWallet).secretKey;
          const sourceEvm = evmAddressFromSolana(sourceSecret);
          job.status = "running";
          rhLog("Funding ready. Spinning up fresh wallets...");
          // Sweeps run in the BACKGROUND so the next buy fires without waiting a full confirmation, and
          // prunes are drained only at the TOP of a cycle (never while a trade is resolving a wallet index),
          // so background work can't shift indexes under an in-flight trade. Money-safety intact: a wallet is
          // only queued for pruning after its ETH actually swept back.
          const toPrune = [];
          let pendingSweeps = 0;
          while (!job.stop) {
            while (toPrune.length) await pruneVolumeWallet(toPrune.shift()).catch(() => {});
            let srcWei = 0n;
            try { srcWei = BigInt((await rhEthBalance(sourceEvm, rpc)).wei || "0"); } catch { srcWei = 0n; }
            const spendable = srcWei - GAS_WEI * 3n;
            if (spendable <= MIN_WEI) {
              if (pendingSweeps > 0) { await wait(300, 700); continue; }   // let in-flight sweeps top the source back up
              rhLog("Source ETH spent. Done."); job.status = "done"; break;
            }
            let sliceWei = (spendable * BigInt(12 + Math.floor(Math.random() * 18))) / 100n;   // 12-30%
            if (sliceWei > CAP_WEI) sliceWei = CAP_WEI;
            if (sliceWei < MIN_WEI) sliceWei = spendable > MIN_WEI ? MIN_WEI : spendable;
            const buyEth = (Number(sliceWei) / 1e18).toFixed(6);
            const fresh = await createEphemeralVolumeWallet(userId, "SlimeBot RH", sourceWallet.publicKey, job.id, tokenAddress, true).catch(() => null);
            if (!fresh) { rhLog("Could not create a wallet; retrying."); await wait(400, 900); continue; }
            const freshIdx = await ephemeralIndexOf(fresh.publicKey);
            const freshSecret = decryptWallet(fresh).secretKey;
            const freshEvm = evmAddressFromSolana(freshSecret);
            const cycleId = job.done + 1;
            let cycleOutcomeUnknown = false;
            try {
              await rhTransferEth(sourceSecret, freshEvm, sliceWei + GAS_WEI, rpc);
              if (job.stop) throw new Error("stopped");
              await webRhTrade(userId, {
                source: "rh_volume", walletIndex: String(freshIdx), walletPublicKey: fresh.publicKey, side: "buy", tokenAddress, amountEth: buyEth,
                tradeAttemptId: `rh-volume:${job.id}:cycle:${cycleId}:wallet:${fresh.publicKey}:buy`
              });
              rhLog(`${shortMint(fresh.publicKey)} bought ${buyEth} ETH.`);
              await wait(300, 800);
              if (!job.stop) {
                const sold = await webRhTrade(userId, {
                  source: "rh_volume", walletIndex: String(freshIdx), walletPublicKey: fresh.publicKey, side: "sell", tokenAddress, percent: 95,
                  tradeAttemptId: `rh-volume:${job.id}:cycle:${cycleId}:wallet:${fresh.publicKey}:sell`
                });
                job.trades.push({ walletIndex: freshIdx, ok: true, amountEth: buyEth, backEth: sold?.outFormatted });
                rhLog(`${shortMint(fresh.publicKey)} sold, one token kept.`);
              }
            } catch (error) {
              cycleOutcomeUnknown = Boolean(error?.tradeSubmissionAmbiguous);
              job.trades.push({ walletIndex: freshIdx, ok: false, outcomeUnknown: cycleOutcomeUnknown, error: friendlyError(error).slice(0, 160) });
              rhLog(`Cycle error ${shortMint(fresh.publicKey)}: ${friendlyError(error).slice(0, 80)}`);
            }
            if (cycleOutcomeUnknown) {
              job.status = "needs_attention";
              job.stop = true;
              job.error = "A Robinhood volume trade has an unknown outcome. This wallet was not swept or pruned; review its receipt and balance.";
              rhLog(`Paused ${shortMint(fresh.publicKey)} without sweeping or pruning because its trade outcome is unknown.`);
              break;
            }
            // Sweep this wallet's ETH back in the background; queue it for retirement once the sweep lands.
            pendingSweeps += 1;
            (async () => {
              let swept = false;
              try {
                const wei = BigInt((await rhEthBalance(freshEvm, rpc)).wei || "0");
                if (wei > GAS_WEI) { await rhTransferEth(freshSecret, sourceEvm, wei - GAS_WEI, rpc); rhLog(`Swept ETH from ${shortMint(fresh.publicKey)} back.`); }
                swept = true;
              } catch { swept = false; }
              if (swept) toPrune.push(fresh.publicKey);
              else rhLog(`Kept ${shortMint(fresh.publicKey)} (sweep pending) so funds stay recoverable.`);
              pendingSweeps -= 1;
            })();
            job.done += 1;
            await wait(150, 450);
          }
          // Drain any in-flight sweeps, then retire the wallets they cleared.
          for (let t = 0; pendingSweeps > 0 && t < 80; t += 1) await wait(300, 600);
          while (toPrune.length) await pruneVolumeWallet(toPrune.shift()).catch(() => {});
          if (["running", "stopping"].includes(job.status)) job.status = job.stop ? "stopped" : "done";
          // Auto cash-out: convert the funding wallet's leftover ETH back to SOL so the run ends in SOL,
          // not ETH. Best-effort -- if the bridge fails, the ETH simply stays in the wallet, recoverable.
          try {
            if (job.status === "needs_attention") throw new Error("cash-out paused until the unknown trade receipt is reviewed");
            await wait(300, 600);
            let leftWei = 0n;
            try { leftWei = BigInt((await rhEthBalance(sourceEvm, rpc)).wei || "0"); } catch { leftWei = 0n; }
            if (leftWei > GAS_WEI * 4n) {
              rhLog("Cashing leftover ETH back to SOL...");
              const cashed = await rhBridgeEthToSol({ solanaSecretKey: sourceSecret, solRecipient: sourceWallet.publicKey, amountEth: "all", rpcUrl: rpc });
              invalidateWalletReadCache(sourceWallet.publicKey);
              job.cashedOutSol = cashed?.outSol || "";
              rhLog(`Cashed out ${cashed?.sentEth || "?"} ETH back to ${cashed?.outSol || "?"} SOL.`);
            } else {
              rhLog("No meaningful ETH left to cash out.");
            }
          } catch (error) {
            rhLog(`Cash-out to SOL failed (ETH stays in your wallet, recoverable): ${friendlyError(error).slice(0, 80)}`);
          }
        }
      }
    } catch (error) {
      job.status = "failed";
      job.error = friendlyError(error).slice(0, 200);
    }
    await audit("web_rh_volume", { userId, tokenAddress, payCurrency: job.payCurrency, fundSolPerWallet: job.fundSolPerWallet, mode: job.mode, wallets: indexes.length, rounds: job.done, trades: job.trades.length, ok: job.trades.filter((t) => t.ok).length }).catch(() => {});
  })();
  return { ok: true, started: true, status: job.status, tokenAddress, payCurrency: job.payCurrency, fundSolPerWallet: job.fundSolPerWallet, rounds, wallets: indexes.length };
}
function webRhVolumeStatus(userId) {
  const job = rhVolumeJobs.get(userId);
  if (!job) return { ok: true, status: "idle" };
  return { ok: true, id: job.id, status: job.status, mode: job.mode || "direct", tokenAddress: job.tokenAddress, payCurrency: job.payCurrency, fundSolPerWallet: job.fundSolPerWallet, walletIndexes: job.walletIndexes, walletCount: job.walletCount, funding: job.funding.slice(-10), done: job.done, rounds: job.rounds, trades: job.trades.slice(-20), log: (job.log || []).slice(-10), cashedOutSol: job.cashedOutSol || "", error: job.error || "" };
}
function webRhVolumeStop(userId) {
  const job = rhVolumeJobs.get(userId);
  if (job && ["funding", "running"].includes(job.status)) { job.stop = true; job.status = "stopping"; }
  return { ok: true };
}

function webMarketOrderTarget(value) {
  const number = Number(String(value ?? "").replace(/[$,\s]/g, ""));
  return Number.isFinite(number) && number > 0 && number <= 1_000_000_000_000_000 ? Math.round(number) : 0;
}

async function webCreateMarketCapOrders(userId, body = {}) {
  const token = String(body.tokenMint || body.tokenAddress || body.token || "").trim();
  const isRobinhood = /^0x[0-9a-fA-F]{40}$/.test(token);
  const isSolana = !isRobinhood && solanaPublicKeyLike(token);
  if (!isRobinhood && !isSolana) { const error = new Error("Paste a valid Solana or Robinhood coin address."); error.statusCode = 400; throw error; }
  const requested = Array.isArray(body.orders) ? body.orders.slice(0, 6) : [];
  if (!requested.length) { const error = new Error("Add at least one market-cap order."); error.statusCode = 400; throw error; }
  // Validate the full batch before persisting its first leg. A typo in the
  // third ladder rung must not leave the first two armed unexpectedly.
  const normalizedRows = requested.map((item) => {
    const side = String(item?.side || "").toLowerCase();
    if (side !== "buy" && side !== "sell") { const error = new Error("Every order must be a buy or sell."); error.statusCode = 400; throw error; }
    const targetMarketCapUsd = webMarketOrderTarget(item.targetMarketCapUsd);
    if (!targetMarketCapUsd) { const error = new Error("Enter a valid target market cap for every order."); error.statusCode = 400; throw error; }
    const amountSol = Number(item.amountSol || 0);
    const sellPercent = Number(item.sellPercent || 0);
    const maxBuySol = isRobinhood ? 5 : LIMIT_MAX_SOL;
    if (side === "buy" && (!(amountSol >= 0.005) || amountSol > maxBuySol)) { const error = new Error(`Buy amounts must be between 0.005 and ${maxBuySol} SOL.`); error.statusCode = 400; throw error; }
    if (side === "sell" && (!Number.isFinite(sellPercent) || sellPercent < 1 || sellPercent > 100)) { const error = new Error("Sell percentages must be between 1 and 100."); error.statusCode = 400; throw error; }
    return { side, targetMarketCapUsd, amountSol, sellPercent, slippageBps: item.slippageBps };
  });
  const normalized = [...new Map(normalizedRows.map((item) => [
    `${item.side}:${item.targetMarketCapUsd}:${item.side === "buy" ? item.amountSol : item.sellPercent}`,
    item
  ])).values()];
  const store = await readWalletStore();
  const walletIndex = parseWebWalletIndex(body.walletIndex);
  const wallet = assertFrozenManagedWallet(
    getWebServerTradeWalletAt(store, walletIndex, userId, "market-cap order"),
    body.walletPublicKey,
    "market-cap order"
  );
  const automationPermission = await requireWebAutomationPermission(userId, "market-cap orders");
  const symbol = String(body.symbol || "").replace(/^\$+/, "").slice(0, 16);

  if (isRobinhood) {
    const probe = rhFeeEvmWallet(CONFIG.appSecret, CONFIG.rhChainRpcUrl).address;
    const [scanInfo, implied] = await Promise.all([
      gatherRhScan(token).catch(() => null),
      rhImpliedPriceUsd(token, probe).catch(() => null)
    ]);
    const entryPriceUsd = firstMeaningfulNumber(implied?.priceUsd, scanInfo?.priceUsd, body.entryPriceUsd) || 0;
    const currentMarketCapUsd = firstMeaningfulNumber(scanInfo?.mc, body.currentMarketCapUsd) || 0;
    const supply = firstMeaningfulNumber(scanInfo?.supply, currentMarketCapUsd > 0 && entryPriceUsd > 0 ? currentMarketCapUsd / entryPriceUsd : 0) || 0;
    if (!(entryPriceUsd > 0) || !(supply > 0)) { const error = new Error("Live Robinhood price and supply are not ready. Refresh and try again."); error.statusCode = 400; throw error; }
    const createdAt = new Date().toISOString();
    const guards = normalized.map((item) => {
      const targetPriceUsd = item.targetMarketCapUsd / supply;
      if (!(targetPriceUsd > 0)) { const error = new Error("Couldn't calculate an order target price."); error.statusCode = 400; throw error; }
      return {
        id: crypto.randomUUID(),
        userId,
        walletIndex,
        walletPublicKey: wallet.publicKey,
        tokenAddress: token,
        symbol,
        kind: item.side === "buy" ? "limit-buy" : "limit-sell",
        exitSlot: null,
        exitGroup: null,
        closesPosition: false,
        entryPriceUsd,
        takeProfitPct: null,
        stopLossPct: null,
        targetMarketCapUsd: item.targetMarketCapUsd,
        targetPriceUsd,
        triggerDirection: targetPriceUsd >= entryPriceUsd ? ">=" : "<=",
        amountSol: item.side === "buy" ? item.amountSol : null,
        sellPercent: item.side === "sell" ? item.sellPercent : 100,
        automationPermission,
        status: "active",
        failCount: 0,
        createdAt
      };
    });
    await mutateRhGuards((guardStore) => {
      const targets = new Set(guards.map((guard) => `${guard.kind}:${Number(guard.targetMarketCapUsd)}`));
      const submittingCollision = guardStore.guards.find((guard) => (
        guard.status === "submitting"
        && guard.userId === userId
        && String(guard.walletPublicKey || "") === wallet.publicKey
        && String(guard.tokenAddress || "").toLowerCase() === token.toLowerCase()
        && targets.has(`${String(guard.kind || "")}:${Number(guard.targetMarketCapUsd)}`)
      ));
      if (submittingCollision) {
        const error = new Error("A matching Robinhood order is already submitting. Wait for its receipt before changing it.");
        error.statusCode = 409;
        throw error;
      }
      guardStore.guards = guardStore.guards.filter((guard) => !(
        guard.status === "active"
        && guard.userId === userId
        && String(guard.walletPublicKey || "") === wallet.publicKey
        && String(guard.tokenAddress || "").toLowerCase() === token.toLowerCase()
        && targets.has(`${String(guard.kind || "")}:${Number(guard.targetMarketCapUsd)}`)
      ));
      const sameTokenCount = guardStore.guards.filter((guard) => (
        guard.status === "active"
        && guard.userId === userId
        && String(guard.walletPublicKey || "") === wallet.publicKey
        && String(guard.tokenAddress || "").toLowerCase() === token.toLowerCase()
      )).length;
      if (sameTokenCount + guards.length > 12) { const error = new Error("This coin would exceed 12 active orders. Cancel one before adding this batch."); error.statusCode = 400; throw error; }
      guardStore.guards.push(...guards);
      guardStore.guards = pruneRhGuardHistory(guardStore.guards);
    });
    await audit("web_rh_market_order_batch_arm", { userId, tokenAddress: token, walletIndex, orders: guards.length }).catch(() => {});
    return { ok: true, armed: guards.map((guard) => webMarketCapOrderRow("robinhood", guard)) };
  }

  const info = await alphaRadarFetchMc(token).catch(() => null);
  const currentMc = Number(info?.mc || body.currentMarketCapUsd || 0);
  if (!(currentMc > 0)) { const error = new Error("Live market cap is not ready for this coin. Refresh the chart and try again."); error.statusCode = 400; throw error; }
  const created = await addLimitOrdersBatch(userId, normalized.map((item) => ({
      side: item.side,
      mint: token,
      sym: symbol || info?.sym || "",
      refMc: currentMc,
      triggerMc: item.targetMarketCapUsd,
      dir: item.targetMarketCapUsd >= currentMc ? ">=" : "<=",
      amountSol: item.side === "buy" ? item.amountSol : undefined,
      pct: item.side === "sell" ? item.sellPercent : undefined,
      slippageBps: parseWebSlippage(item.slippageBps || body.slippageBps),
      source: "web",
      walletIndex,
      walletPublicKey: wallet.publicKey,
      automationPermission
    })));
  if (!created.ok) { const error = new Error(created.why || "Could not arm these orders."); error.statusCode = 400; throw error; }
  return { ok: true, armed: created.orders.map((order) => webMarketCapOrderRow("solana", order)) };
}

async function webMarketCapOrders(userId, token = "") {
  const clean = String(token || "").trim();
  const [solStore, rhStore] = await Promise.all([readLimitOrders(), readRhGuards()]);
  const solana = limitOrdersForUser(solStore, userId)
    .filter((order) => order.source === "web" && (!clean || order.mint === clean))
    .map((order) => webMarketCapOrderRow("solana", order));
  const robinhood = rhStore.guards
    .filter((guard) => guard.userId === userId && ["limit-buy", "limit-sell"].includes(String(guard.kind || "")) && (!clean || guard.tokenAddress.toLowerCase() === clean.toLowerCase()))
    .map((guard) => webMarketCapOrderRow("robinhood", guard));
  const sorted = [...solana, ...robinhood]
    .sort((left, right) => Date.parse(right.updatedAt || right.completedAt || right.createdAt || 0) - Date.parse(left.updatedAt || left.completedAt || left.createdAt || 0));
  const active = sorted.filter((order) => order.isActive || ["submitting", "outcome_unknown", "needs_attention"].includes(order.status));
  const history = sorted.filter((order) => !active.includes(order)).slice(0, Math.max(0, 100 - active.length));
  const orders = [...active, ...history];
  return {
    ok: true,
    orders,
    summary: {
      active: orders.filter((order) => order.isActive).length,
      completed: orders.filter((order) => !order.isActive).length,
      total: orders.length
    }
  };
}

function webMarketCapOrderRow(chain, row = {}) {
  const robinhood = chain === "robinhood";
  const side = robinhood
    ? (String(row.kind || "").toLowerCase() === "limit-sell" ? "sell" : "buy")
    : String(row.side || "").toLowerCase();
  const status = String(row.status || "unknown").toLowerCase();
  const token = String(robinhood ? row.tokenAddress || "" : row.mint || "");
  const walletIndex = Number.parseInt(row.walletIndex || 0, 10) || null;
  const createdAt = row.createdAt || "";
  const triggeredAt = row.firedAt || row.triggeredAt || row.lastTriggeredAt || "";
  const completedAt = row.filledAt || row.completedAt || row.cancelledAt || row.canceledAt || row.failedAt || "";
  return {
    ...row,
    chain,
    id: String(row.id || ""),
    side,
    status,
    isActive: automationOrderIsActivelyMonitored(chain, status),
    token,
    tokenMint: token,
    tokenAddress: token,
    shortToken: token ? shortMint(token) : "",
    symbol: String(row.sym || row.symbol || "").replace(/^\$+/, "").slice(0, 24),
    walletIndex,
    walletLabel: String(row.walletLabel || (walletIndex ? `Wallet ${walletIndex}` : "Wallet")),
    walletPublicKey: String(row.walletPublicKey || ""),
    targetMarketCapUsd: Number(robinhood ? row.targetMarketCapUsd : row.triggerMc) || 0,
    referenceMarketCapUsd: Number(robinhood ? row.currentMarketCapUsd : row.refMc) || 0,
    firedMarketCapUsd: Number(row.firedMc || row.triggeredMarketCapUsd) || 0,
    direction: String(robinhood ? row.triggerDirection || "" : row.dir || ""),
    amountSol: side === "buy" && Number.isFinite(Number(row.amountSol)) ? Number(row.amountSol) : null,
    sellPercent: side === "sell" && Number.isFinite(Number(row.sellPercent ?? row.pct)) ? Number(row.sellPercent ?? row.pct) : null,
    signature: String(row.signature || row.txHash || row.sellSignature || (Array.isArray(row.txHashes) ? row.txHashes[row.txHashes.length - 1] : "") || ""),
    error: String(row.failReason || row.lastError || row.error || ""),
    createdAt,
    triggeredAt,
    completedAt,
    expiresAt: row.expiresAt || ""
  };
}

async function webCancelMarketCapOrder(userId, body = {}) {
  const chain = String(body.chain || "solana").toLowerCase();
  if (chain === "robinhood") return webRhCancelGuard(userId, body);
  const cancelled = await cancelLimitOrder(userId, String(body.id || ""));
  if (!cancelled) { const error = new Error("Order was already completed or removed."); error.statusCode = 404; throw error; }
  return { ok: true };
}

// SOL -> ETH on Robinhood Chain via Relay (live-verified route): one Solana tx signed by the user's
// wallet; Relay's solver delivers ETH to the wallet's derived EVM address. This is how a Solana-native
// user funds launch gas without leaving the site.
async function webRhFundWithSol(userId, body = {}) {
  return runIdempotentMoneyOp("web-rh-fund", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    () => webRhFundWithSolCore(userId, body),
    { busyMessage: "A funding swap is already in flight for this wallet — give it a moment." });
}
async function webRhFundWithSolCore(userId, body = {}) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId),
    body.walletPublicKey,
    "Robinhood funding swap"
  );
  const keypair = decryptWallet(wallet);
  const amountSol = Number(body.amountSol || 0);
  if (!Number.isFinite(amountSol) || amountSol < 0.005 || amountSol > 5) {
    const e = new Error("Enter an amount between 0.005 and 5 SOL.");
    e.statusCode = 400; throw e;
  }
  const evmAddress = evmAddressFromSolana(keypair.secretKey);
  const lamports = Math.round(amountSol * LAMPORTS_PER_SOL);
  // Fail BEFORE quoting/signing if the wallet can't cover swap + fees — clearest possible error.
  const solBal = Number(await getSolBalanceCached(keypair.publicKey, { force: true, priority: true }).catch(() => 0));
  if (solBal < lamports + 2_500_000) {
    const e = new Error(`This wallet has ${lamportsToSol(solBal)} SOL — not enough to swap ${amountSol} SOL (needs ~0.0025 extra for fees). Lower the amount or top up.`);
    e.statusCode = 400; throw e;
  }
  const quote = await relayQuoteSolToRhEth({ solanaAddress: keypair.publicKey.toBase58(), evmRecipient: evmAddress, lamports });

  // Build the v0 tx from Relay's instructions + lookup tables, sign with the user's wallet, send.
  // (Instruction data arrives as plain hex; strip a 0x prefix defensively — Buffer.from silently
  // truncates on invalid chars, which would corrupt the tx.)
  const instructions = quote.instructions.map((ins) => new TransactionInstruction({
    programId: new PublicKey(ins.programId),
    keys: (ins.keys || []).map((k) => ({ pubkey: new PublicKey(k.pubkey), isSigner: Boolean(k.isSigner), isWritable: Boolean(k.isWritable) })),
    data: Buffer.from(String(ins.data || "").replace(/^0x/i, ""), "hex")
  }));
  const lookups = [];
  for (const alt of quote.lookupTables) {
    const table = await rpcWithRetry("get relay lookup table", () => connection.getAddressLookupTable(new PublicKey(alt)));
    if (table?.value) lookups.push(table.value);
  }
  const { blockhash } = await rpcWithRetry("get relay blockhash", () => connection.getLatestBlockhash("confirmed"));
  const message = new TransactionMessage({ payerKey: keypair.publicKey, recentBlockhash: blockhash, instructions }).compileToV0Message(lookups);
  const tx = new VersionedTransaction(message);
  tx.sign([keypair]);
  const signature = await sendVersionedTransaction(tx, "relay SOL -> Robinhood ETH", { priority: true });
  invalidateWalletReadCache(wallet.publicKey);

  // Standalone funding can wait for a friendly completion receipt. A SOL-funded
  // trade skips this loop and performs one authoritative destination-balance
  // wait in webRhTradeCore instead of waiting for the same bridge twice.
  let relayStatus = "pending";
  if (body.waitForDelivery !== false) {
    for (let i = 0; i < 6; i += 1) {
      await new Promise((resolve) => setTimeout(resolve, 2_000));
      const st = await relayCheckStatus(quote.checkEndpoint).catch(() => null);
      if (st && typeof st.status === "string") relayStatus = st.status;
      if (relayStatus === "success") break;
      if (relayStatus === "failure" || relayStatus === "refund") break;
    }
  }
  const bal = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0" }));
  await audit("web_rh_fund_sol", { userId, wallet: wallet.publicKey, evmAddress, amountSol, signature, requestId: quote.requestId, relayStatus, outEthQuoted: quote.outEth, ethBalance: bal.eth });
  return { ok: true, signature, relayStatus, requestId: quote.requestId, evmAddress, quotedEth: quote.outEth, ethBalance: bal.eth, impactPercent: quote.impactPercent };
}

// Reverse of fund-with-sol: cash the wallet's Robinhood ETH back out to its OWN Solana address (native
// ETH -> native SOL via the same Relay rail the fee sweep uses). User-triggered only; leaves a gas reserve.
async function webRhBridgeToSol(userId, body = {}) {
  try {
    return await runIdempotentMoneyOp("web-rh-bridge-sol", userId, firstString(body.tradeAttemptId, body.clientRequestId),
      () => webRhBridgeToSolCore(userId, body),
      { busyMessage: "A cash-out is already in flight for this wallet — give it a moment." });
  } catch (error) {
    console.warn(`[rh-cashout] failed user=${manualSellUserHash(userId)} wallet=${parseWebWalletIndex(body.walletIndex)}: ${friendlyError(error).slice(0, 300)}`);
    throw error;
  }
}
async function webRhBridgeToSolCore(userId, body = {}) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId),
    body.walletPublicKey,
    "Robinhood cashout"
  );
  const keypair = decryptWallet(wallet);
  const evmAddress = evmAddressFromSolana(keypair.secretKey);
  const solRecipient = keypair.publicKey.toBase58();
  // "all" (or blank) sweeps the whole ETH balance minus a gas reserve; a number cashes out that much ETH.
  const rawAmount = firstString(body.amountEth, body.amount);
  const wantAll = !rawAmount || String(rawAmount).trim().toLowerCase() === "all";
  const amountEth = wantAll ? "all" : Number(rawAmount);
  if (!wantAll && (!Number.isFinite(amountEth) || amountEth <= 0)) {
    const e = new Error("Enter an ETH amount above 0, or use Cash out all."); e.statusCode = 400; throw e;
  }
  const beforeUsdcLookup = await getOwnedTokenAccountsWithWarningsCached(keypair.publicKey, { force: true }).catch(() => ({ accounts: [] }));
  const beforeUsdcRaw = aggregateTokenAccountsForMint(beforeUsdcLookup.accounts || [], SOLANA_USDC_MINT)?.rawAmount || 0n;
  const result = await rhBridgeEthToSol({
    solanaSecretKey: keypair.secretKey,
    solRecipient,
    amountEth,
    rpcUrl: CONFIG.rhChainRpcUrl
  });
  let relayStatus = "pending";
  let usdcReceivedRaw = 0n;
  let usdcSwapSignature = "";
  let usdcSwapError = "";
  let outSol = result.outSol || "";
  if (result.settlementAsset === "USDC") {
    // The bridge deposit is already submitted. Observe only that exact destination delta;
    // never create another bridge while the first outcome remains pending.
    for (let attempt = 0; attempt < 20; attempt += 1) {
      if (attempt > 0) await sleep(3_000);
      const status = await relayCheckStatus(result.checkEndpoint).catch(() => null);
      if (status && typeof status.status === "string") relayStatus = status.status;
      const lookup = await getOwnedTokenAccountsWithWarningsCached(keypair.publicKey, { force: true }).catch(() => ({ accounts: [] }));
      const currentRaw = aggregateTokenAccountsForMint(lookup.accounts || [], SOLANA_USDC_MINT)?.rawAmount || 0n;
      if (currentRaw > beforeUsdcRaw) {
        usdcReceivedRaw = currentRaw - beforeUsdcRaw;
        break;
      }
      if (["failure", "refund"].includes(String(relayStatus).toLowerCase())) {
        const error = new Error("The Robinhood bridge did not settle. Its ETH was refunded to the same Robinhood wallet; refresh Positions and try again.");
        error.statusCode = 502;
        throw error;
      }
    }
    if (usdcReceivedRaw > 0n) {
      const solBalance = Number(await getSolBalanceCached(keypair.publicKey, { force: true }).catch(() => 0));
      if (solBalance < 1_000_000) await topUpSellFees(store, userId, wallet, 5_000_000).catch(() => false);
      try {
        const swap = await executeJupiterSwap({
          signer: keypair,
          inputMint: SOLANA_USDC_MINT,
          outputMint: SOL_MINT,
          amount: usdcReceivedRaw.toString(),
          slippageBps: 150,
          priority: true
        });
        usdcSwapSignature = swap.signature;
        outSol = lamportsToSol(Number(BigInt(swap.outputAmount || 0)));
      } catch (error) {
        // The cross-chain recovery already landed as USDC. Never resubmit that bridge because a
        // destination swap was unavailable or outcome-unknown; the balance remains visible and
        // convertible from SlimeCash instead of becoming hidden or risking a duplicate move.
        usdcSwapError = friendlyError(error).slice(0, 240);
        console.warn(`[rh-cashout] USDC arrived but SOL conversion needs attention user=${manualSellUserHash(userId)} wallet=${parseWebWalletIndex(body.walletIndex)}: ${usdcSwapError}`);
      }
    }
  }
  invalidateWalletReadCache(wallet.publicKey);
  const bal = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0" }));
  const settlementPending = result.settlementAsset === "USDC" && !usdcSwapSignature;
  await audit("web_rh_bridge_sol", { userId, wallet: wallet.publicKey, evmAddress, solRecipient, sentEth: result.sentEth, outSol, outUsdc: result.outUsdc || "", settlementAsset: result.settlementAsset || "SOL", settlementPending, relayStatus, usdcReceivedRaw: usdcReceivedRaw.toString(), usdcSwapSignature, usdcSwapError, hashes: result.hashes, ethBalance: bal.eth });
  return { ok: true, sentEth: result.sentEth, outSol, outUsdc: result.outUsdc || "", settlementAsset: result.settlementAsset || "SOL", settlementPending, relayStatus, usdcReceivedRaw: usdcReceivedRaw.toString(), usdcSwapSignature, usdcSwapError, hashes: result.hashes, requestId: result.requestId, evmAddress, solRecipient, ethBalance: bal.eth, impactPercent: result.impactPercent };
}

async function webLaunchRhCoin(userId, body = {}) {
  const walletIndex = parseWebWalletIndex(body.devWalletIndex || body.walletIndex);
  const lockName = `web-rh-launch-wallet:${manualSellUserHash(userId)}:${walletIndex}`;
  return LockService.withLock(lockName, 360_000, async () => {
    try {
      return await runIdempotentMoneyOp(
        "web-rh-launch",
        userId,
        firstString(body.launchAttemptId, body.tradeAttemptId, body.clientRequestId),
        () => webLaunchRhCoinCore(userId, body),
        { busyMessage: "This Robinhood launch is still confirming. Do not submit it again.", lockMs: 360_000, ttlMs: 24 * 60 * 60_000 }
      );
    } catch (error) {
      console.warn(`[rh-launch] failed user=${manualSellUserHash(userId)} wallet=${walletIndex} attempt=${firstString(body.launchAttemptId, body.tradeAttemptId, "none").slice(0, 36)}: ${friendlyError(error).slice(0, 300)}`);
      throw error;
    }
  }, () => {
    const error = new Error("This wallet already has a Robinhood launch confirming. Wait for that result before starting another coin.");
    error.statusCode = 409;
    error.duplicate = true;
    throw error;
  });
}

async function webLaunchRhCoinCore(userId, body = {}) {
  const store = await readWalletStore();
  const walletIndex = parseWebWalletIndex(body.devWalletIndex || body.walletIndex);
  const wallet = getWalletAt(store, walletIndex, userId);
  const keypair = decryptWallet(wallet);
  const attemptId = firstString(body.launchAttemptId, body.tradeAttemptId) || crypto.randomUUID();
  const evmAddress = evmAddressFromSolana(keypair.secretKey);
  const automaticMarket = rhSushiLaunchConfigured(CONFIG.rhSushiLaunchFactoryAddress);
  let launchFunding = null;
  // Robinhood Chain needs native gas internally, but launchers only manage SOL. The server bridges the
  // small required amount automatically when the derived Robinhood wallet is short.
  const fundWithSol = true;
  if (fundWithSol) {
    const amountSol = Number(firstString(body.fundSolAmount, body.rhFundSolAmount, body.amountSol) || (automaticMarket ? "0.03" : "0.01"));
    if (!Number.isFinite(amountSol) || amountSol < 0.005 || amountSol > 5) {
      const e = new Error("Enter a SOL funding amount between 0.005 and 5.");
      e.statusCode = 400; throw e;
    }
    const beforeEth = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0" }));
    const requiredEthFloor = automaticMarket ? 0.0015 : 0.00008;
    if (Number(beforeEth.eth || 0) < requiredEthFloor) {
      const funding = await webRhFundWithSol(userId, {
        walletIndex,
        amountSol,
        tradeAttemptId: `${attemptId}-rh-launch-fund`
      });
      const quotedEth = Number(funding?.quotedEth || 0);
      // Wait for most of the quoted bridge output, not a fixed balance that can
      // exceed the quote and force a pointless 90-second timeout. The atomic
      // launch performs its own exact fee + gas estimate before submission.
      const targetEth = Number(beforeEth.eth || 0) + Math.max(0.00008, quotedEth * 0.72);
      const afterEth = await waitForRhEthBalanceAtLeast(evmAddress, targetEth, 90_000);
      launchFunding = {
        amountSol,
        quotedEth: funding?.quotedEth || "",
        relayStatus: funding?.relayStatus || "",
        requestId: funding?.requestId || "",
        signature: funding?.signature || "",
        ethBalance: afterEth.eth || "0"
      };
    } else {
      launchFunding = { skipped: true, reason: "wallet already had deploy ETH", ethBalance: beforeEth.eth || "0" };
    }
  }
  const metadataUri = `https://slimewire.org/api/web/rh/launch-metadata/${encodeURIComponent(attemptId)}`;
  const result = automaticMarket
    ? await rhLaunchTokenOnSushi({
      solanaSecretKey: keypair.secretKey,
      factoryAddress: CONFIG.rhSushiLaunchFactoryAddress,
      name: body.name,
      symbol: body.symbol,
      supplyTokens: body.supplyTokens || 1_000_000_000,
      contractUri: metadataUri,
      initialMarketCapUsd: Number(body.initialMarketCapUsd || CONFIG.rhSushiDefaultMarketCapUsd),
      ethUsd: await rhEthUsd(),
      rpcUrl: CONFIG.rhChainRpcUrl
    })
    : await rhDeployToken({
      solanaSecretKey: keypair.secretKey,
      name: body.name,
      symbol: body.symbol,
      supplyTokens: body.supplyTokens || 1_000_000_000,
      rpcUrl: CONFIG.rhChainRpcUrl
    });
  // Metadata registry: EVM tokens have no native image/socials, so we store what the launch form
  // collected keyed by token address — the RH feed + coin rows read it back (like wallets/DEXes keep
  // their own address->logo registries on other chains).
  const hasImage = await saveRhTokenImage(result.tokenAddress, body.imageDataUrl).catch(() => false);
  // Creator fees (pump-style, venue-side): the creator earns rhCreatorFeeBps of every trade of this coin
  // THROUGH SLIMEWIRE, paid in ETH to the dev wallet's EVM address. Stored on the coin,
  // NOT baked into the token — so the coin stays ✅ Verified. Recipient = deployer (the dev wallet).
  const holderRewards = launchHolderRewardsFromBody(body);
  const creatorFeeEnabled = true;
  await upsertPumpLaunchAttempt({
    id: attemptId,
    userId,
    rail: "robinhood",
    status: "confirmed",
    mintPublicKey: result.tokenAddress,
    tokenName: String(body.name || "").trim(),
    symbol: String(body.symbol || "").trim(),
    description: String(body.description || "").trim().slice(0, 800),
    website: String(body.website || "").trim().slice(0, 200),
    x: String(body.x || "").trim().slice(0, 200),
    telegram: String(body.telegram || "").trim().slice(0, 200),
    rhImageFile: hasImage,
    devWalletPublicKey: wallet.publicKey,
    rhDeployer: result.deployer,
    rhCreatorFeeBps: creatorFeeEnabled ? CONFIG.rhCreatorFeeBps : 0,
    rhCreatorFeeRecipient: creatorFeeEnabled ? result.deployer : "",
    metadataUri,
    rhVenue: result.venue || "uniswap-v3-legacy",
    rhPool: result.pool || "",
    rhSupplyTokens: result.supplyTokens || String(body.supplyTokens || 1_000_000_000),
    rhTokenId: result.tokenId || "",
    rhLiquidityLocker: result.locker || "",
    rhLiquidityLocked: Boolean(result.liquidityLocked),
    rhAutomaticMarket: automaticMarket,
    holderRewards,
    rhHolderRewards: holderRewards,
    txSignature: result.txHash,
    createdAt: new Date().toISOString()
  });
  // The pool is confirmed and the durable launch record exists. Fire armed Robinhood rooms now,
  // before an optional creator buy, so community entries do not wait behind another bridge/swap.
  maybeRhCommunitySnipe({
    tokenAddress: result.tokenAddress,
    deployer: result.deployer,
    symbol: String(body.symbol || "").trim(),
    name: String(body.name || "").trim(),
    block: result.blockNumber || 0
  }, { source: "slimewire-launch" });
  let ownerBundleArmed = false;
  const ownerBundle = body.autoBundle && typeof body.autoBundle === "object" ? body.autoBundle : null;
  if (automaticMarket && ownerBundle && Array.isArray(ownerBundle.walletIndexes) && ownerBundle.walletIndexes.length) {
    try {
      await webRhArmAutoBundle(userId, {
        tokenAddress: result.tokenAddress,
        symbol: String(body.symbol || "").trim(),
        walletIndexes: ownerBundle.walletIndexes,
        walletConfigs: ownerBundle.walletConfigs,
        payCurrency: "SOL",
        minSol: ownerBundle.minSol,
        maxSol: ownerBundle.maxSol,
        launchWave: true
      });
      ownerBundleArmed = true;
      // The pool is already confirmed, so ask the single-flight guard worker to
      // fire now. If it is already running, the durable arm waits for its next
      // pass instead of racing a second bundle submission.
      void rhGuardTick().catch((error) => console.warn(`[rh-launch-bundle] ${friendlyError(error)}`));
    } catch (error) {
      await audit("web_rh_launch_bundle_arm_failed", { userId, tokenAddress: result.tokenAddress, error: friendlyError(error) }).catch(() => {});
    }
  }
  // External opt-in wallets must enter as soon as the RH pool exists. Start
  // their SOL->RH->coin paths before the optional dev buy finishes so one
  // bridge cannot hold the whole launch wave behind it.
  const participantInviteIds = Array.isArray(body.participantInviteIds) ? body.participantInviteIds : [];
  const participantEntriesPromise = participantInviteIds.length
    ? fulfillRhLaunchBundleInvites(userId, attemptId, result.tokenAddress).catch((error) => ({
      requested: participantInviteIds.length,
      completed: 0,
      failed: participantInviteIds.length,
      error: friendlyError(error)
    }))
    : Promise.resolve(null);
  let devBuy = null;
  const devBuySol = Number(firstString(body.devBuySol, body.initialBuySol) || 0);
  if (automaticMarket && Number.isFinite(devBuySol) && devBuySol > 0) {
    try {
      devBuy = await webRhTradeCore(userId, {
        walletIndex,
        walletPublicKey: wallet.publicKey,
        side: "buy",
        tokenAddress: result.tokenAddress,
        payCurrency: "SOL",
        amountSol: devBuySol,
        tradeAttemptId: `${attemptId}-rh-dev-buy`
      });
      const devExitStrategy = pumpLaunchExitStrategy(body.devExitStrategy || {});
      if (pumpLaunchManualExit(devExitStrategy)) devBuy.exitStatus = "manual";
      else if (Number(devExitStrategy.takeProfitPct) > 0 || Number(devExitStrategy.stopLossPct) > 0) {
        try {
          await webRhArmGuard(userId, { walletIndex, walletPublicKey: wallet.publicKey, tokenAddress: result.tokenAddress, symbol: String(body.symbol || "").trim(), takeProfitPct: Number(devExitStrategy.takeProfitPct) || 0, stopLossPct: Number(devExitStrategy.stopLossPct) || 0, sellPercent: 100 });
          devBuy.exitStatus = "armed";
        } catch (error) { devBuy.exitStatus = "needs_attention"; devBuy.exitError = friendlyError(error).slice(0, 160); }
      }
    } catch (error) {
      devBuy = { ok: false, error: friendlyError(error).slice(0, 240) };
    }
  }
  const participantEntries = await participantEntriesPromise;
  await audit("web_rh_launch", { userId, wallet: wallet.publicKey, token: result.tokenAddress, pool: result.pool || "", venue: result.venue || "legacy", automaticMarket, liquidityLocked: Boolean(result.liquidityLocked), tx: result.txHash, supply: result.supplyTokens, gasEth: result.gasCostEth, creatorFeeBps: creatorFeeEnabled ? CONFIG.rhCreatorFeeBps : 0, holderRewards, launchFunding, devBuyOk: devBuy ? devBuy.ok !== false : null });
  void instantRhWalletLaunchSnipe({
    tokenAddress: result.tokenAddress,
    deployer: result.deployer,
    symbol: String(body.symbol || "").trim(),
    name: String(body.name || "").trim(),
    block: result.blockNumber || 0
  }).catch((error) => console.warn(`[wallet-launch-snipe:rh] instant fire failed: ${friendlyError(error)}`));
  return { ok: true, ...result, chainId: RH_CHAIN_ID, explorerToken: rhExplorerToken(result.tokenAddress), creatorFeeBps: creatorFeeEnabled ? CONFIG.rhCreatorFeeBps : 0, holderRewards, launchFunding, automaticMarket, devBuy, participantEntries, ownerBundleArmed };
}

// Make a launched coin BUYABLE: create + seed its Uniswap V3 pool with the creator's ETH + tokens. This
// is the "add liquidity" step — until a pool exists there's nothing to buy against. Idempotency-guarded;
// the user's derived RH wallet signs (same model as launch/buy). Every tx is gas-estimated first.
async function webRhCreatePool(userId, body = {}) {
  return runIdempotentMoneyOp("web-rh-create-pool", userId, firstString(body.poolAttemptId, body.clientRequestId),
    async () => {
      const store = await readWalletStore();
      const wallet = getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId);
      const keypair = decryptWallet(wallet);
      const evmAddress = evmAddressFromSolana(keypair.secretKey);
      let ethAmount = body.ethAmount;
      let solFunding = null;
      const solFunded = body.amountSol != null || ["sol", "solana"].includes(String(body.payCurrency || body.payWith || "").toLowerCase());
      if (solFunded) {
        const amountSol = Number(body.amountSol || 0);
        if (!Number.isFinite(amountSol) || amountSol < 0.005 || amountSol > 5) {
          const e = new Error("Enter a SOL liquidity amount between 0.005 and 5.");
          e.statusCode = 400; throw e;
        }
        const beforeEth = await rhEthBalance(evmAddress, CONFIG.rhChainRpcUrl).catch(() => ({ eth: "0" }));
        const funding = await webRhFundWithSol(userId, {
          walletIndex: body.walletIndex,
          walletPublicKey: wallet.publicKey,
          amountSol,
          tradeAttemptId: `${firstString(body.poolAttemptId, body.clientRequestId) || crypto.randomUUID()}-rh-pool-fund`
        });
        const quotedEth = Number(funding?.quotedEth || 0);
        const targetEth = Number(beforeEth.eth || 0) + Math.max(0.00001, quotedEth * 0.86);
        const afterEth = await waitForRhEthBalanceAtLeast(evmAddress, targetEth, 45_000);
        const spendPlan = await rhBuySpendPlan({
          availableWei: afterEth.wei || "0",
          quotedEth: funding?.quotedEth || "0",
          userReserveEth: body.rhGasReserveEth,
          gasUnits: 1_500_000n,
          rpcUrl: CONFIG.rhChainRpcUrl
        });
        ethAmount = Number(spendPlan.spendEth || 0);
        solFunding = { amountSol, quotedEth: funding?.quotedEth || "", relayStatus: funding?.relayStatus || "", requestId: funding?.requestId || "", gasReserveEth: spendPlan.gasReserveEth };
        if (!(Number(ethAmount) >= 0.00001)) {
          const e = new Error("SOL was converted, but the Robinhood network funds are not ready yet. Wait a few seconds and try again.");
          e.statusCode = 425; throw e;
        }
      }
      const res = await rhCreatePoolAndSeed({
        solanaSecretKey: keypair.secretKey,
        tokenAddress: String(body.tokenAddress || ""),
        ethAmount,
        tokenAmount: body.tokenAmount,
        rpcUrl: CONFIG.rhChainRpcUrl,
      });
      await audit("web_rh_create_pool", { userId, wallet: wallet.publicKey, token: res.tokenAddress, pool: res.pool, tx: res.txHash, ethSeeded: res.ethSeeded, tokenSeeded: res.tokenSeeded });
      return { ...res, chainId: RH_CHAIN_ID, solFunding };
    },
    { busyMessage: "A pool seed for this coin is already in flight — give it a moment." });
}

// ---------------------------------------------------------------------------
// Growth funnel: per-user milestones (wallet_created -> funded -> first_trade ->
// second_trade). Emitted from hooks we already run, so no extra RPC/balance polling.
// ---------------------------------------------------------------------------
function funnelPath() { return path.join(CONFIG.dataDir, "funnel-events.json"); }
async function readFunnel() {
  try {
    const store = JSON.parse(await fs.readFile(funnelPath(), "utf8"));
    if (!store.users || typeof store.users !== "object") store.users = {};
    return store;
  } catch { return { users: {} }; }
}
async function recordFunnelMilestone(userId, patch = {}) {
  const key = String(userId || "");
  if (!key) return;
  try {
    await withFileLock(funnelPath(), async () => {
      const store = await readFunnel();
      const row = store.users[key] || {};
      let changed = false;
      for (const [field, value] of Object.entries(patch)) {
        if (field === "trade") continue;
        if (!row[field] && value) { row[field] = value; changed = true; }
      }
      if (patch.trade) {
        row.tradeCount = Number(row.tradeCount || 0) + 1;
        const now = new Date().toISOString();
        if (!row.firstTradeAt) row.firstTradeAt = now;
        else if (!row.secondTradeAt) row.secondTradeAt = now;
        if (!row.fundedAt) row.fundedAt = now;   // a trade proves the wallet was funded
        changed = true;
      }
      if (changed) {
        row.updatedAt = new Date().toISOString();
        store.users[key] = row;
        await writeJsonFile(funnelPath(), store);
      }
    });
  } catch { /* funnel telemetry must never break a trade or funding path */ }
}
function recordFunnelTrade(userId) { return recordFunnelMilestone(userId, { trade: true }); }

const SOL_EXIT_RECEIPT_RECORDED_MAX = 2_000;
// A sell fee intent is written before any fee transaction may sign. If the
// process disappears in that narrow pre-sign window, there is no signature to
// reconcile. Keep a generous lease so a merely slow live request is never
// mistaken for a crash; after it expires, recovery may retire only legs that
// are still explicitly pending and have never recorded signed bytes.
const MANUAL_SOL_SELL_UNSIGNED_FEE_STALE_MS = 15 * 60_000;
// Activity persistence is not proof that the HTTP/TG result reached the
// client. During this durable replay window, a different attempt for the same
// wallet/mint receives the prior confirmed receipt instead of submitting a
// second partial sell. This intentionally trades a short delay between
// deliberate partial sells for response-loss safety.
const MANUAL_SELL_CROSS_ATTEMPT_REPLAY_MS = 15 * 60_000;
let solExitHistoryBackfillActive = false;

async function readSolExitReceipts() {
  const store = await readJson(solExitReceiptsPath());
  store.receipts = objectRows(store.receipts);
  store.manualSubmissions = objectRows(store.manualSubmissions);
  store.manualFeeIntents = objectRows(store.manualFeeIntents);
  return store;
}

function standaloneManualSellSubmissionKey(row = {}) {
  return [
    String(row.userId || "").trim(),
    normalizeManualSellAttemptId(row.manualSellAttemptId || row.attemptId),
    String(row.walletPublicKey || "").trim(),
    String(row.tokenMint || "").trim()
  ].join(":");
}

function standaloneManualSellSubmissionError(row = {}, message = "The prior sell submission is still being reconciled and will not be sent again.") {
  const error = new Error(message);
  error.tradeSubmissionAmbiguous = true;
  error.tradePreSubmit = false;
  error.signature = String(row.signature || "").trim() || undefined;
  error.partialHashes = error.signature ? [error.signature] : [];
  error.manualSellAttemptId = normalizeManualSellAttemptId(row.manualSellAttemptId || row.attemptId);
  return error;
}

function standaloneManualSellSamePosition(row = {}, identity = {}) {
  return String(row.userId || "").trim() === String(identity.userId || "").trim()
    && String(row.walletPublicKey || "").trim() === String(identity.walletPublicKey || "").trim()
    && String(row.tokenMint || "").trim() === String(identity.tokenMint || "").trim();
}

function standaloneManualSellConsumed(row = {}, options = {}) {
  // Internal confirmation and Activity persistence are not client
  // acknowledgement: the process can disappear after either one but before an
  // HTTP/TG result (or idempotency result) reaches the caller. Legacy
  // `consumedAt` is deliberately ignored. A prior receipt releases only after
  // an explicit acknowledgement marker or a conservative durable replay
  // window, during which a fresh attempt replays the old receipt without a new
  // broadcast.
  if (String(row.clientAcknowledgedAt || row.confirmNewSaleAcknowledgedAt || "").trim()) return true;
  const committedAt = Date.parse(String(row.activityCommittedAt || row.historyRecordedAt || ""));
  if (!Number.isFinite(committedAt)) return false;
  const configuredNow = Number(options.now);
  const now = Number.isFinite(configuredNow) ? configuredNow : Date.now();
  const persistedReplayUntil = Date.parse(String(row.crossAttemptReplayUntil || ""));
  const replayUntil = Number.isFinite(persistedReplayUntil)
    ? persistedReplayUntil
    : committedAt + MANUAL_SELL_CROSS_ATTEMPT_REPLAY_MS;
  return now >= replayUntil;
}

async function readStandaloneManualSellSubmission(identity = {}) {
  const key = standaloneManualSellSubmissionKey(identity);
  if (!key || key.includes("::")) return null;
  const store = await readSolExitReceipts();
  return objectRows(store.manualSubmissions).find((row) => standaloneManualSellSubmissionKey(row) === key) || null;
}

async function persistStandaloneManualSellSubmission(submission = {}) {
  const normalized = {
    ...submission,
    userId: String(submission.userId || "").trim(),
    manualSellAttemptId: normalizeManualSellAttemptId(submission.manualSellAttemptId || submission.attemptId),
    parentManualSellAttemptId: normalizeManualSellAttemptId(submission.parentManualSellAttemptId || submission.manualSellAttemptId || submission.attemptId),
    walletPublicKey: String(submission.walletPublicKey || "").trim(),
    tokenMint: String(submission.tokenMint || "").trim(),
    signature: String(submission.signature || "").trim(),
    tokenAmount: positiveRawString(submission.tokenAmount) || null,
    status: String(submission.status || "submitting").toLowerCase(),
    updatedAt: new Date().toISOString()
  };
  const key = standaloneManualSellSubmissionKey(normalized);
  if (!normalized.userId || !normalized.manualSellAttemptId || !normalized.walletPublicKey
    || !normalized.tokenMint || !normalized.signature || !normalized.tokenAmount || !key) {
    throw new Error("Standalone manual sell checkpoint is missing its user, attempt, wallet, mint, signature, or exact token amount.");
  }
  return withFileLock(solExitReceiptsPath(), async () => {
    const store = await readSolExitReceipts();
    const index = store.manualSubmissions.findIndex((row) => standaloneManualSellSubmissionKey(row) === key);
    const previous = index >= 0 ? store.manualSubmissions[index] : null;
    const attempts = objectRows(previous?.submissionAttempts);
    if (previous?.signature && previous.signature !== normalized.signature
      && !attempts.some((row) => String(row.signature || "") === String(previous.signature))) {
      attempts.push({
        signature: previous.signature,
        status: previous.status || "superseded_pre_submit",
        updatedAt: previous.updatedAt || null
      });
    }
    const saved = {
      ...(previous || {}),
      ...normalized,
      createdAt: previous?.createdAt || normalized.createdAt || normalized.updatedAt,
      submissionAttempts: attempts.slice(-12)
    };
    if (index >= 0) store.manualSubmissions[index] = saved;
    else store.manualSubmissions.push(saved);
    const terminal = new Set(["confirmed", "failed", "expired"]);
    const pending = store.manualSubmissions.filter((row) => !terminal.has(String(row.status || "").toLowerCase()));
    const settled = store.manualSubmissions.filter((row) => terminal.has(String(row.status || "").toLowerCase())).slice(-2_000);
    store.manualSubmissions = [...pending, ...settled];
    await writeJsonFile(solExitReceiptsPath(), store);
    return saved;
  });
}

function manualSolSellFeeIntentKey(row = {}) {
  return [
    String(row.sourceSignature || row.signature || "").trim(),
    String(row.walletPublicKey || "").trim(),
    String(row.tokenMint || "").trim()
  ].join(":");
}

function normalizedManualSolSellFeeLeg(leg = {}) {
  return {
    ...leg,
    status: String(leg.status || "pending").trim().toLowerCase(),
    lamports: normalizeTradeHistoryAmount(leg.lamports || "0"),
    signature: String(leg.signature || "").trim(),
    recentBlockhash: String(leg.recentBlockhash || leg.blockhash || "").trim() || null,
    lastValidBlockHeight: Number.isFinite(Number(leg.lastValidBlockHeight))
      ? Number(leg.lastValidBlockHeight)
      : null
  };
}

function mergeManualSolSellFeeLeg(previous = {}, incoming = {}) {
  const normalized = normalizedManualSolSellFeeLeg(incoming);
  const merged = { ...previous, ...normalized };
  if (!positiveRawString(normalized.lamports) && positiveRawString(previous.lamports)) {
    merged.lamports = normalizeTradeHistoryAmount(previous.lamports);
  }
  if (!normalized.signature && previous.signature) merged.signature = previous.signature;
  if (!normalized.recentBlockhash && previous.recentBlockhash) merged.recentBlockhash = previous.recentBlockhash;
  if (normalized.lastValidBlockHeight === null && previous.lastValidBlockHeight != null) {
    merged.lastValidBlockHeight = previous.lastValidBlockHeight;
  }
  return merged;
}

function manualSolSellFeeIntentUnresolved(intent = {}) {
  if (!intent.collectionFinishedAt) return positiveBigIntOrZero(intent.feeLamports) > 0n;
  return Object.values(intent.legs || {}).some((leg) => (
    positiveBigIntOrZero(leg?.lamports) > 0n
    && ["submitting", "outcome_unknown", "unknown", "ambiguous"].includes(String(leg?.status || "").toLowerCase())
  ));
}

async function persistManualSolSellFeeIntent(intent = {}) {
  const normalized = {
    ...intent,
    userId: String(intent.userId || "").trim(),
    sourceSignature: String(intent.sourceSignature || intent.signature || "").trim(),
    walletPublicKey: String(intent.walletPublicKey || "").trim(),
    tokenMint: String(intent.tokenMint || "").trim(),
    grossSolLamportsReceived: normalizeTradeHistoryAmount(intent.grossSolLamportsReceived || "0"),
    feeLamports: normalizeTradeHistoryAmount(intent.feeLamports || "0"),
    feePaidLamports: normalizeTradeHistoryAmount(intent.feePaidLamports || "0"),
    status: String(intent.status || "submitting").trim().toLowerCase(),
    updatedAt: new Date().toISOString()
  };
  const incomingLegs = intent.legs && typeof intent.legs === "object" && !Array.isArray(intent.legs)
    ? intent.legs
    : {};
  normalized.legs = Object.fromEntries(Object.entries(incomingLegs).map(([name, leg]) => [name, normalizedManualSolSellFeeLeg(leg)]));
  const key = manualSolSellFeeIntentKey(normalized);
  if (!normalized.sourceSignature || !normalized.walletPublicKey || !normalized.tokenMint || !key) {
    throw new Error("Manual sell fee intent is missing its swap signature, wallet, or mint.");
  }
  return withFileLock(solExitReceiptsPath(), async () => {
    const store = await readSolExitReceipts();
    const index = store.manualFeeIntents.findIndex((row) => manualSolSellFeeIntentKey(row) === key);
    const previous = index >= 0 ? store.manualFeeIntents[index] : null;
    const saved = {
      ...(previous || {}),
      ...normalized,
      createdAt: previous?.createdAt || normalized.createdAt || normalized.updatedAt,
      legs: { ...(previous?.legs || {}) }
    };
    for (const [name, leg] of Object.entries(normalized.legs)) {
      saved.legs[name] = mergeManualSolSellFeeLeg(previous?.legs?.[name], leg);
    }
    for (const field of ["grossSolLamportsReceived", "feeLamports", "feePaidLamports"]) {
      if (!positiveRawString(normalized[field]) && positiveRawString(previous?.[field])) {
        saved[field] = normalizeTradeHistoryAmount(previous[field]);
      }
    }
    if (index >= 0) store.manualFeeIntents[index] = saved;
    else store.manualFeeIntents.push(saved);
    const pending = store.manualFeeIntents.filter(manualSolSellFeeIntentUnresolved);
    const settled = store.manualFeeIntents.filter((row) => !manualSolSellFeeIntentUnresolved(row)).slice(-2_000);
    store.manualFeeIntents = [...pending, ...settled];
    await writeJsonFile(solExitReceiptsPath(), store);
    return saved;
  });
}

async function readManualSolSellFeeIntent(identity = {}) {
  const key = manualSolSellFeeIntentKey(identity);
  if (!String(identity.sourceSignature || identity.signature || "").trim()
    || !String(identity.walletPublicKey || "").trim()
    || !String(identity.tokenMint || "").trim()) return null;
  const store = await readSolExitReceipts();
  return store.manualFeeIntents.find((row) => manualSolSellFeeIntentKey(row) === key) || null;
}

function paidManualSolSellFeeLamports(details = {}) {
  return Object.values(details.legs || {}).reduce((total, leg) => {
    const status = String(leg?.status || "").toLowerCase();
    return ["paid", "embedded"].includes(status)
      ? total + positiveBigIntOrZero(leg?.lamports)
      : total;
  }, 0n);
}

function manualSolSellFeeDetailsUnresolved(details = {}) {
  return Object.values(details.legs || {}).some((leg) => (
    positiveBigIntOrZero(leg?.lamports) > 0n
    && ["submitting", "outcome_unknown", "unknown", "ambiguous"].includes(String(leg?.status || "").toLowerCase())
  ));
}

async function reconcileManualSolSellFeeIntent(identity = {}, options = {}) {
  let intent = await readManualSolSellFeeIntent(identity);
  if (!intent) return { state: "resolved", feePaidLamports: "0", intent: null };
  const legs = { ...(intent.legs || {}) };
  const configuredNow = Number(options.now);
  const now = Number.isFinite(configuredNow) ? configuredNow : Date.now();
  const configuredUnsignedStaleMs = Number(options.unsignedStaleMs);
  const unsignedStaleMs = Number.isFinite(configuredUnsignedStaleMs) && configuredUnsignedStaleMs >= 0
    ? configuredUnsignedStaleMs
    : MANUAL_SOL_SELL_UNSIGNED_FEE_STALE_MS;
  const collectionStartedAt = Date.parse(String(intent.collectionStartedAt || intent.createdAt || intent.updatedAt || ""));
  const unsignedIntentStale = !intent.collectionFinishedAt
    && Number.isFinite(collectionStartedAt)
    && now - collectionStartedAt >= unsignedStaleMs;
  let changed = false;
  let unresolved = false;
  for (const [name, original] of Object.entries(legs)) {
    const leg = { ...original };
    const due = positiveBigIntOrZero(leg.lamports) > 0n;
    if (!due) continue;
    const status = String(leg.status || "pending").toLowerCase();
    if (["paid", "embedded", "failed", "expired", "not_due", "not_collected", "skipped"].includes(status)) continue;
    if (!leg.signature) {
      const neverStarted = status === "pending" && !String(leg.signedAt || "").trim();
      if (neverStarted && (intent.collectionFinishedAt || unsignedIntentStale)) {
        leg.status = "not_collected";
        leg.resolvedAt = leg.resolvedAt || intent.collectionFinishedAt || new Date(now).toISOString();
        if (unsignedIntentStale && !intent.collectionFinishedAt) {
          leg.recoveryReason = leg.recoveryReason || "unsigned_intent_stale_before_sign";
        }
        legs[name] = leg;
        changed = true;
      } else {
        unresolved = true;
      }
      continue;
    }
    const outcome = await reconcileSubmittedSolanaSignature(leg.signature, {
      label: `manual sell ${name} fee reconciliation`,
      lastValidBlockHeight: leg.lastValidBlockHeight,
      recentBlockhash: leg.recentBlockhash
    });
    if (outcome.state === "confirmed") {
      leg.status = "paid";
      leg.confirmedAt = leg.confirmedAt || new Date().toISOString();
      changed = true;
    } else if (["failed", "expired"].includes(outcome.state)) {
      leg.status = outcome.state;
      leg.resolvedAt = leg.resolvedAt || new Date().toISOString();
      changed = true;
    } else {
      unresolved = true;
    }
    legs[name] = leg;
  }
  const feePaidLamports = paidManualSolSellFeeLamports({ legs }).toString();
  if (!unresolved) {
    unresolved = Object.values(legs).some((leg) => (
      positiveBigIntOrZero(leg?.lamports) > 0n
      && ["submitting", "outcome_unknown", "unknown", "ambiguous"].includes(String(leg?.status || "").toLowerCase())
    ));
  }
  if (changed || (!unresolved && !intent.resolvedAt)) {
    const resolvedAt = intent.resolvedAt || new Date(now).toISOString();
    intent = await persistManualSolSellFeeIntent({
      ...intent,
      legs,
      feePaidLamports,
      status: unresolved ? "outcome_unknown" : "resolved",
      ...(unresolved ? {} : {
        collectionFinishedAt: intent.collectionFinishedAt || resolvedAt,
        resolvedAt
      })
    });
  }
  return { state: unresolved ? "pending" : "resolved", feePaidLamports, intent };
}

function standaloneManualSellReceipt(row = {}, amounts = {}) {
  const solLamportsReceived = positiveRawString(amounts.solLamportsReceived || row.solLamportsReceived) || "0";
  const waitingForOutput = BigInt(solLamportsReceived) <= 0n;
  return {
    userId: row.userId,
    source: row.source || "manual_sell_confirmed",
    tokenMint: row.tokenMint,
    walletLabel: row.walletLabel || "Managed wallet",
    walletPublicKey: row.walletPublicKey,
    tokenAmount: positiveRawString(amounts.tokenAmount || row.tokenAmount) || "0",
    solLamportsReceived,
    grossSolLamportsReceived: positiveRawString(amounts.grossSolLamportsReceived || row.grossSolLamportsReceived) || solLamportsReceived,
    tradeFeeLamports: positiveRawString(amounts.tradeFeeLamports || row.tradeFeeLamports) || "0",
    feeStatus: amounts.feeStatus || row.feeStatus || "",
    signature: row.signature,
    triggerKind: "manual",
    triggerReason: row.triggerReason || "confirmed manual sell",
    sellPercent: row.percent,
    manualSellAttemptId: row.manualSellAttemptId,
    confirmedAt: row.confirmedAt || new Date().toISOString(),
    historyRecorded: false,
    needsAttention: waitingForOutput,
    historyRecordError: waitingForOutput
      ? "Confirmed manual sell is waiting for its exact wallet proceeds before Activity is completed."
      : null
  };
}

function standaloneManualSellReplayResult(row = {}) {
  const outputLamports = positiveRawString(row.outputLamports || row.solLamportsReceived) || "0";
  const waitingForOutput = !positiveRawString(row.solLamportsReceived) || row.feeRecoveryPending === true;
  const warning = waitingForOutput
    ? "Confirmed sell receipt pending: exact wallet proceeds are still being reconciled; the sell will not be submitted again."
    : firstString(row.recordError);
  return {
    signature: row.signature,
    tokenAmount: row.tokenAmount,
    outputLamports,
    feeLamports: positiveRawString(row.feeLamports) || "0",
    feePaidLamports: normalizeTradeHistoryAmount(row.feePaidLamports || row.tradeFeeLamports || "0"),
    feeRecoveryPending: row.feeRecoveryPending === true,
    feeStatus: row.feeStatus || "",
    manualSellAttemptId: row.manualSellAttemptId,
    duplicate: true,
    recovered: true,
    ...(warning ? { recordError: warning, protectionRecordError: warning } : {})
  };
}

async function reconcileStandaloneManualSellSubmission(identity = {}) {
  let row = identity.signature ? identity : await readStandaloneManualSellSubmission(identity);
  if (!row) return { state: "none", row: null };
  const status = String(row.status || "submitting").toLowerCase();
  if (status === "confirmed") {
    if (!positiveRawString(row.solLamportsReceived) || row.feeRecoveryPending === true) {
      const recovered = await confirmedSolExitWalletReceiptAmounts(row).catch(() => null);
      if (recovered) {
        const receipt = standaloneManualSellReceipt(row, recovered);
        await persistConfirmedSolAutoExitReceipt(receipt);
        row = await persistStandaloneManualSellSubmission({
          ...row,
          status: "confirmed",
          outputLamports: recovered.grossSolLamportsReceived,
          solLamportsReceived: recovered.solLamportsReceived,
          grossSolLamportsReceived: recovered.grossSolLamportsReceived,
          feePaidLamports: recovered.tradeFeeLamports,
          tradeFeeLamports: recovered.tradeFeeLamports,
          feeRecoveryPending: false,
          feeStatus: recovered.feeStatus,
          recordError: null,
          needsAttention: false
        });
      }
    }
    return { state: "confirmed", row, result: standaloneManualSellReplayResult(row) };
  }
  if (["failed", "expired"].includes(status)) return { state: status, row };

  const outcome = await reconcileSubmittedSolanaSignature(row.signature, {
    label: "standalone manual sell reconciliation",
    lastValidBlockHeight: row.lastValidBlockHeight,
    recentBlockhash: row.recentBlockhash
  });
  if (["failed", "expired"].includes(outcome.state)) {
    row = await persistStandaloneManualSellSubmission({ ...row, status: outcome.state, resolvedAt: new Date().toISOString() });
    return { state: outcome.state, row };
  }
  if (outcome.state !== "confirmed") {
    row = await persistStandaloneManualSellSubmission({
      ...row,
      status: "ambiguous",
      needsAttention: true,
      recordError: "The signed manual sell has an unknown outcome and is blocked from replay."
    });
    return { state: "ambiguous", row };
  }

  const exactProceeds = await confirmedSolExitWalletReceiptAmounts(row).catch(() => null);
  const receipt = standaloneManualSellReceipt(row, exactProceeds || {
    solLamportsReceived: "0",
    grossSolLamportsReceived: "0"
  });
  await persistConfirmedSolAutoExitReceipt(receipt);
  row = await persistStandaloneManualSellSubmission({
    ...row,
    status: "confirmed",
    confirmedAt: receipt.confirmedAt,
    outputLamports: exactProceeds?.grossSolLamportsReceived || "0",
    solLamportsReceived: exactProceeds?.solLamportsReceived || "0",
    grossSolLamportsReceived: exactProceeds?.grossSolLamportsReceived || "0",
    feePaidLamports: exactProceeds?.tradeFeeLamports || "0",
    tradeFeeLamports: exactProceeds?.tradeFeeLamports || "0",
    feeRecoveryPending: !exactProceeds,
    feeStatus: exactProceeds?.feeStatus || "",
    needsAttention: !exactProceeds,
    recordError: receipt.historyRecordError
  });
  return { state: "confirmed", row, result: standaloneManualSellReplayResult(row) };
}

async function assertNoUnresolvedStandaloneManualSell(identity = {}, options = {}) {
  const currentAttemptId = normalizeManualSellAttemptId(options.excludeAttemptId);
  const trustedPriorAttemptId = normalizeManualSellAttemptId(options.trustedPriorAttemptId);
  const trustedPriorSignature = String(options.trustedPriorSignature || "").trim();
  const store = await readSolExitReceipts();
  const candidates = objectRows(store.manualSubmissions).filter((row) => (
    standaloneManualSellSamePosition(row, identity)
    && (!currentAttemptId
      || normalizeManualSellAttemptId(row.manualSellAttemptId || row.attemptId) !== currentAttemptId)
    && !standaloneManualSellConsumed(row)
  ));
  const confirmedOutcomes = [];
  for (const candidate of candidates) {
    const outcome = await reconcileStandaloneManualSellSubmission(candidate);
    if (["failed", "expired"].includes(outcome.state)) continue;
    if (outcome.state === "confirmed") {
      if (standaloneManualSellConsumed(outcome.row)) continue;
      confirmedOutcomes.push(outcome);
      continue;
    }
    throw standaloneManualSellSubmissionError(
      outcome.row || candidate,
      "A prior signed sell for this wallet and coin is still being reconciled. SlimeWire blocked a new sell so the same bag cannot be sold twice."
    );
  }
  if (confirmedOutcomes.length) {
    const confirmedReplay = confirmedOutcomes.reduce((latest, outcome) => {
      if (!latest) return outcome;
      const outcomeAt = Date.parse(outcome.row?.confirmedAt || outcome.row?.updatedAt || 0);
      const latestAt = Date.parse(latest.row?.confirmedAt || latest.row?.updatedAt || 0);
      return Number.isFinite(outcomeAt) && (!Number.isFinite(latestAt) || outcomeAt >= latestAt)
        ? outcome
        : latest;
    }, null);
    // One exact acknowledgement of the newest durably applied receipt closes
    // the causal prefix before it. Requiring every still-live prefix receipt
    // to have Activity committed prevents a newer receipt from hiding an older
    // incomplete recovery, while allowing rapid trusted TP -> SL progression.
    const trustedAutomationAcknowledgement = Boolean(
      trustedPriorAttemptId
      && trustedPriorSignature
      && trustedPriorAttemptId === normalizeManualSellAttemptId(
        confirmedReplay.row?.manualSellAttemptId || confirmedReplay.row?.attemptId
      )
      && trustedPriorSignature === String(confirmedReplay.row?.signature || "").trim()
      && confirmedOutcomes.every((outcome) => (
        String(outcome.row?.activityCommittedAt || outcome.row?.historyRecordedAt || "").trim()
      ))
    );
    if (trustedAutomationAcknowledgement) return { checked: candidates.length, replay: null };
    return {
      checked: candidates.length,
      replay: {
        row: confirmedReplay.row,
        result: confirmedReplay.result || standaloneManualSellReplayResult(confirmedReplay.row)
      }
    };
  }
  return { checked: candidates.length, replay: null };
}

async function trustedAutomationManualSellAcknowledgements(userId, tokenMint, walletPublicKeys = []) {
  const wantedWallets = new Set((Array.isArray(walletPublicKeys) ? walletPublicKeys : [walletPublicKeys])
    .map((value) => String(value || "").trim())
    .filter(Boolean));
  const store = await readSolExitReceipts();
  const latestByWallet = new Map();
  for (const row of objectRows(store.manualSubmissions)) {
    const walletPublicKey = String(row.walletPublicKey || "").trim();
    if (String(row.userId || "") !== String(userId || "")
      || String(row.tokenMint || "") !== String(tokenMint || "")
      || (wantedWallets.size && !wantedWallets.has(walletPublicKey))
      || String(row.status || "").toLowerCase() !== "confirmed"
      || standaloneManualSellConsumed(row)
      || !positiveRawString(row.solLamportsReceived)
      || !String(row.activityCommittedAt || row.historyRecordedAt || "").trim()) continue;
    const manualSellAttemptId = normalizeManualSellAttemptId(row.manualSellAttemptId || row.attemptId);
    const signature = String(row.signature || "").trim();
    if (!walletPublicKey || !manualSellAttemptId || !signature) continue;
    const existing = latestByWallet.get(walletPublicKey);
    const rowAt = Date.parse(row.confirmedAt || row.updatedAt || 0);
    const existingAt = Date.parse(existing?.confirmedAt || 0);
    if (!existing || (Number.isFinite(rowAt) && (!Number.isFinite(existingAt) || rowAt > existingAt))) {
      latestByWallet.set(walletPublicKey, {
        walletPublicKey,
        manualSellAttemptId,
        signature,
        confirmedAt: row.confirmedAt || row.updatedAt || null
      });
    }
  }
  return [...latestByWallet.values()];
}

async function reconcileStandaloneManualSellAttempt(userId, manualSellAttemptId) {
  const normalizedAttemptId = normalizeManualSellAttemptId(manualSellAttemptId);
  if (!normalizedAttemptId) return { checked: 0 };
  const store = await readSolExitReceipts();
  const candidates = objectRows(store.manualSubmissions).filter((row) => (
    String(row.userId || "") === String(userId || "")
    && (row.parentManualSellAttemptId === normalizedAttemptId
      || row.manualSellAttemptId === normalizedAttemptId
      || String(row.manualSellAttemptId || "").startsWith(`${normalizedAttemptId}:`))
  ));
  for (const candidate of candidates) {
    const result = await reconcileStandaloneManualSellSubmission(candidate);
    if (result.state === "ambiguous") throw standaloneManualSellSubmissionError(result.row);
  }
  return { checked: candidates.length };
}

async function reconcilePendingStandaloneManualSells(options = {}) {
  const limit = Math.max(1, Math.min(50, Number.parseInt(options.limit || 12, 10) || 12));
  const store = await readSolExitReceipts();
  const candidates = objectRows(store.manualSubmissions).filter((row) => {
    const status = String(row.status || "").toLowerCase();
    if (["ambiguous", "needs_attention"].includes(status)) return true;
    if (status !== "submitting") return false;
    const signedAt = Date.parse(row.signedAt || row.updatedAt || 0);
    return Number.isFinite(signedAt) && Date.now() - signedAt >= CONFIG.stopLossSubmitStaleMs;
  }).slice(0, limit);
  let confirmed = 0;
  let settled = 0;
  let pending = 0;
  for (const candidate of candidates) {
    try {
      const outcome = await reconcileStandaloneManualSellSubmission(candidate);
      if (outcome.state === "confirmed") confirmed += 1;
      else if (["failed", "expired"].includes(outcome.state)) settled += 1;
      else pending += 1;
    } catch {
      pending += 1;
    }
  }
  return { checked: candidates.length, confirmed, settled, pending };
}

function normalizeConfirmedSolAutoExitReceipt(receipt = {}) {
  const signature = String(receipt.signature || receipt.sellSignature || "").trim();
  if (!signature) throw new Error("Confirmed Solana exit receipt is missing its signature.");
  const confirmedAt = String(receipt.confirmedAt || receipt.soldAt || new Date().toISOString());
  return {
    ...receipt,
    signature,
    sellSignature: signature,
    status: "confirmed",
    exitStatus: "confirmed",
    confirmedAt,
    soldAt: String(receipt.soldAt || confirmedAt),
    userId: String(receipt.userId || ""),
    tokenMint: String(receipt.tokenMint || ""),
    walletPublicKey: String(receipt.walletPublicKey || ""),
    tokenAmount: normalizeTradeHistoryAmount(receipt.tokenAmount || "0"),
    solLamportsReceived: normalizeTradeHistoryAmount(receipt.solLamportsReceived || "0"),
    grossSolLamportsReceived: normalizeTradeHistoryAmount(receipt.grossSolLamportsReceived || receipt.solLamportsReceived || "0"),
    tradeFeeLamports: normalizeTradeHistoryAmount(receipt.tradeFeeLamports || "0"),
    historyRecorded: receipt.historyRecorded === true,
    historyRecordedAt: receipt.historyRecordedAt || null
  };
}

function confirmedSolAutoExitReceiptKey(receipt = {}) {
  return [
    String(receipt.signature || receipt.sellSignature || "").trim(),
    String(receipt.walletPublicKey || "").trim(),
    String(receipt.tokenMint || "").trim()
  ].join(":");
}

async function persistConfirmedSolAutoExitReceipt(receipt = {}) {
  const normalized = normalizeConfirmedSolAutoExitReceipt(receipt);
  const key = confirmedSolAutoExitReceiptKey(normalized);
  return withFileLock(solExitReceiptsPath(), async () => {
    const store = await readSolExitReceipts();
    const index = store.receipts.findIndex((row) => confirmedSolAutoExitReceiptKey(row) === key);
    const previous = index >= 0 ? store.receipts[index] : null;
    const saved = previous
      ? { ...previous, ...normalized,
        historyRecorded: previous.historyRecorded === true || normalized.historyRecorded === true,
        historyRecordedAt: previous.historyRecordedAt || normalized.historyRecordedAt || null }
      : normalized;
    if (previous) {
      for (const field of ["tokenAmount", "solLamportsReceived", "grossSolLamportsReceived", "tradeFeeLamports"]) {
        // `normalizeConfirmedSolAutoExitReceipt` falls gross back to net for
        // legacy rows. During an enrichment merge that fallback must not make
        // an omitted gross value look exact and replace a previously persisted
        // positive gross amount.
        const incomingPositive = field === "grossSolLamportsReceived"
          ? positiveRawString(receipt[field])
          : positiveRawString(normalized[field]);
        if (!incomingPositive && positiveRawString(previous[field])) {
          saved[field] = normalizeTradeHistoryAmount(previous[field]);
        }
      }
      if (!String(normalized.feeStatus || "").trim() && String(previous.feeStatus || "").trim()) {
        saved.feeStatus = previous.feeStatus;
      }
      // A sparse/zero recovery checkpoint can never downgrade an already exact
      // receipt back to attention-needed after the chain amounts were saved.
      if (positiveRawString(saved.solLamportsReceived)) {
        saved.needsAttention = false;
        if (/waiting for (?:its )?exact wallet proceeds/i.test(String(saved.historyRecordError || ""))) {
          saved.historyRecordError = null;
        }
      }
    }
    if (index >= 0) store.receipts[index] = saved;
    else store.receipts.push(saved);
    const pending = store.receipts.filter((row) => confirmedExitNeedsHistoryBackfill(row));
    const recorded = store.receipts.filter((row) => !confirmedExitNeedsHistoryBackfill(row)).slice(-SOL_EXIT_RECEIPT_RECORDED_MAX);
    store.receipts = [...pending, ...recorded];
    await writeJsonFile(solExitReceiptsPath(), store);
    return saved;
  });
}

async function markConfirmedSolAutoExitHistoryRecorded(receipt = {}) {
  const key = confirmedSolAutoExitReceiptKey(receipt);
  if (!key || key.startsWith(":")) return false;
  return withFileLock(solExitReceiptsPath(), async () => {
    const store = await readSolExitReceipts();
    const row = store.receipts.find((candidate) => confirmedSolAutoExitReceiptKey(candidate) === key);
    if (!row) return false;
    row.historyRecorded = true;
    row.historyRecordedAt = row.historyRecordedAt || new Date().toISOString();
    for (const submission of store.manualSubmissions) {
      if (String(submission.signature || "").trim() !== String(row.signature || row.sellSignature || "").trim()
        || String(submission.walletPublicKey || "").trim() !== String(row.walletPublicKey || "").trim()
        || String(submission.tokenMint || "").trim() !== String(row.tokenMint || "").trim()) continue;
      // A positive Activity row for this exact signed receipt is authoritative
      // confirmation even if an earlier standalone-status write failed after
      // the receipt itself landed.
      submission.status = "confirmed";
      submission.confirmedAt = submission.confirmedAt || row.confirmedAt || row.historyRecordedAt;
      submission.consumedAt = submission.consumedAt || row.historyRecordedAt;
      submission.historyRecordedAt = submission.historyRecordedAt || row.historyRecordedAt;
      submission.activityCommittedAt = submission.activityCommittedAt || row.historyRecordedAt;
      submission.crossAttemptReplayUntil = submission.crossAttemptReplayUntil || new Date(
        Date.parse(submission.activityCommittedAt) + MANUAL_SELL_CROSS_ATTEMPT_REPLAY_MS
      ).toISOString();
      submission.needsAttention = false;
    }
    await writeJsonFile(solExitReceiptsPath(), store);
    return true;
  });
}

function confirmedSolSellReceiptAmounts(sell = {}) {
  const gross = positiveBigIntOrZero(sell.outputLamports);
  const quotedFee = positiveBigIntOrZero(sell.feeLamports);
  const hasExactPaidFee = Object.prototype.hasOwnProperty.call(sell || {}, "feePaidLamports");
  const paidFee = hasExactPaidFee
    ? positiveBigIntOrZero(sell.feePaidLamports)
    : (quotedFee > 0n && !/fee failed/i.test(String(sell.feeStatus || "")) ? quotedFee : 0n);
  const feePending = sell.feeRecoveryPending === true;
  const net = feePending ? 0n : (gross >= paidFee ? gross - paidFee : 0n);
  return {
    solLamportsReceived: net.toString(),
    grossSolLamportsReceived: gross.toString(),
    tradeFeeLamports: paidFee.toString(),
    feeStatus: sell.feeStatus || ""
  };
}

function manualSellReceiptWarning(sell = {}) {
  return firstString(sell.protectionRecordError, sell.recordError);
}

function confirmedSolAutoExitTradeEvent(receipt = {}) {
  return {
    userId: receipt.userId,
    type: "sell",
    source: receipt.source || "managed_auto_exit",
    tokenMint: receipt.tokenMint,
    walletLabel: receipt.walletLabel || "Managed wallet",
    walletPublicKey: receipt.walletPublicKey,
    tokenAmount: receipt.tokenAmount,
    solLamportsReceived: receipt.solLamportsReceived,
    grossSolLamportsReceived: receipt.grossSolLamportsReceived || receipt.solLamportsReceived,
    tradeFeeLamports: receipt.tradeFeeLamports || "0",
    feeStatus: receipt.feeStatus || "",
    signature: receipt.signature || receipt.sellSignature
  };
}

async function recordConfirmedSolAutoExit(receipt = {}) {
  let saved;
  try {
    // The receipt is the durable source of truth. It must land before the
    // derived activity row, otherwise a crash can leave a confirmed sell out
    // of history with nothing safe to replay.
    saved = await persistConfirmedSolAutoExitReceipt(receipt);
  } catch (error) {
    return { recorded: false, error: `receipt persistence failed: ${friendlyError(error)}` };
  }

  if (BigInt(saved.solLamportsReceived || 0) <= 0n) {
    return { recorded: false, pendingOutput: true, receipt: saved };
  }
  try {
    await recordTradeEvents([confirmedSolAutoExitTradeEvent(saved)]);
  } catch (error) {
    return { recorded: false, error: friendlyError(error), receipt: saved };
  }
  try {
    await markConfirmedSolAutoExitHistoryRecorded(saved);
  } catch (error) {
    // The history append is signature-idempotent. Leaving the marker false
    // makes the bounded backfill verify history and repair the marker later.
    return { recorded: true, markerPending: true, error: friendlyError(error), receipt: saved };
  }
  return { recorded: true, receipt: saved };
}

async function confirmedSolExitWalletReceiptAmounts(receipt = {}) {
  const signature = String(receipt.signature || receipt.sellSignature || "").trim();
  const walletPublicKey = String(receipt.walletPublicKey || "").trim();
  if (!signature || !walletPublicKey) return null;
  const tx = await rpcRead("read confirmed Solana auto-exit receipt", (client) => client.getParsedTransaction(signature, {
    commitment: "confirmed",
    maxSupportedTransactionVersion: 0
  }));
  if (!tx || tx.meta?.err) return null;
  const delta = parsedWalletLamportDelta(tx, new Set([walletPublicKey]));
  if (!Number.isSafeInteger(delta) || delta <= 0) return null;
  const fee = await reconcileManualSolSellFeeIntent({
    sourceSignature: signature,
    walletPublicKey,
    tokenMint: receipt.tokenMint
  });
  if (fee.state !== "resolved") return null;
  const gross = BigInt(delta);
  const paidFee = positiveBigIntOrZero(fee.feePaidLamports);
  const net = gross >= paidFee ? gross - paidFee : 0n;
  if (net <= 0n) return null;
  return {
    solLamportsReceived: net.toString(),
    grossSolLamportsReceived: gross.toString(),
    tradeFeeLamports: paidFee.toString(),
    feeStatus: paidFee > 0n ? ", fee recovered from confirmed debit" : ""
  };
}

async function confirmedSolExitWalletLamportDelta(receipt = {}) {
  const amounts = await confirmedSolExitWalletReceiptAmounts(receipt);
  return amounts?.solLamportsReceived || null;
}

function confirmedSolExitCandidateStatus(row = {}) {
  return [row.status, row.exitStatus, row.triggerStatus]
    .map((value) => String(value || "").toLowerCase())
    .some((status) => ["sold", "confirmed", "closed"].includes(status));
}

async function seedConfirmedSolAutoExitReceipts(options = {}) {
  const limit = Math.max(1, Math.min(500, Number.parseInt(options.limit || 200, 10) || 200));
  const [planStore, guardStore, receiptStore] = await Promise.all([
    readTradePlans(),
    readWebExitGuards(),
    readSolExitReceipts()
  ]);
  const existing = new Set(objectRows(receiptStore.receipts).map(confirmedSolAutoExitReceiptKey));
  const candidates = [];

  for (const plan of objectRows(planStore.plans)) {
    for (const wallet of objectRows(plan.wallets)) {
      for (const partial of objectRows(wallet.partialExitSignatures)) {
        const partialSignature = firstString(partial.signature, partial.sellSignature);
        if (!partialSignature) continue;
        candidates.push({
          userId: plan.userId,
          source: timedPlanExitSource(plan),
          tokenMint: plan.tokenMint,
          walletLabel: wallet.label || "Managed wallet",
          walletPublicKey: wallet.publicKey,
          tokenAmount: firstString(partial.tokenAmount, partial.soldTokenAmount, "0"),
          solLamportsReceived: firstString(partial.solLamportsReceived, partial.outputLamports, "0"),
          signature: partialSignature,
          provider: partial.provider || wallet.sellProvider || null,
          triggerKind: "take-profit",
          triggerReason: firstString(partial.triggerReason, `take-profit ladder ${partial.targetPct || ""}`),
          sellPercent: partial.sellPercent || plan.triggerSellPercent || plan.sellPercent || 100,
          planId: plan.id || null,
          confirmedAt: firstString(partial.soldAt, partial.confirmedAt, plan.updatedAt, plan.createdAt)
        });
      }
      const signature = firstString(wallet.sellSignature, wallet.exitSignature);
      if (!signature || !confirmedSolExitCandidateStatus(wallet)) continue;
      candidates.push({
        userId: plan.userId,
        source: timedPlanExitSource(plan),
        tokenMint: plan.tokenMint,
        walletLabel: wallet.label || "Managed wallet",
        walletPublicKey: wallet.publicKey,
        tokenAmount: firstString(wallet.soldTokenAmount, wallet.sellTokenAmount, wallet.tokenAmount, "0"),
        solLamportsReceived: firstString(wallet.solLamportsReceived, wallet.outputLamports, wallet.sellOutputLamports, "0"),
        signature,
        provider: wallet.sellProvider || null,
        triggerKind: wallet.triggerKind || (/^stop-loss\b/i.test(String(wallet.triggerReason || "")) ? "stop-loss" : /^take-profit\b/i.test(String(wallet.triggerReason || "")) ? "take-profit" : "timer"),
        triggerReason: wallet.triggerReason || "confirmed managed exit",
        sellPercent: wallet.triggerSellPercent || plan.triggerSellPercent || plan.sellPercent || 100,
        planId: plan.id || null,
        confirmedAt: firstString(wallet.soldAt, wallet.submissionResolvedAt, plan.completedAt, plan.updatedAt, plan.createdAt)
      });
    }
  }
  for (const guard of objectRows(guardStore.guards)) {
    const signature = firstString(guard.sellSignature, guard.exitSignature);
    if (!signature || !confirmedSolExitCandidateStatus(guard)) continue;
    candidates.push({
      userId: guard.userId,
      source: guard.source || "web_exit_guard",
      tokenMint: guard.tokenMint,
      walletLabel: guard.walletLabel || "Managed wallet",
      walletPublicKey: guard.walletPublicKey,
      tokenAmount: firstString(guard.soldTokenAmount, guard.sellTokenAmount, guard.tokenAmount, "0"),
      solLamportsReceived: firstString(guard.solLamportsReceived, guard.outputLamports, guard.sellOutputLamports, "0"),
      signature,
      provider: guard.sellProvider || null,
      triggerKind: guard.triggerKind || (/^stop-loss\b/i.test(String(guard.triggerReason || "")) ? "stop-loss" : /^take-profit\b/i.test(String(guard.triggerReason || "")) ? "take-profit" : "timer"),
      triggerReason: guard.triggerReason || "confirmed web exit guard",
      sellPercent: guard.triggerSellPercent || guard.sellPercent || 100,
      guardId: guard.id || guard.key || null,
      planId: guard.planId || null,
      confirmedAt: firstString(guard.soldAt, guard.submissionResolvedAt, guard.updatedAt, guard.createdAt)
    });
  }

  candidates.sort((left, right) => Date.parse(right.confirmedAt || 0) - Date.parse(left.confirmedAt || 0));
  let seeded = 0;
  for (const candidate of candidates) {
    const normalized = normalizeConfirmedSolAutoExitReceipt(candidate);
    const key = confirmedSolAutoExitReceiptKey(normalized);
    if (existing.has(key)) continue;
    await persistConfirmedSolAutoExitReceipt(normalized);
    existing.add(key);
    seeded += 1;
    if (seeded >= limit) break;
  }
  return { checked: candidates.length, seeded };
}

async function backfillConfirmedSolAutoExitHistory(options = {}) {
  if (solExitHistoryBackfillActive) return { skipped: true, reason: "active" };
  solExitHistoryBackfillActive = true;
  const limit = Math.max(1, Math.min(25, Number.parseInt(options.limit || 8, 10) || 8));
  try {
    const seeded = await seedConfirmedSolAutoExitReceipts({ limit: 250 });
    const [receiptStore, historyStore] = await Promise.all([readSolExitReceipts(), readTradeHistory()]);
    // Source-specific manual paths append their own Activity row after the
    // durable receipt. Mark those receipts complete without re-appending or
    // fanning out duplicate trade notifications.
    const markerReady = receiptStore.receipts.filter((receipt) => (
      confirmedExitNeedsHistoryBackfill(receipt)
      && !confirmedExitNeedsHistoryBackfill(receipt, historyStore.trades)
    )).slice(0, limit);
    const pending = receiptStore.receipts
      // Re-check the actual signature row, not only the receipt marker. Older
      // builds could mark a receipt complete while dedupe left a zero-output
      // row behind; those rows must be repaired too.
      .filter((receipt) => confirmedExitNeedsHistoryBackfill(receipt, historyStore.trades))
      .slice(0, limit);
    let recorded = 0;
    let marked = 0;
    let deferred = 0;
    for (const receipt of markerReady) {
      if (await markConfirmedSolAutoExitHistoryRecorded(receipt).catch(() => false)) marked += 1;
      else deferred += 1;
    }
    for (const original of pending) {
      let receipt = original;
      if (BigInt(receipt.solLamportsReceived || 0) <= 0n) {
        const recovered = await confirmedSolExitWalletReceiptAmounts(receipt).catch(() => null);
        if (!recovered) {
          deferred += 1;
          continue;
        }
        receipt = await persistConfirmedSolAutoExitReceipt({
          ...receipt,
          ...recovered,
          historyRecordError: null,
          needsAttention: false
        });
      }
      const result = await recordConfirmedSolAutoExit(receipt);
      if (result.recorded) recorded += 1;
      else deferred += 1;
    }
    return { checked: markerReady.length + pending.length, recorded, marked, deferred, seeded: seeded.seeded };
  } finally {
    solExitHistoryBackfillActive = false;
  }
}

function enrichIncompleteSellHistoryEvent(existing = {}, incoming = {}) {
  if (String(existing.type || "").toLowerCase() !== "sell"
    || String(incoming.type || "").toLowerCase() !== "sell") return false;
  const exactReceived = positiveRawString(incoming.solLamportsReceived);
  if (!exactReceived || positiveRawString(existing.solLamportsReceived)) return false;

  existing.solLamportsReceived = normalizeTradeHistoryAmount(exactReceived);
  if (!positiveRawString(existing.grossSolLamportsReceived)
    && positiveRawString(incoming.grossSolLamportsReceived)) {
    existing.grossSolLamportsReceived = normalizeTradeHistoryAmount(incoming.grossSolLamportsReceived);
  }
  if (!positiveRawString(existing.tradeFeeLamports)
    && positiveRawString(incoming.tradeFeeLamports)) {
    existing.tradeFeeLamports = normalizeTradeHistoryAmount(incoming.tradeFeeLamports);
  }
  if (!positiveRawString(existing.tokenAmount) && positiveRawString(incoming.tokenAmount)) {
    existing.tokenAmount = normalizeTradeHistoryAmount(incoming.tokenAmount);
  }
  if (!String(existing.feeStatus || "").trim() && String(incoming.feeStatus || "").trim()) {
    existing.feeStatus = incoming.feeStatus;
  }
  if (!String(existing.source || "").trim() && String(incoming.source || "").trim()) {
    existing.source = incoming.source;
  }
  existing.historyEnrichedAt = new Date().toISOString();
  return true;
}

async function recordTradeEvents(events) {
  if (!events.length) return;
  for (const event of events) {
    invalidateWalletReadCache(event.walletPublicKey);
    if (event?.tokenMint && /pump|launch/i.test(String(event.source || event.type || ""))) {
      invalidateTokenMetadataCache(event.tokenMint);
    }
  }
  const sanitizedEvents = events.map((event) => ({
    ...event,
    solLamportsSpent: Object.prototype.hasOwnProperty.call(event || {}, "solLamportsSpent")
      ? normalizeTradeHistoryAmount(event.solLamportsSpent)
      : event.solLamportsSpent,
    solLamportsReceived: Object.prototype.hasOwnProperty.call(event || {}, "solLamportsReceived")
      ? normalizeTradeHistoryAmount(event.solLamportsReceived)
      : event.solLamportsReceived,
    tokenAmount: Object.prototype.hasOwnProperty.call(event || {}, "tokenAmount")
      ? normalizeTradeHistoryAmount(event.tokenAmount)
      : event.tokenAmount
  }));
  // Lock the read-modify-write (was racy → lost/duplicated trades) and skip any event whose on-chain
  // trade is already recorded, so `received`/`spent` can't be double-counted.
  const insertedEvents = [];
  await withFileLock(tradeHistoryPath(), async () => {
    const store = await readTradeHistory();
    const byKey = new Map(store.trades.map((trade) => [tradeEventDedupeKey(trade), trade]).filter(([key]) => Boolean(key)));
    for (const event of sanitizedEvents) {
      const key = tradeEventDedupeKey(event);
      const existing = key ? byKey.get(key) : null;
      if (existing) {
        // A response-loss/manual-recovery path can record the signature before
        // exact proceeds are indexed. Signature dedupe must enrich that row,
        // never freeze a false zero and block the durable receipt backfill.
        enrichIncompleteSellHistoryEvent(existing, event);
        continue;
      }
      const inserted = { id: crypto.randomUUID(), timestamp: new Date().toISOString(), ...event };
      store.trades.push(inserted);
      if (key) byKey.set(key, inserted);
      insertedEvents.push(inserted);
    }
    await writeJsonFile(tradeHistoryPath(), store);
  });
  // A confirmed standalone sell remains a cross-attempt tombstone through the
  // source-specific Activity commit and the durable response-loss replay
  // window. If the process dies around either write, backfill observes the same
  // positive signature row and repairs the marker without submitting again.
  const committedSellReceipts = sanitizedEvents.filter((event) => (
    String(event.type || "").toLowerCase() === "sell"
    && String(event.signature || "").trim()
    && String(event.walletPublicKey || "").trim()
    && String(event.tokenMint || "").trim()
    && Boolean(positiveRawString(event.solLamportsReceived))
  ));
  for (const event of committedSellReceipts) {
    await markConfirmedSolAutoExitHistoryRecorded(event).catch(() => false);
  }
  void maybeCopyRoomBest(events).catch(() => {});   // 🪞 Copy-the-room's-best: mirror a followed trader's buy
  void maybeCopyRoomConsensus(events).catch(() => {});   // 🤝 Copy room consensus: mirror when ≥2 board traders agree
  void maybeCreditReferralConversion(events).catch(() => {});   // 🎟️ credit a site-referred user's first trade to their TG inviter
  for (const funnelEvent of events) if (funnelEvent?.userId) void recordFunnelTrade(String(funnelEvent.userId)); // 📊 growth funnel
  void pvpBroadcastTradeEvents(events).catch(() => {});   // 🥊 PvP live feed: post members' trades to their arena groups
  void notifyProfileTradeFollowers(insertedEvents).catch(() => {}); // alerts only; never copies a trade

  const hasWebBuyNeedingGuard = events.some((event) => (
    event?.type === "buy"
    && event?.userId
    && event?.walletPublicKey
    && event?.tokenMint
    && eligibleWebDefaultExitSource(event.source)
  ));
  if (hasWebBuyNeedingGuard) {
    scheduleWebExitGuardProcessing("web buy recorded", [250, 750, 1500, 3000, 6000, 12000]);
  }
}

async function readSniperSettings() {
  const store = await readJson(sniperSettingsPath());
  if (!store.users || typeof store.users !== "object") store.users = {};
  return store;
}

async function writeSniperSettings(store) {
  await writeJsonFile(sniperSettingsPath(), store);
}

async function readWebAuthStore() {
  const store = await readJson(webAuthPath());
  if (!Array.isArray(store.codes)) store.codes = [];
  if (!Array.isArray(store.sessions)) store.sessions = [];
  if (!Array.isArray(store.telegramLoginTicketUses)) store.telegramLoginTicketUses = [];
  if (!store.profiles || typeof store.profiles !== "object") store.profiles = {};
  if (!store.cashRecoveryIndex || typeof store.cashRecoveryIndex !== "object" || Array.isArray(store.cashRecoveryIndex)) store.cashRecoveryIndex = {};
  if (!store.cashHandleHistory || typeof store.cashHandleHistory !== "object" || Array.isArray(store.cashHandleHistory)) store.cashHandleHistory = {};
  if (!store.mobileWalletConnects || typeof store.mobileWalletConnects !== "object") store.mobileWalletConnects = {};
  if (!Array.isArray(store.browserTradeOrders)) store.browserTradeOrders = [];
  if (!Array.isArray(store.sessionWalletOrders)) store.sessionWalletOrders = [];
  return store;
}

async function readGrowthStats() {
  const store = await readJson(growthStatsPath()).catch(() => ({ telegramUsers: {}, days: {} }));
  if (!store.telegramUsers || typeof store.telegramUsers !== "object") store.telegramUsers = {};
  if (!store.directTelegramUsers || typeof store.directTelegramUsers !== "object") store.directTelegramUsers = {};
  if (!store.days || typeof store.days !== "object") store.days = {};
  return store;
}

const growthTelegramProcessSeen = new Set();
async function recordTelegramGrowthUser(userId, telegramUser = {}) {
  const raw = String(userId || "");
  if (!raw) return;
  const day = new Date().toISOString().slice(0, 10);
  const now = new Date().toISOString();
  const userHash = hashWebSecret(`growth:telegram:${raw}`).slice(0, 24);
  const processKey = `${day}:${userHash}`;
  if (growthTelegramProcessSeen.has(processKey)) return;
  await withFileLock(growthStatsPath(), async () => {
    const store = await readGrowthStats();
    const isNew = !store.telegramUsers[userHash];
    if (isNew) store.telegramUsers[userHash] = { firstSeenDay: day };
    const directNew = !store.directTelegramUsers[userHash];
    const existing = store.directTelegramUsers[userHash] || {};
    const username = String(telegramUser?.username || existing.username || "").replace(/^@+/, "").trim().slice(0, 64);
    const displayName = [telegramUser?.first_name, telegramUser?.last_name]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .join(" ")
      .slice(0, 120) || String(existing.displayName || "");
    store.directTelegramUsers[userHash] = {
      ...existing,
      telegramUserId: raw,
      username,
      displayName,
      firstSeenAt: existing.firstSeenAt || now,
      firstSeenDay: existing.firstSeenDay || day,
      lastSeenAt: now,
      lastSeenDay: day
    };
    const row = store.days[day] && typeof store.days[day] === "object" ? store.days[day] : { telegramNew: 0, telegramActive: {} };
    if (!row.telegramActive || typeof row.telegramActive !== "object") row.telegramActive = {};
    if (!row.telegramDirectActive || typeof row.telegramDirectActive !== "object") row.telegramDirectActive = {};
    row.telegramActive[userHash] = 1;
    row.telegramDirectActive[userHash] = 1;
    if (isNew) row.telegramNew = Number(row.telegramNew || 0) + 1;
    if (directNew) row.telegramDirectNew = Number(row.telegramDirectNew || 0) + 1;
    store.days[day] = row;
    const keep = Object.keys(store.days).sort().slice(-120);
    for (const key of Object.keys(store.days)) if (!keep.includes(key)) delete store.days[key];
    await writeJsonFile(growthStatsPath(), store);
  });
  growthTelegramProcessSeen.add(processKey);
}

const OWNER_ANALYTICS_TICKET_TTL_MS = 30 * 60 * 1000;
const OWNER_ANALYTICS_SESSION_TTL_MS = 30 * 60 * 1000;
const OWNER_ANALYTICS_ORIGIN = "https://app.slimewire.org";
const ownerAnalyticsTickets = new Map();
const ownerAnalyticsSessions = new Map();

function ownerAnalyticsDashboardUrl(ticket = "") {
  const url = new URL("/owner-analytics", `${OWNER_ANALYTICS_ORIGIN}/`);
  if (ticket) url.searchParams.set("t", String(ticket));
  return url.toString();
}

function pruneOwnerAnalyticsAccess(now = Date.now()) {
  for (const [key, row] of ownerAnalyticsTickets) if (Number(row?.expiresAt || 0) <= now) ownerAnalyticsTickets.delete(key);
  for (const [key, row] of ownerAnalyticsSessions) if (Number(row?.expiresAt || 0) <= now) ownerAnalyticsSessions.delete(key);
}

function isOwnerAnalyticsTelegramUser(chatId, userId) {
  const chat = String(chatId || "");
  const user = String(userId || "");
  const claimedOwner = xReplyOwnerChat();
  if (claimedOwner) return chat === claimedOwner && user === claimedOwner;
  const admins = CONFIG.adminUserIds.map((value) => String(value));
  return admins.length === 1 && chat === user && admins[0] === user;
}

function issueOwnerAnalyticsTicket(userId) {
  pruneOwnerAnalyticsAccess();
  const grant = {
    kind: "owner-analytics",
    userId: String(userId || ""),
    expiresAt: Date.now() + OWNER_ANALYTICS_TICKET_TTL_MS,
    nonce: crypto.randomBytes(16).toString("base64url"),
  };
  // Stateless signing keeps the private Telegram link valid when Render restarts during a deploy or
  // routes the click to a different instance. The in-memory copy remains only for backward compatibility.
  const ticket = signVerifyToken({ ...grant, exp: grant.expiresAt });
  ownerAnalyticsTickets.set(ticket, grant);
  return ticket;
}

function validateOwnerAnalyticsTicket(ticket) {
  pruneOwnerAnalyticsAccess();
  const key = String(ticket || "");
  const row = ownerAnalyticsTickets.get(key);
  // Do not consume on GET. Telegram, mobile browsers and security scanners may preview a private link before
  // the owner sees it; deleting here made the real tap land on "Not found". The random bearer remains valid
  // only for the five-minute TTL, while the resulting HttpOnly owner session is still private and short-lived.
  if (row && Number(row.expiresAt || 0) > Date.now()) return row;
  const signed = readVerifyToken(key);
  if (!signed || signed.kind !== "owner-analytics" || !signed.userId || !signed.nonce) return null;
  const expiresAt = Number(signed.expiresAt || signed.exp || 0);
  if (expiresAt <= Date.now() || expiresAt > Date.now() + OWNER_ANALYTICS_TICKET_TTL_MS + 30_000) return null;
  return { userId: String(signed.userId), expiresAt };
}

function createOwnerAnalyticsSession(userId) {
  pruneOwnerAnalyticsAccess();
  const sessionId = crypto.randomBytes(32).toString("base64url");
  ownerAnalyticsSessions.set(sessionId, {
    userId: String(userId || ""),
    expiresAt: Date.now() + OWNER_ANALYTICS_SESSION_TTL_MS
  });
  return sessionId;
}

function ownerAnalyticsSessionForRequest(request) {
  pruneOwnerAnalyticsAccess();
  const sessionId = readRequestCookie(request, "sw_owner_analytics");
  const session = ownerAnalyticsSessions.get(sessionId);
  if (!session || Number(session.expiresAt || 0) <= Date.now()) return null;
  session.expiresAt = Date.now() + OWNER_ANALYTICS_SESSION_TTL_MS;
  return { sessionId, ...session };
}

function ownerAnalyticsCookie(sessionId, maxAgeSeconds = Math.floor(OWNER_ANALYTICS_SESSION_TTL_MS / 1000)) {
  return `sw_owner_analytics=${encodeURIComponent(sessionId || "")}; Path=/; Max-Age=${maxAgeSeconds}; HttpOnly; Secure; SameSite=Lax`;
}

function ownerAnalyticsPrivateHeaders(extra = {}) {
  return {
    "Cache-Control": "no-store, private",
    "X-Robots-Tag": "noindex, nofollow, noarchive",
    "Referrer-Policy": "no-referrer",
    "X-Frame-Options": "DENY",
    "Cross-Origin-Resource-Policy": "same-origin",
    "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
    ...extra
  };
}

function ownerAnalyticsNotFound(response) {
  response.writeHead(404, ownerAnalyticsPrivateHeaders({ "Content-Type": "text/plain; charset=utf-8" }));
  response.end("Not found");
}

function sendOwnerAnalyticsJson(response, status, data, extraHeaders = {}) {
  response.writeHead(status, ownerAnalyticsPrivateHeaders({
    "Content-Type": "application/json; charset=utf-8",
    ...extraHeaders
  }));
  response.end(JSON.stringify(data));
}

async function serveOwnerAnalyticsPage(requestUrl, request, response) {
  const ticket = requestUrl.searchParams.get("t");
  if (ticket) {
    const requestHost = firstString(request.headers["x-forwarded-host"], request.headers.host).split(",")[0].trim().replace(/:\d+$/, "").toLowerCase();
    if (requestHost && requestHost !== new URL(OWNER_ANALYTICS_ORIGIN).hostname) {
      response.writeHead(307, ownerAnalyticsPrivateHeaders({ Location: ownerAnalyticsDashboardUrl(ticket) }));
      response.end();
      return;
    }
    const grant = validateOwnerAnalyticsTicket(ticket);
    if (!grant) { ownerAnalyticsNotFound(response); return; }
    const sessionId = createOwnerAnalyticsSession(grant.userId);
    response.writeHead(303, ownerAnalyticsPrivateHeaders({
      Location: "/owner-analytics",
      "Set-Cookie": ownerAnalyticsCookie(sessionId)
    }));
    response.end();
    return;
  }
  if (!ownerAnalyticsSessionForRequest(request)) { ownerAnalyticsNotFound(response); return; }
  await serveStaticHtmlPage(response, "owner-analytics.html", "no-store, private", ownerAnalyticsPrivateHeaders());
}

function ownerAnalyticsPlaceholderName(value) {
  const text = String(value || "").trim();
  if (!text) return true;
  const flat = text.replace(/^@+/, "").toLowerCase();
  if (/^(?:profile|wallet|guest|anonymous|anon|trader|user|degen)(?:[-_ .]?\w*)?$/.test(flat)) return true;
  if (/^web[_-]/.test(flat) || /^\d{5,}$/.test(flat)) return true;
  if (/^[1-9A-HJ-NP-Za-km-z]{30,50}$/.test(text) || /^[a-f0-9]{32,}$/i.test(text)) return true;
  return false;
}

function ownerAnalyticsDisplayName(profile = {}, telegramUser = {}) {
  const candidates = [
    profile.username,
    profile.cashHandleDisplay,
    profile.cashHandle,
    profile.displayName,
    profile.name,
    telegramUser.username ? `@${String(telegramUser.username).replace(/^@+/, "")}` : "",
    telegramUser.displayName
  ];
  const value = candidates.map((item) => String(item || "").trim()).find((item) => !ownerAnalyticsPlaceholderName(item));
  return value ? { name: value.slice(0, 120), hasRealName: true } : { name: "", hasRealName: false };
}

function ownerAnalyticsPeriodStart(period, now = Date.now()) {
  const today = new Date().toISOString().slice(0, 10);
  if (period === "today") return Date.parse(`${today}T00:00:00.000Z`);
  if (period === "7d") return now - 7 * 24 * 60 * 60 * 1000;
  if (period === "30d") return now - 30 * 24 * 60 * 60 * 1000;
  return 0;
}

function ownerAnalyticsTimestamp(row, ...fields) {
  for (const field of fields) {
    const at = Date.parse(row?.[field] || "");
    if (Number.isFinite(at) && at > 0) return at;
  }
  return 0;
}

async function platformOwnerAnalyticsSnapshot(period = "all") {
  const selectedPeriod = ["today", "7d", "30d", "all"].includes(period) ? period : "all";
  const sinceMs = ownerAnalyticsPeriodStart(selectedPeriod);
  const [auth, walletStore, tradeHistory, growth, telegramLinks, funnel, tgGroups, groupMentions, rhHistory, auditLog] = await Promise.all([
    readWebAuthStore(), readWalletStore(), readTradeHistory(), readGrowthStats(), readTelegramLinks(), readFunnel(),
    readTelegramGroups().catch(() => ({ groups: {} })), readGroupMentions().catch(() => ({ groups: {} })),
    readRhTradeHistory().catch(() => ({ trades: [] })), readJson(auditPath()).catch(() => ({ entries: [] }))
  ]);
  const profiles = auth.profiles || {};
  const links = telegramLinks.links || {};
  const directByTelegramId = new Map();
  for (const entry of Object.values(growth.directTelegramUsers || {})) {
    const telegramUserId = String(entry?.telegramUserId || "");
    if (telegramUserId) directByTelegramId.set(telegramUserId, entry);
  }
  const webByTelegramId = new Map();
  for (const [profileId, telegramValue] of Object.entries(links)) {
    const telegramUserId = String(telegramValue?.telegramUserId || telegramValue?.userId || telegramValue || "");
    if (telegramUserId) webByTelegramId.set(telegramUserId, profileId);
  }
  const canonicalId = (ownerId) => webByTelegramId.get(String(ownerId || "")) || String(ownerId || "");
  const rows = new Map();
  const ensureRow = (ownerId) => {
    const key = canonicalId(ownerId);
    if (!key || key.startsWith("__")) return null;
    if (!rows.has(key)) rows.set(key, {
      key,
      profileId: profiles[key] ? key : "",
      telegramUserId: /^\d+$/.test(key) ? key : "",
      wallets: [],
      trades: [],
      referrals: [],
      sessions: [],
      funnel: funnel.users?.[key] || {}
    });
    return rows.get(key);
  };
  for (const [profileId] of Object.entries(profiles)) ensureRow(profileId);
  for (const telegramUserId of directByTelegramId.keys()) ensureRow(telegramUserId);
  for (const [profileId, telegramValue] of Object.entries(links)) {
    const row = ensureRow(profileId);
    const telegramUserId = String(telegramValue?.telegramUserId || telegramValue?.userId || telegramValue || "");
    if (row && telegramUserId) row.telegramUserId = telegramUserId;
  }
  for (const wallet of walletStore.wallets || []) {
    const row = ensureRow(wallet?.ownerId);
    if (row) row.wallets.push(wallet);
  }
  for (const trade of tradeHistory.trades || []) {
    if (!trade || !["buy", "sell"].includes(String(trade.type || "").toLowerCase())) continue;
    const row = ensureRow(trade.userId);
    if (row) row.trades.push(trade);
  }
  // Robinhood (0x) trades live outside trade-history.json; fold them into the SAME rows so profile trade
  // counts reflect BOTH chains. Merge the durable store with recent audit-log mirrors (dedupe by tx hash)
  // and drop volume-bot churn so only real user buys/sells are counted.
  const rhBySig = new Map();
  for (const t of rhHistory.trades || []) {
    if (!t || !["buy", "sell"].includes(String(t.type || "").toLowerCase())) continue;
    if (String(t.source || "") === "rh_volume") continue;
    const sig = String(t.signature || "") || `${t.userId}:${t.timestamp}`;
    rhBySig.set(sig, { userId: t.userId, type: t.type, timestamp: t.timestamp, walletPublicKey: t.walletPublicKey || "", solLamportsSpent: t.solLamportsSpent, chain: "robinhood" });
  }
  for (const entry of auditLog.entries || []) {
    if (!entry || entry.action !== "web_rh_trade") continue;
    const d = entry.details || {};
    if (String(d.source || "") === "rh_volume") continue;
    if (!["buy", "sell"].includes(String(d.side || "").toLowerCase())) continue;
    const sig = String((Array.isArray(d.txHashes) ? d.txHashes[d.txHashes.length - 1] : "") || "") || `${d.userId}:${entry.timestamp}`;
    if (rhBySig.has(sig)) continue;
    rhBySig.set(sig, { userId: d.userId, type: d.side, timestamp: entry.timestamp, walletPublicKey: d.wallet || "", solLamportsSpent: d.solFunding ? String(solToLamports(Number(d.solFunding.amountSol) || 0)) : undefined, chain: "robinhood" });
  }
  for (const t of rhBySig.values()) {
    const row = ensureRow(t.userId);
    if (row) row.trades.push(t);
  }
  for (const session of auth.sessions || []) {
    const row = ensureRow(session?.userId);
    if (row) row.sessions.push(session);
  }
  for (const [childId, profile] of Object.entries(profiles)) {
    const referrerId = String(profile?.referredByUserId || "");
    if (!referrerId || referrerId === childId || !profiles[referrerId]) continue;
    const row = ensureRow(referrerId);
    if (row) row.referrals.push({ profileId: childId, createdAt: profile?.createdAt || "" });
  }

  const resultRows = [];
  for (const row of rows.values()) {
    const profile = profiles[row.profileId || row.key] || {};
    if (!row.telegramUserId && links[row.profileId || row.key]) {
      const linked = links[row.profileId || row.key];
      row.telegramUserId = String(linked?.telegramUserId || linked?.userId || linked || "");
    }
    const telegramUser = directByTelegramId.get(row.telegramUserId || (/^\d+$/.test(row.key) ? row.key : "")) || {};
    const identity = ownerAnalyticsDisplayName(profile, telegramUser);
    const periodTrades = row.trades.filter((trade) => ownerAnalyticsTimestamp(trade, "timestamp", "tradedAt", "createdAt") >= sinceMs);
    const periodWallets = row.wallets.filter((wallet) => ownerAnalyticsTimestamp(wallet, "createdAt") >= sinceMs);
    const periodReferrals = row.referrals.filter((referral) => ownerAnalyticsTimestamp(referral, "createdAt") >= sinceMs);
    let buys = 0, sells = 0, volume = 0n;
    const tradedWallets = new Set();
    for (const trade of periodTrades) {
      if (String(trade.type || "").toLowerCase() === "buy") buys += 1; else sells += 1;
      volume += positiveBigIntOrZero(trade.solLamportsSpent) + positiveBigIntOrZero(trade.solLamportsReceived);
      const wallet = String(trade.walletPublicKey || trade.wallet || "");
      if (wallet) tradedWallets.add(wallet);
    }
    const allTimes = [
      ownerAnalyticsTimestamp(profile, "createdAt", "updatedAt"),
      ownerAnalyticsTimestamp(telegramUser, "lastSeenAt", "firstSeenAt"),
      ...row.wallets.map((wallet) => ownerAnalyticsTimestamp(wallet, "createdAt")),
      ...row.trades.map((trade) => ownerAnalyticsTimestamp(trade, "timestamp", "tradedAt", "createdAt")),
      ...row.sessions.map((session) => ownerAnalyticsTimestamp(session, "lastUsedAt", "createdAt"))
    ].filter(Boolean);
    const creationTimes = [
      ownerAnalyticsTimestamp(profile, "createdAt"),
      ownerAnalyticsTimestamp(telegramUser, "firstSeenAt"),
      ...row.wallets.map((wallet) => ownerAnalyticsTimestamp(wallet, "createdAt"))
    ].filter(Boolean);
    const createdAtMs = creationTimes.length ? Math.min(...creationTimes) : 0;
    const directActiveAt = ownerAnalyticsTimestamp(telegramUser, "lastSeenAt", "firstSeenAt");
    const webActiveAt = Math.max(0, ...row.sessions.map((session) => ownerAnalyticsTimestamp(session, "lastUsedAt", "createdAt")));
    const matchesPeriod = !sinceMs || periodTrades.length || periodWallets.length || periodReferrals.length || directActiveAt >= sinceMs || webActiveAt >= sinceMs || createdAtMs >= sinceMs;
    if (!matchesPeriod) continue;
    const web = Boolean(row.profileId || profiles[row.key]);
    const telegram = Boolean(telegramUser.telegramUserId || row.telegramUserId);
    const referredActive = row.referrals.filter((referral) => {
      const child = rows.get(canonicalId(referral.profileId));
      return child?.trades?.some((trade) => ownerAnalyticsTimestamp(trade, "timestamp", "tradedAt", "createdAt") >= sinceMs);
    }).length;
    resultRows.push({
      name: identity.name,
      hasRealName: identity.hasRealName,
      channel: web && telegram ? "Linked" : web ? "Web" : "Telegram",
      telegramUsername: telegramUser.username ? `@${String(telegramUser.username).replace(/^@+/, "")}` : "",
      wallets: periodWallets.length,
      totalWallets: row.wallets.length,
      tradedWallets: tradedWallets.size,
      trades: periodTrades.length,
      buys,
      sells,
      volumeLamports: volume.toString(),
      volumeSol: referralSolString(volume),
      referrals: periodReferrals.length,
      activeReferrals: referredActive,
      referralEarnedSol: referralSolString(positiveBigIntOrZero(profile?.referralStats?.totalLamports)),
      createdAt: createdAtMs ? new Date(createdAtMs).toISOString() : "",
      lastActiveAt: allTimes.length ? new Date(Math.max(...allTimes)).toISOString() : ""
    });
  }
  resultRows.sort((a, b) => BigInt(b.volumeLamports) > BigInt(a.volumeLamports) ? 1
    : BigInt(b.volumeLamports) < BigInt(a.volumeLamports) ? -1
      : b.trades - a.trades || b.referrals - a.referrals || a.name.localeCompare(b.name));
  const namedResultRows = resultRows.filter((row) => row.hasRealName);
  const namedVolume = namedResultRows.reduce((sum, row) => sum + positiveBigIntOrZero(row.volumeLamports), 0n);
  const referralRows = namedResultRows.filter((row) => row.referrals || row.activeReferrals || Number(row.referralEarnedSol) > 0)
    .sort((a, b) => b.referrals - a.referrals || b.activeReferrals - a.activeReferrals || Number(b.referralEarnedSol) - Number(a.referralEarnedSol));
  return {
    ok: true,
    generatedAt: new Date().toISOString(),
    period: selectedPeriod,
    summary: {
      directTelegramUsers: namedResultRows.filter((row) => row.channel === "Telegram" || row.channel === "Linked").length,
      webAccounts: namedResultRows.filter((row) => row.channel === "Web" || row.channel === "Linked").length,
      linkedAccounts: namedResultRows.filter((row) => row.channel === "Linked").length,
      wallets: namedResultRows.reduce((sum, row) => sum + row.wallets, 0),
      telegramWallets: namedResultRows.filter((row) => row.channel === "Telegram").reduce((sum, row) => sum + row.wallets, 0),
      webWallets: namedResultRows.filter((row) => row.channel !== "Telegram").reduce((sum, row) => sum + row.wallets, 0),
      activeTraders: namedResultRows.filter((row) => row.trades > 0).length,
      trades: namedResultRows.reduce((sum, row) => sum + row.trades, 0),
      buys: namedResultRows.reduce((sum, row) => sum + row.buys, 0),
      sells: namedResultRows.reduce((sum, row) => sum + row.sells, 0),
      volumeSol: referralSolString(namedVolume),
      referrals: namedResultRows.reduce((sum, row) => sum + row.referrals, 0),
      activeReferrals: namedResultRows.reduce((sum, row) => sum + row.activeReferrals, 0),
      namedProfiles: namedResultRows.length,
      groups: Object.keys(tgGroups.groups || {}).length
    },
    users: namedResultRows.slice(0, 500),
    referrals: referralRows.slice(0, 200),
    groups: Object.entries(tgGroups.groups || {}).map(([chatId, g]) => {
      const roster = (groupMentions.groups && groupMentions.groups[chatId] && groupMentions.groups[chatId].members) || {};
      return {
        chatId: String(chatId),
        title: String((g && g.title) || "").slice(0, 80) || "Untitled group",
        knownMembers: Object.keys(roster).length,
        addedAt: (g && g.addedAt) || ""
      };
    }).sort((a, b) => b.knownMembers - a.knownMembers).slice(0, 300)
  };
}

function growthDateCount(rows, field, sinceMs) {
  return rows.filter((row) => {
    const at = Date.parse(row?.[field] || "");
    return at > 0 && at >= sinceMs;
  }).length;
}

// A created wallet is not the same thing as an activated trader. These counts use
// only successfully-recorded buy/sell events, never a panel open, quote, or failed order.
function tradeUsageStats(trades, sinceMs = 0) {
  const wallets = new Set();
  const users = new Set();
  let executedTrades = 0;
  for (const trade of Array.isArray(trades) ? trades : []) {
    if (!trade || !["buy", "sell"].includes(String(trade.type || "").toLowerCase())) continue;
    const at = Date.parse(trade.timestamp || trade.tradedAt || trade.createdAt || "");
    if (sinceMs && (!at || at < sinceMs)) continue;
    const wallet = String(trade.walletPublicKey || trade.wallet || "").trim();
    if (wallet) wallets.add(wallet);
    const userId = String(trade.userId || "").trim();
    if (userId && !userId.startsWith("__")) users.add(userId);
    executedTrades += 1;
  }
  return { wallets: wallets.size, users: users.size, trades: executedTrades };
}

function countTradedWallets(trades, sinceMs = 0) {
  return tradeUsageStats(trades, sinceMs).wallets;
}

async function platformGrowthSnapshot() {
  const now = Date.now(), today = new Date().toISOString().slice(0, 10);
  const todayStart = Date.parse(`${today}T00:00:00.000Z`), weekStart = now - 7 * 24 * 60 * 60 * 1000;
  const [auth, walletStore, telegramGroups, launches, growth, tradeHistory] = await Promise.all([
    readWebAuthStore(), readWalletStore(), readTelegramGroups(), readLaunchOs(), readGrowthStats(), readTradeHistory()
  ]);
  const profiles = Object.values(auth.profiles || {}), wallets = (walletStore.wallets || []).filter((row) => {
    const owner = String(row?.ownerId || "");
    return owner && !owner.startsWith("__");
  });
  const groups = Object.values(telegramGroups.groups || {}), sites = Object.values(launches.projects || {});
  const knownTelegram = new Set(Object.keys(growth.directTelegramUsers || {}));
  const todayGrowth = growth.days?.[today] || {}, recentDays = Object.entries(growth.days || {}).filter(([day]) => Date.parse(`${day}T00:00:00.000Z`) >= weekStart);
  const activeWeek = new Set();
  for (const [, row] of recentDays) for (const hash of Object.keys(row?.telegramDirectActive || {})) activeWeek.add(hash);
  const activeWebToday = new Set((auth.sessions || []).filter((row) => Date.parse(row.lastUsedAt || row.createdAt || "") >= todayStart).map((row) => String(row.userId))).size;
  const tradeUsage = {
    today: tradeUsageStats(tradeHistory.trades, todayStart),
    week: tradeUsageStats(tradeHistory.trades, weekStart),
    total: tradeUsageStats(tradeHistory.trades)
  };
  const referralCounts = new Map();
  for (const [profileId, profile] of Object.entries(auth.profiles || {})) {
    const referrerId = String(profile?.referredByUserId || "");
    if (referrerId && referrerId !== profileId && auth.profiles?.[referrerId]) {
      referralCounts.set(referrerId, Number(referralCounts.get(referrerId) || 0) + 1);
    }
  }
  const profileTradeTotals = new Map();
  for (const trade of tradeHistory.trades || []) {
    if (!trade || !["buy", "sell"].includes(String(trade.type || "").toLowerCase())) continue;
    const profileId = String(trade.userId || "");
    if (!profileId || !auth.profiles?.[profileId]) continue;
    const current = profileTradeTotals.get(profileId) || { trades: 0, volume: 0n, wallets: new Set() };
    current.trades += 1;
    current.volume += positiveBigIntOrZero(trade.solLamportsSpent) + positiveBigIntOrZero(trade.solLamportsReceived);
    const wallet = String(trade.walletPublicKey || trade.wallet || "").trim();
    if (wallet) current.wallets.add(wallet);
    profileTradeTotals.set(profileId, current);
  }
  const profileRows = Object.entries(auth.profiles || {}).map(([profileId, profile]) => {
    const totals = profileTradeTotals.get(profileId) || { trades: 0, volume: 0n, wallets: new Set() };
    const rawName = String(profile?.username || profile?.cashHandleDisplay || profile?.cashHandle || "").trim();
    return {
      name: rawName || `profile-${shortMint(profileId)}`,
      trades: totals.trades,
      tradedWallets: totals.wallets.size,
      volumeLamports: totals.volume,
      volumeSol: referralSolString(totals.volume),
      referrals: Number(referralCounts.get(profileId) || 0)
    };
  }).sort((a, b) => Number(b.volumeLamports - a.volumeLamports) || b.trades - a.trades || b.referrals - a.referrals || a.name.localeCompare(b.name));
  return {
    today: {
      webAccounts: growthDateCount(profiles, "createdAt", todayStart), webActive: activeWebToday,
      telegramNew: Number(todayGrowth.telegramDirectNew || 0), telegramActive: Object.keys(todayGrowth.telegramDirectActive || {}).length,
      wallets: growthDateCount(wallets, "createdAt", todayStart), tradedWallets: tradeUsage.today.wallets,
      tradingUsers: tradeUsage.today.users, executedTrades: tradeUsage.today.trades,
      groups: growthDateCount(groups, "addedAt", todayStart), sites: growthDateCount(sites, "createdAt", todayStart)
    },
    week: {
      webAccounts: growthDateCount(profiles, "createdAt", weekStart), telegramNew: recentDays.reduce((sum, [, row]) => sum + Number(row?.telegramDirectNew || 0), 0),
      telegramActive: activeWeek.size, wallets: growthDateCount(wallets, "createdAt", weekStart), tradedWallets: tradeUsage.week.wallets,
      tradingUsers: tradeUsage.week.users, executedTrades: tradeUsage.week.trades,
      groups: growthDateCount(groups, "addedAt", weekStart), sites: growthDateCount(sites, "createdAt", weekStart)
    },
    total: {
      webAccounts: profiles.length, telegramKnown: knownTelegram.size, wallets: wallets.length,
      tradedWallets: tradeUsage.total.wallets, tradingUsers: tradeUsage.total.users, executedTrades: tradeUsage.total.trades,
      groups: groups.length, sites: sites.length
    },
    profileRows
  };
}

