function launchOsArtIdentity(token = {}) {
  const symbol = String(token.symbol || "COIN").replace(/^\$+/, "").slice(0, 14);
  const name = String(token.name || symbol).slice(0, 48);
  const digest = crypto.createHash("sha256").update(String(token.ca || `${name}:${symbol}`)).digest();
  const hue = digest[0] % 360;
  const accent = `hsl(${hue} 92% 56%)`;
  const accent2 = `hsl(${(hue + 72 + digest[1] % 80) % 360} 88% 58%)`;
  const xml = (value) => String(value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" }[char]));
  return { symbol, name, accent, accent2, xml };
}

function launchOsFallbackArtData(token = {}, square = false) {
  const { symbol, name, accent, accent2, xml } = launchOsArtIdentity(token);
  const width = square ? 1200 : 1800, height = square ? 1200 : 1000;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><defs><radialGradient id="g" cx="68%" cy="35%"><stop stop-color="${accent}" stop-opacity=".72"/><stop offset=".48" stop-color="${accent2}" stop-opacity=".22"/><stop offset="1" stop-color="#050705"/></radialGradient><filter id="b"><feGaussianBlur stdDeviation="46"/></filter></defs><rect width="100%" height="100%" fill="#050705"/><rect width="100%" height="100%" fill="url(#g)"/><circle cx="${square ? 850 : 1320}" cy="${square ? 350 : 350}" r="310" fill="none" stroke="${accent}" stroke-opacity=".42" stroke-width="3"/><circle cx="${square ? 850 : 1320}" cy="${square ? 350 : 350}" r="220" fill="${accent2}" fill-opacity=".16" filter="url(#b)"/><path d="M-40 ${height * .78} Q ${width * .28} ${height * .42} ${width * .55} ${height * .74} T ${width + 40} ${height * .48}" fill="none" stroke="${accent}" stroke-opacity=".28" stroke-width="4"/><text x="${square ? 72 : 105}" y="${square ? 865 : 720}" fill="#fff" fill-opacity=".11" font-family="Arial Black,Arial" font-size="${square ? 190 : 250}" font-weight="900">$${xml(symbol)}</text><text x="${square ? 78 : 115}" y="${square ? 1010 : 860}" fill="#fff" fill-opacity=".72" font-family="Arial, sans-serif" font-size="${square ? 48 : 56}" font-weight="700" letter-spacing="8">${xml(name.toUpperCase())}</text></svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

async function generateLaunchOsFreeMedia(project, sourceBuffer) {
  const dir = path.join(launchOsMediaDir(), project.slug);
  await fs.mkdir(dir, { recursive: true });
  const heroBase = Buffer.from(decodeURIComponent(launchOsFallbackArtData(project.token).split(",")[1]));
  const galleryBase = Buffer.from(decodeURIComponent(launchOsFallbackArtData(project.token, true).split(",")[1]));
  const stamp = `${Date.now()}-${crypto.randomBytes(3).toString("hex")}`;
  const composites = [];
  let mascot = null;
  if (sourceBuffer) {
    const mask = Buffer.from('<svg width="760" height="760"><rect width="760" height="760" rx="110" fill="white"/></svg>');
    mascot = await sharp(sourceBuffer).rotate().resize(760, 760, { fit: "cover", position: "attention" }).composite([{ input: mask, blend: "dest-in" }]).png().toBuffer();
    composites.push({ input: mascot, left: 930, top: 120 });
  }
  const hero = await sharp(heroBase).composite(composites).png({ quality: 92 }).toBuffer();
  const gallery = await sharp(galleryBase).composite(mascot ? [{ input: await sharp(mascot).resize(820, 820).png().toBuffer(), left: 190, top: 110 }] : []).png({ quality: 92 }).toBuffer();
  const heroName = `free-hero-${stamp}.png`, galleryName = `free-gallery-${stamp}.png`;
  await Promise.all([fs.writeFile(path.join(dir, heroName), hero), fs.writeFile(path.join(dir, galleryName), gallery)]);
  const heroUrl = `/api/launch-os/media/${encodeURIComponent(project.slug)}/${encodeURIComponent(heroName)}`;
  const galleryUrl = `/api/launch-os/media/${encodeURIComponent(project.slug)}/${encodeURIComponent(galleryName)}`;
  await mutateLaunchOs((store) => {
    const saved = store.projects[project.id]; if (!saved) return;
    saved.site = saved.site || launchOsDefaultSite(saved.token, saved.publicUrl, saved.mode);
    saved.site.media = saved.site.media || { pfp: "", hero: "", gallery: [] };
    saved.site.media.hero = heroUrl;
    saved.site.media.gallery = [galleryUrl, ...(saved.site.media.gallery || []).filter((item) => item !== galleryUrl)].slice(0, 12);
    saved.site.freeArtGenerated = true;
    saved.updatedAt = new Date().toISOString();
  });
  return { heroUrl, galleryUrl };
}

async function launchOsTrustedTokenImageBuffer(value) {
  let parsed;
  try { parsed = new URL(String(value || "")); } catch { return null; }
  if (parsed.protocol !== "https:") return null;
  const host = parsed.hostname.toLowerCase();
  const ownMediaHost = (() => { try { return new URL(String(CONFIG.xDmRedirectOrigin || "https://ogrevolbot.onrender.com")).hostname.toLowerCase(); } catch { return "ogrevolbot.onrender.com"; } })();
  const allowed = ["dexscreener.com", "arweave.net", "ipfs.io", "cf-ipfs.com", "pinata.cloud", "filebase.io", "pbs.twimg.com", ownMediaHost];
  if (!allowed.some((domain) => host === domain || host.endsWith(`.${domain}`))) return null;
  const response = await fetch(parsed.href, { headers: { Accept: "image/png,image/jpeg,image/webp,image/*" }, signal: AbortSignal.timeout(8_000) }).catch(() => null);
  if (!response?.ok) return null;
  const declared = Number(response.headers.get("content-length")) || 0;
  if (declared > 8_000_000) return null;
  const buffer = Buffer.from(await response.arrayBuffer());
  if (buffer.length < 200 || buffer.length > 8_000_000) return null;
  await sharp(buffer).metadata();
  return buffer;
}

function assertLaunchOsCreateAllowed(request) {
  const key = webClientKey(request);
  const now = Date.now();
  const windowMs = 60 * 60 * 1000;
  const record = launchOsCreateLimits.get(key) || { count: 0, resetAt: now + windowMs };
  if (record.resetAt <= now) { record.count = 0; record.resetAt = now + windowMs; }
  record.count += 1;
  launchOsCreateLimits.set(key, record);
  if (launchOsCreateLimits.size > 5_000) {
    for (const [client, row] of launchOsCreateLimits) if (row.resetAt <= now) launchOsCreateLimits.delete(client);
  }
  if (record.count > 12) throw Object.assign(new Error("Too many Launch Passports created. Wait a little and try again."), { statusCode: 429 });
}

function launchOsEditorKeyFromRequest(request) {
  const value = request.headers["x-launch-edit-key"];
  return Array.isArray(value) ? String(value[0] || "") : String(value || "");
}

function launchOsEditorMatches(project, editKey) {
  if (!project?.editorKeyHash || !/^[a-f0-9]{48}$/i.test(String(editKey || ""))) return false;
  return constantTimeStringEquals(project.editorKeyHash, hashWebSecret(String(editKey)));
}

async function requireLaunchOsEditor(slug, editKey) {
  const project = await launchOsProjectBySlug(slug);
  if (!launchOsEditorMatches(project, editKey)) throw Object.assign(new Error("Private edit link is invalid or incomplete."), { statusCode: 404 });
  return project;
}

function launchOsSetupUrl(project) {
  const base = telegramStartGroupLink(`launchos_${project.setupCode}`);
  return base ? `${base}&admin=change_info+delete_messages+restrict_members+invite_users+pin_messages+manage_video_chats` : "";
}

function launchOsDefaultContent(token, publicUrl) {
  const symbol = String(token.symbol || "COIN").replace(/^\$+/, "");
  return {
    launchPost: `Meet $${symbol}.\n\nCA: ${token.ca}\n\nLive chart, safety read and community tools: ${publicUrl}`,
    pinnedPost: `$${symbol} official launch hub\n\nCA: ${token.ca}\nWebsite: ${publicUrl}\n\nVerify every link and never share a seed phrase.`,
    telegramWelcome: `Welcome to the $${symbol} community. Verify the CA before trading: ${token.ca}`,
    milestonePost: `$${symbol} just crossed a new community milestone. Track the live market and holders: ${publicUrl}`,
    emergencyPost: `SECURITY NOTICE for $${symbol}: use only the verified links at ${publicUrl}. Do not trust DMs or send funds to unlisted addresses.`,
  };
}

function launchOsDefaultSite(token, publicUrl, mode = "official") {
  const symbol = String(token.symbol || "COIN").replace(/^\$+/, "");
  const chain = token.chain === "robinhood" ? "Robinhood Chain" : "Solana";
  const description = launchOsCleanText(token.description || `${token.name} is a community-powered memecoin built on ${chain}.`, 1800);
  return {
    engine: "slimewire-site-engine-v2", generatedAt: new Date().toISOString(),
    template: "signature", accent: "#b7ff00", prompt: "", headline: `${token.name}. Built to own the timeline.`,
    subhead: `${mode === "cto" ? "The community takeover" : "The official home"} of $${symbol} on ${chain}—live market intelligence, verified links and the full story in one world.`,
    lore: `${description}\n\n$${symbol} is built around a simple idea: make the identity unmistakable, keep the contract verifiable and give the community one home for every official link and market signal.`.slice(0, 2400),
    roadmap: ["Launch the signal", "Grow the community", "Take over the timeline"],
    sections: { market: true, lore: true, gallery: true, howToBuy: true, roadmap: true, socials: true, memeMaker: true },
    media: {
      pfp: token.imageUrl || launchOsFallbackArtData(token, true),
      hero: token.imageUrl || launchOsFallbackArtData(token),
      mobileHero: token.imageUrl || launchOsFallbackArtData(token, true),
      gallery: token.imageUrl ? [token.imageUrl] : []
    }, publicUrl
  };
}

function launchOsCreativeCopy(token, direction = "", mode = "official") {
  const name = String(token.name || token.symbol || "This coin");
  const symbol = String(token.symbol || "COIN").replace(/^\$+/, "");
  const chain = token.chain === "robinhood" ? "Robinhood Chain" : "Solana";
  const cue = String(direction || "").toLowerCase();
  const voice = /luxury|premium|clean|editorial|fashion/.test(cue) ? "premium"
    : /cute|fun|friendly|cartoon/.test(cue) ? "playful"
    : /cyber|neon|future|tech/.test(cue) ? "future"
    : /rebel|menace|chaos|wild|dark|degen/.test(cue) ? "rebel" : "signal";
  const headlines = {
    premium: `${name}. The new standard.`, playful: `${name}. Cute face. Serious signal.`,
    future: `${name}. Signal from the future.`, rebel: `${name}. Not here to behave.`,
    signal: `${name}. Built to own the timeline.`
  };
  const descriptions = {
    premium: `A refined home for $${symbol} on ${chain}—live markets, verified links and a brand designed to feel established from day one.`,
    playful: `$${symbol} brings a recognizable character and an easy-to-join community to ${chain}, backed by live data and verified links.`,
    future: `$${symbol} is a live community signal on ${chain}: real-time market intelligence, verified links and a world built around the token.`,
    rebel: `$${symbol} is the ${chain} outsider built to take over feeds, rally the community and keep every official signal in one place.`,
    signal: `${mode === "cto" ? "The community takeover" : "The official home"} of $${symbol} on ${chain}—live market intelligence, verified links and the full story in one world.`
  };
  return { headline: headlines[voice], subhead: descriptions[voice], voice };
}

async function launchOsGenerateStructuredCopy(project) {
  const direction = launchOsCleanText(project.site?.prompt || "", 700);
  const promptHash = hashWebSecret(JSON.stringify({ ca: project.token?.ca, direction, mode: project.mode })).slice(0, 24);
  if (project.site?.copyPromptHash === promptHash) return project;
  let generated = null;
  let textProvider = "local";
  const apiKey = String(process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY || "").trim();
  if (apiKey) {
    const model = String(process.env.GEMINI_SITE_TEXT_MODEL || "gemini-flash-lite-latest").trim();
    const requestPrompt = [
      "Create an original professional memecoin website content system. Return JSON only.",
      `Token: ${project.token?.name} ($${project.token?.symbol})`, `Chain: ${project.token?.chain}`, `CA: ${project.token?.ca}`,
      `Existing metadata: ${project.token?.description || "none"}`, `Creative direction: ${direction || "premium, memorable and community-first"}`,
      "Write distinctive copy grounded only in these inputs. Do not invent partnerships, utility, returns, audits or guarantees.",
      "Headline maximum 9 words. Subhead maximum 32 words. Lore 2-4 short paragraphs. Roadmap exactly 3 concise phases.",
      "Also create desktop, mobile and square image prompts that preserve the supplied mascot, contain no text, and reserve safe space for HTML copy."
    ].join("\n");
    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`, {
      method: "POST", headers: { "x-goog-api-key": apiKey, "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ role: "user", parts: [{ text: requestPrompt }] }],
        generationConfig: {
          temperature: 0.9, responseMimeType: "application/json",
          responseSchema: { type: "OBJECT", required: ["headline", "subhead", "lore", "roadmap", "heroPromptDesktop", "heroPromptMobile", "galleryPrompt"], properties: {
            headline: { type: "STRING" }, subhead: { type: "STRING" }, lore: { type: "STRING" },
            roadmap: { type: "ARRAY", items: { type: "STRING" }, minItems: 3, maxItems: 3 },
            heroPromptDesktop: { type: "STRING" }, heroPromptMobile: { type: "STRING" }, galleryPrompt: { type: "STRING" },
            accent: { type: "STRING" }
          } }
        }
      }), signal: AbortSignal.timeout ? AbortSignal.timeout(25_000) : undefined
    }).catch(() => null);
    if (response?.ok) {
      const data = await response.json().catch(() => ({}));
      const text = (data?.candidates || []).flatMap((candidate) => candidate?.content?.parts || []).map((part) => part?.text || "").join("");
      try { generated = JSON.parse(text); textProvider = model; } catch { generated = null; }
    }
  }
  const fallback = launchOsCreativeCopy(project.token, direction, project.mode);
  return mutateLaunchOs((store) => {
    const saved = store.projects[project.id]; if (!saved) return project;
    saved.site = saved.site || launchOsDefaultSite(saved.token, saved.publicUrl, saved.mode);
    saved.site.headline = launchOsCleanText(generated?.headline || fallback.headline, 140);
    saved.site.subhead = launchOsCleanText(generated?.subhead || fallback.subhead, 360);
    if (generated?.lore) saved.site.lore = launchOsCleanText(generated.lore, 2400);
    if (Array.isArray(generated?.roadmap)) saved.site.roadmap = generated.roadmap.slice(0, 3).map((item) => launchOsCleanText(item, 180)).filter(Boolean);
    saved.site.artPrompts = {
      desktop: launchOsCleanText(generated?.heroPromptDesktop || direction, 900),
      mobile: launchOsCleanText(generated?.heroPromptMobile || direction, 900),
      gallery: launchOsCleanText(generated?.galleryPrompt || direction, 900)
    };
    if (/^#[0-9a-f]{6}$/i.test(String(generated?.accent || ""))) saved.site.accent = generated.accent;
    saved.site.copyVoice = generated ? "gemini" : fallback.voice;
    saved.site.textProvider = generated ? textProvider : "local";
    saved.site.copyPromptHash = promptHash;
    saved.updatedAt = new Date().toISOString();
    return clientLaunchOsProject(saved);
  });
}

function launchOsSiteForClient(project) {
  const defaults = launchOsDefaultSite(project.token, project.publicUrl, project.mode);
  const site = project.site && typeof project.site === "object" ? project.site : {};
  const media = site.media && typeof site.media === "object" ? site.media : {};
  const legacyPfp = /\/assets\/slimewire\/png\/slimewire-mark\.png$/i.test(String(media.pfp || "")) ? "" : media.pfp;
  const legacyHero = /\/assets\/slimewire\/launch\/hero\.png$/i.test(String(media.hero || "")) ? "" : media.hero;
  const publicMedia = (value) => String(value || "").startsWith("/api/launch-os/media/")
    ? `${String(CONFIG.xDmRedirectOrigin || "https://ogrevolbot.onrender.com").replace(/\/+$/, "")}${value}`
    : value;
  return {
    ...defaults, ...site,
    sections: { ...defaults.sections, ...(site.sections || {}) },
    media: {
      ...defaults.media, ...media,
      pfp: publicMedia(firstString(legacyPfp, project.token?.imageUrl, defaults.media.pfp)),
      hero: publicMedia(firstString(legacyHero, project.token?.imageUrl, defaults.media.hero)),
      mobileHero: publicMedia(firstString(media.mobileHero, project.token?.imageUrl, defaults.media.mobileHero)),
      gallery: (Array.isArray(media.gallery) ? media.gallery.filter(Boolean).slice(0, 12) : defaults.media.gallery).map(publicMedia)
    }
  };
}

async function saveLaunchOsMedia(project, body = {}) {
  const src = decodePfpImageDataUrl(body.dataUrl);
  if (!src) throw Object.assign(new Error("Use a PNG, JPG or WebP image under 8MB."), { statusCode: 400 });
  const kind = ["pfp", "hero", "mobileHero", "gallery"].includes(String(body.kind)) ? String(body.kind) : "gallery";
  const dir = path.join(launchOsMediaDir(), project.slug);
  await fs.mkdir(dir, { recursive: true });
  const name = `${kind}-${Date.now()}-${crypto.randomBytes(3).toString("hex")}.png`;
  const width = kind === "hero" ? 1800 : kind === "mobileHero" ? 900 : 1200;
  const height = kind === "hero" ? 1000 : kind === "mobileHero" ? 1200 : 1200;
  const output = await sharp(src).rotate().resize(width, height, { fit: "cover", position: "attention" }).png({ quality: 92 }).toBuffer();
  await fs.writeFile(path.join(dir, name), output);
  const url = `/api/launch-os/media/${encodeURIComponent(project.slug)}/${encodeURIComponent(name)}`;
  await mutateLaunchOs((store) => {
    const saved = store.projects[project.id]; if (!saved) return;
    saved.site = saved.site || launchOsDefaultSite(saved.token, saved.publicUrl, saved.mode);
    saved.site.media = saved.site.media || { pfp: "", hero: "", gallery: [] };
    if (kind === "gallery") {
      const gallery = [...(saved.site.media.gallery || [])];
      const galleryIndex = Number(body.galleryIndex);
      if (Number.isInteger(galleryIndex) && galleryIndex >= 0 && galleryIndex < gallery.length) gallery[galleryIndex] = url;
      else gallery.push(url);
      saved.site.media.gallery = gallery.slice(-12);
    }
    else saved.site.media[kind] = url;
    saved.updatedAt = new Date().toISOString();
  });
  if (kind === "pfp") {
    try { await generateLaunchOsFreeMedia(project, src); }
    catch (error) {
      console.warn(`[site-maker] uploaded PFP saved but free art composition failed: ${friendlyError(error)}`);
      await generateLaunchOsFreeMedia(project, null);
    }
  }
  return { url, kind, project: clientLaunchOsProject(await getLaunchOsProjectForUser(project.userId, project.id).catch(async () => (await readLaunchOs()).projects[project.id])) };
}

function launchOsReadiness(project) {
  const links = project.links || {};
  const groups = Array.isArray(project.telegram?.groups) ? project.telegram.groups : [];
  const steps = [
    { id: "identity", label: "Token identity", done: Boolean(project.token?.ca && project.token?.symbol), detail: "Name, ticker, CA and chain" },
    { id: "brand", label: "Brand kit", done: Boolean(project.token?.imageUrl && project.brand?.tagline), detail: "PFP, banner direction and tagline" },
    { id: "story", label: "Story", done: Boolean(project.brand?.description), detail: "Description and community voice" },
    { id: "site", label: "Launch HQ", done: Boolean(project.publicUrl), detail: "Public SlimeWire project page" },
    { id: "telegram", label: "Telegram", done: groups.length > 0, detail: groups.length ? `${groups.length} group${groups.length === 1 ? "" : "s"} configured` : "Add the bot to a group" },
    { id: "x", label: "X account", done: Boolean(links.x), detail: links.x ? "Profile linked" : "Create or connect an existing account" },
    { id: "links", label: "Official links", done: Boolean(links.x && (links.telegram || groups.length) && (links.website || project.publicUrl)), detail: "X, Telegram and website are consistent" },
    { id: "trust", label: project.mode === "official" ? "Official claim" : "CTO disclosure", done: project.mode !== "official" || Boolean(project.officialClaim), detail: project.mode === "official" ? "Optional deployer-wallet signature" : "Clearly marked community takeover" },
    { id: "content", label: "Launch content", done: Boolean(project.content?.launchPost && project.content?.pinnedPost), detail: "Launch, pinned and emergency copy" },
  ];
  const complete = steps.filter((step) => step.done).length;
  return { score: Math.round((complete / steps.length) * 100), complete, total: steps.length, steps };
}

function launchOsLinkAudit(project) {
  const rows = [
    ["X", project.links?.x], ["Telegram", project.links?.telegram], ["Website", project.links?.website || project.publicUrl],
    ["Discord", project.links?.discord], ["Farcaster", project.links?.farcaster]
  ];
  return rows.filter(([, value]) => value).map(([label, value]) => ({
    label, url: socialKitPublicUrl(value), ok: Boolean(socialKitPublicUrl(value)),
    note: socialKitPublicUrl(value) ? "Valid HTTPS destination" : "Invalid or unsafe URL"
  }));
}

function clientLaunchOsProject(project) {
  if (!project) return null;
  const sourcePayment = project.payment || { status: "unlocked", waived: true, legacy: true, priceUsd: COIN_SITE_PRICE_USD, priceSol: 0, depositAddress: "" };
  const payment = {
    status: sourcePayment.status === "awaiting_payment" ? "awaiting_payment" : "unlocked",
    waived: Boolean(sourcePayment.waived), legacy: Boolean(sourcePayment.legacy),
    priceUsd: Number(sourcePayment.priceUsd || COIN_SITE_PRICE_USD), priceSol: Number(sourcePayment.priceSol || 0),
    depositAddress: String(sourcePayment.depositAddress || ""), paidAt: sourcePayment.paidAt || ""
  };
  return {
    id: project.id, slug: project.slug, mode: project.mode, publicUrl: project.publicUrl,
    token: project.token, brand: project.brand, links: project.links, content: project.content, site: launchOsSiteForClient(project),
    payment, published: payment.status === "unlocked",
    listing: project.listing || {}, crisis: project.crisis || { active: false, message: "" },
    officialClaim: Boolean(project.officialClaim), telegram: project.telegram || { groups: [] },
    partner: project.partner || { enabled: false, status: "not_configured", payoutWallet: "" },
    telegramSetupUrl: launchOsSetupUrl(project), readiness: launchOsReadiness(project),
    linkAudit: launchOsLinkAudit(project), createdAt: project.createdAt, updatedAt: project.updatedAt
  };
}

function publicLaunchOsProject(project) {
  const value = clientLaunchOsProject(project);
  if (!value) return null;
  delete value.telegramSetupUrl;
  value.telegram = { groupCount: Array.isArray(project.telegram?.groups) ? project.telegram.groups.length : 0 };
  return value;
}

async function launchOsProjectsForUser(userId) {
  const store = await readLaunchOs();
  return Object.values(store.projects).filter((project) => String(project.userId) === String(userId))
    .sort((a, b) => Date.parse(b.updatedAt || b.createdAt || 0) - Date.parse(a.updatedAt || a.createdAt || 0))
    .map(clientLaunchOsProject);
}

async function getLaunchOsProjectForUser(userId, id) {
  const project = (await readLaunchOs()).projects[String(id || "")];
  if (!project || String(project.userId) !== String(userId)) throw Object.assign(new Error("Launch OS project not found."), { statusCode: 404 });
  return project;
}

async function launchOsProjectBySlug(slug) {
  const raw = String(slug || "").trim();
  let wanted = raw.toLowerCase();
  try {
    const parsed = new URL(raw);
    wanted = decodeURIComponent(parsed.pathname.split("/").filter(Boolean).pop() || "").toLowerCase();
  } catch {
    let decoded = raw;
    try { decoded = decodeURIComponent(raw); } catch { /* keep the literal identifier */ }
    wanted = decoded.replace(/^\/+|\/+$/g, "").split("/").pop().toLowerCase();
  }
  const store = await readLaunchOs();
  let project = Object.values(store.projects).find((project) =>
    String(project.slug || "").toLowerCase() === wanted ||
    String(project.publicSlug || "").toLowerCase() === wanted ||
    String(project.token?.ca || "").toLowerCase() === wanted
  ) || null;
  // Repair sites created by the old editor bug that retained the payout wallet
  // but accidentally saved the rewards toggle as off during first publish.
  if (project?.payment?.status === "unlocked" && project.partner?.payoutWallet && project.partner?.status !== "active") {
    await mutateLaunchOs((current) => {
      const saved = current.projects[project.id];
      if (!saved?.partner?.payoutWallet) return;
      saved.partner.enabled = true;
      saved.partner.status = "activating";
    });
    await syncLaunchOsPartner(project.id).catch(() => {});
    project = (await readLaunchOs()).projects[project.id] || project;
  }
  return project;
}

function launchOsPublicSlug(store, token, excludeId = "") {
  const base = socialKitSlug(token?.symbol || token?.name || "coin").slice(0, 48) || "coin";
  const used = new Set(Object.values(store?.projects || {})
    .filter((project) => String(project.id) !== String(excludeId))
    .map((project) => String(project.publicSlug || "").trim().toLowerCase())
    .filter(Boolean));
  if (!used.has(base)) return base;
  let number = 2;
  while (used.has(`${base}-${number}`)) number += 1;
  return `${base}-${number}`;
}

function launchOsPublicSiteUrl(publicSlug) {
  return `https://www.slimewire.org/ca/${encodeURIComponent(publicSlug)}`;
}

async function createLaunchOsProject(userId, body = {}, options = {}) {
  const token = await resolveSocialKitToken(body.input);
  const mode = String(body.mode || "official").toLowerCase() === "cto" ? "cto" : "official";
  const store = await readLaunchOs();
  const existing = userId ? Object.values(store.projects).find((project) => String(project.userId) === String(userId) && String(project.token?.ca || "").toLowerCase() === token.ca.toLowerCase()) : null;
  if (existing) {
    if (!existing.publicSlug || !String(existing.publicUrl || "").includes("/ca/")) {
      const migrated = await mutateLaunchOs((current) => {
        const saved = current.projects[existing.id];
        if (!saved.publicSlug) saved.publicSlug = launchOsPublicSlug(current, saved.token, saved.id);
        const oldUrl = saved.publicUrl;
        saved.publicUrl = launchOsPublicSiteUrl(saved.publicSlug);
        if (!saved.links?.website || saved.links.website === oldUrl || /\/coin-site\?project=/i.test(saved.links.website)) saved.links.website = saved.publicUrl;
        saved.updatedAt = new Date().toISOString();
        return saved;
      });
      return clientLaunchOsProject(migrated);
    }
    return clientLaunchOsProject(existing);
  }
  const id = crypto.randomBytes(6).toString("hex");
  const slug = `${socialKitSlug(token.name || token.symbol)}-${id.slice(0, 6)}`;
  const publicSlug = launchOsPublicSlug(store, token);
  const publicUrl = launchOsPublicSiteUrl(publicSlug);
  const code = String(body.code || "").trim().toUpperCase();
  const solUsd = await getSolUsdPrice({ timeoutMs: 2_500 }).catch(() => 0);
  if (!(solUsd > 0)) throw Object.assign(new Error("SOL/USD price is temporarily unavailable. Try again shortly."), { statusCode: 503 });
  const codeRow = code ? store.codes?.[code] : null;
  const waived = Boolean(codeRow && !codeRow.usedAt && !codeRow.revokedAt);
  if (code && !waived) throw Object.assign(new Error("That free code is invalid, used or revoked."), { statusCode: 400 });
  let depositAddress = "";
  if (!waived) {
    const wallet = await mutateWalletStore((walletStore) => {
      const kp = Keypair.generate();
      const row = walletRecord(`coinsite:${id}`, kp, COIN_SITE_DEPOSIT_OWNER);
      walletStore.wallets.push(row); return row;
    });
    depositAddress = wallet.publicKey;
  }
  const priceSol = Math.ceil((COIN_SITE_PRICE_USD / solUsd) * 1_000_000) / 1_000_000;
  const project = {
    id, slug, publicSlug, setupCode: crypto.randomBytes(5).toString("hex"), userId: String(userId), mode,
    editorKeyHash: options.editorKeyHash || "",
    createRequestId: options.createRequestId || "",
    createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), publicUrl, token,
    officialClaim: false,
    brand: {
      tagline: `${token.name}: built by the community, tracked in public.`,
      description: launchOsCleanText(token.description || `${token.name} is a community-driven ${token.chain === "robinhood" ? "Robinhood Chain" : "Solana"} coin.`),
      voice: "meme-native", primaryColor: "#76ff35"
    },
    links: { x: token.twitterUrl || "", telegram: token.telegramUrl || "", website: token.websiteUrl || publicUrl, discord: "", farcaster: "" },
    content: launchOsDefaultContent(token, publicUrl),
    telegram: { groups: [] }, listing: { notes: "", dexPaid: false, coinGeckoSubmitted: false },
    crisis: { active: false, message: "" },
    partner: { enabled: false, status: "not_configured", payoutWallet: "" }
  };
  const requestedPayout = String(body.partnerPayoutWallet || "").trim();
  if (requestedPayout) {
    try {
      new PublicKey(requestedPayout);
      project.partner = { enabled: true, status: waived ? "activating" : "awaiting_publish", payoutWallet: requestedPayout };
    } catch {
      throw Object.assign(new Error("Enter a valid Solana payout wallet for Community Rewards."), { statusCode: 400 });
    }
  }
  project.payment = {
    status: waived ? "unlocked" : "awaiting_payment", waived, code: waived ? code : "",
    priceUsd: COIN_SITE_PRICE_USD, priceSol, depositAddress, createdAt: new Date().toISOString()
  };
  project.site = launchOsDefaultSite(token, publicUrl, mode);
  await mutateLaunchOs((current) => {
    const availablePublicSlug = launchOsPublicSlug(current, project.token, project.id);
    if (availablePublicSlug !== project.publicSlug) {
      const oldUrl = project.publicUrl;
      project.publicSlug = availablePublicSlug;
      project.publicUrl = launchOsPublicSiteUrl(availablePublicSlug);
      if (project.links?.website === oldUrl) project.links.website = project.publicUrl;
      for (const key of Object.keys(project.content || {})) {
        project.content[key] = String(project.content[key] || "").split(oldUrl).join(project.publicUrl);
      }
    }
    if (waived) {
      const row = current.codes[code];
      if (!row || row.usedAt || row.revokedAt) throw Object.assign(new Error("That free code was already used."), { statusCode: 409 });
      row.usedAt = new Date().toISOString(); row.usedBy = String(userId || "public"); row.projectId = id;
    }
    current.projects[id] = project;
  });
  const tokenArt = await launchOsTrustedTokenImageBuffer(token.imageUrl).catch(() => null);
  try {
    await generateLaunchOsFreeMedia(project, tokenArt);
  } catch (error) {
    // A malformed remote token image must never prevent the built-in brand art.
    if (tokenArt) await generateLaunchOsFreeMedia(project, null);
    else throw error;
  }
  if (waived && project.partner?.enabled) await syncLaunchOsPartner(project.id).catch(() => {});
  return clientLaunchOsProject(await getLaunchOsProjectForUser(userId, id));
}

async function syncLaunchOsPartner(projectId) {
  const stored = (await readLaunchOs()).projects[String(projectId || "")];
  if (!stored?.partner?.enabled || stored.payment?.status !== "unlocked") return null;
  const program = await ensurePartnerProgramForProject(stored, stored.partner.payoutWallet);
  if (!program) return null;
  await mutateLaunchOs((store) => {
    const row = store.projects[stored.id];
    if (!row) return;
    row.partner = { ...row.partner, enabled: true, status: "active", programId: program.id, code: program.code, dashboardUrl: `${row.publicUrl}#rewards` };
    row.updatedAt = new Date().toISOString();
  });
  const latest = (await readLaunchOs()).projects[stored.id];
  const notifyChatId = latest?.editDelivery?.deliveredChatId;
  if (notifyChatId && !latest.partner?.notifiedAt) {
    const dashboardUrl = `https://www.slimewire.org/rewards/${encodeURIComponent(program.code)}`;
    try {
      await sayHtml(notifyChatId, [
        `<b>${escapeTelegramHtml(stored.token?.name || stored.token?.symbol)} Community Rewards is live</b>`,
        "",
        "Developer <b>50%</b> Â· Top holders <b>50%</b>",
        "Trade fee: 0.65% total. Eligible reward or referral allocations stay inside that total; they never add a surcharge."
      ].join("\n"), { inline_keyboard: [[{ text: "Live rewards dashboard", url: dashboardUrl }], [{ text: "Partner trade link", url: partnerProgramPublic(program).tradeUrl }]] });
      await mutateLaunchOs((store) => { if (store.projects[stored.id]?.partner) store.projects[stored.id].partner.notifiedAt = new Date().toISOString(); });
    } catch { /* owner can still open the dashboard from Site Maker */ }
  }
  return program;
}

async function coinSitePaymentStatus(slug, editKey) {
  let project = await requireLaunchOsEditor(slug, editKey);
  const payment = project.payment;
  if (!payment) return clientLaunchOsProject(project);
  if (payment.status === "awaiting_payment" && payment.depositAddress) {
    await LockService.withLock(`coin-site-payment:${project.id}`, 15_000, async () => {
      const current = await requireLaunchOsEditor(slug, editKey);
      if (current.payment?.status !== "awaiting_payment") return;
      const lamports = Number(await getSolBalanceCached(new PublicKey(current.payment.depositAddress), { force: true }).catch(() => 0));
      if (lamports < Math.round(Number(current.payment.priceSol) * 0.98 * 1e9)) return;
      await mutateLaunchOs((store) => {
        const row = store.projects[current.id];
        row.payment.status = "unlocked"; row.payment.paidAt = new Date().toISOString(); row.payment.paidLamports = lamports;
      });
    });
    project = await requireLaunchOsEditor(slug, editKey);
  }
  if (project.payment?.status === "unlocked" && project.payment.depositAddress && !project.payment.sweptAt) {
    const wallet = (await readWalletStore()).wallets.find((row) => row.ownerId === COIN_SITE_DEPOSIT_OWNER && row.label === `coinsite:${project.id}`);
    if (wallet) {
      try {
        const sweep = await drainSolFromWallet(decryptWallet(wallet), new PublicKey(CONFIG.feeWallet));
        if (sweep?.signature) project = await mutateLaunchOs((store) => {
          const row = store.projects[project.id]; row.payment.sweptAt = new Date().toISOString(); row.payment.sweepSignature = sweep.signature; return row;
        });
      } catch { /* payment stays unlocked; retry treasury sweep on the next check */ }
    }
  }
  if (project.payment?.status === "unlocked" && project.partner?.enabled && project.partner?.status !== "active") {
    await syncLaunchOsPartner(project.id).catch(() => {});
    project = await requireLaunchOsEditor(slug, editKey);
  }
  return clientLaunchOsProject(project);
}

function normalizeCoinSiteTelegramUsername(value = "") {
  const clean = String(value || "").trim().replace(/^@+/, "");
  return /^[A-Za-z0-9_]{5,32}$/.test(clean) ? clean.toLowerCase() : "";
}

async function rememberCoinSiteTelegramUser(from, userId) {
  const username = normalizeCoinSiteTelegramUsername(from?.username);
  if (!username || !userId) return false;
  const current = (await readLaunchOs()).telegramUsers?.[username];
  if (String(current?.chatId || "") === String(userId)) return true;
  await mutateLaunchOs((store) => {
    store.telegramUsers = store.telegramUsers || {};
    store.telegramUsers[username] = {
      chatId: String(userId), username: String(from.username || username),
      firstName: launchOsCleanText(from?.first_name || "", 80), updatedAt: new Date().toISOString()
    };
  });
  return true;
}

function coinSiteOwnerEditUrl(project, editKey) {
  return `https://www.slimewire.org/site-maker?project=${encodeURIComponent(project.slug)}#edit=${encodeURIComponent(editKey)}`;
}

function coinSiteTelegramDeliveryForEditor(project) {
  const row = project?.editDelivery || {};
  let claimCode = "";
  try { claimCode = row.claimSecret ? decryptSecretBuffer(row.claimSecret).toString("utf8") : ""; } catch { claimCode = ""; }
  return {
    status: row.deliveredAt ? "sent" : claimCode ? "needs_start" : "not_requested",
    username: row.requestedUsername ? `@${row.requestedUsername}` : "",
    botUrl: claimCode ? telegramStartLink(`siteedit_${claimCode}`) : "",
    deliveredAt: row.deliveredAt || ""
  };
}

async function sendCoinSiteEditLinkDm(project, editKey, chatId) {
  const editUrl = coinSiteOwnerEditUrl(project, editKey);
  await sayHtml(chatId, [
    `🔐 <b>${escapeTelegramHtml(project.token?.name || "Coin")} Site Maker owner link</b>`,
    "",
    "Keep this DM. It lets you update the site text, images and generated art anytime.",
    `<a href="${escapeTelegramHtml(editUrl)}">Open private site editor</a>`,
    "",
    "Never share this owner link publicly."
  ].join("\n"), { inline_keyboard: [[{ text: "✏️ Open Site Editor", url: editUrl }], [{ text: "🌐 Open Coin Site", url: project.publicUrl }]] });
  await mutateLaunchOs((store) => {
    const saved = store.projects[project.id];
    if (!saved?.editDelivery) return;
    saved.editDelivery.deliveredAt = new Date().toISOString();
    saved.editDelivery.deliveredChatId = String(chatId);
  });
  return true;
}

async function claimCoinSiteEditLink(claimCode, chatId) {
  const claimHash = hashWebSecret(String(claimCode || ""));
  return mutateLaunchOs((store) => {
    const project = Object.values(store.projects).find((item) => item.editDelivery?.claimHash === claimHash);
    if (!project?.editDelivery?.editKeySecret) return null;
    const deliveredChatId = String(project.editDelivery.deliveredChatId || "");
    if (deliveredChatId && deliveredChatId !== String(chatId)) return null;
    let editKey = "";
    try { editKey = decryptSecretBuffer(project.editDelivery.editKeySecret).toString("utf8"); } catch { return null; }
    return { project, editKey };
  });
}

async function prepareCoinSiteTelegramDelivery(projectId, editKey, rawUsername) {
  const requestedUsername = normalizeCoinSiteTelegramUsername(rawUsername);
  if (!requestedUsername) return { status: "not_requested", username: "", botUrl: "", deliveredAt: "" };
  const claimCode = crypto.randomBytes(18).toString("base64url");
  const project = await mutateLaunchOs((store) => {
    const saved = store.projects[projectId];
    if (!saved) return null;
    saved.editDelivery = {
      requestedUsername, claimHash: hashWebSecret(claimCode),
      claimSecret: encryptSecret(Buffer.from(claimCode, "utf8")),
      editKeySecret: encryptSecret(Buffer.from(editKey, "utf8")),
      createdAt: new Date().toISOString(), deliveredAt: "", deliveredChatId: ""
    };
    return saved;
  });
  if (!project) return { status: "not_requested", username: `@${requestedUsername}`, botUrl: "", deliveredAt: "" };
  const known = (await readLaunchOs()).telegramUsers?.[requestedUsername];
  if (known?.chatId) {
    try {
      const currentChat = await telegram("getChat", { chat_id: known.chatId });
      if (normalizeCoinSiteTelegramUsername(currentChat?.username) === requestedUsername) {
        await sendCoinSiteEditLinkDm(project, editKey, known.chatId);
        const refreshed = (await readLaunchOs()).projects[project.id];
        return coinSiteTelegramDeliveryForEditor(refreshed);
      }
    } catch { /* user may have blocked the bot; the start link remains available */ }
  }
  return coinSiteTelegramDeliveryForEditor(project);
}

async function createPublicLaunchOsProject(body = {}) {
  const editKey = crypto.randomBytes(24).toString("hex");
  const editorKeyHash = hashWebSecret(editKey);
  const payoutWallet = String(body.partnerPayoutWallet || "").trim();
  if (!payoutWallet) {
    throw Object.assign(new Error("Enter a Solana developer payout wallet. Community Rewards is included with every published coin site."), { statusCode: 400 });
  }
  try { new PublicKey(payoutWallet); }
  catch { throw Object.assign(new Error("Enter a valid Solana payout wallet for Community Rewards."), { statusCode: 400 }); }
  const requestId = /^[A-Za-z0-9_-]{16,80}$/.test(String(body.requestId || "")) ? String(body.requestId) : "";
  if (requestId) {
    const existing = Object.values((await readLaunchOs()).projects || {}).find((row) => row.createRequestId === requestId);
    if (existing?.editDelivery?.editKeySecret) {
      try {
        const recoveredKey = decryptSecretBuffer(existing.editDelivery.editKeySecret).toString("utf8");
        if (launchOsEditorMatches(existing, recoveredKey)) {
          return { project: clientLaunchOsProject(existing), editKey: recoveredKey, telegramDelivery: coinSiteTelegramDeliveryForEditor(existing) };
        }
      } catch { /* a malformed retry record falls through to a normal create */ }
    }
  }
  const project = await createLaunchOsProject("", body, { editorKeyHash, createRequestId: requestId });
  const telegramDelivery = await prepareCoinSiteTelegramDelivery(project.id, editKey, body.telegramUsername);
  return { project, editKey, telegramDelivery };
}

function applyLaunchOsUpdate(project, body = {}) {
  if (body.mode != null) project.mode = String(body.mode).toLowerCase() === "cto" ? "cto" : "official";
  if (body.officialClaim != null) project.officialClaim = Boolean(body.officialClaim);
  const brand = body.brand && typeof body.brand === "object" ? body.brand : {};
  project.brand = project.brand || {};
  if (brand.tagline != null) project.brand.tagline = launchOsCleanText(brand.tagline, 120);
  if (brand.description != null) project.brand.description = launchOsCleanText(brand.description, 700);
  if (brand.voice != null) project.brand.voice = ["meme-native", "clean", "chaotic", "premium"].includes(String(brand.voice)) ? String(brand.voice) : "meme-native";
  if (brand.primaryColor != null && /^#[0-9a-f]{6}$/i.test(String(brand.primaryColor))) project.brand.primaryColor = String(brand.primaryColor);
  project.links = project.links || {};
  for (const key of ["x", "telegram", "website", "discord", "farcaster"]) {
    if (body.links?.[key] != null) project.links[key] = socialKitPublicUrl(body.links[key]);
  }
  project.content = project.content || {};
  for (const key of ["launchPost", "pinnedPost", "telegramWelcome", "milestonePost", "emergencyPost"]) {
    if (body.content?.[key] != null) project.content[key] = launchOsCleanText(body.content[key], 1200);
  }
  project.listing = project.listing || {};
  if (body.listing?.notes != null) project.listing.notes = launchOsCleanText(body.listing.notes, 1200);
  if (body.listing?.dexPaid != null) project.listing.dexPaid = Boolean(body.listing.dexPaid);
  if (body.listing?.coinGeckoSubmitted != null) project.listing.coinGeckoSubmitted = Boolean(body.listing.coinGeckoSubmitted);
  project.crisis = project.crisis || { active: false, message: "" };
  if (body.crisis?.active != null) project.crisis.active = Boolean(body.crisis.active);
  if (body.crisis?.message != null) project.crisis.message = launchOsCleanText(body.crisis.message, 500);
  if (body.partner && typeof body.partner === "object") {
    const payout = String(body.partner.payoutWallet || "").trim();
    project.partner = project.partner || { enabled: false, status: "not_configured", payoutWallet: "" };
    if (payout) {
      try { new PublicKey(payout); }
      catch { throw Object.assign(new Error("Enter a valid Solana payout wallet for Community Rewards."), { statusCode: 400 }); }
      project.partner.payoutWallet = payout;
    }
    // Coin sites always participate once a valid payout wallet exists. The editor
    // cannot accidentally switch rewards off while saving unrelated site changes.
    project.partner.enabled = Boolean(project.partner.payoutWallet);
    if (project.partner.enabled && project.partner.status !== "active") project.partner.status = project.payment?.status === "unlocked" ? "activating" : "awaiting_publish";
  }
  const site = body.site && typeof body.site === "object" ? body.site : null;
  if (site) {
    project.site = project.site || launchOsDefaultSite(project.token, project.publicUrl, project.mode);
    const firstCreativeDirection = !project.site.prompt && launchOsCleanText(site.prompt, 500);
    if (["signature", "cinematic", "terminal", "editorial"].includes(String(site.template))) project.site.template = String(site.template);
    if (/^#[0-9a-f]{6}$/i.test(String(site.accent || ""))) project.site.accent = String(site.accent);
    for (const key of ["prompt", "headline", "subhead", "lore"]) if (site[key] != null) project.site[key] = launchOsCleanText(site[key], key === "lore" ? 2400 : 500);
    if (firstCreativeDirection) {
      const copy = launchOsCreativeCopy(project.token, firstCreativeDirection, project.mode);
      project.site.headline = copy.headline;
      project.site.subhead = copy.subhead;
      project.site.copyVoice = copy.voice;
    }
    if (Array.isArray(site.roadmap)) project.site.roadmap = site.roadmap.slice(0, 6).map((x) => launchOsCleanText(x, 180)).filter(Boolean);
    if (site.sections && typeof site.sections === "object") {
      project.site.sections = project.site.sections || {};
      for (const key of ["market", "lore", "gallery", "howToBuy", "roadmap", "socials", "memeMaker"]) if (site.sections[key] != null) project.site.sections[key] = Boolean(site.sections[key]);
    }
  }
  project.updatedAt = new Date().toISOString();
  return project;
}

async function updateLaunchOsProject(userId, body = {}) {
  const id = String(body.id || "");
  return mutateLaunchOs((store) => {
    const project = store.projects[id];
    if (!project || String(project.userId) !== String(userId)) throw Object.assign(new Error("Launch OS project not found."), { statusCode: 404 });
    return clientLaunchOsProject(applyLaunchOsUpdate(project, body));
  });
}

async function updatePublicLaunchOsProject(slug, editKey, body = {}) {
  const wanted = String(slug || "").trim().toLowerCase();
  const updated = await mutateLaunchOs((store) => {
    const project = Object.values(store.projects).find((item) => String(item.slug || "").toLowerCase() === wanted);
    if (!launchOsEditorMatches(project, editKey)) throw Object.assign(new Error("Private edit link is invalid or incomplete."), { statusCode: 404 });
    return clientLaunchOsProject(applyLaunchOsUpdate(project, body));
  });
  if (updated.partner?.enabled && updated.payment?.status === "unlocked") await syncLaunchOsPartner(updated.id).catch(() => {});
  return clientLaunchOsProject((await readLaunchOs()).projects[updated.id]);
}

async function launchOsLiveStatus(project) {
  const token = project.token || {};
  let row = {};
  if (token.chain === "robinhood") {
    const info = await gatherRhScan(token.ca).catch(() => null);
    row = info ? { priceUsd: info.priceUsd, marketCap: info.mc, liquidityUsd: info.liq, volume24h: info.vol24, holders: info.holders, change24h: info.ch24, source: info.source } : {};
  } else {
    const info = await getDexTokenMetadata(token.ca, { timeoutMs: 4_000 }).catch(() => null);
    row = info ? {
      priceUsd: firstMeaningfulNumber(info.priceUsd, info.price), marketCap: firstMeaningfulNumber(info.marketCap, info.fdv),
      liquidityUsd: firstMeaningfulNumber(info.liquidityUsd), volume24h: firstMeaningfulNumber(info.volume?.h24, info.volume24h),
      holders: firstMeaningfulNumber(info.holders), change24h: firstMeaningfulNumber(info.priceChange?.h24), source: info.source || info.metadataSourceUsed
    } : {};
  }
  return { ...row, readiness: launchOsReadiness(project), linkAudit: launchOsLinkAudit(project), checkedAt: new Date().toISOString() };
}

async function webWalletRows(userId) {
  const store = await readWalletStore();
  // Keep ALL wallets here (indexes must stay stable for trade wallet resolution).
  // Volume-bot/background wallets are flagged so the UI can hide them.
  return walletsForOwner(store, userId).map((wallet, index) => ({
    index: index + 1,
    label: wallet.label,
    publicKey: wallet.publicKey,
    shortPublicKey: shortMint(wallet.publicKey),
    sessionWallet: Boolean(wallet.sessionWallet),
    sessionStatus: wallet.sessionStatus || "",
    sourceConnectedWallet: wallet.sourceConnectedWallet || "",
    sessionExpiresAt: wallet.sessionExpiresAt || "",
    fundingSignature: wallet.fundingSignature || "",
    fundingAmountSol: wallet.fundingAmountLamports ? lamportsToSol(wallet.fundingAmountLamports) : "",
    volumeBot: Boolean(wallet.volumeBot || wallet.ephemeral),
    volumeSource: wallet.volumeSource || ""
  }));
}

function webWalletRowFromRecord(record, index = 1) {
  return {
    index,
    label: record.label,
    publicKey: record.publicKey,
    shortPublicKey: shortMint(record.publicKey),
    sessionWallet: Boolean(record.sessionWallet),
    sessionStatus: record.sessionStatus || "",
    sourceConnectedWallet: record.sourceConnectedWallet || "",
    sessionExpiresAt: record.sessionExpiresAt || "",
    fundingSignature: record.fundingSignature || "",
    fundingAmountSol: record.fundingAmountLamports ? lamportsToSol(record.fundingAmountLamports) : ""
  };
}

function assertServerTradeWalletReady(wallet, context = "trading") {
  if (!wallet?.secret) {
    throw new Error(`${wallet?.label || "This wallet"} is not a server-signable SlimeWire wallet.`);
  }
  if (!wallet.sessionWallet) return wallet;
  if (wallet.sessionStatus !== "funded") {
    throw new Error(`${wallet.label || "Session wallet"} is not funded yet. Open Wallets and finish Start Session before using it for ${context}.`);
  }
  const expiresAt = Date.parse(wallet.sessionExpiresAt || "");
  if (Number.isFinite(expiresAt) && expiresAt <= Date.now()) {
    throw new Error(`${wallet.label || "Session wallet"} has expired. Fund a new session wallet before using it for ${context}.`);
  }
  return wallet;
}

async function freshServerTradeWalletForOwner(ownerUserId, walletPublicKey, context = "trading") {
  const expectedPublicKey = String(walletPublicKey || "").trim();
  const store = await readWalletStore();
  const owned = walletsForOwner(store, ownerUserId);
  const zeroBasedIndex = owned.findIndex((wallet) => String(wallet.publicKey || "") === expectedPublicKey);
  if (zeroBasedIndex < 0) {
    throw new Error("The selected SlimeWire wallet is no longer available. No new transaction was sent.");
  }
  const wallet = assertServerTradeWalletReady(owned[zeroBasedIndex], context);
  return { wallet, walletIndex: zeroBasedIndex + 1 };
}

function getWebServerTradeWalletAt(store, oneBasedIndex, userId, context = "trading") {
  return assertServerTradeWalletReady(getWalletAt(store, oneBasedIndex, userId), context);
}

function assertFrozenManagedWallet(wallet, expectedPublicKey, context = "trade") {
  const expected = String(expectedPublicKey || "").trim();
  if (expected && String(wallet?.publicKey || "") !== expected) {
    const error = new Error(`The selected wallet changed before this ${context}. Refresh and stage it again; no order was sent.`);
    error.statusCode = 409;
    throw error;
  }
  return wallet;
}

// Sweeping/draining a wallet's OWN SOL or tokens out to an external address needs nothing but the
// signing key — NOT a "funded session". So sweeps use this lighter check instead of the trade-ready
// gate, otherwise one half-finished or expired session wallet in the set aborts the entire "sweep all".
function assertServerSignableWallet(wallet, context = "sweeping") {
  if (!wallet?.secret) {
    throw new Error(`${wallet?.label || "This wallet"} is not a server-signable SlimeWire wallet — can't ${context} it.`);
  }
  return wallet;
}

async function createWebWalletSet(userId, body = {}) {
  const label = cleanLabel(String(body.label || "Ogre Web"));
  const count = Number.parseInt(body.count || "1", 10);
  const idempotencyKeyHash = /^[a-f0-9]{64}$/i.test(String(body.idempotencyKeyHash || ""))
    ? String(body.idempotencyKeyHash).toLowerCase()
    : "";
  if (!Number.isInteger(count) || count < 1 || count > 20) {
    const error = new Error("Wallet count must be from 1 to 20.");
    error.statusCode = 400;
    throw error;
  }

  const createdRecords = [];
  const createdIndexes = new Map();
  let duplicate = false;
  // Append the new records under the wallet-store lock so a concurrent create/import can't drop them.
  await mutateWalletStore((store) => {
    if (idempotencyKeyHash) {
      const existing = walletsForOwner(store, userId).filter((wallet) => wallet.xDmCreateRequestHash === idempotencyKeyHash);
      if (existing.length) {
        createdRecords.push(...existing);
        const ownerWallets = walletsForOwner(store, userId);
        for (const wallet of existing) createdIndexes.set(wallet.publicKey, ownerWallets.indexOf(wallet) + 1);
        duplicate = true;
        return;
      }
      if (walletsForOwner(store, userId).length + count > 40) {
        const error = new Error("X Trade Pad supports up to 40 managed wallets. Use or remove an existing wallet before creating more.");
        error.statusCode = 400;
        throw error;
      }
    }
    for (let index = 1; index <= count; index += 1) {
      const keypair = Keypair.generate();
      const walletLabel = count === 1 ? label : `${label} ${index}`;
      const record = walletRecord(walletLabel, keypair, userId);
      if (idempotencyKeyHash) record.xDmCreateRequestHash = idempotencyKeyHash;
      store.wallets.push(record);
      createdRecords.push(record);
      createdIndexes.set(record.publicKey, walletsForOwner(store, userId).indexOf(record) + 1);
    }
  });

  await audit("web_create_wallet_set", {
    userId,
    label,
    count,
    publicKeys: createdRecords.map((wallet) => wallet.publicKey),
    duplicate
  }).catch(() => {});

  const encryptedBackup = buildWalletBackupDocument(
    userId,
    "Automatic web backup after wallet creation.",
    label,
    createdRecords
  );
  const recoveryKeys = buildPrivateKeyDocument(
    userId,
    createdRecords,
    `solflare-recovery-${sanitizeFilenamePart(label)}-${userId}`,
    {
      title: "SOLFLARE / PHANTOM RECOVERY KEY FILE",
      note: "Automatic web recovery file after wallet creation."
    }
  );
  const evmRecoveryKeys = buildEvmPrivateKeyDocument(
    userId,
    createdRecords,
    `robinhood-eth-recovery-${sanitizeFilenamePart(label)}-${userId}`,
    { note: "Automatic Robinhood/EVM recovery file after wallet creation." }
  );

  return {
    duplicate,
    wallets: createdRecords.map((wallet, index) => ({
      index: createdIndexes.get(wallet.publicKey) || index + 1,
      label: wallet.label,
      publicKey: wallet.publicKey,
      shortPublicKey: shortMint(wallet.publicKey)
    })),
    downloads: {
      encryptedBackup: {
        filename: encryptedBackup.filename,
        text: encryptedBackup.text
      },
      recoveryKeys: {
        filename: recoveryKeys.filename,
        text: recoveryKeys.text
      },
      evmRecoveryKeys: {
        filename: evmRecoveryKeys.filename,
        text: evmRecoveryKeys.text
      }
    }
  };
}

async function renameWebWallet(userId, body = {}) {
  const walletIndex = parseWebWalletIndex(body.walletIndex || body.index);
  const label = cleanLabel(String(body.label || body.name || ""));
  if (!label) {
    const error = new Error("Enter a wallet name.");
    error.statusCode = 400;
    throw error;
  }
  let renamed = null;
  await mutateWalletStore((store) => {
    const wallet = getWalletAt(store, walletIndex, userId);
    wallet.label = label;
    wallet.renamedAt = new Date().toISOString();
    renamed = webWalletRowFromRecord(wallet, walletIndex);
  });
  await audit("web_wallet_rename", {
    userId,
    walletIndex,
    publicKey: renamed?.publicKey || "",
    label
  });
  return {
    wallet: renamed,
    wallets: await webWalletRows(userId),
    message: `Wallet ${walletIndex} renamed to ${label}.`
  };
}

// Create N fresh managed wallets and fund each from a source wallet in one
// step (compose the tested wallet-create + send-sol-many paths). Lets a
// trader move off their known wallet so copy-traders can't follow it.
// Idempotency wrapper — creates AND funds N wallets, so a retry must not do it twice.
async function webDistributeToFreshWallets(userId, body = {}) {
  return runIdempotentMoneyOp("web-distribute", userId,
    firstString(body.tradeAttemptId, body.distributeAttemptId, body.clientRequestId),
    () => webDistributeToFreshWalletsCore(userId, body),
    { busyMessage: "Distribution is already running — SlimeWire won't fund a second set of wallets." });
}

async function webDistributeToFreshWalletsCore(userId, body = {}) {
  const count = Number.parseInt(body.count || "0", 10);
  if (!Number.isInteger(count) || count < 1 || count > 20) {
    const error = new Error("Wallet count must be from 1 to 20.");
    error.statusCode = 400;
    throw error;
  }
  const amountSol = parsePositiveNumber(String(body.amountSol || ""));
  const sourceIndex = parseWebWalletIndex(body.sourceWalletIndex || body.fromWalletIndex || body.walletIndex);
  const label = cleanLabel(String(body.label || "Fresh"));

  // Confirm the source wallet exists/owned before creating anything.
  const store = await readWalletStore();
  const sourceRecord = getWalletAt(store, sourceIndex, userId);

  const created = await createWebWalletSet(userId, { count, label });
  const destinations = (created.wallets || []).map((wallet) => wallet.publicKey).filter(Boolean);
  if (!destinations.length) {
    throw new Error("Wallet creation returned no wallets. Try again.");
  }

  const fund = await webSendSolMany(userId, {
    fromWalletIndex: sourceIndex,
    destinations,
    amountSol: String(amountSol)
  });

  await audit("web_distribute_fresh_wallets", {
    userId,
    count: destinations.length,
    amountSol,
    sourcePublicKey: sourceRecord.publicKey,
    signature: fund?.signature
  });

  return {
    action: "distribute-fresh-wallets",
    count: destinations.length,
    amountSol,
    fundedSol: Number((amountSol * destinations.length).toFixed(6)),
    wallets: created.wallets,
    downloads: created.downloads,
    signature: fund?.signature || "",
    summary: `Created ${destinations.length} fresh wallet(s) and funded each with ${amountSol} SOL${fund?.signature ? ` (${fund.signature})` : ""}.`
  };
}

function pruneSessionWalletOrders(orders = []) {
  const now = Date.now();
  return (Array.isArray(orders) ? orders : [])
    .filter((order) => Number(Date.parse(order.expiresAt || "")) > now || ["submitted", "complete"].includes(order.status))
    .slice(-100);
}

async function saveSessionWalletOrder(order) {
  await mutateWebAuthStore((store) => {
    store.sessionWalletOrders = pruneSessionWalletOrders(store.sessionWalletOrders);
    const index = store.sessionWalletOrders.findIndex((item) => item.sessionWalletAttemptId === order.sessionWalletAttemptId);
    if (index >= 0) store.sessionWalletOrders[index] = { ...store.sessionWalletOrders[index], ...order };
    else store.sessionWalletOrders.push(order);
  });
}

async function takePendingSessionWalletOrder(userId, sessionWalletAttemptId, expectedKind = "session-wallet") {
  // Atomic pending→submitting flip (see takePendingBrowserTradeOrder for the why).
  const outcome = await mutateWebAuthStore((store) => {
    store.sessionWalletOrders = pruneSessionWalletOrders(store.sessionWalletOrders);
    const order = store.sessionWalletOrders.find((item) => (
      item.sessionWalletAttemptId === sessionWalletAttemptId
      && String(item.userId || "") === String(userId || "")
    ));
    if (!order) return { error: { message: "Session wallet funding approval expired. Start a new session wallet.", status: 404 } };
    const orderKind = String(order.orderKind || "session-wallet");
    if (expectedKind && orderKind !== expectedKind) return { error: { message: "Wallet funding approval does not match this action. Start again.", status: 409 } };
    if (order.status !== "pending") return { error: { message: "This session wallet funding approval was already submitted.", status: 409 } };
    if (Date.parse(order.expiresAt || "") <= Date.now()) {
      order.status = "expired";
      return { error: { message: "Session wallet funding approval expired. Start a new session wallet.", status: 410 } };
    }
    order.status = "submitting";
    order.submittingAt = new Date().toISOString();
    return { order };
  });
  if (outcome.error) {
    const error = new Error(outcome.error.message);
    error.statusCode = outcome.error.status;
    throw error;
  }
  return outcome.order;
}

async function completePendingSessionWalletOrder(order, patch = {}) {
  await saveSessionWalletOrder({
    ...order,
    ...patch,
    updatedAt: new Date().toISOString()
  });
}

function sessionWalletFundingAmountLamports(body = {}) {
  const amountSol = parsePositiveNumber(String(body.amountSol || "0.1"));
  if (amountSol < 0.005) {
    throw new Error("Wallet funding must be at least 0.005 SOL.");
  }
  if (amountSol > 10) {
    throw new Error("Wallet funding is capped at 10 SOL per approval.");
  }
  return solToLamports(amountSol);
}

function buildWalletFundingTransaction(options) {
  const { sourcePublicKey, destinationPublicKey, amountLamports, blockhash } = options;
  // Declare a small, bounded priority fee ourselves. Phantom only rewrites unsigned transactions
  // that do not already contain compute-budget instructions, while Solflare signs this message as-is.
  // Keeping the message stable makes the mobile app handoff deterministic for both wallets.
  return new Transaction({
    recentBlockhash: blockhash,
    feePayer: sourcePublicKey
  }).add(
    ComputeBudgetProgram.setComputeUnitLimit({ units: 200_000 }),
    ComputeBudgetProgram.setComputeUnitPrice({ microLamports: 5_000 }),
    SystemProgram.transfer({
      fromPubkey: sourcePublicKey,
      toPubkey: destinationPublicKey,
      lamports: amountLamports
    })
  );
}

function verifySessionWalletFundingTransaction(tx, order) {
  const reject = (code, message) => {
    const error = new Error(message);
    error.code = `WALLET_FUNDING_${code}`;
    error.statusCode = 400;
    throw error;
  };
  const source = new PublicKey(order.sourcePublicKey);
  const destination = new PublicKey(order.destinationPublicKey || order.sessionWalletPublicKey);
  // Phantom and Solflare append Lighthouse guard instructions after the transfer on mainnet. These are
  // wallet-generated anti-spoofing assertions: they make the transaction fail if its real state changes do
  // not match the wallet preview. The program is immutable/audited and cannot replace our one exact System
  // transfer. Keep the allowlist deliberately narrow and bounded (Phantom currently adds one; Solflare can
  // add two; the upstream x402 verifier allows up to three for current wallet variants).
  const lighthouseProgram = new PublicKey("L2TExMFKdjpN9kozasaurPirfHy9P8sbXoAN1qA3S95");
  const amountLamports = BigInt(order.amountLamports || 0);
  if (!tx?.feePayer?.equals(source)) {
    reject("SOURCE", "Wallet funding transaction has the wrong source wallet.");
  }
  // Wallets may append any of Solana's safe Compute Budget variants before signing. Validate those
  // instructions by their on-chain byte layout instead of the older web3.js decoder, which does not
  // recognize discriminator 4 (SetLoadedAccountsDataSizeLimit). The only value-moving instruction
  // allowed remains one exact SystemProgram transfer to the chosen SlimeWire wallet.
  if (!Array.isArray(tx.instructions) || tx.instructions.length < 1 || tx.instructions.length > 8) {
    reject("INSTRUCTION_COUNT", "Wallet funding transaction was changed. Start again.");
  }
  if (tx.recentBlockhash !== order.blockhash) {
    reject("BLOCKHASH", "Wallet funding approval expired. Start again.");
  }
  const signer = tx.signatures?.find((item) => item.publicKey?.equals?.(source));
  if (!signer?.signature || !tx.verifySignatures()) {
    reject("SIGNATURE", "Wallet funding transaction is missing a valid connected wallet signature.");
  }

  const transfers = [];
  const seenComputeTypes = new Set();
  let lighthouseInstructions = 0;
  let sawTransferInstruction = false;
  let computeUnitLimit = 1_400_000n;
  let computeUnitPrice = 0n;
  let legacyAdditionalFeeLamports = 0n;
  let sawLegacyRequestUnits = false;
  for (const instruction of tx.instructions) {
    if (instruction.programId.equals(SystemProgram.programId)) {
      try { transfers.push(SystemInstruction.decodeTransfer(instruction)); }
      catch { reject("SYSTEM_INSTRUCTION", "Wallet funding transaction was changed. Start again."); }
      sawTransferInstruction = true;
      continue;
    }
    if (instruction.programId.equals(lighthouseProgram)) {
      // A guard belongs after the value-moving instruction it protects. Never accept an unbounded chain of
      // wallet-added calls even though the program itself is safe.
      lighthouseInstructions += 1;
      if (!sawTransferInstruction || lighthouseInstructions > 3) {
        reject("LIGHTHOUSE_LAYOUT", "Wallet funding transaction was changed. Start again.");
      }
      continue;
    }
    if (!instruction.programId.equals(ComputeBudgetProgram.programId)) {
      reject("PROGRAM", "Wallet funding transaction was changed. Start again.");
    }
    if (instruction.keys?.length) {
      reject("COMPUTE_ACCOUNTS", "Wallet funding transaction was changed. Start again.");
    }
    const data = Buffer.from(instruction.data || []);
    const type = data[0];
    const expectedLength = type === 0 || type === 3 ? 9 : 5;
    if (![0, 1, 2, 3, 4].includes(type) || data.length !== expectedLength || seenComputeTypes.has(type)) {
      reject("COMPUTE_LAYOUT", "Wallet funding transaction was changed. Start again.");
    }
    seenComputeTypes.add(type);

    if (type === 0) { // Legacy RequestUnits(u32 units, u32 additional_fee)
      if (seenComputeTypes.has(2) || seenComputeTypes.has(3)) {
        reject("COMPUTE_DUPLICATE", "Wallet funding transaction was changed. Start again.");
      }
      const units = data.readUInt32LE(1);
      const additionalFee = BigInt(data.readUInt32LE(5));
      if (units < 1 || units > 1_400_000) {
        reject("COMPUTE_UNSAFE", "Wallet funding priority fee settings are unsafe. Start again.");
      }
      computeUnitLimit = BigInt(units);
      legacyAdditionalFeeLamports = additionalFee;
      sawLegacyRequestUnits = true;
      continue;
    }
    if ((type === 2 || type === 3) && sawLegacyRequestUnits) {
      reject("COMPUTE_DUPLICATE", "Wallet funding transaction was changed. Start again.");
    }
    if (type === 1) { // RequestHeapFrame(u32 bytes)
      const bytes = data.readUInt32LE(1);
      if (bytes < 32_768 || bytes > 262_144 || bytes % 1_024 !== 0) {
        reject("COMPUTE_UNSAFE", "Wallet funding compute settings are unsafe. Start again.");
      }
      continue;
    }
    if (type === 2) { // SetComputeUnitLimit(u32 units)
      const units = data.readUInt32LE(1);
      if (units < 1 || units > 1_400_000) {
        reject("COMPUTE_UNSAFE", "Wallet funding priority fee settings are unsafe. Start again.");
      }
      computeUnitLimit = BigInt(units);
      continue;
    }
    if (type === 3) { // SetComputeUnitPrice(u64 micro-lamports)
      computeUnitPrice = data.readBigUInt64LE(1);
      continue;
    }
    // SetLoadedAccountsDataSizeLimit(u32 bytes) is safe and cannot move funds. Solana caps it at 64 MiB.
    const loadedAccountsBytes = data.readUInt32LE(1);
    if (loadedAccountsBytes < 1 || loadedAccountsBytes > 64 * 1024 * 1024) {
      reject("COMPUTE_UNSAFE", "Wallet funding compute settings are unsafe. Start again.");
    }
  }

  const maxPriorityFeeLamports = 1_000_000n;
  const priorityFeeLamports = sawLegacyRequestUnits
    ? legacyAdditionalFeeLamports
    : (computeUnitLimit * computeUnitPrice + 999_999n) / 1_000_000n;
  if (priorityFeeLamports > maxPriorityFeeLamports) {
    reject("PRIORITY_FEE", "Wallet funding priority fee settings are unsafe. Start again.");
  }
  if (transfers.length !== 1) {
    reject("TRANSFER_COUNT", "Wallet funding transaction was changed. Start again.");
  }
  const transfer = transfers[0];
  if (!transfer.fromPubkey.equals(source)
      || !transfer.toPubkey.equals(destination)
      || BigInt(transfer.lamports) !== amountLamports) {
    reject("TRANSFER", "Wallet funding transaction does not match the approved amount.");
  }
}

function walletFundingTransactionShape(tx) {
  if (!Array.isArray(tx?.instructions)) return "unparsed";
  return tx.instructions.map((instruction) => {
    if (instruction.programId?.equals?.(SystemProgram.programId)) return "system";
    if (instruction.programId?.equals?.(ComputeBudgetProgram.programId)) return `compute:${Buffer.from(instruction.data || [])[0] ?? "empty"}`;
    const program = instruction.programId?.toBase58?.() || "other";
    return `other:${String(program).slice(0, 12)}`;
  }).join(",").slice(0, 120);
}

function logWalletFundingFailure(pending, tx, error, stage) {
  const provider = String(pending?.provider || "unknown").replace(/[^a-z0-9._ -]/gi, "").slice(0, 30) || "unknown";
  const code = String(error?.code || error?.name || "UNKNOWN").replace(/[^A-Z0-9_]/gi, "_").slice(0, 48);
  console.warn(`[wallet-funding] rejected kind=${pending?.orderKind || "unknown"} provider=${provider} stage=${stage} code=${code} shape=${walletFundingTransactionShape(tx)}`);
}

async function createWebSessionWalletOrder(userId, body = {}) {
  const profile = await webProfileForUser(userId);
  const connected = profile.connectedWallet || {};
  if (!connected.publicKey) {
    const error = new Error("Connect Phantom, Solflare, or another browser wallet before starting a session wallet.");
    error.statusCode = 400;
    throw error;
  }
  const sourcePublicKey = parsePublicKey(connected.publicKey);
  const amountLamports = sessionWalletFundingAmountLamports(body);
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 10 * 60 * 1000).toISOString();
  const sessionExpiresAt = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString();
  const store = await readWalletStore();
  const keypair = Keypair.generate();
  const label = cleanLabel(String(body.label || `Session ${shortMint(sourcePublicKey.toBase58())}`));
  const record = {
    ...walletRecord(label, keypair, userId),
    sessionWallet: true,
    sessionStatus: "pending-funding",
    sourceConnectedWallet: sourcePublicKey.toBase58(),
    sessionCreatedAt: now.toISOString(),
    sessionExpiresAt,
    sessionBudgetLamports: String(amountLamports)
  };
  store.wallets.push(record);
  const walletIndex = walletsForOwner(store, userId).findIndex((wallet) => wallet.publicKey === record.publicKey) + 1;
  await writeWalletStore(store);

  const latestBlockhash = await rpcWithRetry("get session wallet funding blockhash", () => connection.getLatestBlockhash("confirmed"), CONFIG.rpcRetries, { priority: true });
  const tx = buildWalletFundingTransaction({
    sourcePublicKey,
    destinationPublicKey: keypair.publicKey,
    amountLamports,
    blockhash: latestBlockhash.blockhash
  });
  const sessionWalletAttemptId = `session-wallet-${crypto.randomUUID()}`;
  const pending = {
    sessionWalletAttemptId,
    orderKind: "session-wallet",
    userId,
    status: "pending",
    provider: connected.provider || "Browser Wallet",
    sourcePublicKey: sourcePublicKey.toBase58(),
    sessionWalletPublicKey: record.publicKey,
    walletIndex,
    amountLamports: String(amountLamports),
    blockhash: latestBlockhash.blockhash,
    lastValidBlockHeight: latestBlockhash.lastValidBlockHeight,
    createdAt: now.toISOString(),
    expiresAt
  };
  await saveSessionWalletOrder(pending);
  await audit("web_session_wallet_order", {
    userId,
    provider: pending.provider,
    sourcePublicKey: pending.sourcePublicKey,
    sessionWalletPublicKey: pending.sessionWalletPublicKey,
    walletIndex,
    amountSol: lamportsToSol(amountLamports)
  });

  return {
    wallet: webWalletRowFromRecord(record, walletIndex),
    wallets: await webWalletRows(userId),
    downloads: webBackupDownloadsForWallets(
      userId,
      [record],
      label,
      "Automatic backup for a connected-wallet funded session trading wallet."
    ),
    order: {
      sessionWalletAttemptId,
      provider: pending.provider,
      sourcePublicKey: pending.sourcePublicKey,
      sessionWalletPublicKey: pending.sessionWalletPublicKey,
      walletIndex,
      amountSol: lamportsToSol(amountLamports),
      expiresAt,
      transaction: tx.serialize({ requireAllSignatures: false, verifySignatures: false }).toString("base64"),
      message: `Approve ${lamportsToSol(amountLamports)} SOL funding in ${pending.provider}.`
    }
  };
}

async function createWebWalletFundingOrder(userId, body = {}) {
  const profile = await webProfileForUser(userId);
  const connected = profile.connectedWallet || {};
  if (!connected.publicKey) {
    const error = new Error("Connect a Solana wallet before funding this wallet.");
    error.statusCode = 400;
    throw error;
  }
  const sourcePublicKey = parsePublicKey(connected.publicKey);
  const walletIndex = parseWebWalletIndex(body.walletIndex || body.index);
  const walletStore = await readWalletStore();
  const wallet = getWalletAt(walletStore, walletIndex, userId);
  if (wallet.volumeBot || wallet.ephemeral) {
    const error = new Error("Choose a normal trading wallet to fund.");
    error.statusCode = 400;
    throw error;
  }
  const destinationPublicKey = parsePublicKey(wallet.publicKey);
  if (sourcePublicKey.equals(destinationPublicKey)) {
    const error = new Error("The connected wallet and destination wallet are the same.");
    error.statusCode = 400;
    throw error;
  }
  const amountLamports = sessionWalletFundingAmountLamports(body);
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 10 * 60 * 1000).toISOString();
  const latestBlockhash = await rpcWithRetry("get managed wallet funding blockhash", () => connection.getLatestBlockhash("confirmed"), CONFIG.rpcRetries, { priority: true });
  const tx = buildWalletFundingTransaction({
    sourcePublicKey,
    destinationPublicKey,
    amountLamports,
    blockhash: latestBlockhash.blockhash
  });
  const walletFundingAttemptId = `wallet-funding-${crypto.randomUUID()}`;
  const pending = {
    sessionWalletAttemptId: walletFundingAttemptId,
    orderKind: "wallet-funding",
    userId,
    status: "pending",
    provider: connected.provider || "Browser Wallet",
    sourcePublicKey: sourcePublicKey.toBase58(),
    destinationPublicKey: destinationPublicKey.toBase58(),
    walletIndex,
    amountLamports: String(amountLamports),
    blockhash: latestBlockhash.blockhash,
    lastValidBlockHeight: latestBlockhash.lastValidBlockHeight,
    createdAt: now.toISOString(),
    expiresAt
  };
  await saveSessionWalletOrder(pending);
  await audit("web_wallet_funding_order", {
    userId,
    provider: pending.provider,
    sourcePublicKey: pending.sourcePublicKey,
    destinationPublicKey: pending.destinationPublicKey,
    walletIndex,
    amountSol: lamportsToSol(amountLamports)
  });
  return {
    wallet: webWalletRowFromRecord(wallet, walletIndex),
    wallets: await webWalletRows(userId),
    order: {
      walletFundingAttemptId,
      provider: pending.provider,
      sourcePublicKey: pending.sourcePublicKey,
      destinationPublicKey: pending.destinationPublicKey,
      walletIndex,
      amountSol: lamportsToSol(amountLamports),
      expiresAt,
      transaction: tx.serialize({ requireAllSignatures: false, verifySignatures: false }).toString("base64"),
      message: `Approve ${lamportsToSol(amountLamports)} SOL funding in ${pending.provider}.`
    }
  };
}

async function executeWebWalletFunding(userId, body = {}) {
  const walletFundingAttemptId = String(body.walletFundingAttemptId || "").trim();
  if (!walletFundingAttemptId) {
    const error = new Error("Missing wallet funding attempt ID.");
    error.statusCode = 400;
    throw error;
  }
  const signedTransaction = String(body.signedTransaction || "").trim();
  if (!/^[a-z0-9+/=]+$/i.test(signedTransaction) || signedTransaction.length < 100 || signedTransaction.length > 250_000) {
    const error = new Error("Signed wallet funding transaction is missing or invalid.");
    error.statusCode = 400;
    throw error;
  }

  const pending = await takePendingSessionWalletOrder(userId, walletFundingAttemptId, "wallet-funding");
  let tx;
  let stage = "decode";
  try {
    tx = Transaction.from(Buffer.from(signedTransaction, "base64"));
    stage = "verify";
    verifySessionWalletFundingTransaction(tx, pending);
    stage = "broadcast";
    const signature = await rpcWithRetry("send managed wallet funding", () => connection.sendRawTransaction(tx.serialize(), {
      skipPreflight: false,
      maxRetries: 10
    }), CONFIG.rpcRetries, { priority: true });
    stage = "confirm";
    await rpcWithRetry("confirm managed wallet funding", () => connection.confirmTransaction({
      signature,
      blockhash: pending.blockhash,
      lastValidBlockHeight: pending.lastValidBlockHeight
    }, "confirmed"), CONFIG.rpcRetries, { priority: true });

    const walletStore = await readWalletStore();
    const wallet = walletsForOwner(walletStore, userId).find((item) => item.publicKey === pending.destinationPublicKey);
    if (wallet) {
      wallet.fundingSignature = signature;
      wallet.fundingAmountLamports = pending.amountLamports;
      if (wallet.sessionWallet) {
        wallet.sessionStatus = "funded";
        wallet.sessionFundedAt = new Date().toISOString();
        wallet.sessionBudgetLamports = pending.amountLamports;
      }
      await writeWalletStore(walletStore);
      invalidateWalletReadCache(wallet.publicKey);
    }
    invalidateWalletReadCache(pending.sourcePublicKey);
    await completePendingSessionWalletOrder(pending, {
      status: "complete",
      signature,
      completedAt: new Date().toISOString()
    });
    await audit("web_wallet_funded", {
      userId,
      sourcePublicKey: pending.sourcePublicKey,
      destinationPublicKey: pending.destinationPublicKey,
      walletIndex: pending.walletIndex,
      amountSol: lamportsToSol(pending.amountLamports),
      signature
    });
    void recordFunnelMilestone(userId, { fundedAt: new Date().toISOString() });
    return {
      signature,
      wallet: wallet ? webWalletRowFromRecord(wallet, pending.walletIndex) : null,
      wallets: await webWalletRows(userId),
      message: `Wallet funded with ${lamportsToSol(pending.amountLamports)} SOL.`
    };
  } catch (error) {
    logWalletFundingFailure(pending, tx, error, stage);
    await completePendingSessionWalletOrder(pending, {
      status: "failed",
      error: friendlyError(error),
      failedAt: new Date().toISOString()
    }).catch(() => {});
    throw error;
  }
}

async function executeWebSessionWalletFunding(userId, body = {}) {
  const sessionWalletAttemptId = String(body.sessionWalletAttemptId || "").trim();
  if (!sessionWalletAttemptId) {
    const error = new Error("Missing session wallet funding attempt ID.");
    error.statusCode = 400;
    throw error;
  }
  const signedTransaction = String(body.signedTransaction || "").trim();
  if (!/^[a-z0-9+/=]+$/i.test(signedTransaction) || signedTransaction.length < 100 || signedTransaction.length > 250_000) {
    const error = new Error("Signed session wallet funding transaction is missing or invalid.");
    error.statusCode = 400;
    throw error;
  }

  const pending = await takePendingSessionWalletOrder(userId, sessionWalletAttemptId);
  let tx;
  let stage = "decode";
  try {
    tx = Transaction.from(Buffer.from(signedTransaction, "base64"));
    stage = "verify";
    verifySessionWalletFundingTransaction(tx, pending);
    stage = "broadcast";
    const signature = await rpcWithRetry("send session wallet funding", () => connection.sendRawTransaction(tx.serialize(), {
      skipPreflight: false,
      maxRetries: 10
    }), CONFIG.rpcRetries, { priority: true });
    stage = "confirm";
    await rpcWithRetry("confirm session wallet funding", () => connection.confirmTransaction({
      signature,
      blockhash: pending.blockhash,
      lastValidBlockHeight: pending.lastValidBlockHeight
    }, "confirmed"), CONFIG.rpcRetries, { priority: true });

    const walletStore = await readWalletStore();
    const wallet = walletsForOwner(walletStore, userId).find((item) => item.publicKey === pending.sessionWalletPublicKey);
    if (wallet) {
      wallet.sessionStatus = "funded";
      wallet.sessionFundedAt = new Date().toISOString();
      wallet.fundingSignature = signature;
      wallet.fundingAmountLamports = pending.amountLamports;
      wallet.sessionBudgetLamports = pending.amountLamports;
      await writeWalletStore(walletStore);
      invalidateWalletReadCache(wallet.publicKey);
    }
    invalidateWalletReadCache(pending.sourcePublicKey);
    await completePendingSessionWalletOrder(pending, {
      status: "complete",
      signature,
      completedAt: new Date().toISOString()
    });
    await audit("web_session_wallet_funded", {
      userId,
      sourcePublicKey: pending.sourcePublicKey,
      sessionWalletPublicKey: pending.sessionWalletPublicKey,
      walletIndex: pending.walletIndex,
      amountSol: lamportsToSol(pending.amountLamports),
      signature
    });
    return {
      signature,
      wallet: wallet ? webWalletRowFromRecord(wallet, pending.walletIndex) : null,
      wallets: await webWalletRows(userId),
      message: `Session wallet funded with ${lamportsToSol(pending.amountLamports)} SOL. It is now available for presets, Ogre A.I., TP/SL, timer exits, and sells.`
    };
  } catch (error) {
    logWalletFundingFailure(pending, tx, error, stage);
    await completePendingSessionWalletOrder(pending, {
      status: "failed",
      error: friendlyError(error),
      failedAt: new Date().toISOString()
    }).catch(() => {});
    throw error;
  }
}

async function restoreWebWalletBackup(userId, body = {}) {
  const text = String(body.backupText || body.text || "").trim();
  if (!text) {
    const error = new Error("Choose a backup file or paste backup text first.");
    error.statusCode = 400;
    throw error;
  }

  const backup = parseBackupPayload(text);
  const backupWallets = backupWalletList(backup);
  const store = await readWalletStore();
  const existing = new Set(walletsForOwner(store, userId).map((wallet) => wallet.publicKey));
  const restoredRecords = [];
  const skippedExisting = [];
  const errors = [];
  let skipped = 0;

  for (const [index, wallet] of backupWallets.entries()) {
    let record;
    try {
      record = walletRecordFromBackup(wallet, userId, index);
    } catch (error) {
      skipped += 1;
      errors.push(`Wallet ${index + 1}: ${friendlyBackupError(error)}`);
      continue;
    }

    if (existing.has(record.publicKey)) {
      skipped += 1;
      skippedExisting.push(`${record.label}: ${record.publicKey}`);
      continue;
    }

    store.wallets.push(record);
    existing.add(record.publicKey);
    restoredRecords.push(record);
  }

  if (restoredRecords.length === 0 && errors.length > 0) {
    throw new Error(`Backup parsed but no wallets could be restored. ${errors.slice(0, 3).join(" ")}`);
  }

  await writeWalletStore(store);
  const polyRecovery = await restorePolyRecoveryForUser(userId, backup?.polyRecovery).catch((error) => ({ restored: false, error: friendlyBackupError(error) }));
  await audit("web_restore_wallet_backup", {
    userId,
    backupId: backup?.backupId || backup?.id || "",
    groupLabel: backup?.groupLabel || "",
    restored: restoredRecords.length,
    skipped,
    errors: errors.slice(0, 5)
  });

  const refreshedPolyRecovery = restoredRecords.length > 0
    ? await polyRecoverySnapshotForUser(userId, restoredRecords).catch(() => basicPolyRecoverySnapshot(userId, restoredRecords))
    : null;
  const downloads = restoredRecords.length > 0
    ? webBackupDownloadsForWallets(
      userId,
      restoredRecords,
      backup?.groupLabel || "restored-wallets",
      "Automatic web backup after wallet restore.",
      refreshedPolyRecovery
    )
    : null;

  return {
    restoredCount: restoredRecords.length,
    skippedCount: skipped,
    skippedExisting: skippedExisting.slice(0, 25),
    errors: errors.slice(0, 10),
    polyRecovery,
    downloads,
    wallets: restoredRecords.map((wallet, index) => ({
      index: index + 1,
      label: wallet.label,
      publicKey: wallet.publicKey,
      shortPublicKey: shortMint(wallet.publicKey)
    })),
    message: `Restore complete: ${restoredRecords.length} wallet(s) restored, ${skipped} skipped.`
  };
}

function webBackupEligibleWallet(wallet, options = {}) {
  if (!wallet || wallet.volumeBot || wallet.ephemeral) return false;
  if (!wallet.sessionWallet) return true;
  // Funded session wallets are visible trade wallets and may hold user funds.
  // Pending sessions stay out of backup-all, but an explicitly selected one is
  // still recoverable from the balance-adjacent button.
  return Boolean(options.exactSelection || wallet.sessionStatus === "funded");
}

async function exportWebWalletBackup(userId, body = {}) {
  const store = await readWalletStore();
  const owned = walletsForOwner(store, userId);
  const eligible = owned.filter((wallet) => webBackupEligibleWallet(wallet));
  const requestedPublicKey = String(body.publicKey || body.walletPublicKey || "").trim();
  const rawRequestedIndex = body.walletIndex ?? body.index;
  const hasRequestedIndex = rawRequestedIndex !== undefined
    && rawRequestedIndex !== null
    && String(rawRequestedIndex).trim() !== "";
  const requestedIndex = hasRequestedIndex ? parseWebWalletIndex(rawRequestedIndex) : null;
  const byPublicKey = requestedPublicKey
    ? owned.find((wallet) => wallet.publicKey === requestedPublicKey)
    : null;
  const byIndex = requestedIndex ? owned[requestedIndex - 1] : null;

  if (requestedPublicKey && requestedIndex && byPublicKey?.publicKey !== byIndex?.publicKey) {
    const error = new Error("That wallet selection changed. Refresh Wallets and try again.");
    error.statusCode = 409;
    throw error;
  }

  const requestedWallet = byPublicKey || byIndex;
  if ((requestedPublicKey || requestedIndex) && (!requestedWallet || !webBackupEligibleWallet(requestedWallet, { exactSelection: true }))) {
    const error = new Error("That managed wallet is not available for backup. Refresh Wallets and try again.");
    error.statusCode = 400;
    throw error;
  }

  const wallets = requestedWallet ? [requestedWallet] : eligible;
  if (wallets.length === 0) {
    const error = new Error("No user-facing managed wallets found in this web account yet.");
    error.statusCode = 400;
    throw error;
  }

  const singleWallet = wallets.length === 1 && Boolean(requestedWallet);
  const groupLabel = singleWallet
    ? `current-web-wallet-${sanitizeFilenamePart(requestedWallet.label || shortMint(requestedWallet.publicKey))}`
    : "current-web-wallets";

  await audit("web_export_wallet_backup", {
    userId,
    walletCount: wallets.length,
    scope: singleWallet ? "active-wallet" : "all-managed",
    publicKeys: wallets.map((wallet) => wallet.publicKey)
  });

  return {
    walletCount: wallets.length,
    scope: singleWallet ? "active-wallet" : "all-managed",
    downloads: webBackupDownloadsForWallets(
      userId,
      wallets,
      groupLabel,
      singleWallet
        ? "Manual web recovery export for the active managed wallet."
        : "Manual web backup export for all user-facing managed wallets currently loaded in this account.",
      await polyRecoverySnapshotForUser(userId, wallets).catch(() => basicPolyRecoverySnapshot(userId, wallets))
    ),
    message: singleWallet
      ? `Backup ready for ${requestedWallet.label || shortMint(requestedWallet.publicKey)}.`
      : `Backup ready: ${wallets.length} managed wallet(s) exported.`
  };
}

async function importWebWallet(userId, body = {}) {
  const label = cleanLabel(String(body.label || "Imported Wallet"));
  const secret = String(body.secret || body.privateKey || "").trim();
  if (!secret) {
    const error = new Error("Paste a private key or JSON secret-key array first.");
    error.statusCode = 400;
    throw error;
  }

  const candidates = webImportSecretCandidates(secret);
  const importedRecords = [];
  const skippedExisting = [];
  const errors = [];

  // Read→append→write under the wallet-store lock: the `existing` set must reflect the SAME store we
  // write, and a concurrent create/import mustn't drop these records. Throwing inside skips the write.
  await mutateWalletStore((store) => {
    const existing = new Map(walletsForOwner(store, userId).map((wallet) => [wallet.publicKey, wallet]));
    for (const [index, candidate] of candidates.entries()) {
      let keypair;
      try {
        keypair = keypairFromSecret(candidate);
      } catch (error) {
        errors.push(`Key ${index + 1}: ${friendlyError(error)}`);
        continue;
      }

      const publicKey = keypair.publicKey.toBase58();
      if (existing.has(publicKey)) {
        skippedExisting.push(`${existing.get(publicKey).label}: ${publicKey}`);
        continue;
      }

      const recordLabel = candidates.length === 1 ? label : cleanLabel(`${label} ${importedRecords.length + 1}`);
      const record = walletRecord(recordLabel, keypair, userId);
      store.wallets.push(record);
      existing.set(publicKey, record);
      importedRecords.push(record);
    }

    if (importedRecords.length === 0) {
      const detail = [
        skippedExisting.length ? `${skippedExisting.length} already imported` : "",
        errors.length ? errors.slice(0, 3).join(" ") : ""
      ].filter(Boolean).join(". ");
      const error = new Error(detail ? `No new wallets were imported. ${detail}` : "No valid wallet private keys were found.");
      error.statusCode = skippedExisting.length && !errors.length ? 409 : 400;
      throw error;
    }
  });

  await audit("web_import_wallet", {
    userId,
    label,
    imported: importedRecords.length,
    skippedExisting: skippedExisting.length,
    errors: errors.slice(0, 5),
    publicKeys: importedRecords.map((record) => record.publicKey)
  });

  const downloads = webBackupDownloadsForWallets(
    userId,
    importedRecords,
    label,
    "Automatic web backup after wallet import."
  );

  const firstRecord = importedRecords[0];
  return {
    label: firstRecord.label,
    publicKey: firstRecord.publicKey,
    shortPublicKey: shortMint(firstRecord.publicKey),
    importedCount: importedRecords.length,
    skippedCount: skippedExisting.length + errors.length,
    skippedExisting: skippedExisting.slice(0, 25),
    errors: errors.slice(0, 10),
    wallets: importedRecords.map((record, index) => ({
      index: index + 1,
      label: record.label,
      publicKey: record.publicKey,
      shortPublicKey: shortMint(record.publicKey)
    })),
    downloads,
    message: `Imported ${importedRecords.length} wallet(s)${skippedExisting.length || errors.length ? `, skipped ${skippedExisting.length + errors.length}` : ""}.`
  };
}

function webImportSecretCandidates(secretText) {
  const text = String(secretText || "")
    .trim()
    .replace(/^```(?:json)?/i, "")
    .replace(/```$/i, "")
    .trim();
  const candidates = [
    ...looseSecretCandidates(text),
    ...[...text.matchAll(/\b[1-9A-HJ-NP-Za-km-z]{80,120}\b/g)].map((match) => match[0]),
    ...[...text.matchAll(/\[(?:\s*\d+\s*,){31,}\s*\d+\s*\]/g)].map((match) => match[0])
  ];

  if (!candidates.length) candidates.push(text);
  return [...new Set(candidates.map((item) => String(item || "").trim()).filter(Boolean))];
}

async function removeWebWallets(userId, body = {}) {
  const rawIndexes = Array.isArray(body.walletIndexes)
    ? body.walletIndexes
    : String(body.walletIndex || body.index || "")
      .split(/[,\s]+/)
      .filter(Boolean);
  const indexes = uniqueStrings(rawIndexes.map((item) => String(item).replace(/[^\d]/g, "")).filter(Boolean));
  if (!indexes.length && !(Array.isArray(body.publicKeys) && body.publicKeys.length)) {
    const error = new Error("Choose at least one wallet to remove.");
    error.statusCode = 400;
    throw error;
  }

  const store = await readWalletStore();
  const owned = walletsForOwner(store, userId);
  // Prefer removal by PUBLIC KEY: positional indexes shift after every removal,
  // so a stale UI row used to hit "Wallet N does not exist" or, worse, the
  // wrong wallet. Keys are stable no matter how the list renumbers.
  const requestedKeys = uniqueStrings((Array.isArray(body.publicKeys) ? body.publicKeys : [])
    .map((key) => String(key || "").trim()).filter(Boolean));
  const selected = requestedKeys.length
    ? requestedKeys.map((key) => {
      const wallet = owned.find((item) => item.publicKey === key);
      if (!wallet) {
        const error = new Error(`Wallet ${shortMint(key)} is not in your saved list (it may already be removed). Refresh and try again.`);
        error.statusCode = 400;
        throw error;
      }
      return wallet;
    })
    : indexes.map((index) => {
      const wallet = owned[Number.parseInt(index, 10) - 1];
      if (!wallet) {
        const error = new Error(`Wallet ${index} does not exist - the list may have renumbered. Refresh and try again.`);
        error.statusCode = 400;
        throw error;
      }
      return wallet;
  });
  const selectedPublicKeys = new Set(selected.map((wallet) => wallet.publicKey));
  const planStore = await readTradePlans();
  const activeVolumeKeys = new Set();
  for (const plan of (planStore.plans || []).filter((entry) => activeVolumePlanForUser(entry, userId))) {
    if (plan.sourcePublicKey) activeVolumeKeys.add(plan.sourcePublicKey);
    if (plan.activeWalletPublicKey) activeVolumeKeys.add(plan.activeWalletPublicKey);
    for (const key of (plan.tradingPublicKeys || [])) activeVolumeKeys.add(key);
    for (const entry of (plan.pool || [])) if (entry?.publicKey) activeVolumeKeys.add(entry.publicKey);
  }
  const activeSelection = [...selectedPublicKeys].find((key) => activeVolumeKeys.has(key));
  if (activeSelection) {
    const error = new Error(`Wallet ${shortMint(activeSelection)} is part of an active SlimeBot run. Stop it and wait for the automatic sweep before removing the wallet.`);
    error.statusCode = 409;
    throw error;
  }
  const managedWallets = owned.filter((wallet) => !wallet.volumeBot && !wallet.ephemeral && !wallet.sessionWallet);
  const mainWallet = managedWallets[0];
  if (mainWallet && selectedPublicKeys.has(mainWallet.publicKey)) {
    const error = new Error("Your Main wallet stays with your account. Choose another wallet to remove.");
    error.statusCode = 400;
    throw error;
  }
  if (managedWallets.length && !managedWallets.some((wallet) => !selectedPublicKeys.has(wallet.publicKey))) {
    const error = new Error("Keep at least one wallet with your account.");
    error.statusCode = 400;
    throw error;
  }
  const downloads = webBackupDownloadsForWallets(
    userId,
    selected,
    "removed-web-wallets",
    "Automatic web backup before wallet removal."
  );

  const before = store.wallets.length;
  store.wallets = store.wallets.filter((wallet) => {
    return !(String(wallet.ownerId) === String(userId) && selectedPublicKeys.has(wallet.publicKey));
  });
  const removedCount = before - store.wallets.length;
  await writeWalletStore(store);
  await audit("web_remove_wallets", {
    userId,
    removedCount,
    wallets: selected.map(publicWallet)
  });

  return {
    removedCount,
    downloads,
    wallets: await webWalletRows(userId),
    message: `Removed ${removedCount} wallet record(s). Backup downloads started first. No SOL or tokens were moved.`
  };
}

function webBackupDownloadsForWallets(userId, wallets, groupLabel, note, polyRecovery = null) {
  if (!Array.isArray(wallets) || wallets.length === 0) return null;
  const encryptedBackup = buildWalletBackupDocument(userId, note, groupLabel, wallets, polyRecovery);
  const recoveryKeys = buildPrivateKeyDocument(
    userId,
    wallets,
    `solflare-recovery-${sanitizeFilenamePart(groupLabel)}-${userId}`,
    {
      title: "SOLFLARE / PHANTOM RECOVERY KEY FILE",
      note
    }
  );
  const evmRecoveryKeys = buildEvmPrivateKeyDocument(
    userId,
    wallets,
    `robinhood-eth-recovery-${sanitizeFilenamePart(groupLabel)}-${userId}`,
    { note }
  );

  return {
    encryptedBackup: {
      filename: encryptedBackup.filename,
      text: encryptedBackup.text
    },
    recoveryKeys: {
      filename: recoveryKeys.filename,
      text: recoveryKeys.text
    },
    evmRecoveryKeys: {
      filename: evmRecoveryKeys.filename,
      text: evmRecoveryKeys.text
    }
  };
}

// Normalize a laddered take-profit from a web body: array of {pct, sellPercent} (or bare pct numbers).
// Sorted ascending, sell percentages filled to sum ~100, capped at 8 rungs. [] when none/invalid.
function normalizeWebTakeProfitLadder(raw) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  for (const item of raw) {
    const pct = Number.parseFloat(item && typeof item === "object" ? (item.pct ?? item.takeProfitPct) : item);
    let sellPercent = Number.parseFloat(item && typeof item === "object" ? (item.sellPercent ?? item.sell) : NaN);
    if (!Number.isFinite(pct) || pct <= 0) continue;
    if (!Number.isFinite(sellPercent) || sellPercent <= 0) sellPercent = 0;
    out.push({ pct: Math.round(pct * 100) / 100, sellPercent: Math.min(100, Math.round(sellPercent)) });
  }
  if (!out.length) return [];
  out.sort((a, b) => a.pct - b.pct);
  const missing = out.filter((x) => !x.sellPercent);
  if (missing.length) {
    const used = out.reduce((s, x) => s + (x.sellPercent || 0), 0);
    const each = Math.max(1, Math.floor(Math.max(0, 100 - used) / missing.length));
    missing.forEach((x, i) => { x.sellPercent = (i === missing.length - 1) ? Math.max(1, 100 - used - each * (missing.length - 1)) : each; });
  }
  return out.slice(0, 8);
}

function webAutoExitRequested(body = {}) {
  if (webAutoExitExplicitlyDisabled(body)) return false;
  if (cleanLaunchBoolean(body.autoExit)) return true;
  if (normalizeWebTakeProfitLadder(body.takeProfitLadder).length) return true;

  const hasExitFields = body.takeProfitPct !== undefined
    || body.stopLossPct !== undefined
    || body.sellDelay !== undefined
    || body.sellDelaySeconds !== undefined
    || (Array.isArray(body.takeProfitLadder) && body.takeProfitLadder.length > 0);
  if (!hasExitFields) return false;

  const takeProfitPct = parseTakeProfitPercent(String(body.takeProfitPct || "0"));
  const stopLossPct = parseOptionalTriggerPercent(String(body.stopLossPct || "0"));
  const sellDelaySeconds = parseOptionalSellDelaySeconds(firstString(body.sellDelay, body.sellDelaySeconds, "off"));
  return Boolean(takeProfitPct || stopLossPct || sellDelaySeconds > 0);
}

function webActionableAutoExitRequested(body = {}) {
  if (webAutoExitExplicitlyDisabled(body)) return false;
  let takeProfitPct = 0;
  let stopLossPct = 0;
  let sellDelaySeconds = 0;
  try {
    takeProfitPct = parseTakeProfitPercent(String(body.takeProfitPct || "0"));
    stopLossPct = parseOptionalTriggerPercent(String(body.stopLossPct || "0"));
    sellDelaySeconds = parseOptionalSellDelaySeconds(firstString(body.sellDelay, body.sellDelaySeconds, "off"));
  } catch {
    return false;
  }
  return hasActionableExitSettings({
    takeProfitPct,
    stopLossPct,
    sellDelaySeconds,
    takeProfitLadder: normalizeWebTakeProfitLadder(body.takeProfitLadder),
    trailingStopPct: Number(body.trailingStopPct || 0)
  });
}

function webAutoExitExplicitlyDisabled(body = {}) {
  if (body.disableAutoExit !== undefined && cleanLaunchBoolean(body.disableAutoExit)) return true;
  if (body.autoExit === undefined) return false;
  const text = String(body.autoExit).trim().toLowerCase();
  return ["0", "false", "no", "off", "disabled"].includes(text) || body.autoExit === false;
}

function webQuickBuyAutoExitBody(body = {}) {
  if (webAutoExitExplicitlyDisabled(body)) return body;

  const requested = webActionableAutoExitRequested(body);
  const hasExitFields = body.takeProfitPct !== undefined
    || body.stopLossPct !== undefined
    || body.sellDelay !== undefined
    || body.sellDelaySeconds !== undefined;
  return {
    ...body,
    autoExit: true,
    takeProfitPct: firstString(body.takeProfitPct, hasExitFields ? "0" : "25"),
    stopLossPct: firstString(body.stopLossPct, hasExitFields ? "0" : "8"),
    sellDelay: firstString(body.sellDelay, body.sellDelaySeconds, "off"),
    sellPercent: firstString(body.sellPercent, "100"),
    defaultAutoExit: !requested
  };
}

function webProtectionRequiredError(message) {
  const error = new Error(message);
  error.statusCode = 409;
  return error;
}

async function resolveWebTradeProtectionBody(userId, body = {}) {
  const presetId = String(body.presetId || "").trim();
  const protectionRequired = cleanLaunchBoolean(body.protectionRequired);

  if (!presetId) {
    if (protectionRequired && webAutoExitExplicitlyDisabled(body)) {
      throw webProtectionRequiredError("This buy requires TP / SL protection, but the request also disabled automatic exits. Review the trade again.");
    }
    if (protectionRequired && !webActionableAutoExitRequested(body)) {
      throw webProtectionRequiredError("Your TP / SL settings were not available. The buy was not submitted; reload your preset and try again.");
    }
    return body;
  }

  if (webAutoExitExplicitlyDisabled(body)) {
    throw webProtectionRequiredError("The selected preset requires automatic exits. Choose Manual explicitly if you want an unprotected buy.");
  }
  const presets = await webPresetRows(userId);
  const preset = objectRows(presets.trade).find((row) => String(row.id || "") === presetId);
  if (!preset) {
    throw webProtectionRequiredError("That trade preset changed or is no longer available. Refresh presets before buying.");
  }

  const resolved = {
    ...body,
    presetId,
    protectionRequired: true,
    autoExit: true,
    takeProfitPct: String(preset.takeProfitPct || "0"),
    stopLossPct: String(preset.stopLossPct || "0"),
    sellDelay: String(preset.sellDelay || "off"),
    sellPercent: String(preset.sellPercent || "100"),
    slippageBps: String(preset.slippageBps || body.slippageBps || "400"),
    takeProfitLadder: normalizeWebTakeProfitLadder(preset.takeProfitLadder),
    // Saved trade presets currently own these basic exit fields. Never let
    // stale client-only advanced settings silently alter a reviewed preset.
    smartExits: false,
    trailingStopPct: 0,
    trailingActivatePct: 0,
    breakEvenAfterTp1: false,
    breakEvenStopPct: 0
  };
  if (!webActionableAutoExitRequested(resolved)) {
    throw webProtectionRequiredError("That preset has no active take-profit, stop-loss, timer, ladder, or trailing exit. The buy was not submitted.");
  }
  return resolved;
}

function webPreviewRawUi(raw, decimals = 0) {
  try { return rawTokenAmountToUi(BigInt(raw || 0), Number(decimals) || 0); }
  catch { return ""; }
}

function webPreviewMinimumRaw(order = {}, slippageBps = 0) {
  const direct = firstString(order.otherAmountThreshold, order.minimumOutAmount, order.minOutAmount);
  if (direct && /^\d+$/.test(direct)) return BigInt(direct);
  const output = BigInt(firstString(order.outAmount, order.outputAmount, "0") || 0);
  const bps = BigInt(Math.max(0, Math.min(9_900, Number(slippageBps) || 0)));
  return (output * (10_000n - bps)) / 10_000n;
}

async function simulateManagedSolanaPreview(tx, keypair) {
  if (!tx?.message || typeof tx.sign !== "function") {
    return { status: "route_verified", networkFeeLamports: 0, message: "Provider route built. Final network preflight runs again at submit." };
  }
  tx.sign([keypair]);
  const [feeResult, simulation] = await Promise.all([
    rpcWithRetry("preview transaction fee", () => connection.getFeeForMessage(tx.message, "confirmed"), 1, { priority: true }).catch(() => null),
    rpcWithRetry("simulate wallet transaction", () => connection.simulateTransaction(tx, { commitment: "processed", sigVerify: true }), 1, { priority: true })
  ]);
  if (simulation?.value?.err) {
    const message = simulation.value.logs?.slice(-3).join(" | ") || JSON.stringify(simulation.value.err);
    const error = new Error(`Simulation failed before any funds moved: ${String(message).slice(0, 420)}`);
    error.statusCode = 400;
    throw error;
  }
  return {
    status: "passed",
    networkFeeLamports: Math.max(0, Number(feeResult?.value || 0)),
    unitsConsumed: Math.max(0, Number(simulation?.value?.unitsConsumed || 0)),
    message: "On-chain simulation passed. No transaction was broadcast."
  };
}

async function pumpPortalPreviewTransaction({ keypair, tokenMint, side, amountSol = 0, percent = 100, slippageBps = 500 }) {
  const base = {
    publicKey: keypair.publicKey.toBase58(),
    action: side,
    mint: tokenMint,
    denominatedInSol: side === "buy" ? "true" : "false",
    amount: side === "buy" ? Number(amountSol) : (Number(percent) >= 99.999 ? "100%" : `${Number(percent)}%`),
    slippage: Math.max(0.01, Math.min(50, Number(slippageBps || 500) / 100)),
    priorityFee: side === "buy" ? CONFIG.pumpLaunchPriorityFeeSol : CONFIG.tradeJitoExitTipSol
  };
  const errors = [];
  for (const pool of pumpPortalSellPoolAttempts(tokenMint)) {
    try {
      const tx = await requestPumpPortalLocalTransaction({ ...base, pool }, 12_000, { url: CONFIG.pumpPortalTradeLocalUrl });
      const simulation = await simulateManagedSolanaPreview(tx, keypair);
      return { provider: `PumpPortal ${pool}`, simulation };
    } catch (error) {
      errors.push(`${pool}: ${friendlyError(error)}`);
    }
  }
  const error = new Error(`No executable Pump route passed preflight. ${errors.join(" | ")}`.slice(0, 680));
  error.statusCode = 400;
  throw error;
}

async function webSendSolPreview(userId, body = {}) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWalletAt(store, parseWebWalletIndex(body.walletIndex || body.fromWalletIndex), userId),
    body.walletPublicKey,
    "send preview"
  );
  const keypair = decryptWallet(wallet);
  const destination = parsePublicKey(String(body.destination || ""));
  if (destination.equals(keypair.publicKey)) throw new Error("That destination is this wallet.");
  const balance = Number(await getSolBalanceCached(keypair.publicKey, { force: true, priority: true }));
  const latest = await rpcWithRetry("preview send blockhash", () => connection.getLatestBlockhash("confirmed"), 1, { priority: true });
  const probe = new Transaction({ recentBlockhash: latest.blockhash, feePayer: keypair.publicKey }).add(SystemProgram.transfer({ fromPubkey: keypair.publicKey, toPubkey: destination, lamports: 1 }));
  const feeLamports = Math.max(0, Number(await estimateLegacyTransactionFee(probe)));
  const sendAll = cleanLaunchBoolean(body.sendAll);
  const amountLamports = sendAll ? balance - feeLamports : solToLamports(parsePositiveNumber(String(body.amountSol || body.amount || "")));
  if (amountLamports <= 0 || balance < amountLamports + feeLamports) throw new Error(`Not enough SOL. Balance ${lamportsToSol(balance)} SOL; send plus estimated fee needs ${lamportsToSol(amountLamports + feeLamports)} SOL.`);
  const tx = new Transaction({ recentBlockhash: latest.blockhash, feePayer: keypair.publicKey }).add(SystemProgram.transfer({ fromPubkey: keypair.publicKey, toPubkey: destination, lamports: amountLamports }));
  tx.sign(keypair);
  const simulation = await rpcWithRetry("simulate SOL send", () => connection.simulateTransaction(tx, [keypair]), 1, { priority: true });
  if (simulation?.value?.err) {
    const error = new Error(`Send simulation failed before funds moved: ${JSON.stringify(simulation.value.err)}`);
    error.statusCode = 400;
    throw error;
  }
  return {
    kind: "send",
    chain: "solana",
    side: "send",
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    destination: destination.toBase58(),
    inputLabel: "SOL",
    inputAmount: lamportsToSol(amountLamports),
    outputLabel: "SOL",
    estimatedOutput: lamportsToSol(amountLamports),
    minimumReceived: lamportsToSol(amountLamports),
    priceImpactPct: 0,
    appFee: "0 SOL",
    networkFee: `${lamportsToSol(feeLamports)} SOL estimated`,
    balanceAfter: `${lamportsToSol(balance - amountLamports - feeLamports)} SOL`,
    route: "Solana transfer",
    simulation: { status: "passed", message: "On-chain send simulation passed. Nothing was broadcast." },
    warnings: ["Confirm the full destination address. On-chain transfers cannot be reversed."],
    expiresAt: new Date(Date.now() + 45_000).toISOString()
  };
}

async function webSolTradePreview(userId, body = {}) {
  const side = String(body.side || "buy").toLowerCase();
  if (!['buy', 'sell'].includes(side)) throw new Error("Trade side must be buy or sell.");
  if (side === "buy") body = await resolveWebTradeProtectionBody(userId, body);
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWebServerTradeWalletAt(store, parseWebWalletIndex(body.walletIndex), userId, "trade preview"),
    body.walletPublicKey,
    "trade preview"
  );
  const keypair = decryptWallet(wallet);
  const tokenMint = parsePublicKey(String(body.tokenMint || body.token || "")).toBase58();
  const slippageBps = parseWebSlippage(body.slippageBps);
  const balance = Number(await getSolBalanceCached(keypair.publicKey, { force: true, priority: true }));
  let inputRaw = 0n;
  let amountLamports = 0;
  let feeLamports = 0;
  let outputRaw = 0n;
  let minimumRaw = 0n;
  let decimals = 0;
  let provider = "";
  let priceImpactPct = null;
  let simulation = null;
  let positionAdd = null;
  let unprotectedPositionAdd = null;
  let existingProtectionSummary = null;
  const warnings = [];

  if (side === "buy") {
    const swapOnly = webAutoExitExplicitlyDisabled(body);
    const eligibleAdd = await assertManagedSolBuyReentryAllowed(userId, [wallet], tokenMint, {
      // Both reviewed choices reuse the one authoritative position record.
      // A protected Buy merges into that record; Wallet Swap is explicitly
      // unprotected and leaves its exact protected lot/basis untouched.
      allowPositionAdd: true,
      // Preview is deliberately read-only. The confirmed-empty record is
      // retired only by the serialized submit path after the user confirms.
      persistEmptyRetirement: false
    });
    if (eligibleAdd) {
      existingProtectionSummary = eligibleAdd.existingProtectionSummary;
      if (swapOnly) {
        unprotectedPositionAdd = {
          planId: eligibleAdd.plan.id,
          summary: "Swap only: these new tokens will stay manual. The existing automatic exit continues to cover only its previously protected token amount."
        };
        warnings.push("This coin already has protected tokens in this wallet. This swap will not inherit, replace, or restart that TP / SL, and it will not create a second exit plan.");
      } else {
        positionAdd = {
          planId: eligibleAdd.plan.id,
          walletStateRevision: eligibleAdd.walletRevision,
          protectedLotRevision: eligibleAdd.protectedLotRevision,
          summary: eligibleAdd.existingProtectionSummary
        };
        warnings.push("This wallet already has one eligible protected position. Confirming will add the new tokens and cost basis to that position without changing its existing exit settings.");
      }
    }
    amountLamports = await webBuyAmountLamports(wallet, body);
    ({ feeLamports } = await calculateTradeFeeLamports(amountLamports, userId));
    const swapLamports = amountLamports - feeLamports;
    if (balance < recommendedBuyFundingLamports(amountLamports)) throw new Error(`Not enough SOL. Has ${lamportsToSol(balance)} SOL, needs about ${lamportsToSol(recommendedBuyFundingLamports(amountLamports))} SOL.`);
    const safety = await assertTokenBuyBaseSafety(tokenMint, { priority: true });
    decimals = Number(safety.safety?.decimals || 0);
    inputRaw = BigInt(swapLamports);

    const previewJupiterBuy = async () => {
      const order = await createJupiterOrder({ taker: keypair.publicKey, inputMint: SOL_MINT, outputMint: tokenMint, amount: swapLamports, slippageBps, priority: true, timeoutMs: 8_000, retries: 1 });
      outputRaw = BigInt(firstString(order.outAmount, order.outputAmount, "0") || 0);
      minimumRaw = webPreviewMinimumRaw(order, slippageBps);
      priceImpactPct = jupiterOrderPriceImpactPercent(order);
      provider = `Jupiter${order.router ? ` · ${order.router}` : ""}`;
      const tx = VersionedTransaction.deserialize(Buffer.from(order.transaction, "base64"));
      simulation = await simulateManagedSolanaPreview(tx, keypair);
    };
    const previewPumpBuy = async () => {
      const pump = await pumpPortalPreviewTransaction({ keypair, tokenMint, side: "buy", amountSol: lamportsToSol(swapLamports), slippageBps });
      provider = pump.provider;
      simulation = pump.simulation;
      warnings.push("This live Pump route does not expose an exact token amount until settlement; SlimeWallet will enforce the selected slippage on-chain.");
    };

    const token2022RouteRequired = safety.market?.token2022RouteRequired === true;
    const preferPumpPool = !token2022RouteRequired && isPumpBondingCurveBuy(tokenMint, safety.market);
    if (preferPumpPool) {
      // Match the actual execution engine: an ungraduated Pump coin belongs on
      // its live bonding curve. Jupiter's USD-reference impact can briefly read
      // near 100% while a new coin is still indexing, even though the exact Pump
      // transaction is valid. Simulate that exact transaction first; only try
      // Jupiter if Pump reports that the coin has migrated.
      try {
        await previewPumpBuy();
      } catch (pumpError) {
        try {
          await previewJupiterBuy();
        } catch (jupiterError) {
          throw wrapTradeExecutionError(
            jupiterError,
            `Pump preview failed: ${friendlyError(pumpError)}. Jupiter preview fallback failed: ${friendlyError(jupiterError)}`
          );
        }
      }
    } else {
      try {
        await previewJupiterBuy();
      } catch (jupiterError) {
        const reason = friendlyError(jupiterError);
        if (token2022RouteRequired || /blocked to protect you|simulation failed|price impact/i.test(reason)) throw jupiterError;
        await previewPumpBuy();
      }
    }
  } else {
    const token = await getReliableTokenBalanceForMint(keypair.publicKey, new PublicKey(tokenMint), { throwOnError: true, priority: true });
    if (!token || token.rawAmount <= 0n) throw new Error("This wallet holds none of that coin.");
    decimals = Number(token.decimals || 0);
    const percent = parsePercent(String(body.percent || "100"));
    inputRaw = sellAmountForPercent(token.rawAmount, percent);
    try {
      const order = await createJupiterOrder({ taker: keypair.publicKey, inputMint: tokenMint, outputMint: SOL_MINT, amount: inputRaw.toString(), slippageBps, priority: true, timeoutMs: 8_000, retries: 1 });
      outputRaw = BigInt(firstString(order.outAmount, order.outputAmount, "0") || 0);
      minimumRaw = webPreviewMinimumRaw(order, slippageBps);
      ({ feeLamports } = await calculateTradeFeeLamports(Number(outputRaw), userId));
      priceImpactPct = jupiterOrderPriceImpactPercent(order);
      provider = `Jupiter${order.router ? ` · ${order.router}` : ""}`;
      const tx = VersionedTransaction.deserialize(Buffer.from(order.transaction, "base64"));
      simulation = await simulateManagedSolanaPreview(tx, keypair);
    } catch (jupiterError) {
      const pump = await pumpPortalPreviewTransaction({ keypair, tokenMint, side: "sell", percent: Number(body.percent || 100), slippageBps });
      provider = pump.provider;
      simulation = pump.simulation;
      warnings.push("The Pump route passed on-chain simulation. Exact SOL proceeds are finalized by the bonding curve when submitted.");
    }
  }

  const networkFeeLamports = Math.max(0, Number(simulation?.networkFeeLamports || 0));
  const netOutputRaw = side === "sell" && outputRaw > BigInt(feeLamports) ? outputRaw - BigInt(feeLamports) : outputRaw;
  return {
    kind: "trade",
    chain: "solana",
    side,
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    token: tokenMint,
    inputLabel: side === "buy" ? "SOL" : "tokens",
    inputAmount: side === "buy" ? lamportsToSol(amountLamports) : webPreviewRawUi(inputRaw, decimals),
    outputLabel: side === "buy" ? "tokens" : "SOL",
    estimatedOutput: outputRaw > 0n ? (side === "buy" ? webPreviewRawUi(outputRaw, decimals) : lamportsBigToSol(netOutputRaw)) : "Finalized on-chain",
    minimumReceived: minimumRaw > 0n ? (side === "buy" ? webPreviewRawUi(minimumRaw, decimals) : lamportsBigToSol(minimumRaw > BigInt(feeLamports) ? minimumRaw - BigInt(feeLamports) : 0n)) : "Protected by slippage",
    priceImpactPct,
    appFee: `${lamportsToSol(feeLamports)} SOL`,
    networkFee: networkFeeLamports > 0 ? `${lamportsToSol(networkFeeLamports)} SOL estimated` : "Included in route preflight",
    balanceAfter: side === "buy" ? `${lamportsToSol(Math.max(0, balance - amountLamports - networkFeeLamports))} SOL` : `${lamportsToSol(balance + Number(netOutputRaw) - networkFeeLamports)} SOL estimated`,
    route: provider,
    simulation,
    warnings,
    ...(positionAdd ? {
      positionAdd,
      existingProtectionSummary
    } : {}),
    ...(unprotectedPositionAdd ? { unprotectedPositionAdd } : {}),
    expiresAt: new Date(Date.now() + 30_000).toISOString()
  };
}

async function webRhTradePreview(userId, body = {}) {
  if (String(body.side || "buy").toLowerCase() === "buy") {
    body = await resolveWebTradeProtectionBody(userId, body);
  }
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(getWalletAt(store, parseWebWalletIndex(body.walletIndex), userId), body.walletPublicKey, "Robinhood trade preview");
  const keypair = decryptWallet(wallet);
  const evmAddress = evmAddressFromSolana(keypair.secretKey);
  const tokenAddress = String(body.tokenAddress || body.token || "").trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(tokenAddress)) throw new Error("Invalid Robinhood token address.");
  const side = String(body.side || "buy").toLowerCase();
  if (!['buy', 'sell'].includes(side)) throw new Error("Trade side must be buy or sell.");
  const ETH = "0x0000000000000000000000000000000000000000";
  let fromCurrency = ETH;
  let toCurrency = tokenAddress;
  let amountRaw = 0n;
  let inputAmount = "";
  let solBalance = Number(await getSolBalanceCached(keypair.publicKey, { force: true, priority: true }));
  const warnings = [];
  let bridgeImpact = null;
  if (side === "buy") {
    const amountSol = Number(firstString(body.amountSol, body.amount));
    if (!Number.isFinite(amountSol) || amountSol < 0.005 || amountSol > 5) throw new Error("Enter a SOL amount between 0.005 and 5.");
    if (solBalance < solToLamports(amountSol) + CONFIG.buyReserveLamports) throw new Error(`Not enough SOL. Has ${lamportsToSol(solBalance)} SOL.`);
    const bridge = await relayQuoteSolToRhEth({ solanaAddress: keypair.publicKey.toBase58(), evmRecipient: evmAddress, lamports: solToLamports(amountSol) });
    const quotedEth = Number(bridge.outEth || 0);
    if (!(quotedEth > 0)) throw new Error("SOL to Robinhood funding quote returned no ETH.");
    const plan = await rhBuySpendPlan({ availableWei: rhWeiFromEthNumber(quotedEth).toString(), quotedEth, rpcUrl: CONFIG.rhChainRpcUrl });
    amountRaw = rhWeiFromEthNumber(Number(plan.spendEth || 0));
    if (CONFIG.baseTradeFeeBps > 0) amountRaw -= calculateTradeFeeAmount(amountRaw, CONFIG.baseTradeFeeBps);
    if (amountRaw <= 0n) throw new Error("This amount is too small after the live bridge and network reserve.");
    inputAmount = String(amountSol);
    bridgeImpact = Number.isFinite(Number(bridge.impactPercent)) ? Math.abs(Number(bridge.impactPercent)) : null;
    const safety = await rhHoneypotCheck(tokenAddress, CONFIG.rhChainRpcUrl).catch(() => null);
    if (safety?.verdict === "block") throw new Error(`Blocked to protect you: ${safety.reasons?.[0] || "this coin cannot be sold"}.`);
  } else {
    const percent = Math.min(100, Math.max(1, Number(body.percent || 100)));
    const balance = await rhErc20Balance(tokenAddress, evmAddress, CONFIG.rhChainRpcUrl);
    amountRaw = (BigInt(balance.raw || 0) * BigInt(Math.round(percent))) / 100n;
    if (amountRaw <= 0n) throw new Error("This wallet holds none of that Robinhood coin.");
    inputAmount = rawCashAmountToUi(amountRaw, Number(balance.decimals || 18));
    fromCurrency = tokenAddress;
    toCurrency = ETH;
  }
  const quoteAttempts = [
    ["Relay", () => relayQuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw })],
    ["Sushi V3", () => sushiV3QuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw, rpcUrl: CONFIG.rhChainRpcUrl })],
    ["Uniswap V3", () => uniswapQuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw, rpcUrl: CONFIG.rhChainRpcUrl })],
    ["Sushi API", () => sushiQuoteRhSwap({ address: evmAddress, fromCurrency, toCurrency, amountRaw })]
  ];
  const quoteResult = await firstSuccessfulRhQuote(quoteAttempts, 1);
  if (!quoteResult.quote) throw new Error(`No executable Robinhood route passed preflight. ${quoteResult.errors.join(" ")}`.slice(0, 680));
  const quote = quoteResult.quote;
  const provider = rhProvider(CONFIG.rhChainRpcUrl);
  let gasUnits = 0n;
  let simulatedSteps = 0;
  for (const tx of quote.txs || []) {
    try {
      gasUnits += await provider.estimateGas({ from: evmAddress, to: tx.to, data: tx.data || "0x", value: BigInt(tx.value || 0) });
      simulatedSteps += 1;
    } catch (error) {
      if (side === "buy" || simulatedSteps === 0) throw new Error(`Robinhood simulation failed before funds moved: ${friendlyError(error)}`);
      warnings.push("The approval step simulated successfully; the swap is quoted and will be re-estimated immediately after approval at submit.");
      break;
    }
  }
  const feeData = await provider.getFeeData().catch(() => ({}));
  const gasPrice = BigInt(feeData.maxFeePerGas || feeData.gasPrice || 0);
  const networkFeeWei = gasUnits * gasPrice;
  const outputNumber = Number(quote.outFormatted || 0);
  const minimumOutput = outputNumber > 0 ? outputNumber * 0.97 : 0;
  const platformFeeWei = side === "buy"
    ? calculateTradeFeeAmount(amountRaw, CONFIG.baseTradeFeeBps)
    : (outputNumber > 0 ? calculateTradeFeeAmount(rhWeiFromEthNumber(outputNumber), CONFIG.baseTradeFeeBps) : 0n);
  const impact = Number.isFinite(Number(quote.impactPercent)) ? Math.abs(Number(quote.impactPercent)) : bridgeImpact;
  return {
    kind: "trade",
    chain: "robinhood",
    side,
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    token: tokenAddress,
    inputLabel: side === "buy" ? "SOL" : "tokens",
    inputAmount,
    outputLabel: side === "buy" ? (quote.outSymbol || "tokens") : "SOL",
    estimatedOutput: side === "sell" ? `${outputNumber || 0} ETH before automatic SOL return` : String(quote.outFormatted || ""),
    minimumReceived: side === "sell" ? `${minimumOutput.toPrecision(6)} ETH before automatic SOL return` : minimumOutput.toPrecision(6),
    priceImpactPct: impact,
    appFee: `${rawCashAmountToUi(platformFeeWei, 18)} ETH`,
    networkFee: networkFeeWei > 0n ? `${rawCashAmountToUi(networkFeeWei, 18)} ETH maximum estimate` : "Re-estimated at submit",
    balanceAfter: side === "buy" ? `${lamportsToSol(Math.max(0, solBalance - solToLamports(inputAmount)))} SOL before network reserve` : "Sale automatically returns to this wallet as SOL",
    route: `${quoteResult.label}${quote.venue ? ` · ${quote.venue}` : ""}`,
    simulation: { status: simulatedSteps === (quote.txs || []).length ? "passed" : "route_verified", message: simulatedSteps === (quote.txs || []).length ? `All ${simulatedSteps} Robinhood transaction step${simulatedSteps === 1 ? "" : "s"} passed gas simulation. Nothing was broadcast.` : "Route and approval preflight passed; the swap is re-simulated after approval." },
    warnings,
    expiresAt: new Date(Date.now() + 30_000).toISOString()
  };
}

async function webTransactionPreview(userId, body = {}) {
  const kind = String(body.kind || "trade").trim().toLowerCase();
  if (kind === "send") return webSendSolPreview(userId, body);
  const chain = String(body.chain || "").toLowerCase();
  return chain === "robinhood" || /^0x[0-9a-fA-F]{40}$/.test(String(body.tokenAddress || body.token || ""))
    ? webRhTradePreview(userId, body)
    : webSolTradePreview(userId, body);
}

function managedSolBuyReentryError(decision, wallet) {
  const waitSeconds = decision.retryAfterMs
    ? Math.max(1, Math.ceil(decision.retryAfterMs / 1000))
    : null;
  const message = decision.reason === "stop_loss_closed_cooldown"
    ? `A stop-loss just closed this coin in ${wallet.label || "this wallet"}. Wait ${waitSeconds} second${waitSeconds === 1 ? "" : "s"}, then retry the buy.`
    : decision.reason === "exit_outcome_unknown"
    ? `An earlier automatic exit for this coin in ${wallet.label || "this wallet"} still has an unknown on-chain outcome. SlimeWire blocked this buy so that exit cannot sell the new tokens. Check Activity before retrying.`
    : decision.reason === "exit_submitting"
    ? `An automatic exit for this coin in ${wallet.label || "this wallet"} is submitting now. SlimeWire blocked this buy so the in-flight exit cannot sell the new tokens. Retry after it confirms.`
    : `This coin already has active automatic protection in ${wallet.label || "this wallet"}. Add to that exact protected position from the reviewed trade preview, or cancel and finish that exit so two full-position plans cannot sell the same bag.`;
  const error = new Error(message);
  error.statusCode = 409;
  if (waitSeconds) error.retryAfterSeconds = waitSeconds;
  return error;
}

function managedSolPositionAddSummary(plan, planWallet) {
  const timerAt = planWallet.sellAfterAt || plan.sellAfterAt || null;
  const timer = timerAt ? `timer ${new Date(timerAt).toISOString()}` : "timer off";
  return `Existing exits stay unchanged: TP ${formatPlanTakeProfitSummary(plan)}, SL ${formatPlanStopLossSummary(plan)}, ${timer}.`;
}

function managedSolPositionAddEligibility(userId, wallet, tokenMint, planStore, guardStore, receiptStore) {
  const decision = protectedPositionAddDecision({
    userId,
    walletPublicKey: wallet.publicKey,
    tokenMint
  }, objectRows(planStore.plans), objectRows(guardStore.guards), objectRows(receiptStore.receipts), {
    stopClosedCooldownMs: CONFIG.stopLossReentryCooldownMs
  });
  if (!decision.eligible) return null;
  return {
    plan: decision.plan,
    planWallet: decision.holder,
    walletRevision: tradePlanWalletStateRevision(decision.holder),
    protectedLotRevision: protectedLotRevision(decision.holder),
    existingProtectionSummary: managedSolPositionAddSummary(decision.plan, decision.holder)
  };
}

function managedSolBuyProtectionExits(tokenMint, planStore, guardStore, receiptStore) {
  const exits = [];
  const planTerminal = new Set(["canceled", "cancelled", "stopped", "closed", "completed"]);
  for (const plan of objectRows(planStore.plans)) {
    if (String(plan.tokenMint || "") !== String(tokenMint || "")) continue;
    if (planTerminal.has(String(plan.status || "").toLowerCase())) continue;
    for (const planWallet of objectRows(plan.wallets)) {
      exits.push({
        ...planWallet,
        userId: plan.userId,
        tokenMint: plan.tokenMint,
        planId: plan.id,
        source: plan.source
      });
    }
  }
  for (const guard of objectRows(guardStore.guards)) {
    if (["canceled", "cancelled", "completed"].includes(String(guard.status || guard.exitStatus || "").toLowerCase())) continue;
    exits.push(guard);
  }
  exits.push(...objectRows(receiptStore.receipts));
  return exits;
}

async function retireConfirmedEmptyManagedSolProtection(wallet, tokenMint, decision, options = {}) {
  if (!idleProtectionCanRetireAtConfirmedZero(decision)) return false;
  let token = null;
  try {
    token = await getReliableTokenBalanceForMint(
      new PublicKey(wallet.publicKey),
      new PublicKey(tokenMint),
      { throwOnError: true, priority: true }
    );
  } catch {
    return false;
  }
  if (BigInt(token?.rawAmount || 0) !== 0n || token?.tokenBalanceConfirmedZero !== true) return false;
  if (options.persist === false) return true;

  const now = new Date().toISOString();
  let retired = 0;
  await mutateTradePlans((store) => {
    for (const plan of objectRows(store.plans)) {
      if (String(plan.tokenMint || "") !== String(tokenMint || "")) continue;
      if (["canceled", "cancelled", "stopped", "closed", "completed"].includes(String(plan.status || "").toLowerCase())) continue;
      for (const holder of objectRows(plan.wallets)) {
        if (String(holder.publicKey || "") !== String(wallet.publicKey || "")) continue;
        if (!idleProtectionCanRetireAtConfirmedZero({ blocked: true, reason: "exit_active", row: holder })) continue;
        holder.status = "skipped";
        holder.exitStatus = "skipped";
        holder.triggerStatus = "no-live-token-balance";
        holder.triggerReason = "confirmed empty before a new buy";
        holder.noLiveTokenBalanceAt = now;
        holder.retryAfterAt = null;
        holder.nextRetryAt = null;
        holder.error = null;
        holder.lastError = null;
        holder.updatedAt = now;
        bumpTradePlanWalletStateRevision(holder, now);
        retired += 1;
      }
      if (objectRows(plan.wallets).length && objectRows(plan.wallets).every((holder) => !isActiveTimedWalletStatus(holder.status))) {
        plan.status = "completed";
        plan.completedAt = plan.completedAt || now;
        plan.updatedAt = now;
      }
    }
    return retired;
  });

  await mutateWebExitGuards((store) => {
    for (const guard of objectRows(store.guards)) {
      if (String(guard.tokenMint || "") !== String(tokenMint || "")) continue;
      if (String(guard.walletPublicKey || "") !== String(wallet.publicKey || "")) continue;
      if (!idleProtectionCanRetireAtConfirmedZero({ blocked: true, reason: "exit_active", row: guard })) continue;
      guard.status = "skipped";
      guard.exitStatus = "skipped";
      guard.triggerStatus = "no-live-token-balance";
      guard.triggerReason = "confirmed empty before a new buy";
      guard.noLiveTokenBalanceAt = now;
      guard.retryAfterAt = null;
      guard.nextRetryAt = null;
      guard.error = null;
      guard.lastError = null;
      guard.updatedAt = now;
      bumpTradePlanWalletStateRevision(guard, now);
      retired += 1;
    }
    return retired;
  });
  return retired > 0;
}

async function assertManagedSolBuyReentryAllowed(userId, wallets = [], tokenMint = "", options = {}) {
  let [planStore, guardStore, receiptStore] = await Promise.all([
    readTradePlans(),
    readWebExitGuards(),
    readSolExitReceipts()
  ]);
  let exits = managedSolBuyProtectionExits(tokenMint, planStore, guardStore, receiptStore);

  for (const wallet of wallets) {
    let decision = sameWalletTokenBuyBlockDecision({
      walletPublicKey: wallet.publicKey,
      tokenMint
    }, exits, {
      stopClosedCooldownMs: CONFIG.stopLossReentryCooldownMs
    });
    if (!decision.blocked) continue;
    const positionAdd = options.allowPositionAdd
      ? managedSolPositionAddEligibility(userId, wallet, tokenMint, planStore, guardStore, receiptStore)
      : null;
    if (positionAdd) return positionAdd;
    if (await retireConfirmedEmptyManagedSolProtection(wallet, tokenMint, decision, {
      persist: options.persistEmptyRetirement !== false
    })) {
      if (options.persistEmptyRetirement === false) continue;
      [planStore, guardStore, receiptStore] = await Promise.all([
        readTradePlans(),
        readWebExitGuards(),
        readSolExitReceipts()
      ]);
      exits = managedSolBuyProtectionExits(tokenMint, planStore, guardStore, receiptStore);
      decision = sameWalletTokenBuyBlockDecision({
        walletPublicKey: wallet.publicKey,
        tokenMint
      }, exits, {
        stopClosedCooldownMs: CONFIG.stopLossReentryCooldownMs
      });
      if (!decision.blocked) continue;
    }
    throw managedSolBuyReentryError(decision, wallet);
  }
  return null;
}

function managedSolBuyPositionLockName(userId, walletPublicKey, tokenMint) {
  // The on-chain wallet is the money identity. The same key imported under a
  // second account must not bypass an exit/buy lock by changing userId.
  return `managed-sol-buy-position:${String(walletPublicKey || "")}:${String(tokenMint || "")}`;
}

function managedSolBuyPositionBusyError() {
  const error = new Error("A buy or automatic exit is already being finalized for this wallet and coin. SlimeWire blocked this request so two full-position plans cannot overlap. Check Activity, then retry.");
  error.statusCode = 409;
  throw error;
}

async function withManagedSolBuyPositionLocks(userId, wallets = [], tokenMint = "", task) {
  const keys = [...new Set(wallets.map((wallet) => managedSolBuyPositionLockName(userId, wallet.publicKey, tokenMint)))].sort();
  const run = (index) => {
    if (index >= keys.length) return task();
    return withMoneyCacheLock(keys[index], 30 * 60_000, () => run(index + 1), managedSolBuyPositionBusyError);
  };
  return run(0);
}

async function webManagedSolBuyIdentity(userId, body = {}) {
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWebServerTradeWalletAt(store, parseWebWalletIndex(body.walletIndex), userId, "quick buy"),
    body.walletPublicKey,
    "buy"
  );
  const tokenMint = parsePublicKey(String(body.tokenMint || "")).toBase58();
  return { wallet, tokenMint };
}

function managedBuyProtectionKey(userId, walletPublicKey, tokenMint, body = {}) {
  const attemptId = firstString(body.tradeAttemptId, body.clientRequestId, crypto.randomUUID());
  return `buy-${crypto.createHash("sha256")
    .update([String(userId || ""), String(walletPublicKey || ""), String(tokenMint || ""), attemptId].join("\0"))
    .digest("hex")}`;
}

function positionAddClaimToken(planId, walletPublicKey, attemptId) {
  return `position-add-${crypto.createHash("sha256")
    .update([String(planId || ""), String(walletPublicKey || ""), String(attemptId || "")].join("\0"))
    .digest("hex")}`;
}

function positionAddPreviousState(plan, holder) {
  return {
    planStatus: plan.status,
    protectionIntent: plan.protectionIntent,
    status: holder.status,
    exitStatus: holder.exitStatus,
    triggerStatus: holder.triggerStatus,
    triggerReason: holder.triggerReason ?? null,
    triggerKind: holder.triggerKind ?? null,
    retryAfterAt: holder.retryAfterAt ?? null,
    nextRetryAt: holder.nextRetryAt ?? null,
    tokenOutAmount: String(holder.tokenOutAmount || ""),
    protectedTokenRemainingRaw: String(holder.protectedTokenRemainingRaw || ""),
    basisLamports: String(holder.basisLamports || ""),
    grossLamports: String(holder.grossLamports || ""),
    feeLamports: String(holder.feeLamports || "0"),
    preBuyTokenRawAmount: String(holder.preBuyTokenRawAmount ?? ""),
    buySignature: String(holder.buySignature || ""),
    walletRevision: tradePlanWalletStateRevision(holder),
    protectedLotRevision: protectedLotRevision(holder)
  };
}

function clearPositionAddReservation(holder, options = {}) {
  delete holder.buyReservationKind;
  delete holder.buyReservationAttemptId;
  delete holder.buyReservationStartedAt;
  delete holder.buyReservationExpectedWalletRevision;
  delete holder.buyReservationExpectedProtectedLotRevision;
  delete holder.buyReservationPreTokenRawAmount;
  delete holder.positionAddPreviousState;
  if (!options.preserveSubmission) {
    holder.buyReservationClaimToken = null;
    holder.buySubmissionSignature = null;
    holder.buySubmissionRequestId = null;
    holder.buySubmissionLastValidBlockHeight = null;
    holder.buySubmissionRecentBlockhash = null;
    holder.buySubmissionProvider = null;
    holder.buySubmissionSignedAt = null;
    holder.buySubmissionAmountLamports = null;
    holder.buySubmissionSwapLamports = null;
    holder.buySubmissionFeeLamports = null;
  }
}

function restorePositionAddHolder(plan, holder, resolution = "failed", errorText = "") {
  const previous = holder.positionAddPreviousState || {};
  const signature = String(holder.buySubmissionSignature || "").trim();
  const claimToken = String(holder.buyReservationClaimToken || "").trim();
  holder.status = previous.status || "watching";
  holder.exitStatus = previous.exitStatus || "watching";
  holder.triggerStatus = previous.triggerStatus || "armed";
  holder.triggerReason = previous.triggerReason ?? null;
  holder.triggerKind = previous.triggerKind ?? null;
  holder.retryAfterAt = previous.retryAfterAt ?? null;
  holder.nextRetryAt = previous.nextRetryAt ?? null;
  if (signature) {
    holder.resolvedBuySubmissionSignature = signature;
    holder.resolvedBuyReservationClaimToken = claimToken || null;
    holder.buySubmissionResolution = resolution;
    holder[`buySubmission${resolution === "expired" ? "Expired" : "Failed"}At`] = new Date().toISOString();
  }
  holder.lastPositionAddResolution = resolution;
  holder.lastPositionAddError = errorText || null;
  holder.lastError = errorText || null;
  clearPositionAddReservation(holder);
  const nowIso = new Date().toISOString();
  holder.updatedAt = nowIso;
  bumpTradePlanWalletStateRevision(holder, nowIso);
  plan.status = previous.planStatus || "watching";
  plan.protectionIntent = previous.protectionIntent || "armed";
  plan.updatedAt = nowIso;
}

async function claimManagedSolPositionAdd(userId, wallet, tokenMint, body, eligible, preTokenRawAmount) {
  const attemptId = firstString(body.tradeAttemptId, body.clientRequestId);
  if (!attemptId) {
    const error = new Error("A reviewed position add requires a stable trade attempt ID. Refresh the preview and confirm again.");
    error.statusCode = 409;
    throw error;
  }
  const requestedPlanId = String(body.addToProtectionPlanId || "").trim();
  const requestedWalletRevision = Number(body.addToProtectionWalletRevision);
  if (!requestedPlanId || !Number.isInteger(requestedWalletRevision) || requestedWalletRevision < 0) {
    const error = new Error("This position add was not authorized by a current trade preview. Refresh the preview before confirming.");
    error.statusCode = 409;
    throw error;
  }
  if (requestedPlanId !== String(eligible?.plan?.id || "")
    || requestedWalletRevision !== Number(eligible?.walletRevision)) {
    const error = new Error("The protected position changed after preview. Refresh it before adding funds.");
    error.statusCode = 409;
    throw error;
  }
  const claimToken = positionAddClaimToken(requestedPlanId, wallet.publicKey, attemptId);
  const claimed = await mutateTradePlans((store) => {
    const latestEligibility = protectedPositionAddDecision({
      userId,
      walletPublicKey: wallet.publicKey,
      tokenMint
    }, objectRows(store.plans), [], [], {
      stopClosedCooldownMs: CONFIG.stopLossReentryCooldownMs
    });
    const plan = objectRows(store.plans).find((row) => String(row.id || "") === requestedPlanId);
    const holder = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(wallet.publicKey || ""));
    if (!latestEligibility.eligible
      || String(latestEligibility.plan?.id || "") !== requestedPlanId
      || latestEligibility.holder !== holder
      || !plan || !holder
      || String(plan.userId || "") !== String(userId || "")
      || String(plan.tokenMint || "") !== String(tokenMint || "")
      || objectRows(plan.wallets).length !== 1
      || String(plan.status || "").toLowerCase() !== "watching"
      || String(holder.status || "").toLowerCase() !== "watching"
      || String(holder.exitStatus || "").toLowerCase() !== "watching"
      || holder.submissionClaimToken
      || holder.submissionSignature
      || holder.buyReservationClaimToken
      || holder.buySubmissionSignature
      || holder.manualSellClaimToken
      || !protectedPositionAddRevisionMatches(holder, requestedWalletRevision, eligible.protectedLotRevision)) {
      return null;
    }
    const previous = positionAddPreviousState(plan, holder);
    holder.buyReservationKind = "position_add";
    holder.buyReservationClaimToken = claimToken;
    holder.buyReservationAttemptId = attemptId;
    holder.buyReservationStartedAt = new Date().toISOString();
    holder.buyReservationExpectedWalletRevision = previous.walletRevision;
    holder.buyReservationExpectedProtectedLotRevision = previous.protectedLotRevision;
    holder.buyReservationPreTokenRawAmount = String(preTokenRawAmount);
    holder.positionAddPreviousState = previous;
    holder.status = "pending_buy";
    holder.exitStatus = "pending_buy";
    holder.triggerStatus = "pending_buy";
    holder.lastError = "Protected position add reserved before buy; waiting for a signed transaction checkpoint.";
    holder.updatedAt = new Date().toISOString();
    bumpTradePlanWalletStateRevision(holder, holder.updatedAt);
    plan.status = "pending_buy";
    plan.protectionIntent = "pending_buy";
    plan.updatedAt = holder.updatedAt;
    return {
      plan: JSON.parse(JSON.stringify(plan)),
      holder: JSON.parse(JSON.stringify(holder)),
      claimToken,
      attemptId,
      existingProtectionSummary: managedSolPositionAddSummary(plan, holder)
    };
  });
  if (!claimed) {
    const error = new Error("The protected position changed before the add-on reservation could be saved. Refresh the preview and try again.");
    error.statusCode = 409;
    error.tradePreSubmit = true;
    throw error;
  }
  return claimed;
}

async function checkpointManagedSolPositionAdd(planId, walletPublicKey, claimToken, submission) {
  return mutateTradePlans((store) => {
    const plan = objectRows(store.plans).find((row) => String(row.id || "") === String(planId || ""));
    const holder = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(walletPublicKey || ""));
    if (!plan || !holder
      || holder.buyReservationKind !== "position_add"
      || String(holder.buyReservationClaimToken || "") !== String(claimToken || "")
      || protectedLotRevision(holder) !== Number(holder.buyReservationExpectedProtectedLotRevision || 0)) return false;
    const nowIso = new Date().toISOString();
    holder.status = "arming";
    holder.exitStatus = "arming";
    holder.triggerStatus = "arming";
    holder.buySubmissionSignature = String(submission.signature || "");
    holder.buySubmissionRequestId = submission.requestId || null;
    holder.buySubmissionLastValidBlockHeight = submission.lastValidBlockHeight || null;
    holder.buySubmissionRecentBlockhash = submission.recentBlockhash || submission.blockhash || null;
    holder.buySubmissionProvider = submission.provider || null;
    holder.buySubmissionSignedAt = nowIso;
    holder.buySubmissionAmountLamports = positiveRawString(submission.amountLamports) || null;
    holder.buySubmissionSwapLamports = positiveRawString(submission.swapLamports) || null;
    holder.buySubmissionFeeLamports = String(positiveBigIntOrZero(submission.feeLamports));
    holder.lastError = "Protected position add signed; waiting for on-chain confirmation before exits reactivate.";
    holder.updatedAt = nowIso;
    bumpTradePlanWalletStateRevision(holder, nowIso);
    plan.updatedAt = nowIso;
    return true;
  });
}

function applyConfirmedPositionAdd(plan, holder, buy, boughtRaw) {
  const previous = holder.positionAddPreviousState || {};
  const update = protectedLotAfterConfirmedBuy({
    initialLotRaw: previous.tokenOutAmount,
    protectedLotRaw: previous.protectedTokenRemainingRaw,
    basisLamports: previous.basisLamports,
    grossLamports: previous.grossLamports,
    feeLamports: previous.feeLamports,
    boughtRaw,
    boughtBasisLamports: positiveRawString(buy.swapLamports),
    boughtGrossLamports: positiveRawString(buy.amountLamports),
    boughtFeeLamports: String(positiveBigIntOrZero(buy.feeLamports))
  });
  if (!update) return false;
  const nowIso = new Date().toISOString();
  holder.tokenOutAmount = update.initialRaw;
  holder.protectedTokenRemainingRaw = update.remainingRaw;
  holder.basisLamports = update.basisLamports;
  holder.grossLamports = update.grossLamports;
  holder.feeLamports = update.feeLamports;
  holder.preBuyTokenRawAmount = previous.preBuyTokenRawAmount;
  holder.buySignature = previous.buySignature;
  holder.positionAddBuySignatures = appendLimited(holder.positionAddBuySignatures, {
    signature: buy.signature,
    tokenAmount: update.boughtRaw,
    basisLamports: positiveRawString(buy.swapLamports),
    grossLamports: positiveRawString(buy.amountLamports),
    feeLamports: String(positiveBigIntOrZero(buy.feeLamports)),
    confirmedAt: nowIso
  });
  upsertManagedSolPositionAddReceipt(holder, {
    signature: buy.signature,
    source: "web_trade_position_add",
    tokenAmount: update.boughtRaw,
    basisLamports: positiveRawString(buy.swapLamports),
    grossLamports: positiveRawString(buy.amountLamports),
    feeLamports: String(positiveBigIntOrZero(buy.feeLamports)),
    protectionAttemptId: holder.buyReservationAttemptId || null,
    confirmedAt: nowIso,
    historyRecorded: false,
    historyRecordError: null
  });
  holder.lastPositionAddAttemptId = holder.buyReservationAttemptId || null;
  holder.lastPositionAddSignature = buy.signature;
  holder.lastPositionAddTokenAmount = update.boughtRaw;
  holder.status = previous.status || "watching";
  holder.exitStatus = previous.exitStatus || "watching";
  holder.triggerStatus = previous.triggerStatus || "armed";
  holder.triggerReason = null;
  holder.triggerKind = null;
  holder.lastCheckedAt = null;
  holder.lastTriggerCheckAt = null;
  holder.lastMovePct = null;
  holder.lastGrossMovePct = null;
  holder.lastNetMovePct = null;
  holder.lastEstimatedOut = null;
  holder.lastEstimatedNetOut = null;
  holder.peakMovePct = 0;
  holder.estimateFailures = 0;
  holder.lastError = null;
  clearConfirmedProtectedBuySubmission(holder, buy.signature);
  clearPositionAddReservation(holder);
  bumpProtectedLotRevision(holder, nowIso);
  bumpTradePlanWalletStateRevision(holder, nowIso);
  holder.updatedAt = nowIso;
  plan.status = previous.planStatus || "watching";
  plan.protectionIntent = previous.protectionIntent || "armed";
  plan.updatedAt = nowIso;
  return true;
}

async function finalizeManagedSolPositionAdd(planId, walletPublicKey, claimToken, buy, boughtRaw) {
  return mutateTradePlans((store) => {
    const plan = objectRows(store.plans).find((row) => String(row.id || "") === String(planId || ""));
    const holder = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(walletPublicKey || ""));
    if (!plan || !holder
      || holder.buyReservationKind !== "position_add"
      || String(holder.buyReservationClaimToken || "") !== String(claimToken || "")
      || String(holder.buySubmissionSignature || "") !== String(buy.signature || "")
      || protectedLotRevision(holder) !== Number(holder.buyReservationExpectedProtectedLotRevision || 0)) return null;
    if (!applyConfirmedPositionAdd(plan, holder, buy, boughtRaw)) return null;
    return { plan: JSON.parse(JSON.stringify(plan)), holder: JSON.parse(JSON.stringify(holder)) };
  });
}

function managedSolPositionAddReceiptEvent(plan, holder, receipt) {
  return {
    userId: plan.userId,
    type: "buy",
    source: receipt.source || "web_trade_position_add_recovery",
    tokenMint: plan.tokenMint,
    walletLabel: holder.label || "Managed wallet",
    walletPublicKey: holder.publicKey,
    solLamportsSpent: positiveRawString(receipt.grossLamports) || "0",
    tokenAmount: positiveRawString(receipt.tokenAmount),
    signature: receipt.signature,
    protectionAttemptId: receipt.protectionAttemptId || null,
    protectionPlanKey: firstString(plan.durablePlanKey, plan.id)
  };
}

async function upsertManagedSolPositionAddHistoryEvent(event = {}) {
  const signature = String(event.signature || "").trim();
  const tokenAmount = positiveRawString(event.tokenAmount);
  const solLamportsSpent = positiveRawString(event.solLamportsSpent);
  const source = String(event.source || "").trim();
  if (!signature || !tokenAmount || !solLamportsSpent || !source) return { complete: false, inserted: false };
  let result = { complete: false, inserted: false };
  await withFileLock(tradeHistoryPath(), async () => {
    const store = await readTradeHistory();
    let row = objectRows(store.trades).find((trade) => String(trade.signature || "") === signature);
    let changed = false;
    if (!row) {
      row = {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        ...event,
        tokenAmount: normalizeTradeHistoryAmount(tokenAmount),
        solLamportsSpent: normalizeTradeHistoryAmount(solLamportsSpent),
        source
      };
      store.trades.push(row);
      changed = true;
      result.inserted = true;
    } else {
      if (!positiveRawString(row.tokenAmount)) {
        row.tokenAmount = normalizeTradeHistoryAmount(tokenAmount);
        changed = true;
      }
      if (!positiveRawString(row.solLamportsSpent)) {
        row.solLamportsSpent = normalizeTradeHistoryAmount(solLamportsSpent);
        changed = true;
      }
      if (!String(row.source || "").trim()) {
        row.source = source;
        changed = true;
      }
    }
    result.complete = Boolean(
      positiveRawString(row.tokenAmount)
      && positiveRawString(row.solLamportsSpent)
      && String(row.source || "").trim()
    );
    if (changed) await writeJsonFile(tradeHistoryPath(), store);
  });
  return result;
}

async function updateManagedSolPositionAddReceiptHistory(planId, walletPublicKey, signature, patch = {}) {
  return mutateTradePlans((store) => {
    const plan = objectRows(store.plans).find((row) => String(row.id || "") === String(planId || ""));
    const holder = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(walletPublicKey || ""));
    const receipt = objectRows(holder?.positionAddReceipts).find((row) => String(row.signature || "") === String(signature || ""));
    if (!plan || !holder || !receipt) return false;
    Object.assign(receipt, patch, { historyUpdatedAt: new Date().toISOString() });
    holder.updatedAt = receipt.historyUpdatedAt;
    plan.updatedAt = receipt.historyUpdatedAt;
    return true;
  });
}

async function backfillManagedSolPositionAddHistory() {
  const snapshot = await readTradePlans();
  const pending = [];
  for (const plan of objectRows(snapshot.plans)) {
    for (const holder of objectRows(plan.wallets)) {
      for (const receipt of objectRows(holder.positionAddReceipts)) {
        const signature = String(receipt.signature || "").trim();
        if (!signature || receipt.historyRecorded === true) continue;
        pending.push({ plan, holder, receipt, signature });
      }
    }
  }
  let repaired = 0;
  for (const row of pending) {
    try {
      const event = managedSolPositionAddReceiptEvent(row.plan, row.holder, row.receipt);
      const history = await upsertManagedSolPositionAddHistoryEvent(event);
      if (!history.complete) continue;
      await updateManagedSolPositionAddReceiptHistory(row.plan.id, row.holder.publicKey, row.signature, {
        historyRecorded: true,
        historyRecordedAt: new Date().toISOString(),
        historyRecordError: null
      });
      repaired += 1;
    } catch (error) {
      await updateManagedSolPositionAddReceiptHistory(row.plan.id, row.holder.publicKey, row.signature, {
        historyRecorded: false,
        historyRecordError: friendlyError(error)
      }).catch(() => {});
    }
  }
  return repaired;
}

async function settleManagedSolPositionAddError(planId, walletPublicKey, claimToken, error) {
  const definitelyPreSubmit = error?.tradePreSubmit === true && !error?.tradeSubmissionAmbiguous;
  const ambiguous = !definitelyPreSubmit
    && Boolean(error?.tradeSubmissionAmbiguous || error?.signature || error?.transactionSignature);
  return mutateTradePlans((store) => {
    const plan = objectRows(store.plans).find((row) => String(row.id || "") === String(planId || ""));
    const holder = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(walletPublicKey || ""));
    if (!plan || !holder || String(holder.buyReservationClaimToken || "") !== String(claimToken || "")) return false;
    const signature = firstString(error?.signature, error?.transactionSignature, error?.partialHashes?.[0], holder.buySubmissionSignature);
    if (definitelyPreSubmit || (!ambiguous && !signature)) {
      restorePositionAddHolder(plan, holder, "failed", `Position add did not submit: ${friendlyError(error)}`);
      return true;
    }
    const nowIso = new Date().toISOString();
    holder.status = "outcome_unknown";
    holder.exitStatus = "outcome_unknown";
    holder.triggerStatus = "outcome_unknown";
    holder.buySubmissionSignature = signature || holder.buySubmissionSignature || null;
    holder.buySubmissionProvider = error?.provider || holder.buySubmissionProvider || null;
    const message = `Protected position add outcome is unknown; no replay will be sent. ${friendlyError(error)}`;
    holder.lastError = message;
    holder.updatedAt = nowIso;
    bumpTradePlanWalletStateRevision(holder, nowIso);
    plan.status = "pending_buy";
    plan.protectionIntent = "pending_buy";
    plan.lastError = "A protected position add needs on-chain reconciliation before exits can resume.";
    plan.updatedAt = nowIso;
    return true;
  });
}

async function updateManagedBuyProtectionIntent(durablePlanKey, patch = {}) {
  const key = String(durablePlanKey || "").trim();
  if (!key) return null;
  return mutateTradePlans((store) => {
    const plan = objectRows(store.plans).find((row) => String(row.durablePlanKey || "") === key);
    if (!plan) return null;
    Object.assign(plan, patch, { updatedAt: new Date().toISOString() });
    for (const wallet of objectRows(plan.wallets)) {
      if (patch.status) wallet.status = patch.status;
      if (patch.exitStatus || patch.status) wallet.exitStatus = patch.exitStatus || patch.status;
      if (patch.triggerStatus || patch.status) wallet.triggerStatus = patch.triggerStatus || patch.status;
      if (patch.lastError !== undefined) wallet.lastError = patch.lastError;
      if (patch.buySignature) wallet.buySignature = patch.buySignature;
      if (patch.tokenOutAmount) wallet.tokenOutAmount = patch.tokenOutAmount;
      if (patch.protectedTokenRemainingRaw !== undefined) wallet.protectedTokenRemainingRaw = patch.protectedTokenRemainingRaw;
      if (patch.preBuyTokenRawAmount !== undefined) wallet.preBuyTokenRawAmount = patch.preBuyTokenRawAmount;
      if (patch.basisLamports) wallet.basisLamports = patch.basisLamports;
      if (patch.grossLamports) wallet.grossLamports = patch.grossLamports;
      if (patch.feeLamports) wallet.feeLamports = patch.feeLamports;
      if (patch.submissionSignature) wallet.submissionSignature = patch.submissionSignature;
      if (patch.submissionRequestId !== undefined) wallet.submissionRequestId = patch.submissionRequestId;
      if (patch.submissionLastValidBlockHeight !== undefined) wallet.submissionLastValidBlockHeight = patch.submissionLastValidBlockHeight;
      if (patch.submissionRecentBlockhash !== undefined) wallet.submissionRecentBlockhash = patch.submissionRecentBlockhash;
      if (patch.submissionProvider !== undefined) wallet.submissionProvider = patch.submissionProvider;
      if (patch.submissionSignedAt) wallet.submissionSignedAt = patch.submissionSignedAt;
      if (patch.buyReservationClaimToken !== undefined) wallet.buyReservationClaimToken = patch.buyReservationClaimToken;
      if (patch.buySubmissionSignature !== undefined) wallet.buySubmissionSignature = patch.buySubmissionSignature;
      if (patch.buySubmissionRequestId !== undefined) wallet.buySubmissionRequestId = patch.buySubmissionRequestId;
      if (patch.buySubmissionLastValidBlockHeight !== undefined) wallet.buySubmissionLastValidBlockHeight = patch.buySubmissionLastValidBlockHeight;
      if (patch.buySubmissionRecentBlockhash !== undefined) wallet.buySubmissionRecentBlockhash = patch.buySubmissionRecentBlockhash;
      if (patch.buySubmissionProvider !== undefined) wallet.buySubmissionProvider = patch.buySubmissionProvider;
      if (patch.buySubmissionSignedAt !== undefined) wallet.buySubmissionSignedAt = patch.buySubmissionSignedAt;
      if (patch.resolvedBuySubmissionSignature !== undefined) wallet.resolvedBuySubmissionSignature = patch.resolvedBuySubmissionSignature;
      if (patch.resolvedBuyReservationClaimToken !== undefined) wallet.resolvedBuyReservationClaimToken = patch.resolvedBuyReservationClaimToken;
      if (patch.buySubmissionResolution !== undefined) wallet.buySubmissionResolution = patch.buySubmissionResolution;
      if (patch.buySubmissionConfirmedAt !== undefined) wallet.buySubmissionConfirmedAt = patch.buySubmissionConfirmedAt;
    }
    return plan;
  });
}

function upsertManagedSolPositionAddReceipt(holder, receipt = {}) {
  const signature = String(receipt.signature || "").trim();
  if (!signature) return null;
  const rows = objectRows(holder.positionAddReceipts);
  const existing = rows.find((row) => String(row.signature || "") === signature);
  if (existing) {
    Object.assign(existing, receipt, {
      signature,
      historyRecorded: existing.historyRecorded === true || receipt.historyRecorded === true
    });
    holder.positionAddReceipts = rows;
    return existing;
  }
  holder.positionAddReceipts = appendLimited(rows, { ...receipt, signature });
  return holder.positionAddReceipts.find((row) => String(row.signature || "") === signature) || null;
}

async function markManagedSolPositionAddNeedsAttention(planId, walletPublicKey, claimToken, message, receipt = null) {
  return mutateTradePlans((store) => {
    const plan = objectRows(store.plans).find((row) => String(row.id || "") === String(planId || ""));
    const holder = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(walletPublicKey || ""));
    if (!plan || !holder || String(holder.buyReservationClaimToken || "") !== String(claimToken || "")) return false;
    const nowIso = new Date().toISOString();
    holder.status = "needs_attention";
    holder.exitStatus = "needs_attention";
    holder.triggerStatus = "needs_attention";
    if (receipt?.signature) upsertManagedSolPositionAddReceipt(holder, receipt);
    holder.lastError = message;
    holder.updatedAt = nowIso;
    bumpTradePlanWalletStateRevision(holder, nowIso);
    plan.status = "pending_buy";
    plan.protectionIntent = "pending_buy";
    plan.lastError = message;
    plan.updatedAt = nowIso;
    return true;
  });
}

async function executeManagedSolPositionAdd(userId, wallet, tokenMint, body, eligible) {
  const slippageBps = parseWebSlippage(body.slippageBps);
  const amountLamports = await webBuyAmountLamports(wallet, body);
  const preTokenRawAmount = await readProtectedBuyTokenBaselineRaw(wallet, tokenMint);
  const oldBaseline = BigInt(eligible.planWallet.preBuyTokenRawAmount || 0);
  const protectedRemaining = BigInt(eligible.planWallet.protectedTokenRemainingRaw || 0);
  if (BigInt(preTokenRawAmount) - oldBaseline < protectedRemaining) {
    const error = new Error("The protected token balance changed after its last checkpoint. SlimeWire blocked this add-on until the position is reconciled.");
    error.statusCode = 409;
    throw error;
  }
  const claimed = await claimManagedSolPositionAdd(userId, wallet, tokenMint, body, eligible, preTokenRawAmount);
  let buy;
  try {
    buy = await buyTokenForPlan(wallet, tokenMint, amountLamports, slippageBps, {
      trackTokenDelta: true,
      tokenBeforeRawAmount: preTokenRawAmount,
      priority: true,
      userId,
      locallySignedOnly: true,
      rejectSignatureOnlyResponse: true,
      onSigned: async (submission) => {
        const saved = await checkpointManagedSolPositionAdd(
          claimed.plan.id,
          wallet.publicKey,
          claimed.claimToken,
          submission
        );
        if (!saved) {
          const error = new Error("The protected position changed before its signed add-on could be submitted.");
          error.tradePreSubmit = true;
          throw error;
        }
      }
    });
  } catch (error) {
    await settleManagedSolPositionAddError(claimed.plan.id, wallet.publicKey, claimed.claimToken, error).catch(() => {});
    throw error;
  }

  // The swap is already confirmed. Every bookkeeping/reconciliation step from
  // here down must degrade to needs_attention, never turn success into a
  // retryable request failure that could submit a second buy.
  const exactBoughtRaw = await readConfirmedBuyOwnerMintRawDelta(
    buy.signature,
    wallet.publicKey,
    tokenMint
  ).catch(() => null);
  const recordEvent = {
    userId,
    type: "buy",
    source: "web_trade_position_add",
    tokenMint,
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    solLamportsSpent: String(buy.amountLamports),
    tokenAmount: exactBoughtRaw,
    signature: buy.signature,
    protectionAttemptId: claimed.attemptId,
    protectionPlanKey: firstString(claimed.plan.durablePlanKey, claimed.plan.id)
  };
  const durableReceipt = {
    signature: buy.signature,
    source: "web_trade_position_add",
    tokenAmount: exactBoughtRaw,
    basisLamports: positiveRawString(buy.swapLamports),
    grossLamports: positiveRawString(buy.amountLamports),
    feeLamports: String(positiveBigIntOrZero(buy.feeLamports)),
    protectionAttemptId: claimed.attemptId,
    confirmedAt: new Date().toISOString(),
    historyRecorded: false,
    historyRecordError: null
  };
  let finalized = null;
  if (exactBoughtRaw) {
    finalized = await finalizeManagedSolPositionAdd(
      claimed.plan.id,
      wallet.publicKey,
      claimed.claimToken,
      buy,
      exactBoughtRaw
    ).catch(() => null);
  }
  let positionAddError = "";
  if (!finalized) {
    positionAddError = exactBoughtRaw
      ? "The buy confirmed, but the protected lot changed before its exact add-on could be merged. Automatic exits are paused for reconciliation."
      : "The buy confirmed, but its exact owner/mint token delta is still indexing. Automatic exits are paused until reconciliation proves the added amount.";
    await markManagedSolPositionAddNeedsAttention(
      claimed.plan.id,
      wallet.publicKey,
      claimed.claimToken,
      positionAddError,
      durableReceipt
    ).catch(() => {});
  }
  let recordError = "";
  if (!positiveRawString(exactBoughtRaw)) {
    recordError = "The confirmed top-up is waiting for its exact token amount before Activity can be completed.";
    await updateManagedSolPositionAddReceiptHistory(claimed.plan.id, wallet.publicKey, buy.signature, {
      historyRecorded: false,
      historyRecordError: recordError
    }).catch(() => {});
  } else {
    try {
      await recordTradeEvents([recordEvent]);
      const marked = await updateManagedSolPositionAddReceiptHistory(claimed.plan.id, wallet.publicKey, buy.signature, {
        historyRecorded: true,
        historyRecordedAt: new Date().toISOString(),
        historyRecordError: null
      });
      if (!marked) recordError = "The confirmed top-up is recorded in Activity, but its durable receipt still needs reconciliation.";
    } catch (error) {
      recordError = friendlyError(error);
      await updateManagedSolPositionAddReceiptHistory(claimed.plan.id, wallet.publicKey, buy.signature, {
        historyRecorded: false,
        historyRecordError: recordError
      }).catch(() => {});
    }
  }
  if (finalized) await safeArmWebExitGuardsForPlan(finalized.plan, [finalized.holder]).catch(() => {});
  scheduleTradePlanProcessing("protected position add", [250, 750, 1500, 3000, 6000]);
  void audit("web_trade_position_add", {
    userId,
    planId: claimed.plan.id,
    tokenMint,
    wallet: publicWallet(wallet),
    signature: buy.signature,
    tokenAmount: exactBoughtRaw,
    positionAddApplied: Boolean(finalized),
    error: positionAddError || null,
    recordError: recordError || null
  }).catch(() => {});

  const baseMessage = `${wallet.label} bought ${shortMint(tokenMint)} with ${lamportsToSol(buy.amountLamports)} SOL.`;
  return {
    type: "buy",
    tokenMint,
    shortMint: shortMint(tokenMint),
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    spentSol: lamportsToSol(buy.amountLamports),
    netSwapSol: lamportsToSol(buy.swapLamports),
    feeSol: lamportsToSol(buy.feeLamports),
    tokenAmount: exactBoughtRaw,
    signature: buy.signature,
    attempts: buy.attempts,
    dexUrl: dexScreenerUrl(tokenMint),
    autoExitRequested: true,
    autoExitArmed: Boolean(finalized),
    autoExitError: positionAddError,
    autoExitPlan: finalized ? {
      id: finalized.plan.id,
      existing: true,
      tokenMint,
      shortMessage: "Added to the existing protected position; its reviewed TP/SL settings were preserved."
    } : null,
    positionAddApplied: Boolean(finalized),
    recordError,
    existingProtectionSummary: claimed.existingProtectionSummary,
    message: finalized
      ? `${baseMessage} Added to the existing protected position without changing its exits.`
      : `${baseMessage} ${positionAddError}`
  };
}

// Idempotency wrapper for web buys. The terminal stamps every buy with `tradeAttemptId`; without this a
// network retry, the postTrade 403-retry, or a multi-tab/multi-device resend each fired a SECOND real
// buy. Mirrors the proven sell dedup (runManualSellCriticalAttempt): cached-result replay for repeats,
// a short lock so two truly-concurrent requests can't both spend. Back-compat: no id → runs core as-is.
async function webTradeBuy(userId, body = {}) {
  return runIdempotentMoneyOp("web-buy", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    async () => {
      const { wallet, tokenMint } = await webManagedSolBuyIdentity(userId, body);
      return withManagedSolBuyPositionLocks(userId, [wallet], tokenMint, () => webTradeBuyCore(userId, body));
    },
    { busyMessage: "This buy is already submitting — SlimeWire won't send a duplicate order.", ttlMs: 24 * 60 * 60_000 });
}

async function webTradeBuyCore(userId, body = {}) {
  body = await resolveWebTradeProtectionBody(userId, body);
  const store = await readWalletStore();
  const wallet = assertFrozenManagedWallet(
    getWebServerTradeWalletAt(store, parseWebWalletIndex(body.walletIndex), userId, "quick buy"),
    body.walletPublicKey,
    "buy"
  );
  const tokenMint = parsePublicKey(String(body.tokenMint || "")).toBase58();
  const requestedPositionAdd = Boolean(String(body.addToProtectionPlanId || "").trim());
  const unprotectedAddRequested = webAutoExitExplicitlyDisabled(body);
  if (requestedPositionAdd && unprotectedAddRequested) {
    const error = new Error("A swap-only buy cannot join an automatic TP / SL plan. Review it from Buy with protection, or finish the existing exit first.");
    error.statusCode = 409;
    throw error;
  }
  const eligiblePositionAdd = await assertManagedSolBuyReentryAllowed(userId, [wallet], tokenMint, {
    // A swap-only add is allowed only through the same strict single-plan,
    // idle-holder eligibility check as a protected add. The wallet+mint money
    // lock is already held, so no automatic exit can race this broadcast.
    allowPositionAdd: requestedPositionAdd || unprotectedAddRequested
  });
  if (requestedPositionAdd) {
    if (!eligiblePositionAdd) {
      const error = new Error("That protected position is no longer active. Refresh the preview before confirming this add-on.");
      error.statusCode = 409;
      throw error;
    }
    await requireWebAutomationPermission(userId, "protected position add");
    return executeManagedSolPositionAdd(userId, wallet, tokenMint, body, eligiblePositionAdd);
  }
  const slippageBps = parseWebSlippage(body.slippageBps);
  const autoExitBody = webQuickBuyAutoExitBody(body);
  const autoExitRequested = webActionableAutoExitRequested(autoExitBody);
  const autoExitPermission = autoExitRequested
    ? await requireWebAutomationPermission(userId, "quick-buy auto exits")
    : null;
  const amountLamports = await webBuyAmountLamports(wallet, body);
  const preBuyTokenRawAmount = autoExitRequested
    ? await readProtectedBuyTokenBaselineRaw(wallet, tokenMint)
    : null;
  const protectionKey = autoExitRequested
    ? managedBuyProtectionKey(userId, wallet.publicKey, tokenMint, body)
    : "";
  if (autoExitRequested) {
    // Reserve the protection record before broadcasting. A disk/permission
    // failure now stops the buy before any SOL moves.
    await webCreateSingleTradeAutoExitPlan(userId, wallet, tokenMint, {
      amountLamports: String(amountLamports),
      swapLamports: String(amountLamports),
      feeLamports: "0",
      tokenDeltaAmount: null,
      outputAmount: null,
      preBuyTokenRawAmount,
      signature: ""
    }, autoExitBody, slippageBps, autoExitPermission, {
      durablePlanKey: protectionKey,
      source: "web_trade_auto_exit",
      pendingBuy: true
    });
  }
  // Capture the exact post-buy increase. PumpPortal does not always return an
  // output amount, and using the wallet's whole balance would make a new stop
  // capable of selling a pre-existing bag.
  let result;
  try {
    result = await buyTokenForPlan(wallet, tokenMint, amountLamports, slippageBps, {
      trackTokenDelta: autoExitRequested,
      tokenBeforeRawAmount: preBuyTokenRawAmount,
      priority: true,
      userId,
      onSigned: protectionKey
        ? async (submission) => {
          const signedAt = new Date().toISOString();
          const saved = await updateManagedBuyProtectionIntent(protectionKey, {
            status: "arming",
            exitStatus: "arming",
            triggerStatus: "arming",
            buySubmissionSignature: submission.signature,
            buySubmissionRequestId: submission.requestId || null,
            buySubmissionLastValidBlockHeight: submission.lastValidBlockHeight || null,
            buySubmissionRecentBlockhash: submission.recentBlockhash || submission.blockhash || null,
            buySubmissionProvider: submission.provider || null,
            buySubmissionSignedAt: signedAt,
            lastError: "Buy transaction signed; waiting for on-chain confirmation before protection activates."
          });
          if (!saved) {
            const persistError = new Error("Protection reservation disappeared before the buy could be submitted.");
            persistError.tradePreSubmit = true;
            throw persistError;
          }
        }
        : null
    });
  } catch (error) {
    if (protectionKey) {
      const partialSignatures = Array.isArray(error?.partialHashes)
        ? error.partialHashes.filter((value) => typeof value === "string")
        : [];
      const submissionSignature = firstString(
        error?.signature,
        error?.transactionSignature,
        ...partialSignatures
      );
      const ambiguous = Boolean(error?.tradeSubmissionAmbiguous || submissionSignature);
      await updateManagedBuyProtectionIntent(protectionKey, {
        status: ambiguous ? "outcome_unknown" : "failed",
        exitStatus: ambiguous ? "outcome_unknown" : "failed",
        triggerStatus: ambiguous ? "outcome_unknown" : "failed",
        buySubmissionSignature: submissionSignature || undefined,
        buySubmissionProvider: error?.provider || undefined,
        lastError: ambiguous
          ? `Buy submission outcome is unknown; no retry will be sent automatically. ${friendlyError(error)}`
          : `Buy did not submit; protection reservation released. ${friendlyError(error)}`
      }).catch(() => {});
    }
    throw error;
  }
  const tokenAmount = result.tokenDeltaAmount || result.outputAmount || null;

  let recordError = "";
  const recordTask = (async () => {
    try {
      await recordTradeEvents([{
      userId,
      type: "buy",
      source: "web_trade",
      tokenMint,
      walletLabel: wallet.label,
      walletPublicKey: wallet.publicKey,
      solLamportsSpent: String(result.amountLamports),
      tokenAmount,
      signature: result.signature,
      protectionAttemptId: firstString(body.tradeAttemptId, body.clientRequestId),
      protectionPlanKey: protectionKey
      }]);
    } catch (error) {
      recordError = friendlyError(error);
    }
  })();

  let autoExitPlan = null;
  let autoExitError = "";
  const autoExitTask = (async () => {
  if (autoExitRequested) {
    try {
      autoExitPlan = await webCreateSingleTradeAutoExitPlan(userId, wallet, tokenMint, result, autoExitBody, slippageBps, autoExitPermission, {
        durablePlanKey: protectionKey,
        source: "web_trade_auto_exit"
      });
    } catch (error) {
      // The swap is already on-chain. Return and cache the buy success so an
      // exit-plan persistence problem can never be mistaken for a failed buy.
      autoExitError = friendlyError(error);
      await updateManagedBuyProtectionIntent(protectionKey, {
        status: "needs_attention",
        exitStatus: "needs_attention",
        triggerStatus: "needs_attention",
        buySignature: result.signature,
        resolvedBuySubmissionSignature: result.signature,
        resolvedBuyReservationClaimToken: `buy-reservation-${crypto.createHash("sha256").update(protectionKey).digest("hex").slice(0, 32)}`,
        buySubmissionResolution: "confirmed",
        buySubmissionConfirmedAt: new Date().toISOString(),
        buySubmissionSignature: null,
        buyReservationClaimToken: null,
        tokenOutAmount: tokenAmount,
        ...(tokenAmount ? { protectedTokenRemainingRaw: tokenAmount } : {}),
        preBuyTokenRawAmount,
        basisLamports: positiveRawString(result.swapLamports) || String(amountLamports),
        grossLamports: String(result.amountLamports || amountLamports),
        feeLamports: positiveRawString(result.feeLamports) || "0",
        lastError: `Buy confirmed, but protection finalization needs recovery: ${autoExitError}`
      }).catch(() => {});
      void audit("web_trade_buy_auto_exit_failed", {
        userId,
        tokenMint,
        wallet: publicWallet(wallet),
        signature: result.signature,
        error: autoExitError
      }).catch(() => {});
    }
  }
  })();
  // The confirmed swap is authoritative. Persist its history and requested exit
  // protection concurrently; neither operation depends on the other's file.
  await Promise.all([recordTask, autoExitTask]);
  void audit("web_trade_buy", {
    userId,
    tokenMint,
    wallet: publicWallet(wallet),
    amountMode: String(body.amountMode || "").toLowerCase() === "max" ? "max" : "fixed",
    amountSol: lamportsToSol(result.amountLamports),
    slippageBps,
    signature: result.signature,
    recordError
  }).catch(() => {});
  const baseMessage = `${wallet.label} bought ${shortMint(tokenMint)} with ${lamportsToSol(result.amountLamports)} SOL.`;
  const unprotectedPositionAdd = Boolean(unprotectedAddRequested && eligiblePositionAdd);

  return {
    type: "buy",
    tokenMint,
    shortMint: shortMint(tokenMint),
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    spentSol: lamportsToSol(result.amountLamports),
    netSwapSol: lamportsToSol(result.swapLamports),
    feeSol: lamportsToSol(result.feeLamports),
    tokenAmount,
    signature: result.signature,
    attempts: result.attempts,
    recordError,
    dexUrl: dexScreenerUrl(tokenMint),
    autoExitRequested,
    autoExitDefaulted: Boolean(autoExitBody.defaultAutoExit),
    autoExitArmed: Boolean(autoExitPlan),
    autoExitError,
    autoExitPlan,
    unprotectedPositionAdd,
    existingProtectionSummary: unprotectedPositionAdd
      ? managedSolPositionAddSummary(eligiblePositionAdd.plan, eligiblePositionAdd.planWallet)
      : null,
    message: autoExitPlan
      ? `${baseMessage} ${autoExitPlan.shortMessage}`
      : autoExitError
        ? `${baseMessage} Auto-exit did not arm: ${autoExitError}`
        : unprotectedPositionAdd
          ? `${baseMessage} The new tokens remain manual; the existing TP / SL still covers only its original protected lot.`
          : baseMessage
  };
}

function normalizeBrowserTradeSide(value) {
  const side = String(value || "").trim().toLowerCase();
  if (side !== "buy" && side !== "sell") {
    const error = new Error("Browser wallet trade side must be buy or sell.");
    error.statusCode = 400;
    throw error;
  }
  return side;
}

async function connectedWalletForBrowserTrade(userId, body = {}) {
  const profile = await webProfileForUser(userId);
  const connected = profile.connectedWallet || null;
  if (!connected?.publicKey) {
    const error = new Error("Connect Phantom, Solflare, or another browser wallet before trading.");
    error.statusCode = 400;
    throw error;
  }
  const publicKey = parsePublicKey(connected.publicKey).toBase58();
  const requested = String(body.walletPublicKey || "").trim();
  if (requested && parsePublicKey(requested).toBase58() !== publicKey) {
    const error = new Error("Connected wallet changed. Reconnect the wallet you want to trade with.");
    error.statusCode = 409;
    throw error;
  }
  return {
    ...connected,
    publicKey,
    provider: cleanConnectedWalletProvider(connected.provider || body.provider || "Browser Wallet")
  };
}

async function browserBuyAmountLamports(publicKey, body = {}) {
  if (String(body.amountMode || "").trim().toLowerCase() === "max") {
    const balance = await getSolBalanceCached(new PublicKey(publicKey), { force: true });
    const amountLamports = balance - CONFIG.buyReserveLamports;
    if (amountLamports <= 0) {
      throw new Error(`Not enough SOL after keeping ${CONFIG.buyReserveSol} SOL safety reserve.`);
    }
    return amountLamports;
  }
  return solToLamports(parsePositiveNumber(String(body.amountSol || "")));
}

async function browserSellAmountRaw(publicKey, tokenMint, percent) {
  const token = await getReliableTokenBalanceForMint(new PublicKey(publicKey), new PublicKey(tokenMint), {
    throwOnError: true,
    priority: true
  });
  if (!token || token.rawAmount <= 0n) {
    throw new Error("No live token balance for this connected wallet.");
  }
  const amount = sellAmountForPercent(token.rawAmount, percent, token.rawAmount.toString());
  if (amount <= 0n) throw new Error("Sell amount rounded to zero.");
  return { token, amount };
}

function pruneBrowserTradeOrders(orders = []) {
  const now = Date.now();
  return (Array.isArray(orders) ? orders : [])
    .filter((order) => Number(Date.parse(order.expiresAt || "")) > now || ["submitted", "complete"].includes(order.status))
    .slice(-100);
}

async function saveBrowserTradeOrder(order) {
  await mutateWebAuthStore((store) => {
    store.browserTradeOrders = pruneBrowserTradeOrders(store.browserTradeOrders);
    const index = store.browserTradeOrders.findIndex((item) => item.browserTradeAttemptId === order.browserTradeAttemptId);
    if (index >= 0) store.browserTradeOrders[index] = { ...store.browserTradeOrders[index], ...order };
    else store.browserTradeOrders.push(order);
  });
}

async function takePendingBrowserTradeOrder(userId, browserTradeAttemptId) {
  // Flip pending→submitting atomically under the store lock so two concurrent executes can't both see
  // "pending" and both submit. Errors are returned (not thrown) so the store write still persists the
  // expired-status update; the throw happens after the lock is released.
  const outcome = await mutateWebAuthStore((store) => {
    store.browserTradeOrders = pruneBrowserTradeOrders(store.browserTradeOrders);
    const order = store.browserTradeOrders.find((item) => (
      item.browserTradeAttemptId === browserTradeAttemptId
      && String(item.userId || "") === String(userId || "")
    ));
    if (!order) return { error: { message: "Browser wallet trade approval expired. Build the trade again.", status: 404 } };
    if (order.status !== "pending") return { error: { message: "This browser wallet trade was already submitted.", status: 409 } };
    if (Date.parse(order.expiresAt || "") <= Date.now()) {
      order.status = "expired";
      return { error: { message: "Browser wallet trade approval expired. Build the trade again.", status: 410 } };
    }
    order.status = "submitting";
    order.submittingAt = new Date().toISOString();
    return { order };
  });
  if (outcome.error) {
    const error = new Error(outcome.error.message);
    error.statusCode = outcome.error.status;
    throw error;
  }
  return outcome.order;
}

async function completePendingBrowserTradeOrder(order, patch = {}) {
  await saveBrowserTradeOrder({
    ...order,
    ...patch,
    updatedAt: new Date().toISOString()
  });
}

async function webBrowserTradeOrder(userId, body = {}) {
  const side = normalizeBrowserTradeSide(body.side);
  const connected = await connectedWalletForBrowserTrade(userId, body);
  const tokenMint = parsePublicKey(String(body.tokenMint || "")).toBase58();
  const slippageBps = parseWebSlippage(body.slippageBps);
  const browserTradeAttemptId = String(body.tradeAttemptId || crypto.randomUUID()).slice(0, 96) || crypto.randomUUID();
  let inputMint;
  let outputMint;
  let inputAmount;
  let order;
  let tokenAmount = "";

  // Connected-wallet platform fee (OFF unless configured). Embedded in the
  // swap the user signs, so it works without a server-side fee transfer.
  const referralAccount = CONFIG.connectedTradeFeeBps > 0 ? CONFIG.jupiterReferralAccount : "";
  const referralFee = referralAccount ? CONFIG.connectedTradeFeeBps : 0;

  if (side === "buy") {
    inputMint = SOL_MINT;
    outputMint = tokenMint;
    inputAmount = String(await browserBuyAmountLamports(connected.publicKey, body));
    order = await assertTokenBuySafety({
      tokenMint,
      taker: new PublicKey(connected.publicKey),
      buyLamports: inputAmount,
      slippageBps,
      referralAccount,
      referralFee
    });
  } else {
    const percent = parsePercent(String(body.percent || "100"));
    const sell = await browserSellAmountRaw(connected.publicKey, tokenMint, percent);
    inputMint = tokenMint;
    outputMint = SOL_MINT;
    inputAmount = sell.amount.toString();
    tokenAmount = inputAmount;
    order = await createJupiterOrder({
      taker: new PublicKey(connected.publicKey),
      inputMint,
      outputMint,
      amount: inputAmount,
      slippageBps,
      priority: true,
      timeoutMs: 8_000,
      retries: CONFIG.jupiterRetries,
      referralAccount,
      referralFee
    });
  }

  const now = new Date();
  const pending = {
    browserTradeAttemptId,
    userId,
    status: "pending",
    side,
    provider: connected.provider || "Browser Wallet",
    walletPublicKey: connected.publicKey,
    tokenMint,
    inputMint,
    outputMint,
    inputAmount,
    outputAmount: String(order.outAmount || order.outputAmount || ""),
    tokenAmount,
    slippageBps,
    requestId: order.requestId || "",
    lastValidBlockHeight: order.lastValidBlockHeight || null,
    router: order.router || "",
    mode: order.mode || "",
    createdAt: now.toISOString(),
    expiresAt: new Date(now.getTime() + 10 * 60 * 1000).toISOString()
  };
  await saveBrowserTradeOrder(pending);
  await audit("web_browser_trade_order", {
    userId,
    side,
    tokenMint,
    walletPublicKey: connected.publicKey,
    slippageBps,
    browserTradeAttemptId,
    router: pending.router,
    mode: pending.mode
  });

  return {
    browserTradeAttemptId,
    side,
    provider: pending.provider,
    walletPublicKey: pending.walletPublicKey,
    tokenMint,
    inputMint,
    outputMint,
    inputAmount,
    outputAmount: pending.outputAmount,
    requestId: pending.requestId,
    lastValidBlockHeight: pending.lastValidBlockHeight,
    transaction: order.transaction,
    message: `Approve ${side === "buy" ? "buy" : "sell"} in ${pending.provider}.`
  };
}

async function webBrowserTradeExecute(userId, body = {}) {
  const browserTradeAttemptId = String(body.browserTradeAttemptId || "").trim();
  if (!browserTradeAttemptId) {
    const error = new Error("Missing browser trade attempt ID.");
    error.statusCode = 400;
    throw error;
  }
  const signedTransaction = String(body.signedTransaction || "").trim();
  if (!/^[a-z0-9+/=]+$/i.test(signedTransaction) || signedTransaction.length < 100 || signedTransaction.length > 1_200_000) {
    const error = new Error("Signed wallet transaction is missing or invalid.");
    error.statusCode = 400;
    throw error;
  }

  const pending = await takePendingBrowserTradeOrder(userId, browserTradeAttemptId);
  let localSignature = "";
  try {
    const tx = VersionedTransaction.deserialize(Buffer.from(signedTransaction, "base64"));
    localSignature = bs58.encode(Buffer.from(tx.signatures[0]));
  } catch {
    // Jupiter currently returns v0 transactions. If that changes, the durable
    // request/order checkpoint still prevents a blind retry even without a
    // locally decoded signature.
  }
  let submissionStarted = false;
  try {
    await completePendingBrowserTradeOrder(pending, {
      status: "submitting",
      submissionSignature: localSignature || null,
      submissionStartedAt: new Date().toISOString()
    });
    submissionStarted = true;
    const execute = await jupiterFetchJson(`${CONFIG.jupiterApiBase}/execute`, {
      priority: true,
      timeoutMs: 20_000,
      method: "POST",
      headers: jupiterHeaders({ "Content-Type": "application/json" }),
      body: JSON.stringify({
        signedTransaction,
        requestId: pending.requestId,
        lastValidBlockHeight: pending.lastValidBlockHeight
      })
    }, "Jupiter browser wallet execute", CONFIG.jupiterRetries);

    if (execute.status && execute.status !== "Success") {
      throw new Error(execute.error || `Jupiter execute failed with code ${execute.code ?? "unknown"}.`);
    }
    if (!execute.signature) {
      throw new Error("Jupiter execute did not return a transaction signature.");
    }

    const outputAmount = String(execute.outputAmountResult || pending.outputAmount || "");
    // Checkpoint chain success before any ancillary history/audit work. Those
    // writes may be retried, but may never turn a landed trade into a failed
    // response that invites a duplicate order.
    let completionError = "";
    await completePendingBrowserTradeOrder(pending, {
      status: "submitted",
      signature: execute.signature,
      submissionSignature: execute.signature,
      outputAmount,
      completedAt: new Date().toISOString()
    }).catch((error) => { completionError = friendlyError(error); });
    let recordError = "";
    await recordTradeEvents([{
      userId,
      type: pending.side,
      source: "web_browser_wallet_trade",
      tokenMint: pending.tokenMint,
      walletLabel: pending.provider || "Browser Wallet",
      walletPublicKey: pending.walletPublicKey,
      solLamportsSpent: pending.side === "buy" ? pending.inputAmount : undefined,
      solLamportsReceived: pending.side === "sell" ? outputAmount : undefined,
      tokenAmount: pending.side === "buy" ? outputAmount : pending.tokenAmount,
      signature: execute.signature
    }]).catch((error) => { recordError = friendlyError(error); });
    await audit("web_browser_trade_execute", {
      userId,
      side: pending.side,
      tokenMint: pending.tokenMint,
      walletPublicKey: pending.walletPublicKey,
      browserTradeAttemptId,
      signature: execute.signature,
      router: pending.router,
      mode: pending.mode
    }).catch(() => {});
    invalidateWalletReadCache(pending.walletPublicKey);
    return {
      type: pending.side,
      source: "browser-wallet",
      tokenMint: pending.tokenMint,
      shortMint: shortMint(pending.tokenMint),
      walletLabel: pending.provider || "Browser Wallet",
      walletPublicKey: pending.walletPublicKey,
      shortPublicKey: shortMint(pending.walletPublicKey),
      spentSol: pending.side === "buy" ? lamportsBigToSol(pending.inputAmount || "0") : undefined,
      receivedSol: pending.side === "sell" && outputAmount ? lamportsBigToSol(outputAmount || "0") : undefined,
      tokenAmount: pending.side === "buy" ? outputAmount : pending.tokenAmount,
      signature: execute.signature,
      recordError: [completionError, recordError].filter(Boolean).join(" | "),
      dexUrl: dexScreenerUrl(pending.tokenMint),
      message: `${pending.provider || "Browser wallet"} ${pending.side === "buy" ? "buy" : "sell"} submitted for ${shortMint(pending.tokenMint)}.`
    };
  } catch (error) {
    if (submissionStarted) {
      const ambiguous = markTradeSubmissionAmbiguous(error, "jupiter:browser-execute");
      ambiguous.signature = localSignature || undefined;
      await completePendingBrowserTradeOrder(pending, {
        status: "outcome_unknown",
        submissionSignature: localSignature || null,
        lastError: `Submission outcome is unknown; this order will not be replayed. ${friendlyError(error)}`
      }).catch(() => {});
      throw ambiguous;
    }
    await completePendingBrowserTradeOrder(pending, {
      status: "failed",
      lastError: friendlyError(error)
    }).catch(() => {});
    throw error;
  }
}

// Scan the user's managed wallets for the one holding the most of a given token. Used as a
// sell fallback: the web "active wallet" often isn't the wallet that bought the coin, and selling
// from a wallet with a zero balance is what surfaced "sell server error" to the user.
async function findManagedWalletHoldingToken(store, userId, tokenMint, skipPublicKey = "") {
  const wallets = walletsForOwner(store, userId).filter((wallet) => wallet.publicKey !== skipPublicKey);
  if (!wallets.length) return null;
  const mintKey = new PublicKey(tokenMint);
  let best = null;
  let bestRaw = 0n;
  await runWithConcurrency(wallets, Math.min(4, Math.max(2, CONFIG.balanceConcurrency)), async (wallet) => {
    try {
      const keypair = decryptWallet(wallet);
      const token = await getReliableTokenBalanceForMint(keypair.publicKey, mintKey, { throwOnError: false, priority: true }).catch(() => null);
      const raw = token ? positiveBigIntOrZero(token.rawAmount) : 0n;
      if (raw > bestRaw) { bestRaw = raw; best = wallet; }
    } catch {
      // skip unreadable wallet
    }
  });
  return bestRaw > 0n ? best : null;
}

function isNoTokenBalanceError(error) {
  return /no token balance|token account.*not found|no .*balance/i.test(String(error?.message || ""));
}

// A wallet that HOLDS the token but has ~no SOL can't pay the sell's network fee — the chain rejects it
// at simulation ("Attempt to debit an account but found no record of a prior credit" / insufficient
// lamports). Detect that case so we can top the wallet up and retry instead of surfacing a raw RPC error.
function isInsufficientFeeError(error) {
  return /debit an account but found no record of a prior credit|insufficient lamports|insufficient funds for (?:fee|rent)|attempt to debit an account/i.test(String(error?.message || ""));
}

function manualSellProtectionStatus(holder = {}) {
  return String(holder.status || holder.exitStatus || holder.triggerStatus || "").toLowerCase();
}

function manualSellProtectionTerminal(holder = {}) {
  const statuses = [holder.status, holder.exitStatus, holder.triggerStatus]
    .map((value) => String(value || "").toLowerCase());
  return statuses.some((status) => ["sold", "confirmed", "closed", "canceled", "cancelled", "stopped", "skipped", "failed"].includes(status));
}

function manualSellProtectionInFlight(holder = {}) {
  const statuses = [holder.status, holder.exitStatus, holder.triggerStatus]
    .map((value) => String(value || "").toLowerCase());
  return Boolean(holder.submissionSignature || holder.manualSellSubmissionSignature)
    || statuses.some((status) => ["pending_buy", "arming", "submitting", "outcome_unknown", "manual_sell_submitting", "manual_sell_outcome_unknown"].includes(status));
}

function manualSellProtectionRelevant(holder = {}) {
  if (manualSellProtectionTerminal(holder)) return false;
  const status = manualSellProtectionStatus(holder);
  return isActiveTimedWalletStatus(status)
    || isActiveWebExitGuardStatus(status)
    || ["needs_attention", "price-unavailable", "timer-only", "retrying"].includes(status);
}

function manualSellProtectionBusyError() {
  const error = new Error("An automatic exit for this wallet and coin is already submitting or has an unknown outcome. SlimeWire blocked the manual sell so the same tokens cannot be sold twice. Check Activity before retrying.");
  error.statusCode = 409;
  error.manualSellProtectionBusy = true;
  return error;
}

function submittedUnknownHashes(error = {}) {
  return [...new Set([
    ...(Array.isArray(error.partialHashes) ? error.partialHashes : []),
    error.signature,
    error.txHash,
    error.transactionHash
  ].map((value) => String(value || "").trim()).filter(Boolean))];
}

function aggregateTradeSubmissionAmbiguous(label, errors = [], rows = []) {
  const hashes = [...new Set(errors.flatMap((error) => submittedUnknownHashes(error)))];
  const error = new Error(`${label}: at least one transaction was submitted but its confirmation is unknown. SlimeWire paused retries so it cannot sell twice.`);
  error.tradeSubmissionAmbiguous = true;
  error.partialHashes = hashes;
  error.results = rows;
  return error;
}

function rememberManualSellProtectionState(holder, claimToken, nowIso, percent = 100) {
  holder.manualSellPreviousState = {
    status: holder.status ?? null,
    exitStatus: holder.exitStatus ?? null,
    triggerStatus: holder.triggerStatus ?? null,
    triggerReason: holder.triggerReason ?? null,
    triggerKind: holder.triggerKind ?? null,
    retryAfterAt: holder.retryAfterAt ?? null,
    nextRetryAt: holder.nextRetryAt ?? null
  };
  holder.manualSellClaimToken = claimToken;
  holder.manualSellIntendedPercent = Number(percent);
  holder.manualSellStartedAt = nowIso;
  holder.status = "submitting";
  holder.exitStatus = "submitting";
  holder.triggerStatus = "manual-sell-submitting";
  holder.updatedAt = nowIso;
  bumpTradePlanWalletStateRevision(holder, nowIso);
}

function clearManualSellProtectionState(holder, { preserveSubmission = false } = {}) {
  delete holder.manualSellPreviousState;
  delete holder.manualSellStartedAt;
  if (!preserveSubmission) {
    delete holder.manualSellClaimToken;
    delete holder.manualSellSubmissionSignature;
    delete holder.manualSellSubmissionRequestId;
    delete holder.manualSellSubmissionLastValidBlockHeight;
    delete holder.manualSellSubmissionRecentBlockhash;
    delete holder.manualSellSubmissionProvider;
    delete holder.manualSellSignedAt;
    delete holder.manualSellReviewPreviousState;
    delete holder.manualSellIntendedPercent;
    delete holder.manualSellIntendedTokenAmount;
    delete holder.manualSellOutcomeUnknownAt;
    delete holder.manualSellNeedsAttention;
    delete holder.manualSellReceiptPendingAt;
  }
}

function restoreManualSellProtectionState(holder) {
  const previous = holder.manualSellPreviousState || holder.manualSellReviewPreviousState || {};
  holder.status = previous.status || "watching";
  holder.exitStatus = previous.exitStatus || holder.status;
  holder.triggerStatus = previous.triggerStatus || holder.exitStatus;
  holder.triggerReason = previous.triggerReason ?? null;
  holder.triggerKind = previous.triggerKind ?? null;
  holder.retryAfterAt = previous.retryAfterAt ?? null;
  holder.nextRetryAt = previous.nextRetryAt ?? null;
  holder.updatedAt = new Date().toISOString();
  clearManualSellProtectionState(holder);
  bumpTradePlanWalletStateRevision(holder, holder.updatedAt);
}

function manualSellProtectionTargetKey(planId, walletPublicKey) {
  return `${String(planId || "")}:${String(walletPublicKey || "")}`;
}

async function claimManualSellProtection(walletPublicKey, tokenMint, claimToken, percent = 100) {
  const nowIso = new Date().toISOString();
  const claimed = { claimToken, planTargets: [], guardTargets: [] };
  await mutateTradePlans((store) => {
    for (const plan of objectRows(store.plans)) {
      if (String(plan.tokenMint || "") !== String(tokenMint || "")) continue;
      if (["canceled", "cancelled", "stopped", "closed", "completed"].includes(String(plan.status || "").toLowerCase())) continue;
      for (const holder of objectRows(plan.wallets)) {
        if (String(holder.publicKey || "") !== String(walletPublicKey || "")) continue;
        if (manualSellProtectionInFlight(holder)) throw manualSellProtectionBusyError();
        if (!manualSellProtectionRelevant(holder)) continue;
        rememberManualSellProtectionState(holder, claimToken, nowIso, percent);
        claimed.planTargets.push(manualSellProtectionTargetKey(plan.id, holder.publicKey));
      }
    }
    return claimed.planTargets.length;
  });

  try {
    await mutateWebExitGuards((store) => {
      for (const guard of objectRows(store.guards)) {
        if (String(guard.tokenMint || "") !== String(tokenMint || "")) continue;
        if (String(guard.walletPublicKey || "") !== String(walletPublicKey || "")) continue;
        if (manualSellProtectionInFlight(guard)) throw manualSellProtectionBusyError();
        if (!manualSellProtectionRelevant(guard)) continue;
        rememberManualSellProtectionState(guard, claimToken, nowIso, percent);
        claimed.guardTargets.push(webExitGuardPrecheckKey(guard));
      }
      return claimed.guardTargets.length;
    });
  } catch (error) {
    await settleManualSellProtection(claimed, "failed").catch(() => {});
    throw error;
  }
  return claimed;
}

async function checkpointManualSellProtection(claimed, checkpoint = {}) {
  if (!claimed?.claimToken) return true;
  const signature = String(checkpoint.signature || "").trim();
  if (!signature) throw new Error("Signed manual sell checkpoint is missing its transaction signature.");
  const nowIso = new Date().toISOString();
  let planCount = 0;
  await mutateTradePlans((store) => {
    for (const plan of objectRows(store.plans)) {
      for (const holder of objectRows(plan.wallets)) {
        const key = manualSellProtectionTargetKey(plan.id, holder.publicKey);
        if (!claimed.planTargets.includes(key) || holder.manualSellClaimToken !== claimed.claimToken) continue;
        holder.manualSellSubmissionSignature = signature;
        holder.manualSellSubmissionRequestId = String(checkpoint.requestId || "");
        holder.manualSellSubmissionLastValidBlockHeight = checkpoint.lastValidBlockHeight ?? null;
        holder.manualSellSubmissionRecentBlockhash = checkpoint.recentBlockhash || checkpoint.blockhash || null;
        holder.manualSellSubmissionProvider = String(checkpoint.provider || "");
        holder.manualSellIntendedTokenAmount = positiveRawString(checkpoint.tokenAmount) || holder.manualSellIntendedTokenAmount || null;
        holder.manualSellSignedAt = nowIso;
        holder.updatedAt = nowIso;
        bumpTradePlanWalletStateRevision(holder, nowIso);
        planCount += 1;
      }
    }
    if (planCount !== claimed.planTargets.length) throw new Error("Automatic protection changed before the manual sell could be submitted.");
  });

  let guardCount = 0;
  await mutateWebExitGuards((store) => {
    for (const guard of objectRows(store.guards)) {
      const key = webExitGuardPrecheckKey(guard);
      if (!claimed.guardTargets.includes(key) || guard.manualSellClaimToken !== claimed.claimToken) continue;
      guard.manualSellSubmissionSignature = signature;
      guard.manualSellSubmissionRequestId = String(checkpoint.requestId || "");
      guard.manualSellSubmissionLastValidBlockHeight = checkpoint.lastValidBlockHeight ?? null;
      guard.manualSellSubmissionRecentBlockhash = checkpoint.recentBlockhash || checkpoint.blockhash || null;
      guard.manualSellSubmissionProvider = String(checkpoint.provider || "");
      guard.manualSellIntendedTokenAmount = positiveRawString(checkpoint.tokenAmount) || guard.manualSellIntendedTokenAmount || null;
      guard.manualSellSignedAt = nowIso;
      guard.updatedAt = nowIso;
      bumpTradePlanWalletStateRevision(guard, nowIso);
      guardCount += 1;
    }
    if (guardCount !== claimed.guardTargets.length) throw new Error("Automatic protection changed before the manual sell could be submitted.");
  });
  return true;
}

function settleConfirmedManualSellHolder(plan, holder, sell = {}, percent = 100) {
  const nowIso = new Date().toISOString();
  const update = applyConfirmedProtectedLotSell(holder, sell.tokenAmount);
  const remaining = positiveBigIntOrZero(update?.remainingRaw);
  holder.manualSellSignature = sell.signature || holder.manualSellSubmissionSignature || null;
  holder.manualSellConfirmedAt = nowIso;
  holder.manualSellPercent = percent;
  holder.manualSellTokenAmount = sell.tokenAmount || null;
  holder.lastError = null;
  holder.error = null;
  holder.retryAfterAt = null;
  holder.nextRetryAt = null;
  holder.triggerReason = null;
  holder.triggerKind = null;
  clearManualSellProtectionState(holder);

  if ((update && remaining === 0n) || (!update && Number(percent) >= 99.999)) {
    holder.status = "sold";
    holder.exitStatus = "confirmed";
    holder.triggerStatus = "confirmed";
    holder.sellSignature = sell.signature || holder.sellSignature || null;
    holder.soldAt = nowIso;
  } else if (update && remaining > 0n) {
    holder.status = "watching";
    holder.exitStatus = "watching";
    holder.triggerStatus = "watching";
    resetPartialExitTriggerState(plan, holder);
  } else {
    holder.status = "needs_attention";
    holder.exitStatus = "needs_attention";
    holder.triggerStatus = "needs_attention";
    holder.lastError = "A manual partial sell changed this legacy position. Review and re-arm protection for the remaining tokens.";
  }
  holder.updatedAt = nowIso;
  bumpTradePlanWalletStateRevision(holder, nowIso);
}

function settleAmbiguousManualSellHolder(holder, error = null, percent = 100) {
  const nowIso = new Date().toISOString();
  const signature = firstString(error?.signature, error?.partialHashes?.[0], holder.manualSellSubmissionSignature);
  holder.manualSellReviewPreviousState = { ...(holder.manualSellPreviousState || {}) };
  holder.manualSellIntendedPercent = Number(percent);
  holder.manualSellIntendedTokenAmount = firstString(error?.tokenAmount, error?.intendedTokenAmount) || null;
  holder.manualSellNeedsAttention = true;
  holder.status = "outcome_unknown";
  holder.exitStatus = "outcome_unknown";
  holder.triggerStatus = "outcome_unknown";
  holder.manualSellSubmissionSignature = signature || holder.manualSellSubmissionSignature || null;
  holder.manualSellOutcomeUnknownAt = nowIso;
  holder.lastError = "The manual sell was submitted but its on-chain outcome is unknown. Automatic exits are paused to prevent a duplicate sell.";
  holder.updatedAt = nowIso;
  clearManualSellProtectionState(holder, { preserveSubmission: true });
  bumpTradePlanWalletStateRevision(holder, nowIso);
}

function settleConfirmedManualSellReceiptPendingHolder(holder, sell = {}, percent = 100, error = null) {
  const nowIso = new Date().toISOString();
  holder.manualSellReviewPreviousState = { ...(holder.manualSellPreviousState || holder.manualSellReviewPreviousState || {}) };
  holder.manualSellIntendedPercent = Number(percent);
  holder.manualSellIntendedTokenAmount = positiveRawString(sell.tokenAmount)
    || positiveRawString(holder.manualSellIntendedTokenAmount)
    || null;
  holder.manualSellSubmissionSignature = firstString(sell.signature, holder.manualSellSubmissionSignature) || null;
  holder.manualSellConfirmedAt = nowIso;
  holder.manualSellReceiptPendingAt = nowIso;
  holder.manualSellNeedsAttention = true;
  holder.status = "needs_attention";
  holder.exitStatus = "needs_attention";
  holder.triggerStatus = "needs_attention";
  holder.lastError = `The manual sell is confirmed, but its durable Activity receipt could not be saved. Protection accounting is paused and the sell will not be retried. ${friendlyError(error)}`;
  holder.updatedAt = nowIso;
  clearManualSellProtectionState(holder, { preserveSubmission: true });
  bumpTradePlanWalletStateRevision(holder, nowIso);
}

async function settleManualSellProtection(claimed, outcome, sell = {}, percent = 100, error = null) {
  if (!claimed?.claimToken) return;
  await mutateTradePlans((store) => {
    for (const plan of objectRows(store.plans)) {
      let touched = false;
      for (const holder of objectRows(plan.wallets)) {
        const key = manualSellProtectionTargetKey(plan.id, holder.publicKey);
        if (!claimed.planTargets.includes(key) || holder.manualSellClaimToken !== claimed.claimToken) continue;
        touched = true;
        if (outcome === "confirmed") settleConfirmedManualSellHolder(plan, holder, sell, percent);
        else if (outcome === "confirmed_receipt_pending") settleConfirmedManualSellReceiptPendingHolder(holder, sell, percent, error);
        else if (outcome === "ambiguous") settleAmbiguousManualSellHolder(holder, error, percent);
        else restoreManualSellProtectionState(holder);
      }
      if (!touched) continue;
      const wallets = objectRows(plan.wallets);
      if (wallets.length && wallets.every((holder) => manualSellProtectionTerminal(holder))) {
        plan.status = "completed";
        plan.completedAt = plan.completedAt || new Date().toISOString();
      } else if (wallets.some((holder) => isActiveTimedWalletStatus(holder.status))) {
        plan.status = "watching";
        plan.completedAt = null;
      }
      plan.updatedAt = new Date().toISOString();
    }
  });

  await mutateWebExitGuards((store) => {
    for (const guard of objectRows(store.guards)) {
      const key = webExitGuardPrecheckKey(guard);
      if (!claimed.guardTargets.includes(key) || guard.manualSellClaimToken !== claimed.claimToken) continue;
      if (outcome === "confirmed") settleConfirmedManualSellHolder(webExitGuardPlan(guard), guard, sell, percent);
      else if (outcome === "confirmed_receipt_pending") settleConfirmedManualSellReceiptPendingHolder(guard, sell, percent, error);
      else if (outcome === "ambiguous") settleAmbiguousManualSellHolder(guard, error, percent);
      else restoreManualSellProtectionState(guard);
    }
  });
}

async function reconcilePendingManualSolSellProtection() {
  // Unprotected manual sells have no plan/guard holder to discover below.
  // Reconcile their standalone signed intents on the same bounded worker path;
  // live `submitting` requests remain untouched until the stale watchdog age.
  await reconcilePendingStandaloneManualSells().catch(() => ({ pending: 1 }));
  const [planStore, guardStore] = await Promise.all([
    readTradePlans(),
    readWebExitGuards()
  ]);
  const groups = new Map();
  const collect = (holder, target, defaults = {}) => {
    const signature = String(holder?.manualSellSubmissionSignature || "").trim();
    const claimToken = String(holder?.manualSellClaimToken || "").trim();
    if (!signature || !claimToken) return;
    const recoveryStatuses = [holder.status, holder.exitStatus, holder.triggerStatus]
      .map((value) => String(value || "").trim().toLowerCase());
    const immediatelyRecoverable = recoveryStatuses.some((status) => [
      "outcome_unknown",
      "needs_attention",
      "manual-sell-outcome-unknown"
    ].includes(status));
    const submitting = recoveryStatuses.some((status) => [
      "submitting",
      "manual-sell-submitting"
    ].includes(status));
    const signedAt = Date.parse(holder.manualSellSignedAt || holder.manualSellStartedAt || "");
    const staleSubmitting = submitting
      && Number.isFinite(signedAt)
      && Date.now() - signedAt >= CONFIG.stopLossSubmitStaleMs;
    // A live request still has to collect its platform fee and persist the
    // exact net receipt. Do not let the worker race that path with a gross
    // chain-delta receipt; only stale submissions or explicit review states
    // are safe to reconcile here.
    if (!immediatelyRecoverable && !staleSubmitting) return;
    const key = `${claimToken}:${signature}`;
    const group = groups.get(key) || {
      signature,
      claimToken,
      planTargets: [],
      guardTargets: [],
      userId: defaults.userId || null,
      tokenMint: defaults.tokenMint || null,
      walletPublicKey: defaults.walletPublicKey || null,
      walletLabel: defaults.walletLabel || "Managed wallet",
      tokenAmount: positiveRawString(holder.manualSellIntendedTokenAmount),
      percent: Number.isFinite(Number(holder.manualSellIntendedPercent)) ? Number(holder.manualSellIntendedPercent) : null,
      lastValidBlockHeight: holder.manualSellSubmissionLastValidBlockHeight || null,
      recentBlockhash: holder.manualSellSubmissionRecentBlockhash || null
    };
    if (target.planTarget && !group.planTargets.includes(target.planTarget)) group.planTargets.push(target.planTarget);
    if (target.guardTarget && !group.guardTargets.includes(target.guardTarget)) group.guardTargets.push(target.guardTarget);
    group.tokenAmount ||= positiveRawString(holder.manualSellIntendedTokenAmount);
    if (group.percent === null && Number.isFinite(Number(holder.manualSellIntendedPercent))) group.percent = Number(holder.manualSellIntendedPercent);
    group.lastValidBlockHeight ||= holder.manualSellSubmissionLastValidBlockHeight || null;
    group.recentBlockhash ||= holder.manualSellSubmissionRecentBlockhash || null;
    groups.set(key, group);
  };
  for (const plan of objectRows(planStore.plans)) {
    for (const holder of objectRows(plan.wallets)) {
      collect(holder, { planTarget: manualSellProtectionTargetKey(plan.id, holder.publicKey) }, {
        userId: plan.userId,
        tokenMint: plan.tokenMint,
        walletPublicKey: holder.publicKey,
        walletLabel: holder.label
      });
    }
  }
  for (const guard of objectRows(guardStore.guards)) {
    collect(guard, { guardTarget: webExitGuardPrecheckKey(guard) }, {
      userId: guard.userId,
      tokenMint: guard.tokenMint,
      walletPublicKey: guard.walletPublicKey,
      walletLabel: guard.walletLabel
    });
  }

  let resolved = 0;
  for (const group of groups.values()) {
    const outcome = await reconcileSubmittedSolanaSignature(group.signature, {
      label: "manual sell reconciliation",
      lastValidBlockHeight: group.lastValidBlockHeight,
      recentBlockhash: group.recentBlockhash
    });
    if (["pending", "unavailable", "unknown_expiry"].includes(outcome.state)) continue;
    const claimed = {
      claimToken: group.claimToken,
      planTargets: group.planTargets,
      guardTargets: group.guardTargets
    };
    if (["failed", "expired"].includes(outcome.state)) {
      await settleManualSellProtection(claimed, "failed");
      resolved += 1;
      continue;
    }
    if (outcome.state !== "confirmed" || !group.tokenAmount || group.percent === null) continue;
    const receipt = {
      userId: group.userId,
      source: "manual_sell_recovery",
      tokenMint: group.tokenMint,
      walletLabel: group.walletLabel,
      walletPublicKey: group.walletPublicKey,
      tokenAmount: group.tokenAmount,
      solLamportsReceived: "0",
      signature: group.signature,
      triggerKind: "manual",
      triggerReason: "confirmed manual sell recovered after response loss",
      sellPercent: group.percent,
      confirmedAt: new Date().toISOString(),
      historyRecorded: false,
      needsAttention: true,
      historyRecordError: "Confirmed manual sell is waiting for its exact wallet proceeds before Activity is recorded."
    };
    // Durably checkpoint the confirmed receipt before clearing the holder's
    // submission claim. A crash after this point can backfill Activity without
    // replaying or reapplying the sell to the protected lot.
    try {
      await persistConfirmedSolAutoExitReceipt(receipt);
    } catch {
      continue;
    }
    await settleManualSellProtection(claimed, "confirmed", {
      signature: group.signature,
      tokenAmount: group.tokenAmount
    }, group.percent);
    const exactProceeds = await confirmedSolExitWalletReceiptAmounts({
      signature: group.signature,
      walletPublicKey: group.walletPublicKey,
      tokenMint: group.tokenMint
    }).catch(() => null);
    if (exactProceeds) {
      await recordConfirmedSolAutoExit({
        ...receipt,
        ...exactProceeds,
        needsAttention: false,
        historyRecordError: null
      });
    }
    resolved += 1;
  }
  return resolved;
}

async function executeManualSolSellWithProtection(wallet, tokenMint, percent, task, options = {}) {
  const claimToken = crypto.randomUUID();
  const userId = firstString(options.userId, wallet.ownerId, wallet.userId);
  const manualSellAttemptId = normalizeManualSellAttemptId(options.manualSellAttemptId) || `manual-sell-${claimToken}`;
  const standaloneIdentity = {
    userId,
    manualSellAttemptId,
    parentManualSellAttemptId: normalizeManualSellAttemptId(options.parentManualSellAttemptId || options.manualSellAttemptId) || manualSellAttemptId,
    walletPublicKey: wallet.publicKey,
    walletLabel: wallet.label || "Managed wallet",
    tokenMint,
    percent: Number(percent)
  };
  const previousStandalone = await reconcileStandaloneManualSellSubmission(standaloneIdentity);
  if (previousStandalone.state === "ambiguous") throw standaloneManualSellSubmissionError(previousStandalone.row);
  if (previousStandalone.state === "confirmed") {
    // Replaying this exact attempt returns its confirmed receipt, but it cannot
    // release the same-position tombstone. Activity plus the response-loss
    // window (or an exact trusted automation acknowledgement) controls when a
    // different attempt may sell the remaining partial bag.
    return previousStandalone.result;
  }
  const crossAttempt = await assertNoUnresolvedStandaloneManualSell(standaloneIdentity, {
    excludeAttemptId: manualSellAttemptId,
    trustedPriorAttemptId: options.trustedPriorManualSellAttemptId,
    trustedPriorSignature: options.trustedPriorManualSellSignature
  });
  if (crossAttempt?.replay?.row) {
    const prior = crossAttempt.replay;
    return {
      ...(prior.result || standaloneManualSellReplayResult(prior.row)),
      duplicate: true,
      recovered: true,
      crossAttemptReplay: true,
      blockedNewSubmission: true,
      priorManualSellAttemptId: normalizeManualSellAttemptId(prior.row.manualSellAttemptId || prior.row.attemptId),
      priorManualSellSignature: String(prior.row.signature || prior.result?.signature || ""),
      recordError: firstString(
        prior.result?.recordError,
        prior.result?.protectionRecordError,
        "A recent confirmed sell receipt was replayed because the prior response may not have reached the client. No new sell was submitted."
      )
    };
  }

  const claimed = await claimManualSellProtection(wallet.publicKey, tokenMint, claimToken, percent);
  const protectedTargetCount = claimed.planTargets.length + claimed.guardTargets.length;
  if (Number(percent) < 99.999 && protectedTargetCount > 1) {
    await settleManualSellProtection(claimed, "failed").catch(() => {});
    const error = new Error("This partial sell overlaps more than one automatic protection record. SlimeWire blocked it so the same token amount cannot be deducted twice. Review Orders & exits, then close or consolidate the duplicate protection first.");
    error.statusCode = 409;
    error.manualSellProtectionOverlap = true;
    throw error;
  }
  let standaloneCheckpoint = null;
  try {
    const sell = await task(async (checkpoint = {}) => {
      // This file-backed intent is required even when no TP/SL holder exists.
      // It lands before broadcast and gives a restarted request one exact
      // signature to reconcile instead of selling a second partial tranche.
      try {
        standaloneCheckpoint = await persistStandaloneManualSellSubmission({
          ...standaloneIdentity,
          signature: checkpoint.signature,
          tokenAmount: checkpoint.tokenAmount,
          lastValidBlockHeight: checkpoint.lastValidBlockHeight ?? null,
          recentBlockhash: checkpoint.recentBlockhash || checkpoint.blockhash || null,
          provider: checkpoint.provider || null,
          requestId: checkpoint.requestId || null,
          status: "submitting",
          signedAt: new Date().toISOString(),
          needsAttention: true
        });
      } catch (error) {
        error.tradePreSubmit = true;
        throw error;
      }
      try {
        await checkpointManualSellProtection(claimed, checkpoint);
      } catch (error) {
        await persistStandaloneManualSellSubmission({
          ...standaloneCheckpoint,
          status: "failed",
          resolvedAt: new Date().toISOString(),
          recordError: friendlyError(error)
        }).catch(() => {});
        error.tradePreSubmit = true;
        throw error;
      }
    });
    const receipt = {
      userId,
      source: "manual_sell_confirmed",
      tokenMint,
      walletLabel: wallet.label || "Managed wallet",
      walletPublicKey: wallet.publicKey,
      tokenAmount: positiveRawString(sell?.tokenAmount) || "0",
      ...confirmedSolSellReceiptAmounts(sell),
      signature: String(sell?.signature || "").trim(),
      triggerKind: "manual",
      triggerReason: "confirmed manual sell",
      sellPercent: percent,
      manualSellAttemptId,
      confirmedAt: new Date().toISOString(),
      historyRecorded: false,
      needsAttention: BigInt(confirmedSolSellReceiptAmounts(sell).solLamportsReceived || 0) <= 0n,
      historyRecordError: BigInt(confirmedSolSellReceiptAmounts(sell).solLamportsReceived || 0) <= 0n
        ? "Confirmed manual sell is waiting for its exact wallet proceeds before Activity is completed."
        : null
    };
    let receiptError = null;
    try {
      if (!receipt.userId || !receipt.walletPublicKey || !receipt.tokenMint
        || !receipt.signature || BigInt(receipt.tokenAmount || 0) <= 0n) {
        throw new Error("Confirmed manual sell result is missing its user, wallet, mint, signature, or exact token amount.");
      }
      // This receipt is the crash-safe bridge between confirmation and each
      // caller's source-specific Activity append. It must exist before the
      // protection claim can be cleared or its lot can be decremented.
      await persistConfirmedSolAutoExitReceipt(receipt);
      standaloneCheckpoint = await persistStandaloneManualSellSubmission({
        ...standaloneIdentity,
        ...(standaloneCheckpoint || {}),
        signature: receipt.signature,
        tokenAmount: receipt.tokenAmount,
        status: "confirmed",
        confirmedAt: receipt.confirmedAt,
        outputLamports: positiveRawString(sell.outputLamports) || "0",
        solLamportsReceived: receipt.solLamportsReceived,
        grossSolLamportsReceived: receipt.grossSolLamportsReceived,
        feeLamports: positiveRawString(sell.feeLamports) || "0",
        feePaidLamports: normalizeTradeHistoryAmount(sell.feePaidLamports || receipt.tradeFeeLamports || "0"),
        feeRecoveryPending: sell.feeRecoveryPending === true,
        tradeFeeLamports: receipt.tradeFeeLamports,
        feeStatus: receipt.feeStatus,
        needsAttention: receipt.needsAttention,
        recordError: receipt.historyRecordError
      });
    } catch (error) {
      receiptError = error;
    }
    if (receiptError) {
      await settleManualSellProtection(claimed, "confirmed_receipt_pending", sell, percent, receiptError).catch(() => {});
      sell.recordError = `Confirmed sell receipt pending: ${friendlyError(receiptError)}`;
      sell.protectionRecordError = sell.recordError;
      await audit("manual_sell_receipt_persist_failed", {
        walletPublicKey: wallet.publicKey,
        tokenMint,
        signature: sell?.signature || null,
        error: friendlyError(receiptError)
      }).catch(() => {});
      return sell;
    }
    if (receipt.needsAttention) {
      sell.recordError = receipt.historyRecordError;
      sell.protectionRecordError = receipt.historyRecordError;
    }
    await settleManualSellProtection(claimed, "confirmed", sell, percent).catch(async (error) => {
      await audit("manual_sell_protection_update_failed", {
        walletPublicKey: wallet.publicKey,
        tokenMint,
        signature: sell?.signature || null,
        error: friendlyError(error)
      }).catch(() => {});
    });
    return sell;
  } catch (error) {
    const explicitPreSubmit = error?.tradePreSubmit === true && !error?.tradeSubmissionAmbiguous;
    const signedButNotProvenPreSubmit = Boolean(standaloneCheckpoint?.signature) && !explicitPreSubmit;
    const ambiguous = !explicitPreSubmit && (
      Boolean(error?.tradeSubmissionAmbiguous)
      || Boolean(firstString(error?.signature, error?.partialHashes?.[0]))
      || signedButNotProvenPreSubmit
    );
    let finalError = error;
    if (ambiguous && !error?.tradeSubmissionAmbiguous) {
      finalError = markTradeSubmissionAmbiguous(error, "standalone-manual-sell-after-sign");
      finalError.signature = firstString(finalError.signature, standaloneCheckpoint?.signature);
      finalError.tradePreSubmit = false;
    }
    if (standaloneCheckpoint?.signature) {
      await persistStandaloneManualSellSubmission({
        ...standaloneCheckpoint,
        status: ambiguous ? "ambiguous" : "failed",
        needsAttention: ambiguous,
        resolvedAt: ambiguous ? null : new Date().toISOString(),
        recordError: friendlyError(finalError)
      }).catch(() => {});
    }
    await settleManualSellProtection(claimed, ambiguous ? "ambiguous" : "failed", {}, percent, finalError).catch(() => {});
    throw finalError;
  }
}

// Move a sliver of SOL into `wallet` from the user's most-funded OTHER wallet so it can cover a sell's
// network fee ("gasless" sell). Best-effort; only called AFTER a sell already failed for lack of fee SOL.
async function topUpSellFees(store, userId, wallet, targetLamports = 5_000_000) {
  const FEE_TARGET = Math.max(500_000, Math.round(targetLamports)); // default ~0.005 SOL — a couple of priority-fee'd txs
  const kp = decryptWallet(wallet);
  const siblingWallets = walletsForOwner(store, userId).filter((row) => row.publicKey !== wallet.publicKey && row.secret);
  await primeSolBalancesBatch([wallet.publicKey, ...siblingWallets.map((row) => row.publicKey)], { priority: true }).catch(() => 0);
  const bal = Number(await getSolBalanceCached(kp.publicKey, { force: false, priority: true }).catch(() => 0));
  if (bal >= FEE_TARGET) return false; // already has enough — the failure was something else
  const need = FEE_TARGET - bal;
  const candidates = [];
  for (const s of siblingWallets) {
    const sbal = Number(await getSolBalanceCached(new PublicKey(s.publicKey), { force: false, priority: true }).catch(() => 0));
    if (sbal > need + CONFIG.buyReserveLamports + 30_000) candidates.push({ s, sbal });
  }
  candidates.sort((a, b) => b.sbal - a.sbal); // fund from the most-funded sibling
  for (const { s } of candidates) {
    try {
      const skp = decryptWallet(s);
      const tx = new Transaction();
      tx.add(SystemProgram.transfer({ fromPubkey: skp.publicKey, toPubkey: kp.publicKey, lamports: need }));
      await sendLegacyTransaction(tx, [skp], { priority: true });
      invalidateWalletReadCache(s.publicKey);
      invalidateWalletReadCache(wallet.publicKey);
      await audit("sell_fee_topup", { userId, to: wallet.publicKey, from: s.publicKey, lamports: String(need) });
      return true;
    } catch { /* try the next funded sibling */ }
  }
  return false;
}

// Sell, and if it fails purely because the holding wallet can't afford the network fee, top it up from a
// sibling wallet and retry ONCE. Any non-fee error (incl. no-token-balance) propagates unchanged.
async function sellWithFeeRetry(store, userId, wallet, tokenMint, percent, slippageBps, options = {}) {
  try {
    return await sellTokenFromWallet(wallet, tokenMint, percent, slippageBps, { userId, priority: true, ...options });
  } catch (error) {
    if (!isInsufficientFeeError(error)) throw error;
    const funded = await topUpSellFees(store, userId, wallet).catch(() => false);
    if (!funded) {
      const e = new Error("This wallet holds the coin but has no SOL for the network fee, and no other wallet has SOL to cover it. Send a little SOL (~0.01) to this wallet, then sell.");
      e.statusCode = 400;
      throw e;
    }
    return await sellTokenFromWallet(wallet, tokenMint, percent, slippageBps, { userId, priority: true, ...options });
  }
}

async function webTradeSell(userId, body = {}, options = {}) {
  return runManualSellCriticalAttempt(userId, body, options, (attempt) => webTradeSellCore(userId, body, options, attempt));
}

async function webTradeSellCore(userId, body = {}, options = {}, attempt = {}) {
  const backendStartedAt = Date.now();
  const store = await readWalletStore();
  let wallet = assertFrozenManagedWallet(
    getWebServerTradeWalletAt(store, parseWebWalletIndex(body.walletIndex), userId, "manual sell"),
    body.walletPublicKey,
    "sell"
  );
  const tokenMint = parsePublicKey(String(body.tokenMint || "")).toBase58();
  const percent = parsePercent(String(body.percent || "100"));
  const slippageBps = parseWebSlippage(body.slippageBps);
  const trustedPriorForWallet = (candidateWallet) => {
    const acknowledgement = options.trustedPriorManualSellAcknowledgement;
    return acknowledgement
      && String(acknowledgement.walletPublicKey || "") === String(candidateWallet.publicKey || "")
      ? acknowledgement
      : null;
  };
  const validationMs = Date.now() - backendStartedAt;
  const submitStartedAt = Date.now();
  let result;
  try {
    result = await withExitSellLock(userId, wallet.publicKey, tokenMint, () => (
      executeManualSolSellWithProtection(wallet, tokenMint, percent, (onSigned) => (
        sellWithFeeRetry(store, userId, wallet, tokenMint, percent, slippageBps, { onSigned })
      ), {
        userId,
        manualSellAttemptId: attempt.manualSellAttemptId,
        trustedPriorManualSellAttemptId: trustedPriorForWallet(wallet)?.manualSellAttemptId,
        trustedPriorManualSellSignature: trustedPriorForWallet(wallet)?.signature
      })
    ));
  } catch (error) {
    // The active wallet doesn't hold this coin (the common cause of "sell server error"):
    // find the managed wallet that actually does and sell from there. If none hold it, the
    // coin is in a connected browser wallet and must be sold from that wallet directly.
    if (isNoTokenBalanceError(error) && !cleanLaunchBoolean(body.strictWallet)) {
      const holder = await findManagedWalletHoldingToken(store, userId, tokenMint, wallet.publicKey);
      if (holder) {
        wallet = holder;
        result = await withExitSellLock(userId, wallet.publicKey, tokenMint, () => (
          executeManualSolSellWithProtection(wallet, tokenMint, percent, (onSigned) => (
            sellWithFeeRetry(store, userId, wallet, tokenMint, percent, slippageBps, { onSigned })
          ), {
            userId,
            manualSellAttemptId: attempt.manualSellAttemptId,
            trustedPriorManualSellAttemptId: trustedPriorForWallet(wallet)?.manualSellAttemptId,
            trustedPriorManualSellSignature: trustedPriorForWallet(wallet)?.signature
          })
        ));
      } else {
        const friendly = new Error("None of your SlimeWire wallets hold this coin to sell. If you bought it with a connected browser wallet (Phantom/Solflare), sell it from that wallet.");
        friendly.statusCode = 400;
        throw friendly;
      }
    } else {
      throw error;
    }
  }
  const submitMs = Date.now() - submitStartedAt;
  const receiptAmounts = confirmedSolSellReceiptAmounts(result);
  const outputLamports = positiveBigIntOrZero(receiptAmounts.grossSolLamportsReceived);
  const feeLamports = positiveBigIntOrZero(receiptAmounts.tradeFeeLamports);
  const receivedLamports = positiveBigIntOrZero(receiptAmounts.solLamportsReceived);
  const feePending = result.feeRecoveryPending === true;

  const recordStartedAt = Date.now();
  let recordError = [
    feePending ? "Fee outcome is still confirming; final net proceeds are pending." : "",
    manualSellReceiptWarning(result)
  ].filter(Boolean).join(" ");
  const [historyResult, auditResult] = await Promise.allSettled([
    recordTradeEvents([{
      userId,
      type: "sell",
      source: "web_trade",
      tokenMint,
      walletLabel: wallet.label,
      walletPublicKey: wallet.publicKey,
      tokenAmount: result.tokenAmount,
      ...receiptAmounts,
      signature: result.signature
    }]),
    audit("web_trade_sell", {
      userId,
      tokenMint,
      wallet: publicWallet(wallet),
      percent,
      slippageBps,
      signature: result.signature
    })
  ]);
  if (historyResult.status === "rejected") recordError = [recordError, `Trade history: ${friendlyError(historyResult.reason)}`].filter(Boolean).join("; ");
  if (auditResult.status === "rejected") recordError = [recordError, `Audit: ${friendlyError(auditResult.reason)}`].filter(Boolean).join("; ");
  const recordMs = Date.now() - recordStartedAt;
  const backendMs = Date.now() - backendStartedAt;
  const manualSellTiming = manualSellTimingSummary({
    backendMs,
    validationMs,
    queueWaitMs: attempt.queueWaitMs || 0,
    submitMs,
    recordMs
  });
  void recordManualSellTimingEvent({
    action: "manual-sell-backend",
    manualSellAttemptId: attempt.manualSellAttemptId || "",
    durationMs: backendMs,
    resultCount: 1,
    queueWaitMs: attempt.queueWaitMs || 0,
    slowestStep: manualSellTiming.slowestStep,
    status: "submitted"
  }, options.request).catch(() => {});

  return {
    type: "sell",
    manualSellAttemptId: attempt.manualSellAttemptId || "",
    manualSellTiming,
    tokenMint,
    shortMint: shortMint(tokenMint),
    walletLabel: wallet.label,
    walletPublicKey: wallet.publicKey,
    percent,
    tokenAmount: result.tokenAmount,
    grossSol: lamportsBigToSol(outputLamports),
    feeSol: feePending ? null : lamportsBigToSol(feeLamports),
    netSol: feePending ? null : lamportsBigToSol(receivedLamports),
    feeRecoveryPending: feePending,
    feeStatus: receiptAmounts.feeStatus,
    signature: result.signature,
    attempts: result.attempts,
    duplicate: result.duplicate === true,
    recovered: result.recovered === true,
    crossAttemptReplay: result.crossAttemptReplay === true,
    blockedNewSubmission: result.blockedNewSubmission === true,
    priorManualSellAttemptId: normalizeManualSellAttemptId(result.priorManualSellAttemptId),
    priorManualSellSignature: String(result.priorManualSellSignature || (result.crossAttemptReplay ? result.signature : "") || ""),
    recordError,
    dexUrl: dexScreenerUrl(tokenMint),
    message: feePending
      ? `${wallet.label} sold ${percent}% of ${shortMint(tokenMint)}; fee and final net proceeds are pending confirmation.${recordError ? ` Warning: ${recordError}` : ""}`
      : `${wallet.label} sold ${percent}% of ${shortMint(tokenMint)} for ${lamportsBigToSol(receivedLamports)} SOL net; fee charged ${lamportsBigToSol(feeLamports)} SOL.${recordError ? ` Warning: ${recordError}` : ""}`
  };
}

async function webCreateSingleTradeAutoExitPlan(userId, wallet, tokenMint, buyResult, body = {}, slippageBps = CONFIG.defaultSlippageBps, automationPermission = null, options = {}) {
  const ladder = normalizeWebTakeProfitLadder(body.takeProfitLadder);
  // Ladder: the first rung is the "armed" TP; the engine sells each rung's sellPercent as its pct is hit.
  const takeProfitPct = ladder.length ? ladder[0].pct : parseTakeProfitPercent(String(body.takeProfitPct || "0"));
  const stopLossPct = parseOptionalTriggerPercent(String(body.stopLossPct || "0"));
  const sellDelaySeconds = parseOptionalSellDelaySeconds(firstString(body.sellDelay, body.sellDelaySeconds, "off"));
  // TP ladder tranches carry their own percentages. The immutable plan sell
  // percent belongs to stop-loss/timer exits and must remain 100% by default.
  const sellPercent = parsePercent(String(body.sellPercent || "100"));
  const triggerSellPercent = sellPercent;
  // Cornix-style advanced exits (all opt-in; the engine already runs these):
  //  - trailing stop: lock gains when a winner pulls back from its peak (only arms once in profit,
  //    so it can never cause a loss-sell). If activation isn't given, arm once up the trail distance.
  //  - break-even after TP1: after the first ladder tranche fills, tighten the stop to ~entry.
  const trailingStopPct = Math.max(0, Math.min(95, Number(body.trailingStopPct) || 0));
  const trailingActivatePct = trailingStopPct > 0 ? Math.max(Number(body.trailingActivatePct) || 0, trailingStopPct) : 0;
  const breakEvenAfterTp1 = cleanLaunchBoolean(body.breakEvenAfterTp1);
  const breakEvenStopPct = Math.max(0, Math.min(20, Number(body.breakEvenStopPct) || 2));
  const durablePlanKey = String(options.durablePlanKey || "").trim().slice(0, 128);
  const planSource = String(options.source || "web_trade_auto_exit").trim().slice(0, 80) || "web_trade_auto_exit";
  const pendingBuy = options.pendingBuy === true;
  const buyReservationClaimToken = durablePlanKey
    ? `buy-reservation-${crypto.createHash("sha256").update(durablePlanKey).digest("hex").slice(0, 32)}`
    : null;

  if (!takeProfitPct && !stopLossPct && sellDelaySeconds <= 0 && !ladder.length && !(trailingStopPct > 0)) {
    return null;
  }
  const permission = automationPermission || await requireWebAutomationPermission(userId, "quick-buy auto exits");

  const now = Date.now();
  const sellAfterAt = planSellAfterAtFromNow({ sellDelaySeconds }, now);
  const amountLamports = positiveRawString(buyResult.amountLamports) || "0";
  const basisLamports = positiveRawString(buyResult.swapLamports) || amountLamports;
  const feeLamports = positiveRawString(buyResult.feeLamports) || "0";
  const tokenAmount = positiveRawString(buyResult.tokenDeltaAmount) || positiveRawString(buyResult.outputAmount);
  const preBuyTokenRawAmount = buyResult.preBuyTokenRawAmount === undefined || buyResult.preBuyTokenRawAmount === null
    ? null
    : BigInt(buyResult.preBuyTokenRawAmount).toString();
  const walletIndex = parseWebWalletIndex(body.walletIndex || "1");
  const planWallet = {
    label: wallet.label,
    publicKey: wallet.publicKey,
    walletIndex,
    basisLamports,
    grossLamports: String(amountLamports),
    feeLamports,
    tokenOutAmount: tokenAmount,
    ...(tokenAmount ? { protectedTokenRemainingRaw: tokenAmount } : {}),
    protectedLotRevision: tokenAmount ? 1 : 0,
    ...(preBuyTokenRawAmount !== null ? { preBuyTokenRawAmount } : {}),
    buySignature: buyResult.signature,
    ...(pendingBuy && buyReservationClaimToken ? { buyReservationClaimToken } : {}),
    ...(!pendingBuy && buyResult.signature ? {
      resolvedBuySubmissionSignature: buyResult.signature,
      resolvedBuyReservationClaimToken: buyReservationClaimToken,
      buySubmissionResolution: "confirmed",
      buySubmissionConfirmedAt: new Date(now).toISOString(),
      buySubmissionSignature: null,
      buyReservationClaimToken: null
    } : {}),
    currentLoop: 1,
    completedLoops: 0,
    takeProfitPct,
    stopLossPct,
    completedTakeProfitLevels: [],
    sellAfterAt,
    triggerSellPercent,
    exitStatus: pendingBuy ? "pending_buy" : "watching",
    status: pendingBuy ? "pending_buy" : "watching",
    lastCheckedAt: null,
    lastMovePct: null,
    armedAt: pendingBuy ? null : new Date(now).toISOString(),
    triggerStatus: pendingBuy ? "pending_buy" : (takeProfitPct || stopLossPct ? "armed" : "timer-only"),
    lastError: pendingBuy
      ? "Protection reserved before buy; waiting for the confirmed trade receipt."
      : (tokenAmount ? null : "Waiting for token account indexing before TP/SL checks.")
  };
  let plan = {
    id: durablePlanKey ? `durable-${durablePlanKey.slice(0, 48)}` : crypto.randomUUID(),
    status: pendingBuy ? "pending_buy" : "watching",
    userId,
    chatId: null,
    tokenMint,
    source: planSource,
    ...(durablePlanKey ? { durablePlanKey } : {}),
    executionMode: "managed_server",
    automationPermission: permission,
    walletSelector: String(walletIndex),
    amountSol: lamportsBigToSol(amountLamports),
    sellDelayMinutes: sellDelaySeconds / 60,
    sellDelaySeconds,
    sellAfterAt,
    sellPercent,
    triggerSellPercent,
    loopCount: 1,
    loopDelaySeconds: 0,
    takeProfitPct,
    stopLossPct,
    takeProfitMode: ladder.length ? "ladder" : "single",
    stopLossMode: "single",
    takeProfitLadder: ladder,
    trailingStopPct,
    trailingActivatePct,
    breakEvenAfterTp1,
    breakEvenStopPct,
    autoBundle: false,
    slippageBps,
    createdAt: new Date().toISOString(),
    wallets: [planWallet],
    protectionIntent: pendingBuy ? "pending_buy" : "armed",
    protectionAttemptId: firstString(body.tradeAttemptId, body.clientRequestId),
    results: [pendingBuy
      ? `${wallet.label}: protection reserved before buy`
      : `${wallet.label}: auto-exit armed after quick buy`]
  };

  let planCreated = true;
  let planFinalized = false;
  await mutateTradePlans((plans) => {
    const existing = durablePlanKey
      ? plans.plans.find((row) => String(row.durablePlanKey || "") === durablePlanKey)
      : null;
    if (existing) {
      const existingStatus = String(existing.status || "").toLowerCase();
      if (!pendingBuy && ["pending_buy", "arming", "needs_attention"].includes(existingStatus)) {
        const createdAt = existing.createdAt || plan.createdAt;
        const id = existing.id || plan.id;
        Object.assign(existing, plan, {
          id,
          createdAt,
          protectionIntent: "armed",
          protectionFinalizedAt: new Date().toISOString()
        });
        plan = existing;
        planCreated = false;
        planFinalized = true;
      } else {
        plan = existing;
        planCreated = false;
      }
      return;
    }
    plans.plans.push(plan);
  });
  if (planCreated && !pendingBuy || planFinalized) {
    await audit("web_trade_auto_exit_plan", {
      userId,
      planId: plan.id,
      tokenMint,
      wallet: publicWallet(wallet),
      sellDelaySeconds,
      sellPercent,
      triggerSellPercent,
      takeProfitPct,
      stopLossPct,
      slippageBps,
      buySignature: buyResult.signature,
      durablePlanKey,
      source: planSource
    }).catch(() => {});
  }

  if (!pendingBuy) {
    scheduleTradePlanProcessing("single trade auto-exit", [500, 1200, 2500, 5000, 8000, 12000, 20000, 30000]);
    if (planCreated || planFinalized) await safeArmWebExitGuardsForPlan(plan, [planWallet]);
  }

  const timerSummary = sellDelaySeconds > 0 ? formatDelay(sellDelaySeconds) : "timer off";
  return {
    id: plan.id,
    tokenMint,
    shortMint: shortMint(tokenMint),
    walletLabel: wallet.label,
    walletCount: 1,
    successCount: 1,
    failedCount: 0,
    amountSol: lamportsBigToSol(amountLamports),
    sellAfterAt,
    sellDelaySeconds,
    sellPercent,
    triggerSellPercent,
    takeProfitPct,
    stopLossPct,
    takeProfitSummary: formatPlanTakeProfitSummary(plan),
    stopLossSummary: formatPlanStopLossSummary(plan),
    loopCount: 1,
    loopDelaySeconds: 0,
    slippageBps,
    executionMode: "managed_server",
    source: plan.source || planSource,
    pendingBuy,
    duplicate: !planCreated,
    results: [{ ok: true, message: `${wallet.label}: auto-exit armed` }],
    dexUrl: dexScreenerUrl(tokenMint),
    shortMessage: `Auto-exit armed: TP ${formatPlanTakeProfitSummary(plan)}, SL ${formatPlanStopLossSummary(plan)}, ${timerSummary}.`,
    message: `Single trade auto-exit armed for ${wallet.label}: TP ${formatPlanTakeProfitSummary(plan)}, SL ${formatPlanStopLossSummary(plan)}, ${timerSummary}.`
  };
}

async function webCreateTradePlan(userId, body = {}) {
  const store = await readWalletStore();
  const wallets = Array.isArray(body.walletIndexes) || String(body.walletGroup || "").trim()
    ? webSelectedWallets(store, userId, body.walletIndexes, body.walletGroup, { walletPublicKeys: body.walletPublicKeys })
    : [getWebServerTradeWalletAt(store, parseWebWalletIndex(body.walletIndex || "1"), userId, "managed trade")];
  return webCreateManagedBuyPlan(userId, wallets, body, {
    source: "web_trade_plan",
    label: "Managed trade",
    auditType: "web_create_trade_plan",
    defaultSellDelay: "5",
    defaultTakeProfitPct: "25",
    defaultStopLossPct: "8",
    defaultSlippageBps: 400,
    defaultSmartExits: true // laddered take-profit + break-even after TP1 by default (pass smartExits:false to opt out)
  });
}

// Normalize a take-profit ladder (array of {pct, sellPercent}) from a web request.
// Keeps only positive, ascending-pct rungs; caps total sell at 100%.
function parseWebTakeProfitLadder(raw) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  let sold = 0;
  for (const level of raw) {
    const pct = Number(level && (level.pct ?? level.takeProfitPct));
    let sell = Number(level && (level.sellPercent ?? level.sell));
    if (!Number.isFinite(pct) || pct <= 0) continue;
    if (!Number.isFinite(sell) || sell <= 0) sell = 25;
    sell = Math.min(sell, Math.max(0, 100 - sold));
    if (sell <= 0) break;
    sold += sell;
    out.push({ pct: Math.round(pct), sellPercent: Math.round(sell) });
  }
  return out.sort((a, b) => a.pct - b.pct);
}
// The default "Smart exits" ladder: bank early, keep a moon-bag riding.
const SMART_EXIT_LADDER = [{ pct: 50, sellPercent: 40 }, { pct: 120, sellPercent: 35 }, { pct: 300, sellPercent: 50 }];

async function resolveWebProceedsRouting(userId, raw = {}) {
  const normalized = pumpLaunchProceedsRouting(raw);
  if (!normalized.enabled) return { enabled: false, mode: "next-wallet", percent: normalized.percent, walletPublicKeys: [] };
  const walletStore = await readWalletStore();
  const owned = walletsForOwner(walletStore, userId);
  const walletPublicKeys = normalized.walletIndexes
    .map((index) => owned[index - 1]?.publicKey || "")
    .filter(Boolean);
  if (walletPublicKeys.length < 2 || new Set(walletPublicKeys).size !== walletPublicKeys.length) {
    throw new Error("Sale-proceeds routing needs at least two different managed wallets. Refresh Wallet and choose the route again.");
  }
  return { enabled: true, mode: "next-wallet", percent: normalized.percent, walletPublicKeys };
}

async function webCreateManagedBuyPlan(userId, wallets, body = {}, options = {}) {
  return runIdempotentMoneyOp("web-managed-buy-plan", userId, firstString(body.tradeAttemptId, body.clientRequestId),
    async () => {
      const protectedBody = await resolveWebTradeProtectionBody(userId, body);
      const tokenMint = parsePublicKey(String(protectedBody.tokenMint || "")).toBase58();
      return withManagedSolBuyPositionLocks(userId, wallets, tokenMint, () => webCreateManagedBuyPlanCore(userId, wallets, protectedBody, options));
    },
    { busyMessage: "This managed buy plan is already submitting — SlimeWire won't send it twice.", lockMs: 30 * 60_000, ttlMs: 24 * 60 * 60_000 });
}

function webWalletTradeConfigMap(body = {}, wallets = [], defaults = {}) {
  const allowed = new Set(wallets.map((wallet, index) => Number(wallet.webIndex || index + 1)));
  const configs = new Map();
  for (const row of (Array.isArray(body.walletConfigs) ? body.walletConfigs : []).slice(0, 20)) {
    const walletIndex = Number.parseInt(row?.walletIndex, 10);
    if (!allowed.has(walletIndex)) continue;
    const config = {};
    const amountText = firstString(row?.amountSol, defaults.amountSol);
    if (amountText) config.amountSol = parsePositiveNumber(String(amountText));
    const percentText = firstString(row?.sellPercent, row?.percent, defaults.percent);
    if (percentText) config.percent = parsePercent(String(percentText));
    configs.set(walletIndex, config);
  }
  return configs;
}

async function webCreateManagedBuyPlanCore(userId, wallets, body = {}, options = {}) {
  const tokenMint = parsePublicKey(String(body.tokenMint || "")).toBase58();
  const amountSol = parsePositiveNumber(String(body.amountSol || ""));
  const amountLamports = solToLamports(amountSol);
  const sellDelaySeconds = parseOptionalSellDelaySeconds(firstString(body.sellDelay, body.sellDelaySeconds, options.defaultSellDelay, "5"));
  const sellPercent = parsePercent(String(body.sellPercent || "100"));
  const takeProfitPct = parseTakeProfitPercent(firstString(body.takeProfitPct, options.defaultTakeProfitPct, "25"));
  const stopLossPct = parseOptionalTriggerPercent(firstString(body.stopLossPct, options.defaultStopLossPct, "8"));
  const loopCount = parseLoopCount(String(body.loopCount || "1"));
  const loopDelaySeconds = parseLoopDelaySeconds(String(body.loopDelay || body.loopDelaySeconds || "0"));
  const slippageBps = parseWebSlippage(body.slippageBps || options.defaultSlippageBps);
  const triggerSellPercent = sellPercent;
  const proceedsRouting = await resolveWebProceedsRouting(userId, body.proceedsRouting || {});
  // Smart exits: laddered take-profit (bank some, ride some) + break-even after TP1.
  // Opt-in per request (body.smartExits) or per caller default (options.defaultSmartExits).
  const smartExits = body.smartExits === true || body.smartExits === "true" || (options.defaultSmartExits && body.smartExits !== false && body.smartExits !== "false");
  let takeProfitLadder = parseWebTakeProfitLadder(body.takeProfitLadder);
  if (smartExits && takeProfitLadder.length === 0) takeProfitLadder = SMART_EXIT_LADDER.slice();
  const breakEvenAfterTp1 = body.breakEvenAfterTp1 === true || body.breakEvenAfterTp1 === "true" || (smartExits && body.breakEvenAfterTp1 !== false && body.breakEvenAfterTp1 !== "false");
  const trailingStopPct = Math.max(0, Math.min(95, Number(body.trailingStopPct) || (smartExits ? 25 : 0)));
  const trailingActivatePct = trailingStopPct > 0
    ? Math.max(trailingStopPct, Number(body.trailingActivatePct) || (smartExits ? 40 : trailingStopPct))
    : 0;
  const source = options.source || "web_volume";
  const label = options.label || "Plan";
  const results = [];
  const tradeEvents = [];
  const planWallets = [];
  const walletIndexes = wallets.map((wallet, index) => Number(wallet.webIndex || index + 1));
  const walletTradeConfigs = webWalletTradeConfigMap(body, wallets, { amountSol: String(amountSol), percent: String(sellPercent) });
  const walletTakeProfitTargets = parseWebWalletTakeProfitTargets(body, walletIndexes);
  const walletStopLossTargets = parseWebWalletStopLossTargets(body, walletIndexes);
  const manualExitWalletIndexes = parseWebManualExitWalletIndexes(body, walletIndexes);
  const manualExitWalletSet = new Set(manualExitWalletIndexes.map(String));
  if (manualExitWalletIndexes.length === walletIndexes.length) {
    throw new Error("At least one selected wallet must keep automatic exits. Use Bundle Buy when every wallet should be manual-only.");
  }
  ensureTimedPlanHasExit({
    sellDelaySeconds,
    takeProfitPct,
    stopLossPct,
    walletTakeProfitTargets,
    walletStopLossTargets,
    takeProfitLadder
  });
  const automationPermission = await requireWebAutomationPermission(userId, `${label} server exits`);
  await assertManagedSolBuyReentryAllowed(userId, wallets, tokenMint);

  const now = Date.now();
  const sellAfterAt = planSellAfterAtFromNow({ sellDelaySeconds }, now);
  const protectionAttemptId = firstString(body.tradeAttemptId, body.clientRequestId, crypto.randomUUID());
  const durablePlanKey = `managed-${crypto.createHash("sha256")
    .update([String(userId || ""), tokenMint, protectionAttemptId].join("\0"))
    .digest("hex")}`;
  const planId = `durable-${durablePlanKey.slice(0, 48)}`;
  const walletRuntimes = wallets.map((wallet, index) => {
    const walletIndex = Number(wallet.webIndex || index + 1);
    const walletAmountSol = walletTradeConfigs.get(walletIndex)?.amountSol || amountSol;
    return {
      wallet,
      walletIndex,
      walletAmountSol,
      walletAmountLamports: solToLamports(walletAmountSol),
      walletSellPercent: walletTradeConfigs.get(walletIndex)?.percent || triggerSellPercent,
      buyReservationClaimToken: crypto.randomUUID(),
      manualExit: manualExitWalletSet.has(String(walletIndex))
    };
  });
  // Checkpoint each protected wallet's existing same-mint balance before the
  // durable reservation and before any buy can broadcast. If this read is not
  // authoritative, fail closed instead of risking an exit that absorbs an old
  // bag into the new position.
  await runWithConcurrency(
    walletRuntimes.filter((runtime) => !runtime.manualExit),
    CONFIG.bundleConcurrency,
    async (runtime) => {
      runtime.preBuyTokenRawAmount = await readProtectedBuyTokenBaselineRaw(runtime.wallet, tokenMint);
    }
  );
  const reservationWallets = walletRuntimes.map((runtime) => ({
    label: runtime.wallet.label,
    publicKey: runtime.wallet.publicKey,
    walletIndex: runtime.walletIndex,
    basisLamports: String(runtime.walletAmountLamports),
    grossLamports: String(runtime.walletAmountLamports),
    feeLamports: "0",
    tokenOutAmount: null,
    ...(runtime.preBuyTokenRawAmount !== undefined
      ? { preBuyTokenRawAmount: runtime.preBuyTokenRawAmount }
      : {}),
    buySignature: null,
    buyReservationClaimToken: runtime.buyReservationClaimToken,
    currentLoop: 1,
    completedLoops: 0,
    autoExitDisabled: runtime.manualExit,
    manualExit: runtime.manualExit,
    takeProfitPct: runtime.manualExit ? null : (walletTakeProfitTargets ? walletTakeProfitTargets[String(runtime.walletIndex)] || null : null),
    stopLossPct: runtime.manualExit ? null : (walletStopLossTargets ? walletStopLossTargets[String(runtime.walletIndex)] || null : null),
    completedTakeProfitLevels: [],
    triggerSellPercent: runtime.walletSellPercent,
    triggerStatus: "pending_buy",
    exitStatus: "pending_buy",
    armedAt: null,
    sellAfterAt: runtime.manualExit ? null : sellAfterAt,
    status: "pending_buy",
    lastCheckedAt: null,
    lastMovePct: null,
    lastError: "Protection reserved before buy; waiting for a signed transaction checkpoint."
  }));
  const reservationPlan = {
    id: planId,
    durablePlanKey,
    protectionIntent: "pending_buy",
    protectionAttemptId,
    status: "pending_buy",
    userId,
    chatId: null,
    tokenMint,
    source,
    executionMode: "managed_server",
    automationPermission,
    walletSelector: String(body.walletGroup || "").trim()
      ? `group:${String(body.walletGroup).trim()}`
      : Array.isArray(body.walletIndexes)
        ? body.walletIndexes.join(",")
        : String(body.walletIndex || reservationWallets.length),
    amountSol,
    variedAmounts: walletTradeConfigs.size > 0,
    sellDelayMinutes: sellDelaySeconds / 60,
    sellDelaySeconds,
    sellAfterAt,
    sellPercent,
    triggerSellPercent,
    loopCount,
    loopDelaySeconds,
    takeProfitPct,
    stopLossPct,
    takeProfitMode: takeProfitLadder.length ? "ladder" : (walletTakeProfitTargets ? "wallets" : "single"),
    stopLossMode: walletStopLossTargets ? "wallets" : "single",
    manualExitWalletIndexes,
    takeProfitLadder,
    breakEvenAfterTp1: Boolean(breakEvenAfterTp1),
    breakEvenStopPct: 2,
    trailingStopPct,
    trailingActivatePct,
    proceedsRouting,
    autoBundle: false,
    slippageBps,
    createdAt: new Date(now).toISOString(),
    wallets: reservationWallets,
    results: reservationWallets.map((wallet) => `${wallet.label}: protection reserved before buy`)
  };
  await mutateTradePlans((plans) => {
    if (objectRows(plans.plans).some((plan) => String(plan.durablePlanKey || "") === durablePlanKey)) {
      const error = new Error("This protected managed buy is already reserved. Check Activity before retrying.");
      error.statusCode = 409;
      throw error;
    }
    plans.plans.push(reservationPlan);
  });

  const reservationByWallet = new Map(reservationWallets.map((wallet) => [wallet.publicKey, wallet]));
  const updateReservedWallet = async (walletPublicKey, patch = {}) => {
    Object.assign(reservationByWallet.get(walletPublicKey) || {}, patch);
    return mutateTradePlans((plans) => {
      const plan = objectRows(plans.plans).find((row) => String(row.durablePlanKey || "") === durablePlanKey);
      const planWallet = objectRows(plan?.wallets).find((row) => String(row.publicKey || "") === String(walletPublicKey || ""));
      if (!plan || !planWallet) return false;
      Object.assign(planWallet, patch, { updatedAt: new Date().toISOString() });
      plan.updatedAt = new Date().toISOString();
      return true;
    });
  };

  await runWithConcurrency(walletRuntimes, CONFIG.bundleConcurrency, async (runtime) => {
    const { wallet, walletIndex, walletAmountSol, walletAmountLamports, walletSellPercent, manualExit } = runtime;
    try {
      const result = await buyTokenForPlan(wallet, tokenMint, walletAmountLamports, slippageBps, {
        trackTokenDelta: true,
        tokenBeforeRawAmount: runtime.preBuyTokenRawAmount,
        userId,
        trustedLaunchMint: Boolean(options.trustedLaunchMint),
        onSigned: async (submission) => {
          const saved = await updateReservedWallet(wallet.publicKey, {
            status: "arming",
            exitStatus: "arming",
            triggerStatus: "arming",
            buySubmissionSignature: submission.signature,
            buySubmissionRequestId: submission.requestId || null,
            buySubmissionLastValidBlockHeight: submission.lastValidBlockHeight || null,
            buySubmissionRecentBlockhash: submission.recentBlockhash || submission.blockhash || null,
            buySubmissionProvider: submission.provider || null,
            buySubmissionSignedAt: new Date().toISOString(),
            lastError: "Buy transaction signed; waiting for on-chain confirmation before protection activates."
          });
          if (!saved) {
            const persistError = new Error("Protection reservation disappeared before this managed buy could be submitted.");
            persistError.tradePreSubmit = true;
            throw persistError;
          }
        }
      });
      const tokenAmount = result.tokenDeltaAmount || result.outputAmount || null;
      const finalizedWallet = {
        label: wallet.label,
        publicKey: wallet.publicKey,
        walletIndex,
        basisLamports: positiveRawString(result.swapLamports) || String(walletAmountLamports),
        grossLamports: String(walletAmountLamports),
        feeLamports: positiveRawString(result.feeLamports) || "0",
        tokenOutAmount: tokenAmount,
        ...(tokenAmount ? { protectedTokenRemainingRaw: tokenAmount } : {}),
        protectedLotRevision: tokenAmount ? 1 : 0,
        ...(result.preBuyTokenRawAmount !== null && result.preBuyTokenRawAmount !== undefined
          ? { preBuyTokenRawAmount: String(result.preBuyTokenRawAmount) }
          : runtime.preBuyTokenRawAmount !== undefined
            ? { preBuyTokenRawAmount: runtime.preBuyTokenRawAmount }
            : {}),
        buySignature: result.signature,
        resolvedBuySubmissionSignature: result.signature,
        resolvedBuyReservationClaimToken: runtime.buyReservationClaimToken,
        buySubmissionResolution: "confirmed",
        buySubmissionConfirmedAt: new Date().toISOString(),
        buySubmissionSignature: null,
        buySubmissionRequestId: null,
        buySubmissionLastValidBlockHeight: null,
        buySubmissionRecentBlockhash: null,
        buyReservationClaimToken: null,
        currentLoop: 1,
        completedLoops: 0,
        autoExitDisabled: manualExit,
        manualExit,
        takeProfitPct: manualExit ? null : (walletTakeProfitTargets ? walletTakeProfitTargets[String(walletIndex)] || null : null),
        stopLossPct: manualExit ? null : (walletStopLossTargets ? walletStopLossTargets[String(walletIndex)] || null : null),
        completedTakeProfitLevels: [],
        triggerSellPercent: walletSellPercent,
        triggerStatus: manualExit ? "manual" : (takeProfitPct || stopLossPct || trailingStopPct || walletTakeProfitTargets || walletStopLossTargets ? "armed" : "timer-only"),
        exitStatus: manualExit ? "manual" : "watching",
        armedAt: manualExit ? null : new Date(now).toISOString(),
        sellAfterAt: manualExit ? null : sellAfterAt,
        status: manualExit ? "manual_hold" : "watching",
        submissionResolvedAt: new Date().toISOString(),
        lastCheckedAt: null,
        lastMovePct: null,
        lastError: manualExit || tokenAmount ? null : "Waiting for token account indexing before TP/SL checks."
      };
      let finalizeError = "";
      try {
        const saved = await updateReservedWallet(wallet.publicKey, finalizedWallet);
        if (!saved) throw new Error("The durable managed protection reservation was not found.");
      } catch (error) {
        finalizeError = friendlyError(error);
      }
      tradeEvents.push({
        userId,
        type: "buy",
        source,
        tokenMint,
        walletLabel: wallet.label,
        walletPublicKey: wallet.publicKey,
        solLamportsSpent: String(walletAmountLamports),
        tokenAmount,
        signature: result.signature,
        protectionAttemptId,
        protectionPlanKey: durablePlanKey
      });
      planWallets.push(finalizedWallet);
      results.push({
        ok: true,
        walletLabel: wallet.label,
        walletPublicKey: wallet.publicKey,
        signature: result.signature,
        needsAttention: Boolean(finalizeError),
        message: `${formatBuySuccessLine(wallet, result.amountLamports, result.feeLamports, result.swapLamports, result, result.feeStatus)}${finalizeError ? ` Protection finalization will be recovered from the signed checkpoint: ${finalizeError}` : ""}`
      });
    } catch (error) {
      const partialSignatures = Array.isArray(error?.partialHashes)
        ? error.partialHashes.filter((value) => typeof value === "string")
        : [];
      const submissionSignature = firstString(
        error?.signature,
        error?.transactionSignature,
        ...partialSignatures
      );
      const ambiguous = Boolean(error?.tradeSubmissionAmbiguous || submissionSignature);
      await updateReservedWallet(wallet.publicKey, {
        status: ambiguous ? "outcome_unknown" : "failed",
        exitStatus: ambiguous ? "outcome_unknown" : "failed",
        triggerStatus: ambiguous ? "outcome_unknown" : "failed",
        buySubmissionSignature: submissionSignature || undefined,
        buySubmissionProvider: error?.provider || undefined,
        lastError: ambiguous
          ? `Buy submission outcome is unknown; no automatic replay will be sent. ${friendlyError(error)}`
          : `Buy did not submit; the reserved protection entry is closed. ${friendlyError(error)}`
      }).catch(() => {});
      results.push({
        ok: false,
        outcomeUnknown: ambiguous,
        walletLabel: wallet.label,
        walletPublicKey: wallet.publicKey,
        message: `${wallet.label}: buy failed - ${friendlyError(error)}`
      });
    }
  });

  let recordError = "";
  await recordTradeEvents(tradeEvents).catch((error) => {
    recordError = friendlyError(error);
  });

  const allPlanWallets = reservationWallets.map((wallet) => ({ ...wallet }));
  const unresolvedWallets = allPlanWallets.filter((wallet) => ["pending_buy", "arming", "needs_attention", "outcome_unknown"].includes(
    String(wallet.status || wallet.exitStatus || "").toLowerCase()
  ));
  const guardedWallets = allPlanWallets.filter((wallet) => (
    !(wallet.autoExitDisabled || wallet.manualExit)
    && ["watching", "armed", "retrying", "triggered", "timer-only"].includes(
      String(wallet.status || wallet.exitStatus || wallet.triggerStatus || "").toLowerCase()
    )
  ));
  const planStatus = guardedWallets.length
    ? "watching"
    : unresolvedWallets.length
      ? "pending_buy"
      : "failed";
  const plan = {
    ...reservationPlan,
    id: planId,
    durablePlanKey,
    protectionIntent: unresolvedWallets.length ? "pending_buy" : guardedWallets.length ? "armed" : "failed",
    status: planStatus,
    userId,
    chatId: null,
    tokenMint,
    source,
    executionMode: "managed_server",
    automationPermission,
    walletSelector: String(body.walletGroup || "").trim()
      ? `group:${String(body.walletGroup).trim()}`
      : Array.isArray(body.walletIndexes)
      ? body.walletIndexes.join(",")
      : String(body.walletIndex || planWallets.length),
    amountSol,
    variedAmounts: walletTradeConfigs.size > 0,
    sellDelayMinutes: sellDelaySeconds / 60,
    sellDelaySeconds,
    sellAfterAt,
    sellPercent,
    triggerSellPercent,
    loopCount,
    loopDelaySeconds,
    takeProfitPct,
    stopLossPct,
    takeProfitMode: takeProfitLadder.length ? "ladder" : (walletTakeProfitTargets ? "wallets" : "single"),
    stopLossMode: walletStopLossTargets ? "wallets" : "single",
    manualExitWalletIndexes,
    takeProfitLadder,
    breakEvenAfterTp1: Boolean(breakEvenAfterTp1),
    breakEvenStopPct: 2,
    trailingStopPct,
    trailingActivatePct,
    proceedsRouting,
    autoBundle: false,
    slippageBps,
    createdAt: reservationPlan.createdAt,
    updatedAt: new Date().toISOString(),
    wallets: allPlanWallets,
    results: results.map((row) => row.message)
  };

  let planPersistError = "";
  try {
    const finalized = await mutateTradePlans((plans) => {
      const existing = objectRows(plans.plans).find((row) => String(row.durablePlanKey || "") === durablePlanKey);
      if (!existing) return false;
      Object.assign(existing, plan);
      return true;
    });
    if (!finalized) throw new Error("The durable protected-buy reservation disappeared before finalization.");
  } catch (error) {
    // Per-wallet signatures were checkpointed before broadcast. Leave the
    // reservation in place for confirmed-only recovery and never invite a
    // second spend merely because aggregate finalization failed.
    planPersistError = friendlyError(error);
  }
  await audit(options.auditType || "web_create_managed_plan", {
    userId,
    planId: plan.id,
    tokenMint,
    wallets: planWallets.map((wallet) => wallet.publicKey),
    walletCount: wallets.length,
    successCount: planWallets.length,
    amountSol,
    sellDelaySeconds,
    sellPercent,
    takeProfitPct,
    stopLossPct,
    walletTakeProfitTargets,
    walletStopLossTargets,
    manualExitWalletIndexes,
    loopCount,
    loopDelaySeconds,
    source,
    slippageBps
  }).catch(() => {});

  if (!planPersistError && guardedWallets.length) {
    scheduleTradePlanProcessing(`${label} auto-exit`, [500, 1200, 2500, 5000, 8000, 12000, 20000, 30000]);
    await safeArmWebExitGuardsForPlan(plan, guardedWallets);
  }

  if (planWallets.length === 0) {
    const unknown = results.some((row) => row.outcomeUnknown);
    const error = new Error(`${label} was not created because no buy was confirmed.${unknown ? " One or more signed submissions still have an unknown outcome; SlimeWire will reconcile them and will not replay the buy." : ""}\n\n${results.map((row) => row.message).join("\n")}`);
    if (unknown) error.tradeSubmissionAmbiguous = true;
    throw error;
  }

  return {
    id: plan.id,
    tokenMint,
    shortMint: shortMint(tokenMint),
    walletLabel: planWallets.length === 1 ? planWallets[0].label : `${planWallets.length}/${wallets.length} wallets`,
    walletCount: wallets.length,
    successCount: planWallets.length,
    failedCount: Math.max(0, wallets.length - planWallets.length),
    amountSol: lamportsToSol(amountLamports),
    sellAfterAt: plan.sellAfterAt,
    sellDelaySeconds,
    sellPercent,
    takeProfitPct,
    stopLossPct,
    manualExitWalletIndexes,
    manualWalletCount: manualExitWalletIndexes.length,
    takeProfitSummary: formatPlanTakeProfitSummary(plan),
    stopLossSummary: formatPlanStopLossSummary(plan),
    loopCount,
    loopDelaySeconds,
    slippageBps,
    source,
    executionMode: "managed_server",
    recordError,
    planPersistError,
    results,
    dexUrl: dexScreenerUrl(tokenMint),
    message: planPersistError
      ? `${label}: ${planWallets.length}/${wallets.length} wallet buy(s) landed. Their signed protection checkpoints are saved and recovery is running; do not retry the buy. ${planPersistError}`
      : `${label} armed: ${planWallets.length}/${wallets.length} wallet(s) bought ${shortMint(tokenMint)}. Watching TP ${formatPlanTakeProfitSummary(plan)}, SL ${formatPlanStopLossSummary(plan)}${sellDelaySeconds > 0 ? `, timer ${formatSellTimerSummary(sellDelaySeconds)}` : ""}${manualExitWalletIndexes.length ? `. ${manualExitWalletIndexes.length} wallet(s) are hold / manual-only with every automatic exit disabled` : ""}.`
  };
}

